const TRIAL_MEDALS_KEY = "final-blow-trial-medals";

function readStoredJson(key) {
  try {
    return JSON.parse(localStorage.getItem(key));
  } catch {
    return null;
  }
}

let trialMedals = normalizeTrialMedals(readStoredJson(TRIAL_MEDALS_KEY));

function saveTrialMedals() {
  localStorage.setItem(TRIAL_MEDALS_KEY, JSON.stringify(trialMedals));
}

const MEDAL_GLYPHS = Object.freeze({ bronze: "●", silver: "●", gold: "★" });

function medalMarkup(counts) {
  const parts = [];
  if (counts.gold) parts.push(`<i class="medal-gold">★${counts.gold}</i>`);
  if (counts.silver) parts.push(`<i class="medal-silver">●${counts.silver}</i>`);
  if (counts.bronze) parts.push(`<i class="medal-bronze">●${counts.bronze}</i>`);
  return parts.join(" ");
}

function refreshTrialMedalBadges() {
  $$("#rosterGrid .fighter-card").forEach((card) => {
    const fighter = roster[Number(card.dataset.index)];
    if (!fighter) return;
    let badge = card.querySelector(".trial-medal-badge");
    if (!badge) {
      badge = document.createElement("span");
      badge.className = "trial-medal-badge";
      card.append(badge);
    }
    const counts = fighterMedalCounts(trialMedals, fighter.id);
    badge.hidden = counts.total === 0;
    badge.innerHTML = medalMarkup(counts);
  });
}

// --- Authored trial demos (WATCH DEMO) -------------------------------------
// Feeds the PLAYER seat through the same direct action fields the QA input
// machinery uses. `forward` frames are mapped onto left/right against the live
// facing so cross-through specials cannot strand the walk-in.
const trialDemo = { active: false, frames: [], index: 0, trialName: "" };

function stopTrialDemo(message = "") {
  if (!trialDemo.active) return;
  trialDemo.active = false;
  trialDemo.frames = [];
  trialDemo.index = 0;
  if (message) state.training.lastResult = message;
  const button = $("#trainingTrialDemoButton");
  if (button) button.textContent = "WATCH DEMO";
}

function startTrialDemo() {
  if (state.mode !== "training" || !state.fighters.length) return false;
  const fighterId = state.fighters[0].kitId;
  const trial = comboTrialsForFighter(fighterId)[state.training.trialIndex];
  if (!trial) return false;
  resetTrainingPosition(false);
  state.training.dummyMode = "stand";
  selectTrainingTrial(state.training, fighterId, state.training.trialIndex);
  state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  trialDemo.frames = trialDemoScript(trial);
  trialDemo.index = 0;
  trialDemo.active = true;
  trialDemo.trialName = trial.name;
  trainingFxDebug.trialDemoRuns += 1;
  state.training.lastResult = `WATCH · ${trial.name}`;
  $("#trainingTrialDemoButton").textContent = "STOP DEMO";
  updateTrainingUi();
  return true;
}

function trialDemoInput() {
  if (!trialDemo.active) return null;
  if (state.mode !== "training" || state.screen !== "fight") {
    stopTrialDemo();
    return null;
  }
  const frame = trialDemo.frames[trialDemo.index];
  trialDemo.index += 1;
  if (trialDemo.index >= trialDemo.frames.length) stopTrialDemo(`${trialDemo.trialName} · YOUR TURN`);
  if (!frame) return null;
  if (frame.forward) {
    const [player, dummy] = state.fighters;
    const toward = player && dummy && dummy.x < player.x ? "left" : "right";
    return { [toward]: true };
  }
  return { ...frame };
}

// --- Situation slots -------------------------------------------------------
const TRAINING_SLOT_KEY_PREFIX = "final-blow-training-slot-";

const situationSlots = Array.from({ length: TRAINING_SLOT_COUNT }, (_, index) => (
  decodeTrainingSlot(localStorage.getItem(`${TRAINING_SLOT_KEY_PREFIX}${index}`))
));

function refreshSituationSlotButtons() {
  $$("[data-slot-load]").forEach((button) => {
    const index = Number(button.dataset.slotLoad);
    const filled = Boolean(situationSlots[index]);
    button.disabled = !filled;
    button.classList.toggle("filled", filled);
  });
}

function saveSituationSlot(index) {
  if (state.mode !== "training" || state.screen !== "fight") return false;
  if (!Number.isInteger(index) || index < 0 || index >= TRAINING_SLOT_COUNT) return false;
  const encoded = encodeTrainingSlot({
    state: serializeRollbackState(saveRollbackState()),
    stage: state.stage,
    dummyMode: state.training.dummyMode,
    recording: state.training.recording,
    savedAt: Date.now(),
  });
  if (!encoded) return false;
  localStorage.setItem(`${TRAINING_SLOT_KEY_PREFIX}${index}`, encoded);
  situationSlots[index] = decodeTrainingSlot(encoded);
  trainingFxDebug.slotSaves += 1;
  state.training.lastResult = `SITUATION SAVED · SLOT ${index + 1}`;
  refreshSituationSlotButtons();
  updateTrainingUi();
  return true;
}

function loadSituationSlot(index) {
  if (state.mode !== "training" || state.screen !== "fight") return false;
  const slot = situationSlots[index];
  if (!slot) return false;
  stopTrialDemo();
  let parsed = null;
  try {
    parsed = parseRollbackState(slot.state);
  } catch {
    return false;
  }
  const previousStage = state.stage;
  try {
    restoreRollbackState(parsed);
  } catch {
    return false;
  }
  // Offline the fixed-step clock owns the tick counter, so it must resume
  // from the snapshot's tick or every restored frame-relative counter
  // (buffers, combo gaps, taunt windows) would sit in the wrong tick domain.
  simulationClock.tick = state.simulationTick;
  state.training.dummyMode = slot.dummyMode;
  state.training.recording = slot.recording.map((frame) => ({ ...frame }));
  state.training.recordingActive = false;
  state.training.playbackFrame = 0;
  state.training.guardAfterTriggered = false;
  state.training.reversalArmed = false;
  state.training.lastResult = `SITUATION LOADED · SLOT ${index + 1}`;
  trainingFxDebug.slotLoads += 1;
  if (state.stage !== previousStage) {
    updateStageUI();
    resetCrowd();
  }
  updateHud();
  updateComboState();
  updateTrainingUi();
  return true;
}

// --- FIGHT SCHOOL ----------------------------------------------------------
const SCHOOL_STORAGE_KEY = "final-blow-fight-school";

const schoolSession = {
  active: false,
  machine: null,
  savedDifficulty: "",
  pendingSetup: null,
  dizzyCooldownTick: -Infinity,
  coachLast: {},
};

function loadSchoolProgress() {
  const raw = readStoredJson(SCHOOL_STORAGE_KEY);
  const completed = {};
  if (raw?.completed && typeof raw.completed === "object") {
    for (const lesson of FIGHT_SCHOOL_LESSONS) {
      if (raw.completed[lesson.id]) completed[lesson.id] = true;
    }
  }
  return { completed, graduated: Boolean(raw?.graduated) };
}

function saveSchoolProgress() {
  if (!schoolSession.machine) return;
  localStorage.setItem(SCHOOL_STORAGE_KEY, JSON.stringify({
    version: 1,
    completed: schoolSession.machine.completed,
    graduated: schoolSession.machine.graduated,
  }));
}

// Philly corner-man lines, drawn with a per-pool no-repeat latch so a line
// can never land back-to-back. visualRandom only — never state.rng here.
function schoolCoach(pool) {
  const lines = FIGHT_SCHOOL_COACH_LINES[pool] || [];
  if (!lines.length) return "";
  if (lines.length === 1) return lines[0];
  let pick = Math.floor(visualRandom() * lines.length) % lines.length;
  if (pick === schoolSession.coachLast[pool]) pick = (pick + 1) % lines.length;
  schoolSession.coachLast[pool] = pick;
  return lines[pick];
}

let schoolPanelStamp = "";

function renderSchoolPanel() {
  const panel = $("#schoolPanel");
  const visible = schoolSession.active && state.mode === "training" && state.screen === "fight";
  panel.hidden = !visible;
  if (!visible) {
    schoolPanelStamp = "";
    return;
  }
  const snapshot = fightSchoolSnapshot(schoolSession.machine, { style: state.controlStyle });
  const stamp = `${snapshot.lesson}:${snapshot.step}:${snapshot.graduated}:${state.controlStyle}`;
  if (stamp === schoolPanelStamp) return;
  schoolPanelStamp = stamp;
  $("#schoolLessonCounter").textContent = snapshot.graduated
    ? "GRADUATED"
    : `LESSON ${Math.min(snapshot.lesson + 1, snapshot.lessonCount)} / ${snapshot.lessonCount}`;
  $("#schoolLessonName").textContent = snapshot.lessonName;
  const lesson = fightSchoolLesson(schoolSession.machine);
  $("#schoolLessonIntro").textContent = lesson?.intro || "Every page of the book, landed. Class dismissed.";
  $("#schoolSteps").innerHTML = snapshot.steps.map((step, index) => (
    `<span class="${step.complete ? "done" : index === snapshot.step ? "next" : ""}">${step.label}</span>`
  )).join("");
}

// Builds the scripted dummy attack loop for the guard lessons: walk toward the
// player, swing the scripted attack, breathe, repeat — through the exact
// sanitized-recording playback path the lab already ships.
function schoolDummyScript(script) {
  const frames = [];
  for (let index = 0; index < 42; index += 1) frames.push({ left: true });
  // 5.1: "launcher" feeds the kit's rising launcher through the same direct
  // action field the reversal dummy uses, so the OFF THE FLOOR lesson gets a
  // real juggle to tech out of; "sweep" is the derived crouching HK — the
  // knockdown low every kit has — for the wake-up steps. Both breathe longer
  // than the guard scripts because the player is on the floor or in the air.
  if (script === "low") frames.push({ down: true, heavy: true });
  else if (script === "launcher") frames.push({ launcher: true });
  else if (script === "sweep") frames.push({ down: true, heavy: true, limb: "kick" });
  else frames.push({ left: true, heavy: true });
  const rest = script === "launcher" || script === "sweep" ? 110 : 66;
  for (let index = 0; index < rest; index += 1) frames.push({});
  return frames;
}

// 5.1 STREET FURNITURE: the lab's SPAWN STAGE WEAPON button body, shared with
// the school's "weapon" setup so the lesson can keep an object on the floor.
function spawnTrainingWeapon() {
  if (!state.stageWeaponsEnabled) {
    if (schoolSession.active) schoolSession.restoreWeapons = true;
    setStageWeapons(true);
  }
  if (!state.stageWeapon) resetStageWeapon();
  if (!state.stageWeapon) return false;
  state.stageWeapon.phase = "ground";
  state.stageWeapon.frames = 0;
  state.stageWeapon.holder = -1;
  state.fighters.forEach((fighter) => { fighter.carriedWeapon = null; fighter.carryFrames = 0; });
  updateHud();
  return true;
}

function applySchoolStepSetup() {
  if (!schoolSession.active || !schoolSession.machine) return;
  const lesson = fightSchoolLesson(schoolSession.machine);
  const step = lesson?.steps[schoolSession.machine.step];
  if (!lesson) return;
  if (step?.dummyScript) {
    state.training.recording = schoolDummyScript(step.dummyScript).map((frame) => ({ ...frame }));
    state.training.recordingActive = false;
    state.training.playbackFrame = 0;
    state.training.dummyMode = "playback";
  } else {
    state.training.dummyMode = "cpu";
  }
  if (lesson.setup === "dizzy") {
    schoolSession.pendingSetup = "dizzy";
  } else if (lesson.setup === "lowHealth") {
    state.training.autoRecover = false;
    schoolSession.pendingSetup = "lowHealth";
  } else if (lesson.setup === "weapon") {
    state.training.autoRecover = true;
    schoolSession.pendingSetup = "weapon";
    schoolSession.weaponSpawnTick = -Infinity;
  } else {
    state.training.autoRecover = true;
    schoolSession.pendingSetup = null;
  }
  updateTrainingUi();
}

function applySchoolLessonSetup() {
  if (!schoolSession.active) return;
  resetTrainingPosition(false);
  applySchoolStepSetup();
}

function exitFightSchool({ toTitle = false } = {}) {
  if (!schoolSession.active) return;
  schoolSession.active = false;
  schoolSession.pendingSetup = null;
  stopTrialDemo();
  if (schoolSession.savedDifficulty) setAiDifficulty(schoolSession.savedDifficulty);
  // 5.1: the STREET FURNITURE lesson may have switched stage weapons on for
  // a player who keeps them off — hand the option back the way it was.
  if (schoolSession.restoreWeapons) {
    schoolSession.restoreWeapons = false;
    setStageWeapons(false);
  }
  if (state.mode === "training") {
    state.training.autoRecover = true;
    state.training.dummyMode = "stand";
  }
  $("#schoolPanel").hidden = true;
  if (!toTitle) updateTrainingUi();
}

// 5.3: `startAt` is the lesson index the coach card routes to. Omitted (the
// menu button, the newcomer ribbon) it keeps the old behaviour — the first
// lesson the player has not finished.
function startFightSchool(startAt = null) {
  unlockAudio();
  exitDemo?.();
  state.mode = "training";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  const progress = loadSchoolProgress();
  const firstOpen = FIGHT_SCHOOL_LESSONS.findIndex((lesson) => !progress.completed[lesson.id]);
  const requested = Number.isInteger(startAt) && startAt >= 0 && startAt < FIGHT_SCHOOL_LESSONS.length
    ? startAt
    : null;
  state.picks = [0, 1];
  state.locks = [true, true];
  startMatch(true);
  state.phase = "fight";
  state.phaseTime = 0;
  schoolSession.machine = createFightSchoolState({
    lesson: requested !== null ? requested : firstOpen < 0 ? 0 : firstOpen,
    completed: requested !== null || firstOpen >= 0 ? progress.completed : {},
  });
  schoolSession.active = true;
  schoolSession.savedDifficulty = state.aiDifficulty;
  schoolSession.coachLast = {};
  setAiDifficulty("passive");
  state.training.dummyMode = "cpu";
  state.training.infiniteGrit = true;
  state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  applySchoolLessonSetup();
  renderSchoolPanel();
  const lesson = fightSchoolLesson(schoolSession.machine);
  announce(lesson ? lesson.name : "FIGHT SCHOOL", schoolCoach("start"), 2.4);
  updateTrainingUi();
}

// COMBO TRIALS quick entry: boots the lab with the locked trial dummy config
// (standing dummy, infinite Grit) using the current fighter picks.
function startComboTrialsLab() {
  unlockAudio();
  schoolSession.active = false;
  $("#schoolPanel").hidden = true;
  state.mode = "training";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  startMatch(true);
  state.phase = "fight";
  state.phaseTime = 0;
  state.training.dummyMode = "stand";
  state.training.infiniteGrit = true;
  state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  selectTrainingTrial(state.training, state.fighters[0].kitId, 0);
  announce("COMBO TRIALS", "PICK A TRIAL · WATCH THE DEMO · EARN MEDALS", 1.8);
  updateTrainingUi();
}

// R1.9 LEGEND: the touch HUD advertises the one-button jobs (CSS badges via
// the data attribute, semantics via aria labels).
function syncTouchControlStyle() {
  $("#touchControls").dataset.controlStyle = state.controlStyle;
  const legend = state.controlStyle === "legend";
  $(".touch-hp").setAttribute("aria-label", legend
    ? "Special attack, or super at full Grit"
    : "Heavy punch, hook");
  $(".touch-hk").setAttribute("aria-label", legend
    ? "Kick special"
    : "Heavy kick, roundhouse");
}

/**
 * School progress fold. Called from guarded hook points (hit/block/finisher on
 * sim paths behind !rollbackResimulating, walk from updateTrainingUi which
 * already early-returns during resimulation).
 */
function schoolEvent(event) {
  if (!schoolSession.active || !schoolSession.machine) return;
  if (state.mode !== "training") return;
  const progress = fightSchoolObserve(schoolSession.machine, event);
  if (!progress) return;
  trainingFxDebug.schoolSteps += 1;
  saveSchoolProgress();
  // 5.3: the coach reads the completion map, so a finished lesson has to move
  // the title recommendation on before the player gets back there.
  refreshProgressionUi();
  if (progress.graduated) {
    announce("SCHOOL'S OUT", schoolCoach("graduate"), 2.6);
    state.training.autoRecover = true;
    // v2.1 PROGRESSION: graduation inks THE GRADUATE (ledger dedupes).
    progressionEvent("fightSchool");
    progressionEvaluateLedger();
  } else if (progress.lessonComplete) {
    const next = fightSchoolLesson(schoolSession.machine);
    announce(next ? next.name : "FIGHT SCHOOL", schoolCoach("lesson"), 2.3);
    applySchoolLessonSetup();
  } else {
    announce("NICE", schoolCoach("step"), 1.5);
    applySchoolStepSetup();
  }
  renderSchoolPanel();
}

// Per-tick school observation: walking drills, the panel/dummy babysitting and
// the deferred sim-side setups (dizzy stun, low-health KO dummy).
function schoolTick() {
  if (!schoolSession.active) return;
  if (state.mode !== "training" || state.screen !== "fight") {
    exitFightSchool({ toTitle: true });
    return;
  }
  const machine = schoolSession.machine;
  const lesson = fightSchoolLesson(machine);
  const step = lesson?.steps[machine.step];
  const [player, dummy] = state.fighters;
  if (schoolSession.pendingSetup === "dizzy" && dummy
    && state.simulationTick - schoolSession.dizzyCooldownTick > 90) {
    if (dummy.dizzyFrames <= 0 && !dummy.down && dummy.wakeupFrames <= 0) {
      enterDizzy(dummy, player);
      schoolSession.dizzyCooldownTick = state.simulationTick;
    }
  }
  if (schoolSession.pendingSetup === "lowHealth" && dummy && dummy.health > 5 && state.phase === "fight") {
    dummy.health = 5;
    updateHud();
  }
  // 5.1 STREET FURNITURE: keep an object on the floor until the lesson is
  // done — a thrown or expired weapon respawns after a breath (the "thrown"
  // phase is left alone so the landing hit can still bank the step).
  if (schoolSession.pendingSetup === "weapon" && state.phase === "fight"
    && state.simulationTick - (schoolSession.weaponSpawnTick ?? -Infinity) > 60) {
    const weapon = state.stageWeapon;
    if (!weapon || !["ground", "held", "thrown"].includes(weapon.phase)) {
      schoolSession.weaponSpawnTick = state.simulationTick;
      spawnTrainingWeapon();
    }
  }
  if (step?.kind === "walk" && player && player.grounded && !player.attacking
    && player.hitstunFrames <= 0 && player.blockstunFrames <= 0 && Math.abs(player.vx) > 40) {
    const direction = Math.sign(player.vx) === player.facing ? "forward" : "back";
    schoolEvent({ type: "walk", direction });
  }
}
const initialsUi = {
  active: false,
  letters: ["A", "A", "A"],
  cursor: 0,
  score: 0,
  onDone: null,
};
// Monotonic one-shot totals for the new modes, on the hudFxDebug pattern.
const modeFxDebug = {
  tallyScreens: 0,
  tallyCountUps: 0,
  initialsEntries: 0,
  survivalMilestones: 0,
  teamEliminations: 0,
  teamWalkIns: 0,
  teamDrafts: 0,
  dailyRuns: 0,
  attractScoreBoards: 0,
  scoreSubmissions: 0,
  // v2.1 PROGRESSION one-shot totals, same monotonic pattern.
  blackBookToasts: 0,
  bookStamps: 0,
  rankSlams: 0,
  endingPanelsShown: 0,
  creditsRolls: 0,
  endingSequences: 0,
  blackBookScreens: 0,
  recordsScreens: 0,
  // R2.0 FAMILY wave 16 one-shot totals.
  commissionerUnlocks: 0,
  dialogueExchanges: 0,
  dialogueCardsShown: 0,
  winQuoteSelections: 0,
};

// ===========================================================================
// v2.1 PROGRESSION (R1.8 GRIND remainder) — The Black Book achievements
// ledger + fight records + mastery ranks. All logic lives in
// engine/progression.mjs (pure); this block is observation + persistence +
// UI. Everything here is render/meta-side on the scoreSession pattern:
// module-level, never snapshotted, never read by the sim. Hooks that sit on
// sim paths are announce()-guarded (`if (!rollbackResimulating)`) at the call
// site, and the fold points dedupe by matchSerial/round key, so rollback
// resimulation can never double-count. Online-safe by shape: observation only.
// ===========================================================================

const RECORDS_STORAGE_KEY = "final-blow-records";
const BLACK_BOOK_STORAGE_KEY = "final-blow-black-book";
// 5.3: one slot, overwritten every match — the LAST fight, not a history.
// It survives a reload so the title screen can still name a lesson.
const LAST_FIGHT_STORAGE_KEY = "final-blow-last-fight";

let recordsStore = normalizeRecordsStore(storedJson(RECORDS_STORAGE_KEY, null));
let blackBookLedger = normalizeBlackBookStore(storedJson(BLACK_BOOK_STORAGE_KEY, null));
let lastFightDigest = normalizeFightDigest(storedJson(LAST_FIGHT_STORAGE_KEY, null));

function saveRecordsStore() {
  try {
    localStorage.setItem(RECORDS_STORAGE_KEY, JSON.stringify(recordsStore));
  } catch { /* storage full/blocked — records stay in-memory for the session */ }
}

function saveLastFightDigest() {
  try {
    localStorage.setItem(LAST_FIGHT_STORAGE_KEY, JSON.stringify(lastFightDigest));
  } catch { /* storage full/blocked — the digest stays in-memory for the session */ }
}

function saveBlackBookLedger() {
  try {
    localStorage.setItem(BLACK_BOOK_STORAGE_KEY, JSON.stringify(blackBookLedger));
  } catch { /* non-fatal */ }
}

// Per-match observation accumulators. Reset at every match start (real flows
// and QA fights); folded exactly once per match by progressionMatchEnd.
const progressionMatch = {
  serial: -1,
  folded: false,
  rounds: 0,
  roundWins: [0, 0],
  perfectRounds: [0, 0],
  damageDealt: [0, 0],
  damageTaken: [0, 0],
  dizzies: [0, 0],
  techs: [0, 0],
  supers: [0, 0],
  moveUses: [{}, {}],
  fatalities: [0, 0],
  fatalityVariants: [[], []],
  peakCombo: [0, 0],
  timeOverWin: false,
  // Per-round latches.
  jumped: [false, false],
  roundStartHealth: [100, 100],
  // Last damage applied to each side: { tick, chip, weapon } — read only at
  // round end to classify decision/weapon finishes.
  lastDamage: [null, null],
  roundKey: "",
  // 5.3 (sweep #30 / #31): the P1 seat's last-fight digest — per-cause damage
  // taken plus the handful of habit counters the FIGHT SCHOOL lesson graph
  // reads. Guarded meta like everything else here; never read by the sim.
  digest: createFightDigest(),
};

function progressionResetRound() {
  progressionMatch.jumped = [false, false];
  progressionMatch.lastDamage = [null, null];
  progressionMatch.roundStartHealth = state.fighters.map((fighter) => clamp(fighter?.health ?? 100, 0, 100));
}

function progressionResetMatch() {
  progressionMatch.serial = state.matchSerial;
  progressionMatch.folded = false;
  progressionMatch.rounds = 0;
  progressionMatch.roundWins = [0, 0];
  progressionMatch.perfectRounds = [0, 0];
  progressionMatch.damageDealt = [0, 0];
  progressionMatch.damageTaken = [0, 0];
  progressionMatch.dizzies = [0, 0];
  progressionMatch.techs = [0, 0];
  progressionMatch.supers = [0, 0];
  progressionMatch.moveUses = [{}, {}];
  progressionMatch.fatalities = [0, 0];
  progressionMatch.fatalityVariants = [[], []];
  progressionMatch.peakCombo = [0, 0];
  progressionMatch.timeOverWin = false;
  progressionMatch.roundKey = "";
  progressionMatch.digest = createFightDigest();
  progressionResetRound();
}

// Human seat rule: the ledger and records belong to the P1 seat (the cabinet
// owner's book). Demo and tournament (CPU in seat 0) never write; the
// arcade/survival/team CPU in seat 1 never earns credit. Online is
// observation-only — the local player renders as side 0 there too.

// Move usage observation from beginAttack (sim path; call site is guarded).
// Distinct-move cap bounds localStorage growth against modded/QA move ids.
function progressionNoteMove(fighter) {
  if (state.screen !== "fight" || fighter.side !== 0 && fighter.side !== 1) return;
  const name = String(fighter.attacking?.profileId || fighter.attacking?.kind || "").trim();
  if (!name) return;
  const uses = progressionMatch.moveUses[fighter.side];
  if (uses[name] === undefined && Object.keys(uses).length >= 64) return;
  uses[name] = (uses[name] || 0) + 1;
}

// Damage-source latch from every damage site (guarded call sites).
//
// 5.3: the same call now attributes the hit. `lastDamage` answers "what had
// the last word" for the ledger; the digest answers "what took my health",
// which needs a cause per landed hit — a health delta at round end cannot
// know. Only the P1 seat is folded (the digest is the cabinet owner's), and
// a blocked hit counts as a block whether or not its chip is non-zero.
function progressionNoteDamage(victimSide, {
  chip = false, weapon = false, amount = 0,
  throwMove = false, throwable = false, superMove = false, kind = "", level = "",
} = {}) {
  if (victimSide !== 0 && victimSide !== 1) return;
  progressionMatch.lastDamage[victimSide] = { tick: state.simulationTick, chip, weapon };
  if (victimSide !== 0 || sideIsCpuControlled(0)) return;
  const digest = progressionMatch.digest;
  if (chip) digest.blocks += 1;
  const cause = classifyDamageCause({ blocked: chip, throwMove, weapon, throwable, superMove, kind, level });
  noteFightDamage(digest, cause, amount);
  digest.damageTaken += Math.max(0, Number(amount) || 0);
}

// The mirror of the latch on the attacking side: what the player actually
// GOT OUT, which is half of what the lesson graph reasons about (a fight with
// no special and no EX is a different lesson from a fight with no blocks).
function progressionNoteLanded(attackerSide, {
  blocked = false, kind = "", superMove = false, enhanced = false, throwable = false,
} = {}) {
  if (attackerSide !== 0 || blocked || sideIsCpuControlled(0)) return;
  const digest = progressionMatch.digest;
  digest.hitsLanded += 1;
  if (throwable) digest.throwablesUsed += 1;
  if (superMove) digest.supersLanded += 1;
  else if (enhanced) digest.exLanded += 1;
  if (superMove || kind === "special") digest.specialsLanded += 1;
  else if (kind === "heavy") digest.heavyLanded += 1;
  else if (kind === "light") digest.lightLanded += 1;
  // A throw is booked on the seat that ATE it (throwsTaken), not here.
}

// Instant one-shot ledger events (throwables landed, perfect guards, taunts…).
// Counters only — predicate evaluation waits for the next bounded fold point.
function progressionEvent(kind, detail = {}, side = 0) {
  if (side !== 0 || sideIsCpuControlled(0)) return;
  blackBookObserve(blackBookLedger, { type: "event", kind, ...detail });
}

// Queue of pending unlock/rank toasts, shown one at a time via the announcer
// letter-slam + the book-stamp overlay. Pure DOM/timer land.
const progressionToasts = [];
let progressionToastTimer = 0;
let progressionToastHideTimer = 0;

function queueBlackBookUnlocks(entries) {
  for (const entry of entries) {
    progressionToasts.push({ kind: "unlock", title: entry.title, sub: "THE BLACK BOOK · ENTRY INKED" });
  }
  pumpProgressionToasts();
}

function queueRankUpToast(rank, fighterName) {
  progressionToasts.push({ kind: "rank", title: rank.name, sub: `${fighterName} · MASTERY ${rank.badge}` });
  pumpProgressionToasts();
}

function pumpProgressionToasts(delay = 1400) {
  if (progressionToastTimer || !progressionToasts.length) return;
  progressionToastTimer = window.setTimeout(() => {
    progressionToastTimer = 0;
    const toast = progressionToasts.shift();
    if (toast) showProgressionToast(toast);
    if (progressionToasts.length) pumpProgressionToasts(3050);
  }, delay);
}

function showProgressionToast(toast) {
  const box = $("#bookStampToast");
  if (!box) return;
  const strong = box.querySelector("strong");
  const letters = [...String(toast.title)];
  const stagger = 45;
  strong.setAttribute("aria-label", toast.title);
  // Same per-letter slam markup as announce(): spaces keep white-space:pre so
  // textContent round-trips exactly for QA reads.
  strong.innerHTML = letters.map((character, index) => (character === " "
    ? `<i class="gap" aria-hidden="true"> </i>`
    : `<i aria-hidden="true" style="animation-delay:${index * stagger}ms">${escapeAnnounceChar(character)}</i>`)).join("");
  box.querySelector(".stamp-sub").textContent = toast.sub;
  box.querySelector(".stamp-seal b").textContent = toast.kind === "rank" ? "RANK" : "INKED";
  box.classList.toggle("rank-up", toast.kind === "rank");
  // On the fight screen the announcer banner slams the title itself, so the
  // toast keeps just the seal + sub instead of doubling the letters.
  box.classList.toggle("with-announcer", state.screen === "fight");
  box.classList.remove("out");
  box.hidden = false;
  restartCssAnimation(box.querySelector(".stamp-seal"), "thud");
  if (toast.kind === "rank") modeFxDebug.rankSlams += 1;
  else modeFxDebug.blackBookToasts += 1;
  modeFxDebug.bookStamps += 1;
  // Mirror the call onto the fight announcer when a bout is on screen — the
  // letter-slam pipeline proper (announce() self-guards against resim).
  if (state.screen === "fight") announce(toast.title, toast.sub, 1.9);
  sound("select");
  window.clearTimeout(progressionToastHideTimer);
  progressionToastHideTimer = window.setTimeout(() => {
    box.classList.add("out");
    window.setTimeout(() => { box.hidden = true; box.classList.remove("out"); }, 160);
  }, 2600);
}

// Bounded evaluation point: run every locked predicate, stamp fresh unlocks
// with today's date, persist, queue toasts.
function progressionEvaluateLedger() {
  const fresh = evaluateBlackBook(blackBookLedger, dailyDateString());
  if (fresh.length) {
    saveBlackBookLedger();
    queueBlackBookUnlocks(fresh);
    refreshProgressionUi();
  }
  return fresh;
}

// Round-end fold, called from finishRound inside its existing
// `if (!rollbackResimulating)` block. Deduped by the same key shape
// queueStoryCallouts uses so a re-entered round can never double-fold.
function progressionRoundEnd(winner, type) {
  if (state.fighters.length !== 2 || state.mode === "demo" || state.mode === "tournament") return;
  const key = `${state.matchSerial}:${state.round}:${winner}:${state.rounds[winner]}`;
  if (key === progressionMatch.roundKey) return;
  progressionMatch.roundKey = key;
  if (progressionMatch.serial !== state.matchSerial) progressionResetMatch();
  const loser = 1 - winner;
  const winnerFighter = state.fighters[winner];
  const loserFighter = state.fighters[loser];
  // Health deltas against the round-start latch (health only falls mid-round).
  for (const side of [0, 1]) {
    const dealt = Math.max(0, progressionMatch.roundStartHealth[1 - side] - clamp(state.fighters[1 - side].health, 0, 100));
    const taken = Math.max(0, progressionMatch.roundStartHealth[side] - clamp(state.fighters[side].health, 0, 100));
    progressionMatch.damageDealt[side] += dealt;
    progressionMatch.damageTaken[side] += taken;
    progressionMatch.peakCombo[side] = Math.max(progressionMatch.peakCombo[side], state.fighters[side].combo?.peakHits || 0);
  }
  progressionMatch.rounds += 1;
  progressionMatch.roundWins[winner] += 1;
  const perfect = winnerFighter.health >= 100;
  if (perfect) progressionMatch.perfectRounds[winner] += 1;
  const timeOver = state.timer <= 0 && loserFighter.health > 0;
  if (timeOver && winner === 0) progressionMatch.timeOverWin = true;
  if (type >= 0) {
    progressionMatch.fatalities[winner] += 1;
    if (!winnerFighter.def.boss) {
      progressionMatch.fatalityVariants[winner].push(`${winnerFighter.def.id}:${type}`);
    }
  }
  // The Black Book observes from the P1 seat only.
  if (sideIsCpuControlled(0)) return;
  const lastOnLoser = progressionMatch.lastDamage[loser];
  if (winner === 0 && loserFighter.health <= 0 && lastOnLoser?.weapon) {
    blackBookObserve(blackBookLedger, { type: "event", kind: "weaponKo", stage: state.stage });
  }
  blackBookObserve(blackBookLedger, {
    type: "roundEnd",
    won: winner === 0,
    perfect: winner === 0 && perfect,
    timeOver,
    chip: Boolean(winner === 0 && timeOver && lastOnLoser?.chip),
    jumped: progressionMatch.jumped[0],
    combo: state.fighters[0].combo?.peakHits || 0,
    fatality: type >= 0 && winner === 0 && !winnerFighter.def.boss
      ? { fighterId: winnerFighter.def.id, variant: type, opponentIsBoss: Boolean(loserFighter.def.boss) }
      : null,
  });
  progressionEvaluateLedger();
}

function progressionRecordMode() {
  if (dailySession.active && state.mode === "arcade") return "daily";
  if (["arcade", "survival", "team"].includes(state.mode)) return state.mode;
  return "versus";
}

// Match-end fold: exactly once per matchSerial, from the resolveMatchResult
// family (never a resim path — guarded anyway for safety).
function progressionMatchEnd(winner) {
  if (rollbackResimulating || progressionMatch.folded) return;
  if (progressionMatch.serial !== state.matchSerial || state.fighters.length !== 2) return;
  if (state.mode === "demo" || state.mode === "tournament") return;
  progressionMatch.folded = true;
  const heroDef = state.fighters[0]?.def;
  if (!heroDef || heroDef.boss || sideIsCpuControlled(0)) return;
  const won = winner === 0;
  const result = applyMatchToRecords(recordsStore, {
    fighterId: heroDef.id,
    mode: progressionRecordMode(),
    won,
    rounds: progressionMatch.rounds,
    roundWins: progressionMatch.roundWins[0],
    damageDealt: progressionMatch.damageDealt[0],
    damageTaken: progressionMatch.damageTaken[0],
    fatalities: progressionMatch.fatalities[0],
    fatalityVariants: progressionMatch.fatalityVariants[0],
    dizzies: progressionMatch.dizzies[0],
    perfects: progressionMatch.perfectRounds[0],
    peakCombo: progressionMatch.peakCombo[0],
    timeOverWin: progressionMatch.timeOverWin,
    moveUses: progressionMatch.moveUses[0],
  });
  saveRecordsStore();
  // 5.3: seal the digest for this match and hand it to the coach. The record
  // store's damage numbers come from round-start health deltas; the digest's
  // come from the attributed hits, so they agree to within chip rounding and
  // the percentage on the result screen is internally consistent.
  const digest = progressionMatch.digest;
  digest.fighterId = heroDef.id;
  digest.opponentId = state.fighters[1]?.def?.id || "";
  digest.mode = progressionRecordMode();
  digest.won = won;
  digest.rounds = progressionMatch.rounds;
  digest.damageDealt = progressionMatch.damageDealt[0];
  lastFightDigest = normalizeFightDigest(digest);
  saveLastFightDigest();
  if (result?.rankedUp) queueRankUpToast(result.after, heroDef.name);
  blackBookObserve(blackBookLedger, {
    type: "matchEnd",
    won,
    stage: state.stage,
    techs: progressionMatch.techs[0],
    dizzies: progressionMatch.dizzies[0],
    supers: progressionMatch.supers[0],
    perfectRounds: progressionMatch.perfectRounds[0],
    runScore: scoreTrackingActive() || scoreSession.total > 0 ? Math.round(scoreSession.total) : 0,
  });
  progressionEvaluateLedger();
  saveBlackBookLedger();
  refreshProgressionUi();
}

// Run-end fold (arcade clear, survival streak, daily, Block War) — pure
// meta paths, called beside the mode resolvers.
function progressionRunEnd(kind, detail = {}) {
  if (rollbackResimulating || sideIsCpuControlled(0)) return;
  blackBookObserve(blackBookLedger, { type: "runEnd", kind, ...detail });
  progressionEvaluateLedger();
  saveBlackBookLedger();
  // Wave 16: a FINAL-difficulty arcade clear hands over the Keeper's keys.
  if (kind === "arcade" && detail.finalDifficulty) unlockCommissioner();
}

// ---------------------------------------------------------------------------
// Wave 16 — playable-Commissioner unlock plumbing. Persisted via the standard
// final-blow-* localStorage pattern; the roster, the select grid and the
// online eligibility set all resync from the one flag.
// ---------------------------------------------------------------------------
function unlockCommissioner({ quiet = false } = {}) {
  const fresh = !commissionerUnlocked();
  localStorage.setItem(COMMISSIONER_UNLOCK_KEY, "1");
  if (!rosterHasCommissioner()) {
    roster.push(commissionerPlayableDef);
    setupRoster();
  buildMoveListSelect();
  }
  onlineFighterIds.add(ARCADE_BOSS_ID);
  syncOnlineCommissionerOption();
  if (fresh && !quiet) {
    modeFxDebug.commissionerUnlocks += 1;
    progressionToasts.push({ kind: "unlock", title: "KEEPER'S KEYS", sub: "THE COMMISSIONER JOINS THE ROSTER · 9TH SLOT" });
    pumpProgressionToasts();
  }
  return fresh;
}

function relockCommissioner() {
  localStorage.removeItem(COMMISSIONER_UNLOCK_KEY);
  const index = roster.findIndex(({ id }) => id === ARCADE_BOSS_ID);
  if (index >= 0) roster.splice(index, 1);
  onlineFighterIds.delete(ARCADE_BOSS_ID);
  syncOnlineCommissionerOption();
  setupRoster();
  buildMoveListSelect();
  return true;
}

function progressionHighScore(rank) {
  if (!Number.isFinite(rank) || rank < 0) return;
  blackBookObserve(blackBookLedger, { type: "highScore", rank });
  progressionEvaluateLedger();
  saveBlackBookLedger();
}

// CINEMA 3D first activation — fired from the options toggle (DOM path).
function progressionCinemaActivated() {
  blackBookObserve(blackBookLedger, { type: "event", kind: "cinema3d" });
  progressionEvaluateLedger();
  saveBlackBookLedger();
}

// --- Progression UI: title status, Black Book screen, Records screen -------

function refreshProgressionUi() {
  const summary = blackBookSummary(blackBookLedger);
  const bookStatus = $("#blackBookStatus");
  if (bookStatus) bookStatus.textContent = `${summary.unlocked} / ${summary.total} INKED`;
  const records = recordsSummary(recordsStore);
  const recordsStatus = $("#recordsStatus");
  if (recordsStatus) {
    recordsStatus.textContent = records.matches > 0
      ? `${records.wins}W · ${records.losses}L · ${records.rankedFighters} RANKED`
      : "NO FIGHTS LOGGED";
  }
  // 5.1 (sweep #30): the school button reports real progress, and a player
  // with no fight logged and no lesson done gets a one-line route to it.
  const school = loadSchoolProgress();
  const done = Object.keys(school.completed).length;
  const schoolStatus = $("#fightSchoolStatus");
  if (schoolStatus) {
    schoolStatus.textContent = school.graduated || done >= FIGHT_SCHOOL_LESSONS.length
      ? "GRADUATED · REPLAY ANY LESSON"
      : done > 0
        ? `${done} / ${FIGHT_SCHOOL_LESSONS.length} LESSONS DONE`
        : `${FIGHT_SCHOOL_LESSONS.length} LESSONS · FREE`;
  }
  const newcomer = $("#titleNewcomer");
  const recommendation = currentLessonRecommendation();
  // The NEW HERE ribbon is the zero-state; once a fight is on the books the
  // coach card takes over, so the two never stack.
  const firstRun = records.matches === 0 && done === 0;
  if (newcomer) newcomer.hidden = !firstRun;
  renderCoachCard("#titleCoach", recommendation, { hidden: firstRun });
}

// ---------------------------------------------------------------------------
// 5.3 (sweep #30 / #31): THE COACH.
//
// One recommendation, computed from the last fight's digest against the
// school's completion map (engine/training.mjs owns the rule order; this side
// only renders it and routes the click). Shown in the title's LEARN tier and
// again on the result screen, where the fight it is talking about is still on
// the player's mind.
// ---------------------------------------------------------------------------

function currentLessonRecommendation(digest = lastFightDigest) {
  const progress = loadSchoolProgress();
  return recommendLesson(digest, { completed: progress.completed });
}

function renderCoachCard(selector, recommendation, { hidden = false } = {}) {
  const card = $(selector);
  if (!card) return null;
  if (!recommendation || hidden) {
    card.hidden = true;
    delete card.dataset.lesson;
    return null;
  }
  card.querySelector("b").textContent = recommendation.headline;
  card.querySelector("small").textContent = recommendation.reason;
  card.dataset.lesson = String(recommendation.lessonIndex);
  card.dataset.rule = recommendation.ruleId || "";
  card.hidden = false;
  return recommendation;
}

function startRecommendedLesson(selector) {
  const card = $(selector);
  const index = Number(card?.dataset.lesson);
  sound("select");
  startFightSchool(Number.isInteger(index) ? index : null);
}

function renderBlackBookScreen() {
  const summary = blackBookSummary(blackBookLedger);
  $("#blackBookCount").textContent = `${summary.unlocked} / ${summary.total} INKED`;
  $("#blackBookList").innerHTML = BLACK_BOOK_ENTRIES.map((entry, index) => {
    const date = blackBookLedger.unlocked[entry.id];
    const ordinal = String(index + 1).padStart(2, "0");
    if (date !== undefined) {
      return `<div class="book-entry inked" role="listitem" data-ordinal="${ordinal}">
        <b>${entry.title}</b><span>${entry.line}</span>
        <span class="book-date">INKED${date ? ` · ${date}` : ""}</span>
      </div>`;
    }
    return `<div class="book-entry locked" role="listitem" data-ordinal="${ordinal}">
      <b aria-label="Redacted entry">${entry.title.replace(/[^ ]/g, "█")}</b>
      <span>${entry.hint}</span>
    </div>`;
  }).join("");
}

function showBlackBookScreen() {
  renderBlackBookScreen();
  modeFxDebug.blackBookScreens += 1;
  sound("select");
  showScreen("blackbook");
}

function formatRecordNumber(value) {
  return Math.round(value).toLocaleString("en-US");
}

function renderRecordsScreen() {
  const records = recordsSummary(recordsStore);
  $("#recordsLifetime").innerHTML = [
    ["MATCHES", records.matches],
    ["WINS", records.wins],
    ["LOSSES", records.losses],
    ["ROUNDS", records.rounds],
    ["DMG DEALT", formatRecordNumber(records.damageDealt)],
    ["DMG TAKEN", formatRecordNumber(records.damageTaken)],
    ["FINAL BLOWS", records.fatalities],
    ["PERFECTS", records.perfects],
  ].map(([label, value]) => `<span>${label} <b>${value}</b></span>`).join("");
  const best = loadSurvivalBest();
  const daily = loadDailyRecord();
  $("#recordsStreaks").textContent =
    `GAUNTLET BEST ${best.streak} STRAIGHT · DAILY STREAK ${Math.max(0, Math.round(Number(daily?.streak) || 0))} (BEST ${Math.max(0, Math.round(Number(daily?.bestStreak) || 0))})`;
  $("#recordsGrid").innerHTML = roster.map((def) => {
    const record = recordsStore.fighters[def.id] || null;
    const rank = masteryRank(record);
    const favorite = favoriteMove(record);
    const modes = record?.modes || {};
    const arcadeWins = (modes.arcade?.wins || 0) + (modes.daily?.wins || 0);
    return `<div class="record-card" role="listitem" style="--fighter:${def.color}">
      <img src="assets/fighters/${def.id}.webp" alt="" draggable="false">
      <h3>${def.name}</h3>
      <span class="record-rank" data-tier="${rank.id}" title="${rank.points} PTS${rank.nextName ? ` · ${rank.toNext} TO ${rank.nextName}` : ""}">${rank.tierIndex > 0 ? rank.name : "UNRANKED"}</span>
      <div class="record-lines">
        <span>W — L <b>${record?.wins || 0} — ${record?.losses || 0}</b></span>
        <span>ROUNDS <b>${record?.rounds || 0}</b></span>
        <span>DMG DEALT <b>${formatRecordNumber(record?.damageDealt || 0)}</b></span>
        <span>DMG TAKEN <b>${formatRecordNumber(record?.damageTaken || 0)}</b></span>
        <span>GO-TO MOVE <b>${favorite ? prettyMoveName(favorite.action) : "—"}</b></span>
        <span>FINAL BLOWS <b>${record?.fatalities || 0}</b></span>
        <span>PEAK COMBO <b>${record?.peakCombo || 0} HITS</b></span>
        <span>ARCADE WINS <b>${arcadeWins}</b></span>
      </div>
    </div>`;
  }).join("");
}

function showRecordsScreen() {
  renderRecordsScreen();
  modeFxDebug.recordsScreens += 1;
  sound("select");
  showScreen("records");
}

// Small mastery chip on every select-screen portrait card.
function refreshMasteryBadges() {
  $$(".fighter-card .mastery-badge").forEach((badge) => {
    const card = badge.closest(".fighter-card");
    const id = roster[Number(card?.dataset.index)]?.id;
    if (!id) return;
    const rank = masteryRank(recordsStore.fighters[id]);
    badge.hidden = rank.tierIndex === 0;
    badge.dataset.tier = rank.id;
    badge.textContent = rank.badge;
    badge.title = `${rank.name} · ${rank.points} PTS`;
  });
}

function loadHighScores() {
  const stored = storedJson(SCORE_STORAGE_KEY, []);
  return Array.isArray(stored) ? stored.filter((row) => row && Number.isFinite(row.score)) : [];
}

function saveHighScores(list) {
  try {
    localStorage.setItem(SCORE_STORAGE_KEY, JSON.stringify(list.slice(0, SCORE_RULES.tableSize)));
  } catch { /* storage full/blocked — table stays in-memory for the session */ }
}

function loadSurvivalBest() {
  const stored = storedJson(SURVIVAL_BEST_KEY, null);
  return {
    streak: Math.max(0, Math.round(Number(stored?.streak) || 0)),
    score: Math.max(0, Math.round(Number(stored?.score) || 0)),
  };
}

function saveSurvivalBest(best) {
  try {
    localStorage.setItem(SURVIVAL_BEST_KEY, JSON.stringify(best));
  } catch { /* non-fatal */ }
}

function loadDailyRecord() {
  return storedJson(DAILY_RULES.storageKey, null);
}

function saveDailyRecord(record) {
  try {
    localStorage.setItem(DAILY_RULES.storageKey, JSON.stringify(record));
  } catch { /* non-fatal */ }
}

// Offline-first, failure-silent submission to Jez's first-party score worker
// (the pinball-fantasies / hard-hat-mac client pattern). The local table is
// already written before this is ever called; any network problem is ignored.
async function submitScoreToWorker(initials, score, detail) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    await fetch(SCORES_API, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ initials, score, extra: detail }),
      signal: controller.signal,
    });
    clearTimeout(timer);
    modeFxDebug.scoreSubmissions += 1;
  } catch { /* offline or worker down — the local table already has it */ }
}

function scoreTrackingActive() {
  return scoreSession.active && (state.mode === "arcade" || state.mode === "survival");
}

function beginScoreRun(mode, detail, multiplier) {
  scoreSession.active = true;
  scoreSession.mode = mode;
  scoreSession.detail = detail;
  scoreSession.total = 0;
  scoreSession.boutCount = 0;
  scoreSession.multiplier = multiplier;
  scoreSession.bout = createBoutTally();
  scoreSession.roundFirstHitDone = false;
  scoreSession.lastBout = null;
  scoreSession.lastBoutTotal = 0;
  scoreSession.submitted = false;
}

function endScoreRun() {
  scoreSession.active = false;
}

function resetRoundScoreTracking() {
  scoreSession.roundFirstHitDone = false;
}

// Per-hit points, called from the sim's hit/grab/projectile damage sites.
// Guarded: never during resimulation, never online, only the human player.
function awardHitScore(attacker, kind, { counter = false } = {}) {
  if (rollbackResimulating || !scoreTrackingActive() || attacker.side !== 0) return;
  const points = scoreForHit(kind, { counter });
  scoreSession.bout.fightPoints += points;
  scoreSession.bout.hits += 1;
  if (!scoreSession.roundFirstHitDone) {
    scoreSession.roundFirstHitDone = true;
    scoreSession.bout.firstAttacks += 1;
  }
}

function awardDizzyScore(attacker) {
  if (rollbackResimulating || !scoreTrackingActive() || attacker?.side !== 0) return;
  scoreSession.bout.dizzies += 1;
}

// Round-end bonuses, captured in finishRound (sim path, resim-guarded there).
function captureRoundBonuses(winner, finisherType) {
  if (!scoreTrackingActive() || winner !== 0) return;
  const player = state.fighters[0];
  scoreSession.bout.rounds += 1;
  scoreSession.bout.timeSeconds += Math.max(0, Math.ceil(state.timer));
  scoreSession.bout.vitality += Math.max(0, Math.round(player?.health || 0));
  if ((player?.health ?? 0) >= 100) scoreSession.bout.perfects += 1;
  if (finisherType >= 0) scoreSession.bout.fatalities += 1;
}

// Close out the finished bout: bank its multiplied total into the run score
// and hand back the tally for the SF2 count-up screen.
function finalizeBoutTally() {
  if (!scoreTrackingActive()) return null;
  const tally = scoreSession.bout;
  const boutTotal = tallyTotal(tally, scoreSession.multiplier);
  scoreSession.total += boutTotal;
  scoreSession.boutCount += 1;
  scoreSession.lastBout = tally;
  scoreSession.lastBoutTotal = boutTotal;
  scoreSession.bout = createBoutTally();
  return { tally, boutTotal, runTotal: scoreSession.total, multiplier: scoreSession.multiplier };
}

function scoreSessionSnapshot() {
  return {
    active: scoreSession.active,
    mode: scoreSession.mode,
    detail: scoreSession.detail,
    total: scoreSession.total,
    boutCount: scoreSession.boutCount,
    multiplier: scoreSession.multiplier,
    bout: { ...scoreSession.bout },
    lastBoutTotal: scoreSession.lastBoutTotal,
    roundFirstHitDone: scoreSession.roundFirstHitDone,
  };
}

function onlineSnapshot() {
  const rollback = onlineSession.rollback?.metrics() || null;
  const confirmedChecksumFrame = rollback
    ? Math.floor(Math.min(rollback.frame, rollback.confirmedRemoteFrame + 1, rollback.acknowledgedLocalFrame + 1) / 60) * 60
    : 0;
  return {
    role: onlineSession.role,
    roomId: onlineSession.roomId,
    fingerprint: onlineSession.roomId ? roomFingerprint(onlineSession.roomId) : "",
    expiresAt: onlineSession.expiresAt,
    peers: [...onlineSession.peers],
    latency: onlineSession.latency,
    status: onlineSession.status,
    signalingState: onlineSession.signaling?.socket?.readyState ?? -1,
    peer: onlineSession.peer?.snapshot() ?? null,
    lobby: { ...onlineSession.lobby },
    matchConfig: onlineSession.matchConfig ? { ...onlineSession.matchConfig } : null,
    matchActive: onlineSession.matchActive,
    networkPaused: onlineSession.networkPaused,
    reconnecting: onlineSession.reconnecting,
    rollback,
    checksumMismatches: onlineSession.checksumMismatches,
    localChecksum: rollback ? onlineSession.rollback.checksumAt(rollback.frame) : null,
    confirmedChecksumFrame,
    confirmedChecksum: confirmedChecksumFrame > 0 ? onlineSession.rollback.checksumAt(confirmedChecksumFrame) : null,
    lastChecksumSentFrame: onlineSession.lastChecksumSentFrame,
  };
}

// R2.1 STREETS: replay/set/connection/rematch observability for smoke tests
// and QA probes — counters on the monotonic netFxDebug pattern plus live
// module state. Read-only.
function netQolSnapshot() {
  return {
    counters: { ...netFxDebug },
    recorder: {
      active: replayRecorder.active,
      kind: replayRecorder.kind,
      aborted: replayRecorder.aborted,
      frames: replayRecorder.kind === "online"
        ? (replayRecorder.onlineFrames?.size || 0)
        : replayRecorder.frames0.length,
      startTick: replayRecorder.startTick,
      matchKey: replayRecorder.matchKey,
    },
    playback: {
      active: replayPlayback.active,
      index: replayPlayback.index,
      frames: replayPlayback.frames0.length,
      paused: replayPlayback.paused,
      speed: replayPlayback.speed,
      kind: replayPlayback.header?.kind || "",
      lastOutcome: replayUi.lastOutcome ? { ...replayUi.lastOutcome } : null,
      status: replayUi.status,
    },
    ringCount: loadReplayRing().length,
    set: {
      pendingLength: pendingSetLength,
      offline: offlineSet ? setSummary(offlineSet) : null,
      online: setSummary(onlineSession.set),
      lastLoserRole: onlineSession.lastLoserRole,
      stagePickerRole: onlineStagePickerRole(),
    },
    connection: {
      tier: connMeter.tier,
      sample: connMeterSample(),
      detail: connMeter.detail,
      forced: Boolean(connMeter.forced),
      toastedTier: connMeter.toastedTier,
    },
    lobbyQol: {
      remoteQol: onlineSession.lobby.remoteQol,
      remotePing: onlineSession.lobby.remotePing,
      setChoice: onlineSession.lobby.setChoice,
      remoteSetLength: onlineSession.lobby.remoteSetLength,
    },
    // Wave 19 — ONLINE SOCIAL summary block for the orchestrator's smoke.
    social: {
      qr: { rendered: Boolean(onlineQrState.matrix), version: onlineQrState.version, size: onlineQrState.size },
      streets: { rows: streetListUi.rows.length, stubbed: streetListUi.stubbed, error: streetListUi.lastError },
      spectate: {
        hostWatchers: spectateHost.watchers,
        hostStreaming: spectateHost.wantsStream,
        watcherActive: spectatorSession.active,
        watcherBuffered: spectatorSession.feed.frames0.length,
        spectatePlayback: replayPlayback.spectate,
      },
      bracket: {
        active: bracketSession.active,
        playing: bracketSession.playing,
        champion: bracketSession.bracket ? bracketSession.bracket.champion : -1,
        playedMatches: bracketSession.bracket?.playedMatches || 0,
        saved: Boolean(localStorage.getItem(BRACKET_STORAGE_KEY)),
      },
    },
    gameVersion: GAME_VERSION,
    protocol: ROLLBACK_PROTOCOL_VERSION,
  };
}

function demoSnapshot() {
  return {
    active: demoSession.active,
    attract: demoSession.attract,
    qa: demoSession.qa,
    cycle: demoSession.cycle ? { ...demoSession.cycle, picks: [...demoSession.cycle.picks] } : null,
    matches: demoSession.matches,
    superSide: demoSession.superSide,
    superShown: demoSession.superShown,
    difficulty: DEMO_AI_DIFFICULTY,
    resultScheduled: Boolean(demoSession.resultTimer),
    idleScheduled: Boolean(demoSession.idleTimer),
    director: demoSession.director?.snapshot() || null,
  };
}

function cancelFightAnnouncement() {
  window.clearTimeout(fightAnnouncementTimer);
  fightAnnouncementTimer = 0;
  fightAnnouncementPlan = null;
}

// v5.1 #35: the plan (callback, when it was armed, for how long) outlives the
// timer so the intro art hold can move the call by the time it held the sim.
function scheduleFightAnnouncement(callback, delay) {
  cancelFightAnnouncement();
  fightAnnouncementPlan = { callback, armedAt: performance.now(), delay };
  fightAnnouncementTimer = window.setTimeout(fireFightAnnouncement, delay);
}

function fireFightAnnouncement() {
  fightAnnouncementTimer = 0;
  const plan = fightAnnouncementPlan;
  if (!plan) return;
  // The timer beat the hold's release: leave the plan armed, the release
  // re-arms it for the shifted moment.
  if (introArtHold.active) return;
  fightAnnouncementPlan = null;
  plan.callback();
}

function shiftFightAnnouncement(heldMs, now) {
  const plan = fightAnnouncementPlan;
  if (!plan) return;
  window.clearTimeout(fightAnnouncementTimer);
  fightAnnouncementTimer = window.setTimeout(fireFightAnnouncement, shiftedAnnouncementDelay(plan, heldMs, now));
}

function clearDemoResultTimer() {
  window.clearTimeout(demoSession.resultTimer);
  demoSession.resultTimer = 0;
}

function clearIdleDemoTimer() {
  window.clearTimeout(demoSession.idleTimer);
  demoSession.idleTimer = 0;
}

function updateDemoUi() {
  const activeFight = demoSession.active && state.mode === "demo" && state.screen === "fight";
  const panel = $("#demoHud");
  panel.hidden = !activeFight;
  if (!demoSession.cycle) return;
  const [firstId, secondId] = demoSession.cycle.picks;
  const first = roster.find(({ id }) => id === firstId);
  const second = roster.find(({ id }) => id === secondId);
  $("#demoHudMatchup").textContent = `${first?.name || firstId} VS ${second?.name || secondId}`;
  $("#demoHudCycle").textContent = `CYCLE ${demoSession.cycle.cycle} · ${stages[demoSession.cycle.stage].name}`;
}

function endDemoSession() {
  clearDemoResultTimer();
  cancelFightAnnouncement();
  demoSession.active = false;
  demoSession.attract = false;
  demoSession.qa = false;
  demoSession.director = null;
  demoSession.cycle = null;
  demoSession.matches = 0;
  demoSession.superSide = 0;
  demoSession.superShown = false;
  demoSession.choreo = null;
  demoSession.pairsSeen = [];
  demoSession.coverageCarry = {};
  document.body.classList.remove("demo-active");
  $("#demoHud").hidden = true;
  $("#demoResultStatus").hidden = true;
  $("#attractScores").hidden = true;
  if (state.mode === "demo") state.mode = "arcade";
  if (state.musicChoice !== "auto") setTrack(Number(state.musicChoice), false);
}

function exitDemo() {
  if (!demoSession.active) return false;
  endDemoSession();
  showScreen("title");
  return true;
}

/**
 * Is the speed transport in scope at all? This is the ONE gate — the keys, the
 * qa hooks, the HUD chip and the render loop all ask exactly this. Online is
 * refused twice (by mode and by an active session role) because a client that
 * advances the sim on its own cadence stops delivering inputs on the frames
 * the remote peer is waiting for; replay playback is refused because it is
 * already its own transport and drives the clock itself.
 */
function demoSpeedScoped() {
  if (onlineSession.role) return false;
  return demoSpeedAllowed(state.mode, {
    online: state.mode === "online",
    replay: replayPlayback.active,
  });
}

/**
 * ...and is it allowed to drive the clock this frame? `qaManualMode` owns the
 * clock outright (qa.step is the driver there), so the transport stands down
 * and the QA reproduction path stays byte-identical.
 */
function demoSpeedActive() {
  return demoSpeedScoped() && !state.qaManualMode;
}

function demoSpeedSnapshot() {
  return {
    ...demoSpeed.snapshot(),
    scoped: demoSpeedScoped(),
    active: demoSpeedActive(),
    mode: state.mode,
    tick: simulationClock.tick,
  };
}

/**
 * The transport keys. Runs BEFORE the any-input-exits-the-demo rule in the
 * keydown listener — otherwise every one of these would quit the demo.
 */
function handleDemoSpeedKey(event) {
  if (!demoSpeedScoped() || event.altKey || event.ctrlKey || event.metaKey) return false;
  // Never eat a keystroke that belongs to something else. The transport's
  // defaults ([ ] \ . 1-4 R) collide with nothing in DEFAULT_KEY_MAPS, but
  // every combat key is REMAPPABLE — so a player who has bound one of these
  // keeps their binding, in training as much as anywhere. A rebind capture in
  // progress and any focused text field outrank it for the same reason.
  if (pendingKeyBinding) return false;
  const target = event.target;
  if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA"
    || target.tagName === "SELECT" || target.isContentEditable)) return false;
  if (keyMaps.some((map) => Object.values(map).includes(event.code))) return false;
  switch (event.code) {
    case "BracketLeft": demoSpeed.nudge(-1); break;
    case "BracketRight": demoSpeed.nudge(1); break;
    case "Backslash":
    case "Space": demoSpeed.togglePause(); break;
    case "Period": demoSpeed.frameStep(1); break;
    case "Digit1": demoSpeed.setRate(1); break;
    case "Digit2": demoSpeed.setRate(0.5); break;
    case "Digit3": demoSpeed.setRate(0.25); break;
    case "Digit4": demoSpeed.setRate(0.1); break;
    default: return false;
  }
  demoSpeed.hintUntilMs = performance.now() + DEMO_SPEED_HINT_MS;
  return true;
}

function startNextDemoMatch() {
  if (!demoSession.active || !demoSession.director) return false;
  clearDemoResultTimer();
  cancelFightAnnouncement();
  // v2.9 FLOW: bank the outgoing exhibition's coverage before it is replaced,
  // so the attract cycle is CUMULATIVE — the next time this fighter is
  // featured it leads with the part of its kit the cabinet has not shown yet.
  if (demoSession.choreo) {
    Object.assign(demoSession.coverageCarry, demoSession.choreo.carryover());
  }
  const cycle = demoSession.director.next();
  const picks = cycle.picks.map((id) => roster.findIndex((fighter) => fighter.id === id));
  if (picks.some((index) => index < 0)
    || picks[0] === picks[1]) throw new Error("Demo director produced an invalid matchup.");
  demoSession.cycle = cycle;
  demoSession.matches += 1;
  demoSession.superSide = (cycle.cycle - 1) % 2;
  demoSession.superShown = false;
  $("#attractScores").hidden = true;
  state.mode = "demo";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  state.picks = picks;
  state.locks = [true, true];
  state.stage = cycle.stage;
  $("#demoResultStatus").hidden = true;
  startMatch(true);
  state.fighters[demoSession.superSide].meter = GRIT_RULES.maximum;
  // v2.9 FLOW: a fresh coverage choreographer per exhibition. It works from
  // kit ids (what beginAttack resolves moves through) and knows whether this
  // stage/round actually planned a weapon, so the pickup beat is only chased
  // where one exists. The seed derives from the director's deterministic
  // stream, so the same demo seed replays the same choreography.
  demoSession.choreo = createDemoChoreographer({
    pair: state.fighters.map((fighter) => fighter.kitId),
    stageId: cycle.stage,
    hasStageWeapon: Boolean(state.stageWeapon),
    seed: hashSeed(demoSession.director.snapshot().seed, "choreo", cycle.cycle),
    priorShown: demoSession.coverageCarry,
  });
  const pairKey = demoMatchupKey(...cycle.picks);
  if (!demoSession.pairsSeen.includes(pairKey)) demoSession.pairsSeen.push(pairKey);
  while (demoSession.pairsSeen.length > demoSession.director.snapshot().matchupCount) demoSession.pairsSeen.shift();
  updateHud();
  state.qaManualMode = demoSession.qa;
  setTrack(cycle.track, true);
  updateDemoUi();
  announce(`WATCH DEMO · CYCLE ${cycle.cycle}`, `${state.fighters[0].def.name} VS ${state.fighters[1].def.name}`, 1.2);
  return true;
}

function startDemo({ attract = false, qa = false, seed = null } = {}) {
  if (onlineSession.role) disconnectOnline(true);
  if (demoSession.active) endDemoSession();
  clearIdleDemoTimer();
  if (!attract && !qa) {
    enterImmersiveMode();
    unlockAudio();
  }
  demoSession.active = true;
  demoSession.attract = Boolean(attract);
  demoSession.qa = Boolean(qa);
  // v3.2: a demo always STARTS running. The rate is deliberately kept (it is
  // what `?speed=` set, and it should survive the demo's own match loop), but
  // a pause left latched from a previous session would open the next one
  // frozen with no obvious cause.
  demoSpeed.setPaused(false);
  // v4.0: THE LEGEND'S HOME. The speed transport's key legend used to be armed
  // only by the retired A/B exhibition's entry point, so on its own the demo
  // never announced the transport at all — the keys worked, but the only way
  // to discover them was to already know one and press it. Arming the hint on
  // every demo start puts the legend where the controls are actually useful:
  // nine seconds under the floor line at the top of a WATCH DEMO (and of the
  // attract loop), then out of the way, and any transport key brings it back.
  demoSpeed.hintUntilMs = performance.now() + DEMO_SPEED_HINT_MS;
  // v2.9 FLOW round 2 — SAME-PAGE DETERMINISM. A seeded demo is the QA
  // reproduction path, and every match seed derives from state.matchSerial
  // (see seedMatch), which only ever GROWS across a page's lifetime. A second
  // qa.demo(555) in the same page therefore replayed the same choreography
  // against a DIFFERENT sim stream and diverged (measured: 7 moves vs 5 after
  // 900 steps). Rewinding the serial and the rng streams restores exactly the
  // cold-load starting point, so a cold load stays byte-identical to what it
  // has always been and a same-page repeat now matches it. The attract loop
  // never passes a seed, so nothing about unattended attract changes.
  if (seed !== null) {
    state.matchSerial = 0;
    state.rng.setState(initialSeed);
    state.visualRng.setState(hashSeed(initialSeed, "visual"));
    // The tick domain has to rewind with it. Every frame-relative counter the
    // choreographer and the sim own — decision gaps, beat cooldowns, command
    // history, input buffers — is measured against state.simulationTick, which
    // only ever grows, so a second run starting at tick 3000 diverged from a
    // cold-load run starting at 0 even with identical seeds. Offline the
    // fixed-step clock owns the counter, so both move together (the same pair
    // replay playback rewinds; see loadReplayHeader).
    state.simulationTick = 0;
    simulationClock.tick = 0;
  }
  demoSession.director = createDemoDirector({
    fighterIds: roster.map(({ id }) => id),
    stageIds: Object.keys(stages),
    trackCount: musicTracks.length,
    seed: seed ?? hashSeed(Date.now(), performance.now(), state.rng.nextUint32()),
  });
  document.body.classList.add("demo-active");
  startNextDemoMatch();
  return demoSnapshot();
}

function scheduleNextDemoMatch() {
  if (!demoSession.active) return;
  clearDemoResultTimer();
  $("#demoResultStatus").hidden = false;
  // Release 1.8 GRIND: real-cabinet attract loop — while the idle demo holds
  // its result, the local high-score table takes the screen.
  if (demoSession.attract) {
    const table = renderHighScoreBoard();
    if (table.length) {
      $("#attractScores").hidden = false;
      modeFxDebug.attractScoreBoards += 1;
    }
  }
  demoSession.resultTimer = window.setTimeout(() => {
    demoSession.resultTimer = 0;
    startNextDemoMatch();
  }, DEMO_RESULT_HOLD_MS);
}

function scheduleIdleDemo() {
  clearIdleDemoTimer();
  // Wave 15: CABINET MODE always attracts — a cabinet with the demo switched
  // off is just a dark TV.
  const attracts = state.attractEnabled || state.cabinetMode;
  if (!attracts || demoSession.active || state.screen !== "title" || document.hidden) return;
  demoSession.idleTimer = window.setTimeout(() => {
    demoSession.idleTimer = 0;
    if ((state.attractEnabled || state.cabinetMode) && state.screen === "title" && !document.hidden && !$("#controlsDialog").open) startDemo({ attract: true });
  }, DEMO_IDLE_DELAY_MS);
}

function noteUserActivity() {
  if (demoSession.active) return exitDemo();
  if (state.screen === "title") scheduleIdleDemo();
  return false;
}

function setOnlineStatus(kind, detail) {
  const titles = {
    idle: "ROOM SYSTEM READY",
    signaling: "SIGNALING LOCKED",
    waiting: "PRIVATE ROOM OPEN",
    connecting: "NEGOTIATING P2P",
    connected: "DIRECT LINK READY",
    error: "LINK ERROR",
    closed: "ROOM CLOSED",
  };
  onlineSession.status = kind;
  const panel = $("#onlineStatus");
  panel.className = `online-status ${kind}`;
  $("#onlineStatusTitle").textContent = titles[kind] || "PRIVATE ROOM";
  $("#onlineStatusDetail").textContent = detail || "Create a room or open a private invite.";
}

function setOnlineError(message = "") {
  const node = $("#onlineError");
  node.textContent = message;
  node.hidden = !message;
}

function updateOnlineSeats() {
  const hostPresent = onlineSession.role === "host" || onlineSession.peers.has("host");
  const guestPresent = onlineSession.role === "guest" || onlineSession.peers.has("guest");
  for (const [role, present] of [["host", hostPresent], ["guest", guestPresent]]) {
    const node = $(`#online${role[0].toUpperCase()}${role.slice(1)}Seat`);
    node.classList.toggle("occupied", present);
    node.querySelector("em").textContent = present ? (onlineSession.role === role ? "YOU" : "CONNECTED") : "WAITING";
  }
}

const ONLINE_RESUME_KEY = "final-blow-online-resume-v1";
const onlineFighterIds = new Set(roster.map(({ id }) => id));

function onlineLocalSide() {
  return onlineSession.role === "guest" ? 1 : 0;
}

function onlineRemoteRole() {
  return onlineSession.role === "host" ? "guest" : "host";
}

function safeSessionWrite(value) {
  try {
    if (value === null) sessionStorage.removeItem(ONLINE_RESUME_KEY);
    else sessionStorage.setItem(ONLINE_RESUME_KEY, JSON.stringify(value));
  } catch {
    // Private browsing can deny session storage; the in-memory room remains usable.
  }
}

function persistOnlineResume(includeState = false) {
  if (!onlineSession.credentials || !onlineSession.roomId) return;
  const resume = {
    credentials: onlineSession.credentials,
    inviteUrl: onlineSession.inviteUrl,
    lobby: onlineSession.lobby,
    matchConfig: onlineSession.matchConfig,
    matchActive: onlineSession.matchActive,
    screen: state.screen,
    // R2.1 STREETS: the running first-to-N set + the loser-picks-stage latch
    // survive a reload with the room.
    set: {
      length: onlineSession.set.length,
      scores: [...onlineSession.set.scores],
      history: onlineSession.set.history.map((entry) => ({ ...entry })),
    },
    lastLoserRole: onlineSession.lastLoserRole,
    savedAt: Date.now(),
  };
  if (includeState && onlineSession.rollback && state.screen === "fight") {
    const sync = onlineSession.rollback.exportSync();
    resume.rollback = { frame: sync.frame, state: serializeRollbackState(sync.state) };
  }
  safeSessionWrite(resume);
}

function readOnlineResume() {
  try {
    const value = JSON.parse(sessionStorage.getItem(ONLINE_RESUME_KEY));
    if (!value?.credentials?.roomId || !value.credentials.token) return null;
    if (Number(value.credentials.expiresAt) <= Date.now()) return null;
    return value;
  } catch {
    return null;
  }
}

function setOnlineInterruption(visible, title = "RECONNECTING", detail = "Holding the match while the encrypted link returns…") {
  const panel = $("#onlineInterruption");
  panel.hidden = !visible;
  $("#onlineInterruptionTitle").textContent = title;
  $("#onlineInterruptionDetail").textContent = detail;
}

function updateOnlineHud(kind = "sync") {
  const panel = $("#onlineHud");
  const metrics = onlineSession.rollback?.metrics();
  panel.hidden = !(state.mode === "online" && ["fight", "result"].includes(state.screen));
  panel.classList.toggle("warning", kind === "warning" || onlineSession.networkPaused);
  panel.classList.toggle("error", kind === "error");
  $("#onlineHudState").textContent = onlineSession.networkPaused ? "LINK HOLD"
    : kind === "error" ? "DESYNC"
      : kind === "warning" ? "PREDICTING" : "ROLLBACK SYNC";
  $("#onlineHudPing").textContent = onlineSession.latency === null ? "— MS" : `${onlineSession.latency} MS`;
  $("#onlineHudDelay").textContent = `${metrics?.inputDelay ?? onlineSession.matchConfig?.inputDelay ?? 0}F DELAY`;
  $("#onlineHudRollbacks").textContent = `${metrics?.rollbacks || 0} RB`;
  // R2.1 STREETS: running set score + the signal-bars connection meter.
  const setScore = $("#onlineHudSet");
  const liveSet = onlineSession.set.length > 1 && onlineSession.matchConfig;
  setScore.hidden = !liveSet;
  if (liveSet) setScore.textContent = `SET ${onlineSession.set.scores[0]}–${onlineSession.set.scores[1]} · FT${onlineSession.set.length}`;
  renderConnMeter(metrics);
}

// ===========================================================================
// R2.1 STREETS — CONNECTION METER. Pure meta: EWMA ping/jitter from the peer
// latency callback, packet cadence from receiveOnlineInput, recent rollback
// behaviour from RollbackSession.metrics(). connMeter.forced is the QA stub.
// ===========================================================================

function connMeterSample() {
  if (connMeter.forced) return { ...connMeter.forced };
  return {
    pingMs: connMeter.ewmaPing ?? (onlineSession.latency === null ? null : onlineSession.latency),
    jitterMs: connMeter.ewmaJitter,
    rollbackDepth: connMeter.recentRollbackDepth,
    stalledRecent: connMeter.recentStalled,
  };
}

function feedConnMeterLatency(milliseconds) {
  if (!Number.isFinite(milliseconds)) return;
  if (Number.isFinite(connMeter.lastPing)) {
    connMeter.ewmaJitter = ewma(connMeter.ewmaJitter, Math.abs(milliseconds - connMeter.lastPing));
  }
  connMeter.lastPing = milliseconds;
  connMeter.ewmaPing = ewma(connMeter.ewmaPing, milliseconds);
}

function renderConnMeter(metrics = null) {
  const meter = $("#connMeter");
  if (!meter) return;
  const sample = connMeterSample();
  const rating = connectionTier(sample);
  connMeter.tier = rating.tier;
  meter.dataset.grade = rating.grade;
  $("#connMeterLabel").textContent = rating.label;
  meter.querySelectorAll("i").forEach((bar, index) => {
    bar.classList.toggle("lit", index < 4 - rating.tier);
  });
  // One-shot degradation toast per worsening step; re-arms on recovery.
  if (rating.tier >= 2 && rating.tier > connMeter.toastedTier && state.screen === "fight") {
    connMeter.toastedTier = rating.tier;
    netFxDebug.connToasts += 1;
    showConnToast(rating.tier >= 3
      ? "CONNECTION ROUGH · PREDICTION RUNNING DEEP"
      : "CONNECTION SHAKY · EXPECT SMALL ROLLBACKS");
  } else if (rating.tier < connMeter.toastedTier) {
    connMeter.toastedTier = rating.tier;
  }
  const detail = $("#connMeterDetail");
  detail.hidden = !connMeter.detail;
  if (connMeter.detail) {
    const stats = metrics || onlineSession.rollback?.metrics() || null;
    detail.innerHTML = [
      `PING ${sample.pingMs === null || sample.pingMs === undefined ? "—" : `${Math.round(sample.pingMs)}MS`}`,
      `JITTER ${Number.isFinite(sample.jitterMs) ? `${Math.round(sample.jitterMs)}MS` : "—"}`,
      `DELAY ${stats?.inputDelay ?? onlineSession.matchConfig?.inputDelay ?? 0}F`,
      `RB DEPTH ${sample.rollbackDepth || 0}F`,
      `STALLS ${sample.stalledRecent || 0}`,
      `LINK ${rating.label}`,
    ].map((row) => `<span>${row}</span>`).join("");
  }
}

let connToastTimer = 0;

function showConnToast(text) {
  const toast = $("#connToast");
  if (!toast) return;
  toast.textContent = text;
  toast.hidden = false;
  toast.classList.remove("out");
  window.clearTimeout(connToastTimer);
  connToastTimer = window.setTimeout(() => { toast.hidden = true; }, 3200);
}

// Pre-match 3-2-1 sync countdown: wall-clock DOM beats over the deterministic
// intro phase. Presentation only — the rollback session starts regardless.
let syncCountdownTimers = [];

function beginSyncCountdown() {
  clearSyncCountdown();
  const node = $("#syncCountdown");
  if (!node) return;
  netFxDebug.readyChecks += 1;
  const beats = ["3", "2", "1"];
  beats.forEach((beat, index) => {
    syncCountdownTimers.push(window.setTimeout(() => {
      // Only ever scheduled from an online match start (or the QA hook) — the
      // fight-screen gate alone keeps stray beats off the menus.
      if (state.screen !== "fight") return;
      node.textContent = beat;
      node.hidden = false;
      restartCssAnimation(node, "beat");
    }, 250 + index * 520));
  });
  syncCountdownTimers.push(window.setTimeout(() => { node.hidden = true; }, 250 + beats.length * 520));
}

function clearSyncCountdown() {
  for (const timer of syncCountdownTimers) window.clearTimeout(timer);
  syncCountdownTimers = [];
  const node = $("#syncCountdown");
  if (node) node.hidden = true;
}

// Wave 16: the Commissioner appears in the online fighter list only while
// BOTH peers have him unlocked (the lobby handshake carries the flags). A
// peer who loses eligibility mid-lobby is snapped back to DeathBlow.
function syncOnlineCommissionerOption() {
  const select = $("#onlineFighterSelect");
  if (!select) return;
  const eligible = commissionerUnlocked() && onlineSession.lobby.remoteCommissionerUnlocked;
  let option = select.querySelector('option[value="commissioner"]');
  if (eligible && !option) {
    option = document.createElement("option");
    option.value = ARCADE_BOSS_ID;
    option.textContent = "THE COMMISSIONER";
    select.append(option);
  } else if (!eligible && option) {
    option.remove();
    if (onlineSession.lobby.localFighter === ARCADE_BOSS_ID) {
      onlineSession.lobby.localFighter = "deathblow";
      onlineSession.lobby.localReady = false;
      sendOnlineLobbyState();
    }
  }
}

function updateOnlineMatchSetup() {
  const connected = Boolean(onlineSession.peer?.connected);
  const setup = $("#onlineMatchSetup");
  setup.hidden = !connected || onlineSession.matchActive;
  if (!connected) return;
  const lobby = onlineSession.lobby;
  $("#onlineFighterSelect").value = lobby.localFighter;
  $("#onlineOpponentFighter").textContent = onlineFighterIds.has(lobby.remoteFighter)
    ? `${roster.find(({ id }) => id === lobby.remoteFighter).name}${lobby.remotePalette === 1 ? " · ALT" : ""}`
    : lobby.remoteFighterRaw === ARCADE_BOSS_ID
      ? "THE COMMISSIONER · LOCKED HERE"
      : "CHOOSING…";
  const paletteSelect = $("#onlinePaletteSelect");
  if (paletteSelect) paletteSelect.value = String(lobby.localPalette);
  // R2.1 STREETS: MK-style loser-picks-stage. The stage cursor belongs to the
  // last match's loser once both peers speak QoL; otherwise the 2.3 host rule.
  const stageOwner = onlineStagePickerRole();
  $("#onlineStageSelect").value = lobby.stage;
  $("#onlineStageSelect").disabled = onlineSession.role !== stageOwner;
  const stageOwnerNote = $("#onlineStageOwner");
  if (stageOwnerNote) {
    stageOwnerNote.textContent = onlineSession.lastLoserRole && lobby.remoteQol >= 1
      ? (stageOwner === onlineSession.role ? "LOSER'S CALL · YOU PICK" : "LOSER'S CALL · OPPONENT PICKS")
      : (stageOwner === onlineSession.role ? "HOST PICKS" : "HOST'S CALL");
  }
  $("#onlineDelaySelect").value = lobby.delayChoice;
  // First-to-N set length: host-picked, mirrored to the guest, disabled
  // entirely against a 2.3 peer (the config would fall back to one match).
  const setSelect = $("#onlineSetSelect");
  if (setSelect) {
    setSelect.value = lobby.setChoice;
    setSelect.disabled = onlineSession.role !== "host" || lobby.remoteQol < 1;
    setSelect.title = lobby.remoteQol < 1 ? "OPPONENT'S BUILD PREDATES SETS" : "";
  }
  const readyButton = $("#onlineReadyButton");
  readyButton.disabled = !connected;
  readyButton.textContent = lobby.localReady ? "READY LOCKED · CANCEL" : "READY FOR ROLLBACK";
  // Pre-ready connection check: measured RTT + the AUTO delay it would tune.
  const connBadge = $("#lobbyConnBadge");
  if (connBadge) {
    const ping = connMeter.forced?.pingMs ?? connMeter.ewmaPing ?? onlineSession.latency;
    if (Number.isFinite(ping)) {
      const rating = connectionTier(connMeterSample());
      connBadge.hidden = false;
      connBadge.dataset.grade = rating.grade;
      connBadge.textContent = `CONNECTION ${rating.label} · ${Math.round(ping)}MS · AUTO = ${recommendedInputDelay(ping)}F`;
    } else {
      connBadge.hidden = false;
      connBadge.dataset.grade = "";
      connBadge.textContent = "CONNECTION · MEASURING…";
    }
  }
  setup.classList.toggle("ready", lobby.localReady && lobby.remoteReady);
  $("#onlineMatchStatus").textContent = lobby.localReady && lobby.remoteReady
    ? onlineSession.role === "host" ? "BOTH READY · LAUNCHING MATCH" : "BOTH READY · HOST IS LAUNCHING"
    : lobby.localReady ? "YOU ARE READY · WAITING FOR OPPONENT"
      : lobby.remoteReady ? "OPPONENT READY · LOCK YOUR FIGHTER" : "CHOOSE, TUNE DELAY, THEN READY UP";
}

// Which seat owns the lobby stage cursor right now (see stagePickerRole).
function onlineStagePickerRole() {
  return stagePickerRole({
    localQol: ONLINE_QOL_LEVEL,
    remoteQol: onlineSession.lobby.remoteQol,
    lastLoserRole: onlineSession.lastLoserRole,
  });
}

function sendOnlineControl(message) {
  return onlineSession.peer?.sendControl({ protocol: "final-blow-1.0d", ...message }) || false;
}

function sendOnlineLobbyState() {
  if (!onlineSession.peer?.connected) return false;
  const lobby = onlineSession.lobby;
  return sendOnlineControl({
    type: "lobby-state",
    fighter: lobby.localFighter,
    stage: lobby.stage,
    delayChoice: lobby.delayChoice,
    controlStyle: state.controlStyle,
    ready: lobby.localReady,
    // Wave 16: color pick + Commissioner eligibility handshake.
    palette: lobby.localPalette,
    commissioner: commissionerUnlocked(),
    // R2.1 STREETS: versioned QoL extension. Older peers ignore all three;
    // sanitizeLobbyQol on the receive side defaults them to 2.3 behaviour.
    qol: ONLINE_QOL_LEVEL,
    ping: onlineSession.latency ?? undefined,
    setLength: normalizeSetLength(lobby.setChoice),
  });
}

function tickOnlineExpiry() {
  if (!onlineSession.expiresAt) return;
  const remaining = Math.max(0, onlineSession.expiresAt - Date.now());
  const minutes = Math.floor(remaining / 60_000);
  const seconds = Math.floor((remaining % 60_000) / 1000);
  $("#onlineExpiry").textContent = `EXPIRES IN ${minutes}:${String(seconds).padStart(2, "0")}`;
  if (remaining === 0) {
    if (onlineSession.peer?.connected) {
      $("#onlineExpiry").textContent = "SIGNALING EXPIRED · P2P ACTIVE";
      return;
    }
    disconnectOnline(false);
    setOnlineStatus("closed", "This private room expired. Create a new room to continue.");
  }
}

function resetOnlineUi() {
  $("#onlineActions").hidden = false;
  $("#onlineRoomDetails").hidden = true;
  $("#onlineCreateButton").disabled = false;
  $("#onlineJoinButton").disabled = false;
  $("#onlineInviteLink").value = "";
  $("#onlineInviteInput").value = "";
  $("#onlineCopyButton").hidden = false;
  $("#onlineLatency").textContent = "NEGOTIATING";
  $("#onlineMatchSetup").hidden = true;
  $("#onlineRematchStatus").hidden = true;
  $("#onlineHud").hidden = true;
  setOnlineInterruption(false);
  setOnlineError();
  updateOnlineSeats();
}

function disconnectOnline(resetStatus = true, { clearStored = true } = {}) {
  onlineSession.generation += 1;
  onlineSession.peerGeneration += 1;
  if (onlineSession.expiryTimer) clearInterval(onlineSession.expiryTimer);
  if (onlineSession.reconnectTimer) clearTimeout(onlineSession.reconnectTimer);
  onlineSession.expiryTimer = 0;
  onlineSession.reconnectTimer = 0;
  onlineSession.stopUiSignal?.();
  onlineSession.stopUiSignal = null;
  onlineSession.peer?.close();
  onlineSession.signaling?.close();
  onlineSession.peer = null;
  onlineSession.signaling = null;
  onlineSession.role = null;
  onlineSession.roomId = "";
  onlineSession.expiresAt = 0;
  onlineSession.inviteUrl = "";
  onlineSession.peers.clear();
  onlineSession.latency = null;
  onlineSession.credentials = null;
  // Wave 19: QR, watch seats and any Street List posting die with the room.
  onlineSession.watchToken = "";
  onlineQrState.text = "";
  onlineQrState.matrix = null;
  spectateHost.watchers = 0;
  spectateHost.wantsStream = false;
  spectateHost.lastSentFrame = 0;
  spectateHost.headerSentFor = "";
  setStreetPostStatus("", false);
  onlineSession.reconnectAttempts = 0;
  onlineSession.reconnecting = false;
  onlineSession.rollback = null;
  onlineSession.matchConfig = null;
  onlineSession.matchActive = false;
  onlineSession.networkPaused = false;
  onlineSession.localSuspended = false;
  onlineSession.remoteSuspended = false;
  onlineSession.awaitingResume = false;
  onlineSession.rematchVotes.clear();
  onlineSession.remoteChecksums.clear();
  onlineSession.checksumMismatches = 0;
  onlineSession.lastChecksumSentFrame = -1;
  onlineSession.lastPersistedFrame = -1;
  onlineSession.lobby.localReady = false;
  onlineSession.lobby.remoteReady = false;
  // R2.1 STREETS: the set, the stage-cursor latch, the peer's QoL level and
  // the connection meter all die with the room.
  onlineSession.set = createSetState(1);
  onlineSession.lastLoserRole = "";
  onlineSession.lobby.remoteQol = 0;
  onlineSession.lobby.remotePing = null;
  onlineSession.lobby.remoteSetLength = 1;
  onlineSession.lobby.setChoice = "1";
  resetConnMeter();
  clearSyncCountdown();
  resetReplayRecorder();
  if (clearStored) safeSessionWrite(null);
  resetOnlineUi();
  if (resetStatus) setOnlineStatus("idle", "Create a room or open a private invite.");
}

function resetConnMeter() {
  connMeter.ewmaPing = null;
  connMeter.ewmaJitter = null;
  connMeter.lastPing = null;
  connMeter.lastPacketAt = 0;
  connMeter.ewmaGapMs = null;
  connMeter.tier = 0;
  connMeter.toastedTier = 0;
  connMeter.detail = false;
  connMeter.baseline = null;
  connMeter.recentRollbackDepth = 0;
  connMeter.recentStalled = 0;
  connMeter.forced = null;
}

function renderOnlineRoom() {
  $("#onlineActions").hidden = true;
  $("#onlineRoomDetails").hidden = false;
  $("#onlineFingerprint").textContent = roomFingerprint(onlineSession.roomId);
  $("#onlineInviteLink").value = onlineSession.role === "host" ? onlineSession.inviteUrl : "PRIVATE INVITE AUTHENTICATED";
  $("#onlineCopyButton").hidden = onlineSession.role !== "host";
  renderInviteQr();
  renderStreetPostRow();
  updateOnlineSeats();
  updateOnlineMatchSetup();
  tickOnlineExpiry();
}

// --- Wave 19: QR-code + native-share invites --------------------------------
// The invite URL (token in the fragment, as always) painted as a self-drawn
// QR on the host's room card. Pure canvas: no external fetches, no library.

function paintQrToCanvas(canvasNode, code) {
  const context = canvasNode.getContext("2d");
  const quiet = 4;
  const cells = code.size + quiet * 2;
  // Crisp integer scale; the CSS box scales it to layout size.
  const scale = Math.max(2, Math.floor(196 / cells));
  canvasNode.width = cells * scale;
  canvasNode.height = cells * scale;
  context.fillStyle = "#f4ecd9";
  context.fillRect(0, 0, canvasNode.width, canvasNode.height);
  context.fillStyle = "#05070c";
  for (let row = 0; row < code.size; row += 1) {
    for (let col = 0; col < code.size; col += 1) {
      if (code.modules[row][col]) {
        context.fillRect((col + quiet) * scale, (row + quiet) * scale, scale, scale);
      }
    }
  }
}

function renderInviteQr() {
  const block = $("#onlineQrBlock");
  const isHost = onlineSession.role === "host" && Boolean(onlineSession.inviteUrl);
  block.hidden = !isHost;
  $("#onlineShareButton").hidden = !isHost || typeof navigator.share !== "function";
  $("#onlineWatchLinkButton").hidden = !isHost || !onlineSession.watchToken;
  if (!isHost) return;
  if (onlineQrState.text !== onlineSession.inviteUrl) {
    try {
      const code = encodeQr(onlineSession.inviteUrl);
      onlineQrState.text = onlineSession.inviteUrl;
      onlineQrState.version = code.version;
      onlineQrState.size = code.size;
      onlineQrState.matrix = code.modules;
      netFxDebug.qrRenders += 1;
    } catch {
      block.hidden = true;
      return;
    }
  }
  paintQrToCanvas($("#onlineQrCanvas"), { size: onlineQrState.size, modules: onlineQrState.matrix });
}

async function shareOnlineInvite() {
  if (!onlineSession.inviteUrl) return;
  netFxDebug.shareInvites += 1;
  if (typeof navigator.share === "function") {
    try {
      await navigator.share({
        title: "FINAL BLOW · PRIVATE ROOM",
        text: "Answer the challenge — this invite seats you as my opponent.",
        url: onlineSession.inviteUrl,
      });
      return;
    } catch {
      // Cancelled or unsupported target — fall back to the clipboard below.
    }
  }
  await copyOnlineInvite();
}

async function copyOnlineWatchLink() {
  if (!onlineSession.watchToken || !onlineSession.roomId) return;
  const watchUrl = buildWatchUrl({ roomId: onlineSession.roomId, watchToken: onlineSession.watchToken });
  try {
    await navigator.clipboard.writeText(watchUrl);
  } catch {
    return;
  }
  netFxDebug.watchLinksCopied += 1;
  const button = $("#onlineWatchLinkButton");
  button.textContent = "WATCH LINK COPIED";
  setTimeout(() => { button.textContent = "COPY WATCH LINK"; }, 1400);
}

function receiveOnlineSignal(message) {
  if (message.type === "welcome") {
    onlineSession.expiresAt = Number(message.expiresAt) || onlineSession.expiresAt;
    if (onlineSession.credentials) onlineSession.credentials.expiresAt = onlineSession.expiresAt;
    onlineSession.peers = new Set((message.peers || []).filter((role) => role === "host" || role === "guest"));
    spectateHost.watchers = Math.max(0, Number(message.watchers) || 0);
    updateOnlineSeats();
    tickOnlineExpiry();
    persistOnlineResume(false);
  } else if (message.type === "peer" && ["host", "guest"].includes(message.role)) {
    if (message.state === "joined") onlineSession.peers.add(message.role);
    else onlineSession.peers.delete(message.role);
    updateOnlineSeats();
  } else if (message.type === "peer" && message.role === "watch") {
    // Wave 19: watcher headcount (host bookkeeping only — old clients filter
    // this role out entirely).
    spectateHost.watchers = Math.max(0, spectateHost.watchers + (message.state === "joined" ? 1 : -1));
    if (spectateHost.watchers === 0) spectateHost.wantsStream = false;
  } else if (message.type === "watch-hello" && message.from === "watch" && onlineSession.role === "host") {
    // A watcher asked for the stream: send the header plus a catch-up resend
    // from wherever their buffer stands. Existing watchers dedupe overlap.
    spectateHost.wantsStream = true;
    sendSpectateHeader();
    sendSpectateCatchup(Math.max(0, Number(message.have) || 0));
  }
}

// --- Wave 19: host-side spectate relay --------------------------------------
// The host mirrors its CONFIRMED input stream (the wave-18 recorder map) over
// the signaling socket: one 60-frame batch per second steady-state, chunked
// catch-up for late joiners. Watchers replay the identical deterministic sim.

function sendSpectate(message) {
  return Boolean(onlineSession.signaling?.send(message));
}

function sendSpectateHeader() {
  const config = onlineSession.matchConfig;
  if (onlineSession.role !== "host" || !onlineSession.matchActive || !config) return false;
  const header = buildSpectateHeader(config, { gameVersion: GAME_VERSION, protocol: ROLLBACK_PROTOCOL_VERSION });
  if (!header || !sendSpectate(header)) return false;
  spectateHost.headerSentFor = config.matchId;
  netFxDebug.spectateHeadersSent += 1;
  return true;
}

function sendSpectateRange(start, endExclusive) {
  const config = onlineSession.matchConfig;
  const map = replayRecorder.onlineFrames;
  if (!config || !map) return;
  for (const chunk of planSpectateChunks(start, endExclusive - start)) {
    const range = collectConfirmedRange(map, chunk.start, chunk.start + chunk.count);
    if (!range) return; // hole — that stretch is not confirmed yet
    const batch = encodeSpectateBatch(config.matchId, chunk.start, range.frames0, range.frames1);
    if (!batch || !sendSpectate(batch)) return;
    spectateHost.lastSentFrame = Math.max(spectateHost.lastSentFrame, chunk.start + chunk.count);
    netFxDebug.spectateBatchesSent += 1;
    netFxDebug.spectateFramesSent += chunk.count;
  }
}

function sendSpectateCatchup(fromFrame) {
  if (onlineSession.role !== "host" || !onlineSession.matchActive) return;
  if (spectateHost.lastSentFrame > fromFrame) sendSpectateRange(fromFrame, spectateHost.lastSentFrame);
}

function maybePumpSpectate(metrics) {
  if (onlineSession.role !== "host" || !spectateHost.wantsStream || spectateHost.watchers <= 0) return;
  const config = onlineSession.matchConfig;
  if (!config || !replayRecorder.active || replayRecorder.kind !== "online") return;
  if (spectateHost.headerSentFor !== config.matchId && !sendSpectateHeader()) return;
  const confirmed = Math.min(metrics.frame, metrics.confirmedRemoteFrame + 1, metrics.acknowledgedLocalFrame + 1);
  const target = Math.floor(confirmed / SPECTATE_BATCH_FRAMES) * SPECTATE_BATCH_FRAMES;
  if (target > spectateHost.lastSentFrame) sendSpectateRange(spectateHost.lastSentFrame, target);
}

// Called from resolveMatchResult's meta path BEFORE the recorder is banked:
// flush every remaining confirmed frame, then close the broadcast with the
// outcome so watchers land on a clean end card.
function flushSpectateAtResult(winner) {
  if (onlineSession.role !== "host" || !spectateHost.wantsStream) return;
  const config = onlineSession.matchConfig;
  const map = replayRecorder.onlineFrames;
  if (!config || !map || replayRecorder.kind !== "online") return;
  if (spectateHost.headerSentFor !== config.matchId) sendSpectateHeader();
  let last = -1;
  for (const frame of map.keys()) last = Math.max(last, frame);
  if (last + 1 > spectateHost.lastSentFrame) sendSpectateRange(spectateHost.lastSentFrame, last + 1);
  if (sendSpectate(encodeSpectateEnd(config.matchId, { reason: "ended", winner }))) {
    netFxDebug.spectateEnds += 1;
  }
  spectateHost.lastSentFrame = 0;
  spectateHost.headerSentFor = "";
}

function scheduleOnlineReconnect(detail = "Encrypted peer link interrupted.") {
  if (onlineSession.reconnecting || !onlineSession.credentials || Date.now() >= onlineSession.expiresAt) return;
  onlineSession.reconnecting = true;
  onlineSession.networkPaused = onlineSession.matchActive;
  onlineSession.reconnectAttempts += 1;
  setOnlineInterruption(onlineSession.matchActive, "RECONNECTING", `${detail} · ATTEMPT ${onlineSession.reconnectAttempts} / 5`);
  updateOnlineHud("warning");
  setOnlineStatus("connecting", `Reconnecting encrypted seat · attempt ${onlineSession.reconnectAttempts} / 5…`);
  if (onlineSession.reconnectAttempts > 5) {
    setOnlineInterruption(true, "LINK LOST", "The room could not reconnect. Return to the title and create a new invite.");
    setOnlineStatus("error", "Reconnect window exhausted.");
    return;
  }
  onlineSession.peerGeneration += 1;
  onlineSession.stopUiSignal?.();
  onlineSession.stopUiSignal = null;
  onlineSession.peer?.close();
  onlineSession.signaling?.close();
  onlineSession.peer = null;
  onlineSession.signaling = null;
  onlineSession.reconnectTimer = setTimeout(async () => {
    onlineSession.reconnectTimer = 0;
    try {
      await connectOnlineTransport();
    } catch (error) {
      onlineSession.reconnecting = false;
      scheduleOnlineReconnect(error instanceof Error ? error.message : "Reconnect failed.");
    }
  }, 450 + onlineSession.reconnectAttempts * 350);
}

function beginOnlineResumeHandshake() {
  if (!onlineSession.matchActive || !onlineSession.rollback) return;
  onlineSession.networkPaused = true;
  onlineSession.awaitingResume = true;
  setOnlineInterruption(true, "RESYNCHRONIZING", "Verifying the deterministic match state…");
  const metrics = onlineSession.rollback.metrics();
  sendOnlineControl({
    type: "resume-hello",
    matchId: onlineSession.matchConfig?.matchId,
    frame: metrics.frame,
    checksum: onlineSession.rollback.checksumAt(metrics.frame),
  });
  updateOnlineHud("warning");
}

async function connectOnlineTransport() {
  const credentials = onlineSession.credentials;
  if (!credentials) throw new Error("Private room credentials are unavailable.");
  const generation = onlineSession.generation;
  const peerGeneration = ++onlineSession.peerGeneration;
  const signaling = await connectPrivateRoom(credentials);
  if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) {
    signaling.close();
    return;
  }
  onlineSession.signaling = signaling;
  onlineSession.peer = new FinalBlowPeer({
    role: onlineSession.role,
    signaling,
    onStatus(kind, detail) {
      if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) return;
      if (kind === "connected") {
        // Wave 9: fresh lobby link -> "opponent connected"; a reconnect
        // outside a live match resolves here too -> "connection recovered"
        // (mid-match recovery announces from completeOnlineResume instead).
        const wasReconnecting = onlineSession.reconnecting || onlineSession.reconnectAttempts > 0;
        onlineSession.reconnectAttempts = 0;
        onlineSession.reconnecting = false;
        onlineSession.peers.add(onlineRemoteRole());
        setOnlineStatus("connected", onlineSession.matchActive ? "Direct link restored. Verifying rollback state…" : detail);
        updateOnlineSeats();
        updateOnlineMatchSetup();
        if (onlineSession.matchActive) beginOnlineResumeHandshake();
        else {
          sendOnlineLobbyState();
          announcerOnlineMoment(wasReconnecting ? "recovered" : "connected");
        }
        persistOnlineResume(false);
        return;
      }
      if (["error", "closed"].includes(kind) || (kind === "waiting" && onlineSession.matchActive)) {
        scheduleOnlineReconnect(detail);
        return;
      }
      setOnlineStatus(kind, detail);
    },
    onLatency(milliseconds) {
      if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) return;
      onlineSession.latency = milliseconds;
      // R2.1 STREETS: EWMA ping + jitter feed for the connection meter, and
      // the lobby's pre-ready connection line.
      feedConnMeterLatency(milliseconds);
      $("#onlineLatency").textContent = `${milliseconds} MS · ENCRYPTED`;
      updateOnlineHud();
      if (!onlineSession.matchActive) updateOnlineMatchSetup();
    },
    onControl(message) {
      if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) return;
      receiveOnlineControl(message);
    },
    onInput(packet) {
      if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) return;
      receiveOnlineInput(packet);
    },
  });
  onlineSession.stopUiSignal = signaling.onMessage(receiveOnlineSignal);
  signaling.onClose(({ code, reason }) => {
    if (generation !== onlineSession.generation || peerGeneration !== onlineSession.peerGeneration) return;
    if (onlineSession.peer?.connected) return;
    if (code === 4001) setOnlineStatus("closed", "Private signaling room expired.");
    else scheduleOnlineReconnect(reason || "Private room signaling closed.");
  });
}

async function beginOnlineConnection({ roomId, role, token, guestToken = "", watchToken = "", expiresAt = 0 }) {
  // Wave 19: a watch-link invite opens the read-only spectator flow instead.
  if (role === "watch") {
    return beginSpectatorSession({ roomId, token, expiresAt });
  }
  disconnectOnline(false, { clearStored: false });
  state.mode = "online";
  onlineSession.role = role;
  onlineSession.roomId = roomId;
  onlineSession.expiresAt = Number(expiresAt) || Date.now() + 15 * 60_000;
  onlineSession.inviteUrl = role === "host" ? buildInviteUrl({ roomId, guestToken }) : "";
  onlineSession.watchToken = role === "host" ? String(watchToken || "") : "";
  onlineSession.credentials = { roomId, role, token, guestToken, watchToken: onlineSession.watchToken, expiresAt: onlineSession.expiresAt };
  onlineSession.lobby.localFighter = role === "host" ? "deathblow" : "jez";
  onlineSession.lobby.remoteFighter = role === "host" ? "jez" : "deathblow";
  onlineSession.lobby.localReady = false;
  onlineSession.lobby.remoteReady = false;
  onlineSession.peers.add(role);
  renderOnlineRoom();
  setOnlineError();
  setOnlineStatus("signaling", "Authenticating the private room seat…");
  persistOnlineResume(false);
  try {
    await connectOnlineTransport();
    onlineSession.expiryTimer = setInterval(tickOnlineExpiry, 1000);
  } catch (error) {
    onlineSession.peer?.close();
    onlineSession.signaling?.close();
    onlineSession.peer = null;
    onlineSession.signaling = null;
    const message = error instanceof Error ? error.message : "Could not open private room.";
    setOnlineError(message);
    setOnlineStatus("error", message);
    if (!onlineSession.reconnecting) scheduleOnlineReconnect(message);
  }
}

async function resumeStoredOnlineConnection(resume) {
  const credentials = resume?.credentials;
  if (!credentials || !["host", "guest"].includes(credentials.role)) return false;
  disconnectOnline(false, { clearStored: false });
  state.mode = "online";
  onlineSession.role = credentials.role;
  onlineSession.roomId = credentials.roomId;
  onlineSession.expiresAt = Number(credentials.expiresAt) || 0;
  onlineSession.credentials = cloneRollbackValue(credentials);
  onlineSession.inviteUrl = credentials.role === "host" ? String(resume.inviteUrl || "") : "";
  onlineSession.watchToken = credentials.role === "host" ? String(credentials.watchToken || "") : "";
  Object.assign(onlineSession.lobby, resume.lobby || {});
  onlineSession.peers.add(credentials.role);
  // R2.1 STREETS: restore the room's set + stage latch (sanitized — the
  // stored blob is only as trusted as any other message).
  onlineSession.set = sanitizeSetSync(resume.set, resume.set?.length ?? 1);
  onlineSession.lastLoserRole = ["host", "guest"].includes(resume.lastLoserRole) ? resume.lastLoserRole : "";
  if (resume.matchActive && validOnlineMatchConfig(resume.matchConfig)) {
    startOnlineMatch(resume.matchConfig);
    // startOnlineMatch re-adopted the config's match-start snapshot; the
    // persisted scores are at least as fresh.
    onlineSession.set = sanitizeSetSync(resume.set, resume.set?.length ?? 1);
    if (resume.rollback?.state && Number.isInteger(resume.rollback.frame)) {
      onlineSession.rollback.importSync({
        frame: resume.rollback.frame,
        state: parseRollbackState(resume.rollback.state),
      });
      syncRollbackPresentation();
    }
    if (resume.screen === "result") {
      const winner = state.rounds[0] > state.rounds[1] ? 0 : 1;
      showResult(winner);
    }
    onlineSession.networkPaused = true;
    onlineSession.reconnecting = true;
    setOnlineInterruption(true, "RESTORING MATCH", "Reopening the private seat and requesting verified host state…");
  } else {
    showScreen("online");
    renderOnlineRoom();
  }
  setOnlineStatus("connecting", "Restoring the private room seat…");
  try {
    await connectOnlineTransport();
    onlineSession.expiryTimer = setInterval(tickOnlineExpiry, 1000);
    return true;
  } catch (error) {
    onlineSession.reconnecting = false;
    scheduleOnlineReconnect(error instanceof Error ? error.message : "Stored room reconnect failed.");
    return false;
  }
}

function openOnlineLobby() {
  enterImmersiveMode();
  unlockAudio();
  state.mode = "online";
  showScreen("online");
  if (pendingOnlineInvite) {
    $("#onlineInviteInput").value = location.href;
    setOnlineStatus("waiting", "Private invite detected. Press Join Private Room.");
  }
  // Wave 19: scan the Street List on entry (fire-and-forget; the panel shows
  // its own status either way). QA stubs skip the network entirely.
  if (!streetListUi.stubbed) refreshStreetList();
}

async function createOnlineRoom() {
  setOnlineError();
  $("#onlineCreateButton").disabled = true;
  setOnlineStatus("connecting", "Creating an expiring two-seat room…");
  try {
    const room = await createPrivateRoom();
    await beginOnlineConnection({
      roomId: room.roomId,
      role: "host",
      token: room.hostToken,
      guestToken: room.guestToken,
      watchToken: room.watchToken,
      expiresAt: room.expiresAt,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Could not create private room.";
    setOnlineError(message);
    setOnlineStatus("error", message);
    $("#onlineCreateButton").disabled = false;
  }
}

async function joinOnlineRoom() {
  setOnlineError();
  const credentials = parseInvite($("#onlineInviteInput").value) || parseInvite(location.hash);
  if (!credentials) {
    setOnlineError("Paste the complete private invite link. A room fingerprint alone cannot unlock a seat.");
    setOnlineStatus("error", "Private invite missing its secure key.");
    return;
  }
  $("#onlineJoinButton").disabled = true;
  pendingOnlineInvite = null;
  scrubInviteFromAddress();
  await beginOnlineConnection(credentials);
}

async function copyOnlineInvite() {
  if (!onlineSession.inviteUrl) return;
  try {
    await navigator.clipboard.writeText(onlineSession.inviteUrl);
  } catch {
    const field = $("#onlineInviteLink");
    field.select();
    document.execCommand("copy");
  }
  const button = $("#onlineCopyButton");
  button.textContent = "COPIED";
  setTimeout(() => { button.textContent = "COPY"; }, 1200);
}

// ===========================================================================
// Wave 19 — STREET LIST: the public challenge board. Posting is a deliberate
// host action; browsing/claiming flows straight into the normal join path.
// All endpoints are additive on the worker — nothing here runs for 2.3 flows.
// ===========================================================================

function setStreetPostStatus(text, listed) {
  const row = $("#streetPostRow");
  if (!row) return;
  $("#streetPostStatus").textContent = text;
  row.classList.toggle("listed", Boolean(listed));
}

function renderStreetPostRow() {
  const row = $("#streetPostRow");
  if (!row) return;
  const canPost = onlineSession.role === "host" && Boolean(onlineSession.credentials?.guestToken);
  row.hidden = !canPost;
  if (!canPost) return;
  const select = $("#streetTagSelect");
  if (!select.options.length) {
    select.innerHTML = STREET_TAGS.map((tag) => `<option value="${tag.id}">${tag.label}</option>`).join("");
  }
}

async function postStreetChallenge() {
  const credentials = onlineSession.credentials;
  if (onlineSession.role !== "host" || !credentials?.guestToken) return;
  const button = $("#streetPostButton");
  button.disabled = true;
  setStreetPostStatus("POSTING…", false);
  try {
    const posted = await postChallenge({
      roomId: credentials.roomId,
      hostToken: credentials.token,
      guestToken: credentials.guestToken,
      tag: $("#streetTagSelect").value,
      fighter: onlineSession.lobby.localFighter,
    });
    netFxDebug.streetPosts += 1;
    setStreetPostStatus(`LISTED ON ${streetTagLabel($("#streetTagSelect").value)} · FIRST TAKER GETS THE SEAT`, true);
    void posted;
  } catch (error) {
    setStreetPostStatus(String(error instanceof Error ? error.message : error).toUpperCase(), false);
  } finally {
    button.disabled = false;
  }
}

function renderStreetList() {
  const rowsNode = $("#streetListRows");
  if (!rowsNode) return;
  rowsNode.innerHTML = streetListUi.rows.map((row, index) => `
    <div class="street-row" role="listitem">
      <span class="street-tag">${row.tagLabel}</span>
      <span class="street-fighter">${roster.find((fighter) => fighter.id === row.fighter)?.name || row.fighter.toUpperCase()}</span>
      <span class="street-age">${row.ageLabel}</span>
      <button type="button" data-street-claim="${index}">ANSWER</button>
    </div>`).join("");
  const status = $("#streetListStatus");
  status.classList.toggle("error", Boolean(streetListUi.lastError));
  status.textContent = streetListUi.lastError
    || (streetListUi.rows.length
      ? `${streetListUi.rows.length} OPEN CHALLENGE${streetListUi.rows.length === 1 ? "" : "S"} ON THE BOARD`
      : "NO OPEN CHALLENGES · CREATE A ROOM AND POST YOURS");
}

async function refreshStreetList() {
  if (streetListUi.busy) return;
  streetListUi.busy = true;
  streetListUi.stubbed = false;
  streetListUi.lastError = "";
  $("#streetListStatus").textContent = "SCANNING THE BOARD…";
  try {
    streetListUi.rows = await fetchChallenges();
    netFxDebug.streetRefreshes += 1;
  } catch (error) {
    streetListUi.rows = [];
    streetListUi.lastError = String(error instanceof Error ? error.message : error).toUpperCase();
  } finally {
    streetListUi.busy = false;
    renderStreetList();
  }
}

async function claimStreetChallenge(index) {
  const row = streetListUi.rows[index];
  if (!row || streetListUi.busy) return;
  streetListUi.busy = true;
  streetListUi.lastError = "";
  $("#streetListStatus").textContent = `ANSWERING THE ${row.tagLabel} CHALLENGE…`;
  try {
    const credentials = await claimChallenge(row.id);
    netFxDebug.streetClaims += 1;
    streetListUi.rows = [];
    streetListUi.busy = false;
    renderStreetList();
    // The claim released the guest token exactly once — straight into the
    // standard join flow (same seat auth, same everything).
    await beginOnlineConnection(credentials);
    return;
  } catch (error) {
    streetListUi.lastError = String(error instanceof Error ? error.message : error).toUpperCase();
    streetListUi.rows = streetListUi.rows.filter((entry) => entry !== row);
  }
  streetListUi.busy = false;
  renderStreetList();
}

// ===========================================================================
// Wave 19 — SPECTATOR SEATS (watcher side). A third browser authenticates the
// read-only watch seat, receives the host's confirmed input stream over
// signaling, seeds the identical deterministic match from the shared header
// and plays it through the replay driver a beat behind live. No inputs, a
// SPECTATING badge, and a clean end card when the broadcast stops.
// ===========================================================================

function updateSpectateHud() {
  const hud = $("#spectateHud");
  if (!hud) return;
  const visible = replayPlayback.active && replayPlayback.spectate && state.screen === "fight";
  hud.hidden = !visible;
  if (!visible) return;
  const feed = spectatorSession.feed;
  const behind = Math.max(0, feed.frames0.length - replayPlayback.index);
  $("#spectateHudDetail").textContent = spectatorSession.buffering
    ? "BUFFERING · HOLDING FOR THE STREET FEED"
    : `LIVE · ${Math.max(1, Math.round(behind / 60))}S BEHIND`;
}

function startSpectatePlayback() {
  const feed = spectatorSession.feed;
  const header = feed.header;
  if (!header || replayPlayback.active) return false;
  const record = createReplayRecord({
    header: createReplayHeader({
      kind: "online",
      mode: "online",
      protocol: header.protocol,
      gameVersion: header.gameVersion,
      picks: header.picks,
      palettes: header.palettes,
      stage: header.stage,
      mutators: header.mutators,
      stageWeaponsEnabled: true,
      startPhase: { phase: "intro", phaseTime: 2.25 },
      startTick: 1,
      seed: header.seed,
      inputDelay: header.inputDelay,
      matchId: header.matchId,
    }),
    frames0: feed.frames0,
    frames1: feed.frames1,
  });
  const started = startReplayPlayback(record, { manual: false });
  if (!started.ok) {
    endSpectate(`BROADCAST REFUSED · ${started.reason || "VERSION MISMATCH"}`.toUpperCase());
    return false;
  }
  // Live aliasing: batches append into the feed arrays and playback sees them
  // immediately; stepping is buffer-bounded so it never invents idle frames.
  replayPlayback.spectate = true;
  replayPlayback.frames0 = feed.frames0;
  replayPlayback.frames1 = feed.frames1;
  replayPlayback.burns = [];
  spectatorSession.playing = true;
  spectatorSession.buffering = feed.frames0.length === 0;
  $("#replayHud").hidden = true;
  const names = header.picks.map((id) => roster.find((fighter) => fighter.id === id)?.name || id.toUpperCase());
  announce("SPECTATING", `${names[0]} VS ${names[1]} · LIVE FROM THE STREET`, 1.1);
  updateSpectateHud();
  return true;
}

function receiveSpectateSignal(message) {
  const feed = spectatorSession.feed;
  if (message.type === "welcome") {
    spectatorSession.hostPresent = (message.peers || []).includes("host");
    spectatorSession.signaling?.send({ type: "watch-hello", have: feed.frames0.length });
    setOnlineStatus("connected", spectatorSession.hostPresent
      ? "Spectator seat authenticated. Waiting for the broadcast…"
      : "Spectator seat authenticated. The host is away — holding the seat.");
    return;
  }
  if (message.type === "peer" && message.role === "host") {
    spectatorSession.hostPresent = message.state === "joined";
    if (message.state === "joined") {
      spectatorSession.signaling?.send({ type: "watch-hello", have: feed.frames0.length });
    } else if (replayPlayback.active && replayPlayback.spectate && replayPlayback.index >= feed.frames0.length && !feed.ended) {
      // The broadcaster vanished and the buffer is dry — clean end screen.
      endSpectate("BROADCAST ENDED · THE HOST LEFT THE ARENA");
    }
    return;
  }
  if (message.type !== "spectate" || message.from !== "host") return;
  if (message.kind === "header") {
    if (replayPlayback.active && replayPlayback.spectate && feed.header?.matchId === message.matchId) return;
    if (replayPlayback.active && replayPlayback.spectate) stopReplayPlayback();
    if (feedSpectateHeader(feed, message)) startSpectatePlayback();
    return;
  }
  if (message.kind === "frames") {
    const result = feedSpectateBatch(feed, message);
    if (result.accepted && result.appended) {
      netFxDebug.spectateBatchesReceived += 1;
      spectatorSession.buffering = false;
    } else if (result.gap) {
      // Missed a stretch — ask the host to resend from our frontier.
      spectatorSession.signaling?.send({ type: "watch-hello", have: feed.gapAt });
    }
    if (!replayPlayback.active && feed.header) startSpectatePlayback();
    updateSpectateHud();
    return;
  }
  if (message.kind === "end") {
    feedSpectateEnd(feed, message);
    // Let playback drain the remaining buffered frames; the natural result
    // (or the drain check in simulateReplayTick) closes the broadcast.
    if (!replayPlayback.active) {
      endSpectate(feed.endWinner === null
        ? "BROADCAST ENDED"
        : `BROADCAST ENDED · ${roster.find((fighter) => fighter.id === feed.header?.picks?.[feed.endWinner])?.name || `P${feed.endWinner + 1}`} WINS`);
    }
  }
}

function endSpectate(statusMessage = "BROADCAST ENDED") {
  const wasActive = spectatorSession.active;
  spectatorSession.generation += 1;
  spectatorSession.playing = false;
  spectatorSession.buffering = false;
  if (replayPlayback.active && replayPlayback.spectate) stopReplayPlayback();
  spectatorSession.stopSignal?.();
  spectatorSession.stopSignal = null;
  spectatorSession.signaling?.close();
  spectatorSession.signaling = null;
  spectatorSession.active = false;
  spectatorSession.feed = createSpectatorFeed();
  $("#spectateHud").hidden = true;
  if (!wasActive) return;
  showScreen("online");
  resetOnlineUi();
  setOnlineStatus("closed", statusMessage.charAt(0) + statusMessage.slice(1).toLowerCase());
  announce("BROADCAST OVER", statusMessage, 1.1);
}

async function beginSpectatorSession({ roomId, token, expiresAt = 0 }) {
  endSpectate();
  // A live player seat cannot coexist with the read-only seat on this device.
  if (onlineSession.role) disconnectOnline(false);
  spectatorSession.active = true;
  const generation = ++spectatorSession.generation;
  spectatorSession.credentials = { roomId, role: "watch", token, expiresAt };
  spectatorSession.feed = createSpectatorFeed();
  state.mode = "online";
  showScreen("online");
  $("#onlineActions").hidden = true;
  setOnlineStatus("connecting", "Opening the read-only spectator seat…");
  try {
    const signaling = await connectPrivateRoom({ roomId, role: "watch", token });
    if (generation !== spectatorSession.generation) {
      signaling.close();
      return;
    }
    spectatorSession.signaling = signaling;
    spectatorSession.stopSignal = signaling.onMessage((message) => {
      if (generation !== spectatorSession.generation) return;
      receiveSpectateSignal(message);
    });
    signaling.onClose(({ code }) => {
      if (generation !== spectatorSession.generation || !spectatorSession.active) return;
      endSpectate(code === 4001 ? "BROADCAST ENDED · ROOM EXPIRED" : "BROADCAST ENDED · SIGNAL LOST");
    });
  } catch (error) {
    spectatorSession.active = false;
    const message = error instanceof Error ? error.message : "Could not open the spectator seat.";
    setOnlineError(message);
    setOnlineStatus("error", message);
    resetOnlineUi();
  }
}

// ===========================================================================
// Wave 19 — THE PHILLY OPEN: local 4/8-entrant single-elimination bracket.
// Pure meta around the existing versus/tournament match machinery: humans
// hot-seat one keyboard (a lone human always takes the P1 controls; two
// humans in the same match play couch P1/P2), CPUs fight at their chosen
// difficulty, CPU-vs-CPU matches run watchably in tournament mode. The
// bracket persists to localStorage so an accidental reload resumes.
// ===========================================================================

const BRACKET_CONTROL_CHOICES = Object.freeze([
  { id: "human", label: "HUMAN" },
  { id: "rookie", label: "CPU · ROOKIE" },
  { id: "street", label: "CPU · STREET" },
  { id: "pro", label: "CPU · PRO" },
  { id: "final", label: "CPU · FINAL" },
]);

function saveBracket() {
  try {
    if (bracketSession.bracket) localStorage.setItem(BRACKET_STORAGE_KEY, serializeBracket(bracketSession.bracket));
  } catch {
    // Storage full or denied — the bracket still plays, resume just skips.
  }
}

function clearSavedBracket() {
  try {
    localStorage.removeItem(BRACKET_STORAGE_KEY);
  } catch {
    // Nothing to clear.
  }
}

function loadSavedBracket() {
  try {
    return deserializeBracket(localStorage.getItem(BRACKET_STORAGE_KEY));
  } catch {
    return null;
  }
}

function bracketEntrantDef(index) {
  const entrant = bracketSession.bracket?.entrants[index];
  return entrant ? roster.find((fighter) => fighter.id === entrant.fighter) || null : null;
}

function bracketEntrantName(index) {
  const entrant = bracketSession.bracket?.entrants[index];
  if (!entrant) return "TBD";
  return bracketEntrantDef(index)?.name || entrant.fighter.toUpperCase();
}

function showPhillyOpen() {
  enterImmersiveMode();
  unlockAudio();
  if (!bracketSession.bracket) {
    const saved = loadSavedBracket();
    if (saved) {
      bracketSession.bracket = saved;
      bracketSession.active = true;
      if (saved.playedMatches > 0 && !bracketComplete(saved)) netFxDebug.bracketResumes += 1;
    }
  }
  bracketSession.playing = false;
  bracketSession.current = null;
  showScreen("bracket");
  if (bracketSession.bracket) renderBracketBoard();
  else renderBracketSetup(true);
}

function renderBracketSetup(rebuildRows = false) {
  bracketSession.active = false;
  $("#bracketSetup").hidden = false;
  $("#bracketBoard").hidden = true;
  $("#bracketCeremony").hidden = true;
  $("#bracketNextButton").hidden = true;
  $("#bracketResetButton").hidden = true;
  $("#bracketEyebrow").textContent = "SINGLE ELIMINATION · WINNER TAKES THE STREET";
  $("#bracketStatus").textContent = `${bracketSession.setupSize} ENTRANTS · SEED 1 IS THE TOP LINE`;
  $("#bracketSize4Button").classList.toggle("ghost", bracketSession.setupSize !== 4);
  $("#bracketSize8Button").classList.toggle("ghost", bracketSession.setupSize !== 8);
  const rowsNode = $("#bracketEntrantRows");
  if (!rebuildRows && rowsNode.children.length === bracketSession.setupSize) return;
  const pickable = roster.filter((fighter) => !fighter.secret || commissionerUnlocked());
  const fighterOptions = (selected) => pickable
    .map((fighter) => `<option value="${fighter.id}"${fighter.id === selected ? " selected" : ""}>${fighter.name}</option>`)
    .join("");
  const controlOptions = (selected) => BRACKET_CONTROL_CHOICES
    .map((choice) => `<option value="${choice.id}"${choice.id === selected ? " selected" : ""}>${choice.label}</option>`)
    .join("");
  rowsNode.innerHTML = Array.from({ length: bracketSession.setupSize }, (_, index) => `
    <div class="bracket-entrant-row">
      <span class="seed-chip">${index + 1}</span>
      <select data-bracket-fighter="${index}" aria-label="Seed ${index + 1} fighter">${fighterOptions(pickable[index % pickable.length].id)}</select>
      <select data-bracket-control="${index}" aria-label="Seed ${index + 1} control">${controlOptions(index === 0 ? "human" : "street")}</select>
    </div>`).join("");
}

function startPhillyOpenBracket(entrantsOverride = null) {
  let entrants = entrantsOverride;
  if (!entrants) {
    entrants = Array.from({ length: bracketSession.setupSize }, (_, index) => {
      const control = $(`[data-bracket-control="${index}"]`)?.value || "street";
      return {
        fighter: $(`[data-bracket-fighter="${index}"]`)?.value || roster[index % roster.length].id,
        human: control === "human",
        difficulty: control === "human" ? "street" : control,
      };
    });
  }
  const bracket = createBracket(entrants);
  bracket.createdAt = Date.now();
  bracketSession.bracket = bracket;
  bracketSession.active = true;
  bracketSession.playing = false;
  bracketSession.current = null;
  bracketSession.lastOutcome = null;
  saveBracket();
  renderBracketBoard();
  announce("THE PHILLY OPEN", `${bracket.size} ENTER · ONE TAKES THE STREET`, 1.4);
  return bracket;
}

function renderBracketBoard() {
  const bracket = bracketSession.bracket;
  if (!bracket) {
    renderBracketSetup(true);
    return;
  }
  $("#bracketSetup").hidden = true;
  const complete = bracketComplete(bracket);
  $("#bracketBoard").hidden = complete;
  $("#bracketCeremony").hidden = !complete;
  $("#bracketResetButton").hidden = false;
  const next = nextBracketMatch(bracket);
  const nextButton = $("#bracketNextButton");
  nextButton.hidden = !next;
  if (next) {
    const names = next.slots.map((slot) => bracketEntrantName(slot));
    nextButton.textContent = `NEXT MATCH · ${names[0]} VS ${names[1]} →`;
    $("#bracketStatus").textContent = `${next.roundName} · MATCH ${next.index + 1}`;
    $("#bracketEyebrow").textContent = `SINGLE ELIMINATION · ${bracket.playedMatches} OF ${bracket.size - 1} MATCHES DECIDED`;
  }
  if (complete) {
    renderBracketCeremony();
    return;
  }
  $("#bracketBoard").innerHTML = bracket.rounds.map((round, roundIndex) => `
    <div class="bracket-round">
      <div class="bracket-round-name">${bracketRoundName(bracket.size, roundIndex)}</div>
      ${round.map((match, matchIndex) => {
        const playable = next && next.round === roundIndex && next.index === matchIndex;
        const classes = ["bracket-match", playable ? "playable" : "", match.winner >= 0 ? "decided" : ""].filter(Boolean).join(" ");
        const slots = match.slots.map((slot) => {
          if (slot < 0) return '<span class="bracket-slot tbd"><i class="slot-seed">—</i><span class="slot-name">TBD</span><em class="slot-kind"></em></span>';
          const entrant = bracket.entrants[slot];
          const outcome = match.winner < 0 ? "" : match.winner === slot ? "won" : "lost";
          const kind = entrant.human ? entrant.label : `CPU ${entrant.difficulty.toUpperCase()}`;
          return `<span class="bracket-slot ${outcome}"><i class="slot-seed">#${entrant.seed}</i><span class="slot-name">${bracketEntrantName(slot)}</span><em class="slot-kind">${kind}</em></span>`;
        }).join("");
        return `<div class="${classes}" data-bracket-match="${roundIndex}-${matchIndex}">${slots}</div>`;
      }).join("")}
    </div>`).join("");
}

function renderBracketCeremony() {
  const bracket = bracketSession.bracket;
  if (!bracket || bracket.champion < 0) return;
  const champion = bracket.entrants[bracket.champion];
  const def = bracketEntrantDef(bracket.champion);
  $("#bracketEyebrow").textContent = "THE STREET HAS A NAME ON IT";
  $("#bracketChampionArt").src = `assets/fighters/${champion.fighter}.webp`;
  $("#bracketChampionName").textContent = bracketEntrantName(bracket.champion);
  const quote = def ? selectWinQuote(def.id, {}, 0.237, "") : null;
  $("#bracketChampionQuote").textContent = quote?.text?.toUpperCase() || "THE STREET MOVED FIRST.";
  $("#bracketChampionLabel").textContent = champion.human ? `${champion.label} · CHAMPION` : "CHAMPION";
  // Credits-style roll of every decided match, latest round last.
  $("#bracketCeremonyRoll").innerHTML = bracket.rounds.map((round, roundIndex) => round
    .filter((match) => match.winner >= 0)
    .map((match) => {
      const loser = match.slots[0] === match.winner ? match.slots[1] : match.slots[0];
      const isFinal = roundIndex === bracket.rounds.length - 1;
      return `<div class="roll-line${isFinal ? " champ" : ""}">${bracketRoundName(bracket.size, roundIndex)} · <b>${bracketEntrantName(match.winner)}</b> OVER ${bracketEntrantName(loser)}</div>`;
    }).join("")).join("");
  $("#bracketStatus").textContent = "CHAMPION CROWNED · NEW OPEN TO RUN IT BACK";
}

function startBracketMatch() {
  const bracket = bracketSession.bracket;
  const next = bracket ? nextBracketMatch(bracket) : null;
  if (!next || bracketSession.playing) return false;
  // Seat order: a lone human always takes side 0 (the shared P1 controls).
  let sides = [next.slots[0], next.slots[1]];
  const [top, bottom] = next.slots.map((slot) => bracket.entrants[slot]);
  if (!top.human && bottom.human) sides = [next.slots[1], next.slots[0]];
  const seated = sides.map((slot) => bracket.entrants[slot]);
  bracketSession.current = { round: next.round, index: next.index, slots: [...next.slots], sides };
  bracketSession.matchCpu = seated.map((entrant) => !entrant.human);
  bracketSession.lastOutcome = null;
  const bothCpu = bracketSession.matchCpu[0] && bracketSession.matchCpu[1];
  state.mode = bothCpu ? "tournament" : "versus";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  state.picks = seated.map((entrant) => rosterIndexById(entrant.fighter));
  const stageIds = Object.keys(stages);
  state.stage = stageIds[bracket.playedMatches % stageIds.length];
  bracketSession.playing = true;
  netFxDebug.bracketMatches += 1;
  startMatch(true);
  // Per-seat CPU difficulty straight from the entrant card (survival pattern).
  state.fighters.forEach((fighter, side) => {
    if (bracketSession.matchCpu[side]) {
      fighter.aiBrain = createAiBrain(seated[side].difficulty || "street");
    }
  });
  announce(next.roundName, `${bracketEntrantName(sides[0])} VS ${bracketEntrantName(sides[1])} · THE PHILLY OPEN`, 1.3);
  updateStageUI();
  updateHud();
  return true;
}

// resolveMatchResult meta hook — fold the finished match into the bracket
// BEFORE showResult reads the outcome (never during resimulation).
function recordBracketMatchResult(winnerSide) {
  const current = bracketSession.current;
  const bracket = bracketSession.bracket;
  if (!current || !bracket) return;
  const winnerEntrant = current.sides[winnerSide === 1 ? 1 : 0];
  const slotSide = current.slots.indexOf(winnerEntrant);
  const outcome = slotSide >= 0 ? reportBracketResult(bracket, current.round, current.index, slotSide) : null;
  bracketSession.playing = false;
  bracketSession.current = null;
  if (!outcome) return;
  bracketSession.lastOutcome = { ...outcome, roundName: bracketRoundName(bracket.size, outcome.round) };
  if (outcome.complete) netFxDebug.bracketChampions += 1;
  saveBracket();
}

// Headless fast-forward for a CPU-vs-CPU bracket match (QA path and the
// tournamentMatrix pattern): steps the real deterministic sim to the result.
function fastForwardBracketMatch(maxSeconds = 400) {
  if (!bracketSession.playing || state.screen !== "fight") return false;
  if (!(bracketSession.matchCpu[0] && bracketSession.matchCpu[1])) return false;
  const maxFrames = Math.max(60, Math.floor(maxSeconds * SIMULATION_HZ));
  for (let frame = 0; frame < maxFrames && state.screen === "fight"; frame += 1) {
    simulationClock.stepOnce(runSimulationStep);
  }
  state.simulationTick = simulationClock.tick;
  return state.screen !== "fight";
}

function continueBracketAfterResult() {
  if (!bracketSession.bracket) return;
  bracketSession.lastOutcome = null;
  showScreen("bracket");
  renderBracketBoard();
  if (bracketComplete(bracketSession.bracket)) {
    const name = bracketEntrantName(bracketSession.bracket.champion);
    announce("CHAMPION", `${name} TAKES THE PHILLY OPEN`, 1.6);
  }
}

function resetPhillyOpen() {
  bracketSession.bracket = null;
  bracketSession.active = false;
  bracketSession.playing = false;
  bracketSession.current = null;
  bracketSession.lastOutcome = null;
  clearSavedBracket();
  renderBracketSetup(true);
}

function delayChoiceFrames(choice) {
  return choice === "auto"
    ? recommendedInputDelay(onlineSession.latency || 70)
    : normalizeInputDelay(choice);
}

function makeOnlineMatchConfig({ rematch = false } = {}) {
  if (onlineSession.role !== "host") return null;
  const lobby = onlineSession.lobby;
  const seedBytes = new Uint32Array(1);
  crypto.getRandomValues(seedBytes);
  // Wave 16: the Commissioner may only enter the config when BOTH peers have
  // him unlocked — the same both-sides-agree gate mutators use. The lobby UI
  // never offers him otherwise; this is the belt to that suspenders.
  const commissionerEligible = commissionerUnlocked() && lobby.remoteCommissionerUnlocked;
  if ([lobby.localFighter, lobby.remoteFighter].includes(ARCADE_BOSS_ID) && !commissionerEligible) return null;
  // R2.1 STREETS: first-to-N carry. A finished (or re-sized) set restarts
  // before the config snapshots it, so the guest adopts a coherent scoreboard.
  const setLength = lobby.remoteQol >= 1 ? normalizeSetLength(lobby.setChoice) : 1;
  if (onlineSession.set.length !== setLength || setComplete(onlineSession.set)) {
    onlineSession.set = createSetState(setLength);
  }
  return {
    version: 1,
    matchId: crypto.randomUUID(),
    seed: seedBytes[0] || 237,
    picks: [lobby.localFighter, lobby.remoteFighter],
    stage: stages[lobby.stage] ? lobby.stage : "somerset",
    inputDelay: Math.max(delayChoiceFrames(lobby.delayChoice), delayChoiceFrames(lobby.remoteDelayChoice)),
    controlStyles: [state.controlStyle, lobby.remoteControlStyle],
    // Wave 16: agreed color picks, one per side, in picks order.
    palettes: [lobby.localPalette === 1 ? 1 : 0, lobby.remotePalette === 1 ? 1 : 0],
    rematch: Boolean(rematch),
    // R2.1 STREETS: optional QoL extension — an older guest ignores all of it
    // and simply plays a single match under the 2.3 rules.
    qol: ONLINE_QOL_LEVEL,
    setLength,
    set: setLength > 1
      ? { length: setLength, scores: [...onlineSession.set.scores], history: onlineSession.set.history.map((entry) => ({ ...entry })) }
      : undefined,
  };
}

function validOnlineMatchConfig(config) {
  return Boolean(
    config
    && config.version === 1
    && typeof config.matchId === "string"
    && config.matchId.length >= 12
    && Number.isInteger(config.seed)
    && config.picks?.length === 2
    && config.picks.every((id) => onlineFighterIds.has(id))
    && stages[config.stage]
    && Number.isInteger(config.inputDelay)
    && config.inputDelay >= 0
    && config.inputDelay <= 4
    && config.controlStyles?.length === 2
    // Optional shared House Rules: absent (plain rooms) or a list of known
    // mutator ids agreed by both peers. Unknown ids reject the config.
    && (config.mutators === undefined
      || (Array.isArray(config.mutators) && config.mutators.every((id) => Boolean(MUTATORS[id]))))
    // Wave 16: optional agreed color picks — absent (older peer) or exactly
    // one 0/1 per side. Anything else rejects the config.
    && (config.palettes === undefined
      || (Array.isArray(config.palettes) && config.palettes.length === 2
        && config.palettes.every((palette) => palette === 0 || palette === 1)))
    // R2.1 STREETS: optional first-to-N extension. Absent (older host) or a
    // known FT length; the set snapshot itself is sanitized on adoption.
    && (config.setLength === undefined || SET_LENGTHS.includes(config.setLength))
    && (config.set === undefined || (config.set && typeof config.set === "object")),
  );
}

function maybeLaunchOnlineMatch() {
  if (onlineSession.role !== "host" || onlineSession.matchActive) return;
  if (!onlineSession.lobby.localReady || !onlineSession.lobby.remoteReady) return;
  const config = makeOnlineMatchConfig();
  if (!config) return;
  sendOnlineControl({ type: "match-start", config });
  startOnlineMatch(config);
}

function toggleOnlineReady() {
  if (!onlineSession.peer?.connected || onlineSession.matchActive) return;
  onlineSession.lobby.localReady = !onlineSession.lobby.localReady;
  sendOnlineLobbyState();
  updateOnlineMatchSetup();
  persistOnlineResume(false);
  maybeLaunchOnlineMatch();
}

function updateOnlineRematchUi() {
  const node = $("#onlineRematchStatus");
  const visible = state.mode === "online" && state.screen === "result";
  node.hidden = !visible;
  if (!visible) return;
  node.textContent = `REMATCH VOTES · ${onlineSession.rematchVotes.size} / 2`;
  $("#rematchButton").textContent = onlineSession.rematchVotes.has(onlineSession.role)
    ? "REMATCH REQUESTED" : onlineSession.rematchVotes.has(onlineRemoteRole()) ? "ACCEPT REMATCH" : "REQUEST REMATCH";
}

function maybeLaunchOnlineRematch() {
  if (onlineSession.role !== "host" || onlineSession.rematchVotes.size < 2) return;
  const config = makeOnlineMatchConfig({ rematch: true });
  if (!config) return;
  sendOnlineControl({ type: "match-start", config });
  startOnlineMatch(config);
}

function requestOnlineRematch() {
  if (state.mode !== "online" || state.screen !== "result" || !onlineSession.peer?.connected) return;
  onlineSession.rematchVotes.add(onlineSession.role);
  sendOnlineControl({ type: "rematch-vote", matchId: onlineSession.matchConfig?.matchId });
  updateOnlineRematchUi();
  checkRematchAccepted();
  maybeLaunchOnlineRematch();
}

function compareOnlineChecksum(frame, remoteChecksum) {
  const rollback = onlineSession.rollback;
  if (!rollback || typeof remoteChecksum !== "string") return;
  const localChecksum = rollback.checksumAt(frame);
  if (!localChecksum) {
    onlineSession.remoteChecksums.set(frame, remoteChecksum);
    return;
  }
  onlineSession.remoteChecksums.delete(frame);
  if (localChecksum === remoteChecksum) {
    onlineSession.checksumMismatches = 0;
    updateOnlineHud();
    return;
  }
  onlineSession.checksumMismatches += 1;
  updateOnlineHud("error");
  sendOnlineControl({ type: "desync-warning", matchId: onlineSession.matchConfig?.matchId, frame });
  if (onlineSession.role === "host" && onlineSession.checksumMismatches >= 2) sendAuthoritativeOnlineState("desync");
}

function checkPendingOnlineChecksums() {
  for (const [frame, checksum] of onlineSession.remoteChecksums) compareOnlineChecksum(frame, checksum);
}

function sendAuthoritativeOnlineState(reason = "reconnect") {
  if (onlineSession.role !== "host" || !onlineSession.rollback || !onlineSession.peer?.connected) return false;
  onlineSession.networkPaused = true;
  onlineSession.awaitingResume = true;
  setOnlineInterruption(true, reason === "desync" ? "SYNC REPAIR" : "RESYNCHRONIZING", "Transferring the host's verified deterministic state…");
  const sync = onlineSession.rollback.exportSync();
  const sent = sendOnlineControl({
    type: "state-sync",
    reason,
    matchId: onlineSession.matchConfig?.matchId,
    frame: sync.frame,
    state: serializeRollbackState(sync.state),
  });
  updateOnlineHud("warning");
  return sent;
}

function completeOnlineResume() {
  onlineSession.awaitingResume = false;
  onlineSession.reconnecting = false;
  onlineSession.localSuspended = !state.qaManualMode
    && (document.hidden || document.body.classList.contains("orientation-blocked"));
  onlineSession.networkPaused = onlineSession.localSuspended || onlineSession.remoteSuspended;
  onlineSession.checksumMismatches = 0;
  onlineSession.remoteChecksums.clear();
  refreshOnlinePauseOverlay();
  persistOnlineResume(true);
  // Wave 9: the resync handshake finished — the announcer confirms the link.
  if (onlineSession.matchActive) announcerOnlineMoment("recovered");
}

function refreshOnlinePauseOverlay() {
  if (!onlineSession.matchActive) return;
  const suspended = onlineSession.localSuspended || onlineSession.remoteSuspended;
  onlineSession.networkPaused = onlineSession.reconnecting || onlineSession.awaitingResume || suspended;
  if (suspended) setOnlineInterruption(true, "MATCH HOLD", onlineSession.localSuspended
    ? state.pauseReason || "Return to landscape play to resume both fighters."
    : "The other fighter is restoring the arena view…");
  else if (!onlineSession.networkPaused) setOnlineInterruption(false);
  updateOnlineHud(onlineSession.networkPaused ? "warning" : "sync");
}

function setOnlineLocalSuspended(suspended) {
  if (!onlineSession.matchActive || onlineSession.localSuspended === Boolean(suspended)) return;
  onlineSession.localSuspended = Boolean(suspended);
  sendOnlineControl({ type: "peer-suspend", matchId: onlineSession.matchConfig?.matchId, suspended: onlineSession.localSuspended });
  refreshOnlinePauseOverlay();
}

function receiveOnlineControl(message) {
  if (!message || typeof message !== "object") return;
  if (message.type === "lobby-state" && !onlineSession.matchActive) {
    onlineSession.lobby.remoteFighterRaw = typeof message.fighter === "string" ? message.fighter : "";
    if (onlineFighterIds.has(message.fighter)) onlineSession.lobby.remoteFighter = message.fighter;
    // R2.1 STREETS: sanitize the optional QoL extension FIRST — the stage
    // adoption below depends on who owns the cursor (loser-picks-stage).
    const qol = sanitizeLobbyQol(message);
    onlineSession.lobby.remoteQol = qol.qol;
    onlineSession.lobby.remotePing = qol.ping;
    onlineSession.lobby.remoteSetLength = qol.setLength;
    // The set length is host law: a guest mirrors it into its own display.
    if (onlineSession.role === "guest" && qol.qol >= 1) onlineSession.lobby.setChoice = String(qol.setLength);
    // Stage cursor: the NON-owner adopts the owner's pick. With an older peer
    // (qol 0) the owner is always the host — exactly the 2.3 rule.
    if (stages[message.stage] && onlineStagePickerRole() !== onlineSession.role) {
      onlineSession.lobby.stage = message.stage;
    }
    onlineSession.lobby.remoteDelayChoice = ["auto", "0", "1", "2", "3", "4"].includes(String(message.delayChoice))
      ? String(message.delayChoice) : "auto";
    onlineSession.lobby.remoteControlStyle = normalizeControlStyle(message.controlStyle);
    onlineSession.lobby.remoteReady = Boolean(message.ready);
    // Wave 16: optional fields — absent from an older peer means primary
    // color and a locked Commissioner, which is the safe default both ways.
    onlineSession.lobby.remotePalette = message.palette === 1 ? 1 : 0;
    onlineSession.lobby.remoteCommissionerUnlocked = Boolean(message.commissioner);
    syncOnlineCommissionerOption();
    updateOnlineMatchSetup();
    maybeLaunchOnlineMatch();
    return;
  }
  if (message.type === "match-start" && onlineSession.role === "guest") {
    if (validOnlineMatchConfig(message.config)) {
      startOnlineMatch(message.config);
    } else if (message.config?.picks?.includes?.(ARCADE_BOSS_ID) && !commissionerUnlocked()) {
      // The mutator-style gate tripped: the config names a fighter this
      // machine has not earned. Refuse the match and say exactly why.
      setOnlineStatus("error", "THE COMMISSIONER IS LOCKED ON THIS MACHINE — BEAT ARCADE ON FINAL DIFFICULTY TO ACCEPT THIS MATCH.");
      setOnlineError("Match refused: THE COMMISSIONER is not unlocked on this machine.");
    }
    return;
  }
  if (!onlineSession.matchConfig || message.matchId !== onlineSession.matchConfig.matchId) return;
  if (message.type === "checksum" && Number.isInteger(message.frame)) {
    compareOnlineChecksum(message.frame, message.checksum);
  } else if (message.type === "desync-warning" && onlineSession.role === "host") {
    onlineSession.checksumMismatches += 1;
    if (onlineSession.checksumMismatches >= 2) sendAuthoritativeOnlineState("desync");
  } else if (message.type === "resume-hello") {
    if (onlineSession.role === "host") sendAuthoritativeOnlineState("reconnect");
    else beginOnlineResumeHandshake();
  } else if (message.type === "state-sync" && onlineSession.role === "guest"
    && Number.isInteger(message.frame) && typeof message.state === "string") {
    try {
      onlineSession.networkPaused = true;
      onlineSession.rollback.importSync({ frame: message.frame, state: parseRollbackState(message.state) });
      syncRollbackPresentation();
      sendOnlineControl({ type: "state-sync-ack", matchId: message.matchId, frame: message.frame });
    } catch {
      scheduleOnlineReconnect("Authoritative state transfer failed.");
    }
  } else if (message.type === "state-sync-ack" && onlineSession.role === "host") {
    sendOnlineControl({ type: "state-sync-go", matchId: message.matchId, frame: onlineSession.rollback?.frame || 0 });
    completeOnlineResume();
  } else if (message.type === "state-sync-go" && onlineSession.role === "guest") {
    completeOnlineResume();
  } else if (message.type === "rematch-vote" && state.screen === "result") {
    onlineSession.rematchVotes.add(onlineRemoteRole());
    updateOnlineRematchUi();
    checkRematchAccepted();
    maybeLaunchOnlineRematch();
  } else if (message.type === "peer-suspend") {
    onlineSession.remoteSuspended = Boolean(message.suspended);
    refreshOnlinePauseOverlay();
  } else if (validReturnLobbyMessage(message, onlineSession.matchConfig.matchId)) {
    // R2.1 STREETS: CHANGE FIGHTERS — the opponent asked to drop back to the
    // shared lobby with room, credentials and set score intact.
    returnToOnlineLobby();
  }
}

// R2.1 STREETS: back to #onlineMatchSetup without leaving the room. The set
// scoreboard, credentials and peer link all survive; readiness resets so both
// sides must lock in again. Safe to call on either seat, idempotent.
function returnToOnlineLobby() {
  if (!onlineSession.roomId || state.mode !== "online") return;
  if (!onlineSession.matchActive && state.screen === "online") return;
  onlineSession.matchActive = false;
  onlineSession.rollback = null;
  onlineSession.networkPaused = false;
  onlineSession.awaitingResume = false;
  onlineSession.remoteSuspended = false;
  onlineSession.localSuspended = false;
  onlineSession.rematchVotes.clear();
  onlineSession.remoteChecksums.clear();
  onlineSession.lobby.localReady = false;
  onlineSession.lobby.remoteReady = false;
  resetReplayRecorder();
  clearSyncCountdown();
  setOnlineInterruption(false);
  state.paused = false;
  netFxDebug.returnLobby += 1;
  showScreen("online");
  updateOnlineMatchSetup();
  sendOnlineLobbyState();
  persistOnlineResume(false);
}

function receiveOnlineInput(packet) {
  if (!onlineSession.matchActive || !onlineSession.rollback) return;
  // R2.1 STREETS: packet cadence for the connection meter (meta only). A
  // widening EWMA gap between input packets reads as jitter alongside ping.
  const now = performance.now();
  if (connMeter.lastPacketAt > 0) {
    connMeter.ewmaGapMs = ewma(connMeter.ewmaGapMs, now - connMeter.lastPacketAt, 0.2);
  }
  connMeter.lastPacketAt = now;
  try {
    const result = onlineSession.rollback.receivePacket(packet);
    if (!result.accepted) return;
    checkPendingOnlineChecksums();
    updateOnlineHud(result.rolledBack ? "warning" : "sync");
  } catch {
    onlineSession.checksumMismatches += 1;
    updateOnlineHud("error");
  }
}

function random() {
  // R2.1 STREETS: draw counter for the replay recorder (observation only —
  // the value and the stream are untouched).
  rngDrawSerial += 1;
  return state.rng.nextFloat();
}

function visualRandom() {
  return state.visualRng.nextFloat();
}

function seedMatch(round = state.round) {
  // R2.1 STREETS: replay playback re-derives the EXACT recorded seed. Online
  // replays reuse the online formula with the header's shared seed; offline
  // replays reuse the offline formula with the header's arcade context (the
  // arcadeRun object itself is not reconstructed for playback). Identical to
  // the plain path whenever no replay is running.
  if (replayPlayback.active && replayPlayback.header?.kind === "online") {
    state.matchSeed = hashSeed("FINAL-BLOW-ONLINE", replayPlayback.header.seed || 237, round);
    state.rng.setState(state.matchSeed);
    state.visualRng.setState(hashSeed(state.matchSeed, "visual"));
    return;
  }
  const arcadeCurrent = replayPlayback.active
    ? replayPlayback.header?.arcadeCurrent || 0
    : state.arcadeRun?.current || 0;
  const arcadeOpponent = replayPlayback.active
    ? replayPlayback.header?.arcadeOpponent || "versus"
    : currentArcadeMatch(state.arcadeRun)?.opponentId || "versus";
  state.matchSeed = hashSeed(
    initialSeed,
    state.matchSerial,
    round,
    state.picks[0],
    state.picks[1],
    state.stage,
    arcadeCurrent,
    arcadeOpponent,
  );
  state.rng.setState(state.matchSeed);
  state.visualRng.setState(hashSeed(state.matchSeed, "visual"));
}

function seedOnlineRound(round = state.round) {
  state.matchSeed = hashSeed("FINAL-BLOW-ONLINE", onlineSession.matchConfig?.seed || 237, round);
  state.rng.setState(state.matchSeed);
  state.visualRng.setState(hashSeed(state.matchSeed, "visual"));
}

// ===========================================================================
// R2.1 STREETS — REPLAY THEATER: recorder, ring storage, playback driver.
// ===========================================================================

function loadReplayRing() {
  try {
    const parsed = JSON.parse(localStorage.getItem(REPLAY_STORAGE_KEY));
    return Array.isArray(parsed) ? parsed.filter((entry) => entry && typeof entry === "object") : [];
  } catch {
    return [];
  }
}

function saveReplayRing(ring) {
  try {
    localStorage.setItem(REPLAY_STORAGE_KEY, JSON.stringify(ring));
    return true;
  } catch {
    // Storage full or denied — the match still played; the save just skips.
    return false;
  }
}

function resetReplayRecorder() {
  replayRecorder.active = false;
  replayRecorder.kind = "";
  replayRecorder.mode = "";
  replayRecorder.header = null;
  replayRecorder.frames0 = [];
  replayRecorder.frames1 = [];
  replayRecorder.burns = [];
  replayRecorder.onlineFrames = null;
  replayRecorder.startTick = null;
  replayRecorder.matchKey = "";
  replayRecorder.aborted = false;
}

// Arm the recorder for a freshly-constructed match. Offline covers versus and
// arcade bouts (the same deterministic sim); online records the confirmed
// rollback stream. Never during replay playback itself.
function beginReplayRecording(kind) {
  resetReplayRecorder();
  if (replayPlayback.active) return;
  if (kind === "offline" && !["versus", "arcade"].includes(state.mode)) return;
  if (kind === "offline" && (state.survivalRun || state.teamBattle)) return;
  const online = kind === "online";
  const config = online ? onlineSession.matchConfig : null;
  if (online && !config) return;
  replayRecorder.active = true;
  replayRecorder.kind = online ? "online" : "offline";
  replayRecorder.mode = online ? "online" : state.mode;
  replayRecorder.matchKey = online ? String(config.matchId) : `serial-${state.matchSerial}`;
  replayRecorder.onlineFrames = online ? new Map() : null;
  replayRecorder.header = createReplayHeader({
    kind: replayRecorder.kind,
    mode: replayRecorder.mode,
    protocol: ROLLBACK_PROTOCOL_VERSION,
    gameVersion: GAME_VERSION,
    picks: online
      ? [...config.picks]
      : [roster[state.picks[0]]?.id || "", roster[state.picks[1]]?.id || ""],
    palettes: online ? config.palettes || [0, 0] : [...pendingPalettes],
    stage: state.stage,
    mutators: [...state.mutators],
    stageWeaponsEnabled: state.stageWeaponsEnabled,
    startPhase: { phase: state.phase, phaseTime: state.phaseTime },
    // Online step() runs frame 0 with simulationTick = 1; offline stamps the
    // live tick lazily on the first recorded frame.
    startTick: online ? 1 : 0,
    matchSerial: state.matchSerial,
    arcadeCurrent: state.arcadeRun?.current || 0,
    arcadeOpponent: currentArcadeMatch(state.arcadeRun)?.opponentId || "versus",
    arcadeBoss: Boolean(state.mode === "arcade" && currentArcadeMatch(state.arcadeRun)?.opponentId === ARCADE_BOSS_ID),
    seed: online ? config.seed : 0,
    inputDelay: online ? config.inputDelay : 0,
    matchId: online ? config.matchId : "",
    recordedAt: Date.now(),
  });
  if (online) replayRecorder.startTick = 1;
  netFxDebug.replaysRecorded += 1;
}

function abortReplayRecording() {
  if (replayRecorder.active) replayRecorder.aborted = true;
}

function recordOfflineReplayFrame(input0, input1, rngBurn) {
  if (replayRecorder.aborted) return;
  if (replayRecorder.startTick === null) {
    replayRecorder.startTick = state.simulationTick;
    replayRecorder.header.startTick = state.simulationTick;
  }
  // A round restart or QA time-jump breaks the contiguous input timeline —
  // the recording can no longer reproduce the match, so it disarms.
  if (state.simulationTick !== replayRecorder.startTick + replayRecorder.frames0.length) {
    replayRecorder.aborted = true;
    return;
  }
  replayRecorder.frames0.push(inputToBits(resolveSideInput(0, input0)));
  replayRecorder.frames1.push(inputToBits(resolveSideInput(1, input1)));
  replayRecorder.burns.push(Math.max(0, Math.min(0xffff, rngBurn | 0)));
}

// Flatten the online frame map (0..last, no gaps) or refuse.
function collectOnlineReplayFrames() {
  const map = replayRecorder.onlineFrames;
  if (!map || !map.size) return null;
  let last = -1;
  for (const frame of map.keys()) last = Math.max(last, frame);
  const frames0 = [];
  const frames1 = [];
  for (let frame = 0; frame <= last; frame += 1) {
    const pair = map.get(frame);
    if (!pair) return null;
    frames0.push(pair[0]);
    frames1.push(pair[1]);
  }
  return { frames0, frames1 };
}

// Called from resolveMatchResult (never during resimulation) — banks the
// finished match into the localStorage ring.
function finalizeReplayRecording(winner) {
  if (!replayRecorder.active) return;
  const recorder = replayRecorder;
  const online = recorder.kind === "online";
  const streams = online
    ? collectOnlineReplayFrames()
    : { frames0: recorder.frames0, frames1: recorder.frames1 };
  const modeStable = online ? state.mode === "online" : state.mode === recorder.mode;
  if (recorder.aborted || !modeStable || !streams || !streams.frames0.length) {
    resetReplayRecorder();
    return;
  }
  const record = createReplayRecord({
    header: recorder.header,
    frames0: streams.frames0,
    frames1: streams.frames1,
    burns: online ? [] : recorder.burns,
    outcome: {
      winner: winner === 1 ? 1 : 0,
      rounds: [...state.rounds],
      healths: state.fighters.map((fighter) => Number((fighter?.health ?? 0).toFixed(2))),
    },
  });
  resetReplayRecorder();
  if (saveReplayRing(pushReplayToRing(loadReplayRing(), record))) {
    netFxDebug.replaysSaved += 1;
  }
}

// --- Playback --------------------------------------------------------------

function exitReplayPlayback(status = "") {
  if (!replayPlayback.active) return;
  stopReplayPlayback();
  if (status) replayUi.status = status;
  showReplayTheater();
}

// Tear playback down and restore the module/global values it borrowed. Never
// navigates — callers decide the next screen.
function stopReplayPlayback() {
  if (!replayPlayback.active) return;
  replayPlayback.active = false;
  const saved = replayPlayback.saved;
  replayPlayback.saved = null;
  replayPlayback.frames0 = [];
  replayPlayback.frames1 = [];
  replayPlayback.burns = [];
  replayPlayback.header = null;
  replayPlayback.record = null;
  replayPlayback.spectate = false;
  $("#spectateHud").hidden = true;
  if (saved) {
    state.matchSerial = saved.matchSerial;
    state.stageWeaponsEnabled = saved.stageWeaponsEnabled;
    pendingPalettes = saved.pendingPalettes;
    state.qaManualMode = saved.qaManualMode;
    state.mode = "versus";
    simulationClock.tick = state.simulationTick;
  }
  $("#replayHud").hidden = true;
}

// The replay finished through the real resolveMatchResult pipeline — verify
// determinism against the recorded outcome and land back in the theater.
function finishReplayPlayback(winner) {
  // Wave 19: a spectated match reached its natural result — clean end card on
  // the online screen instead of the theater.
  if (replayPlayback.spectate) {
    const name = roster[state.picks[winner === 1 ? 1 : 0]]?.name || `P${(winner === 1 ? 1 : 0) + 1}`;
    endSpectate(`BROADCAST COMPLETE · ${name} WINS`);
    return;
  }
  const record = replayPlayback.record;
  const outcome = {
    winner: winner === 1 ? 1 : 0,
    rounds: [...state.rounds],
    healths: state.fighters.map((fighter) => Number((fighter?.health ?? 0).toFixed(2))),
  };
  const expected = record?.outcome;
  const verified = !expected
    || (expected.winner === outcome.winner
      && expected.rounds[0] === outcome.rounds[0]
      && expected.rounds[1] === outcome.rounds[1]
      && Math.abs(expected.healths[0] - outcome.healths[0]) < 0.01
      && Math.abs(expected.healths[1] - outcome.healths[1]) < 0.01);
  replayUi.lastOutcome = { ...outcome, verified, expected: expected ? { ...expected } : null };
  const name = roster[state.picks[outcome.winner]]?.name || `P${outcome.winner + 1}`;
  exitReplayPlayback(`REPLAY FINISHED · ${name} WINS${expected ? (verified ? " · DETERMINISM VERIFIED" : " · OUTCOME DIVERGED") : ""}`);
}

function startReplayPlayback(record, { manual = false } = {}) {
  const compat = replayCompatibility(record?.header, { protocol: ROLLBACK_PROTOCOL_VERSION, gameVersion: GAME_VERSION });
  if (!compat.ok) {
    netFxDebug.replayRefusals += 1;
    replayUi.status = `REPLAY REFUSED · ${compat.reason}`;
    renderReplayList();
    return { ok: false, reason: compat.reason };
  }
  const header = record.header;
  const picks = header.picks.map((id) => rosterIndexById(id));
  if (picks.some((index) => index < 0)) {
    netFxDebug.replayRefusals += 1;
    replayUi.status = "REPLAY REFUSED · UNKNOWN FIGHTER IN HEADER";
    renderReplayList();
    return { ok: false, reason: "unknown-fighter" };
  }
  let streams;
  try {
    streams = decodeReplayStreams(record);
  } catch {
    netFxDebug.replayRefusals += 1;
    replayUi.status = "REPLAY REFUSED · CORRUPT INPUT STREAM";
    renderReplayList();
    return { ok: false, reason: "corrupt-stream" };
  }
  resetReplayRecorder();
  cancelFightAnnouncement();
  unlockAudio();
  resetMusicDuck();
  replayPlayback.saved = {
    matchSerial: state.matchSerial,
    stageWeaponsEnabled: state.stageWeaponsEnabled,
    pendingPalettes: [...pendingPalettes],
    qaManualMode: state.qaManualMode,
  };
  replayPlayback.active = true;
  replayPlayback.header = header;
  replayPlayback.record = record;
  replayPlayback.frames0 = streams.frames0;
  replayPlayback.frames1 = streams.frames1;
  replayPlayback.burns = streams.burns;
  replayPlayback.index = 0;
  replayPlayback.speed = 1;
  replayPlayback.paused = false;
  replayPlayback.carry = 0;
  replayPlayback.pendingStep = 0;
  replayPlayback.outcome = null;
  state.mode = "replay";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  state.qaManualMode = manual;
  state.paused = false;
  state.mutators = normalizeMutators(header.mutators);
  state.matchRules = resolveMatchRules(state.mutators);
  state.suddenDeathHitDone = false;
  state.stageWeaponsEnabled = header.stageWeaponsEnabled;
  pendingPalettes = [...header.palettes];
  state.picks = picks;
  state.stage = stages[header.stage] ? header.stage : "somerset";
  applyAutoStageMusic();
  state.rounds = [0, 0];
  state.round = 1;
  state.matchSerial = header.matchSerial;
  // Fighters were BUILT one tick before the first recorded frame in both
  // originals (offline startMatch and online startOnlineMatch at tick 0), and
  // makeFighter latches state.simulationTick into stateEnteredTick — so the
  // rebuild must happen at startTick - 1, then the stream drives the tick.
  state.simulationTick = Math.max(0, header.startTick - 1);
  simulationClock.tick = state.simulationTick;
  seedMatch(1);
  progressionResetMatch();
  applyMatchPalettes([roster[picks[0]], roster[picks[1]]], pendingPalettes);
  state.facingAxis = 1;
  state.fighters = [
    makeFighter(picks[0], 0),
    makeFighter(picks[1], 1, header.arcadeBoss ? arcadeBoss : null),
  ];
  if (state.matchRules.infiniteGrit) {
    for (const fighter of state.fighters) fighter.meter = GRIT_RULES.maximum;
  }
  resetStageWeapon();
  resetCrowd();
  warmFighterAudio();
  clearBattleDamage();
  clearStageScars();
  state.particles.length = 0;
  state.effects.length = 0;
  state.traps.length = 0;
  state.projectiles.length = 0;
  state.timer = 99;
  state.timerCarry = 0;
  state.phase = header.startPhase.phase;
  state.phaseTime = header.startPhase.phaseTime;
  state.hitstop = 0;
  state.lastImpactSide = -1;
  state.finishWinner = -1;
  state.finisherType = 0;
  state.finisher = null;
  state.cinematicZoom = 1;
  state.shake = 0;
  state.flash = 0;
  commandHistory[0].length = 0;
  commandHistory[1].length = 0;
  updateStageUI();
  updateHud();
  showScreen("fight");
  updateReplayHud();
  announce("REPLAY", `${roster[picks[0]].name} VS ${roster[picks[1]].name} · THEATER`, 1.1);
  netFxDebug.replayPlaybacks += 1;
  canvas.focus();
  return { ok: true, frames: replayPlayback.frames0.length };
}

// One recorded frame through the exact online step contract: set the tick,
// burn the recorded AI draws, feed the decoded pair to the sim.
function stepReplayFrame() {
  const playback = replayPlayback;
  const index = playback.index;
  const bits0 = playback.frames0[index] ?? 0;
  const bits1 = playback.frames1[index] ?? 0;
  const burn = playback.burns[index] ?? 0;
  state.simulationTick = playback.header.startTick + index;
  for (let draw = 0; draw < burn; draw += 1) random();
  simulatePreparedGameTick(SIMULATION_STEP_SECONDS, bitsToInput(bits0), bitsToInput(bits1));
  playback.index += 1;
  // Watchdog: a stream that somehow never reaches a result stops a minute
  // past its own end instead of looping forever. Live spectate streams are
  // buffer-bounded in simulateReplayTick, so the watchdog never applies.
  if (playback.active && !playback.spectate && playback.index > playback.frames0.length + 3600) {
    exitReplayPlayback("REPLAY ENDED · NO RESULT IN STREAM");
  }
}

function simulateReplayTick() {
  const playback = replayPlayback;
  if (!playback.active) return;
  let ticks = 0;
  if (playback.paused) {
    ticks = Math.min(1, playback.pendingStep);
    playback.pendingStep = Math.max(0, playback.pendingStep - ticks);
  } else {
    playback.carry += playback.speed;
    ticks = Math.floor(playback.carry);
    playback.carry -= ticks;
  }
  for (let tick = 0; tick < ticks && playback.active && state.screen === "fight"; tick += 1) {
    // Wave 19: a live spectator never steps past the confirmed buffer — it
    // holds (BUFFERING) until the next batch lands, which is what keeps the
    // spectator a beat behind by design.
    if (playback.spectate && playback.index >= playback.frames0.length) {
      spectatorSession.buffering = !spectatorSession.feed.ended;
      // Drained a finished broadcast without a sim result (host quit mid-match).
      if (spectatorSession.feed.ended && playback.active) {
        endSpectate(spectatorSession.feed.endReason === "host-left"
          ? "BROADCAST ENDED · THE HOST LEFT THE ARENA"
          : "BROADCAST ENDED");
        return;
      }
      break;
    }
    stepReplayFrame();
    if (playback.spectate) {
      netFxDebug.spectateFramesPlayed += 1;
      spectatorSession.buffering = false;
    }
  }
  if (playback.active && playback.spectate) updateSpectateHud();
  updateReplayHudFrame();
}

function setReplaySpeed(speed) {
  const allowed = [0.5, 1, 2];
  replayPlayback.speed = allowed.includes(Number(speed)) ? Number(speed) : 1;
  replayPlayback.carry = 0;
  updateReplayHud();
  return replayPlayback.speed;
}

function cycleReplaySpeed() {
  const order = [0.5, 1, 2];
  const next = order[(order.indexOf(replayPlayback.speed) + 1) % order.length];
  return setReplaySpeed(next);
}

function toggleReplayPause(paused = !replayPlayback.paused) {
  replayPlayback.paused = Boolean(paused);
  replayPlayback.pendingStep = 0;
  replayPlayback.carry = 0;
  updateReplayHud();
  return replayPlayback.paused;
}

function updateReplayHud() {
  const hud = $("#replayHud");
  if (!hud) return;
  // Wave 19: live spectate swaps the theater controls for the badge — a
  // spectator can neither pause nor scrub someone else's match.
  if (replayPlayback.spectate) {
    hud.hidden = true;
    updateSpectateHud();
    return;
  }
  updateSpectateHud();
  const visible = replayPlayback.active && state.screen === "fight";
  hud.hidden = !visible;
  if (!visible) return;
  const header = replayPlayback.header;
  $("#replayHudLabel").textContent = header
    ? `${roster[state.picks[0]]?.name || header.picks[0]} VS ${roster[state.picks[1]]?.name || header.picks[1]}`
    : "REPLAY";
  $("#replayPauseButton").textContent = replayPlayback.paused ? "▶" : "⏸";
  $("#replaySpeedButton").textContent = `${replayPlayback.speed}×`;
  updateReplayHudFrame();
}

function updateReplayHudFrame() {
  if (!replayPlayback.active || state.screen !== "fight") return;
  const total = replayPlayback.frames0.length;
  $("#replayHudFrame").textContent = `${Math.min(replayPlayback.index, total)} / ${total}F`;
}

// --- Theater screen --------------------------------------------------------

function showReplayTheater() {
  enterImmersiveMode();
  unlockAudio();
  showScreen("replays");
  renderReplayList();
}

function replayMatchupLabel(summary) {
  const names = summary.picks.map((id) => roster.find((fighter) => fighter.id === id)?.name || id.toUpperCase());
  return `${names[0]} VS ${names[1]}`;
}

function renderReplayList() {
  const list = $("#replayList");
  if (!list) return;
  const ring = loadReplayRing();
  const here = { protocol: ROLLBACK_PROTOCOL_VERSION, gameVersion: GAME_VERSION };
  list.innerHTML = ring.length ? ring.map((record, index) => {
    const summary = replaySummary(record, index);
    const compat = replayCompatibility(record.header, here);
    const winner = summary.winner === null ? "" : ` · ${(summary.picks[summary.winner] || "?").toUpperCase()} WON`;
    const when = summary.recordedAt ? new Date(summary.recordedAt).toLocaleDateString() : "";
    return `
      <div class="replay-row${compat.ok ? "" : " stale"}" data-replay-index="${index}">
        <div class="replay-row-copy">
          <b>${replayMatchupLabel(summary)}</b>
          <small>${summary.mode.toUpperCase()} · ${stages[summary.stage]?.name || summary.stage.toUpperCase()} · ${summary.seconds}S${winner}</small>
          <small>${when} · V${summary.gameVersion} · PROTOCOL ${summary.protocol}${compat.ok ? "" : ` · ${compat.reason}`}</small>
        </div>
        <div class="replay-row-actions">
          <button type="button" class="arcade-button compact primary" data-replay-action="watch" ${compat.ok ? "" : "disabled"}>WATCH</button>
          <button type="button" class="arcade-button compact" data-replay-action="export">EXPORT</button>
          <button type="button" class="arcade-button compact ghost" data-replay-action="delete">DELETE</button>
        </div>
      </div>`;
  }).join("") : '<p class="replay-empty">NO REPLAYS YET — FINISH A VERSUS, ARCADE OR ONLINE MATCH AND IT LANDS HERE.</p>';
  $("#replayStatus").textContent = replayUi.status || `LAST ${ring.length} MATCHES KEPT · EXPORT SHARES A .FBR FILE`;
}

function exportReplay(record) {
  const blob = new Blob([JSON.stringify(record)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = replayFileName(record);
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  netFxDebug.replayExports += 1;
}

function importReplayText(text) {
  let record;
  try {
    record = validateReplayRecord(JSON.parse(text));
  } catch (error) {
    replayUi.status = `IMPORT REFUSED · ${(error instanceof Error ? error.message : "UNREADABLE FILE").toUpperCase()}`;
    renderReplayList();
    return false;
  }
  saveReplayRing(pushReplayToRing(loadReplayRing(), record));
  netFxDebug.replayImports += 1;
  replayUi.status = `IMPORTED · ${replayMatchupLabel(replaySummary(record))}`;
  renderReplayList();
  return true;
}

function handleReplayListClick(event) {
  const button = event.target.closest("[data-replay-action]");
  if (!button) return;
  const row = button.closest("[data-replay-index]");
  const index = Number(row?.dataset.replayIndex);
  const ring = loadReplayRing();
  const record = ring[index];
  if (!record) return;
  replayUi.status = "";
  if (button.dataset.replayAction === "watch") {
    startReplayPlayback(record);
  } else if (button.dataset.replayAction === "export") {
    exportReplay(record);
    replayUi.status = "EXPORTED · SHARE THE .FBR FILE";
    renderReplayList();
  } else if (button.dataset.replayAction === "delete") {
    ring.splice(index, 1);
    saveReplayRing(ring);
    renderReplayList();
  }
}

// ===========================================================================
// R2.1 STREETS — FIRST-TO-N SETS: winner-stays bookkeeping shared by online
// rooms (onlineSession.set, side 0 = host seat) and offline versus
// (offlineSet). Meta only — never snapshotted, folded once per finished match
// via the matchKey dedupe inside recordSetWin.
// ===========================================================================

// The set the CURRENT match belongs to, or null when set play is inert.
function activeSetState() {
  if (state.mode === "online" && onlineSession.matchConfig) return onlineSession.set;
  // Wave 19: bracket matches never fold into the casual versus scoreboard.
  if (state.mode === "versus" && !state.teamBattle && !bracketSession.playing && offlineSet) return offlineSet;
  return null;
}

function setSideNames() {
  return [
    state.fighters[0]?.def.name || roster[state.picks[0]]?.name || "P1",
    state.fighters[1]?.def.name || roster[state.picks[1]]?.name || "P2",
  ];
}

// Fold one finished match into the live set. Called from resolveMatchResult
// (never during resimulation). The announcer layers ride the wave-9 pattern:
// scheduled past the KO call, gated on the round-over scene still playing.
function foldSetResult(winner) {
  const set = activeSetState();
  if (!set || set.length <= 1) return;
  const matchKey = state.mode === "online"
    ? String(onlineSession.matchConfig?.matchId || "")
    : `serial-${state.matchSerial}`;
  const summary = recordSetWin(set, winner === 1 ? 1 : 0, {
    matchKey,
    picks: [state.fighters[0]?.def.id || "", state.fighters[1]?.def.id || ""],
    rounds: [...state.rounds],
  });
  if (!summary) return;
  netFxDebug.setFolds += 1;
  if (state.mode === "online") persistOnlineResume(false);
  if (summary.complete) {
    netFxDebug.setWins += 1;
  } else if (summary.setPoint[0] || summary.setPoint[1]) {
    // Wave-9 setpoint bank: someone is now one MATCH from taking the set.
    netFxDebug.setPointCallouts += 1;
    announcerSay("setpoint", { delay: 2700 });
    scheduleFightAnnouncement(() => {
      if (state.screen === "fight" && state.phase === "roundover") {
        const side = summary.setPoint[0] && summary.setPoint[1] ? -1 : summary.setPoint[0] ? 0 : 1;
        const names = setSideNames();
        announce("SET POINT", side < 0 ? "EITHER FIGHTER CAN CLOSE IT OUT" : `${names[side]} CAN TAKE THE SET`, 1.6);
      }
    }, 3050);
  }
}

// The winner-stays scoreboard card on the result screen. Shows whenever the
// finished match belongs to a live FT set (online or offline versus).
function renderSetScoreCard() {
  const card = $("#setScoreCard");
  if (!card) return;
  const set = activeSetState();
  const summary = set && set.length > 1 ? setSummary(set) : null;
  card.hidden = !summary;
  if (!summary) return;
  const names = setSideNames();
  const champion = summary.complete ? summary.winnerSide : -1;
  $("#setScoreTitle").textContent = champion >= 0
    ? `SET CHAMPION · ${names[champion]}`
    : summary.setPoint[0] || summary.setPoint[1] ? "SET POINT · WINNER STAYS" : "WINNER STAYS";
  $("#setScoreLine").innerHTML = `
    <b class="${champion === 0 ? "champ" : ""}">${names[0]}</b>
    <span>${summary.scores[0]} — ${summary.scores[1]}</span>
    <b class="${champion === 1 ? "champ" : ""}">${names[1]}</b>`;
  $("#setScoreSub").textContent = `FIRST TO ${summary.length} · ${summary.history.length} MATCH${summary.history.length === 1 ? "" : "ES"} PLAYED`;
  $("#setScorePips").innerHTML = summary.history
    .map((entry) => `<i class="${entry.winner === 0 ? "left" : "right"}"></i>`)
    .join("");
  card.classList.toggle("champion", champion >= 0);
  if (champion >= 0) {
    // Set-winner celebration: banner + card shine, one-shot per set end.
    announce("SET CHAMPION", `${names[champion]} TAKES THE SET ${summary.scores[0]}–${summary.scores[1]}`, 1.8);
    restartCssAnimation(card, "crowned");
  }
}

function makeFighter(index, side, overrideDef = null) {
  const def = overrideDef || roster[index];
  // v2.9 critic round 2 (B3): the one choke point every match-start path runs
  // through — versus, arcade, survival, team, online, replay rebuild and the
  // QA probes. Warming here means both authored sheets are decoding through
  // the intro walk-on instead of missing on the first authored beat of round
  // one. Idempotent, so the rollback rebuild path costs a map lookup.
  preloadAuthoredBanks([def.id]);
  const kitId = def.kitId || def.id;
  const kit = getFighterKit(kitId);
  // Release 1.8 GRIND: the Turbo mutator scales walk/dash speeds here, at
  // build time. Movement is a derived-from-config reference (never cloned by
  // the rollback snapshot), and mutators are constant for the whole match, so
  // a rollback rebuild derives the identical object.
  const movement = scaleMovementForRules(getFighterMovement(kitId, MOVEMENT_RULES), state.matchRules);
  const fighter = {
    def,
    kitId,
    kit,
    movement: def.boss ? {
      ...movement,
      walkForward: movement.walkForward * 1.04,
      walkBack: movement.walkBack * 1.04,
      dashSpeed: movement.dashSpeed * 1.03,
    } : movement,
    side,
    x: FIGHTER_HOME_X[side],
    y: FLOOR,
    vx: 0,
    vy: 0,
    width: Math.round(92 * FIGHTER_SCALE),
    height: Math.round(196 * FIGHTER_SCALE),
    facing: side === 0 ? 1 : -1,
    health: 100,
    meter: 0,
    grounded: true,
    crouch: false,
    block: false,
    guarding: false,
    guardHeight: "high",
    attacking: null,
    attackTime: 0,
    attackFrame: 0,
    attackHit: false,
    attackHits: 0,
    attackSerial: 0,
    lastAttackHitFrame: -Infinity,
    lastDamageFrame: -Infinity,
    attackConnected: "",
    armorHits: 0,
    counterTriggered: false,
    trapDeployed: false,
    projectileSpawnFrames: new Set(),
    rhythmStacks: 0,
    rhythmExpiresFrame: 0,
    rhythmLastAttackSerial: -1,
    cancelledFrom: "",
    linkedFrom: "",
    linkWindow: null,
    confirmWindowFrames: 0,
    juggleCount: 0,
    combo: new ComboTracker(),
    stun: 0,
    hitstunFrames: 0,
    blockstunFrames: 0,
    knockdownFrames: 0,
    wakeupFrames: 0,
    invulnerableFrames: 0,
    reversalWindowFrames: 0,
    throwInvulnerableFrames: 0,
    pendingKnockdown: false,
    landingRecoveryFrames: 0,
    dashFrames: 0,
    dashCooldownFrames: 0,
    attackRearmFrames: 0,
    // v5.1 TEMPO TELLS: the last whiff (tick, tax and re-arm lengths) and the
    // tick of the last press the re-arm gap ate. Plain sim fields, rollback-
    // cloned like attackRearmFrames; read by both renderers through
    // whiffTellState() and by the training lab, never by the sim itself.
    whiffTell: null,
    rearmDropTick: -Infinity,
    // BLOCK ECONOMY: blocked special-into-special cancels spent in the
    // current string (reset by any non-cancel attack start) and whether the
    // guard input was held last tick, for the Perfect Guard tap re-arm. Both
    // are plain sim fields, so the rollback snapshot carries them for free.
    blockedSpecialCancels: 0,
    guardInputHeld: false,
    dashDirection: 0,
    queuedDashDirection: 0,
    directionTapTracker: new DirectionTapTracker(),
    previousDirectionalInput: { left: false, right: false },
    justWoke: false,
    throwTechFlashFrames: 0,
    // Release 1.8 GRIND: Block War walk-in target during the intro (plain
    // data — snapshot-cloned like every other fighter field; null when idle).
    introWalkTarget: null,
    // Personal throwable ammunition, refreshed at the start of every round.
    throwableUses: throwableUses(kitId),
    throwableSpawned: false,
    carriedWeapon: null,
    carryFrames: 0,
    slowFrames: 0,
    // Dizzy meter and its deterministic decay / recovery / immunity clocks.
    stunMeter: 0,
    stunDecayDelay: 0,
    dizzyFrames: 0,
    dizzyTotalFrames: 0,
    stunImmuneFrames: 0,
    dizzyMashCount: 0,
    // Release 1.7 DEPTH: guard gauge / wake-up option / air recovery /
    // Perfect Guard fields. All plain data, so the rollback fighter snapshot
    // (which clones every enumerable non-reference field) captures each one
    // and every one counts toward the combat checksum.
    ...createDepthFighterFields(),
    // Release 1.7 wave 11: wall-bounce latches + taunt clocks + the
    // double-tap-Down tracker, on the same plain-data snapshot contract.
    ...createOffenseFighterFields(),
    // Live grab sequence state. `grabbing` is set on the thrower and `grabbed` on
    // the victim; both are plain data so rollback snapshots clone them directly.
    grabbing: null,
    grabbed: null,
    lastThrowInputFrame: -Infinity,
    // 5.3 CLOSE RANGE: did the knockdown this fighter is in come from a THROW?
    // Plain boolean, so the rollback snapshot carries it for free. Decides
    // which throw immunity the wake tick pays (40 frames after a throw so a
    // throw loop is impossible; 8 after a strike so okizeme exists).
    throwKnockdown: false,
    lastHitResult: "",
    // v5.1 EXT4 ROUTING: the attack LEVEL of the last contact, kept apart from
    // lastHitResult because that string drops the level on a counter hit
    // ("counter") and the reaction drawing needs it on every hit: a MID/LOW
    // opens on the body blow, anything else on the head snap. Presentation
    // data — it chooses a drawing, never a sim outcome — so it is snapshotted
    // with lastHitResult and stays out of the combat checksum like it.
    lastHitLevel: "",
    hitFlash: 0,
    specialGlow: 0,
    animTime: visualRandom() * 2,
    walkTime: visualRandom(),
    // v3.5 BACK-WALK: the SIGNED, speed-scaled stride clock the sprite walk
    // cycle rides (see strideClockAdvance in engine/fighter-kits.mjs). Seeded
    // from `walkTime` just below the literal, so the two fighters start out of
    // phase with each other exactly as they always have and a full-speed
    // forward walk keeps the shipped cadence byte-for-byte.
    strideTime: 0,
    cinematicFrame: null,
    cinematicRotation: 0,
    cinematicScale: 1,
    down: false,
    aiClock: 0,
    aiBrain: createAiBrain(state.mode === "demo" ? DEMO_AI_DIFFICULTY : state.aiDifficulty),
    combatState: FIGHTER_STATES.IDLE,
    previousCombatState: FIGHTER_STATES.IDLE,
    stateFrame: 0,
    stateEnteredTick: state.simulationTick,
    inputBuffer: new FrameInputBuffer(DEFAULT_INPUT_BUFFER_FRAMES),
  };
  // v3.5 BACK-WALK: the stride clock starts on the key `walkTime` would have
  // put it on. Assigned AFTER the literal on purpose — drawing its own
  // visualRandom() here would consume an extra value from the seeded visual
  // stream and shift every downstream visual phase in the match.
  fighter.strideTime = fighter.walkTime;
  return fighter;
}

let rollbackResimulating = false;
// Eased super-flash darkness. Module-level and render-only: it never enters a
// rollback snapshot, so a resimulation just re-eases it harmlessly.
let superDimLevel = 0;
// True while drawFighterReflections re-runs drawFighter into the floor sheen
// band; the mirror pass skips the extra silhouette/ghost copies so it stays a
// single sprite draw per fighter.
let reflectionPassActive = false;
// Per-rendered-frame counters for the fighter presentation passes, exposed via
// snapshot().violence for QA smoke tests. Reset at the top of each fight frame
// in draw(); reflection-pass copies are deliberately excluded.
const presentationDebug = {
  rimLights: 0, hitSmears: 0, dizzyGhosts: 0, breathing: 0,
  contactShadows: 0, gritAuras: 0, lastLegs: 0,
  battleDamage: 0, castShadows: 0,
  // 1.9E: the effective sprite mirror last used per side — numeric facing ×
  // authored atlas facing — so QA can prove a mixed-orientation sheet (post)
  // renders toward the opponent instead of trusting numeric facing alone.
  lastFighterMirror: [null, null],
  practicalLights: 0, weatherParticles: 0, foregroundOccluders: 0, crowdFlashes: 0,
  counterFlashes: 0, projectileGlows: 0, swipeRibbons: 0, wallSplats: 0,
  focusLines: 0, lightSpills: 0,
  // v2.6 MOTION steady per-frame passes (2D draw path).
  squashStretchFrames: 0, poseCrossfades: 0, attackSmears: 0,
  // v2.9 FLOW: motion2 cells actually drawn this frame (per side), so probes
  // can prove a transition key rendered at its beat rather than trusting the
  // descriptor alone.
  motion2Cells: 0,
  // v2.9 round 4: the same count broken out PER CELL INDEX, cumulative across
  // the session rather than per frame, so a probe can ask the only honest
  // question about an authored transition key — "did cell N ever reach the
  // screen, and for how many draws?" — instead of trusting a beat counter that
  // watches a sim edge. Instrumentation only: nothing reads this back into the
  // sim, the choreographer or any pose decision.
  motion2CellDraws: {},
  // v2.10 WALK: walk-bank keys actually drawn this frame, and the last key
  // index each side rendered, so a QA burst can prove the cycle ADVANCED
  // 0→1→2→3 rather than trusting the descriptor alone.
  walkCells: 0,
  lastWalkKey: [null, null],
  // v2.9 final round (R9/T6): draw-site instrumentation. reactionDrawPriority
  // counts the frames the reacting fighter was promoted above the attacker in
  // the pair sort; turnaroundDraws / turnaroundBlocked are the TURNAROUND
  // audit — the first counts real draws of motion2:5, the second tallies WHY
  // the latch was live and the cell still did not reach the screen, keyed by
  // the branch that outranked it. Both cumulative across the session, both
  // instrumentation only.
  reactionDrawPriority: 0,
  turnaroundDraws: 0,
  turnaroundBlocked: {},
  // MOTION FIX 7: flip-path arc ribbon frames (2D world pass).
  arcRibbons: 0,
  // Wave 7 steady screen-space passes, counted per rendered frame.
  bloomPasses: 0, rgbSplits: 0,
  // Release 1.8C REALITY BREAK steady render-only passes.
  realisticBackdrops: 0, realisticLighting: 0, realisticPortraits: 0, filmGrainPasses: 0,
  // CINEMA 3D gameplay reads drawn by the 2D overlay pass while the 3D world
  // is live (dizzy/crush markers, rhythm rings, combat text, weapon tag), so a
  // probe can prove a read reached the screen in 3D rather than trusting the
  // sim field alone.
  cinema3dOverlayReads: 0,
  // v5.1 TEMPO TELLS: per-frame draws of the whiff fringe, the extension-cell
  // ghosts, the re-arm flash and the eaten-press flash (2D draw path), so a
  // probe can prove a whiff produced a tell rather than trusting the sim
  // field alone.
  whiffFringes: 0, whiffGhosts: 0, rearmFlashes: 0, rearmDropFlashes: 0,
  // 5.3 OKIZEME: wake-up vulnerable rims drawn THIS FRAME (presentationDebug
  // is zeroed every rendered frame — these are per-frame draw counts, unlike
  // the monotonic mechFxDebug/audioFxDebug totals beside them in oki()).
  wakeupTells: 0,
};

// Release 1.7A CLEAN HITS: preserve the fighter palette during hit feedback.
// Hitstop, particles, camera recoil and sound still carry the impact; this
// short brightness lift replaces the old desaturated/inverted silhouette.
const HIT_FLASH_FILTER = "brightness(1.55) saturate(1.12)";
// Grit super-ready flare latches, one per side. Render-only module state on the
// superDimLevel pattern: never snapshotted, only ever read/written from the
// draw path, so rollback resimulation cannot touch it.
const gritFlareLevel = [0, 0];
const gritReadyLatched = [false, false];
// v5.1 TEMPO TELLS: the extension cell each side was drawing when its swing
// whiffed, so the re-arm gap can show that cell falling away behind the
// idle body. Render-only, same class of state as gritReadyLatched.
const whiffGhostCells = [null, null];
// Accumulating battle damage: MK3-style bruise/cut smudges baked onto each
// fighter's sprite. Module-level per-side arrays on the superDimLevel pattern —
// render-only, never snapshotted, so rollback checksums are untouched. Mark
// creation is resimulation-proof twice over: pushes bail while
// rollbackResimulating (the announce() pattern) AND dedupe against the
// simulationTick stored on each mark, so no (tick, side) pair can ever
// double-mark even if a hit tick is executed twice.
const BATTLE_DAMAGE_MARK_CAP = 10;
const battleDamageMarks = [[], []];
// Bumped on every push/clear so the compositor cache key invalidates cheaply.
const battleDamageRevision = [0, 0];

function pushBattleDamageMark(victim, tier = "light") {
  if (rollbackResimulating) return;
  const side = victim?.side;
  if (side !== 0 && side !== 1) return;
  const marks = battleDamageMarks[side];
  if (marks.some((mark) => mark.tick === state.simulationTick)) return;
  const heavy = tier !== "light";
  // Cell-space (320px atlas cell) coordinates biased to the head/torso bands.
  const band = visualRandom() < 0.38
    ? { top: 48, span: 60 }
    : { top: 112, span: 94 };
  marks.push({
    tick: state.simulationTick,
    x: 160 + (visualRandom() - 0.5) * 104,
    y: band.top + visualRandom() * band.span,
    size: (heavy ? 14 : 9) + visualRandom() * (heavy ? 12 : 7),
    cut: heavy && visualRandom() < 0.6,
    lean: (visualRandom() - 0.5) * 1.6,
  });
  if (marks.length > BATTLE_DAMAGE_MARK_CAP) marks.shift();
  battleDamageRevision[side] += 1;
}

function clearBattleDamage() {
  battleDamageMarks[0].length = 0;
  battleDamageMarks[1].length = 0;
  battleDamageRevision[0] += 1;
  battleDamageRevision[1] += 1;
}

// ---------------------------------------------------------------------------
// v2.6 MOTION — the classic 2D-fighter movement-animation layer.
// Jump flips, squash & stretch, pose cross-fades, attack smears, ground work
// (dash plumes / skid smoke / landing rings / crack flashes) and recovery
// wobble. ALL of it is presentation: the flip/stretch transforms are pure
// functions of already-snapshotted sim fields (vy, y, vx, grounded, movement
// constants), and the event latches live in module-level render-only observer
// state on the documented superDimLevel pattern — written exclusively from
// the render loop (updateMotionObservers runs in draw(), which never executes
// during rollback resimulation), so checksums and resim are untouched.
// Consumed by BOTH renderers: drawFighter applies the transform directly and
// the CINEMA 3D poseRig reads the same fighterMotionTransform via the bridge.
// ---------------------------------------------------------------------------
const MOTION_RULES = Object.freeze({
  crossfadeFrames: 3,        // sim-tick-paced pose cross-fade length
  landSquashFrames: 4,       // landing impact squash duration
  wobbleFrames: 10,          // hit-recoil settle after hitstun ends
  jumpDirThreshold: 60,      // |vx| that reads as a directional jump
  skidSpeed: 230,            // grounded |vx| that arms a reversal skid
  skidCooldown: 10,          // ticks between skid puffs per side
  crackFallSpeed: 940,       // fall speed that earns the ground-crack flash
  // v2.9 critic round 2 (M2): grounded |vx| below which the dash brake key
  // finally releases to the upright idle. The 2.9 read released the tick the
  // dash counter hit zero, with 622px/s still on the clock.
  dashBrakeReleaseSpeed: 150,
  // v2.9 final round (T6): ticks an AIRBORNE facing flip stays pending
  // before it fires the grounded pivot on touchdown. Long enough to cover
  // the descent of a cross-up jump, short enough that a flip which never
  // lands cleanly (round end, a mid-air knockdown) cannot pivot late.
  turnPendingFrames: 34,
  // v2.9 critic round 2 (M2): ticks of dash-exit latch. The brake must cover
  // the velocity decay rather than handing to a frame of walk — but it must
  // not become a hold of its own either, so it is capped at the 2.9 value and
  // the speed gate below releases it early when the fighter has actually
  // stopped.
  dashExitFrames: 4,
});

// v2.9 critic round 2 (B7): height off the street, in world px, at which a
// throw victim is genuinely AIRBORNE and may wear the horizontal hurl key.
// Roughly half a body — above the attacker's knee-and-shin volume, which is
// where the 18px gate was drawing him.
const THROW_HURL_LIFT_PX = Math.round(96 * FIGHTER_SCALE);

// v2.9 critic round 2 (B1): ticks the throw attacker's recovery track is paced
// over, clocked by the motion observer rather than the frozen attack timeline.
const THROW_RECOVERY_RENDER_TICKS = 20;
// Monotonic one-shot totals on the hudFxDebug pattern (never reset), exposed
// via snapshot().violence for orchestrator smoke tests.
const motionFxDebug = { jumpFlips: 0, skidSmokes: 0, landingDust: 0, bankPreloads: 0 };
// Render-frame gate: motion observers advance their frame counters only when
// the simulation actually ticked, so 120Hz displays and QA manual stepping
// both pace the latches in sim frames.
let motionLastObservedTick = -1;

function createMotionObserver() {
  return {
    fighterId: null,
    wasGrounded: true, prevVy: 0, prevVx: 0, prevHitstun: 0, prevDashFrames: 0,
    // Jump-flip latch: armed at a CONTROLLED launch, cancelled by any hit /
    // air attack, cleared on landing. flipSpin is the world-space spin sign.
    flipEligible: false, flipKind: "neutral", flipSpin: 1, airAttackLatch: false,
    landFrames: 0, landMag: 0,
    // MOTION FIX 7: a flip landing earns a deeper touchdown compress + foot
    // dust — latched from flipEligible the tick the feet plant.
    flipLandFrames: 0,
    wobbleFrames: 0,
    leanLevel: 0,
    skidCooldown: 0, dashPuffClock: 0,
    // MOTION FIX 8: ticks since the dash push-off, for the early torso lean
    // (head leads, ~12° over dash frames 2-4) and the stride stretch.
    dashAge: -1,
    // v2.9 critic round (m2): ticks of dash-exit walk suppression, so the
    // authored brake key hands straight to idle instead of flashing a single
    // frame of walk on the residual velocity.
    dashExitFrames: 0,
    // BODY-FIRST (spec 5): ticks since a controlled takeoff — the directional
    // flip's 2-tick launch stretch-smear reads this. -1 = grounded.
    launchAge: -1,
    // BODY-FIRST (spec 9): 3-tick rear-up gesture as the Devil's hex charm
    // leaves the claw; charmCount detects the projectile's spawn tick.
    castFrames: 0, charmCount: 0,
    // MOTION FIX 4: swipe ribbons dissipate within ~9 ticks of first contact
    // instead of holding frozen through hitstop. 1 = live, eases to 0.
    ribbonFade: 1,
    // Pose cross-fade bookkeeping (2D draw path only).
    poseBank: null, poseFrame: -1, fadeBank: null, fadeFrame: -1, fadeLeft: 0,
    // v2.9 FLOW transition latches (tick-paced, render-only): remaining ticks
    // on the authored turnaround pivot key and the crouch enter/leave
    // in-between. prevFacing 0 / prevCrouch null mean "not yet observed".
    prevFacing: 0, turnFrames: 0, turnPending: 0, prevCrouch: null, crouchTransFrames: 0,
    // v2.9 final round (R5): the wake-up SETTLE. wakeLastRung remembers the
    // cell the rise ended on (the drawn one, after the accept mask), so the
    // standing cell can arrive at exactly that height and ease out of it.
    prevWakeup: 0, wakeLastRung: null, wakeSettleFrames: 0, wakeSettleStart: 1,
    // v2.9 critic round 2 (B1): the blockstun window's LENGTH, latched the
    // tick it opens, so the blockstun key track has a denominator. Render-only
    // observer state on the documented pattern — never read by the sim, never
    // advanced during rollback resimulation.
    blockstunTotal: 0,
    // Ticks since a throw's clinch RELEASED. attackFrame and attackTime are
    // both frozen through the throw's cinematic, so neither can pace the
    // attacker's recovery — which is why one kit cell owned 25 ticks of it.
    // -1 = not in a throw recovery.
    throwRecoverFrames: -1,
  };
}
const motionObs = [createMotionObserver(), createMotionObserver()];
// Reusable transform results — fighterMotionTransform runs up to three times
// per fighter per frame (main pass, reflection pass, 3D rig), so it writes
// into these persistent scratches instead of allocating.
const motionScratch = [
  { rotation: 0, flipRotation: 0, scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0, stretchActive: false },
  { rotation: 0, flipRotation: 0, scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0, stretchActive: false },
];

function resetMotionObserver(obs) {
  const fresh = createMotionObserver();
  for (const key of Object.keys(fresh)) obs[key] = fresh[key];
}

// Smootherstep ease shared by the flip arcs: zero-velocity endpoints so the
// sprite leaves the ground upright and lands upright, with the rotation
// concentrated through the middle of the arc (the "tuck").
function motionEase01(edge0, edge1, value) {
  const t = clamp((value - edge0) / (edge1 - edge0), 0, 1);
  return t * t * t * (t * (t * 6 - 15) + 10);
}

// MOTION FIX 8: dash push-off dust is TWO discrete backward puffs — tight
// irregular clumps kicked off the launch foot at staggered distances — not a
// homogeneous spray. Render-path spawn into checksum-exempt state.particles.
function spawnMotionDashPlume(fighter) {
  const forward = fighter.dashDirection || fighter.facing;
  const perClump = Math.max(2, Math.round(4 * state.performance.particleScale));
  for (let clump = 0; clump < 2; clump += 1) {
    // Each clump shares one base position + velocity so it reads as a single
    // kicked lump of street dust, with per-mote jitter for the ragged edge.
    const clumpX = fighter.x - forward * (14 + clump * 30 + visualRandom() * 10);
    const clumpVx = -forward * (120 + clump * 90 + visualRandom() * 60);
    const clumpVy = -55 - clump * 30 - visualRandom() * 40;
    for (let mote = 0; mote < perClump; mote += 1) {
      state.particles.push({
        kind: "dust",
        x: clumpX + (visualRandom() - 0.5) * 12,
        y: FLOOR - 2 - visualRandom() * 8,
        vx: clumpVx * (0.8 + visualRandom() * 0.4),
        vy: clumpVy * (0.7 + visualRandom() * 0.6),
        gravity: 340,
        drag: 0.93,
        life: 0.3 + clump * 0.08 + visualRandom() * 0.22,
        max: 0.6,
        size: 4.5 + visualRandom() * (7 - clump * 2),
        color: visualRandom() > 0.4 ? "#7c756b" : "#524d48",
      });
    }
  }
  // MOTION FIX 12: mirror the push-off dust into the CINEMA 3D layer.
  if (cinema3dBridge.onDust) {
    cinema3dBridge.onDust({ x: fighter.x - forward * 24, y: FLOOR - 4, force: 0.8, direction: -forward });
  }
}

// Skid smoke (spec 5): pale drifting puffs when a grounded fighter reverses
// direction at speed — the feet fighting the old momentum.
function spawnMotionSkidSmoke(fighter, previousVx) {
  const skidDir = Math.sign(previousVx) || fighter.facing;
  const total = Math.max(3, Math.round(8 * state.performance.particleScale));
  for (let index = 0; index < total; index += 1) {
    state.particles.push({
      kind: "dust",
      x: fighter.x + skidDir * (6 + visualRandom() * 30),
      y: FLOOR - 3 - visualRandom() * 8,
      vx: skidDir * (60 + visualRandom() * 150),
      vy: -50 - visualRandom() * 95,
      gravity: 220,
      drag: 0.93,
      life: 0.3 + visualRandom() * 0.34,
      max: 0.64,
      size: 6 + visualRandom() * 8,
      color: visualRandom() > 0.35 ? "#8a8378" : "#6b655e",
    });
  }
  motionFxDebug.skidSmokes += 1;
}

// MOTION FIX 6: landing dust is 3-4 IRREGULAR CLUMPS kicking outward and
// settling — the clean vector shockRing ellipse is gone (a perfect ring read
// as a decal, not dust). Each clump is a handful of motes sharing a base
// trajectory; a violent fall still adds the crack flash in the stage-scar
// visual language (chalky scuff, pale chipped edge, dark crack) that fades
// out completely — no scar persistence, presentation only.
function spawnMotionLandingDust(fighter, fallSpeed, heavy = false) {
  const force = clamp(fallSpeed / 760, 0.45, 1.6) * (heavy ? 1.2 : 1);
  const clumps = 3 + (visualRandom() < 0.5 ? 1 : 0);
  const perClump = Math.max(2, Math.round(3 * state.performance.particleScale));
  for (let clump = 0; clump < clumps; clump += 1) {
    // Alternate sides, ragged reach: clumps kick OUT along the floor line and
    // settle under their own gravity — no two landings share a silhouette.
    const side = clump % 2 ? 1 : -1;
    const reach = 10 + visualRandom() * 30 + clump * 7;
    const clumpVx = side * (80 + visualRandom() * 150) * force;
    // BODY-FIRST (spec 4): the kick-up reaches KNEE height — the old
    // -40..-130 launch died at ankle level and read as floor noise.
    const clumpVy = (-110 - visualRandom() * 130) * force;
    for (let mote = 0; mote < perClump; mote += 1) {
      state.particles.push({
        kind: "dust",
        x: fighter.x + side * reach + (visualRandom() - 0.5) * 14,
        y: FLOOR - 2 - visualRandom() * 5,
        vx: clumpVx * (0.75 + visualRandom() * 0.5),
        vy: clumpVy * (0.6 + visualRandom() * 0.7),
        gravity: 360,
        drag: 0.92,
        life: 0.3 + visualRandom() * 0.34,
        max: 0.64,
        size: 3.5 + visualRandom() * (8 - clump),
        color: visualRandom() > 0.4 ? "#7c756b" : "#4e4a46",
      });
    }
  }
  if (heavy && state.performance.trailScale > 0 && !state.accessibility.reducedMotion) {
    // Crack polyline built once at spawn (same construction as pushStageScar,
    // squashed into the floor perspective) — the draw pass just strokes it.
    const points = [[0, 0]];
    const segments = 4 + Math.floor(visualRandom() * 2);
    const baseAngle = visualRandom() * Math.PI * 2;
    let px = 0;
    let py = 0;
    for (let index = 0; index < segments; index += 1) {
      const angle = baseAngle + (visualRandom() - 0.5) * 1.9;
      const length = 12 + visualRandom() * 26;
      px += Math.cos(angle) * length;
      py += Math.sin(angle) * length * 0.34;
      points.push([px, py]);
    }
    state.effects.push({
      kind: "groundCrackFlash", x: fighter.x, y: FLOOR + 7,
      life: 0.36, max: 0.36, color: "#efe6d4", points,
      scuffW: 34 + force * 26 + visualRandom() * 14,
      scuffH: 6 + visualRandom() * 5,
      rot: (visualRandom() - 0.5) * 0.5,
    });
  }
  // MOTION FIX 12: mirror landing dust into the CINEMA 3D layer.
  if (cinema3dBridge.onDust) {
    cinema3dBridge.onDust({ x: fighter.x, y: FLOOR - 4, force, direction: 0 });
  }
  motionFxDebug.landingDust += 1;
}

// BODY-FIRST (spec 6): dash-stop dust slide — a low, forward-dragged smear of
// motes as the feet bite at the end of the dash (the launch already gets the
// two-puff plume; this is its closing bracket).
function spawnMotionDashStopSlide(fighter) {
  const forward = fighter.dashDirection || fighter.facing;
  const total = Math.max(2, Math.round(4 * state.performance.particleScale));
  for (let mote = 0; mote < total; mote += 1) {
    state.particles.push({
      kind: "dust",
      x: fighter.x + forward * (8 + visualRandom() * 14),
      y: FLOOR - 1 - visualRandom() * 3,
      vx: forward * (90 + visualRandom() * 120),
      vy: -8 - visualRandom() * 22,
      gravity: 260,
      drag: 0.88,
      life: 0.2 + visualRandom() * 0.16,
      max: 0.36,
      size: 3 + visualRandom() * 4,
      color: visualRandom() > 0.5 ? "#7c756b" : "#575249",
    });
  }
}

// MOTION FIX 7: flip touchdown foot dust — two small puffs squeezed straight
// out from under the planted feet on the compress frame, tighter and lower
// than the landing clumps so the read is "feet slap the street".
function spawnMotionFlipFootDust(fighter) {
  const perFoot = Math.max(2, Math.round(3 * state.performance.particleScale));
  for (let foot = 0; foot < 2; foot += 1) {
    const side = foot ? 1 : -1;
    for (let mote = 0; mote < perFoot; mote += 1) {
      state.particles.push({
        kind: "dust",
        x: fighter.x + side * (10 + visualRandom() * 8),
        y: FLOOR - 1 - visualRandom() * 3,
        vx: side * (50 + visualRandom() * 90),
        vy: -14 - visualRandom() * 34,
        gravity: 300,
        drag: 0.9,
        life: 0.2 + visualRandom() * 0.18,
        max: 0.38,
        size: 3 + visualRandom() * 4,
        color: visualRandom() > 0.5 ? "#8a8378" : "#5c5750",
      });
    }
  }
}

// Per-rendered-frame motion observation. Runs once at the top of draw() —
// BEFORE either renderer consumes the transforms — and advances its frame
// counters only on sim-tick edges so render rate never changes the pacing.
function updateMotionObservers() {
  if (state.screen !== "fight" || state.fighters.length < 2) {
    motionObs.forEach(resetMotionObserver);
    motionLastObservedTick = -1;
    return;
  }
  const tickAdvanced = state.simulationTick !== motionLastObservedTick;
  motionLastObservedTick = state.simulationTick;
  if (!tickAdvanced) return;
  const reducedMotion = state.accessibility.reducedMotion;
  for (let side = 0; side < 2; side += 1) {
    const fighter = state.fighters[side];
    const obs = motionObs[side];
    if (obs.fighterId !== fighter.def.id) {
      resetMotionObserver(obs);
      obs.fighterId = fighter.def.id;
      obs.wasGrounded = fighter.grounded;
      obs.prevVy = fighter.vy;
      obs.prevVx = fighter.vx;
    }
    const controlled = fighter.hitstunFrames === 0 && !fighter.down
      && !fighter.pendingKnockdown && !fighter.grabbed && fighter.dizzyFrames === 0
      && fighter.airTechFlipFrames === 0 && fighter.cinematicFrame === null;
    // --- Jump launch: arm the flip on a controlled leap ---------------------
    if (!fighter.grounded && obs.wasGrounded && fighter.vy < 0 && controlled && !fighter.attacking) {
      const jumpDir = Math.abs(fighter.vx) > MOTION_RULES.jumpDirThreshold ? Math.sign(fighter.vx) : 0;
      obs.flipKind = jumpDir === 0 ? "neutral" : jumpDir === fighter.facing ? "forward" : "back";
      obs.flipSpin = obs.flipKind === "back" ? -fighter.facing : fighter.facing;
      obs.flipEligible = !reducedMotion;
      obs.airAttackLatch = false;
      obs.launchAge = 0;
      if (obs.flipEligible) motionFxDebug.jumpFlips += 1;
      // MOTION FIX 12: takeoff dust in both renderers — a small squeeze of
      // street dust under the launch, mirrored into the 3D layer.
      if (state.phase === "fight" && !reducedMotion) {
        spawnMotionFlipFootDust(fighter);
        if (cinema3dBridge.onDust) {
          cinema3dBridge.onDust({ x: fighter.x, y: FLOOR - 4, force: 0.6, direction: 0 });
        }
      }
    }
    // An air attack snaps the sprite upright for the REST of the arc — no
    // rotation pops back in after the recovery (readability rule).
    if (!fighter.grounded && fighter.attacking) obs.airAttackLatch = true;
    // Getting hit / grabbed out of the jump cancels the flip outright.
    if (!fighter.grounded && !controlled) obs.flipEligible = false;
    else if (!fighter.grounded && obs.launchAge >= 0 && !obs.wasGrounded) obs.launchAge += 1;
    // --- Landing ------------------------------------------------------------
    if (fighter.grounded && !obs.wasGrounded) {
      const fallSpeed = Math.max(0, obs.prevVy);
      // "Heavy landing": slamming down out of an air attack (the latch is
      // still live here) or a faster-than-any-jump fall — earns the crack
      // flash tier inside spawnMotionLandingDust.
      const heavyLanding = obs.airAttackLatch || fallSpeed > MOTION_RULES.crackFallSpeed;
      obs.landFrames = MOTION_RULES.landSquashFrames;
      obs.landMag = clamp(fallSpeed / 760, 0.55, 1.4);
      // MOTION FIX 7: a landing out of a live flip gets the touchdown
      // compress read — 2 ticks of deeper squash plus foot dust — so a
      // distinct "feet plant" frame sits between airborne and standing.
      if (obs.flipEligible && !reducedMotion) {
        obs.flipLandFrames = 2;
        if (fighter.hitstunFrames === 0 && !fighter.down && !fighter.pendingKnockdown
          && state.phase === "fight") {
          spawnMotionFlipFootDust(fighter);
        }
      }
      obs.flipEligible = false;
      obs.airAttackLatch = false;
      obs.launchAge = -1;
      // Controlled landings get the dust clumps; knockdown slams already carry
      // their own impact spectacle (spawnKnockdownImpact + stage scar), so
      // those stay theirs.
      if (fighter.hitstunFrames === 0 && !fighter.down && !fighter.pendingKnockdown
        && state.phase === "fight") {
        spawnMotionLandingDust(fighter, fallSpeed, heavyLanding);
      }
    } else {
      if (obs.landFrames > 0) obs.landFrames -= 1;
      if (obs.flipLandFrames > 0) obs.flipLandFrames -= 1;
    }
    // --- Skid smoke on grounded direction reversals at speed ----------------
    if (obs.skidCooldown > 0) obs.skidCooldown -= 1;
    if (fighter.grounded && obs.wasGrounded && obs.skidCooldown === 0
      && Math.abs(obs.prevVx) > MOTION_RULES.skidSpeed
      && Math.sign(fighter.vx) === -Math.sign(obs.prevVx)
      && Math.abs(fighter.vx) > 100 && state.phase === "fight") {
      spawnMotionSkidSmoke(fighter, obs.prevVx);
      obs.skidCooldown = MOTION_RULES.skidCooldown;
    }
    // --- Dash plume + rolling dash dust -------------------------------------
    if (fighter.dashFrames > 0 && obs.prevDashFrames <= 0 && state.phase === "fight") {
      spawnMotionDashPlume(fighter);
      obs.dashPuffClock = 0;
      obs.dashAge = 0;
    } else if (fighter.dashFrames > 0 && state.phase === "fight") {
      obs.dashAge += 1;
      obs.dashPuffClock += 1;
      if (obs.dashPuffClock % 3 === 0 && state.performance.particleScale > 0.4) {
        state.particles.push({
          kind: "dust",
          x: fighter.x - (fighter.dashDirection || fighter.facing) * (14 + visualRandom() * 18),
          y: FLOOR - 2,
          vx: -(fighter.dashDirection || fighter.facing) * (50 + visualRandom() * 110),
          vy: -20 - visualRandom() * 60,
          gravity: 320,
          drag: 0.94,
          life: 0.18 + visualRandom() * 0.2,
          max: 0.38,
          size: 3.5 + visualRandom() * 5,
          color: "#6f6961",
        });
      }
      // MOTION FIX 8: accent ember trail shed off the TORSO line (hip to
      // shoulder), not just the feet — 1-2 hot motes per tick streaming
      // backward so the dash carries a body-height speed read.
      if (!reducedMotion && state.performance.particleScale > 0.4) {
        const back = -(fighter.dashDirection || fighter.facing);
        const embers = 1 + (obs.dashAge % 2);
        for (let ember = 0; ember < embers; ember += 1) {
          state.particles.push({
            kind: "sparkLine",
            x: fighter.x + back * (16 + visualRandom() * 26),
            y: fighter.y - fighter.height * (0.35 + visualRandom() * 0.45),
            vx: back * (140 + visualRandom() * 180),
            vy: (visualRandom() - 0.4) * 70,
            gravity: 60, drag: 0.9,
            life: 0.12 + visualRandom() * 0.14, max: 0.26,
            size: 1.2 + visualRandom() * 1.8,
            color: ember % 2 ? fighter.def.accent : "#ffd9a8",
          });
        }
      }
    } else if (fighter.dashFrames <= 0) {
      // BODY-FIRST (spec 6): dash-stop dust slide — the tick the dash ends,
      // a couple of low motes drag forward as the feet bite the street.
      if (obs.prevDashFrames > 0 && fighter.grounded && state.phase === "fight"
        && state.performance.particleScale > 0.4 && !reducedMotion) {
        spawnMotionDashStopSlide(fighter);
      }
      obs.dashAge = -1;
    }
    // v2.9 critic round (m2): dash-exit walk suppression. Leaving a dash the
    // residual velocity is still well above the walk threshold while it
    // decays, so the locomotion beat flashed a frame or two of walk between
    // the authored brake key and the idle — a third and fourth pose change in
    // three ticks at the exact seam the brake key exists to smooth. Latching
    // across the decay lets the brake read all the way into idle.
    // Blockstun window length, latched on the opening edge.
    if (fighter.blockstunFrames > obs.blockstunTotal) obs.blockstunTotal = fighter.blockstunFrames;
    else if (fighter.blockstunFrames === 0) obs.blockstunTotal = 0;
    // Throw-recovery clock: starts the tick the clinch lets go, runs until the
    // move ends.
    if (fighter.grabbing) obs.throwRecoverFrames = 0;
    else if (fighter.attacking?.kind === "throw") obs.throwRecoverFrames += 1;
    else obs.throwRecoverFrames = -1;
    if (fighter.dashFrames > 0) obs.dashExitFrames = 0;
    else if (obs.prevDashFrames > 0) obs.dashExitFrames = MOTION_RULES.dashExitFrames;
    else if (obs.dashExitFrames > 0) obs.dashExitFrames -= 1;
    // --- BODY-FIRST (spec 9): hex-charm cast latch --------------------------
    if (obs.castFrames > 0) obs.castFrames -= 1;
    let charms = 0;
    for (const projectile of state.projectiles) {
      if (projectile.style === "charm" && projectile.ownerSide === side) charms += 1;
    }
    if (charms > obs.charmCount && !reducedMotion) obs.castFrames = 3;
    obs.charmCount = charms;
    // --- Hit-recoil wobble: settles over ~10 frames after hitstun ends ------
    if (obs.prevHitstun > 0 && fighter.hitstunFrames === 0 && !fighter.down
      && fighter.dizzyFrames === 0 && fighter.grounded) {
      obs.wobbleFrames = MOTION_RULES.wobbleFrames;
    } else if (obs.wobbleFrames > 0) obs.wobbleFrames -= 1;
    // --- MOTION FIX 4: ribbon dissipation after contact ---------------------
    // The swipe ribbon must whip through and be GONE within ~9 ticks of the
    // hit landing instead of holding frozen through hitstop. attackConnected
    // is sim truth; ticks keep advancing through the freeze, so this fade
    // runs while everything else holds.
    if (fighter.attacking && fighter.attackConnected) {
      obs.ribbonFade = Math.max(0, obs.ribbonFade - 1 / 9);
    } else if (!fighter.attacking || !fighter.attackConnected) {
      obs.ribbonFade = 1;
    }
    // --- Dash/walk lean easing ----------------------------------------------
    const moving = fighter.grounded && !fighter.attacking && !fighter.crouch
      && !fighter.block && !fighter.down && fighter.hitstunFrames === 0
      && fighter.cinematicFrame === null;
    const leanTarget = reducedMotion || !moving ? 0
      : fighter.dashFrames > 0 ? (fighter.dashDirection || fighter.facing) * 0.07
        : Math.abs(fighter.vx) > 22 ? Math.sign(fighter.vx) * 0.035 : 0;
    obs.leanLevel += clamp(leanTarget - obs.leanLevel, -0.018, 0.018);
    // --- v2.9 FLOW: facing-flip + crouch-transition latches -----------------
    // Edge-detected here (render loop, tick-deduped — never during rollback
    // resimulation) and consumed by fighterPoseDescriptor as 2-3 tick holds
    // of the authored turnaround / crouch-trans keys.
    // v2.9 final round (T6) — THE PIVOT KEY STILL MEASURED ZERO, AND THE
    // DRAW-SITE AUDIT SAYS WHY.
    //
    // Round 2 gave motion2:5 precedence over guard and crouch and it still did
    // not reach the screen in real demo play. Instrumenting the DRAW SITE
    // (presentationDebug.turnaroundDraws / turnaroundBlocked, which watch
    // pixels rather than a sim edge) over a full demo run returned
    // `{ "motion3:4": 2, "motion:11": 2 }` — the latch was live and lost to
    // AIRBORNE drawings both times. That is the whole story: pushboxes forbid
    // ground crossings, so a facing flip is almost always a JUMP cross-up; the
    // latch only armed on a GROUNDED flip, and on the rare occasion it did
    // arm, the fighter left the ground inside its three ticks and the airborne
    // branch drew instead while the counter ticked away.
    //
    // An airborne flip now arms a PENDING pivot that fires on touchdown, and
    // the latch does not decay in the air. Both are the same correction: the
    // pivot is a grounded drawing, so it must be spent on grounded ticks.
    const facingFlipped = obs.prevFacing !== 0 && fighter.facing !== obs.prevFacing
      && !fighter.down && state.phase === "fight";
    if (facingFlipped && fighter.grounded) {
      obs.turnFrames = 3;
      obs.turnPending = 0;
    } else if (facingFlipped) {
      // The cross-up case: remember it, and pivot when the feet land. The
      // pending flag expires so a flip that never lands (round end, a
      // knockdown mid-air) cannot fire a pivot a second later.
      obs.turnPending = MOTION_RULES.turnPendingFrames;
    } else if (obs.turnPending > 0 && fighter.grounded && !fighter.down
      && state.phase === "fight") {
      obs.turnFrames = 3;
      obs.turnPending = 0;
    } else {
      if (obs.turnPending > 0) obs.turnPending -= 1;
      if (obs.turnFrames > 0 && fighter.grounded) obs.turnFrames -= 1;
    }
    if (fighter.down) { obs.turnFrames = 0; obs.turnPending = 0; }
    // v2.9 final round (R5) — the wake-up SETTLE latch. The rise's last rung
    // is remembered while the countdown runs (obs.poseBank/poseFrame are the
    // RESOLVED cell, so a rejected sheet is accounted for), and the tick the
    // countdown ends the standing cell is handed the height that rung was
    // actually drawn at. Render-only observer state, exactly like the turn and
    // crouch latches — never advanced during rollback resimulation.
    if (fighter.wakeupFrames > 0 && obs.poseBank) {
      obs.wakeLastRung = { bank: obs.poseBank, frame: obs.poseFrame };
    }
    if (obs.prevWakeup > 0 && fighter.wakeupFrames === 0 && !fighter.down
      && state.phase === "fight" && obs.wakeLastRung) {
      obs.wakeSettleFrames = WAKEUP_SETTLE_FRAMES;
      obs.wakeSettleStart = wakeupSettleStart(fighter.def.id,
        obs.wakeLastRung.bank, obs.wakeLastRung.frame, DEFENSE_RULES.wakeupFrames,
        { unified: unifiedFighterReady(fighter.def.id) });
      obs.wakeLastRung = null;
    } else if (obs.wakeSettleFrames > 0) obs.wakeSettleFrames -= 1;
    obs.prevWakeup = fighter.wakeupFrames;
    if (obs.prevCrouch !== null && fighter.crouch !== obs.prevCrouch
      && fighter.grounded && state.phase === "fight") {
      obs.crouchTransFrames = 3;
    } else if (obs.crouchTransFrames > 0) obs.crouchTransFrames -= 1;
    obs.prevFacing = fighter.facing;
    obs.prevCrouch = fighter.crouch;
    // --- Pose cross-fade observation (spec 3) -------------------------------
    // Tick-paced here so render rate never changes the fade length; the 2D
    // draw path consumes fadeBank/fadeFrame/fadeLeft. A fade only ARMS on a
    // clean pose change — hitstop freezes and hit flashes keep the snap (the
    // snap IS the impact), battery keeps the plain blit.
    const observedPose = fighterAnimationPose(fighter);
    // v2.9 critic round 2 (M4): a BLOCK is not an impact. The fade was armed
    // only while hitFlash was zero — the snap IS the impact, and that is right
    // for a clean hit — but a blocked contact also raises the flash, so the
    // guard -> block-flinch -> guard pair snapped twice with no fade at all,
    // which is exactly where the 15% stance-height step was landing. Blockstun
    // now keeps its fade; a genuine hit still snaps.
    const flashSnaps = fighter.hitFlash > 0 && fighter.blockstunFrames <= 0;
    if (obs.poseBank !== observedPose.bank || obs.poseFrame !== observedPose.frame) {
      if (obs.poseBank !== null && state.hitstop <= 0 && state.performance.trailScale > 0
        && !flashSnaps && fighter.cinematicFrame === null) {
        obs.fadeBank = obs.poseBank;
        obs.fadeFrame = obs.poseFrame;
        obs.fadeLeft = MOTION_RULES.crossfadeFrames;
      } else obs.fadeLeft = 0;
      obs.poseBank = observedPose.bank;
      obs.poseFrame = observedPose.frame;
    } else if (obs.fadeLeft > 0) obs.fadeLeft -= 1;
    // --- Store previous-frame fields ---------------------------------------
    obs.wasGrounded = fighter.grounded;
    obs.prevVy = fighter.vy;
    obs.prevVx = fighter.vx;
    obs.prevHitstun = fighter.hitstunFrames;
    obs.prevDashFrames = fighter.dashFrames;
  }
}

// The shared motion transform, consumed by drawFighter AND the CINEMA 3D
// poseRig (via the bridge). Canvas conventions: rotation is world-space
// y-down/clockwise; scales are feet-anchored. flipRotation pivots about the
// body CENTRE (the somersault axis), everything else about the feet.
function fighterMotionTransform(fighter) {
  const scratch = motionScratch[fighter.side] || motionScratch[0];
  scratch.rotation = 0;
  scratch.flipRotation = 0;
  scratch.scaleX = 1;
  scratch.scaleY = 1;
  // v2.6 BODY-FIRST: world-space pixel offset consumed PRE-mirror by both
  // renderers — the attack-extension lunge and the victim stagger step.
  scratch.offsetX = 0;
  scratch.offsetY = 0;
  scratch.stretchActive = false;
  const obs = motionObs[fighter.side];
  if (!obs || fighter.cinematicFrame !== null || state.screen !== "fight") return scratch;
  const reducedMotion = state.accessibility.reducedMotion;
  const squashScale = reducedMotion ? 0.5 : 1;
  const controlledAir = !fighter.grounded && fighter.hitstunFrames === 0 && !fighter.down
    && !fighter.pendingKnockdown && !fighter.grabbed && fighter.dizzyFrames === 0
    && fighter.airTechFlipFrames === 0;

  // 1. JUMP FLIP — a pure function of the ballistic arc. Rising half maps vy
  // (launch → apex) onto progress 0→0.5; falling half maps the REMAINING
  // height onto 0.5→1 so capped-descent kits (the Devil's glide) still land
  // exactly upright. Air attacks and hits zero it instantly (snap upright).
  if (controlledAir && obs.flipEligible && !fighter.attacking && !obs.airAttackLatch
    && !reducedMotion) {
    const launch = fighter.movement.jumpVelocityY || -720;
    const apex = (launch * launch) / (2 * GRAVITY);
    const height = Math.max(0, FLOOR - fighter.y);
    const progress = fighter.vy < 0
      ? 0.5 * (1 - clamp(fighter.vy / launch, 0, 1))
      : 0.5 + 0.5 * clamp(1 - height / Math.max(1, apex), 0, 1);
    // MOTION FIX 6: the rotation eases OUT through the whole fall — no early
    // plateau. The eased curve tops out at ~0.97 of the turn (≈350°) as the
    // feet reach the street, so the last frames before touchdown show a
    // visible UN-TUCK (rotation still closing) and the landing snap covers
    // only the final ~10°. Directional flips keep their earlier commit but
    // inherit the same late finish.
    // BODY-FIRST (spec 4): the neutral flip HOLDS A BEAT at the apex — the
    // middle of the arc remaps onto a rotation plateau, which compresses the
    // remaining turn into the fall — and the limb-sprawl cells tuck 6%
    // toward a ball read mid-rotation.
    // v2.9 final round (T5) — A NEUTRAL JUMP NO LONGER SOMERSAULTS.
    //
    // EVERY jump was a full 360, including a straight-up jump with no
    // direction held. Three things followed from that, all of them wrong:
    // the authored motion3 "apex, knees unfolding" and "descent, legs
    // reaching for the ground" keys played while the body was INVERTED, which
    // is the opposite of what those drawings depict; the pose crossfade is
    // gated off for the whole |flipRotation| >= 0.3 band, so the entire
    // airborne middle of every jump lost its micro-fades; and a neutral jump
    // is the one jump a fighting game reads as a defensive hop, not an
    // acrobatic. Directional jumps keep the somersault — that is a committed
    // movement and the flip sells it. The neutral jump keeps its APEX TUCK
    // (the body still compresses at the top, spec 4's read) and its landing
    // squash; it simply stays the right way up while it does.
    if (obs.flipKind === "neutral") {
      const tuck = Math.sin(clamp(progress, 0, 1) * Math.PI) * 0.06;
      scratch.scaleX *= 1 - tuck;
      scratch.scaleY *= 1 - tuck;
    } else {
      const eased = motionEase01(0.05, 1.0, progress) * 0.97;
      scratch.flipRotation = obs.flipSpin * Math.PI * 2 * eased;
    }
    // BODY-FIRST (spec 5): directional flips leave with ONE genuine
    // stretch-smear — ~15% stretch along the launch vector for the first two
    // airborne ticks, the sprite leaning into its own velocity.
    if (obs.flipKind !== "neutral" && obs.launchAge >= 0 && obs.launchAge < 2) {
      scratch.rotation += clamp(Math.atan2(fighter.vx, -fighter.vy), -0.9, 0.9) * 0.45;
      scratch.scaleY *= 1.15;
      scratch.scaleX *= 0.88;
      scratch.stretchActive = true;
    }
  }

  // 2. SQUASH & STRETCH about the feet. Launch anticipation squat blends into
  // the fast-rise stretch over the first ~30px of height; the landing squash
  // scales with observed fall speed and recovers over 3-4 sim frames.
  // MOTION FIX 12: the anticipation crouch is now a REAL squat (−10% Y, +7% X
  // through the first two airborne frames) — deep enough to read in both
  // renderers; the 3D rig consumes the same scales through the bridge.
  if (controlledAir && !fighter.attacking && fighter.vy < 0) {
    const launch = fighter.movement.jumpVelocityY || -720;
    const rise = clamp(fighter.vy / launch, 0, 1);
    const height = Math.max(0, FLOOR - fighter.y);
    const windup = clamp(1 - height / 30, 0, 1);
    scratch.scaleY *= (1 + 0.06 * rise * squashScale) * (1 - windup) + (1 - 0.1 * squashScale) * windup;
    scratch.scaleX *= (1 - 0.028 * rise * squashScale) * (1 - windup) + (1 + 0.07 * squashScale) * windup;
    // v2.9 critic round (m1): the authored jump-rise key owns ~10 ticks of the
    // ascent before the tuck band opens, and across that hold the stretch
    // above only travels ~2.6% — so it read as a freeze. A GATHER ramp gives
    // every tick of the hold a visible delta: the body draws in and pitches
    // forward as the knees come up toward the tuck, which is exactly the
    // transition the cell is an in-between for.
    const gather = clamp(1 - rise, 0, 1) * (1 - windup) * squashScale;
    if (gather > 0.01) {
      scratch.scaleY *= 1 - 0.055 * gather;
      scratch.scaleX *= 1 + 0.05 * gather;
      scratch.rotation += fighter.facing * 0.1 * gather;
    }
    scratch.stretchActive = true;
  }
  if (obs.landFrames > 0 && fighter.grounded) {
    // BODY-FIRST (spec 4): landing squash deepened (0.06 -> 0.09) — the
    // plant frame must read as a real compress in BOTH renderers.
    const impact = (obs.landFrames / MOTION_RULES.landSquashFrames) * obs.landMag * squashScale;
    scratch.scaleY *= 1 - 0.09 * impact;
    scratch.scaleX *= 1 + 0.075 * impact;
    scratch.stretchActive = true;
  }
  // MOTION FIX 7: flip touchdown compress — 2 ticks of a much deeper crouch
  // stacked on the ordinary landing squash, so the plant frame is unmistakable
  // between "airborne" and "standing".
  if (obs.flipLandFrames > 0 && fighter.grounded) {
    const compress = (obs.flipLandFrames / 2) * squashScale;
    scratch.scaleY *= 1 - 0.09 * compress;
    scratch.scaleX *= 1 + 0.07 * compress;
    scratch.stretchActive = true;
  }

  // Dash lean (~4°) / walk lean (~2°), eased by the observer.
  if (!reducedMotion && Math.abs(obs.leanLevel) > 0.0025 && fighter.grounded && !fighter.down) {
    scratch.rotation += obs.leanLevel;
    scratch.stretchActive = true;
  }

  // MOTION FIX 8: dash launch lean — the head LEADS the dash. Ticks 1-5 of a
  // forward dash add up to ~12° of forward pitch on top of the eased base
  // lean, rising fast and easing off as the stride settles, plus a stride
  // stretch (+7% X) that lengthens the read of each dash step.
  if (!reducedMotion && fighter.dashFrames > 0 && obs.dashAge >= 0
    && fighter.grounded && !fighter.down && !fighter.attacking) {
    const dashDir = fighter.dashDirection || fighter.facing;
    const punchIn = clamp(obs.dashAge / 1.5, 0, 1);          // full by tick ~2
    const settle = clamp(1 - (obs.dashAge - 4) / 4, 0, 1);   // gone by tick ~8
    scratch.rotation += dashDir * 0.21 * punchIn * settle;
    scratch.scaleX *= 1 + 0.07 * punchIn * settle;
    scratch.stretchActive = true;
  }

  // v2.6 BODY-FIRST (core 1): ATTACK EXTENSION + FOLLOW-THROUGH. Pure
  // function of the snapshotted attack timeline: the body ramps toward the
  // target through late startup, PEAKS at the first active frame (translate
  // toward the target + rotation into the swing + stretch along the strike
  // line), decays across the active window, then settles through early
  // recovery as a decaying forward lean — the weight visibly carries past
  // the target. Heavies/specials get the full read, lights a lighter one;
  // multi-hit supers re-extend on every landed hit (combo tracker = sim
  // state). Consumed by drawFighter AND the CINEMA 3D poseRig, and
  // elementLimbPoint adds the same offset so elemental FX decorate the
  // moving body (core 3).
  if (fighter.attacking && !fighter.down) {
    const attack = fighter.attacking;
    const startup = attack.active[0];
    const activeEnd = attack.active[1];
    const t = fighter.attackTime;
    const heft = attack.kind === "light" ? 0.55
      : attack.superMove ? 1.25 : attack.kind === "special" ? 1.1 : 1;
    const calm = reducedMotion ? 0.5 : 1;
    let extend = 0;
    if (t >= startup * 0.7 && t < startup) {
      extend = (t - startup * 0.7) / Math.max(0.001, startup * 0.3);
    } else if (t >= startup && t <= activeEnd) {
      extend = 1 - (t - startup) / Math.max(0.016, activeEnd - startup);
    }
    if (attack.superMove) {
      // Per-hit re-extension: each landed hit of the storm re-lunges the
      // swing, so the cane/fist visibly drives every impact.
      const sinceOwnHit = state.simulationTick - (fighter.combo?.lastHitFrame ?? -Infinity);
      if (sinceOwnHit >= 0 && sinceOwnHit < 6 && t >= startup && t <= activeEnd) {
        extend = Math.max(extend, 1 - sinceOwnHit / 6);
      }
    }
    if (extend > 0.01) {
      // v2.7 FRAMES: while the authored full-extension cell actually draws,
      // the procedural envelope thins — a reduced translate keeps the lunge
      // reading, but the stretch is not double-applied on top of the painted
      // extension. A fallback (sheet missing / cell rejected) keeps the full
      // 2.6 envelope; attackMotionBeat is the same classifier the pose
      // functions use, so cell and transform always agree.
      const beat = attackMotionBeat(attack, fighter.attackFrame);
      const authoredExtension = beat?.beat === "extension"
        && motionCellDrawable(fighter.def.id, beat.cell);
      const lunge = authoredExtension ? 0.55 : 1;
      scratch.offsetX += fighter.facing * 10 * heft * extend * calm * lunge;
      scratch.rotation += fighter.facing * 0.1 * heft * extend * calm * lunge;
      if (!authoredExtension) {
        scratch.scaleX *= 1 + 0.04 * heft * extend * calm;
        scratch.scaleY *= 1 - 0.018 * heft * extend * calm;
      }
      scratch.stretchActive = true;
    } else if (t > activeEnd && attack.kind !== "light") {
      const settle = clamp(1 - (t - activeEnd) / Math.max(0.05, (attack.duration - activeEnd) * 0.6), 0, 1);
      if (settle > 0.01) {
        scratch.offsetX += fighter.facing * 4 * heft * settle * calm;
        scratch.rotation += fighter.facing * 0.05 * heft * settle * calm;
        scratch.stretchActive = true;
      }
    }
    // v2.9 final round (T3) — THE HEAVY KICK'S ARC BRIDGE. motion2:1 (knee
    // chambered at the waist, torso upright) cut to motion:1 (leg extended at
    // head height, torso leaned back) in ONE tick with no smear flash to carry
    // the eye — kicks are excluded from the smear beat, correctly, because
    // both smear cells are painted ARM streaks. There is no leg-smear drawing
    // in any of the four banks, so the in-between is a transform: over the two
    // reserved ticks the body rotates back and rises onto the support leg
    // along the arc the kick is about to travel. attackMotionBeat is the same
    // pure classifier the pose function uses, so the cell and the arc can
    // never disagree.
    const kickBeat = attackMotionBeat(attack, fighter.attackFrame);
    if (kickBeat?.beat === "kickArc" && !reducedMotion) {
      const arc = kickArcTransform(kickBeat.phase);
      scratch.rotation += fighter.facing * arc.lean;
      scratch.offsetY += arc.lift;
      scratch.offsetX += fighter.facing * arc.reach * 34;
      scratch.stretchActive = true;
    }
  }

  // v2.9 final round (R6) — THE GUARD-FLINCH EXIT BRIDGE. The tucked cover
  // (motion2:8) handed off to the tall braced guard cell in one tick. The
  // stance now ARRIVES carrying the flinch's tuck and unwinds out of it over
  // the next few ticks; the helper returns null before the handoff, so the
  // flinch itself is never double-tucked, and null once settled.
  // v5.1: a CROUCHED block has a flinch now too (the ext3 crouch guard, see
  // crouchBlockstunKeys) and hands back to the crouch on the same
  // BLOCK_EXIT_AT tick, so the bridge rides the crouch stance as well — the
  // same lift/pitch/squash, unwinding out of the crouched cover.
  // v5.3 (sweep #52): the phase is the SAME helper the two pose branches use
  // (engine/pose-precedence.mjs), off the same observer clock, so the bridge
  // and the drawing under it can never fall out of step.
  if (fighter.blockstunFrames > 0 && fighter.grounded && !reducedMotion) {
    const bridge = blockRecoverTransform(blockstunPhase(fighter.blockstunFrames, obs.blockstunTotal));
    if (bridge) {
      scratch.offsetY += bridge.lift;
      scratch.rotation += fighter.facing * bridge.pitch;
      scratch.scaleY *= bridge.squash;
      scratch.stretchActive = true;
    }
  }

  // v2.6 BODY-FIRST (core 2): victim stagger transforms riding the
  // reaction-track keys — head-snap back rotation, deeper torso-fold
  // rotation, a 4-8px backward stagger step, then everything eases out.
  // The clock shares the exact sim reads fighterAnimationPose uses, so cell
  // and transform always agree; ground-slam (seismic-family) specials shove
  // the victim visibly further (spec 8).
  if (fighter.hitstunFrames > 0 && fighter.grounded && !fighter.down
    && fighter.knockdownFrames === 0 && state.fighters?.length === 2) {
    const striker = state.fighters[1 - fighter.side];
    const sinceHit = state.simulationTick - (striker?.combo?.lastHitFrame ?? -Infinity);
    if (sinceHit >= 0 && sinceHit <= 44) {
      const calm = reducedMotion ? 0.5 : 1;
      const away = -fighter.facing; // back away from the attacker
      const seismicShove = striker?.attacking?.kind === "special"
        && fighterElementKit(striker.def)?.groundBurst ? 3 : 1;
      let staggerRot = 0;
      let staggerStep = 0;
      if (sinceHit < 5) {                    // head snap
        staggerRot = 0.055;
        staggerStep = 1.5;
      } else if (sinceHit < 11) {            // torso fold
        staggerRot = 0.1;
        staggerStep = 3 + (sinceHit - 5) * 0.4;
      } else if (sinceHit < 18) {            // stagger step
        const ramp = (sinceHit - 11) / 7;
        staggerRot = 0.08 * (1 - ramp * 0.4);
        staggerStep = 5 + ramp * 3;
      } else {                               // recover ease
        const easeOut = clamp(1 - (sinceHit - 18) / 10, 0, 1);
        staggerRot = 0.035 * easeOut;
        staggerStep = 6 * easeOut;
      }
      scratch.rotation += away * staggerRot * calm;
      scratch.offsetX += away * staggerStep * seismicShove * calm;
      scratch.stretchActive = true;
    }
  }

  // BODY-FIRST (spec 9): cast gesture — the Devil REARS UP for ~3 ticks as
  // the hex charm leaves the claw (the wing-flare read: back rotation plus a
  // rise), latched by the motion observer the tick the projectile appears.
  if (obs.castFrames > 0 && !reducedMotion && fighter.grounded && !fighter.down) {
    const flare = obs.castFrames / 3;
    scratch.rotation -= fighter.facing * 0.16 * flare;
    scratch.scaleY *= 1 + 0.06 * flare;
    scratch.stretchActive = true;
  }

  // 6. Hit-recoil wobble: damped oscillation settling after hitstun ends.
  if (!reducedMotion && obs.wobbleFrames > 0 && fighter.grounded && !fighter.down
    && fighter.hitstunFrames === 0 && !fighter.attacking) {
    const settle = obs.wobbleFrames / MOTION_RULES.wobbleFrames;
    scratch.rotation += Math.sin((MOTION_RULES.wobbleFrames - obs.wobbleFrames) * 1.15 + fighter.side)
      * 0.055 * settle * settle;
  }

  // 6. Dizzy body sway (amplitude up): rides on top of the double-vision
  // ghosts, collapsing with the drain bar. animTime-driven — deterministic.
  // v2.9 critic round (B5): the pose no longer alternates with a second base
  // cell (which was an ATTACK on nine of ten fighters), so the sway carries
  // the whole loop — a lateral rubber-legs drift and a slow knee dip run with
  // the rotation at an offset phase, which reads as woozy rather than as a
  // held cell being rocked.
  if (!reducedMotion && fighter.dizzyFrames > 0 && !fighter.down) {
    const drain = fighter.dizzyFrames / Math.max(1, fighter.dizzyTotalFrames);
    const amp = 0.35 + 0.65 * drain;
    const sway = fighter.animTime * 4.4 + fighter.side * 1.7;
    scratch.rotation += Math.sin(sway) * 0.07 * amp;
    scratch.offsetX += Math.sin(sway * 0.5 + 0.9) * 5.5 * amp;
    scratch.scaleY *= 1 - 0.035 * amp * (0.5 + 0.5 * Math.sin(sway * 0.77 + 2.1));
    scratch.stretchActive = true;
  }

  // v2.9 critic round (M4): the wake-up rise. Feet-anchored, so the getup
  // cells lift and un-pitch through their held ticks instead of freezing and
  // then teleporting to standing. Shared with the 3D rig through the same
  // pure helper, and reduced motion keeps a softened version (it is the only
  // thing that makes the recovery read as a rise at all).
  if (fighter.wakeupFrames > 0 && !fighter.down) {
    // v2.9 final round (R5): the bridge on the LAST rung is the measured
    // per-fighter stretch onto the standing height, not round 2's flat 12%
    // (which closed 1.12 of a ratio that runs to 1.40 on jez). obs.poseBank /
    // poseFrame are the resolved cell this frame, so a rejected sheet is
    // accounted for; before the first pose is latched it degrades to 1.
    const rung = obs.poseBank
      ? wakeupRiseStretch(fighter.def.id, obs.poseBank, obs.poseFrame,
        { unified: unifiedFighterReady(fighter.def.id) }) : 1;
    const wake = wakeupRiseTransform(fighter.wakeupFrames, DEFENSE_RULES.wakeupFrames, rung);
    if (wake) {
      const calm = reducedMotion ? 0.5 : 1;
      scratch.scaleY *= 1 + (wake.scaleY - 1) * calm;
      scratch.scaleX *= 1 + (wake.scaleX - 1) * calm;
      scratch.rotation += fighter.facing * wake.pitch * calm;
      scratch.stretchActive = true;
    }
  }

  // v2.9 final round (R5) — the OTHER half of the wake-up seam. The stretch
  // above is capped, so on the four fighters whose getup-b is more than 25%
  // short of standing it cannot close the gap alone. The standing cell arrives
  // compressed to exactly the height the last rung was drawn at and eases out
  // over five ticks, so the handoff has no step in it at all. Floored at 0.88:
  // a briefly compressed standing figure reads as the last of the push, a
  // 37% stretched crouch would read as the character growing.
  if (obs.wakeSettleFrames > 0 && fighter.grounded && !fighter.down
    && fighter.wakeupFrames === 0) {
    const settle = wakeupSettleTransform(obs.wakeSettleFrames, obs.wakeSettleStart);
    if (settle) {
      const calm = reducedMotion ? 0.5 : 1;
      scratch.scaleY *= 1 + (settle.scaleY - 1) * calm;
      scratch.stretchActive = true;
    }
  }
  return scratch;
}

// ---------------------------------------------------------------------------
// v2.6 ELEMENTS — three-phase elemental special-attack VFX (the SF6 bar:
// "special attacks with things like sparks, smoke, flames"). Every special/
// EX/super and every personal throwable flight carries an element kit with
// three phases: CHARGE (gathering aura + converging motes through startup),
// ACTIVE (velocity-inherited trail off the moving limb/projectile through the
// active window) and RELEASE (burst on the first active frame + ~0.5s of
// settling residue). Sprites come from generated 4x4 flipbook sheets under
// assets/vfx/ (magenta-keyed to alpha by tools/build_vfx_atlas.py;
// MANIFEST.json carries per-frame trim boxes) with a procedural glow fallback
// until the media arrives — the sheets follow the on-demand media policy and
// are NOT in the service-worker shell.
//
// Everything in this block is presentation on the documented superDimLevel
// pattern: module-level render-only state written exclusively from the render
// loop (updateElementalVfx runs in draw(), which never executes during
// rollback resimulation), tick-deduped like the motion observers, frame
// selection uses visualRandom/tick hashes only, and the sprite pool is
// budget-scaled by the performance profile (full on high, ~68% balanced,
// minimal on battery). reducedMotion calms particle motion; the flash toggle
// gates the bright release core and the super screen-edge wash. CINEMA 3D
// consumes the same kits through the spawnHit latch: the payload now carries
// the attacker's element id and the 3D impact layer re-tints its
// protection-mask-joined burst stack per element.
// ---------------------------------------------------------------------------

// How particles cut from each sheet move and composite. anim sheets play
// their 16 cells over the particle's life, scatter sheets pin one cell per
// particle, flicker sheets hash a cell from the sim tick (live electricity).
const ELEMENT_SHEET_PHYSICS = Object.freeze({
  flame: Object.freeze({ additive: true, gravity: -150, drag: 0.9, spin: 0.5 }),
  smoke: Object.freeze({ additive: false, gravity: -85, drag: 0.9, spin: 0.7, alpha: 0.82 }),
  electric: Object.freeze({ additive: true, gravity: 0, drag: 0.86, spin: 0 }),
  debris: Object.freeze({ additive: false, gravity: 960, drag: 0.985, spin: 7 }),
  spark: Object.freeze({ additive: true, gravity: 430, drag: 0.94, spin: 0.8 }),
  // Glyphs and curse wisps are PAINTED shapes (dark-edged volume, opaque
  // gold): source-over keeps their silhouettes; additive washed them out
  // against bright sprites. Both still get a backGlow halo so they separate
  // from the night stages.
  glyph: Object.freeze({ additive: false, gravity: -55, drag: 0.9, spin: 0.5, backGlow: true }),
  paper: Object.freeze({ additive: false, gravity: 240, drag: 0.9, spin: 3.2, flutter: true }),
  curse: Object.freeze({ additive: false, gravity: -130, drag: 0.9, spin: 0.4, alpha: 0.95, backGlow: true }),
  // Near-black scatter sprites (feathers, vinyl shards) vanish on the night
  // stages without a soft kit-coloured halo behind them.
  feather: Object.freeze({ additive: false, gravity: 140, drag: 0.88, spin: 2.4, flutter: true, backGlow: true }),
  paint: Object.freeze({ additive: false, gravity: 40, drag: 0.9, spin: 0.3, alpha: 0.9 }),
  vinyl: Object.freeze({ additive: false, gravity: 880, drag: 0.985, spin: 7.5, backGlow: true }),
  cash: Object.freeze({ additive: false, gravity: 180, drag: 0.9, spin: 2.8, flutter: true }),
});

// The element kits: which sheets each phase draws from, the kit's light
// palette, and the generated SFX layer(s) fired at release (super adds the
// second layer). Fighters map here through their roster `vfx` signature.
const ELEMENT_KITS = Object.freeze({
  seismic: Object.freeze({
    id: "seismic", glow: "#e8b25a", core: "#ffe9bd", ring: "#d9c9a8", groundBurst: true,
    charge: ["smoke", "debris"], trail: ["smoke", "debris"], burst: ["debris", "smoke", "spark"],
    residue: ["smoke", "debris"], superBurst: ["flame"], sfx: "vfx-seismic", superSfx: "vfx-flame",
  }),
  neon: Object.freeze({
    id: "neon", glow: "#5ee9ff", core: "#eafcff", ring: "#9ff2ff",
    charge: ["electric", "spark"], trail: ["electric"], burst: ["electric", "spark"],
    residue: ["spark"], superBurst: ["electric"], sfx: "vfx-electric", superSfx: "vfx-spark",
  }),
  concrete: Object.freeze({
    id: "concrete", glow: "#e0e0e0", core: "#ffffff", ring: "#cfcfcf", groundBurst: true,
    charge: ["spark"], trail: ["debris", "spark"], burst: ["debris", "spark"],
    residue: ["smoke"], superBurst: ["smoke"], sfx: "vfx-spark", superSfx: "vfx-smoke",
  }),
  spray: Object.freeze({
    id: "spray", glow: "#ff9b3d", core: "#ffd9a8", ring: "#ffb765",
    charge: ["paint"], trail: ["paint"], burst: ["paint"],
    residue: ["paint"], superBurst: ["paint"], sfx: "vfx-paint", superSfx: "vfx-smoke",
  }),
  tech: Object.freeze({
    id: "tech", glow: "#7fd4ff", core: "#e8f7ff", ring: "#a8e2ff",
    charge: ["electric"], trail: ["electric", "spark"], burst: ["electric"],
    residue: ["spark"], superBurst: ["electric"], sfx: "vfx-electric", superSfx: "vfx-spark",
  }),
  gilded: Object.freeze({
    id: "gilded", glow: "#ffd76b", core: "#fff3cf", ring: "#ffe49a",
    charge: ["spark"], trail: ["cash", "spark"], burst: ["cash", "spark"],
    residue: ["cash"], superBurst: ["cash"], sfx: "vfx-cash", superSfx: "vfx-glyph",
  }),
  feedback: Object.freeze({
    id: "feedback", glow: "#b08cff", core: "#e9dcff", ring: "#8cff6b",
    charge: ["electric"], trail: ["electric", "smoke"], burst: ["electric", "smoke"],
    residue: ["smoke"], superBurst: ["electric"], sfx: "vfx-electric", superSfx: "vfx-smoke",
  }),
  bass: Object.freeze({
    id: "bass", glow: "#ff8c5a", core: "#ffd9c2", ring: "#ffd9a8", rings: true,
    charge: ["vinyl"], trail: ["vinyl"], burst: ["vinyl"],
    residue: ["vinyl"], superBurst: ["vinyl"], sfx: "vfx-bass", superSfx: "vfx-vinyl",
  }),
  contract: Object.freeze({
    id: "contract", glow: "#ffd76b", core: "#fff3cf", ring: "#ffc94f",
    charge: ["glyph"], trail: ["glyph"], burst: ["glyph", "paper"],
    residue: ["paper"], superBurst: ["glyph"], sfx: "vfx-glyph", superSfx: "vfx-paper",
  }),
  curse: Object.freeze({
    id: "curse", glow: "#8cff5e", core: "#e4ffd4", ring: "#6bd44a", wind: true,
    charge: ["curse"], trail: ["curse"], burst: ["curse", "feather"],
    residue: ["feather"], superBurst: ["curse"], sfx: "vfx-curse", superSfx: "vfx-smoke",
  }),
});

// Roster `vfx` signature -> element kit id (the data table's spine).
const ELEMENT_BY_VFX = Object.freeze({
  seismic: "seismic", neon: "neon", steel: "concrete", paint: "spray",
  voltage: "tech", gilded: "gilded", feedback: "feedback", bass: "bass",
  barrens: "curse", authority: "contract",
});

function fighterElementKit(def) {
  return ELEMENT_KITS[ELEMENT_BY_VFX[def?.vfx]] || null;
}

// Monotonic one-shot totals on the motionFxDebug pattern (never reset),
// exposed via snapshot().violence for orchestrator smoke tests.
const elementFxDebug = {
  elementCharges: 0, elementTrails: 0, elementBursts: 0, elementResidue: 0, vfxSfxPlays: 0,
};

// Render-only flipbook sprite pool + per-side phase observers.
const elementParticles = [];
// BODY-FIRST (spec 10): seal-shatter events queued during the pool walk and
// drained into paper/spark shards right after it (no mid-iteration pushes).
const elementShatterQueue = [];
const elementObs = [
  { attackSerial: -1, releasedSerial: -1, chargeLevel: 0, limbX: 0, limbY: 0, prevLimbX: 0, prevLimbY: 0, hadLimb: false },
  { attackSerial: -1, releasedSerial: -1, chargeLevel: 0, limbX: 0, limbY: 0, prevLimbX: 0, prevLimbY: 0, hadLimb: false },
];
let elementLastObservedTick = -1;
let elementLastFrameMs = 0;
// Super screen-edge element wash (eased render level + owning kit colour).
const elementWash = { level: 0, color: null };
// Rate cap per SFX kind so mashed specials never stack the layer.
const elementSfxLast = new Map();
const ELEMENT_SFX_MIN_MS = 300;

// Lazy media: manifest + sheets fetched on first elemental emission, never in
// the install shell. Draws fall back to procedural glows until they arrive.
const elementSheets = { manifest: null, images: new Map(), requested: false };

function ensureElementMedia() {
  if (elementSheets.requested) return;
  elementSheets.requested = true;
  fetch("assets/vfx/MANIFEST.json")
    .then((response) => (response.ok ? response.json() : null))
    .then((manifest) => {
      if (!manifest) return;
      elementSheets.manifest = manifest;
      for (const [name, entry] of Object.entries(manifest)) {
        const image = new Image();
        image.src = `assets/vfx/${entry.sheet}`;
        elementSheets.images.set(name, image);
      }
    })
    .catch(() => {});
}

function elementBudgetCap() {
  // ~190 sprites on high, ~129 balanced, minimal (~80) on battery.
  return Math.max(36, Math.round(190 * state.performance.particleScale));
}

function pushElementParticle(particle) {
  if (elementParticles.length >= elementBudgetCap()) elementParticles.shift();
  elementParticles.push(particle);
}

function elementSfx(kind, fighter = null) {
  if (rollbackResimulating || !kind) return;
  if (!$("#soundToggle").checked) return;
  const now = performance.now();
  if (now - (elementSfxLast.get(kind) || -Infinity) < ELEMENT_SFX_MIN_MS) return;
  elementSfxLast.set(kind, now);
  sound(kind, fighter);
  elementFxDebug.vfxSfxPlays += 1;
}

// EX kits run denser/brighter; supers max all three phases.
function elementTier(attack) {
  if (attack.superMove) return 2;
  return (attack.gritCost || 0) > 0 ? 1 : 0;
}
const ELEMENT_TIER_MULT = [1, 1.5, 2.1];

// The limb the element rides: the furthest live hitbox during active frames,
// the first authored hitbox (projected to world) during startup, the chest as
// a last resort. Pure read of already-snapshotted sim state.
function elementLimbPoint(fighter) {
  // v2.6 BODY-FIRST (core 3): the anchor rides the DRAWN body — the shared
  // motion transform's extension/stagger offset shifts the limb point the
  // same pixels the sprite itself moves, so trails and bursts decorate the
  // extended body instead of the sim-space hitbox behind it.
  const motion = fighterMotionTransform(fighter);
  const active = getActiveHitboxes(fighter);
  const box = active.length ? active[active.length - 1]
    : fighter.attacking?.hitboxes?.length ? localBoxToWorld(fighter, fighter.attacking.hitboxes[0].box) : null;
  if (box) return { x: box.x + box.width * 0.5 + motion.offsetX, y: box.y + box.height * 0.5 + motion.offsetY };
  return { x: fighter.x + fighter.facing * 34 + motion.offsetX, y: fighter.y - fighter.height * 0.55 + motion.offsetY };
}

function spawnElementSprite(sheet, options) {
  const physics = ELEMENT_SHEET_PHYSICS[sheet];
  if (!physics) return;
  const calm = state.accessibility.reducedMotion ? 0.42 : 1;
  const meta = elementSheets.manifest?.[sheet];
  const life = options.life ?? 0.32 + visualRandom() * 0.2;
  const x = options.x + (visualRandom() - 0.5) * (options.spread ?? 0);
  const y = options.y + (visualRandom() - 0.5) * (options.spread ?? 0);
  // MOTION FIX 11: an orbit target turns the sprite into a traveller — it
  // spirals INTO the target over its life instead of popping at an anchor,
  // with prev-position bookkeeping so the draw pass can streak its entry.
  const orbit = options.orbit && !state.accessibility.reducedMotion ? options.orbit : null;
  const orbitAngle = orbit ? Math.atan2(y - orbit.y, x - orbit.x) : 0;
  const orbitRadius = orbit ? Math.max(30, Math.hypot(x - orbit.x, y - orbit.y)) : 0;
  pushElementParticle({
    sheet,
    additive: physics.additive,
    alpha: physics.alpha ?? 1,
    x, y,
    prevX: x, prevY: y,
    vx: (options.vx ?? 0) * calm,
    vy: (options.vy ?? 0) * calm,
    homeX: options.homeX, homeY: options.homeY, converge: options.converge ?? 0,
    orbit: Boolean(orbit),
    orbitX: orbit ? orbit.x : 0, orbitY: orbit ? orbit.y : 0,
    orbitAngle, orbitRadius,
    // BODY-FIRST (spec 10): a caller-supplied orbitDir makes the sweep
    // deterministic (seals arc over the top toward the victim, never a coin
    // flip); shatter marks the sprite to burst into shards on contact.
    orbitAngVel: orbit
      ? (options.orbitDir || (visualRandom() < 0.5 ? -1 : 1)) * (3.2 + visualRandom() * 2.6)
      : 0,
    shatter: Boolean(options.shatter && orbit),
    shattered: false,
    gravity: physics.gravity * (state.accessibility.reducedMotion ? 0.45 : 1),
    drag: physics.drag,
    // MOTION FIX 3: debris-class sheets earn one floor bounce; smoke-class
    // sheets shear sideways as they rise. Latched at spawn, integrated below.
    bounces: sheet === "debris" || sheet === "vinyl" ? 1 : 0,
    shearDir: sheet === "smoke" ? (visualRandom() < 0.5 ? -1 : 1) : 0,
    life, max: life,
    size: options.size ?? 40,
    backGlow: Boolean(physics.backGlow),
    rotation: physics.spin ? visualRandom() * Math.PI * 2 : 0,
    spin: (visualRandom() - 0.5) * physics.spin * calm,
    flutter: physics.flutter ? 5 + visualRandom() * 4 : 0,
    seed: Math.floor(visualRandom() * 4096),
    frame: meta && meta.mode === "scatter" ? Math.floor(visualRandom() * 16) % 16 : 0,
    glow: options.glow,
  });
}

// --- phase emitters ---------------------------------------------------------

function emitElementCharge(kit, fighter, attack, tier, orbitTarget = null) {
  const mult = ELEMENT_TIER_MULT[tier];
  // Battery keeps its charge budget for supers only.
  if (state.performance.particleScale < 0.5 && tier < 2) return;
  const target = elementLimbPoint(fighter);
  const count = Math.max(1, Math.round((tier === 2 ? 2 : 1) * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const sheet = kit.charge[Math.floor(visualRandom() * kit.charge.length) % kit.charge.length];
    const angle = visualRandom() * Math.PI * 2;
    const radius = (36 + visualRandom() * 52) * mult;
    const x = target.x + Math.cos(angle) * radius;
    const y = target.y + Math.sin(angle) * radius * 0.7;
    // BODY-FIRST (spec 10): travelling seals SPAWN BEHIND the caster and arc
    // over the top into the victim (deterministic sweep via orbitDir),
    // shattering on contact — replacing the swap-in-place read.
    const travelling = orbitTarget && sheet === "glyph";
    const life = travelling ? 0.24 + visualRandom() * 0.16 : 0.3 + visualRandom() * 0.18;
    spawnElementSprite(sheet, {
      x: travelling ? fighter.x - fighter.facing * (55 + visualRandom() * 85) : x,
      y: travelling ? fighter.y - fighter.height * (0.55 + visualRandom() * 0.5) : y,
      life,
      orbit: travelling ? orbitTarget : null,
      orbitDir: travelling ? fighter.facing : 0,
      shatter: travelling,
      // Converging motes: aimed to arrive at the limb as they die. Reduced
      // motion swaps the rush for a gentle drift + fade in place.
      vx: state.accessibility.reducedMotion ? 0 : (target.x - x) / life * 0.8,
      vy: state.accessibility.reducedMotion ? 0 : (target.y - y) / life * 0.8,
      size: (24 + visualRandom() * 22) * mult,
      glow: kit.glow,
    });
  }
  if (kit.rings && (state.simulationTick & 7) === 0 && state.performance.trailScale > 0) {
    // MOTION FIX 3: rings are punctuation, not set dressing — 2-3 frames max.
    state.effects.push({
      kind: "shockRing", x: target.x, y: target.y,
      size: 30 * mult, life: 0.12, max: 0.12, color: kit.ring,
    });
  }
  elementFxDebug.elementCharges += 1;
}

function emitElementTrail(kit, x, y, vx, vy, tier, glow, orbitTarget = null, caster = null) {
  const mult = ELEMENT_TIER_MULT[tier];
  const cadence = state.performance.particleScale < 0.5 ? 3 : 1;
  if (state.simulationTick % cadence !== 0) return;
  const count = Math.max(1, Math.round((tier === 2 ? 3 : 2) * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const sheet = kit.trail[Math.floor(visualRandom() * kit.trail.length) % kit.trail.length];
    const travelling = orbitTarget && sheet === "glyph";
    // BODY-FIRST (spec 10): mid-storm seals keep spawning BEHIND the caster
    // and arcing in — the whole window streams travellers, not stamps.
    const behind = travelling && caster;
    spawnElementSprite(sheet, {
      x: behind ? caster.x - caster.facing * (55 + visualRandom() * 85) : x,
      y: behind ? caster.y - caster.height * (0.55 + visualRandom() * 0.5) : y,
      spread: behind ? 0 : 40,
      orbit: travelling ? orbitTarget : null,
      orbitDir: behind ? caster.facing : 0,
      shatter: travelling,
      // Velocity-inherited: the trail streams off the moving limb/projectile.
      vx: vx * 0.42 + (visualRandom() - 0.5) * 90,
      vy: vy * 0.42 - 20 - visualRandom() * 60,
      size: (38 + visualRandom() * 34) * mult,
      life: travelling ? 0.24 + visualRandom() * 0.16 : 0.42 + visualRandom() * 0.3,
      glow: glow || kit.glow,
    });
  }
  elementFxDebug.elementTrails += 1;
}

function emitElementBurst(kit, fighter, attack, tier, orbitTarget = null) {
  const mult = ELEMENT_TIER_MULT[tier];
  const point = elementLimbPoint(fighter);
  const direction = fighter.facing;
  const sheets = tier === 2 && kit.superBurst ? [...kit.burst, ...kit.superBurst] : kit.burst;
  const count = Math.max(6, Math.round(13 * mult * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const sheet = sheets[Math.floor(visualRandom() * sheets.length) % sheets.length];
    const angle = (visualRandom() - 0.5) * 2.4;
    const speed = (140 + visualRandom() * 320) * mult * 0.8;
    const travelling = orbitTarget && sheet === "glyph";
    spawnElementSprite(sheet, {
      // BODY-FIRST (spec 10): release seals launch from behind the caster
      // like the charge/trail ones — one continuous arcing stream.
      x: travelling ? fighter.x - fighter.facing * (55 + visualRandom() * 85) : point.x,
      y: travelling ? fighter.y - fighter.height * (0.55 + visualRandom() * 0.5) : point.y,
      spread: travelling ? 0 : 30,
      orbit: travelling ? orbitTarget : null,
      orbitDir: travelling ? fighter.facing : 0,
      shatter: travelling,
      vx: Math.cos(angle) * speed * 0.55 + direction * speed * 0.6,
      vy: Math.sin(angle) * speed * 0.6 - 60,
      size: (48 + visualRandom() * 46) * mult,
      life: travelling ? 0.26 + visualRandom() * 0.18 : 0.42 + visualRandom() * 0.34,
      glow: kit.glow,
    });
  }
  // Seismic/concrete kits also erupt along the floor line — the ground-slam
  // read: a fan of debris and dust kicked out of the street on both sides.
  if (kit.groundBurst) {
    const groundCount = Math.max(4, Math.round(8 * mult * state.performance.particleScale));
    for (let index = 0; index < groundCount; index += 1) {
      const side = index % 2 ? 1 : -1;
      const sheet = kit.burst[Math.floor(visualRandom() * kit.burst.length) % kit.burst.length];
      spawnElementSprite(sheet, {
        x: point.x + side * (24 + visualRandom() * 90) * mult,
        y: FLOOR - 6,
        vx: side * (80 + visualRandom() * 220) * mult * 0.7,
        vy: -180 - visualRandom() * 260 * mult,
        size: (36 + visualRandom() * 34) * mult,
        life: 0.45 + visualRandom() * 0.3,
        glow: kit.glow,
      });
    }
  }
  // Element pressure ring in the kit colour (doubled for the bass kit, whose
  // identity IS the shockwave), riding the existing shockRing effect path.
  // MOTION FIX 3: rings are 2-3 frame punctuation now — effects keep ticking
  // through hitstop, so these are genuinely gone in ~0.13s of screen time.
  if (state.performance.trailScale > 0) {
    state.effects.push({
      kind: "shockRing", x: point.x, y: point.y,
      size: (kit.rings ? 120 : 84) * mult, life: 0.13, max: 0.13, color: kit.ring,
    });
    if (kit.rings) {
      state.effects.push({
        kind: "shockRing", x: point.x, y: point.y,
        size: 168 * mult, life: 0.16, max: 0.16, color: kit.glow,
      });
    }
  }
  // Bright release core, gated by the flash toggle like every hot flash.
  if ($("#flashToggle").checked) {
    state.effects.push({
      kind: "impactFlash", tier: tier === 2 ? "super" : "special", x: point.x, y: point.y,
      life: tier === 2 ? 0.2 : 0.12, max: tier === 2 ? 0.2 : 0.12,
      color: kit.core, spill: kit.glow,
    });
  }
  elementFxDebug.elementBursts += 1;
  // RESIDUE: lingering settle for ~0.5s — embers/wisps/scraps coming to rest.
  const residueCount = Math.max(3, Math.round(7 * mult * state.performance.particleScale));
  for (let index = 0; index < residueCount; index += 1) {
    const sheet = kit.residue[Math.floor(visualRandom() * kit.residue.length) % kit.residue.length];
    spawnElementSprite(sheet, {
      x: point.x, y: point.y, spread: 70 * mult,
      vx: (visualRandom() - 0.5) * 130 + (kit.wind ? direction * 70 : 0),
      vy: -30 - visualRandom() * 80,
      size: (30 + visualRandom() * 30) * mult,
      life: 0.55 + visualRandom() * 0.5,
      glow: kit.glow,
    });
  }
  elementFxDebug.elementResidue += 1;
  elementSfx(kit.sfx, fighter);
  if (tier === 2) elementSfx(kit.superSfx, fighter);
}

function resetElementObserver(obs) {
  obs.attackSerial = -1;
  obs.releasedSerial = -1;
  obs.chargeLevel = 0;
  obs.hadLimb = false;
}

// Per-rendered-frame elemental observation + pool integration. Runs once at
// the top of draw() beside updateMotionObservers: emissions advance only on
// sim-tick edges (tick-deduped, so QA manual stepping and 120Hz displays pace
// identically), while the pool integrates on real render time so residue
// settles smoothly through hitstop.
function updateElementalVfx(nowMs) {
  const dtSec = clamp((nowMs - elementLastFrameMs) / 1000 || 0, 0, 0.05);
  elementLastFrameMs = nowMs;
  // Integrate the sprite pool (render-time physics; cheap, allocation-free).
  for (const particle of elementParticles) {
    particle.prevX = particle.x;
    particle.prevY = particle.y;
    particle.life -= dtSec;
    // MOTION FIX 11: orbiters spiral into their target — angle advances,
    // radius collapses over the sprite's life — instead of ballistic drift.
    if (particle.orbit) {
      const age = 1 - clamp(particle.life / particle.max, 0, 1);
      particle.orbitAngle += particle.orbitAngVel * dtSec;
      const radius = particle.orbitRadius * Math.max(0.08, 1 - age * age * 1.05);
      particle.x = particle.orbitX + Math.cos(particle.orbitAngle) * radius;
      particle.y = particle.orbitY + Math.sin(particle.orbitAngle) * radius * 0.6;
      particle.rotation += particle.spin * dtSec;
      // BODY-FIRST (spec 10): a travelling seal SHATTERS on contact — the
      // instant its arc collapses onto the victim it dies into paper/spark
      // shards (queued; the pool must not mutate mid-walk).
      if (particle.shatter && !particle.shattered
        && (radius <= Math.max(22, particle.orbitRadius * 0.16) || particle.life <= 0.04)) {
        particle.shattered = true;
        particle.life = 0;
        elementShatterQueue.push({ x: particle.x, y: particle.y, glow: particle.glow });
      }
      continue;
    }
    particle.vy += particle.gravity * dtSec;
    if (particle.flutter) {
      particle.vx += Math.sin(particle.life * particle.flutter * 6 + particle.seed) * 60 * dtSec;
    }
    // MOTION FIX 3: smoke shears sideways as it climbs — the puff slides off
    // its own column instead of rising in place.
    if (particle.shearDir) {
      particle.vx += particle.shearDir * 90 * dtSec;
    }
    particle.x += particle.vx * dtSec;
    particle.y += particle.vy * dtSec;
    particle.vx *= particle.drag;
    if (particle.y > FLOOR - 2 && particle.vy > 0) {
      if (particle.bounces > 0) {
        // MOTION FIX 3: debris-class chips take one real bounce off the
        // street before settling — the gravity arc reads as weight.
        particle.bounces -= 1;
        particle.y = FLOOR - 2;
        particle.vy *= -(0.32 + visualRandom() * 0.14);
        particle.vx *= 0.72;
        particle.spin *= 0.6;
      } else {
        // Residue settles on the floor line instead of sinking through it.
        particle.y = FLOOR - 2;
        particle.vy = 0;
        particle.vx *= 0.82;
        particle.spin *= 0.8;
      }
    }
    particle.rotation += particle.spin * dtSec;
  }
  for (let index = elementParticles.length - 1; index >= 0; index -= 1) {
    if (elementParticles[index].life <= 0) elementParticles.splice(index, 1);
  }
  // BODY-FIRST (spec 10): drain the seal-shatter queue — each contact spits
  // a small spray of contract paper + sparks off the victim.
  if (elementShatterQueue.length) {
    for (const burst of elementShatterQueue) {
      const shards = Math.max(2, Math.round(4 * state.performance.particleScale));
      for (let shard = 0; shard < shards; shard += 1) {
        spawnElementSprite(shard % 2 ? "paper" : "spark", {
          x: burst.x, y: burst.y, spread: 12,
          vx: (visualRandom() - 0.5) * 320,
          vy: -50 - visualRandom() * 190,
          size: 18 + visualRandom() * 16,
          life: 0.22 + visualRandom() * 0.16,
          glow: burst.glow,
        });
      }
    }
    elementShatterQueue.length = 0;
  }

  if (state.screen !== "fight" || state.fighters.length < 2) {
    elementParticles.length = 0;
    elementObs.forEach(resetElementObserver);
    elementWash.level = Math.max(0, elementWash.level - dtSec * 3);
    elementLastObservedTick = -1;
    return;
  }
  const tickAdvanced = state.simulationTick !== elementLastObservedTick;
  elementLastObservedTick = state.simulationTick;

  let washTarget = 0;
  for (let side = 0; side < 2; side += 1) {
    const fighter = state.fighters[side];
    const obs = elementObs[side];
    const attack = fighter.attacking;
    const kit = fighterElementKit(fighter.def);
    const elemental = attack && kit && attack.kind === "special" && !fighter.cinematicFrame;
    if (!elemental) {
      obs.attackSerial = -1;
      obs.hadLimb = false;
      obs.chargeLevel = Math.max(0, obs.chargeLevel - dtSec * 6);
      continue;
    }
    ensureElementMedia();
    const tier = elementTier(attack);
    if (tier === 2) {
      washTarget = 1;
      elementWash.color = kit.glow;
    }
    const serial = attack.attackSerial ?? 0;
    if (obs.attackSerial !== serial) {
      obs.attackSerial = serial;
      obs.hadLimb = false;
    }
    const point = elementLimbPoint(fighter);
    obs.prevLimbX = obs.hadLimb ? obs.limbX : point.x;
    obs.prevLimbY = obs.hadLimb ? obs.limbY : point.y;
    obs.limbX = point.x;
    obs.limbY = point.y;
    obs.hadLimb = true;
    if (!tickAdvanced) continue;
    // MOTION FIX 11: during the contract super the glyph storm TRAVELS — every
    // glyph spirals into the victim's chest instead of popping at an anchor.
    const victim = state.fighters[1 - side];
    const orbitTarget = tier === 2 && kit.id === "contract" && victim
      ? { x: victim.x, y: victim.y - victim.height * 0.55 } : null;
    if (fighter.attackFrame < attack.activeStartFrame) {
      // CHARGE — brief aura + gathering particles through the startup.
      emitElementCharge(kit, fighter, attack, tier, orbitTarget);
      obs.chargeLevel = Math.min(1, obs.chargeLevel + 0.16 * (tier === 2 ? 1.6 : 1));
    } else {
      if (obs.releasedSerial !== serial) {
        // RELEASE — burst at the first active frame (hit or whiff alike).
        obs.releasedSerial = serial;
        emitElementBurst(kit, fighter, attack, tier, orbitTarget);
      }
      obs.chargeLevel = Math.max(0, obs.chargeLevel - 0.25);
      if (fighter.attackFrame < attack.activeEndFrame) {
        // ACTIVE — persistent trail off the moving limb.
        const limbVx = (obs.limbX - obs.prevLimbX) * SIMULATION_HZ;
        const limbVy = (obs.limbY - obs.prevLimbY) * SIMULATION_HZ;
        emitElementTrail(kit, obs.limbX, obs.limbY,
          clamp(limbVx, -900, 900), clamp(limbVy, -900, 900), tier, null, orbitTarget, fighter);
      }
    }
  }

  // Personal throwable flights ride their owner's element kit.
  if (tickAdvanced && state.projectiles.length) {
    for (let index = 0; index < state.projectiles.length; index += 1) {
      const projectile = state.projectiles[index];
      if (!projectile.throwable || projectile.stageWeapon) continue;
      // MOTION FIX 10: the charm sheds its curse-wisp trail EVERY tick — the
      // mist tail needs continuous feeding to sell the single arc.
      if (projectile.style !== "charm" && (state.simulationTick + index) % 2 !== 0) continue;
      const owner = state.fighters[projectile.ownerSide];
      const kit = owner ? fighterElementKit(owner.def) : null;
      if (!kit) continue;
      ensureElementMedia();
      emitElementTrail(kit, projectile.x, projectile.y,
        (projectile.vx || 0) * 0.5, (projectile.vy || 0) * 0.5,
        projectile.enhanced ? 1 : 0, projectile.color);
    }
  }

  // Super screen-edge wash easing (drawn by drawElementalWash).
  elementWash.level = washTarget > elementWash.level
    ? Math.min(washTarget, elementWash.level + dtSec * 5)
    : Math.max(washTarget, elementWash.level - dtSec * 2.4);
}

// Charge auras + flipbook sprites, drawn in the 2D world pass right above
// drawParticles. CINEMA 3D gets its element read through the tinted impact
// layer instead — this pass is 2D-renderer-only by construction.
function drawElementalVfx() {
  for (let side = 0; side < 2; side += 1) {
    const obs = elementObs[side];
    if (obs.chargeLevel <= 0.02) continue;
    const fighter = state.fighters[side];
    const kit = fighterElementKit(fighter?.def);
    if (!kit) continue;
    const tier = fighter.attacking ? elementTier(fighter.attacking) : 0;
    // 5.3 SPECTACLE (#47): radius and alpha come from engine/vfx-bridge.mjs
    // so the 3D charge light is the same swell as this canvas halo.
    const radius = chargeGlowRadius(obs.chargeLevel, tier, state.simulationTick, side);
    const gradient = ctx.createRadialGradient(obs.limbX, obs.limbY, radius * 0.12, obs.limbX, obs.limbY, radius);
    gradient.addColorStop(0, kit.core);
    gradient.addColorStop(0.45, kit.glow);
    gradient.addColorStop(1, "rgba(0,0,0,0)");
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = chargeGlowAlpha(obs.chargeLevel, tier);
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(obs.limbX, obs.limbY, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
  for (const particle of elementParticles) {
    const meta = elementSheets.manifest?.[particle.sheet];
    const image = elementSheets.images.get(particle.sheet);
    const fade = clamp(particle.life / particle.max, 0, 1);
    if (!meta || !image?.complete || !image.naturalWidth) {
      // Procedural fallback until the on-demand sheet arrives.
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = fade * 0.5;
      ctx.fillStyle = particle.glow || "#ffe9bd";
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size * 0.28, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      continue;
    }
    // MOTION FIX 4: live electricity re-forks EVERY sim tick (the >>1 gate is
    // gone) — ticks keep advancing through hitstop, so a held impact never
    // shows the same fork twice. 5.3 SPECTACLE (#47): the anim/flicker/scatter
    // pick moved to engine/vfx-bridge.mjs — the 3D element layer resolves the
    // SAME cell on the same tick from the same function.
    const index = elementFrameIndex(meta, particle, state.simulationTick);
    const frame = meta.frames[index];
    if (!frame || !frame.w) continue;
    // MOTION FIX 3: smoke grows as it climbs — the puff opens up to ~1.5x
    // over its life while the shear slide (integrator) drags it off-column.
    const age = 1 - fade;
    const growth = particle.shearDir ? 1 + age * 0.55 : 1;
    const scale = (particle.size * growth) / Math.max(frame.w, frame.h);
    if (particle.backGlow && particle.glow) {
      // Soft kit-coloured halo behind dark sprites so their silhouettes
      // separate from the night stages.
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = fade * 0.32;
      ctx.fillStyle = particle.glow;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size * 0.58, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    // MOTION FIX 11: motion-streaked entry for orbiters — a tapered additive
    // streak trails the glyph along its spiral while it is still travelling
    // fast (first ~60% of life), so the eye reads the path, not a pop.
    if (particle.orbit && age < 0.6 && particle.glow) {
      const streakX = particle.prevX - particle.x;
      const streakY = particle.prevY - particle.y;
      const streakLen = Math.hypot(streakX, streakY);
      if (streakLen > 1.5) {
        const stretch = Math.min(4.5, 2 + streakLen * 0.25);
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        ctx.globalAlpha = fade * 0.4;
        ctx.strokeStyle = particle.glow;
        ctx.lineCap = "round";
        ctx.lineWidth = Math.max(2, particle.size * 0.14);
        ctx.beginPath();
        ctx.moveTo(particle.x, particle.y);
        ctx.lineTo(particle.x + streakX * stretch, particle.y + streakY * stretch);
        ctx.stroke();
        ctx.restore();
      }
    }
    ctx.save();
    // Front-loaded fades: sprites hold near-full presence through most of
    // their life and drop off at the end, instead of thinning immediately.
    ctx.globalAlpha = elementSpriteAlpha(particle);
    ctx.globalCompositeOperation = particle.additive ? "lighter" : "source-over";
    ctx.translate(particle.x, particle.y);
    if (particle.rotation) ctx.rotate(particle.rotation);
    ctx.drawImage(image, frame.x, frame.y, frame.w, frame.h,
      -(frame.cx - frame.x) * scale, -(frame.cy - frame.y) * scale,
      frame.w * scale, frame.h * scale);
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
}

// Screen-edge element wash while a super is in flight: the element bleeds in
// from both sides of the frame. Flash-toggle-gated (it is a bright wash);
// reduced motion halves it. Screen-space, drawn after the world restore.
function drawElementalWash() {
  if (elementWash.level <= 0.02 || !elementWash.color) return;
  if (!$("#flashToggle").checked) return;
  const strength = elementWash.level * (state.accessibility.reducedMotion ? 0.45 : 1) * 0.3;
  const width = W * 0.17;
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = strength;
  const left = ctx.createLinearGradient(0, 0, width, 0);
  left.addColorStop(0, elementWash.color);
  left.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = left;
  ctx.fillRect(0, 0, width, H);
  const right = ctx.createLinearGradient(W, 0, W - width, 0);
  right.addColorStop(0, elementWash.color);
  right.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = right;
  ctx.fillRect(W - width, 0, width, H);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Wave 5 HUD/screen-space presentation. Module-level render-only state on the
// documented superDimLevel pattern: never snapshotted, never read by the
// simulation, driven purely from observed state (health deltas, phase changes,
// combo counts, round wins), so rollback checksums are untouched. Every write
// path is either the render loop (never runs during resimulation) or a DOM
// update function that already early-returns on rollbackResimulating.
// ---------------------------------------------------------------------------

// Cumulative one-shot event totals exposed via snapshot().violence. Unlike
// presentationDebug these are NOT reset per frame: they count discrete DOM/CSS
// effect triggers (an announce, a pip flip) that a per-frame sampler would
// race against, so peak-sampling simply reads the latest monotonic total.
const hudFxDebug = {
  damageGhosts: 0, letterSlams: 0, comboHeat: 0, slashWipes: 0,
  selectSlams: 0, victoryEntrances: 0, pipFlips: 0, timerPulses: 0,
  // w51: clock ticks booked on the same timer edge as timerPulses (QA
  // asserts the two counters agree — a pulse without a tick is a bug).
  timerTicks: 0,
  // Wave 7 render-tech one-shots: monotonic totals on the same pattern.
  // sloMoBlurFrames counts rendered frames with the slow-mo smear active
  // (like cinemaFxDebug.handheldFrames — still monotonic, never reset).
  distortionRings: 0, sloMoBlurFrames: 0, superCutIns: 0,
};
// Release 1.7 DEPTH: monotonic one-shot totals for the new defensive
// mechanics, on the same hudFxDebug pattern. Each increment site sits inside
// a sim path but is guarded by `if (!rollbackResimulating)` (the announce()
// discipline), so a resimulated tick can never double-count and the counters
// never enter a rollback snapshot or checksum.
const mechFxDebug = {
  guardCrushes: 0, quickRises: 0, wakeDelays: 0, airRecoveries: 0, perfectGuards: 0,
  // Release 1.7 wave 11 offense mechanics, same monotonic resim-guarded pattern.
  wallBounces: 0, exThrowables: 0, commandKicks: 0, taunts: 0,
  // 5.3 CLOSE RANGE: the two new close-range reads.
  clinchTechs: 0, meaties: 0, throwWhiffs: 0,
};
// Per-side damage-ghost render state: `health` is the last observed fraction,
// `shown` the ghost bar's current scaleX, `holdMs` the remaining freeze time.
const damageGhostState = [
  { health: null, shown: 1, holdMs: 0, written: -1 },
  { health: null, shown: 1, holdMs: 0, written: -1 },
];
// Per-side combo readout render state for hit-pops, heat tiers and the
// damage count-up.
const comboFxState = [
  { hits: 0, tier: 0, damageShown: 0, damageWritten: -1 },
  { hits: 0, tier: 0, damageShown: 0, damageWritten: -1 },
];
// Render-side phase observer for the round-transition slash wipe.
let hudObservedPhase = null;
// Render-frame clock for the damage-ghost hold/drain easing.
let hudFxLastTime = 0;
// Select-screen latch so the VS slam fires once per double lock.
let selectBothLocked = false;

// ---------------------------------------------------------------------------
// Wave 6 cinematic camera. COMBAT.md guarantees a fixed tournament framing, so
// this is NOT a gameplay camera: it never tracks fighters during normal play.
// Every move here is a brief presentation beat (intro dolly, KO punch-in,
// FINISH THEM dread creep, counter pops, fatality handheld, win settle,
// directional recoil) that eases back to exact identity. All state is
// module-level render-only on the documented superDimLevel pattern: never
// snapshotted, never read by the simulation. Latches set from simulation paths
// follow the announce() pattern (`if (rollbackResimulating) return`) plus a
// simulationTick dedupe so a re-executed tick can never double-fire.
// ---------------------------------------------------------------------------

// The single shared render camera applied around the world draw. zoom/x/y/
// rotation are the applied values (identity = 1/0/0/0); focusX/focusY is the
// world-space pivot the zoom magnifies around (irrelevant at zoom 1). Zoom is
// always >= 1 so the world always overdraws the frame; the HUD layer and all
// screen-space passes draw after the world restore and are never affected.
const cinematicCamera = { zoom: 1, x: 0, y: 0, rotation: 0, focusX: W * 0.5, focusY: H * 0.5 };
// Monotonic one-shot event totals on the hudFxDebug pattern, exposed via
// snapshot().violence. handheldFrames counts rendered frames with the fatality
// handheld wobble active (still monotonic, never reset).
const cinemaFxDebug = {
  koPunchIns: 0, introDollies: 0, dreadCreeps: 0, counterPunchIns: 0,
  handheldFrames: 0, winSettles: 0, impactRecoils: 0,
};
// Transient zoom-punch envelope: { age, attack, hold, release, magnitude,
// focusX, focusY }. Shared by the KO punch-in and the counter/dizzy pops; the
// biggest young punch wins, smaller latches are dropped instead of stacking.
let cameraPunch = null;
let cameraKoTick = -1;
let cameraCounterTick = -1;
let cameraDizzyTick = -1;
let cameraGuardCrushTick = -1;
// Directional impact recoil (screen px). Displacement is kicked along the hit
// direction and returned by an analytic damped oscillation — a push with one
// tiny rebound, not a vibration. Closed-form (amplitude * e^-13t * cos 17t)
// rather than an integrated spring so it is unconditionally stable no matter
// how long a render frame takes.
const cameraRecoil = { x: 0, y: 0, ampX: 0, ampY: 0, age: 0 };
let cameraRecoilTick = -1;
const CAMERA_RECOIL_PX = Object.freeze({ heavy: 2.4, special: 3.2, throw: 3, weapon: 3.4, super: 4 });
// Eased phase-pose state (intro dolly / dread creep / win settle).
let cameraPhaseZoom = 1;
let cameraPhaseRotation = 0;
let cameraFocusX = W * 0.5;
let cameraFocusY = H * 0.5;
// Fatality handheld drift (smoothed visualRandom walk) and dutch tilt.
let cameraHandheldX = 0;
let cameraHandheldY = 0;
let cameraHandheldTargetX = 0;
let cameraHandheldTargetY = 0;
let cameraHandheldClock = 0;
let cameraDutch = 0;
// Render-side phase edge observer for the one-shot counters (same pattern as
// hudObservedPhase — draw() never runs during rollback resimulation).
let cameraObservedPhase = null;
// Intro cinema-bar deployment level (0..1), canvas-drawn screen-space.
let letterboxLevel = 0;
// Win-pose curtain-call dim, eased in the sim tick beside superDimLevel on the
// same deliberately-unsnapshotted pattern (a resimulation just re-eases it).
let roundOverDimLevel = 0;
// 2.8: kill-spotlight dim for a triggered graphic fatality — the street goes
// dark and the kill stays lit, on the same unsnapshotted eased-level pattern.
let fatalitySpotLevel = 0;

function cameraMotionScale() {
  return state.accessibility.reducedMotion ? 0 : state.accessibility.shakeScale;
}

// Shared wall-pin read (pose selector + the 2.7 wall-splat camera framing):
// a victim carried into the arena bound by slam-grade force — the same 220
// threshold the wave-4 splat spawn uses, so light corner pokes never count.
// Returns -1 (left wall), 1 (right wall) or 0. Pure snapshotted sim fields.
function fighterWallPin(fighter) {
  if (!fighter || !(fighter.hitstunFrames > 0 || fighter.pendingKnockdown)) return 0;
  const atMinWall = fighter.x <= MOVEMENT_RULES.stageMinX + 0.5;
  const atMaxWall = fighter.x >= MOVEMENT_RULES.stageMaxX - 0.5;
  const pinned = (atMinWall || atMaxWall) && (!fighter.grounded
    || (atMaxWall && fighter.vx > 220) || (atMinWall && fighter.vx < -220));
  return pinned ? (atMinWall ? -1 : 1) : 0;
}

// 2.7 critic round M3: render-only x-shift that slides the frame toward an
// active wall splat (composed into cinematicCamera.x beside recoil and
// handheld). Snapped to exactly 0 once the pin releases and the ease lands.
let wallsplatShift = 0;
// 2.8 residual: a grounded (non-bounce) wall pin only satisfies
// fighterWallPin() for the 2-3 ticks the slam velocity survives the wall
// clamp, so the eased shift/push-in barely engaged before decaying. This
// render-only dwell latch keeps the framing TARGET alive for a minimum beat
// after the last live pin tick; the existing ease/decay still owns all the
// motion and the snap back to exact identity the smoke asserts. Cleared by
// resetCinematicCamera(), and self-invalidating if the sim tick ever moves
// backwards past it (new match reseed).
const WALLSPLAT_DWELL_TICKS = 14;
let wallsplatHold = null; // { untilTick, victimIndex, pin }
// Companion 0..1 focus level for the same beat: while a pin is live the
// pinned side's foreground occluder dressing (the somerset chain-link was
// drawing OVER the splat cell) racks down to ~15% and eases back after.
let wallsplatFocus = 0;
let wallsplatFocusSide = 1;

// KO freeze-frame punch-in: latched from checkKnockout() on the killing hit.
// Fast attack, held through the hitstop freeze, easing back out while the
// FINISH THEM stand-off (and later the roundover call) takes over.
function latchKoCameraPunch() {
  if (rollbackResimulating || cameraKoTick === state.simulationTick) return;
  cameraKoTick = state.simulationTick;
  const [first, second] = state.fighters;
  const focusX = first && second ? (first.x + second.x) * 0.5 : W * 0.5;
  const focusY = first && second ? (first.y + second.y) * 0.5 - 128 : H * 0.5;
  cameraPunch = {
    age: 0, attack: 0.07, hold: 0.5, release: 0.45, magnitude: 0.08,
    focusX: clamp(focusX, 0, W), focusY: clamp(focusY, 0, H),
  };
  cinemaFxDebug.koPunchIns += 1;
}

function latchCameraPunchEnvelope(magnitude, focusX, focusY, attack, hold, release) {
  if (cameraPunch && cameraPunch.magnitude > magnitude
    && cameraPunch.age < cameraPunch.attack + cameraPunch.hold) return false;
  cameraPunch = {
    age: 0, attack, hold, release, magnitude,
    focusX: clamp(focusX, 0, W), focusY: clamp(focusY, 0, H),
  };
  return true;
}

// Counter-hit pop: ~5 frame attack to 1.05x on the impact point, back inside
// 0.4s. Latched from spawnHit's counter path so projectiles count too.
function latchCounterCameraPunch(x, y) {
  if (rollbackResimulating || cameraCounterTick === state.simulationTick) return;
  cameraCounterTick = state.simulationTick;
  if (latchCameraPunchEnvelope(0.05, x, y, 0.08, 0.05, 0.26)) cinemaFxDebug.counterPunchIns += 1;
}

// Dizzy pop: same magnitude, slightly longer hold on the stumbling victim.
function latchDizzyCameraPunch(fighter) {
  if (rollbackResimulating || cameraDizzyTick === state.simulationTick) return;
  cameraDizzyTick = state.simulationTick;
  if (latchCameraPunchEnvelope(0.05, fighter.x, fighter.y - 118, 0.08, 0.08, 0.24)) {
    cinemaFxDebug.counterPunchIns += 1;
  }
}

// Release 1.7: guard-crush pop on the shattered defender — the dizzy latch
// pattern verbatim (render-only, resim-guarded, tick-deduped).
function latchGuardCrushCameraPunch(fighter) {
  if (rollbackResimulating || cameraGuardCrushTick === state.simulationTick) return;
  cameraGuardCrushTick = state.simulationTick;
  if (latchCameraPunchEnvelope(0.05, fighter.x, fighter.y - 118, 0.08, 0.1, 0.26)) {
    cinemaFxDebug.counterPunchIns += 1;
  }
}

// Directional impact recoil for landed heavy-class hits. Replaces nothing:
// the existing noise shake still runs; this layers a 2-4px directional shove
// under it. Scaled by the shake setting, zeroed under reduced motion.
function latchCameraRecoil(kind, direction) {
  const px = CAMERA_RECOIL_PX[kind];
  if (!px || rollbackResimulating || cameraRecoilTick === state.simulationTick) return;
  cameraRecoilTick = state.simulationTick;
  const scale = cameraMotionScale();
  cameraRecoil.ampX = clamp(cameraRecoil.x + direction * px * scale, -6, 6);
  cameraRecoil.ampY = clamp(cameraRecoil.y + px * 0.22 * scale, -6, 6);
  cameraRecoil.age = 0;
  cinemaFxDebug.impactRecoils += 1;
}

// One call from spawnHit covers both cinema latches for a landed hit.
function latchImpactCinema(x, y, kind, blocked, direction, counter) {
  if (blocked) return;
  latchCameraRecoil(kind, direction);
  if (counter) latchCounterCameraPunch(x, y);
}

function resetCinematicCamera() {
  cameraPunch = null;
  wallsplatShift = 0;
  wallsplatFocus = 0;
  wallsplatHold = null;
  cameraRecoil.x = 0;
  cameraRecoil.y = 0;
  cameraRecoil.ampX = 0;
  cameraRecoil.ampY = 0;
  cameraRecoil.age = 0;
  cameraPhaseZoom = 1;
  cameraPhaseRotation = 0;
  cameraFocusX = W * 0.5;
  cameraFocusY = H * 0.5;
  cameraHandheldX = 0;
  cameraHandheldY = 0;
  cameraHandheldTargetX = 0;
  cameraHandheldTargetY = 0;
  cameraHandheldClock = 0;
  cameraDutch = 0;
  cameraObservedPhase = null;
  letterboxLevel = 0;
  cinematicCamera.zoom = 1;
  cinematicCamera.x = 0;
  cinematicCamera.y = 0;
  cinematicCamera.rotation = 0;
  cinematicCamera.focusX = W * 0.5;
  cinematicCamera.focusY = H * 0.5;
}

// Called once per rendered frame from draw(), before the world transform.
// Observes snapshotted state (phase, phaseTime, finisher progress, fighter
// positions), eases the presentation camera toward the current beat's pose and
// always back to exact identity when nothing owns the frame. Never writes sim
// state; never runs during rollback resimulation (draw() cannot).
function updateCinematicCamera(dtMs) {
  const dt = clamp(dtMs / 1000, 0.001, 0.1);
  const cam = cinematicCamera;
  if (state.screen !== "fight" || state.fighters.length !== 2) {
    resetCinematicCamera();
    return;
  }
  const motion = cameraMotionScale();
  const reduced = state.accessibility.reducedMotion;
  const phase = state.phase;
  const finisher = state.finisher;
  const [first, second] = state.fighters;
  const midX = (first.x + second.x) * 0.5;
  const midY = clamp((first.y + second.y) * 0.5 - 128, H * 0.3, H * 0.72);

  // One-shot beat counters on phase edges (fires even when reduced motion
  // strips the zoom itself — the beat still happened, bars/spotlight remain).
  if (cameraObservedPhase !== phase) {
    if (phase === "intro") cinemaFxDebug.introDollies += 1;
    else if (phase === "finish" && !finisher) cinemaFxDebug.dreadCreeps += 1;
    else if (phase === "roundover" && !finisher && state.finisherType < 0) cinemaFxDebug.winSettles += 1;
    cameraObservedPhase = phase;
  }

  // Phase pose target. Identity by default: normal fight play NEVER gets a
  // tracking pose, only the transient punch/recoil envelopes below.
  let targetZoom = 1;
  let targetFocusX = W * 0.5;
  let targetFocusY = H * 0.5;
  let targetRotation = 0;
  let ease = 1 - Math.exp(-dt * 9);
  // 2.7 critic round M3: while a wall splat is live, the frame slides toward
  // the wall (plus a slight push-in focused on the bound) so the pinned
  // victim — whose cell overhangs the arena bound by ~40-60px — is fully in
  // frame instead of cropped at the canvas edge.
  let splatShiftTarget = 0;
  let splatVictim = null;
  let splatPin = 0;
  if (!finisher && !reduced && phase === "fight") {
    for (let index = 0; index < state.fighters.length; index += 1) {
      const pin = fighterWallPin(state.fighters[index]);
      if (!pin) continue;
      splatVictim = state.fighters[index];
      splatPin = pin;
      // Refresh the dwell while the pin is live: engagement always outlasts
      // the pin by WALLSPLAT_DWELL_TICKS so 2-3-tick grounded pins read.
      wallsplatHold = {
        untilTick: state.simulationTick + WALLSPLAT_DWELL_TICKS,
        victimIndex: index,
        pin,
      };
      break;
    }
    if (!splatVictim && wallsplatHold) {
      const remaining = wallsplatHold.untilTick - state.simulationTick;
      const heldVictim = state.fighters[wallsplatHold.victimIndex];
      if (remaining <= 0 || remaining > WALLSPLAT_DWELL_TICKS || !heldVictim) {
        wallsplatHold = null;
      } else {
        splatVictim = heldVictim;
        splatPin = wallsplatHold.pin;
      }
    }
  } else if (wallsplatHold) {
    wallsplatHold = null;
  }
  if (finisher) {
    // The scripted finisher camera owns framing: collapse the pose and any
    // pending punch instantly so nothing leaks under the cinematic transform.
    cameraPhaseZoom = 1;
    cameraPhaseRotation = 0;
    cameraPunch = null;
  } else if (phase === "intro" && !reduced) {
    // Broadcast open: start 1.08x tight on the square-up, pull out to full
    // arena width timed so identity lands with FIGHT! (phaseTime 2.1 -> 0.9).
    // A flow-skip flips phase to "fight" and the brisk default ease whips the
    // camera home in a few frames, which reads as a cut.
    const progress = clamp((2.1 - state.phaseTime) / 1.2, 0, 1);
    const eased = progress * progress * (3 - 2 * progress);
    targetZoom = 1 + 0.08 * (1 - eased);
    targetFocusX = midX;
    targetFocusY = midY;
    ease = 1 - Math.exp(-dt * 14);
  } else if (phase === "finish" && !reduced) {
    // FINISH THEM dread: slow 1.04x creep biased onto the helpless victim
    // with a subtle 0.3-degree sway. Expiry or a finisher start both leave
    // this branch, and the default ease snaps the pose back to identity.
    const victim = state.fighters[1 - state.finishWinner] || second;
    const creep = clamp((6 - state.phaseTime) / 5.5, 0, 1);
    targetZoom = 1 + 0.04 * creep;
    targetFocusX = lerp(midX, victim.x, 0.7);
    targetFocusY = clamp(victim.y - 128, H * 0.3, H * 0.72);
    targetRotation = Math.sin(state.simulationTick * 0.021) * (Math.PI / 180) * 0.3 * creep;
    ease = 1 - Math.exp(-dt * 3.2);
  } else if (phase === "roundover" && state.finisherType < 0 && !reduced) {
    // Win-pose settle: gentle 1.03x drift toward the winner under the
    // curtain-call spotlight. Skipped whenever a fatality owns the frame.
    const winner = first.health >= second.health ? first : second;
    targetZoom = 1.03;
    targetFocusX = winner.x;
    targetFocusY = clamp(winner.y - 128, H * 0.3, H * 0.72);
    ease = 1 - Math.exp(-dt * 2.2);
  } else if (splatVictim) {
    // Wall-splat framing: 1.05x focused ON the wall, plus the x-shift below —
    // zoom alone can never reveal world-space past the canvas edge, so the
    // shift carries the overhang into frame while the push-in hides the
    // world edge the shift would otherwise expose on the opposite side.
    const half = fighterRenderSize(splatVictim.def.id) * 0.55;
    const overhang = splatPin > 0
      ? Math.max(0, splatVictim.x + half - W)
      : Math.max(0, half - splatVictim.x);
    splatShiftTarget = -splatPin * (overhang + 8);
    targetZoom = 1.05;
    targetFocusX = splatPin > 0 ? W : 0;
    targetFocusY = clamp(splatVictim.y - 118, H * 0.3, H * 0.72);
    ease = 1 - Math.exp(-dt * 11);
  }
  cameraPhaseZoom += (targetZoom - cameraPhaseZoom) * ease;
  cameraPhaseRotation += (targetRotation - cameraPhaseRotation) * (1 - Math.exp(-dt * 6));
  cameraFocusX += (targetFocusX - cameraFocusX) * ease;
  cameraFocusY += (targetFocusY - cameraFocusY) * ease;

  // Wall-splat x-shift: eases in fast with the pin, decays back and SNAPS to
  // exactly 0 (the identity contract the smoke asserts on cam.x).
  wallsplatShift += (splatShiftTarget - wallsplatShift)
    * (1 - Math.exp(-dt * (splatShiftTarget !== 0 ? 11 : 7)));
  if (splatShiftTarget === 0 && Math.abs(wallsplatShift) < 0.03) wallsplatShift = 0;
  // Matching focus level for the pinned side's foreground dressing.
  if (splatPin) wallsplatFocusSide = splatPin;
  wallsplatFocus += ((splatVictim ? 1 : 0) - wallsplatFocus)
    * (1 - Math.exp(-dt * (splatVictim ? 10 : 5)));
  if (!splatVictim && wallsplatFocus < 0.01) wallsplatFocus = 0;

  // Transient zoom-punch envelope (KO / counter / dizzy).
  let punchZoom = 1;
  if (cameraPunch) {
    cameraPunch.age += dt;
    const { age, attack, hold, release, magnitude } = cameraPunch;
    let shape = 0;
    if (age < attack) shape = age / attack;
    else if (age < attack + hold) shape = 1;
    else if (age < attack + hold + release) {
      const tail = (age - attack - hold) / release;
      shape = 1 - tail * tail * (3 - 2 * tail);
    } else cameraPunch = null;
    if (cameraPunch && shape > 0 && motion > 0) {
      punchZoom = 1 + magnitude * shape * motion;
      const pull = shape * (1 - Math.exp(-dt * 12));
      cameraFocusX += (cameraPunch.focusX - cameraFocusX) * pull;
      cameraFocusY += (cameraPunch.focusY - cameraFocusY) * pull;
    }
  }

  // Directional recoil: closed-form fast return with one small rebound,
  // then a hard zero (~0.3s from kick to rest).
  if (cameraRecoil.ampX !== 0 || cameraRecoil.ampY !== 0) {
    cameraRecoil.age += dt;
    const decay = Math.exp(-13 * cameraRecoil.age);
    const wave = Math.cos(17 * cameraRecoil.age);
    cameraRecoil.x = cameraRecoil.ampX * decay * wave;
    cameraRecoil.y = cameraRecoil.ampY * decay * wave;
    if (decay < 0.02) {
      cameraRecoil.x = 0;
      cameraRecoil.y = 0;
      cameraRecoil.ampX = 0;
      cameraRecoil.ampY = 0;
      cameraRecoil.age = 0;
    }
  }

  // Fatality handheld drift + dutch tilt, only while a finisher cinematic
  // plays. Drift is a smoothed visualRandom walk (~2px), the dutch eases in
  // hard at the fatal impact and unwinds through the aftermath. Both are
  // zeroed by reduced motion and scale with the shake setting.
  if (finisher && motion > 0) {
    // 2.8 critic round: ride the live hold clock so the handheld drift and
    // dutch actually UNWIND through the aftermath (elapsed saturates).
    const aftermath = finisherAftermathSeconds(finisher);
    const fade = clamp(1 - aftermath / 2.6, 0, 1);
    const amplitude = 2 * motion * fade;
    cameraHandheldClock -= dt;
    if (cameraHandheldClock <= 0) {
      cameraHandheldClock = 0.18 + visualRandom() * 0.22;
      cameraHandheldTargetX = (visualRandom() - 0.5) * 2 * amplitude;
      cameraHandheldTargetY = (visualRandom() - 0.5) * 1.4 * amplitude;
    }
    const drift = 1 - Math.exp(-dt * 3.4);
    cameraHandheldX += (cameraHandheldTargetX - cameraHandheldX) * drift;
    cameraHandheldY += (cameraHandheldTargetY - cameraHandheldY) * drift;
    if (amplitude > 0.05) cinemaFxDebug.handheldFrames += 1;
    const struck = finisher.elapsed >= finisher.fatalityAt;
    const dutchTarget = struck
      ? (Math.PI / 180) * 2.5 * finisher.direction * clamp(1 - aftermath / 2.2, 0, 1) * motion
      : 0;
    const dutchRate = struck && aftermath < 0.4 ? 10 : 2.6;
    cameraDutch += (dutchTarget - cameraDutch) * (1 - Math.exp(-dt * dutchRate));
  } else {
    cameraHandheldTargetX = 0;
    cameraHandheldTargetY = 0;
    const settle = 1 - Math.exp(-dt * 8);
    cameraHandheldX += (0 - cameraHandheldX) * settle;
    cameraHandheldY += (0 - cameraHandheldY) * settle;
    cameraDutch += (0 - cameraDutch) * settle;
  }

  // Intro cinema bars: slide in during the intro, retract as FIGHT! lands.
  const barTarget = phase === "intro" && !finisher ? 1 : 0;
  letterboxLevel += (barTarget - letterboxLevel) * (1 - Math.exp(-dt * (barTarget > letterboxLevel ? 9 : 13)));
  if (letterboxLevel < 0.004) letterboxLevel = 0;

  // Compose, then snap-to-identity epsilons: a stuck camera is the failure
  // mode that matters, so anything within a hair of identity becomes identity.
  cam.zoom = cameraPhaseZoom * punchZoom;
  cam.rotation = cameraPhaseRotation + cameraDutch;
  cam.x = cameraRecoil.x + cameraHandheldX + wallsplatShift;
  cam.y = cameraRecoil.y + cameraHandheldY;
  cam.focusX = clamp(cameraFocusX, 0, W);
  cam.focusY = clamp(cameraFocusY, 0, H);
  if (Math.abs(cam.zoom - 1) < 0.0006) {
    cam.zoom = 1;
    if (Math.abs(cameraPhaseZoom - 1) < 0.0006) cameraPhaseZoom = 1;
  }
  if (Math.abs(cam.rotation) < 0.00025) {
    cam.rotation = 0;
    if (Math.abs(cameraPhaseRotation) < 0.00025) cameraPhaseRotation = 0;
    if (Math.abs(cameraDutch) < 0.00025) cameraDutch = 0;
  }
  if (Math.abs(cam.x) < 0.03) cam.x = 0;
  if (Math.abs(cam.y) < 0.03) cam.y = 0;
}

// Screen-space intro cinema bars, drawn after the world restore + stage grade
// so the camera transform never touches them. The finisher overlay owns its
// own bars, so these stand down whenever a finisher is live.
function drawIntroLetterbox() {
  if (letterboxLevel <= 0 || state.finisher || state.screen !== "fight") return;
  const barHeight = Math.round(52 * letterboxLevel);
  if (barHeight < 1) return;
  ctx.fillStyle = "rgba(0,0,0,.92)";
  ctx.fillRect(0, 0, W, barHeight);
  ctx.fillRect(0, H - barHeight, W, barHeight);
  ctx.fillStyle = `rgba(255,213,74,${(0.75 * letterboxLevel).toFixed(3)})`;
  ctx.fillRect(0, barHeight - 2, W, 2);
  ctx.fillRect(0, H - barHeight, W, 2);
}

// Remove-reflow-add so a one-shot CSS animation class replays reliably.
function restartCssAnimation(element, className) {
  if (!element) return;
  element.classList.remove(className);
  void element.offsetWidth;
  element.classList.add(className);
}

function escapeAnnounceChar(character) {
  return character === "&" ? "&amp;" : character === "<" ? "&lt;" : character === ">" ? "&gt;" : character;
}

// Diagonal accent slash across the screen on round transitions. Pure
// compositor CSS; body.reduced-motion swaps the sweep for a soft crossfade
// via a higher-specificity override in styles.css.
function triggerScreenWipe(accent) {
  const wipe = $("#screenWipe");
  if (!wipe) return;
  wipe.style.setProperty("--wipe-accent", accent);
  restartCssAnimation(wipe, "run");
  hudFxDebug.slashWipes += 1;
}

// Observed-phase edge detector, called once per rendered frame from draw().
// Fires the slash wipe leaving the intro (intro -> fight) and entering
// roundover. draw() never runs during rollback resimulation, so no guard is
// needed beyond the screen check.
function observeFightPhaseWipes() {
  if (state.screen !== "fight") {
    hudObservedPhase = null;
    return;
  }
  const phase = state.phase;
  if (hudObservedPhase === null) {
    hudObservedPhase = phase;
    return;
  }
  if (phase === hudObservedPhase) return;
  if (hudObservedPhase === "intro" && phase === "fight") triggerScreenWipe("var(--cyan)");
  else if (phase === "roundover") triggerScreenWipe("var(--red)");
  hudObservedPhase = phase;
}

// SF-style hold-then-drain damage ghost. Runs in the render loop: freshly
// lost health freezes the pale ghost segment (bright + a white chunk flash)
// for ~0.6s — extended while the victim is still being combo'd — then drains
// down in one smooth sweep. Under reducedMotion the drain snaps instead.
function updateDamageGhosts(dtMs) {
  if (state.screen !== "fight" || state.fighters.length < 2) {
    damageGhostState[0].health = null;
    damageGhostState[1].health = null;
    return;
  }
  const reduced = state.accessibility.reducedMotion;
  for (let side = 0; side < 2; side += 1) {
    const fighter = state.fighters[side];
    const ghost = damageGhostState[side];
    const element = $(`#p${side + 1}Damage`);
    if (!element) continue;
    const health = clamp(fighter.health, 0, 100) / 100;
    if (ghost.health === null || health > ghost.health + 0.0001) {
      // Fresh round or a heal (training auto-recover): snap, no ghost.
      ghost.shown = health;
      ghost.holdMs = 0;
    } else if (health < ghost.health - 0.0001) {
      // Damage: freeze the ghost at the pre-hit value so the whole combo's
      // loss reads as one bright chunk, and flash the fresh chunk white.
      ghost.shown = Math.max(ghost.shown, ghost.health);
      ghost.holdMs = 600;
      hudFxDebug.damageGhosts += 1;
      if ($("#flashToggle").checked && !reduced) restartCssAnimation(element, "chunk-flash");
    }
    ghost.health = health;
    const inCombo = fighter.hitstunFrames > 0 || fighter.pendingKnockdown;
    if (ghost.shown > health + 0.0001) {
      if (inCombo) ghost.holdMs = Math.max(ghost.holdMs, 240);
      if (ghost.holdMs > 0) ghost.holdMs = Math.max(0, ghost.holdMs - dtMs);
      else if (reduced) ghost.shown = health;
      else {
        // Proportional sweep: big chunks drain visibly faster, small chips
        // still clear in well under a second.
        const rate = Math.max(0.55, (ghost.shown - health) * 2.6);
        ghost.shown = Math.max(health, ghost.shown - rate * (dtMs / 1000));
      }
    } else {
      ghost.shown = health;
      ghost.holdMs = 0;
    }
    element.classList.toggle("hold", ghost.holdMs > 0);
    if (Math.abs(ghost.shown - ghost.written) > 0.0005) {
      ghost.written = ghost.shown;
      element.style.transform = `scaleX(${ghost.shown.toFixed(4)})`;
    }
    // Release 1.7: guard-gauge sliver INSIDE the health frame (a new HUD row
    // would shrink the fighter-framing area — HANDOFF.md landmine). Synced
    // per rendered frame beside the damage ghost so decay visibly drains;
    // during a crush the sliver flips into the flashing crush-drain bar.
    const guardGauge = $(`#p${side + 1}GuardGauge`);
    if (guardGauge) {
      const crushed = fighter.guardCrushFrames > 0;
      const level = crushed
        ? fighter.guardCrushFrames / Math.max(1, fighter.guardCrushTotalFrames)
        : clamp(fighter.guardMeter, 0, GUARD_RULES.threshold) / GUARD_RULES.threshold;
      guardGauge.style.transform = `scaleX(${level.toFixed(4)})`;
      guardGauge.classList.toggle("crushed", crushed);
      guardGauge.classList.toggle("charged", !crushed && fighter.guardMeter >= GUARD_RULES.threshold * 0.65);
    }
  }
}

// ---------------------------------------------------------------------------
// Wave 3 stage presentation. Everything below is module-level render-only
// state on the documented superDimLevel pattern: never snapshotted, never read
// by the simulation, so rollback checksums are untouched.
// ---------------------------------------------------------------------------

// Small deterministic hash for presentation scatter (weather fields, crowd
// flash picks, light flicker phases). Pure function of its inputs — it never
// consumes the visualRandom stream, so draw order can't perturb other effects.
function presentationHash01(...nums) {
  let h = 2166136261;
  for (const n of nums) {
    h ^= Math.imul((n | 0) + 0x9e3779b9, 2654435761);
    h = Math.imul(h ^ (h >>> 13), 3266489917);
  }
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

// --- Rack focus: pre-blurred half-res stage covers, cross-faded in by the ---
// --- super dim ease / fatality state so the world softens behind the kill ---
const RACK_FOCUS_W = 640;
const RACK_FOCUS_H = 360;
const blurredStageCovers = {};
// Eased focus level (0 sharp → 1 fully racked). Render-only module state.
let rackFocusLevel = 0;

// Lazily pre-blur ONE stage backdrop the first time its rack focus is needed,
// not every stage at boot. ~640x360 RGBA is ~0.9MB per stage; even all six
// stay under 6MB.
function blurredStageCover(stageId) {
  const cached = blurredStageCovers[stageId];
  if (cached) return cached;
  const image = stageImages[stageId];
  if (!image?.complete || !image.naturalWidth) return null;
  const cover = document.createElement("canvas");
  cover.width = RACK_FOCUS_W;
  cover.height = RACK_FOCUS_H;
  const paint = cover.getContext("2d");
  const scale = Math.max(RACK_FOCUS_W / image.naturalWidth, RACK_FOCUS_H / image.naturalHeight);
  const dw = image.naturalWidth * scale;
  const dh = image.naturalHeight * scale;
  // Blur at half resolution: 5px here reads as ~10px once upscaled to 1280.
  paint.filter = "blur(5px)";
  paint.drawImage(image, (RACK_FOCUS_W - dw) * 0.5, (RACK_FOCUS_H - dh) * 0.5, dw, dh);
  paint.filter = "none";
  blurredStageCovers[stageId] = cover;
  return cover;
}

// Ease + draw the blurred copy over the sharp cover. Alpha rides the existing
// superDimLevel ease while a super flies; a triggered fatality holds the world
// soft for the whole aftermath. Static cross-fade — not motion — so it stays
// on under reducedMotion, exactly like the super spotlight.
function drawRackFocus(parallax) {
  const target = Math.max(superDimLevel, state.finisher?.fatalityTriggered ? 1 : 0);
  rackFocusLevel = clamp(rackFocusLevel + clamp(target - rackFocusLevel, -0.05, 0.08), 0, 1);
  if (rackFocusLevel <= 0.02) return;
  const cover = blurredStageCover(state.stage);
  if (!cover) return;
  // Same cover-fit math as drawCover, oversized 2% to hide the blur fringe.
  const scale = Math.max(W / cover.width, H / cover.height) * 1.02;
  const dw = cover.width * scale;
  const dh = cover.height * scale;
  ctx.save();
  ctx.globalAlpha = rackFocusLevel;
  ctx.drawImage(cover, (W - dw) * 0.5 + parallax, (H - dh) * 0.5, dw, dh);
  ctx.restore();
}

// --- Stage battle scars: the arena wears the fight ------------------------
// 5.3 SPECTACLE (#19): through 5.2 this was ONE flavour — a chalky scuff and
// a dark crack — pushed from ONE call site (the knockdown floor impact) onto
// six different floors: the same grey crack on the Vet's asphalt, the
// buffet's tile, the boardwalk's planks and a wet pool deck, while the arena
// edge that had just taken a wall splat kept nothing at all.
//
// Now the MODEL lives in engine/stage-scars.mjs (surfaces, kinds, which kind
// a cause leaves on which material, the geometry builder and the CINEMA 3D
// decal view) and this file keeps only the list: the module-level array
// (never snapshotted), the rollback guard, the (tick, x) dedupe, the cap, and
// the 2D painter. Three causes push now — knockdowns, wall splats (at the
// arena edge, standing UP on the wall) and stage-weapon impacts — and the
// same list rides the host bridge into CINEMA 3D as ground/wall decals.
const STAGE_SCAR_CAP = 24;
const STAGE_SCAR_CAP_BATTERY = 10;
const stageScars = [];

function pushStageScar(x, force = 1, options = {}) {
  if (rollbackResimulating) return null;
  const tick = state.simulationTick;
  const wall = options.wall || 0;
  if (stageScars.some((scar) => scar.tick === tick && scar.wall === wall && Math.abs(scar.x - x) < 1)) return null;
  const scar = makeStageScar({
    x: clamp(x, 70, W - 70),
    // A floor mark lies in the band just below the floor line (the 5.2
    // spread, kept); a wall mark sits at the height the body hit the edge.
    // 5.3: the 5.2 band (FLOOR+8..FLOOR+66) sat on the dark apron BELOW the
    // floor line, where the plates stop drawing ground — measured on the
    // canvas, ten heavy marks there moved the mean brightness of the lit
    // floor by 0.0 on every stage. The band is now FLOOR-46..FLOOR+8, the
    // lit ground the fighters actually stand on (+2.2 to +4.0 mean over a
    // 480x40 rect for ten marks). drawStageScars still runs before the
    // fighters, so a body always passes in front of its own scar.
    y: wall ? clamp(options.y ?? FLOOR - 150, 180, FLOOR - 20) : FLOOR - 46 + visualRandom() * 54,
    stageId: state.stage,
    cause: options.cause || "knockdown",
    weaponStyle: options.weaponStyle || null,
    force,
    tick,
    wall,
    random: visualRandom,
  });
  stageScars.push(scar);
  const cap = state.performance.trailScale === 0 ? STAGE_SCAR_CAP_BATTERY : STAGE_SCAR_CAP;
  if (stageScars.length > cap) stageScars.splice(0, stageScars.length - cap);
  return scar;
}

function clearStageScars() {
  stageScars.length = 0;
}

// The bridge view: CINEMA 3D draws these as decal quads (ground plane and
// arena-edge walls) so the 3D arena wears the fight the same way.
function stageScarDecals() {
  return scarDecals(stageScars);
}

function drawStageScars() {
  if (!stageScars.length) return;
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (const scar of stageScars) {
    const spec = SCAR_KINDS[scar.kind] || SCAR_KINDS.crack;
    ctx.save();
    ctx.translate(scar.x, scar.y);
    ctx.rotate(scar.rot);
    // The stain / scuff / puddle first, in the kind's own colour, so the
    // marks above it sit on a bruised patch. A splash and a spill ARE this
    // ellipse (they carry no crack), which is why the alpha is higher for
    // the kinds that draw no lines.
    ctx.globalAlpha = scar.alpha * (spec.lines ? 0.34 : 0.6);
    ctx.fillStyle = spec.scuff;
    ctx.beginPath();
    ctx.ellipse(0, 0, scar.scuffW, scar.scuffH, 0, 0, Math.PI * 2);
    ctx.fill();
    // Wet kinds get a bright rim: the read that says "this is liquid".
    if (!spec.lines) {
      ctx.globalAlpha = scar.alpha * 0.5;
      ctx.strokeStyle = spec.edge;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.ellipse(0, 0, scar.scuffW * 0.94, scar.scuffH * 0.9, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.globalAlpha = scar.alpha;
    // Cracks / splits / glass stars: a pale chipped edge one pixel up, then
    // the dark line itself. `lines` is how many times the polyline is drawn
    // rotated about the centre — 1 for a crack, 3 for a glass star.
    for (let line = 0; line < spec.lines; line += 1) {
      ctx.save();
      if (line) ctx.rotate((line * Math.PI * 2) / spec.lines);
      for (const [style, width, offsetY] of [
        [spec.edge, scar.heavy ? 3 : 2.2, -1.4],
        [spec.ink, scar.heavy ? 2.2 : 1.5, 0],
      ]) {
        ctx.strokeStyle = style;
        ctx.lineWidth = width;
        ctx.beginPath();
        ctx.moveTo(scar.points[0][0], scar.points[0][1] + offsetY);
        for (let index = 1; index < scar.points.length; index += 1) {
          ctx.lineTo(scar.points[index][0], scar.points[index][1] + offsetY);
        }
        if (scar.branch.length === 2) {
          ctx.moveTo(scar.branch[0][0], scar.branch[0][1] + offsetY);
          ctx.lineTo(scar.branch[1][0], scar.branch[1][1] + offsetY);
        }
        ctx.stroke();
      }
      ctx.restore();
    }
    // Loose bits left behind: glass chips, splinters, crab legs, slush.
    if (scar.debris.length) {
      ctx.fillStyle = spec.debrisColor;
      for (const bit of scar.debris) {
        ctx.globalAlpha = scar.alpha * 0.85;
        ctx.save();
        ctx.translate(bit.x, bit.y);
        ctx.rotate(bit.a);
        ctx.fillRect(-bit.r, -bit.r * 0.42, bit.r * 2, bit.r * 0.84);
        ctx.restore();
      }
    }
    ctx.restore();
  }
  ctx.restore();
}

// --- Practical light sprites ----------------------------------------------
// Each glow/cone is rendered once into a small offscreen canvas so the
// per-frame cost is a handful of drawImages, never fresh gradients.
const practicalSpriteCache = {};

function practicalSprite(key, width, height, painter) {
  let sprite = practicalSpriteCache[key];
  if (!sprite) {
    sprite = document.createElement("canvas");
    sprite.width = width;
    sprite.height = height;
    painter(sprite.getContext("2d"), width, height);
    practicalSpriteCache[key] = sprite;
  }
  return sprite;
}

function glowSprite(red, green, blue) {
  return practicalSprite(`glow-${red}-${green}-${blue}`, 128, 128, (paint, width, height) => {
    const gradient = paint.createRadialGradient(64, 64, 4, 64, 64, 62);
    gradient.addColorStop(0, `rgba(${red},${green},${blue},0.55)`);
    gradient.addColorStop(0.55, `rgba(${red},${green},${blue},0.18)`);
    gradient.addColorStop(1, `rgba(${red},${green},${blue},0)`);
    paint.fillStyle = gradient;
    paint.fillRect(0, 0, width, height);
  });
}

function coneSprite(red, green, blue) {
  return practicalSprite(`cone-${red}-${green}-${blue}`, 160, 256, (paint, width, height) => {
    paint.beginPath();
    paint.moveTo(width * 0.5 - 7, 0);
    paint.lineTo(width * 0.5 + 7, 0);
    paint.lineTo(width, height);
    paint.lineTo(0, height);
    paint.closePath();
    const fall = paint.createLinearGradient(0, 0, 0, height);
    fall.addColorStop(0, `rgba(${red},${green},${blue},0.5)`);
    fall.addColorStop(0.65, `rgba(${red},${green},${blue},0.16)`);
    fall.addColorStop(1, `rgba(${red},${green},${blue},0)`);
    paint.fillStyle = fall;
    paint.fill();
    // Soften the cone sides so it reads as haze, not a hard triangle.
    paint.globalCompositeOperation = "destination-in";
    const side = paint.createLinearGradient(0, 0, width, 0);
    side.addColorStop(0, "rgba(0,0,0,0)");
    side.addColorStop(0.3, "rgba(0,0,0,1)");
    side.addColorStop(0.7, "rgba(0,0,0,1)");
    side.addColorStop(1, "rgba(0,0,0,0)");
    paint.fillStyle = side;
    paint.fillRect(0, 0, width, height);
  });
}

// --- Practical light sources that cast onto the scene ---------------------
// The lights painted into each backdrop start behaving like lights. All
// additive, all flicker phases from simulationTick hashes, flicker amplitude
// forced to 0 under reducedMotion, whole pass skipped without shadows.
function drawPracticalLights(time, frame, centre, reaction) {
  if (!state.performance.shadows) return;
  const reduced = state.accessibility.reducedMotion;
  const flicker = (speed, phase, amount) =>
    reduced ? 0 : Math.sin(frame * speed + phase * Math.PI * 2) * amount;
  const backdropShift = (centre - W * 0.5) * -0.035;
  // v5.1 STAGE KO BEATS: the painted lights answer the same surge the
  // ambient layer reads (a big hit or the KO beat), so the El band, the
  // boardwalk neon pools and the heat-lamp cones flare with their stages.
  const surge = stageSurge(frame, reduced);
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  if (state.stage === "somerset") {
    // The passing El sweeps a band of warm window-light across the pavement.
    const trainX = ((time * 0.08) % (W + 650)) - 500; // same formula as drawCrowd
    const bandX = trainX + 215;
    if (bandX > -280 && bandX < W + 280) {
      const band = glowSprite(255, 208, 116);
      ctx.globalAlpha = 0.34 + flicker(0.31, 0.2, 0.05) + surge.level * 0.4;
      ctx.drawImage(band, bandX - 260, FLOOR - 66, 520, 132);
      ctx.globalAlpha = 0.2;
      ctx.drawImage(band, bandX - 150, 158, 300, 110); // spill around the cars
      presentationDebug.practicalLights += 2;
    }
  } else if (state.stage === "wildwood") {
    // Neon throbs coloured pools onto the wet planks; the two boardwalk
    // lamps keep steady warm pools beneath their heads.
    const pools = [
      { x: 430, red: 255, green: 122, blue: 214, phase: 0.13, radiusX: 190 },
      { x: 665, red: 255, green: 170, blue: 130, phase: 0.47, radiusX: 220 },
      { x: 915, red: 255, green: 104, blue: 190, phase: 0.79, radiusX: 190 },
      { x: 82, red: 255, green: 198, blue: 122, phase: 0.31, radiusX: 130 },
      { x: 1204, red: 255, green: 198, blue: 122, phase: 0.67, radiusX: 130 },
    ];
    for (const pool of pools) {
      const x = pool.x + backdropShift;
      if (x < -220 || x > W + 220) continue;
      ctx.globalAlpha = 0.24 + flicker(0.06, pool.phase, 0.09) + surge.level * 0.36;
      ctx.drawImage(glowSprite(pool.red, pool.green, pool.blue), x - pool.radiusX, FLOOR - 34, pool.radiusX * 2, 120);
      presentationDebug.practicalLights += 1;
    }
    for (const lampX of [82, 1204]) {
      const x = lampX + backdropShift;
      ctx.globalAlpha = 0.3 + flicker(0.17, lampX, 0.04);
      ctx.drawImage(glowSprite(255, 208, 130), x - 56, 118, 112, 112);
      presentationDebug.practicalLights += 1;
    }
  } else if (state.stage === "buffet") {
    // Heat-lamp cones flicker over the steam table, hanging from the same
    // swaying pendants the atmosphere pass draws (same x, same phase).
    const sway = (0.02 + reaction * 0.05 + surge.level * 0.12) * Math.sin(frame * 0.03);
    const cone = coneSprite(255, 186, 104);
    for (let index = 0; index < 6; index += 1) {
      const x = 150 + index * 200 + (centre - W * 0.5) * -0.1 + Math.sin(sway + index) * 12;
      if (x < -120 || x > W + 120) continue;
      // The cones flare and widen with the surge (a heat lamp kicked to full).
      ctx.globalAlpha = 0.3 + flicker(0.052, index * 0.37, 0.08) + surge.level * 0.5;
      ctx.drawImage(cone, x - 82 - surge.level * 20, 132, 164 + surge.level * 40, 310);
      presentationDebug.practicalLights += 1;
    }
  } else if (state.stage === "janney") {
    // One sodium streetlight cone with dust drifting down through it.
    const lampX = 887 + backdropShift;
    const lampY = 148;
    ctx.globalAlpha = 0.34 + flicker(0.043, 0.61, 0.05);
    ctx.drawImage(coneSprite(255, 178, 84), lampX - 120, lampY, 240, FLOOR - lampY + 20);
    ctx.globalAlpha = 0.4;
    ctx.drawImage(glowSprite(255, 196, 110), lampX - 42, lampY - 40, 84, 84);
    presentationDebug.practicalLights += 2;
    const motes = Math.round(9 * state.performance.particleScale);
    ctx.fillStyle = "rgba(255,214,150,0.5)";
    for (let index = 0; index < motes; index += 1) {
      const seedA = presentationHash01(index, 7);
      const seedB = presentationHash01(index, 19);
      const progress = ((reduced ? seedB : frame * (0.0011 + seedB * 0.0013)) + seedA) % 1;
      const spread = 14 + progress * 100;
      const moteX = lampX + (presentationHash01(index, 37) - 0.5) * 2 * spread
        + (reduced ? 0 : Math.sin(frame * 0.01 + index * 2.1) * 5);
      const moteY = lampY + 16 + progress * (FLOOR - lampY - 24);
      ctx.globalAlpha = 0.3 * Math.sin(progress * Math.PI);
      ctx.fillRect(moteX, moteY, 1.6, 1.6);
    }
  }
  ctx.restore();
  ctx.globalAlpha = 1;
}

// --- Time-of-day drift: pure function of the round number -----------------
function timeOfDayLevel() {
  return clamp(((state.round || 1) - 1) / 2, 0, 1);
}

// A soft horizon band over the sky pulls the backdrop later in the evening as
// rounds go by. Colour comes from the stage grade's "late" tint. Skipped under
// high contrast like every colour overlay.
function drawTimeOfDayHorizon() {
  if (state.accessibility.highContrast) return;
  const late = timeOfDayLevel();
  if (late <= 0.01) return;
  const grade = STAGE_GRADES[state.stage];
  if (!grade) return;
  const [red, green, blue] = grade.late;
  const band = ctx.createLinearGradient(0, 0, 0, H * 0.52);
  band.addColorStop(0, `rgba(${red},${green},${blue},${(0.2 * late).toFixed(3)})`);
  band.addColorStop(1, `rgba(${red},${green},${blue},0)`);
  ctx.fillStyle = band;
  ctx.fillRect(0, 0, W, H * 0.52);
}

// --- Per-stage ambient air: deterministic weather particle fields ---------
// Every particle is a pure function of (index, simulationTick), so the field
// is exact under rollback/replay and costs zero state. Frozen to a static
// scatter under reducedMotion, scaled by particleScale, skipped on battery.
const STAGE_WEATHER = Object.freeze({
  somerset: { count: 24, kind: "litter" },
  vet: { count: 30, kind: "ashSmoke" },
  wildwood: { count: 40, kind: "mist" },
  buffet: { count: 26, kind: "steam" },
  cruise: { count: 32, kind: "sparkle" },
  janney: { count: 36, kind: "motes" },
});

function drawStageWeather(frame, centre) {
  const config = STAGE_WEATHER[state.stage];
  if (!config || state.performance.trailScale === 0) return;
  const reduced = state.accessibility.reducedMotion;
  const tick = reduced ? 0 : frame;
  const count = Math.max(6, Math.round(config.count * state.performance.particleScale));
  const drift = centre - W * 0.5;
  ctx.save();
  for (let index = 0; index < count; index += 1) {
    const seedA = presentationHash01(index, 11);
    const seedB = presentationHash01(index, 29);
    const seedC = presentationHash01(index, 47);
    const seedD = presentationHash01(index, 83);
    const depth = 0.05 + presentationHash01(index, 131) * 0.13;
    let x = 0;
    let y = 0;
    let alpha = 0;
    let size = 2;
    let additive = true;
    let color = "255,255,255";
    let stretch = 1;
    if (config.kind === "mist") {
      // Sea-mist droplets glinting past the neon.
      x = (((seedA * (W + 160)) - tick * (0.35 + seedB * 0.55)) % (W + 160) + (W + 160)) % (W + 160) - 80;
      y = 235 + seedC * 300 + (reduced ? 0 : Math.sin(tick * 0.01 + seedD * 6.28) * 9);
      const glint = reduced ? 0.12 : Math.max(0, Math.sin(tick * 0.05 + seedD * 20)) ** 3 * 0.4;
      alpha = 0.14 + glint;
      size = 1 + seedD * 1.6;
      color = "208,232,255";
    } else if (config.kind === "ashSmoke") {
      if (seedD < 0.45) {
        // Grill smoke wisps drifting up off the lots.
        const cycle = ((tick * (0.22 + seedB * 0.26) + seedA * 300) % 300 + 300) % 300;
        x = 80 + seedA * 1120 + (reduced ? 0 : Math.sin(tick * 0.008 + seedC * 6.28) * 16);
        y = 540 - cycle * 0.9;
        alpha = 0.07 * (1 - cycle / 300) + 0.02;
        size = 7 + cycle * 0.03;
        additive = false;
        color = "196,204,210";
      } else {
        // Drifting ash, falling slow and dark.
        const cycle = ((tick * (0.16 + seedB * 0.22) + seedA * 430) % 430 + 430) % 430;
        x = 40 + seedA * 1200 + (reduced ? 0 : Math.sin(tick * 0.013 + seedC * 6.28) * 22);
        y = 170 + cycle;
        alpha = 0.24 * Math.sin((cycle / 430) * Math.PI);
        size = 1 + seedC * 1.4;
        additive = false;
        color = "48,44,42";
      }
    } else if (config.kind === "steam") {
      // Steam curling up off the buffet line.
      const cycle = ((tick * (0.5 + seedB * 0.6) + seedA * 230) % 230 + 230) % 230;
      x = 110 + seedA * 1060 + (reduced ? 0 : Math.sin(cycle * 0.05 + seedC * 6.28) * 11);
      y = 436 - cycle * 0.78;
      alpha = 0.11 * (1 - cycle / 230) + 0.015;
      size = 4 + cycle * 0.05;
      additive = false;
      color = "238,242,246";
    } else if (config.kind === "motes") {
      // Golden dust hanging in the dusk.
      x = 130 + seedA * 1020 + (reduced ? 0 : Math.sin(tick * 0.004 + seedB * 6.28) * 22);
      y = 250 + seedC * 310 + (reduced ? 0 : Math.sin(tick * 0.006 + seedD * 6.28) * 13);
      alpha = 0.1 + (reduced ? 0.06 : (Math.sin(tick * 0.02 + seedB * 6.28) * 0.5 + 0.5) * 0.14);
      size = 0.9 + seedD * 1.3;
      color = "255,214,140";
    } else if (config.kind === "litter") {
      // Wind-blown litter and grit skimming the Somerset pavement.
      x = (((seedA * (W + 140)) + tick * (0.9 + seedB * 1.3)) % (W + 140) + (W + 140)) % (W + 140) - 70;
      y = 462 + seedC * 128 + (reduced ? 0 : Math.sin(tick * 0.02 + seedD * 6.28) * 7);
      alpha = 0.2;
      size = 1.4 + seedD * 2;
      additive = false;
      color = "125,135,148";
      stretch = 2.4;
    } else if (config.kind === "sparkle") {
      // Sun sparkle over the pool deck.
      x = 70 + seedA * 1140;
      y = 415 + seedC * 165;
      alpha = reduced ? 0.18 : Math.max(0, Math.sin(tick * 0.06 + seedD * 6.28)) ** 4 * 0.65;
      size = 0.8 + seedB * 1.4;
      color = "255,252,238";
    }
    if (alpha <= 0.01) continue;
    const drawX = x + drift * -depth;
    if (drawX < -30 || drawX > W + 30) continue;
    ctx.globalCompositeOperation = additive ? "lighter" : "source-over";
    ctx.globalAlpha = clamp(alpha, 0, 1);
    ctx.fillStyle = `rgb(${color})`;
    ctx.beginPath();
    ctx.ellipse(drawX, y, size * stretch, size, 0, 0, Math.PI * 2);
    ctx.fill();
    presentationDebug.weatherParticles += 1;
  }
  ctx.restore();
  ctx.globalAlpha = 1;
}

// --- Foreground occluder rig ----------------------------------------------
// Silhouetted near-depth dressing at the frame edges, drawn after fighters
// and particles with ~3x the backdrop parallax. Pre-rendered once per stage
// with gradient-soft inner edges (fake depth of field, no per-frame filter),
// confined to the outer ~90px of the frame.
const occluderRigs = {};

function occluderCanvas(width, height, painter, softEdge) {
  const canvasEl = document.createElement("canvas");
  canvasEl.width = width;
  canvasEl.height = height;
  const paint = canvasEl.getContext("2d");
  painter(paint, width, height);
  // Fade the inner edge so the rig reads as out-of-focus depth, not a wall.
  paint.globalCompositeOperation = "destination-in";
  const fade = softEdge === "right"
    ? paint.createLinearGradient(0, 0, width, 0)
    : paint.createLinearGradient(width, 0, 0, 0);
  fade.addColorStop(0, "rgba(0,0,0,1)");
  fade.addColorStop(0.55, "rgba(0,0,0,0.9)");
  fade.addColorStop(1, "rgba(0,0,0,0)");
  paint.fillStyle = fade;
  paint.fillRect(0, 0, width, height);
  return canvasEl;
}

function buildOccluderRig(stageId) {
  const rig = [];
  if (stageId === "somerset") {
    // Chain-link fence corner hugging the left edge.
    rig.push({
      baseX: -34, y: 96, minX: -70, maxX: -6,
      canvas: occluderCanvas(124, 560, (paint, width, height) => {
        paint.strokeStyle = "rgba(8,10,13,0.94)";
        paint.lineWidth = 7;
        paint.beginPath();
        paint.moveTo(16, 0);
        paint.lineTo(16, height);
        paint.stroke();
        paint.lineWidth = 2.4;
        for (let offset = -height; offset < width + height; offset += 26) {
          paint.beginPath();
          paint.moveTo(offset, 0);
          paint.lineTo(offset + height * 0.55, height);
          paint.moveTo(offset + height * 0.55, 0);
          paint.lineTo(offset, height);
          paint.stroke();
        }
        paint.lineWidth = 4;
        paint.beginPath();
        paint.moveTo(0, 26);
        paint.lineTo(width, 44);
        paint.stroke();
      }, "right"),
    });
    // Steaming grate slats in the near right corner.
    rig.push({
      baseX: W - 128, y: H - 118, minX: W - 156, maxX: W - 96, steam: true,
      canvas: occluderCanvas(160, 118, (paint, width, height) => {
        paint.fillStyle = "rgba(6,8,10,0.96)";
        for (let row = 0; row < 5; row += 1) {
          paint.beginPath();
          paint.ellipse(width * 0.62, height - 12 - row * 21, width * 0.52, 8, -0.06, 0, Math.PI * 2);
          paint.fill();
        }
      }, "left"),
    });
  } else if (stageId === "wildwood") {
    // A soft-edged railing post at the right of frame.
    rig.push({
      baseX: W - 112, y: 0, minX: W - 148, maxX: W - 72,
      canvas: occluderCanvas(120, H, (paint, width, height) => {
        paint.fillStyle = "rgba(9,7,12,0.95)";
        paint.fillRect(48, 0, 44, height);
        paint.fillRect(30, 96, 80, 26);
        paint.fillRect(30, 342, 80, 26);
        paint.beginPath();
        paint.ellipse(70, 70, 34, 20, 0, 0, Math.PI * 2);
        paint.fill();
      }, "left"),
    });
  } else if (stageId === "buffet") {
    // Sneeze-guard glass glare sliding along the left edge.
    rig.push({
      baseX: -18, y: 120, minX: -54, maxX: 6, glare: true,
      canvas: occluderCanvas(110, 460, (paint, width, height) => {
        paint.fillStyle = "rgba(16,20,24,0.55)";
        paint.fillRect(0, 0, 30, height);
        const glare = paint.createLinearGradient(0, 0, width, height * 0.4);
        glare.addColorStop(0, "rgba(235,242,250,0)");
        glare.addColorStop(0.45, "rgba(235,242,250,0.34)");
        glare.addColorStop(0.55, "rgba(235,242,250,0.4)");
        glare.addColorStop(1, "rgba(235,242,250,0)");
        paint.fillStyle = glare;
        paint.fillRect(8, 0, width - 8, height);
      }, "right"),
    });
  } else if (stageId === "cruise") {
    // Hanging bar glasses in the top right corner (below the HUD band).
    rig.push({
      baseX: W - 150, y: 168, minX: W - 180, maxX: W - 110,
      canvas: occluderCanvas(210, 128, (paint) => {
        paint.fillStyle = "rgba(10,12,16,0.9)";
        paint.fillRect(0, 0, 210, 16);
        for (let slot = 0; slot < 4; slot += 1) {
          const x = 34 + slot * 46;
          paint.fillRect(x - 2, 16, 4, 18);
          paint.beginPath();
          paint.moveTo(x - 13, 34);
          paint.lineTo(x + 13, 34);
          paint.lineTo(x + 5, 74);
          paint.lineTo(x - 5, 74);
          paint.closePath();
          paint.fill();
        }
      }, "left"),
    });
  }
  return rig;
}

// 2.7 critic round M3: the wall-splat camera shift can reveal a strip of
// world-space past the painted backdrop (stage art covers exactly 0..W).
// While the shift is live this curtains that strip with the frame-edge dark
// — the pinned victim reads against deliberate off-stage shadow, not an
// unpainted band. World-space, drawn between stage and fighters; it costs
// nothing and draws nothing once the shift settles back to exactly 0.
function drawWallsplatEdgeCover() {
  if (wallsplatShift === 0) return;
  const rightWall = wallsplatShift < 0;
  const reach = Math.min(130, Math.abs(wallsplatShift) * 1.6 + 70);
  ctx.save();
  ctx.fillStyle = "#05070b";
  if (rightWall) ctx.fillRect(W - 1, -8, reach, H + 16);
  else ctx.fillRect(1 - reach, -8, reach, H + 16);
  // Soft lip just inside the arena edge so the seam never reads as a cut.
  const lip = 26;
  const gradient = rightWall
    ? ctx.createLinearGradient(W - lip, 0, W, 0)
    : ctx.createLinearGradient(lip, 0, 0, 0);
  gradient.addColorStop(0, "rgba(5,7,11,0)");
  gradient.addColorStop(1, "rgba(5,7,11,0.6)");
  ctx.fillStyle = gradient;
  if (rightWall) ctx.fillRect(W - lip, -8, lip + 1, H + 16);
  else ctx.fillRect(-1, -8, lip + 1, H + 16);
  ctx.restore();
}

function drawForegroundOccluders(centre) {
  if (!state.performance.shadows) return;
  let rig = occluderRigs[state.stage];
  if (!rig) {
    rig = buildOccluderRig(state.stage);
    occluderRigs[state.stage] = rig;
  }
  if (!rig.length) return;
  // ~3x the backdrop parallax; pinned still under reducedMotion.
  const shift = state.accessibility.reducedMotion ? 0 : (centre - W * 0.5) * -0.105;
  const frame = state.simulationTick;
  for (const occluder of rig) {
    // 2.7 critic round M3: while a wall splat is live, the pinned side's
    // near-depth dressing racks down to ~15% (the somerset chain-link drew
    // straight over the splat cell) and eases back once the pin releases.
    const onPinnedSide = (wallsplatFocusSide < 0) === (occluder.baseX < W * 0.5);
    const focusFade = wallsplatFocus > 0.01 && onPinnedSide ? 1 - wallsplatFocus * 0.85 : 1;
    const x = clamp(occluder.baseX + shift, occluder.minX, occluder.maxX);
    ctx.globalAlpha = focusFade;
    ctx.drawImage(occluder.canvas, x, occluder.y);
    if (occluder.steam) {
      // Grate steam: an additive pulse rising off the slats.
      const pulse = state.accessibility.reducedMotion ? 0.5 : Math.sin(frame * 0.035) * 0.5 + 0.5;
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = (0.1 + pulse * 0.12) * focusFade;
      ctx.drawImage(glowSprite(210, 222, 230), x + 30, occluder.y - 130 - pulse * 22, 130, 190);
      ctx.restore();
    }
    presentationDebug.foregroundOccluders += 1;
  }
  ctx.globalAlpha = 1;
}

// --- Crowd flashbulbs + round-win light beats -----------------------------
// Flash picks hash (window, person index) — never the visualRandom stream —
// and are hard-capped at ~3/sec regardless of reaction level. Under
// reducedMotion the strobes become one dim steady glow.
let crowdFlashCacheCrowd = null;
let crowdFlashCacheManifest = null;
let crowdFlashCandidates = [];

// v5.1 KO MOMENT: during the KO hold the phones come out — an 8-tick window
// lit 5 of 8 (7.5 pops/s against the fight's 3/s cap) with three picks per
// window, each hashed on its own salt so they land on different people.
// Outside the hold this is exactly the single 20-tick pick it always was.
function crowdFlashPicks(crowd, frame, reaction) {
  if (reaction <= 0.7 || !crowd.people?.length) return [];
  // v5.3 CROWD DEPTH: a flashbulb comes off a PAINTING that is holding a
  // phone, not off a posture that happens to be named "filming". The two
  // streams were independent (crowd.mjs deals the painting on its own seeded
  // stream), so before 5.3 a 14%-of-people posture flag lit up a painted
  // character carrying a beer, a plate or a lollipop. The manifest now
  // classifies every character's prop, and only `phone: true` can pop.
  if (crowdFlashCacheCrowd !== crowd || crowdFlashCacheManifest !== crowdSheets.manifest) {
    crowdFlashCacheCrowd = crowd;
    crowdFlashCacheManifest = crowdSheets.manifest;
    const entry = crowdVariantEntry(crowd.variant);
    const phones = [];
    crowd.people.forEach((person, index) => {
      if (entry?.characters?.[person.sprite?.character]?.phone) phones.push(index);
    });
    crowdFlashCandidates = phones;
  }
  if (!crowdFlashCandidates.length) return [];
  const reduced = state.accessibility.reducedMotion;
  const hold = !reduced && crowdKoHoldAge() >= 0;
  const windowTicks = reduced ? 60 : hold ? CROWD_KO_HOLD.flashWindowTicks : 20; // 20 ticks @60Hz → ≤3 pops per second
  const litTicks = hold ? CROWD_KO_HOLD.flashLitTicks : 8;
  const windowIndex = Math.floor(frame / windowTicks);
  const inWindow = frame - windowIndex * windowTicks;
  if (!reduced && inWindow >= litTicks) return [];
  const count = hold ? Math.min(CROWD_KO_HOLD.flashPicks, crowdFlashCandidates.length) : 1;
  const picks = [];
  for (let salt = 0; salt < count; salt += 1) {
    const pick = crowdFlashCandidates[
      Math.floor(presentationHash01(windowIndex, crowdFlashCandidates.length + salt * 7919) * crowdFlashCandidates.length)
      % crowdFlashCandidates.length
    ];
    if (picks.some((entry) => entry.index === pick)) continue;
    picks.push({ index: pick, fade: reduced ? 1 : 1 - inWindow / litTicks, reduced });
  }
  return picks;
}

function drawCrowdFlash(spot, pick) {
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  const bloom = glowSprite(255, 255, 255);
  ctx.globalAlpha = pick.reduced ? 0.24 : 0.75 * pick.fade;
  ctx.drawImage(bloom, spot.x - spot.size * 2.2, spot.y - spot.size * 2.2, spot.size * 4.4, spot.size * 4.4);
  if (!pick.reduced) {
    // Tiny white starburst over the phone.
    ctx.strokeStyle = `rgba(255,255,255,${(0.85 * pick.fade).toFixed(3)})`;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1], [0.7, 0.7], [-0.7, -0.7]]) {
      ctx.moveTo(spot.x, spot.y);
      ctx.lineTo(spot.x + dx * spot.size, spot.y + dy * spot.size);
    }
    ctx.stroke();
  }
  ctx.restore();
  presentationDebug.crowdFlashes += 1;
}

// Round-win light beat: one stage-signature moment when a round is won.
// Latched purely from the render path (draw never runs during rollback
// resimulation), timed from the simulation tick.
const ROUND_WIN_BEAT_TICKS = 84;
let roundWinBeatStartTick = -1;

function updateRoundWinBeatLatch() {
  if (state.phase === "roundover" && !state.finisher) {
    if (roundWinBeatStartTick < 0) roundWinBeatStartTick = state.simulationTick;
  } else if (state.phase !== "roundover" && roundWinBeatStartTick >= 0) {
    roundWinBeatStartTick = -1;
  }
}

function roundWinBeatLevel(frame) {
  if (roundWinBeatStartTick < 0) return 0;
  const t = (frame - roundWinBeatStartTick) / ROUND_WIN_BEAT_TICKS;
  return t >= 1 || t < 0 ? 0 : 1 - t;
}

// v5.1 KO MOMENT: the crowd's KO hold, latched on the same render-side
// pattern from the roundover phase edge (a fatality round latches on the kill
// itself, observed through finisher.slowMotionHits like the bed swell, so the
// crowd stays hushed through the pre-kill cinematic). While latched the crowd
// draw, the CINEMA 3D billboards, the scuffles, the cups, the flashbulbs and
// the crowd bed all read crowdDrawReaction() — the hold curve from
// engine/crowd-voice.mjs — instead of the decaying sim value. Measured before
// this on 20 seeds: a heavy-hit KO put 6-10% of the painted people on the
// cheer cell for 2.5 ticks of the 294-tick hold. Never sim state, never
// resimulated; the latch is idempotent so every consumer may poke it.
// v5.3 (sweep #52): the latch, the age and the hold-vs-stir read are
// engine/crowd-reaction.mjs. This side supplies the two facts only game.js
// has — the live phase and the simulation tick.
const crowdKoHold = createCrowdKoHold();

function updateCrowdKoHoldLatch() {
  latchCrowdKoHold(crowdKoHold, crowdKoHoldLive(state), state.simulationTick);
}

function crowdKoHoldAge() {
  return koHoldAge(crowdKoHold, state.simulationTick);
}

function crowdDrawReaction() {
  return crowdHoldReaction(state.crowdReaction, crowdKoHoldAge());
}

const ROUND_WIN_BEATS = Object.freeze({
  wildwood: { glows: [{ x: 668, y: 96, rx: 170, ry: 120, color: [255, 150, 216] }], firework: true },
  somerset: { glows: [{ x: 640, y: 184, rx: 300, ry: 80, color: [255, 211, 105] }] },
  vet: {
    glows: [
      { x: 148, y: 186, rx: 130, ry: 110, color: [214, 232, 255] },
      { x: 1200, y: 312, rx: 120, ry: 100, color: [214, 232, 255] },
    ],
  },
  buffet: { glows: [{ x: 640, y: 250, rx: 340, ry: 90, color: [255, 196, 118] }] },
  cruise: { glows: [{ x: 640, y: 396, rx: 330, ry: 70, color: [140, 232, 255] }] },
  janney: { glows: [{ x: 887, y: 150, rx: 130, ry: 110, color: [255, 186, 96] }] },
});

function drawRoundWinBeat(frame, centre) {
  const level = roundWinBeatLevel(frame);
  if (level <= 0.01) return;
  const beat = ROUND_WIN_BEATS[state.stage];
  if (!beat) return;
  const reduced = state.accessibility.reducedMotion;
  const backdropShift = (centre - W * 0.5) * -0.035;
  const ease = level * level;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  for (const glow of beat.glows) {
    ctx.globalAlpha = 0.5 * ease;
    ctx.drawImage(
      glowSprite(glow.color[0], glow.color[1], glow.color[2]),
      glow.x + backdropShift - glow.rx, glow.y - glow.ry, glow.rx * 2, glow.ry * 2,
    );
  }
  if (beat.firework && !reduced) {
    // A single firework bursting over the WILDWOOD sign.
    const burst = 1 - level;
    const x = 668 + backdropShift;
    const y = 88;
    ctx.globalAlpha = 0.9 * ease;
    ctx.lineWidth = 2;
    for (let spark = 0; spark < 12; spark += 1) {
      const angle = (spark / 12) * Math.PI * 2 + 0.26;
      const radius = 14 + burst * 86;
      const droop = burst * burst * 26;
      const gold = spark % 2 === 0;
      ctx.strokeStyle = gold ? "rgba(255,214,130,0.9)" : "rgba(255,150,216,0.9)";
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(angle) * radius * 0.62, y + Math.sin(angle) * radius * 0.62 + droop * 0.5);
      ctx.lineTo(x + Math.cos(angle) * radius, y + Math.sin(angle) * radius + droop);
      ctx.stroke();
    }
    ctx.globalAlpha = 0.8 * ease;
    ctx.drawImage(glowSprite(255, 224, 170), x - 34, y - 34, 68, 68);
  }
  ctx.restore();
  ctx.globalAlpha = 1;
}
const rollbackFighterReferences = new Set(["def", "kit", "movement", "combo", "directionTapTracker", "inputBuffer", "projectileSpawnFrames"]);
const rollbackPresentationFighterFields = new Set([
  // v3.5: "strideTime" joins "walkTime" here — same class of field (a seeded
  // presentation clock that drives which drawing shows, never what the sim
  // resolves), so it is snapshotted and restored with everything else but
  // stays out of the combat checksum exactly as walkTime always has.
  "animTime", "walkTime", "strideTime", "hitFlash", "specialGlow", "cinematicFrame", "cinematicRotation", "cinematicScale", "lastHitResult",
  // v5.1: the last contact's level, same class of field as lastHitResult.
  "lastHitLevel",
]);

function cloneRollbackValue(value) {
  return structuredClone(value);
}

function saveRollbackFighter(fighter) {
  const values = {};
  for (const [key, value] of Object.entries(fighter)) {
    if (!rollbackFighterReferences.has(key)) values[key] = cloneRollbackValue(value);
  }
  return {
    id: fighter.def.id,
    values,
    combo: {
      hits: fighter.combo.hits,
      totalDamage: fighter.combo.totalDamage,
      active: fighter.combo.active,
      startedFrame: fighter.combo.startedFrame,
      lastHitFrame: fighter.combo.lastHitFrame,
      displayUntilFrame: fighter.combo.displayUntilFrame,
      graceUntilFrame: fighter.combo.graceUntilFrame,
      peakHits: fighter.combo.peakHits,
    },
    directionTaps: fighter.directionTapTracker.snapshot(),
    inputBuffer: fighter.inputBuffer.snapshot(),
    projectileSpawnFrames: [...fighter.projectileSpawnFrames],
  };
}

function restoreRollbackFighter(fighter, snapshot) {
  Object.assign(fighter, cloneRollbackValue(snapshot.values));
  Object.assign(fighter.combo, snapshot.combo);
  fighter.directionTapTracker.restore(snapshot.directionTaps);
  fighter.inputBuffer.restore(snapshot.inputBuffer);
  fighter.projectileSpawnFrames = new Set(snapshot.projectileSpawnFrames || []);
}

function saveRollbackState() {
  const finisher = state.finisher ? (() => {
    const { script: _script, ...values } = state.finisher;
    return { ...cloneRollbackValue(values), scriptId: state.fighters[state.finisher.winner]?.def.finisherScriptId || state.fighters[state.finisher.winner]?.def.id };
  })() : null;
  return {
    version: 1,
    simulationTick: state.simulationTick,
    picks: [...state.picks],
    stage: state.stage,
    rounds: [...state.rounds],
    round: state.round,
    timer: state.timer,
    timerCarry: state.timerCarry,
    phase: state.phase,
    phaseTime: state.phaseTime,
    finishWinner: state.finishWinner,
    finisherType: state.finisherType,
    finisher,
    facingAxis: state.facingAxis,
    cinematicZoom: state.cinematicZoom,
    shake: state.shake,
    flash: state.flash,
    hitstop: state.hitstop,
    matchSeed: state.matchSeed,
    lastImpactSide: state.lastImpactSide,
    // Release 1.8 GRIND: House Rules config + the Sudden Death one-shot are
    // sim inputs, so they live in the snapshot (matchRules is derived from
    // mutators on restore rather than stored — single source of truth).
    mutators: [...state.mutators],
    suddenDeathHitDone: state.suddenDeathHitDone,
    rng: state.rng.getState(),
    visualRng: state.visualRng.getState(),
    fighters: state.fighters.map(saveRollbackFighter),
    traps: cloneRollbackValue(state.traps),
    projectiles: cloneRollbackValue(state.projectiles),
    particles: cloneRollbackValue(state.particles),
    effects: cloneRollbackValue(state.effects),
    commands: commandHistory.map((history) => cloneRollbackValue(history)),
    stageWeapon: cloneRollbackValue(state.stageWeapon),
  };
}

function restoreRollbackState(snapshot) {
  if (!snapshot || snapshot.version !== 1 || snapshot.fighters?.length !== 2) throw new Error("Unsupported Final Blow rollback state.");
  state.simulationTick = snapshot.simulationTick;
  state.picks = [...snapshot.picks];
  state.stage = snapshot.stage;
  state.rounds = [...snapshot.rounds];
  state.round = snapshot.round;
  state.timer = snapshot.timer;
  state.timerCarry = snapshot.timerCarry;
  state.phase = snapshot.phase;
  state.phaseTime = snapshot.phaseTime;
  state.finishWinner = snapshot.finishWinner;
  state.finisherType = snapshot.finisherType;
  // Older peers predate the pair axis; fall back to side 0's stored facing so a
  // mixed-build resimulation still restores a coherent orientation.
  state.facingAxis = snapshot.facingAxis ?? snapshot.fighters[0]?.values?.facing ?? 1;
  state.cinematicZoom = snapshot.cinematicZoom;
  state.shake = snapshot.shake;
  state.flash = snapshot.flash;
  state.hitstop = snapshot.hitstop;
  state.matchSeed = snapshot.matchSeed;
  state.lastImpactSide = snapshot.lastImpactSide;
  // Mutator config restores BEFORE the fighters: makeFighter derives movement
  // from state.matchRules, so a mid-restore rebuild must see the right rules.
  state.mutators = [...(snapshot.mutators || [])];
  state.matchRules = resolveMatchRules(state.mutators);
  state.suddenDeathHitDone = Boolean(snapshot.suddenDeathHitDone);
  state.rng.setState(snapshot.rng);
  state.visualRng.setState(snapshot.visualRng);
  for (let side = 0; side < 2; side += 1) {
    if (state.fighters[side]?.def.id !== snapshot.fighters[side].id) {
      const index = roster.findIndex(({ id }) => id === snapshot.fighters[side].id);
      state.fighters[side] = makeFighter(index, side);
    }
    restoreRollbackFighter(state.fighters[side], snapshot.fighters[side]);
  }
  state.traps = cloneRollbackValue(snapshot.traps || []);
  state.projectiles = cloneRollbackValue(snapshot.projectiles || []);
  state.particles = cloneRollbackValue(snapshot.particles || []);
  state.effects = cloneRollbackValue(snapshot.effects || []);
  commandHistory[0] = cloneRollbackValue(snapshot.commands?.[0] || []);
  commandHistory[1] = cloneRollbackValue(snapshot.commands?.[1] || []);
  state.stageWeapon = cloneRollbackValue(snapshot.stageWeapon ?? null);
  state.finisher = snapshot.finisher ? {
    ...cloneRollbackValue(snapshot.finisher),
    script: projectileFinisherScript(snapshot.finisher.scriptId, snapshot.finisher.type),
  } : null;
  if (state.finisher) delete state.finisher.scriptId;
}

function combatRollbackState() {
  const snapshot = saveRollbackState();
  delete snapshot.visualRng;
  delete snapshot.particles;
  delete snapshot.effects;
  delete snapshot.shake;
  delete snapshot.flash;
  delete snapshot.cinematicZoom;
  if (snapshot.finisher) {
    for (const field of ["cinematicShot", "cinematicCuts", "impactCloseUps", "peakZoom", "slowMotionHits"]) {
      delete snapshot.finisher[field];
    }
  }
  for (const fighter of snapshot.fighters) {
    for (const field of rollbackPresentationFighterFields) delete fighter.values[field];
  }
  return snapshot;
}

function syncRollbackPresentation() {
  updateHud();
  updateComboState();
  updateOnlineHud();
  $("#touchControls").classList.toggle("cinematic", Boolean(state.finisher));
  setTouchPrompt(state.phase === "finish" && state.finishWinner === onlineLocalSide() ? "final" : "");
}

function createOnlineRollback(config, initialFrame = 0) {
  return new RollbackSession({
    localSide: onlineLocalSide(),
    matchTag: matchTagFromId(config.matchId),
    inputDelay: config.inputDelay,
    initialFrame,
    saveState: saveRollbackState,
    loadState: restoreRollbackState,
    checksum: () => checksumState(combatRollbackState()),
    step(inputs, frame, { resimulating }) {
      const previous = rollbackResimulating;
      rollbackResimulating = resimulating;
      try {
        state.simulationTick = frame + 1;
        // R2.1 STREETS: replay recorder — keyed by frame in an independent
        // append store (the session prunes its own maps after ~180 frames)
        // and OVERWRITTEN on resimulation, so only confirmed values survive.
        if (replayRecorder.active && replayRecorder.kind === "online" && replayRecorder.onlineFrames) {
          replayRecorder.onlineFrames.set(frame, [Number(inputs[0]) & 0xffff, Number(inputs[1]) & 0xffff]);
        }
        simulatePreparedGameTick(SIMULATION_STEP_SECONDS, bitsToInput(inputs[0]), bitsToInput(inputs[1]));
      } finally {
        rollbackResimulating = previous;
      }
    },
    onRollback() {
      syncRollbackPresentation();
    },
    onWindowExceeded() {
      updateOnlineHud("error");
      if (onlineSession.role === "host") sendAuthoritativeOnlineState("rollback-window");
      else sendOnlineControl({ type: "desync-warning", matchId: config.matchId, frame: onlineSession.rollback?.frame || 0 });
    },
  });
}

function setupRoster() {
  const grid = $("#rosterGrid");
  grid.innerHTML = "";
  // Wave 17: ten cards need five columns; the classic 4x2 stays for any
  // hypothetical eight-fighter roster so the layout rule is data-driven.
  grid.classList.toggle("wide", roster.length > 8);
  roster.forEach((fighter, index) => {
    const card = document.createElement("button");
    // Wave 16: the unlocked Commissioner is the dark-red ninth card.
    card.className = fighter.secret ? "fighter-card secret-card" : "fighter-card";
    card.dataset.index = index;
    card.dataset.mark = fighter.mark;
    card.style.setProperty("--fighter", fighter.color);
    card.innerHTML = `
      <span class="pick-badge p1">P1</span><span class="pick-badge p2">P2</span>
      <span class="mastery-badge" data-tier="none" hidden></span>
      <img class="fighter-portrait" src="assets/fighters/${fighter.id}.webp" alt="" aria-hidden="true" draggable="false">
      <span class="fighter-info"><strong>${fighter.name}</strong><small>${fighter.title}</small></span>`;
    card.addEventListener("click", () => chooseFighter(index));
    grid.append(card);
  });
  // v2.1 PROGRESSION: mastery chips on the fresh cards.
  refreshMasteryBadges();
  // R1.9: combo-trial medal readout per fighter card.
  refreshTrialMedalBadges();
  updateRosterUI();
}

// R1.9: the move list is a live frame-data reference now. Rows come from
// listFighterFrameData — real attack instances, post-ARCADE_TUNING — so the
// dialog can never drift from the sim. Level chips give LOW/OH/MID/THROW at a
// glance (text + color, never hue alone).
const MOVE_LEVEL_TAGS = Object.freeze({
  mid: "MID", low: "LOW", overhead: "OH", throw: "THROW", air: "AIR",
});

// 5.1 (sweep #29): the command column is rendered for the ACTIVE control
// style. Normals keep the frame-data row's own command; specials/EX/super go
// through commandLabel so MODERN reads LP&LK and LEGEND reads HP where CLASSIC
// reads ↓ → + PUNCH. A kit's authored note after " · " (Allan's "counters
// strikes") survives the substitution.
const MOVE_LIST_NORMAL_ACTIONS = new Set(["light", "heavy", "throw"]);

function moveListCommand(row, style = state.controlStyle) {
  if (MOVE_LIST_NORMAL_ACTIONS.has(row.action)) return row.command;
  const [, ...notes] = String(row.command || "").split(" · ");
  const label = commandLabel(row.action, style, row.command);
  return notes.length ? `${label} · ${notes.join(" · ")}` : label;
}

function moveListMarkup(fighterId, style = state.controlStyle) {
  const signed = (value) => `${value >= 0 ? "+" : ""}${value}`;
  const rows = listFighterFrameData(fighterId).map((row) => `
    <div class="move-list-row frame-row">
      <b>${row.name}</b>
      <span>${moveListCommand(row, style)}</span>
      <span class="sar">${row.startup} / ${row.active} / ${row.recovery}</span>
      <span class="sar">${row.level === "throw" ? "—" : `${signed(row.onHit)} / ${signed(row.onBlock)}`}</span>
      <span class="sar">${row.damage}</span>
      <em class="level-chip lvl-${row.level}">${MOVE_LEVEL_TAGS[row.level] || row.level.toUpperCase()}</em>
    </div>`);
  return `
    <div class="move-list-row frame-head">
      <b>MOVE</b><span>COMMAND</span><span>S / A / R</span><span>HIT / BLOCK</span><span>DMG</span><span>LVL</span>
    </div>` + rows.join("");
}

function renderMoveList(fighterId = "deathblow") {
  const kit = getFighterKit(fighterId);
  if (!kit) return;
  $("#moveListIdentity").innerHTML = `<strong>${kit.archetype}</strong> · ${kit.summary}`;
  $("#moveListRows").className = "move-list-rows frame-data";
  $("#moveListRows").innerHTML = moveListMarkup(fighterId);
}

// The dialog's fighter <select> is built from the live roster (the unlocked
// Commissioner included) instead of a static eight-option list that had no
// Pinelands Devil entry.
function buildMoveListSelect() {
  const select = $("#moveListSelect");
  if (!select) return;
  const current = select.value;
  select.innerHTML = roster.map((fighter) => `<option value="${fighter.id}">${fighter.name}</option>`).join("");
  select.value = roster.some(({ id }) => id === current) ? current : roster[0].id;
}

// 5.1 (sweep #29): MOVE LIST from the pause menu — a compact overlay for the
// fighter P1 is actually holding, no scrolling past the remap grid. Opened
// from #pauseMoveListButton, closed by its own button, Escape or the pad's
// back; the pause panel stays underneath so RESUME is one press away.
const moveListOverlay = { open: false, fighterId: "" };

function openMoveListOverlay(fighterId = state.fighters[0]?.kitId || roster[state.picks[0]]?.id || "deathblow") {
  const overlay = $("#moveListOverlay");
  if (!overlay || state.screen !== "fight") return false;
  const def = roster.find(({ id }) => id === fighterId) || (fighterId === ARCADE_BOSS_ID ? arcadeBoss : null);
  const kit = getFighterKit(fighterId);
  if (!kit) return false;
  moveListOverlay.open = true;
  moveListOverlay.fighterId = fighterId;
  $("#moveListOverlayName").textContent = def?.name || fighterId.toUpperCase();
  $("#moveListOverlayStyle").textContent = `${state.controlStyle.toUpperCase()} CONTROLS`;
  $("#moveListOverlayIdentity").innerHTML = `<strong>${kit.archetype}</strong> · ${kit.summary}`;
  $("#moveListOverlayRows").innerHTML = moveListMarkup(fighterId);
  $("#moveListOverlayExtras").innerHTML = [
    ["THROWABLE", commandLabel("throwObject", state.controlStyle)],
    ["STAGE WEAPON", commandLabel("stageWeapon", state.controlStyle)],
    ["DASH", commandLabel("dash", state.controlStyle)],
    ["TAUNT", commandLabel("taunt", state.controlStyle)],
    ["PERFECT GUARD", commandLabel("perfectGuard", state.controlStyle)],
    ["GUARD REVERSAL", commandLabel("guardReversal", state.controlStyle)],
  ].map(([name, command]) => `<span><b>${name}</b>${command}</span>`).join("");
  overlay.hidden = false;
  $("#moveListOverlayClose")?.focus?.({ preventScroll: true });
  return true;
}

function closeMoveListOverlay() {
  const overlay = $("#moveListOverlay");
  if (!overlay || !moveListOverlay.open) return false;
  moveListOverlay.open = false;
  overlay.hidden = true;
  $("#pauseMoveListButton")?.focus?.({ preventScroll: true });
  return true;
}

function arcadeOpponentDef(match = currentArcadeMatch(state.arcadeRun)) {
  if (!match) return null;
  return match.opponentId === ARCADE_BOSS_ID
    ? arcadeBoss
    : roster.find(({ id }) => id === match.opponentId) || null;
}

function renderArcadeRoute() {
  const run = state.arcadeRun;
  const containers = [$("#arcadeRoutePreview"), $("#arcadeLadderNodes")].filter(Boolean);
  for (const container of containers) {
    container.hidden = state.mode !== "arcade" || !run;
    if (!run) {
      container.innerHTML = "";
      continue;
    }
    container.innerHTML = run.matches.map((match, index) => {
      const def = arcadeOpponentDef(match);
      const stateClass = index < run.current ? "cleared" : index === run.current ? "current" : "locked";
      return `<div class="ladder-node ${stateClass} ${match.kind}" title="${match.label} · ${def.name}">
        <span>${index < run.current ? "✓" : index + 1}</span>
        <img src="assets/fighters/${def.id}.webp" alt="" draggable="false">
        <b>${match.kind === "boss" ? "BOSS" : match.kind === "rival" ? "RIVAL" : def.name}</b>
      </div>`;
    }).join("");
  }
  if ($("#arcadeLadderCounter") && run) {
    $("#arcadeLadderCounter").textContent = run.completed
      ? `${run.wins} / ${run.matches.length} CLEARED`
      : `BOUT ${run.current + 1} / ${run.matches.length}`;
  }
}

function prepareArcadeOpponent(usePlannedStage = false) {
  const match = currentArcadeMatch(state.arcadeRun);
  const def = arcadeOpponentDef(match);
  if (!match || !def) return null;
  const opponentIndex = roster.findIndex(({ id }) => id === match.opponentId);
  state.picks[1] = opponentIndex >= 0 ? opponentIndex : 0;
  if (usePlannedStage) state.stage = match.stage;
  renderArcadeRoute();
  updateStageUI();
  return def;
}

function makeMatchFighters() {
  const match = state.mode === "arcade" ? currentArcadeMatch(state.arcadeRun) : null;
  const bossOverride = match?.opponentId === ARCADE_BOSS_ID ? arcadeBoss : null;
  // Wave 16: resolve the per-side palettes for this build. Online reads the
  // shared match config (both peers derive the identical pair); offline reads
  // the select-screen picks. Deterministic on every rebuild — rollback resim
  // included — so the mirror auto-alt can never flicker.
  const defs = [
    roster[state.picks[0]] || null,
    bossOverride || roster[state.picks[1]] || null,
  ];
  applyMatchPalettes(defs, state.mode === "online"
    ? onlineSession.matchConfig?.palettes || [0, 0]
    : pendingPalettes);
  // Fresh fighters always spawn side 0 left of side 1, so every path that
  // rebuilds the pair — new match, rematch, round reset, online seed — resets
  // the axis with them rather than inheriting a crossed-over orientation.
  state.facingAxis = 1;
  return [makeFighter(state.picks[0], 0), makeFighter(state.picks[1], 1, bossOverride)];
}

// ===========================================================================
// Release 1.8 GRIND — mode flows: The Gauntlet (survival), Block War (3v3),
// The Daily Jawn, House Rules mutators, and the SF2 tally / initials /
// high-score loop. Sim-affecting values all flow through state.mutators →
// state.matchRules (snapshotted config); everything else here is meta/UI.
// ===========================================================================

const FIGHTER_HOME_X = [355, 925];

function rosterIndexById(id) {
  return roster.findIndex((fighter) => fighter.id === id);
}

function roundsToWinValue() {
  if (state.mode === "survival" || state.mode === "team") return 1;
  return state.matchRules.roundsToWin || 2;
}

// The mutator set the NEXT match should run under. Online reads the shared
// match config (plain rooms never set it — mutators stay gated out of online);
// the daily forces its single seeded rule; versus and Block War read the
// stage-select picker; every other mode is clean.
function activeMutatorsForMatch() {
  if (state.mode === "online") return state.mutators;
  if (dailySession.active && state.mode === "arcade") return dailySession.plan?.mutator ? [dailySession.plan.mutator] : [];
  // Wave 19: THE PHILLY OPEN runs clean tournament rules — no House Rules.
  if (bracketSession.playing) return [];
  if (state.mode === "versus" || state.mode === "team") return pendingMutators;
  return [];
}

function applyMatchRulesForMatch() {
  state.mutators = normalizeMutators(activeMutatorsForMatch());
  state.matchRules = resolveMatchRules(state.mutators);
  state.suddenDeathHitDone = false;
}

// Block War: incoming teammates start at the near arena edge and walk to
// their slot during the intro. Fixed-dt math on snapshotted fields only.
function updateIntroWalkIns(dt) {
  for (const fighter of state.fighters) {
    if (!Number.isFinite(fighter.introWalkTarget)) continue;
    const speed = Math.max(220, Number(fighter.movement.forwardWalkSpeed) || 0);
    const delta = fighter.introWalkTarget - fighter.x;
    const step = Math.sign(delta) * speed * dt;
    if (Math.abs(delta) <= Math.abs(step) + 1) {
      fighter.x = fighter.introWalkTarget;
      fighter.introWalkTarget = null;
    } else {
      fighter.x += step;
      fighter.walkTime += dt * 2;
      // The walk-on marches toward the fighter's own slot, i.e. forwards.
      fighter.strideTime += dt * 2;
    }
  }
}

// Mode-specific fighter setup, applied right after makeMatchFighters() in
// startMatch. Health carry-in, regen results and AI tuning are all sim inputs
// derived from the run/battle config (never ad-hoc mid-round writes).
function applyModeFighterSetup() {
  if (state.mode === "survival" && state.survivalRun) {
    const bout = currentSurvivalBout(state.survivalRun);
    if (bout) {
      state.fighters[0].health = clamp(bout.carryHealth, 1, 100);
      state.fighters[1].aiBrain = createAiBrain(bout.difficultyId);
    }
  } else if (state.mode === "team" && state.teamBattle) {
    const battle = state.teamBattle;
    for (const side of [0, 1]) {
      state.fighters[side].health = clamp(battle.carryHealth[side], 1, 100);
      state.fighters[side].meter = clamp(battle.carryMeter[side], 0, GRIT_RULES.maximum);
    }
    const incomingSide = battle.lastElimination && !battle.lastElimination.over
      ? battle.lastElimination.loserSide : -1;
    if (incomingSide === 0 || incomingSide === 1) {
      const fighter = state.fighters[incomingSide];
      fighter.introWalkTarget = FIGHTER_HOME_X[incomingSide];
      fighter.x = incomingSide === 0 ? MOVEMENT_RULES.stageMinX : MOVEMENT_RULES.stageMaxX;
    }
    if (battle.cpu) state.fighters[1].aiBrain = createAiBrain(state.aiDifficulty);
  } else if (dailySession.active && state.mode === "arcade") {
    // The Daily Jawn is identical everywhere: CPU difficulty is pinned to the
    // plan's fixed tier regardless of the local difficulty setting.
    state.fighters[1].aiBrain = createAiBrain(dailySession.plan?.difficulty || DAILY_RULES.difficulty);
  }
  if (state.matchRules.infiniteGrit) {
    for (const fighter of state.fighters) fighter.meter = GRIT_RULES.maximum;
  }
}

// --- Survival: The Gauntlet ------------------------------------------------

function startSurvivalRun(fighterId, seed = null) {
  state.mode = "survival";
  state.arcadeRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  const runSeed = Number.isFinite(seed) ? Number(seed) >>> 0 : state.rng.nextUint32();
  state.survivalRun = createSurvivalRun({
    playerId: fighterId,
    fighterIds: roster.map(({ id }) => id),
    stageIds: Object.keys(stages),
    seed: runSeed,
  });
  beginScoreRun("survival", `survival-${fighterId}`, currentSurvivalBout(state.survivalRun).multiplier);
  prepareSurvivalBout();
  startMatch(true);
  return state.survivalRun;
}

function prepareSurvivalBout() {
  const run = state.survivalRun;
  const bout = currentSurvivalBout(run);
  if (!run || !bout) return null;
  registerAiDifficulty(bout.difficultyId, bout.difficultySettings);
  state.picks[0] = Math.max(0, rosterIndexById(run.playerId));
  state.picks[1] = Math.max(0, rosterIndexById(bout.opponentId));
  state.locks = [true, true];
  state.stage = bout.stage;
  scoreSession.multiplier = bout.multiplier;
  return bout;
}

function survivalBestSummary() {
  return loadSurvivalBest();
}

function resolveSurvivalResult(winner) {
  const run = state.survivalRun;
  if (!run) {
    showResult(winner);
    return;
  }
  if (winner === 0) {
    const tallyContext = finalizeBoutTally();
    const outcome = recordSurvivalWin(run, state.fighters[0].health);
    const best = loadSurvivalBest();
    if (outcome.wins > best.streak) saveSurvivalBest({ ...best, streak: outcome.wins });
    // v2.1 PROGRESSION: each Gauntlet bout is a single-round match; the live
    // streak feeds the ledger on every win (best-of stays monotonic).
    progressionMatchEnd(0);
    progressionRunEnd("survival", { wins: outcome.wins });
    const proceed = () => {
      prepareSurvivalBout();
      startMatch(true);
    };
    const announceMilestone = () => {
      if (!outcome.milestone) return;
      modeFxDebug.survivalMilestones += 1;
      announce(`${outcome.wins} STRAIGHT`, outcome.milestoneLine, 1.9);
      announcerSay("perfect", { delay: 350 });
    };
    if (tallyContext) {
      showBoutTally(tallyContext, proceed, {
        title: `BOUT ${outcome.wins} CLEARED`,
        sub: `${outcome.wins} WIN STREAK · NEXT: ${arcadeOpponentDef({ opponentId: outcome.next.opponentId })?.name || outcome.next.opponentId.toUpperCase()}`,
        onShown: announceMilestone,
      });
    } else {
      announceMilestone();
      proceed();
    }
    return;
  }
  // Defeat: the run is over. Points earned during the losing bout still count
  // (banked without a tally screen), then initials if the total charts.
  recordSurvivalDefeat(run);
  finalizeBoutTally();
  const best = loadSurvivalBest();
  saveSurvivalBest({
    streak: Math.max(best.streak, run.wins),
    score: Math.max(best.score, scoreSession.total),
  });
  scoreSession.detail = `survival-${run.wins}`;
  // v2.1 PROGRESSION: the losing bout still counts; the run's final streak
  // is observed one last time.
  progressionMatchEnd(winner);
  progressionRunEnd("survival", { wins: run.wins });
  maybeEnterInitials(() => showResult(winner));
}

// --- Team battle: Block War ------------------------------------------------

function prepareTeamPairing() {
  const battle = state.teamBattle;
  const pair = currentTeamPair(battle);
  if (!pair) return null;
  state.picks[0] = Math.max(0, rosterIndexById(pair[0]));
  state.picks[1] = Math.max(0, rosterIndexById(pair[1]));
  state.locks = [true, true];
  return pair;
}

function beginTeamBattle(cpuOpponent = false) {
  state.teamBattle = createTeamBattle(state.teamPicks[0], state.teamPicks[1]);
  state.teamBattle.cpu = Boolean(cpuOpponent);
  prepareTeamPairing();
  return state.teamBattle;
}

function resolveTeamResult(winner) {
  const battle = state.teamBattle;
  if (!battle) {
    showResult(winner);
    return;
  }
  const winnerFighter = state.fighters[winner];
  const outcome = recordTeamKo(battle, winner, winnerFighter?.health || 0, winnerFighter?.meter || 0);
  // v2.1 PROGRESSION: every Block War pairing folds as a single-round match
  // for the active P1 fighter; a finished war observes the sweep entry.
  progressionMatchEnd(winner);
  if (outcome?.over) {
    progressionRunEnd("team", {
      won: winner === 0,
      sweep: winner === 0 && battle.eliminated[0].length === 0,
    });
  }
  if (!outcome || outcome.over) {
    showResult(winner);
    return;
  }
  modeFxDebug.teamWalkIns += 1;
  prepareTeamPairing();
  startMatch(true);
}

// --- Daily challenge: The Daily Jawn ---------------------------------------

function startDailyRun(dateOverride = null, { force = false } = {}) {
  // The date string is computed ONCE here, render-side; the whole run derives
  // from it (seed, fighter, opponents, stages, mutator) — never from a clock.
  const date = dateOverride || dailyDateString();
  const record = loadDailyRecord();
  if (!force && !dateOverride && record?.date === date && record.played) {
    updateDailyBanners();
    refreshDailyUi();
    sound("select");
    return false;
  }
  const plan = createDailyPlan(date, baseRosterIds());
  dailySession.active = true;
  dailySession.date = date;
  dailySession.plan = plan;
  dailySession.finished = false;
  dailySession.outcome = null;
  modeFxDebug.dailyRuns += 1;
  endDemoSession();
  state.mode = "arcade";
  state.survivalRun = null;
  state.teamBattle = null;
  state.arcadeRun = plan.run;
  state.picks = [Math.max(0, rosterIndexById(plan.fighterId)), 0];
  state.locks = [true, true];
  beginScoreRun("daily", `daily-${date}`, scoreDifficultyMultiplier(plan.difficulty));
  prepareArcadeOpponent(true);
  enterImmersiveMode();
  unlockAudio();
  startMatch(true);
  return true;
}

function finishDailyRun(cleared) {
  if (!dailySession.active || dailySession.finished) return null;
  if (!cleared) finalizeBoutTally();
  const run = state.arcadeRun;
  const record = nextDailyRecord(loadDailyRecord(), {
    date: dailySession.date,
    score: scoreSession.total,
    wins: run?.wins || 0,
    bouts: run?.matches?.length || 8,
    cleared,
  });
  saveDailyRecord(record);
  dailySession.finished = true;
  dailySession.outcome = {
    cleared: Boolean(cleared),
    score: scoreSession.total,
    wins: run?.wins || 0,
    bouts: run?.matches?.length || 8,
    streak: record.streak,
  };
  scoreSession.detail = `daily-${dailySession.date}`;
  // v2.1 PROGRESSION: Daily Jawn clears + streaks feed the Black Book.
  progressionRunEnd("daily", { cleared: Boolean(cleared), streak: record.streak });
  updateDailyBanners();
  refreshDailyUi();
  return dailySession.outcome;
}

function dailyShareTextForOutcome() {
  const outcome = dailySession.outcome;
  if (!outcome) return "";
  return dailyShareText({
    date: dailySession.date,
    fighterName: roster.find(({ id }) => id === dailySession.plan?.fighterId)?.name || dailySession.plan?.fighterId,
    score: outcome.score,
    wins: outcome.wins,
    bouts: outcome.bouts,
    cleared: outcome.cleared,
    streak: outcome.streak,
    mutator: dailySession.plan?.mutator,
  });
}

async function shareDailyResult(button) {
  const text = dailyShareTextForOutcome();
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const scratch = document.createElement("textarea");
    scratch.value = text;
    document.body.append(scratch);
    scratch.select();
    document.execCommand("copy");
    scratch.remove();
  }
  if (button) {
    const label = button.dataset.label || button.textContent;
    button.dataset.label = label;
    button.textContent = "COPIED TO CLIPBOARD";
    setTimeout(() => { button.textContent = label; }, 1400);
  }
}

// Title-screen row state: fresh / completed + live streak readout.
function refreshDailyUi() {
  const status = $("#dailyStatus");
  if (!status) return;
  const today = dailyDateString();
  const record = loadDailyRecord();
  const playedToday = record?.date === today && record.played;
  const liveStreak = record && (record.date === today || record.lastClearedDate === previousDateString(today))
    ? record.streak : 0;
  if (playedToday) {
    status.textContent = `DONE · ${Math.round(record.score).toLocaleString("en-US")} PTS${liveStreak > 0 ? ` · STREAK ${liveStreak}` : ""}`;
    $("#dailyButton")?.classList.add("daily-done");
  } else {
    status.textContent = `${today} · FRESH JAWN${liveStreak > 0 ? ` · STREAK ${liveStreak}` : ""}`;
    $("#dailyButton")?.classList.remove("daily-done");
  }
}

function updateDailyBanners() {
  const visible = dailySession.finished && Boolean(dailySession.outcome);
  for (const id of ["#dailyResultBanner", "#dailyEndingBanner"]) {
    const banner = $(id);
    if (!banner) continue;
    banner.hidden = !visible;
    if (!visible) continue;
    const outcome = dailySession.outcome;
    banner.querySelector("b").textContent = `DAILY JAWN ${dailySession.date} · ${outcome.cleared ? "CLEARED" : `OUT AT ${outcome.wins}/${outcome.bouts}`}`;
    banner.querySelector("em").textContent = `${Math.round(outcome.score).toLocaleString("en-US")} PTS${outcome.streak > 0 ? ` · STREAK ${outcome.streak}` : ""}${dailySession.plan?.mutator ? ` · ${MUTATORS[dailySession.plan.mutator].name}` : ""}`;
  }
}

// --- SF2 tally screen ------------------------------------------------------

function showBoutTally(context, onContinue, { title = "BOUT CLEARED", sub = "", onShown = null } = {}) {
  tallyUi.active = true;
  tallyUi.rows = tallyRows(context.tally);
  tallyUi.total = context.boutTotal;
  tallyUi.runTotal = context.runTotal;
  tallyUi.multiplier = context.multiplier;
  tallyUi.done = false;
  tallyUi.onContinue = onContinue;
  tallyUi.startedAt = performance.now();
  tallyUi.lastTickedRow = -1;
  modeFxDebug.tallyScreens += 1;
  $("#tallyTitle").textContent = title;
  $("#tallySub").textContent = sub || `DIFFICULTY ×${context.multiplier}`;
  $("#tallyRows").innerHTML = tallyUi.rows.map((row) => `
    <div class="tally-row" data-row="${row.id}">
      <span>${row.label}</span>
      <small>${row.count > 0 ? `× ${row.count}` : "—"}</small>
      <b data-points="${row.points}">0</b>
    </div>`).join("");
  $("#tallyMultiplier").textContent = `DIFFICULTY MULTIPLIER ×${context.multiplier}`;
  $("#tallyBoutTotal").textContent = "0";
  $("#tallyRunTotal").textContent = Math.round(context.runTotal - context.boutTotal).toLocaleString("en-US");
  showScreen("tally");
  restartCssAnimation($("#tallyScreen").querySelector(".tally-panel"), "enter");
  if (onShown) onShown();
  requestAnimationFrame(stepTallyCountUp);
}

// Count-up: each row ticks up on a short stagger, then the multiplied bout
// total and run total land. A button press mid-count snaps to the final
// numbers; the next press continues. Reduced motion resolves instantly.
function stepTallyCountUp() {
  if (!tallyUi.active || state.screen !== "tally") return;
  const reduced = state.accessibility.reducedMotion;
  const elapsed = (performance.now() - tallyUi.startedAt) / 1000;
  const rowSlot = 0.16;
  const rowDuration = 0.42;
  const rowElements = $$("#tallyRows .tally-row");
  let allDone = true;
  rowElements.forEach((element, index) => {
    const points = Number(element.querySelector("b").dataset.points) || 0;
    const progress = reduced ? 1 : clamp((elapsed - index * rowSlot) / rowDuration, 0, 1);
    if (progress < 1) allDone = false;
    element.classList.toggle("counting", progress > 0 && progress < 1);
    element.classList.toggle("landed", progress >= 1);
    element.querySelector("b").textContent = Math.round(points * progress).toLocaleString("en-US");
    if (progress >= 1 && tallyUi.lastTickedRow < index) {
      tallyUi.lastTickedRow = index;
      if (points > 0 && !reduced) sound("select");
    }
  });
  const totalStart = reduced ? 0 : rowElements.length * rowSlot + rowDuration;
  const totalProgress = reduced ? 1 : clamp((elapsed - totalStart) / 0.5, 0, 1);
  $("#tallyBoutTotal").textContent = Math.round(tallyUi.total * totalProgress).toLocaleString("en-US");
  const runBase = tallyUi.runTotal - tallyUi.total;
  $("#tallyRunTotal").textContent = Math.round(runBase + tallyUi.total * totalProgress).toLocaleString("en-US");
  if (allDone && totalProgress >= 1) {
    if (!tallyUi.done) {
      tallyUi.done = true;
      modeFxDebug.tallyCountUps += 1;
      $("#tallyContinueButton").classList.add("ready");
    }
    return;
  }
  requestAnimationFrame(stepTallyCountUp);
}

function tallyContinue() {
  if (!tallyUi.active) return false;
  if (!tallyUi.done) {
    // First press: snap the count-up to its final numbers, resolved
    // synchronously so the CONTINUE button arms immediately (and scripted
    // probes can press straight through without waiting on a rAF).
    tallyUi.startedAt = -Infinity;
    stepTallyCountUp();
    return true;
  }
  tallyUi.active = false;
  $("#tallyContinueButton").classList.remove("ready");
  const proceed = tallyUi.onContinue;
  tallyUi.onContinue = null;
  sound("select");
  if (proceed) proceed();
  return true;
}

// --- Initials entry + high-score table -------------------------------------

function maybeEnterInitials(onDone) {
  const score = Math.round(scoreSession.total);
  if (!highScoreQualifies(loadHighScores(), score)) {
    onDone();
    return;
  }
  initialsUi.active = true;
  initialsUi.score = score;
  initialsUi.cursor = 0;
  initialsUi.letters = normalizeInitials(localStorage.getItem(SCORE_INITIALS_KEY) || "AAA").split("");
  initialsUi.onDone = onDone;
  modeFxDebug.initialsEntries += 1;
  $("#initialsScore").textContent = `${score.toLocaleString("en-US")} PTS`;
  $("#initialsMode").textContent = scoreSession.mode === "survival"
    ? "THE GAUNTLET" : scoreSession.mode === "daily" ? "DAILY JAWN" : "ARCADE";
  renderInitials();
  showScreen("initials");
}

function renderInitials() {
  $$("#initialsSlots .initials-slot").forEach((slot, index) => {
    slot.textContent = initialsUi.letters[index] || "A";
    slot.classList.toggle("cursor", initialsUi.active && index === initialsUi.cursor);
  });
}

const INITIALS_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

function cycleInitialLetter(direction) {
  const current = initialsUi.letters[initialsUi.cursor] || "A";
  const index = (INITIALS_ALPHABET.indexOf(current) + direction + INITIALS_ALPHABET.length) % INITIALS_ALPHABET.length;
  initialsUi.letters[initialsUi.cursor] = INITIALS_ALPHABET[index];
  renderInitials();
}

function commitInitials() {
  if (!initialsUi.active) return false;
  const initials = normalizeInitials(initialsUi.letters.join(""));
  try {
    localStorage.setItem(SCORE_INITIALS_KEY, initials);
  } catch { /* non-fatal */ }
  const { list, rank } = insertHighScore(loadHighScores(), {
    initials,
    score: initialsUi.score,
    mode: scoreSession.mode || "arcade",
    detail: scoreSession.detail,
    date: dailySession.finished ? dailySession.date : dailyDateString(),
  });
  saveHighScores(list);
  // v2.1 PROGRESSION: taking the top row inks NAME IN LIGHTS.
  progressionHighScore(rank);
  // Optional first-party leaderboard: offline-first, silent on any failure.
  submitScoreToWorker(initials, initialsUi.score, `${scoreSession.mode}:${scoreSession.detail}`);
  initialsUi.active = false;
  const done = initialsUi.onDone;
  initialsUi.onDone = null;
  sound("select");
  if (done) done();
  else showScreen("title");
  return true;
}

function handleInitialsKey(event) {
  if (state.screen !== "initials" || !initialsUi.active) return false;
  const { code } = event;
  if (/^Key[A-Z]$/.test(code)) {
    initialsUi.letters[initialsUi.cursor] = code.slice(3);
    initialsUi.cursor = Math.min(2, initialsUi.cursor + 1);
  } else if (/^Digit\d$/.test(code)) {
    initialsUi.letters[initialsUi.cursor] = code.slice(5);
    initialsUi.cursor = Math.min(2, initialsUi.cursor + 1);
  } else if (code === "ArrowLeft") initialsUi.cursor = Math.max(0, initialsUi.cursor - 1);
  else if (code === "ArrowRight") initialsUi.cursor = Math.min(2, initialsUi.cursor + 1);
  else if (code === "ArrowUp") cycleInitialLetter(1);
  else if (code === "ArrowDown") cycleInitialLetter(-1);
  else if (code === "Backspace") {
    initialsUi.letters[initialsUi.cursor] = "A";
    initialsUi.cursor = Math.max(0, initialsUi.cursor - 1);
  } else if (["Enter", "Space", "Escape"].includes(code)) {
    commitInitials();
    return true;
  } else return false;
  event.preventDefault();
  renderInitials();
  return true;
}

function handleTallyKey(event) {
  if (state.screen !== "tally" || !tallyUi.active) return false;
  if (!["Enter", "Space", "Escape", "KeyJ", "KeyK"].includes(event.code)) return false;
  event.preventDefault();
  tallyContinue();
  return true;
}

function renderHighScoreBoard(container) {
  const table = loadHighScores();
  const target = container || $("#attractScoresRows");
  if (!target) return table;
  target.innerHTML = table.length
    ? table.map((row, index) => `
      <div class="attract-score-row${index === 0 ? " top" : ""}">
        <span>${String(index + 1).padStart(2, "0")}</span>
        <b>${row.initials}</b>
        <em>${row.mode === "survival" ? "GAUNTLET" : row.mode === "daily" ? "DAILY" : "ARCADE"}</em>
        <strong>${Math.round(row.score).toLocaleString("en-US")}</strong>
      </div>`).join("")
    : `<div class="attract-score-row empty"><b>NO SCORES YET</b><strong>BE FIRST</strong></div>`;
  return table;
}

// --- Mutator picker (versus / Block War stage select) ----------------------

function renderMutatorBar() {
  const bar = $("#mutatorBar");
  if (!bar) return;
  const available = ["versus", "team"].includes(state.mode);
  bar.hidden = !available;
  if (!available) return;
  const options = $("#mutatorOptions");
  if (!options.childElementCount) {
    options.innerHTML = MUTATOR_ORDER.map((id) => `
      <button type="button" class="mutator-chip" data-mutator="${id}" title="${MUTATORS[id].blurb}">
        <b>${MUTATORS[id].name}</b><small>${MUTATORS[id].blurb}</small>
      </button>`).join("");
    options.querySelectorAll(".mutator-chip").forEach((chip) => {
      chip.addEventListener("click", () => toggleMutator(chip.dataset.mutator));
    });
  }
  options.querySelectorAll(".mutator-chip").forEach((chip) => {
    chip.classList.toggle("selected", pendingMutators.includes(chip.dataset.mutator));
  });
  $("#mutatorHint").textContent = pendingMutators.length
    ? `HOUSE RULES ON: ${mutatorLabel(pendingMutators)}`
    : "OPTIONAL HOUSE RULES · STACK AS MANY AS YOU WANT";
}

// R2.1 STREETS: offline versus FIRST-TO-N picker — lives beside the House
// Rules bar on the stage screen, versus only. Meta config, applied by the
// next startMatch(true).
function renderSetLengthBar() {
  const bar = $("#setLengthBar");
  if (!bar) return;
  const available = state.mode === "versus";
  bar.hidden = !available;
  if (!available) return;
  const options = $("#setLengthOptions");
  if (!options.childElementCount) {
    options.innerHTML = SET_LENGTHS.map((length) => `
      <button type="button" class="set-length-chip" data-set-length="${length}">
        ${length <= 1 ? "SINGLE MATCH" : `FIRST TO ${length}`}
      </button>`).join("");
    options.querySelectorAll(".set-length-chip").forEach((chip) => {
      chip.addEventListener("click", () => {
        pendingSetLength = normalizeSetLength(chip.dataset.setLength);
        sound("select");
        renderSetLengthBar();
      });
    });
  }
  options.querySelectorAll(".set-length-chip").forEach((chip) => {
    chip.classList.toggle("selected", normalizeSetLength(chip.dataset.setLength) === pendingSetLength);
  });
  const live = offlineSet && offlineSet.length === pendingSetLength && !setComplete(offlineSet) && offlineSet.history.length;
  $("#setLengthHint").textContent = pendingSetLength <= 1
    ? "ONE MATCH · NO SCOREBOARD"
    : live
      ? `SET LIVE · ${offlineSet.scores[0]}–${offlineSet.scores[1]} · WINNER STAYS`
      : `FIRST TO ${pendingSetLength} MATCH WINS TAKES THE SET`;
}

function toggleMutator(id) {
  if (!MUTATORS[id]) return;
  pendingMutators = pendingMutators.includes(id)
    ? pendingMutators.filter((existing) => existing !== id)
    : normalizeMutators([...pendingMutators, id]);
  sound("select");
  renderMutatorBar();
}

function showScreen(name) {
  if (demoSession.active && !["fight", "result"].includes(name)) endDemoSession();
  const keepsOnlineLink = state.mode === "online" && ["online", "fight", "result"].includes(name);
  if (onlineSession.role && !keepsOnlineLink) disconnectOnline(true);
  state.screen = name;
  $$(".screen").forEach((screen) => screen.classList.toggle("active", screen.id === `${name}Screen`));
  const playing = name === "fight";
  if (!playing) {
    state.paused = false;
    state.pauseReason = "";
    $("#pausePanel").hidden = true;
    $("#pauseReason").hidden = true;
    closeMoveListOverlay();
    hideControlCard();
  }
  $("#hud").classList.toggle("hidden", !playing);
  $("#hud").setAttribute("aria-hidden", String(!playing));
  if (!playing) $$(".combo-readout").forEach((readout) => readout.classList.remove("active"));
  const trainingVisible = playing && state.mode === "training";
  $("#trainingPanel").hidden = !trainingVisible;
  $("#gameFrame").classList.toggle("training-active", trainingVisible);
  // R1.9: the input column and school panel live and die with the lab.
  $("#inputHistoryColumn").hidden = !trainingVisible;
  if (!trainingVisible) $("#schoolPanel").hidden = true;
  else renderSchoolPanel();
  const playerControlled = playing && state.mode !== "demo" && !replayPlayback.active;
  $("#touchControls").classList.toggle("playing", playerControlled);
  $("#touchPauseButton").classList.toggle("playing", playerControlled || (playing && replayPlayback.active));
  $("#touchPauseButton").hidden = playing && state.mode === "online";
  if (!playing) $("#announcer").classList.add("hidden");
  updateFlowSkipHint();
  updateOnlineHud();
  updateReplayHud();
  updateDemoUi();
  syncMusic();
  if (name === "title") {
    refreshDailyUi();
    refreshProgressionUi();
    scheduleIdleDemo();
  } else clearIdleDemoTimer();
  // v2.1 PROGRESSION: leaving the ending screen tears the sequence down so
  // stale panel/credits timers can never advance a dead screen.
  if (name !== "ending" && endingSequence.active) cancelEndingSequence();
  if (name !== "result" && name !== "ending") updateDailyBanners();
  if (name === "stage") {
    renderMutatorBar();
    renderSetLengthBar();
  }
  // Wave 15: hold the screen awake through fights/attract, release on menus;
  // cabinet marquee lives and dies with the title screen.
  syncWakeLock();
  const marquee = $("#cabinetMarquee");
  if (marquee) marquee.hidden = !(state.cabinetMode && name === "title");
}

function startSelect(mode) {
  enterImmersiveMode();
  unlockAudio();
  state.mode = ["arcade", "versus", "training", "survival", "team"].includes(mode) ? mode : "arcade";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  state.teamPicks = [[], []];
  state.teamCpu = false;
  state.teamChoicePending = false;
  renderTeamOpponentChoice();
  dailySession.active = false;
  endScoreRun();
  if (state.mode === "training") {
    // A fresh lab entry keeps accessibility-style toggles but clears transient
    // playback, trial and dummy state so an old recording cannot move P2 during
    // the next intro or silently queue a dash before FIGHT.
    state.training = createTrainingState({
      autoRecover: state.training.autoRecover,
      infiniteGrit: state.training.infiniteGrit,
      showHitboxes: state.training.showHitboxes,
    });
  }
  state.picks = [0, state.mode === "arcade" ? 4 : 1];
  state.locks = [false, state.mode === "arcade" || state.mode === "survival"];
  state.selectingPlayer = 0;
  // Wave 16: fresh color picks each visit to the select screen.
  pendingPalettes = [0, 0];
  $("#selectPrompt").textContent = state.mode === "training"
    ? "CHOOSE YOUR TRAINING FIGHTER"
    : state.mode === "survival"
      ? "THE GAUNTLET — CHOOSE YOUR FIGHTER"
      : state.mode === "team"
        ? "BLOCK WAR · PLAYER 1 — PICK 3 (1/3)"
        : "PLAYER 1 — CHOOSE";
  showScreen("select");
  syncDifficultyUi();
  // v2.1 PROGRESSION: mastery chips reflect any records earned since boot.
  refreshMasteryBadges();
  updateRosterUI();
}

// Wave 16: `palette` is the SF2-style color pick riding the confirm input —
// LP/click/Enter/pad-A locks color 1, HP (or pad Y) locks color 2. Stored per
// seat in pendingPalettes; resolveMatchPalettes applies the mirror auto-alt.
function chooseFighter(index, palette = 0) {
  unlockAudio();
  const paletteSeat = state.mode === "team" ? -1
    : state.mode === "arcade" || state.mode === "survival" || !state.locks[0] ? 0 : 1;
  if (paletteSeat >= 0) pendingPalettes[paletteSeat] = palette === 1 ? 1 : 0;
  if (state.mode === "survival") {
    // The Gauntlet: one pick, straight into bout 1 — no stage select, the
    // seeded ladder owns the route.
    state.picks[0] = index;
    state.locks = [true, true];
    sound("select");
    const lockedCard = $(`.fighter-card[data-index="${index}"]`);
    if (lockedCard) {
      restartCssAnimation(lockedCard, "locked-flash");
      hudFxDebug.selectSlams += 1;
    }
    announcerSay(`${roster[index].id}-name`);
    startSurvivalRun(roster[index].id);
    return;
  }
  if (state.mode === "team") {
    // 5.1 (sweep #32): P1's third pick raises the VS CPU / VS PLAYER 2
    // choice; nothing else on the roster answers until it is made.
    if (state.teamChoicePending) return;
    const side = state.locks[0] ? 1 : 0;
    const team = state.teamPicks[side];
    if (team.includes(roster[index].id) || team.length >= TEAM_RULES.teamSize) return;
    team.push(roster[index].id);
    state.picks[side] = index;
    state.selectingPlayer = side;
    if (team.length >= TEAM_RULES.teamSize) {
      state.locks[side] = true;
      state.selectingPlayer = 1;
      if (side === 0) {
        state.teamChoicePending = true;
        renderTeamOpponentChoice();
      }
    }
    $("#selectPrompt").textContent = state.locks[0] && state.locks[1]
      ? "BLOCK WAR · TEAMS SET — STAGE SELECT"
      : state.teamChoicePending
        ? "BLOCK WAR · YOUR THREE ARE SET — WHO'S ACROSS THE STREET?"
        : state.locks[0]
          ? `BLOCK WAR · PLAYER 2 — PICK 3 (${state.teamPicks[1].length + 1}/3)`
          : `BLOCK WAR · PLAYER 1 — PICK 3 (${state.teamPicks[0].length + 1}/3)`;
    sound("select");
    const lockedCard = $(`.fighter-card[data-index="${index}"]`);
    if (lockedCard) {
      restartCssAnimation(lockedCard, "locked-flash");
      hudFxDebug.selectSlams += 1;
    }
    if (!(state.locks[0] && state.locks[1])) announcerSay(`${roster[index].id}-name`);
    updateRosterUI();
    return;
  }
  if (state.mode === "arcade") {
    state.picks[0] = index;
    state.locks = [true, true];
    state.arcadeRun = createArcadeRun(
      roster[index].id,
      roster.map(({ id }) => id),
      state.rng.nextUint32(),
    );
    // Release 1.8 GRIND: every arcade run is a score-attack run.
    beginScoreRun("arcade", `arcade-${roster[index].id}`, scoreDifficultyMultiplier(state.aiDifficulty));
    prepareArcadeOpponent(false);
  } else if (!state.locks[0]) {
    state.picks[0] = index;
    state.locks[0] = true;
    state.selectingPlayer = 1;
    $("#selectPrompt").textContent = state.mode === "training"
      ? "TRAINING DUMMY — CHOOSE"
      : "PLAYER 2 — CHOOSE";
  } else {
    state.picks[1] = index;
    state.locks[1] = true;
    state.selectingPlayer = 1;
  }
  sound("select");
  // Lock-in stamp: white card flash + punch-scale on the confirmed portrait.
  const lockedCard = $(`.fighter-card[data-index="${index}"]`);
  if (lockedCard) {
    restartCssAnimation(lockedCard, "locked-flash");
    hudFxDebug.selectSlams += 1;
  }
  // Wave 9: the announcer calls the locked fighter's name — unless this lock
  // completes the pair, in which case the VS slam calls both names instead.
  if (!(state.locks[0] && state.locks[1])) announcerSay(`${roster[index].id}-name`);
  updateRosterUI();
}

// 5.1 (sweep #32): the two-button opponent prompt on the Block War select
// screen. VS CPU drafts three fighters P1 did not pick (draftCpuTeam over
// state.rng — seedMatch reseeds at FIGHT, so the draw never leaks into the
// match stream), reveals them with the lock-in stamp one after another and
// raises the difficulty bar; VS PLAYER 2 hands the cursor to the second seat
// exactly as before.
function renderTeamOpponentChoice() {
  const choice = $("#teamOpponentChoice");
  if (!choice) return;
  const visible = state.screen === "select" && state.mode === "team" && state.teamChoicePending;
  choice.hidden = !visible;
  if (visible) $("[data-team-opponent='cpu']")?.focus?.({ preventScroll: true });
}

function focusTeamOpponentChoice(delta = 0) {
  const buttons = $$("[data-team-opponent]");
  if (!buttons.length) return null;
  const current = Math.max(0, buttons.indexOf(document.activeElement));
  const next = buttons[(current + delta + buttons.length) % buttons.length];
  next.focus?.({ preventScroll: true });
  return next;
}

function chooseTeamOpponent(kind = "cpu") {
  if (state.mode !== "team" || !state.teamChoicePending) return false;
  unlockAudio();
  state.teamChoicePending = false;
  if (kind === "cpu") {
    const drafted = draftCpuTeam(state.teamPicks[0], roster.map(({ id }) => id), () => state.rng.nextFloat());
    state.teamPicks[1] = drafted;
    state.teamCpu = true;
    state.locks[1] = true;
    state.picks[1] = Math.max(0, rosterIndexById(drafted[drafted.length - 1]));
    $("#selectPrompt").textContent = "BLOCK WAR · CPU DRAFTED — STAGE SELECT";
    drafted.forEach((id, order) => {
      window.setTimeout(() => {
        if (state.screen !== "select" || state.mode !== "team") return;
        const card = $(`.fighter-card[data-index="${rosterIndexById(id)}"]`);
        if (card) {
          restartCssAnimation(card, "locked-flash");
          hudFxDebug.selectSlams += 1;
        }
      }, 140 + order * 260);
    });
    modeFxDebug.teamDrafts += 1;
  } else {
    state.teamCpu = false;
    $("#selectPrompt").textContent = `BLOCK WAR · PLAYER 2 — PICK 3 (${state.teamPicks[1].length + 1}/3)`;
  }
  sound("select");
  renderTeamOpponentChoice();
  syncDifficultyUi();
  updateRosterUI();
  return true;
}

function updateRosterUI() {
  const teamMode = state.mode === "team";
  $$(".fighter-card").forEach((card) => {
    const index = Number(card.dataset.index);
    const id = roster[index]?.id;
    card.classList.toggle("p1-pick", teamMode
      ? state.teamPicks[0].includes(id)
      : state.locks[0] && state.picks[0] === index);
    card.classList.toggle("p2-pick", teamMode
      ? state.teamPicks[1].includes(id)
      : state.locks[1] && state.picks[1] === index);
    card.classList.toggle("focused", !state.locks[state.selectingPlayer] && state.picks[state.selectingPlayer] === index);
    // Wave 16: the alt-color stamp on a locked card.
    card.classList.toggle("alt-pick", !teamMode && (
      (state.locks[0] && state.picks[0] === index && pendingPalettes[0] === 1)
      || (state.locks[1] && state.picks[1] === index && pendingPalettes[1] === 1)));
  });
  const readout = $("#selectionReadout");
  readout.innerHTML = teamMode
    ? `<span>P1</span> <b class="vs-name p1n">${state.teamPicks[0].map((id) => roster[rosterIndexById(id)].mark).join("·") || "—"}</b> <i>VS</i> <span>P2</span> <b class="vs-name p2n">${state.teamPicks[1].map((id) => roster[rosterIndexById(id)].mark).join("·") || "—"}</b>`
    : `<span>P1</span> <b class="vs-name p1n">${roster[state.picks[0]].name}</b> <i>VS</i> <span>P2</span> <b class="vs-name p2n">${roster[state.picks[1]].name}</b>`;
  const bothLocked = state.locks[0] && state.locks[1];
  readout.classList.toggle("both-locked", bothLocked);
  // VS slam: once both slots lock, the two names slam in from the sides
  // around the flashing VS with a clash flash between them. Latched so
  // later roster refreshes don't replay it.
  if (bothLocked && !selectBothLocked) {
    restartCssAnimation(readout, "vs-slam");
    hudFxDebug.selectSlams += 1;
    // Wave 9: the VS slam calls the matchup — both names in sequence.
    announcerSay(`${roster[state.picks[0]].id}-name`);
    announcerSay(`${roster[state.picks[1]].id}-name`, { delay: 700 });
  } else if (!bothLocked) readout.classList.remove("vs-slam");
  selectBothLocked = bothLocked;
  $("#fighterContinue").disabled = !bothLocked;
  // v5.1 #35: warm the highlighted matchup's sheets (after a dwell; at once
  // on a lock) — the select and stage screens are 5-15 s of cover the first
  // fight used to waste.
  preloadSelectMatchup({ immediate: bothLocked, voice: bothLocked });
}

function showStageSelect() {
  if (!(state.locks[0] && state.locks[1])) return;
  $("#fightButton").textContent = state.mode === "training" ? "ENTER LAB →" : "FIGHT →";
  showScreen("stage");
  // v5.1 #35: the matchup is final here — sheets first, then voice.
  preloadSelectMatchup({ immediate: true, voice: true });
  renderArcadeRoute();
  updateStageUI();
}

function chooseStage(id) {
  state.stage = id;
  sound("select");
  updateStageUI();
}

function updateStageUI() {
  $$(".stage-card").forEach((card) => card.classList.toggle("selected", card.dataset.stage === state.stage));
  $("#stageReadout").textContent = stages[state.stage].name;
  $("#stageTicker").textContent = stages[state.stage].ticker;
}

function startMatch(resetSet = true) {
  cancelFightAnnouncement();
  // Wave 19: any match that is NOT a bracket bout clears the pending bracket
  // outcome so the result screen never wears the wrong buttons.
  if (!bracketSession.playing) bracketSession.lastOutcome = null;
  // The attract loop starts itself with no user gesture, so it must never try
  // to unlock audio — the call warns without one.
  if (!(state.mode === "demo" && demoSession.attract)) unlockAudio();
  // Release 1.6: AUTO mode now picks the stage-matched track instead of
  // cycling the jukebox. Demo/attract keeps whatever was already playing.
  if (state.mode !== "demo") applyAutoStageMusic();
  resetMusicDuck();
  if (resetSet) {
    state.rounds = [0, 0];
    state.round = 1;
  }
  state.matchSerial += 1;
  state.qaManualMode = false;
  // R2.1 STREETS: offline versus set prep. A fresh FT pick (or a finished
  // set) rebuilds the scoreboard; matching live sets carry across rematches.
  if (state.mode === "versus" && !state.teamBattle && !bracketSession.playing && resetSet) {
    if (pendingSetLength > 1 && (!offlineSet || offlineSet.length !== pendingSetLength || setComplete(offlineSet))) {
      offlineSet = createSetState(pendingSetLength);
    } else if (pendingSetLength <= 1) {
      offlineSet = null;
    }
  }
  // Release 1.8 GRIND: build the Block War roster on the first FIGHT press,
  // then lock the House Rules config for this match BEFORE the fighters are
  // built (Turbo scales movement at makeFighter time).
  if (state.mode === "team" && !state.teamBattle && state.teamPicks[0].length === TEAM_RULES.teamSize) {
    beginTeamBattle(state.teamCpu);
  }
  applyMatchRulesForMatch();
  resetRoundScoreTracking();
  // Arcade bouts score against the CURRENT difficulty setting; survival and
  // the daily pin their own multipliers when they prepare the bout.
  if (scoreSession.active && scoreSession.mode === "arcade" && state.mode === "arcade") {
    scoreSession.multiplier = scoreDifficultyMultiplier(state.aiDifficulty);
  }
  seedMatch(state.round);
  state.fighters = makeMatchFighters();
  applyModeFighterSetup();
  resetStageWeapon();
  resetCrowd();
  warmFighterAudio();
  if (state.mode === "training") {
    state.training = createTrainingState({
      ...state.training,
      resets: 0,
      lastDamage: 0,
      lastResult: "READY",
    });
    resetTrainingScenario(state.training);
    selectTrainingTrial(state.training, state.fighters[0].kitId, state.training.trialIndex);
    if (state.training.infiniteGrit) state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  }
  clearBattleDamage();
  clearStageScars();
  // v2.1 PROGRESSION: fresh per-match observation accumulators (fighters are
  // built and any survival/team carry health is already applied above).
  progressionResetMatch();
  state.particles.length = 0;
  state.effects.length = 0;
  state.traps.length = 0;
  state.projectiles.length = 0;
  state.timer = 99;
  state.timerCarry = 0;
  state.phase = "intro";
  state.phaseTime = 2.25;
  state.hitstop = 0;
  state.lastImpactSide = -1;
  state.finishWinner = -1;
  state.finisherType = 0;
  state.finisher = null;
  state.cinematicZoom = 1;
  setTouchPrompt("");
  $("#touchControls").classList.remove("cinematic");
  commandHistory[0].length = 0;
  commandHistory[1].length = 0;
  updateHud();
  showScreen("fight");
  // v5.1 #35: hold the intro clock (offline only, capped) until both
  // fighters' unified family has decoded — see armIntroArtHold. Armed BEFORE
  // the FIGHT! timer below so a release can shift it.
  armIntroArtHold(state.fighters.map((fighter) => fighter.def.id));
  // After showScreen: the touch HUD only exists (display: flex) once the
  // fight screen has marked it .playing, and the coach checks exactly that.
  // 5.1: the first-run control card is raised here, on startMatch's own
  // round-1 path (resetRound only serves later rounds and round restarts),
  // and BEFORE the flick tip so the two coaching lines never share the
  // screen — maybeCoachTouchFlick defers while the card is up.
  if (!rollbackResimulating) maybeShowControlCard();
  maybeCoachTouchFlick();
  updateTrainingUi();
  const arcadeMatch = state.mode === "arcade" ? currentArcadeMatch(state.arcadeRun) : null;
  let introLabel = arcadeMatch?.kind === "boss" ? "FINAL BOUT · THE COMMISSIONER"
    : arcadeMatch?.kind === "rival" ? `RIVAL BOUT · ${state.fighters[1].def.name}`
      : stages[state.stage].name;
  let introMain = `ROUND ${state.round}`;
  // Release 1.8 GRIND: mode-flavoured intro banners. Survival counts bouts,
  // Block War calls the pairing (and the walk-in), active House Rules get
  // named, and a walked-in teammate gets their name-call intro voice cue.
  if (state.mode === "survival" && state.survivalRun) {
    const bout = currentSurvivalBout(state.survivalRun);
    introMain = `BOUT ${(bout?.index ?? 0) + 1}`;
    introLabel = `${state.fighters[1].def.name} · ${state.survivalRun.wins} WIN STREAK`;
  } else if (state.mode === "team" && state.teamBattle) {
    const battle = state.teamBattle;
    const incoming = battle.lastElimination?.incomingId;
    introMain = `BOUT ${battle.bout}`;
    introLabel = incoming
      ? `${roster[rosterIndexById(incoming)]?.name || incoming} STEPS IN · ${teamFightersRemaining(battle, 0)}V${teamFightersRemaining(battle, 1)}`
      : `BLOCK WAR · ${teamFightersRemaining(battle, 0)}V${teamFightersRemaining(battle, 1)}`;
    if (incoming) announcerSay(`${incoming}-name`, { delay: 300 });
  }
  if (state.mutators.length) introLabel = `${introLabel} · ${mutatorLabel(state.mutators)}`;
  announce(introMain, introLabel, 1.2);
  // Wave 16: rival and FINAL BOUT intros open with a spoken-card exchange —
  // the intro window stretches to fit the read, and the FIGHT call waits.
  const dialogueSeconds = beginIntroDialogue(arcadeMatch);
  if (dialogueSeconds > 0) state.phaseTime = dialogueSeconds;
  // Wave 9: the arcade final boss bout gets its own announcer intro, queued
  // behind ROUND 1 / FIGHT via the announcer busy window.
  if (arcadeMatch?.kind === "boss") {
    voiceFxDebug.storyCallouts += 1;
    announcerSay("boss-intro", { delay: 2100 });
  }
  scheduleFightAnnouncement(() => {
    if (state.screen === "fight" && state.phase === "intro") announce("FIGHT!", "NO MERCY ON THESE STREETS", 0.8);
  }, dialogueSeconds > 0 ? Math.round(dialogueSeconds * 1000) - 650 : 1150);
  // R2.1 STREETS: arm the replay recorder once the match config is FINAL
  // (mutators, palettes, stage and the dialogue-stretched intro clock). Only
  // fresh matches record — a mid-match round restart cannot be replayed.
  if (resetSet && state.round === 1) beginReplayRecording("offline");
  else resetReplayRecorder();
  canvas.focus();
}

function startOnlineMatch(config) {
  if (!validOnlineMatchConfig(config)) return false;
  cancelFightAnnouncement();
  unlockAudio();
  resetMusicDuck();
  state.mode = "online";
  state.arcadeRun = null;
  state.survivalRun = null;
  state.teamBattle = null;
  dailySession.active = false;
  endScoreRun();
  // Release 1.8 GRIND: mutators only run online when BOTH sides carry them in
  // the shared match config. The lobby never offers them, so plain/ranked
  // rooms always derive the clean default rules on both peers.
  state.mutators = normalizeMutators(config.mutators || []);
  state.matchRules = resolveMatchRules(state.mutators);
  state.suddenDeathHitDone = false;
  state.qaManualMode = false;
  state.paused = false;
  onlineSession.matchConfig = cloneRollbackValue(config);
  onlineSession.matchActive = true;
  onlineSession.networkPaused = false;
  onlineSession.localSuspended = false;
  onlineSession.remoteSuspended = false;
  onlineSession.awaitingResume = false;
  onlineSession.rematchVotes.clear();
  onlineSession.remoteChecksums.clear();
  onlineSession.checksumMismatches = 0;
  onlineSession.lastChecksumSentFrame = -1;
  onlineSession.lastPersistedFrame = -1;
  onlineSession.lobby.localReady = false;
  onlineSession.lobby.remoteReady = false;
  state.picks = config.picks.map((id) => roster.findIndex((fighter) => fighter.id === id));
  state.stage = config.stage;
  // Release 1.6: online AUTO music maps to the agreed stage (set just above).
  applyAutoStageMusic();
  state.rounds = [0, 0];
  state.round = 1;
  state.matchSerial += 1;
  state.simulationTick = 0;
  seedOnlineRound(1);
  state.fighters = makeMatchFighters();
  resetStageWeapon();
  resetCrowd();
  warmFighterAudio();
  clearBattleDamage();
  clearStageScars();
  // v2.1 PROGRESSION: observation-only accumulators reset for the online
  // match too (nothing here ever writes back into the rollback sim).
  progressionResetMatch();
  state.particles.length = 0;
  state.effects.length = 0;
  state.traps.length = 0;
  state.projectiles.length = 0;
  state.timer = 99;
  state.timerCarry = 0;
  state.phase = "intro";
  state.phaseTime = 2.25;
  state.hitstop = 0;
  state.lastImpactSide = -1;
  state.finishWinner = -1;
  state.finisherType = 0;
  state.finisher = null;
  state.cinematicZoom = 1;
  state.shake = 0;
  state.flash = 0;
  commandHistory[0].length = 0;
  commandHistory[1].length = 0;
  // R2.1 STREETS: adopt the set carried in the shared config. The host is
  // authoritative (its scores snapshot rides the config); a config from an
  // older host simply resets to a dormant single-match session.
  const setLength = normalizeSetLength(config.setLength);
  if (config.set && typeof config.set === "object") {
    onlineSession.set = sanitizeSetSync(config.set, setLength);
  } else if (onlineSession.set.length !== setLength || setComplete(onlineSession.set)) {
    onlineSession.set = createSetState(setLength);
  }
  // Arm the confirmed-input recorder BEFORE the session exists so frame 0 of
  // the step callback is already observed.
  beginReplayRecording("online");
  // Wave 19: fresh match, fresh broadcast frontier. The header goes out with
  // the first pump once a watcher has said hello.
  spectateHost.lastSentFrame = 0;
  spectateHost.headerSentFor = "";
  if (onlineSession.role === "host" && spectateHost.wantsStream) sendSpectateHeader();
  onlineSession.rollback = createOnlineRollback(config, 0);
  // Pre-fight 3-2-1 sync countdown over the intro (pure presentation).
  beginSyncCountdown();
  $("#onlineMatchSetup").hidden = true;
  $("#onlineRematchStatus").hidden = true;
  $("#touchControls").classList.remove("cinematic");
  setTouchPrompt("");
  updateStageUI();
  updateHud();
  showScreen("fight");
  updateOnlineHud();
  announce("ONLINE ROUND 1", `${roster[state.picks[0]].name} VS ${roster[state.picks[1]].name} · ${config.inputDelay}F DELAY`, 1.35);
  scheduleFightAnnouncement(() => {
    if (state.mode === "online" && state.screen === "fight" && state.phase === "intro") announce("FIGHT!", "ROLLBACK SYNC LOCKED", 0.8);
  }, 1150);
  persistOnlineResume(true);
  canvas.focus();
  return true;
}

function resetRound() {
  cancelFightAnnouncement();
  resetMusicDuck();
  const carriedGrit = state.fighters.map((fighter) => fighter.meter);
  state.round += 1;
  // R2.1 STREETS: a manually-stepped replay stays manual across the round
  // break (qaManualMode is meta — never checksummed).
  if (!replayPlayback.active) state.qaManualMode = false;
  // Release 1.8 GRIND: per-round sim/meta resets — the Sudden Death one-shot
  // re-arms (sim state) and the FIRST ATTACK score flag re-arms (meta).
  state.suddenDeathHitDone = false;
  resetRoundScoreTracking();
  if (state.mode === "online") seedOnlineRound(state.round);
  else seedMatch(state.round);
  state.fighters = makeMatchFighters();
  warmFighterAudio();
  state.fighters.forEach((fighter, side) => { fighter.meter = carriedGrit[side] || 0; });
  if (state.matchRules.infiniteGrit) state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  resetStageWeapon();
  resetCrowd();
  clearBattleDamage();
  // v2.1 PROGRESSION: re-arm the per-round latches (jump/no-jump, damage
  // sources, round-start health). resetRound runs on a sim path — guarded.
  if (!rollbackResimulating) progressionResetRound();
  state.particles.length = 0;
  state.effects.length = 0;
  state.traps.length = 0;
  state.projectiles.length = 0;
  state.timer = 99;
  state.timerCarry = 0;
  state.phase = "intro";
  // v2.9 FLOW round 2: demo-only shorter round card — the exhibition owes the
  // viewer fighting, not four seconds of ROUND 2 per exhibition. Every other
  // mode keeps the full 2.1s presentation.
  state.phaseTime = state.mode === "demo" ? DEMO_ROUND_INTRO_SECONDS : 2.1;
  state.hitstop = 0;
  state.lastImpactSide = -1;
  state.finishWinner = -1;
  state.finisher = null;
  state.cinematicZoom = 1;
  setTouchPrompt("");
  $("#touchControls").classList.remove("cinematic");
  commandHistory[0].length = 0;
  commandHistory[1].length = 0;
  updateFlowSkipHint();
  updateHud();
  announce(`ROUND ${state.round}`, "SETTLE IT", 1.15);
  scheduleFightAnnouncement(() => {
    if (state.screen === "fight" && state.phase === "intro") announce("FIGHT!", "", 0.75);
  }, 1050);
  // 5.1: a later round always clears the card; round 1 of the first fight
  // may raise it (render-only, guarded — resetRound runs on a sim path).
  if (!rollbackResimulating) {
    if (state.round === 1) maybeShowControlCard();
    else hideControlCard();
  }
}

function announce(main, sub = "", duration = 1, { speak = null } = {}) {
  if (rollbackResimulating) return;
  const box = $("#announcer");
  const strong = box.querySelector("strong");
  const text = String(main);
  // Wave 9: every banner also books its spoken announcer call (captions
  // always; audio only once real takes exist in assets/audio/announcer/).
  // w51: a caller that knows more than the banner text (finishRound knows
  // whether the round was a decision and whether it closed the match) hands
  // the exact cue plan in through `speak`; the text map is the fallback.
  announcerSpeakBanner(text, speak);
  const letters = [...text];
  // Letter-by-letter slam: each character lands with its own scale-punch on a
  // short stagger. The innerHTML rebuild also restarts the animation on
  // consecutive announces (ROUND N -> FIGHT!) which the old textContent write
  // never replayed. Spaces keep white-space:pre so textContent round-trips
  // exactly (QA reads the announcer text).
  const stagger = 55;
  strong.setAttribute("aria-label", text);
  strong.innerHTML = letters.map((character, index) => (character === " "
    ? `<i class="gap" aria-hidden="true"> </i>`
    : `<i aria-hidden="true" style="animation-delay:${index * stagger}ms">${escapeAnnounceChar(character)}</i>`)).join("");
  hudFxDebug.letterSlams += letters.filter((character) => character !== " ").length;
  box.querySelector("span").textContent = sub;
  box.classList.remove("hidden", "out");
  // Small screen kick per landing letter: a jolt animation on the frame whose
  // duration tracks the letter count. Killed outright by body.reduced-motion.
  if (!state.accessibility.reducedMotion) {
    const frame = $("#gameFrame");
    frame.style.setProperty("--announce-kick-ms", `${Math.min(letters.length, 14) * stagger + 180}ms`);
    restartCssAnimation(frame, "announce-kick");
  }
  clearTimeout(announce.timer);
  clearTimeout(announce.outTimer);
  // Punch out with a quick scale-snap instead of blinking off; the final
  // hide still lands at exactly duration * 1000 so no hold timing moves.
  announce.outTimer = setTimeout(() => box.classList.add("out"), Math.max(0, duration * 1000 - 150));
  announce.timer = setTimeout(() => {
    box.classList.add("hidden");
    box.classList.remove("out");
  }, duration * 1000);
}

function updateFlowSkipHint() {
  const visible = state.screen === "fight" && (state.phase === "intro" || state.phase === "roundover");
  $("#flowSkipHint").hidden = !visible;
}

// ---------------------------------------------------------------------------
// R2.0 FAMILY wave 16 — pre-fight dialogue exchanges. Arcade-only: a rival
// bout or the FINAL BOUT opens with a two-card spoken exchange during the
// intro window (extended to fit the read). Pure presentation on module-level
// state — never snapshotted, never read by the sim; the intro phase clock it
// keys off is ordinary deterministic match config. Skippable through the
// existing flow-skip (phase leaves "intro" -> cards drop on the next frame);
// reduced motion shows both cards instantly with no slide.
// ---------------------------------------------------------------------------
const INTRO_DIALOGUE_SECONDS = 4.9;
const INTRO_DIALOGUE_CARD_TIMES = [0.35, 2.45];

const introDialogue = {
  active: false,
  kind: "",
  lines: [],
  total: 0,
  revealed: 0,
};
// Last variant shown per pairing, so back-to-back runs never repeat while an
// alternative exists. visualRandom only — presentation stream.
const dialogueVariantMemory = new Map();

function dialogueSpeakerDef(fighterId) {
  return fighterId === ARCADE_BOSS_ID
    ? arcadeBoss
    : roster.find(({ id }) => id === fighterId) || null;
}

function pickDialogueVariant(key, variants) {
  if (!variants?.length) return null;
  let pick = Math.floor(visualRandom() * variants.length) % variants.length;
  if (variants.length > 1 && pick === dialogueVariantMemory.get(key)) pick = (pick + 1) % variants.length;
  dialogueVariantMemory.set(key, pick);
  return variants[pick];
}

function cancelIntroDialogue() {
  introDialogue.active = false;
  introDialogue.lines = [];
  introDialogue.revealed = 0;
  const box = $("#introDialogue");
  if (box) {
    box.hidden = true;
    box.innerHTML = "";
  }
}

/**
 * Arm the exchange for the match being started. Returns the intro length the
 * bout should run (0 = no dialogue, keep the standard fast intro).
 */
function beginIntroDialogue(arcadeMatch) {
  cancelIntroDialogue();
  if (state.mode !== "arcade" || !arcadeMatch || !state.arcadeRun) return 0;
  const playerId = state.arcadeRun.playerId;
  let variant = null;
  if (arcadeMatch.kind === "rival") {
    variant = pickDialogueVariant(
      `rival:${[playerId, arcadeMatch.opponentId].sort().join(":")}`,
      rivalDialogueVariants(playerId, arcadeMatch.opponentId),
    );
  } else if (arcadeMatch.kind === "boss") {
    variant = pickDialogueVariant(`boss:${playerId}`, bossDialogueVariants(playerId));
  }
  if (!variant) return 0;
  introDialogue.active = true;
  introDialogue.kind = arcadeMatch.kind;
  introDialogue.total = INTRO_DIALOGUE_SECONDS;
  introDialogue.revealed = 0;
  introDialogue.lines = variant.map((card, index) => {
    const def = dialogueSpeakerDef(card.id);
    // Which corner speaks: match the card to a fighter side; a mirror (both
    // the same id) gives the opening line to the far corner.
    const sides = state.fighters
      .map((fighter, side) => ({ side, id: fighter.def.kitId === "commissioner" ? ARCADE_BOSS_ID : fighter.def.id }))
      .filter((entry) => entry.id === card.id);
    const side = sides.length === 1 ? sides[0].side : index === 0 ? 1 : 0;
    return {
      id: card.id,
      line: card.line,
      name: def?.name || card.id.toUpperCase(),
      color: def?.color || "#d8d8d8",
      side,
    };
  });
  modeFxDebug.dialogueExchanges += 1;
  const box = $("#introDialogue");
  if (box) {
    box.innerHTML = introDialogue.lines.map((card, index) => `
      <div class="speech-card ${card.side === 0 ? "from-left" : "from-right"}" data-card="${index}" hidden>
        <b style="--speaker:${card.color}">${card.name}</b>
        <p>${card.line}</p>
      </div>`).join("");
    box.hidden = false;
  }
  return INTRO_DIALOGUE_SECONDS;
}

// Per-rendered-frame card reveal, driven by the intro phase clock so pause
// holds the cards and the flow-skip drops them with the phase.
function updateIntroDialogue() {
  const box = $("#introDialogue");
  if (!box) return;
  const live = introDialogue.active && state.screen === "fight" && state.phase === "intro";
  if (!live) {
    if (introDialogue.active && (state.phase !== "intro" || state.screen !== "fight")) cancelIntroDialogue();
    else if (!box.hidden && !introDialogue.active) box.hidden = true;
    return;
  }
  const reduced = state.accessibility.reducedMotion;
  const elapsed = introDialogue.total - state.phaseTime;
  box.querySelectorAll(".speech-card").forEach((cardEl, index) => {
    const show = reduced || elapsed >= (INTRO_DIALOGUE_CARD_TIMES[index] ?? 0);
    if (show && cardEl.hidden) {
      cardEl.hidden = false;
      cardEl.classList.toggle("instant", reduced);
      modeFxDebug.dialogueCardsShown += 1;
      introDialogue.revealed = Math.max(introDialogue.revealed, index + 1);
    }
  });
}

// Release 1.8 GRIND: only HUMAN inputs may skip the intro/round-over flow. A
// CPU pressing buttons (arcade zoners, survival, Block War, demo) used to
// fast-forward straight through — which would eat the new elimination
// callouts and team walk-ins entirely.
function sideIsCpuControlled(side) {
  if (state.mode === "demo" || state.mode === "tournament") return true;
  // Wave 19: THE PHILLY OPEN — each seat's humanity comes from the bracket
  // entrant list (a lone human always sits on side 0 for hot-seat play).
  if (state.mode === "versus" && bracketSession.playing) return bracketSession.matchCpu[side];
  if (side !== 1) return false;
  return state.mode === "arcade"
    || state.mode === "survival"
    || (state.mode === "team" && Boolean(state.teamBattle?.cpu))
    || (state.mode === "training" && state.training.dummyMode === "cpu");
}

function trySkipFightFlow(input0 = {}, input1 = {}) {
  const humanInput0 = sideIsCpuControlled(0) ? {} : input0;
  const humanInput1 = sideIsCpuControlled(1) ? {} : input1;
  if (!hasFlowSkipInput(humanInput0) && !hasFlowSkipInput(humanInput1)) return false;
  // In the CPU-only modes a finisher is the thing being exhibited — the
  // showcase must never cancel itself. The CPU-input filter above already
  // covers demo and tournament; kept as belt-and-braces.
  if (state.phase === "roundover" && state.finisher
    && (state.mode === "demo" || state.mode === "tournament")) return false;
  if (state.phase === "intro") {
    state.phase = "fight";
    state.phaseTime = 0;
    // A skipped intro lands any Block War walk-in on their slot instantly.
    for (const fighter of state.fighters) {
      if (Number.isFinite(fighter.introWalkTarget)) fighter.x = fighter.introWalkTarget;
      fighter.introWalkTarget = null;
    }
    cancelFightAnnouncement();
    announce("FIGHT!", "INTRO SKIPPED", 0.55);
    updateFlowSkipHint();
    // v5.3 SPECTACLE: a skipped intro is still a round start.
    playMusicStinger("roundstart", { source: `round${state.round}-skip` });
    return true;
  }
  if (state.phase === "roundover") {
    state.phaseTime = 0;
    state.finisher = null;
    state.cinematicZoom = 1;
    $("#touchControls").classList.remove("cinematic");
    updateFlowSkipHint();
    return true;
  }
  return false;
}

function finishRound(winner, type = -1) {
  if (state.phase === "roundover" || state.phase === "result") return;
  for (const fighter of state.fighters) clearGrabState(fighter);
  for (const fighter of state.fighters) { fighter.carriedWeapon = null; fighter.carryFrames = 0; }
  if (state.stageWeapon) state.stageWeapon.phase = "gone";
  state.phase = "roundover";
  state.rounds[winner] += 1;
  state.finisherType = type;
  // v5.1 KO MOMENT: the round-winning hit is the biggest stir of the round —
  // the FINISH prompt's 1.4, tagged "ko" so the swell plays the KO recipe and
  // the voiced crowd roars. Sim path on purpose (deterministic on both
  // rollback peers, like every other stir); the roundover HOLD that keeps the
  // crowd up for the 4.9 s is render-side (updateCrowdKoHoldLatch).
  stirCrowd(1.4, "ko", { side: winner, splatX: state.fighters[1 - winner]?.x ?? null });
  // v2.9 FLOW: demo coverage — the round-end beat, plus the Final Blow
  // ceremony when one executes (the gore/fatality toggles decide the flavour
  // downstream exactly as before; this is pure observation).
  demoChoreoBeat(winner, "roundEnd");
  if (type >= 0) demoChoreoBeat(winner, "finisher");
  const winDef = state.fighters[winner].def;
  // Wave 15: the KO slams in the hands — for both the knockout hold and the
  // opening of a Final Blow ceremony (all gates inside combatHaptic).
  combatHaptic("ko");
  if (type >= 0) {
    const duration = performFinisher(winner, type);
    state.phaseTime = duration;
    duckMusic(0.1, duration * 1000);
    const scriptId = winDef.finisherScriptId || winDef.id;
    announce("FINAL BLOW", `${winDef.finishers[type]} · ${projectileFinisherScript(scriptId, type).combo}`, 2.45);
  } else {
    // Hold the KO scene so the blood, dust and reactions can be seen before the
    // next round or the result screen takes over.
    // v2.9 FLOW round 2: the attract loop holds a plain KO a little shorter
    // (demo-only; every other mode keeps the full 4.9s beat).
    state.phaseTime = roundWinHoldSeconds();
    duckMusic(0.28, 2600);
    // w51 announcer truth: the clock running out on two standing fighters is
    // a DECISION, not a knockout — the banner says so, the announcer opens on
    // the timeover bank instead of "K.O.!", and knockout.mp3 (the reviewed
    // shared KO groan) stays silent because nobody went down; the :00 buzzer
    // from the clock tick is the sound of that moment. A round win speaks the
    // winner's name; only the round that closes the match (state.rounds was
    // incremented above) earns the "<id>-wins" bank.
    const loser = state.fighters[1 - winner];
    const cause = roundEndCause({ finisherType: type, timer: state.timer, loserHealth: loser.health });
    const matchWon = state.rounds[winner] >= roundsToWinValue();
    const speak = roundEndAnnouncerPlan({ cause, matchWon, fighterId: winDef.id });
    announce(`${winDef.name} WINS`, roundEndBannerSub(cause), 2.4, { speak });
    // v5.3 SPECTACLE: the musical punctuation the round bookends never had —
    // a KO stab, a sour TIME OVER figure, or the match-win fanfare, played on
    // the stinger channel over the bed the duck above just lowered. The
    // decision is engine/music musicStingerForRoundEnd (a Final Blow returns
    // null there: performFinisher's 0.1 duck hands the frame to the gore mix,
    // and that branch never reaches here anyway).
    playMusicStinger(musicStingerForRoundEnd({ cause, matchWon, finisher: type >= 0 }), {
      source: `round${state.round}:${cause}`,
    });
    if (cause !== ROUND_END_CAUSES.decision) sound("ko", loser);
    // v5.3 SPECTACLE (ko-collapse): THE BODY GOES DOWN. checkKnockout stood
    // the victim up for the Final Blow stand-off (down=false, stun=99,
    // hitstunFrames=5940); when that window expires unspent the loser was
    // left on his feet, drawing the head-snap for the whole 4.9 s hold. The
    // decision is engine/bookends koCollapseOnRoundEnd — knockout only, and
    // only a fighter still standing on the ground — so a DECISION and a
    // FINAL BLOW are both untouched (the finisher branch above never reaches
    // here at all). Everything after this is the ORDINARY knockdown path.
    if (koCollapseOnRoundEnd({
      cause, health: loser.health, down: loser.down, grounded: loser.grounded,
    })) collapseKoLoser(loser);
  }
  // Wave 9: round-story callouts (FLAWLESS / COMEBACK / time-over / fatality)
  // layered after the primary call — guarded + deduped like announce().
  if (!rollbackResimulating) queueStoryCallouts(winner, type);
  // Release 1.8 GRIND: bank the SF2 tally bonuses for this round (score is
  // meta, tracked outside the checksummed state) and, in Block War, layer the
  // elimination callout behind the KO banner via the announcer busy window.
  if (!rollbackResimulating) {
    captureRoundBonuses(winner, type);
    // v2.1 PROGRESSION: round-end observation fold (dedupe key inside, same
    // shape as queueStoryCallouts'), plus any Black Book unlock toasts.
    progressionRoundEnd(winner, type);
    if (state.mode === "team" && state.teamBattle && !state.teamBattle.over) {
      const loserDef = state.fighters[1 - winner].def;
      const remaining = teamFightersRemaining(state.teamBattle, 1 - winner) - 1;
      const line = TEAM_ELIMINATION_LINES[
        (state.teamBattle.eliminated[0].length + state.teamBattle.eliminated[1].length) % TEAM_ELIMINATION_LINES.length
      ];
      modeFxDebug.teamEliminations += 1;
      scheduleFightAnnouncement(() => {
        if (state.screen === "fight" && state.phase === "roundover") {
          announce(`${loserDef.name} ELIMINATED`, remaining > 0 ? line : "LAST ONE DOWN · BLOCK WAR OVER", 1.7);
        }
      }, 2550);
    }
  }
  updateFlowSkipHint();
  updateHud();
}

function performFinisher(winner, type) {
  const attacker = state.fighters[winner];
  const victim = state.fighters[1 - winner];
  const scriptId = attacker.def.finisherScriptId || attacker.def.id;
  const script = projectileFinisherScript(scriptId, type);
  const fatality = getGraphicFatality(scriptId, type);
  const fatalityAt = script.impacts.find((impact) => impact.final)?.t ?? script.duration;
  const direction = attacker.x <= victim.x ? 1 : -1;
  const anchor = clamp(victim.x, 390, W - 390);
  attacker.attacking = null;
  attacker.vx = 0;
  attacker.vy = 0;
  attacker.down = false;
  victim.vx = 0;
  victim.vy = 0;
  victim.down = false;
  state.finisher = {
    winner,
    type,
    script,
    direction,
    anchor,
    elapsed: 0,
    impactIndex: 0,
    beatLabel: script.combo,
    beatLife: .8,
    fatalityId: fatality.id,
    fatalityAt,
    fatalityTriggered: false,
    cinematicShot: "establishing",
    cinematicCuts: 0,
    impactCloseUps: 0,
    peakZoom: 1.24,
    slowMotionHits: 0,
    signatureProjectileTriggered: false,
    signatureProjectileId: null,
    signatureProjectileName: null,
    projectileFocusBeats: 0,
    projectileFocusBursts: 0,
    projectileBeatLabels: [],
    projectilePhase: "waiting",
  };
  state.cinematicZoom = 1.24;
  state.shake = .16;
  if (!rollbackResimulating) {
    setTouchPrompt("");
    $("#touchControls").classList.add("cinematic");
  }
  // Keep the fighter's launch accent, then place the dedicated spoken cue on
  // top so every LP/LK execution clearly announces "Death Blow" once.
  sound("special", attacker);
  sound("final");
  // Slow-mo debt plus a long look at the aftermath before the result screen.
  return script.duration + 3.4;
}

// Camera choreography is derived only from the current scripted beat. That
// keeps every cut deterministic in rollback play while allowing each client to
// soften the zoom locally when reduced motion is enabled.
function finisherCinematicCamera(poseZoom = 1.18) {
  const finisher = state.finisher;
  if (!finisher || state.fighters.length !== 2) {
    return {
      x: W * .5,
      y: H * .5,
      zoom: 1,
      shot: "arena",
      intensity: 0,
      focus: "fighters",
      projectileId: null,
    };
  }
  const attacker = state.fighters[finisher.winner];
  const victim = state.fighters[1 - finisher.winner];
  const elapsed = finisher.elapsed;
  const projectile = state.effects.find((effect) => effect.kind === "fatalityProjectile"
    && effect.projectileId === finisher.signatureProjectileId);
  const projectileFocused = Boolean(projectile && finisher.projectileFocusBeats > 0);
  const closestImpact = finisher.script.impacts.reduce((closest, impact) => (
    Math.abs(impact.t - elapsed) < Math.abs(closest.t - elapsed) ? impact : closest
  ), finisher.script.impacts[0]);
  const impactDelta = elapsed - closestImpact.t;
  const inImpactWindow = impactDelta >= -.12 && impactDelta <= .24;
  const inFinalWindow = closestImpact.final && impactDelta >= -.16 && impactDelta <= .46;
  let shot = "pursuit";
  let zoom = Math.max(1.27, poseZoom);
  let intensity = .36;

  if (elapsed < .42) {
    shot = "establishing";
    zoom = Math.max(1.24, poseZoom);
    intensity = .2;
  } else if (inFinalWindow) {
    shot = "final-impact";
    zoom = Math.max(1.62, poseZoom);
    intensity = 1;
  } else if (inImpactWindow) {
    shot = projectileFocused
      ? (projectile.phase === "prime" ? "projectile-prime" : "projectile-trap")
      : "impact-close-up";
    zoom = Math.max(projectileFocused ? 1.5 : 1.43, poseZoom);
    intensity = projectileFocused ? .82 : .72;
  } else if ((finisher.fatalityTriggered || finisher.projectilePhase === "kill") && elapsed > finisher.fatalityAt) {
    shot = "aftermath";
    zoom = Math.max(1.48, poseZoom);
    intensity = .84;
  }

  // Keep the full exchange legible even when a script briefly throws the two
  // bodies apart, then settle the vertical focus onto the victim at impact.
  const separation = Math.abs(attacker.x - victim.x);
  const framingLimit = clamp((W * .72) / Math.max(340, separation), 1.18, 1.68);
  zoom = Math.min(zoom, framingLimit);
  const nominalZoom = zoom;
  if (state.accessibility.reducedMotion) zoom = Math.min(zoom, shot === "final-impact" ? 1.4 : 1.32);
  const midpointY = (attacker.y + victim.y) * .5 - 150;
  const impactY = victim.y - (shot === "final-impact" ? 132 : 145);
  const midpointX = (attacker.x + victim.x) * .5;
  const baseY = inImpactWindow || shot === "aftermath" ? lerp(midpointY, impactY, .68) : midpointY;
  // 2.8 critic round (M3): once the gore aftermath owns the frame the camera
  // favours the BODY — the resting weapon only gets a light pull, so the
  // money shot stays centred on the kill instead of drifting to a prop.
  const goreAftermath = shot === "aftermath" && finisher.fatalityTriggered && state.graphicFatalities;
  const cameraX = projectileFocused && !state.accessibility.reducedMotion
    ? lerp(midpointX, projectile.x, shot === "aftermath" ? (goreAftermath ? .22 : .42) : shot === "final-impact" ? .55 : .72)
    : midpointX;
  const cameraY = projectileFocused && !state.accessibility.reducedMotion
    ? lerp(baseY, projectile.y, shot === "aftermath" ? (goreAftermath ? .2 : .32) : .55)
    : baseY;
  return {
    x: cameraX,
    y: clamp(cameraY, H * .3, H * .59),
    zoom,
    nominalZoom,
    shot,
    intensity,
    focus: projectileFocused ? "projectile" : "fighters",
    projectileId: projectileFocused ? projectile.projectileId : null,
  };
}

// The live aftermath clock: elapsed-based before saturation, then the
// dedicated hold counter (2.8 critic round keystone — see updateFinisher).
function finisherAftermathSeconds(finisher) {
  if (!finisher) return 0;
  return Math.max(
    finisher.fatalityTriggered ? finisher.aftermathSeconds || 0 : 0,
    Math.max(0, finisher.elapsed - finisher.fatalityAt),
  );
}

function fatalityWoundPoint(victim, fatality, direction) {
  const leg = fatality.limb.endsWith("leg");
  const side = fatality.limb.startsWith("left") ? -1 : 1;
  const finisher = state.finisher;
  // Pre-kill (projectile targeting, scripted impacts): the authored
  // standing-pose offsets, exactly as before.
  if (!(finisher?.fatalityTriggered && state.graphicFatalities
    && finisher.elapsed > finisher.fatalityAt)) {
    return {
      x: victim.x + direction * side * (leg ? 18 : 34),
      y: victim.y - (leg ? 58 : 132),
    };
  }
  // 2.8 critic round (M1): during the aftermath the wound anchor is the
  // STUMP AS RENDERED — the same local offset drawFatalityStump draws at,
  // pushed through the victim's live render transform (sprite mirror, then
  // the cinematic rotation the slam scripts use to lay the body down, which
  // also carries the collapse envelope). Spurts, the resting kill object and
  // the spray pump out of the visible wound while the body settles — never
  // out of the standing pose it left a second ago. Pure reads — rollback-safe.
  const size = fighterRenderSize(victim.def.id);
  const pose = fighterAnimationPose(victim);
  const mirror = victim.facing * atlasFrameFacing(victim.def.id, pose.bank, pose.frame);
  const localX = side * direction * size * (leg ? .14 : .22) * mirror;
  const localY = -size * (leg ? .29 : .61);
  const rot = victim.cinematicRotation || 0;
  const cos = Math.cos(rot);
  const sin = Math.sin(rot);
  return {
    x: victim.x + cos * localX - sin * localY,
    y: Math.min(victim.y + sin * localX + cos * localY, FLOOR - 10),
  };
}

function spawnFinisherProjectile(finisher, attacker, victim, fatality) {
  const projectile = getThrowable(attacker.def.finisherScriptId || attacker.def.id);
  if (!projectile || projectile.id !== fatality.projectileId) return;
  const target = fatalityWoundPoint(victim, fatality, finisher.direction);
  const startX = attacker.x + finisher.direction * 58;
  const startY = attacker.y - 142;
  const life = Math.max(1.4, finisher.script.duration - finisher.elapsed + 1.1);
  state.effects = state.effects.filter((effect) => effect.kind !== "fatalityProjectile");
  state.effects.push({
    kind: "fatalityProjectile",
    projectileId: projectile.id,
    name: projectile.name,
    style: projectile.style,
    ownerSide: finisher.winner,
    x: startX,
    y: startY,
    startX,
    startY,
    targetX: target.x,
    targetY: target.y,
    baseWidth: projectile.width * FIGHTER_SCALE * 1.18,
    baseHeight: projectile.height * FIGHTER_SCALE * 1.18,
    width: projectile.width * FIGHTER_SCALE * 1.18,
    height: projectile.height * FIGHTER_SCALE * 1.18,
    vx: finisher.direction * Math.max(320, projectile.speed),
    vy: projectile.launchY || -180,
    spin: projectile.spin || 8,
    spinAngle: 0,
    wobble: projectile.wobble || 0,
    hazard: false,
    landed: false,
    flightProgress: 0,
    phase: "prime",
    focusScale: 1.32,
    direction: finisher.direction,
    life,
    max: life,
    color: attacker.def.accent,
  });
  finisher.signatureProjectileTriggered = true;
  finisher.signatureProjectileId = projectile.id;
  finisher.signatureProjectileName = projectile.name;
}

function focusFinisherProjectile(finisher, attacker, victim, fatality, phase) {
  let projectile = state.effects.find((effect) => effect.kind === "fatalityProjectile"
    && effect.projectileId === fatality.projectileId);
  if (!projectile) {
    spawnFinisherProjectile(finisher, attacker, victim, fatality);
    projectile = state.effects.find((effect) => effect.kind === "fatalityProjectile"
      && effect.projectileId === fatality.projectileId);
  }
  if (!projectile) return;
  const target = fatalityWoundPoint(victim, fatality, finisher.direction);
  projectile.phase = phase;
  projectile.targetX = target.x;
  projectile.targetY = target.y;
  projectile.focusScale = phase === "kill" ? 1.82 : phase === "trap" ? 1.56 : 1.32;
  if (phase === "prime" && !rollbackResimulating) objectSound(projectile.style);
  if (phase !== "prime") {
    projectile.x = target.x;
    projectile.y = target.y;
    projectile.landed = true;
    projectile.hazard = ["wires", "bedbugs"].includes(projectile.style);
    spawnThrowableImpact({ ...projectile, throwable: true }, "impact");
  }
  state.effects.push({
    kind: "projectileFocusBurst",
    projectileId: projectile.projectileId,
    name: projectile.name,
    style: projectile.style,
    phase,
    x: phase === "prime" ? projectile.x : target.x,
    y: phase === "prime" ? projectile.y : target.y,
    direction: finisher.direction,
    // 2.8 critic round (M3): with gore ON the kill burst collapses inside
    // ~33 ticks so the arterial systole window is readable; gore-off keeps
    // the long burst because it carries the whole kill read there.
    life: phase === "kill" ? (state.graphicFatalities ? .55 : 1.35) : .72,
    max: phase === "kill" ? (state.graphicFatalities ? .55 : 1.35) : .72,
    color: attacker.def.accent,
  });
  finisher.projectilePhase = phase;
  finisher.projectileFocusBeats += 1;
  finisher.projectileFocusBursts += 1;
  finisher.projectileBeatLabels.push(phase === "prime"
    ? fatality.projectileSetup
    : phase === "trap" ? fatality.projectileAction : fatality.projectileFinale);
}

// ---------------------------------------------------------------------------
// 2.8 FATALITY REALISM — gore audio wrapper, budgeted mist, and the
// per-fighter signature beats. Data + envelopes live in engine/gore.mjs.
// ---------------------------------------------------------------------------

// Monotonic one-shot counters on the elementFxDebug pattern, exposed via
// snapshot().violence for smoke probes.
const goreFxDebug = {
  signatureBeats: 0, goreSfxPlays: 0, mistPuffs: 0, wallStains: 0, smears: 0,
};

// Per-cue rate caps (manifest minMs) so pump peaks never stack the layer.
const goreSfxLast = new Map();

// 2.8 critic round (M2): monotonic spawn serial so a full stain budget
// recycles its OLDEST decal instead of refusing the spawn — during the
// frozen-life fatality hold nothing expires on its own, and the aftermath
// must keep accumulating paint until scene teardown. Render-side only.
let goreDecalSerial = 0;

// Spawn a bloodDecal, or recycle the oldest decal of the same class when the
// budget is full. `sameClass` picks the pool the decal competes in (floor
// stain / wall stain / smear) so flags never leak across classes.
function pushBloodDecal(decal, sameClass) {
  const budget = stainBudget(state.effects);
  const room = decal.smear ? canSpawnSmear(budget)
    : decal.wall ? canSpawnWallStain(budget)
      : canSpawnFloorStain(budget);
  if (room) {
    state.effects.push({ kind: "bloodDecal", age: 0, serial: goreDecalSerial += 1, ...decal });
    return true;
  }
  let oldest = null;
  for (const effect of state.effects) {
    if (effect.kind !== "bloodDecal" || !sameClass(effect)) continue;
    if (!oldest || (effect.serial || 0) < (oldest.serial || 0)) oldest = effect;
  }
  if (!oldest) return false;
  for (const key of Object.keys(decal)) oldest[key] = decal[key];
  oldest.age = 0;
  oldest.serial = goreDecalSerial += 1;
  return true;
}

// 2.8 critic round (S3): which stages actually SHOW a wall surface at the
// arena bounds. The buffet interior and the cruise pool deck read as open
// space at the movement limits, so wall spatter there hung mid-air — those
// droplets convert to extra floor stains at the bound instead.
const STAGE_WALL_SURFACES = Object.freeze({
  somerset: true, vet: true, wildwood: true, buffet: false, cruise: false, janney: true,
});

function goreSfx(kind, fighter = null) {
  if (rollbackResimulating || !state.graphicFatalities) return;
  const meta = GORE_SFX[kind];
  if (!meta) return;
  if (!$("#soundToggle").checked) return;
  const now = performance.now();
  if (now - (goreSfxLast.get(kind) || -Infinity) < meta.minMs) return;
  goreSfxLast.set(kind, now);
  sound(kind, fighter);
  goreFxDebug.goreSfxPlays += 1;
}

// Aerosol blood mist / steam / ash: capped soft particles that billow and
// rise a hair. Colour comes from the spawner so the same particle carries
// benny's steam and devil's ash. Checksum-exempt array, visualRandom only.
function spawnGoreMist(x, y, count, scale = 1, color = "#6b050c", rise = 1) {
  if (!state.graphicFatalities) return;
  let mist = 0;
  for (const particle of state.particles) if (particle.kind === "mist") mist += 1;
  const room = Math.max(0, GORE_BUDGETS.mist - mist);
  const spawn = Math.min(room, Math.max(1, Math.round(count * state.performance.particleScale)));
  for (let index = 0; index < spawn; index += 1) {
    state.particles.push({
      kind: "mist",
      x: x + (visualRandom() - 0.5) * 46 * scale,
      y: y + (visualRandom() - 0.5) * 30 * scale,
      vx: (visualRandom() - 0.5) * 70,
      vy: -(6 + visualRandom() * 26) * rise,
      gravity: -14 * rise, drag: 0.965,
      life: 0.8 + visualRandom() * 0.9, max: 1.7,
      size: (11 + visualRandom() * 17) * scale,
      color,
    });
  }
  goreFxDebug.mistPuffs += spawn;
}

// The killing blow's bespoke per-fighter beat (SIGNATURE_GORE selects the
// path). Everything lands in the checksum-exempt arrays with visualRandom,
// inside the same finalImpact+gore gate as the rest of the fatality dressing.
function spawnSignatureGoreBeat(scriptId, fatality, x, y, direction) {
  const sig = signatureGore(scriptId);
  const scale = state.performance.particleScale;
  goreFxDebug.signatureBeats += 1;
  if (sig.slamRing) {
    // Seismic: the slam answers in the ground — a low blood shock ring.
    state.effects.push({
      kind: "goreShockwave", family: "crush", direction,
      x, y: FLOOR - 6, life: 1.05, max: 1.05,
      color: bloodTint(fatality.palette[0]), secondary: bloodTint(fatality.palette[1]), scale: 0.8,
    });
  }
  if (sig.boneScale) {
    // Heavier bone-chip fountain out of the crush point.
    const chips = Math.max(4, Math.round(7 * sig.boneScale * scale));
    for (let index = 0; index < chips; index += 1) {
      const angle = -Math.PI * (0.2 + visualRandom() * 0.6);
      const speed = 260 + visualRandom() * 520;
      state.particles.push({
        kind: "goreFragment", bone: true,
        x: x + (visualRandom() - 0.5) * 30, y: y + (visualRandom() - 0.5) * 30,
        vx: Math.cos(angle) * speed * (visualRandom() > 0.5 ? 1 : -1),
        vy: Math.sin(angle) * speed - 60,
        gravity: 980, drag: 0.982,
        rotation: visualRandom() * Math.PI * 2, spin: (visualRandom() - 0.5) * 16,
        spikes: 4 + index % 3,
        life: 0.9 + visualRandom() * 1.2, max: 2.1,
        size: 4 + visualRandom() * 7,
        color: index % 3 ? "#e6d3b3" : bloodTint(fatality.palette[1]),
      });
    }
  }
  if (sig.verdict) {
    // Contract: a tight, precise seal-burst — ten exact rays of deep red.
    for (let ray = 0; ray < 10; ray += 1) {
      const angle = -Math.PI * 0.5 + (ray - 4.5) * 0.3;
      const speed = 420 + (ray % 3) * 120;
      state.particles.push({
        kind: "sparkLine",
        x, y,
        vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
        gravity: 760, drag: 0.96,
        life: 0.22 + visualRandom() * 0.14, max: 0.36,
        size: 2 + ray % 3,
        color: ray % 4 ? bloodTint(fatality.palette[0]) : "#ff3b4e",
      });
    }
  }
  if (sig.glitchBits) {
    // Glitch: quantised signal-green debris tumbling with the fragments.
    const bits = Math.max(6, Math.round(10 * scale));
    for (let index = 0; index < bits; index += 1) {
      const angle = Math.round(visualRandom() * 8) * (Math.PI / 4);
      const speed = 180 + Math.round(visualRandom() * 3) * 140;
      state.particles.push({
        kind: "debris",
        x: x + (Math.round(visualRandom() * 4) - 2) * 14,
        y: y + (Math.round(visualRandom() * 4) - 2) * 14,
        vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed - 120,
        gravity: 900, drag: 0.98,
        rotation: Math.round(visualRandom() * 4) * (Math.PI / 2), spin: 0,
        life: 0.5 + visualRandom() * 0.7, max: 1.2,
        size: 3 + Math.round(visualRandom() * 3) * 2,
        color: index % 3 ? sig.glitchColor : bloodTint(fatality.palette[0]),
      });
    }
  }
  if (sig.gushScale) {
    // Concrete crush: thick, slow gouts that fall close and pool fast.
    const gouts = Math.max(5, Math.round(9 * scale));
    for (let index = 0; index < gouts; index += 1) {
      const angle = -Math.PI * (0.25 + visualRandom() * 0.5);
      const speed = (110 + visualRandom() * 220) * 0.9;
      state.particles.push({
        kind: "blood",
        x: x + (visualRandom() - 0.5) * 26, y: y + (visualRandom() - 0.5) * 26,
        vx: Math.cos(angle) * speed * (visualRandom() > 0.5 ? 1 : -1),
        vy: Math.sin(angle) * speed,
        gravity: 1240, drag: 0.988,
        life: 0.8 + visualRandom() * 0.9, max: 1.7,
        size: (6 + visualRandom() * 8) * (sig.dropletScale || 1),
        color: index % 3 ? bloodTint(fatality.palette[0]) : bloodTint(fatality.palette[1]),
      });
    }
  }
  if (sig.mistScale) spawnGoreMist(x, y, Math.round(6 * sig.mistScale), 1.25);
}

function triggerFinisherImpact(finisher, impact) {
  const attacker = state.fighters[finisher.winner];
  const victim = state.fighters[1 - finisher.winner];
  const finalImpact = Boolean(impact.final);
  const gore = state.graphicFatalities;
  const scriptId = attacker.def.finisherScriptId || attacker.def.id;
  const fatalityProfile = getGraphicFatality(scriptId, finisher.type);
  const fatality = finalImpact && gore ? fatalityProfile : null;
  const wound = impact.projectilePhase
    ? fatalityWoundPoint(victim, fatalityProfile, finisher.direction)
    : { x: victim.x - finisher.direction * 12, y: victim.y - 125 };
  const pointX = wound.x;
  const pointY = wound.y;
  const count = Math.round((finalImpact ? 52 : 12) * impact.power * (gore ? 1.35 : 1));

  victim.hitFlash = finalImpact ? .22 : .11;
  attacker.specialGlow = finalImpact ? 1.1 : .45;
  // The long final-frame hold reads as time dilation without changing the
  // authored pose timeline or introducing a second simulation clock.
  state.hitstop = Math.max(state.hitstop, finalImpact ? .26 : .055 + impact.power * .032);
  state.shake = Math.max(state.shake, finalImpact ? 1.1 : .16 + impact.power * .22);
  if (finalImpact && $("#flashToggle").checked) state.flash = .34;
  // Wave 7: the killing blow tears the screen — distortion ring from the
  // impact point plus a short RGB-split impulse (render-only latches).
  if (finalImpact) latchFatalImpactPresentation(pointX, pointY);
  finisher.beatLabel = impact.label;
  finisher.beatLife = finalImpact ? 1.05 : .48;
  finisher.impactCloseUps += 1;
  if (finalImpact) finisher.slowMotionHits += 1;
  if (impact.projectilePhase) {
    focusFinisherProjectile(finisher, attacker, victim, fatalityProfile, impact.projectilePhase);
  }
  // Release 1.6 LOUD: synth heft under the scripted cinematic impacts too.
  impactLayerAudio(finalImpact ? "super" : "heavy", { counter: false });
  // Wave 9: the victim's fatality scream on the killing blow — a distinct
  // cue from the shared ko bell (guarded + tick-deduped inside).
  if (finalImpact) fighterReactiveCue(victim, "scream");

  for (let index = 0; index < count; index += 1) {
    const angle = visualRandom() * Math.PI * 2;
    const speed = 100 + visualRandom() * (finalImpact ? 670 : 330) * impact.power;
    const splatter = finalImpact && gore && visualRandom() > .34;
    state.particles.push({
      kind: finalImpact && gore ? "blood" : "impact",
      x: pointX,
      y: pointY,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed - (finalImpact ? 150 : 35),
      life: (finalImpact ? .65 : .22) + visualRandom() * (finalImpact ? 1.15 : .42),
      max: finalImpact ? 1.8 : .64,
      size: 2 + visualRandom() * (finalImpact ? 8 : 5),
      color: finalImpact && gore
        ? splatter ? "#d90b19" : visualRandom() > .45 ? "#a50713" : "#e32632"
        : visualRandom() > .4 ? attacker.def.accent : "#fff0df",
    });
  }

  state.effects.push({
    kind: "finisherImpact",
    style: attacker.def.vfx,
    variant: finisher.type,
    final: finalImpact,
    power: impact.power,
    direction: finisher.direction,
    x: pointX,
    y: pointY,
    life: finalImpact ? 1.2 : .55,
    max: finalImpact ? 1.2 : .55,
    color: attacker.def.accent,
    secondary: attacker.def.color,
  });
  if (finalImpact && gore) {
    finisher.fatalityTriggered = true;
    // 2.8 critic round (S1): everything blood-classed spawns in the arterial
    // red family — fighter palettes only flavour signature emitters and copy.
    const bloodBright = bloodTint(fatality.palette[0]);
    const bloodDeep = bloodTint(fatality.palette[1]);
    // Time dilation for the killing blow, then a pumping wound. Both are plain
    // numbers on the finisher, so rollback snapshots reproduce them exactly.
    finisher.slowMotionTicks = 42;
    finisher.arterialFrames = ARTERIAL_FRAMES;
    finisher.fatalityLimb = fatality.limb;
    finisher.fatalitySpecial = fatality.special;
    finisher.beatLabel = fatality.projectileFinale;
    finisher.beatLife = 1.45;
    // 2.8: the fatality decals (pool, lens blood, severed limb) must survive
    // the whole cinematic hold INCLUDING the longer pressure-model bleed-out —
    // a pool vanishing while the wound still pumps read as a glitch.
    const decalLife = Math.max(1.4, finisher.script.duration - finisher.elapsed + 4.2);
    state.effects.push({
      kind: "fatalityPool",
      profileId: fatality.id,
      family: fatality.family,
      x: victim.x,
      y: FLOOR + 4,
      age: 0,
      life: decalLife,
      max: decalLife,
      color: bloodBright,
      secondary: bloodDeep,
      direction: finisher.direction,
      scale: fatality.blood,
    });
    const goreCount = Math.round(42 * fatality.blood * state.performance.particleScale);
    for (let index = 0; index < goreCount; index += 1) {
      const angle = -Math.PI * (.12 + visualRandom() * .76);
      const speed = 180 + visualRandom() * 620 * fatality.separation;
      state.particles.push({
        kind: "blood",
        x: pointX + (visualRandom() - .5) * 34,
        y: pointY + (visualRandom() - .5) * 42,
        vx: Math.cos(angle) * speed * (visualRandom() > .5 ? 1 : -1),
        vy: Math.sin(angle) * speed,
        life: .75 + visualRandom() * 1.4,
        max: 2.15,
        size: 3 + visualRandom() * 9,
        color: visualRandom() > .28 ? bloodBright : bloodDeep,
      });
    }
    const fragmentCount = Math.max(12, Math.round(30 * fatality.separation * state.performance.particleScale));
    for (let index = 0; index < fragmentCount; index += 1) {
      const angle = -Math.PI * (.08 + visualRandom() * .84);
      const speed = 230 + visualRandom() * 760 * fatality.separation;
      state.particles.push({
        kind: "goreFragment",
        x: pointX + (visualRandom() - .5) * 46,
        y: pointY + (visualRandom() - .5) * 56,
        vx: Math.cos(angle) * speed * (visualRandom() > .5 ? 1 : -1),
        vy: Math.sin(angle) * speed - 45,
        gravity: 940,
        drag: .981,
        rotation: visualRandom() * Math.PI * 2,
        spin: (visualRandom() - .5) * 18,
        spikes: 5 + index % 4,
        bone: index % 6 === 0,
        life: 1 + visualRandom() * 1.5,
        max: 2.5,
        size: 6 + visualRandom() * 13,
        color: index % 4 ? bloodBright : bloodDeep,
      });
    }
    state.effects.push({
      kind: "goreShockwave",
      family: fatality.family,
      direction: finisher.direction,
      x: pointX,
      y: pointY,
      life: 1.45,
      max: 1.45,
      color: bloodBright,
      secondary: bloodDeep,
      scale: fatality.separation,
    });
    state.effects.push({
      kind: "lensBlood",
      family: fatality.family,
      variant: finisher.type,
      x: pointX,
      y: pointY,
      life: decalLife,
      max: decalLife,
      color: bloodBright,
      secondary: bloodDeep,
      scale: fatality.blood,
    });
    // One unmistakable complete limb, not an abstract meat fragment. It arcs
    // out of the signature-special impact, bounces once, and stays in the
    // aftermath beside its own blood trail for the full cinematic hold.
    state.effects.push({
      kind: "severedLimb",
      profileId: fatality.id,
      limb: fatality.limb,
      special: fatality.special,
      device: fatality.device,
      x: pointX,
      y: pointY,
      vx: finisher.direction * (240 + visualRandom() * 190),
      vy: -(390 + visualRandom() * 170),
      gravity: 1080,
      drag: .988,
      rotation: visualRandom() * Math.PI * 2,
      spin: finisher.direction * (7 + visualRandom() * 7),
      resting: false,
      bounced: false,
      life: decalLife,
      max: decalLife,
      color: bloodBright,
      secondary: bloodDeep,
      clothColor: victim.def.color,
      clothAccent: victim.def.accent,
      direction: finisher.direction,
    });
    // 2.8: impact aerosol — heavy hits throw a low blood mist that hangs.
    spawnGoreMist(pointX, pointY, 7 + Math.round(5 * fatality.blood), 1.2);
    // 2.8: the fighter's bespoke signature gore beat (engine/gore.mjs table).
    spawnSignatureGoreBeat(scriptId, fatality, pointX, pointY, finisher.direction);
    // 2.8 gore audio: wet tear + bone report layered under the 'fatal' hit.
    goreSfx("gore-squelch", victim);
    goreSfx("gore-bone");
  }
  sound(finalImpact ? "fatal" : impact.sound, attacker);
}

function updateFinisher(dt) {
  const finisher = state.finisher;
  if (!finisher) return;
  const attacker = state.fighters[finisher.winner];
  const victim = state.fighters[1 - finisher.winner];
  const slowMo = (finisher.slowMotionTicks || 0) > 0;
  if (slowMo) finisher.slowMotionTicks -= 1;
  finisher.elapsed = Math.min(finisher.script.duration, finisher.elapsed + dt * (slowMo ? 0.38 : 1));
  // 2.8 critic round (M1/M3/M6 keystone): finisher.elapsed SATURATES at the
  // script duration, so every aftermath derived from it froze ~0.5s after
  // the killing blow — scattered pieces hung mid-flight, the collapse
  // envelope never slumped, and the title card never moved. This clock keeps
  // counting through the whole cinematic hold (same timescale as elapsed, a
  // plain snapshotted number, so rollback replays it exactly).
  if (finisher.fatalityTriggered) {
    finisher.aftermathSeconds = (finisher.aftermathSeconds || 0) + dt * (slowMo ? 0.38 : 1);
  }
  finisher.beatLife = Math.max(0, finisher.beatLife - dt);
  const pose = sampleFinisher(finisher.script.keys, finisher.elapsed);

  attacker.x = finisher.anchor + finisher.direction * pose.ax;
  attacker.y = FLOOR - pose.ay;
  victim.x = finisher.anchor + finisher.direction * pose.vx;
  victim.y = FLOOR - pose.vy;
  attacker.facing = victim.x >= attacker.x ? 1 : -1;
  victim.facing = -attacker.facing;
  // Keep the pair axis tracking the cinematic so the fighters stay oriented
  // through a script that walks them past each other, and so anything that
  // resumes after the finisher inherits the correct side.
  state.facingAxis = state.fighters[0].facing;
  attacker.grounded = pose.ay < 2;
  victim.grounded = pose.vy < 2;
  attacker.cinematicFrame = pose.af;
  victim.cinematicFrame = pose.vf;
  attacker.cinematicRotation = pose.ar * finisher.direction;
  victim.cinematicRotation = pose.vr * finisher.direction;
  const fatalityProfile = getGraphicFatality(attacker.def.finisherScriptId || attacker.def.id, finisher.type);
  const projectileTarget = fatalityWoundPoint(victim, fatalityProfile, finisher.direction);
  const killResting = finisher.fatalityTriggered && state.graphicFatalities;
  for (const effect of state.effects) {
    if (effect.kind !== "fatalityProjectile") continue;
    if (killResting) {
      // 2.8 critic round (M3): after the killing blow the giant signature
      // sigil stops parking over the victim — it shrinks toward the impact
      // point and comes to rest on the street beside the body (still in the
      // scene through the whole aftermath, just no longer a billboard). The
      // rest point stays within 130px of the body so the aftermath camera,
      // which tracks the weapon, never drags framing off the fight.
      effect.targetX = victim.x
        + clamp(projectileTarget.x + finisher.direction * 46 - victim.x, -130, 130);
      effect.targetY = FLOOR - Math.max(10, (effect.baseHeight || 40) * 0.16);
    } else {
      effect.targetX = projectileTarget.x;
      effect.targetY = projectileTarget.y;
    }
  }
  if (finisher.fatalityTriggered && state.graphicFatalities && !state.accessibility.reducedMotion
    && finisher.elapsed > finisher.fatalityAt) {
    const aftermath = finisherAftermathSeconds(finisher);
    // 2.8 collapse weight (engine/gore.mjs): a half-second beat of stillness,
    // then the joints unload into an eased slump layered on the authored
    // pose; spasms arrive in bursts that space out and decay quadratically
    // to TRUE stillness — no residual buzz on the settled body.
    const env = collapseEnvelope(aftermath, state.simulationTick);
    victim.cinematicRotation += env.slump * 0.085 * finisher.direction
      + env.twitch * 0.055;
    // The settle lands with a heavy body-drop cue exactly once (plain flag on
    // the snapshotted finisher; goreSfx carries the resim guard).
    if (!finisher.bodyDropPlayed && env.slump >= 1 && (victim.grounded || aftermath > 1.6)) {
      finisher.bodyDropPlayed = true;
      goreSfx("gore-body-drop");
    }
    // 2.8 smearing: a body dragged/sliding through the aftermath pulls an
    // elongated streak out of nearby blood instead of leaving it pristine.
    // Scripted drags are eased, so the slide ACCUMULATES: every ~18px of
    // grounded movement through the gore field leaves one streak.
    // 2.8 critic round (S4): the accumulator never hard-resets on a slow
    // tick — eased scripted drags move well under the old 0.45px/tick floor,
    // which is why probes saw zero body smears. Every ~9px of grounded slide
    // through the gore field now leaves a pair of streaks along the path.
    if (finisher.smearX === undefined) finisher.smearX = victim.x;
    const slide = victim.x - finisher.smearX;
    finisher.smearX = victim.x;
    if (Math.abs(slide) > 0.12 && victim.grounded) {
      finisher.smearAccum = (finisher.smearAccum || 0) + Math.abs(slide);
    }
    if ((finisher.smearAccum || 0) >= 9) {
      finisher.smearAccum = 0;
      const nearBlood = state.effects.some((effect) => (effect.kind === "fatalityPool"
        || (effect.kind === "bloodDecal" && effect.stain && !effect.wall))
        && Math.abs(effect.x - victim.x) < 260);
      if (nearBlood) {
        const smearDirection = Math.sign(slide) || 1;
        for (let streak = 0; streak < 2; streak += 1) {
          const smearLife = 3 + visualRandom() * 2;
          pushBloodDecal({
            smear: true,
            x: victim.x - smearDirection * (14 + streak * 26 + visualRandom() * 10),
            y: FLOOR + 3,
            width: 46 + visualRandom() * 44,
            direction: smearDirection,
            life: smearLife, max: smearLife, color: "#5c040b",
          }, (effect) => effect.smear);
          goreFxDebug.smears += 1;
        }
      }
    }
  }
  attacker.specialGlow = Math.max(attacker.specialGlow, .28 + Math.sin(finisher.elapsed * 9) * .08);
  attacker.block = false;
  victim.block = false;
  attacker.crouch = false;
  victim.crouch = false;
  const cinematic = finisherCinematicCamera(pose.zoom);
  if (cinematic.shot !== finisher.cinematicShot) {
    finisher.cinematicShot = cinematic.shot;
    finisher.cinematicCuts += 1;
  }
  finisher.peakZoom = Math.max(finisher.peakZoom, cinematic.nominalZoom);
  state.cinematicZoom = cinematic.zoom;

  while (finisher.impactIndex < finisher.script.impacts.length
    && finisher.script.impacts[finisher.impactIndex].t <= finisher.elapsed) {
    triggerFinisherImpact(finisher, finisher.script.impacts[finisher.impactIndex]);
    finisher.impactIndex += 1;
  }

  // Arterial spray: the wound pumps on a heartbeat for ~2.6 seconds after the
  // killing blow. Droplets arc away from the attacker, and each one that lands
  // becomes a floor stain plus a small splash back up.
  if (finisher.fatalityTriggered && state.graphicFatalities && (finisher.arterialFrames || 0) > 0) {
    finisher.arterialFrames -= 1;
    // 2.8: pressure-based spurts (engine/gore.mjs) — the heartbeat slows and
    // peak pressure decays as the supply drains, so the wound collapses from
    // fast regular arcs into a weak dribble instead of pumping flat.
    const ap = arterialPressure(finisher.arterialFrames, ARTERIAL_FRAMES);
    // Wave 15: one haptic lub-dub per systolic peak. Module-level tick latch
    // on the wallSplatLastTick pattern; combatHaptic carries the
    // rollbackResimulating guard, and the 2.8 arterial hiss rides the same
    // latch (goreSfx adds its own rate cap on top).
    if (ap.peak && state.simulationTick - lastHeartbeatHapticTick > 12) {
      lastHeartbeatHapticTick = state.simulationTick;
      combatHaptic("fatalityHeartbeat");
      goreSfx("gore-arterial", victim);
    }
    const scriptId = attacker.def.finisherScriptId || attacker.def.id;
    const fatality = getGraphicFatality(scriptId, finisher.type);
    const sig = signatureGore(scriptId);
    const wound = fatalityWoundPoint(victim, fatality, finisher.direction);
    const speedMul = sig.gushScale ? 0.78 : 1;
    const sizeMul = sig.dropletScale || 1;
    if (state.simulationTick % 2 === 0 && ap.strength > 0.03) {
      const jets = 1 + (ap.pulse > 0.72 ? 1 : 0)
        + (state.performance.particleScale >= 1 && ap.pressure > 0.45 ? 1 : 0);
      for (let jet = 0; jet < jets; jet += 1) {
        const vr = visualRandom();
        // Post's paint kit marbles the spray with the attacker's accent.
        const marbled = sig.marbling && visualRandom() < 0.3;
        state.particles.push({
          kind: "arterial",
          x: wound.x + (visualRandom() - .5) * 8,
          y: wound.y + (visualRandom() - .5) * 7,
          vx: finisher.direction * (90 + vr * 430) * (0.3 + ap.strength * 0.9) * speedMul
            + (visualRandom() - 0.5) * 90,
          vy: -(150 + visualRandom() * 470) * (0.35 + ap.strength * 0.85) * speedMul,
          gravity: 1150, drag: 0.985,
          life: 1.5, max: 1.5,
          size: (1.7 + visualRandom() * (2 + ap.pressure * 1.7)) * sizeMul,
          color: marbled ? attacker.def.accent : vr > 0.4 ? "#a50713" : "#d90b19",
        });
      }
    }
    // 2.8 per-fighter aftermath dressing on the same pump clock — every
    // emitter is short-lived and in motion (never a static decal spark).
    if (sig.emberColor && state.simulationTick % 3 === 0 && visualRandom() < (sig.emberRate || 0.5)) {
      state.particles.push({
        kind: "sparkLine",
        x: wound.x + (visualRandom() - 0.5) * 12, y: wound.y + (visualRandom() - 0.5) * 12,
        vx: (visualRandom() - 0.5) * 220, vy: -(40 + visualRandom() * 160),
        gravity: 420, drag: 0.95,
        life: 0.14 + visualRandom() * 0.16, max: 0.3,
        size: 1.2 + visualRandom() * 1.6, color: sig.emberColor,
      });
    }
    if (sig.arcs && ap.peak && state.simulationTick % 2 === 0) {
      for (let arc = 0; arc < 3; arc += 1) {
        const angle = visualRandom() * Math.PI * 2;
        const speed = 260 + visualRandom() * 340;
        state.particles.push({
          kind: "sparkLine",
          x: wound.x, y: wound.y,
          vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
          gravity: 180, drag: 0.9,
          life: 0.1 + visualRandom() * 0.12, max: 0.22,
          size: 1.6 + visualRandom() * 2, color: sig.arcColor,
        });
      }
      if (sig.steam) spawnGoreMist(wound.x, wound.y - 8, 2, 0.7, "#cfd8de", 1.7);
    }
    if (sig.ash && state.simulationTick % 5 === 0 && ap.reserve > 0.1) {
      spawnGoreMist(wound.x, wound.y, 1, 0.45, sig.ashColor, 2.1);
    }
    if (sig.fleckColor && state.simulationTick % 4 === 0 && visualRandom() < (sig.fleckRate || 0.4)) {
      state.particles.push({
        kind: "sparkLine",
        x: wound.x + (visualRandom() - 0.5) * 10, y: wound.y + (visualRandom() - 0.5) * 10,
        vx: finisher.direction * (60 + visualRandom() * 260) * ap.strength,
        vy: -(80 + visualRandom() * 260) * ap.strength,
        gravity: 1050, drag: 0.98,
        life: 0.3 + visualRandom() * 0.3, max: 0.6,
        size: 1 + visualRandom() * 1.4, color: sig.fleckColor,
      });
    }
    if (sig.poolRipples && ap.peak && state.simulationTick % 2 === 0) {
      const pool = state.effects.find((effect) => effect.kind === "fatalityPool");
      if (pool) {
        state.effects.push({
          kind: "shockRing", x: pool.x, y: pool.y - 2, size: 64,
          life: 0.4, max: 0.4, color: bloodTint(fatality.palette[0]),
        });
      }
    }
    // Heavy peaks atomise a little extra mist while pressure is high.
    if (ap.peak && ap.pressure > 0.5 && state.simulationTick % 4 === 0) {
      spawnGoreMist(wound.x, wound.y, 2, 0.8);
    }
    // Late bleed-out: the spray gives way to a slow drip tail by ear too.
    if (ap.pressure < 0.22 && state.simulationTick % 96 === 0) goreSfx("gore-drip");
  }
}

// ---------------------------------------------------------------------------
// Wave 16 — context win quotes. The pools and the pure selector live in
// engine/fighter-kits.mjs; this side supplies the CONTEXT (all states the
// result path already knows) plus the visualRandom roll and the per-fighter
// no-repeat memory. lastWinQuoteSelection is exposed for QA probes.
// ---------------------------------------------------------------------------
const lastWinQuoteKeys = new Map();
let lastWinQuoteSelection = null;

function selectResultQuote(winner, def) {
  const loserDef = state.fighters[1 - winner]?.def;
  const winnerId = def.kitId || def.id;
  const loserId = loserDef ? loserDef.kitId || loserDef.id : "";
  const context = {
    fatality: state.finisherType >= 0,
    flawless: (state.fighters[winner]?.health ?? 0) >= 100,
    comeback: state.finisherType < 0 && (voiceRoundMinHealth[winner] ?? 100) <= 15,
    boss: loserId === ARCADE_BOSS_ID && winnerId !== ARCADE_BOSS_ID,
    rival: Boolean(loserId) && ARCADE_RIVALS[winnerId] === loserId,
    mirror: Boolean(loserId) && loserId === winnerId,
  };
  const selection = selectWinQuote(winnerId, context, visualRandom(), lastWinQuoteKeys.get(winnerId) || "");
  if (!selection) return "";
  lastWinQuoteKeys.set(winnerId, selection.key);
  lastWinQuoteSelection = { fighterId: winnerId, ...selection, context };
  modeFxDebug.winQuoteSelections += 1;
  return selection.text;
}

function showResult(winner) {
  state.phase = "result";
  state.finisher = null;
  state.cinematicZoom = 1;
  updateFlowSkipHint();
  const def = state.fighters[winner].def;
  const kit = getFighterKit(def.kitId || def.id);
  const dailyOver = dailySession.active && dailySession.finished;
  const arcadeDefeat = state.mode === "arcade" && winner === 1 && state.arcadeRun && !dailyOver;
  const survivalOver = state.mode === "survival" && state.survivalRun?.over;
  const teamOver = state.mode === "team" && state.teamBattle?.over;
  $("#resultEyebrow").textContent = state.mode === "demo" ? `WATCH DEMO · CYCLE ${demoSession.cycle?.cycle || 1}`
    : survivalOver ? "THE GAUNTLET · RUN ENDED"
      : teamOver ? "BLOCK WAR · 3V3 SETTLED"
        : dailyOver ? "THE DAILY JAWN · ONE SHOT A DAY"
          : arcadeDefeat ? "ARCADE RUN INTERRUPTED" : "MATCH COMPLETE";
  $("#resultTitle").textContent = teamOver ? `TEAM P${state.teamBattle.winnerSide + 1} WINS` : `${def.name} WINS`;
  $("#resultFinisher").textContent = survivalOver
    ? `${state.survivalRun.wins} WINS · ${Math.round(scoreSession.total).toLocaleString("en-US")} PTS · BEST ${survivalBestSummary().streak}`
    : teamOver
      ? `${def.name} HOLDS THE BLOCK · ${teamFightersRemaining(state.teamBattle, state.teamBattle.winnerSide)} STILL STANDING`
      : dailyOver
        ? `${dailySession.outcome?.cleared ? "CLEARED" : "RUN OVER"} · ${Math.round(scoreSession.total).toLocaleString("en-US")} PTS`
        : arcadeDefeat
          ? `${currentArcadeMatch(state.arcadeRun)?.label || "BOUT"} · CONTINUE?`
          : state.finisherType >= 0 ? def.finishers[state.finisherType] : "KNOCKOUT";
  const victoryPose = $("#victoryPose");
  victoryPose.classList.toggle("portrait-art", !kit || def.boss || def.secret);
  victoryPose.style.backgroundImage = kit && !def.boss && !def.secret
    ? `url("${posesSheetUrl(def)}")`
    : `url("assets/fighters/${def.id}.webp")`;
  // Wave 16: context-aware win quote — pool keyed to HOW the match was won,
  // rotated no-repeat via visualRandom (presentation stream only).
  $("#resultQuote").textContent = selectResultQuote(winner, def)
    || def.victoryQuote || kit?.victory.quote || "PHILLY REMEMBERS THE WINNER.";
  $("#rematchButton").textContent = survivalOver ? "NEW GAUNTLET RUN"
    : teamOver ? "REMATCH · SAME TEAMS"
      : dailyOver ? "BACK TO TITLE"
        : arcadeDefeat ? "CONTINUE" : state.mode === "online" ? "REQUEST REMATCH" : "INSTANT REMATCH";
  $("#reselectButton").textContent = arcadeDefeat ? "ABANDON RUN"
    : state.mode === "online" ? "LEAVE ROOM" : "SELECT FIGHTERS";
  $("#newStageButton").hidden = state.mode !== "versus";
  renderResultRecap();
  updateDailyBanners();
  showScreen("result");
  // Victory entrance: pose rises from the bottom edge, the WINS title slams
  // in with a scale-settle, the finisher name stamps down last, and a light
  // sweep passes across the copy panel. One-shot per match end; all classes
  // are flattened by body.reduced-motion into static end states.
  restartCssAnimation(victoryPose, "enter");
  restartCssAnimation($("#resultTitle"), "enter");
  restartCssAnimation($("#resultFinisher"), "enter");
  restartCssAnimation($(".result-copy"), "sweep");
  hudFxDebug.victoryEntrances += 1;
  if (state.mode === "demo") scheduleNextDemoMatch();
  else $("#demoResultStatus").hidden = true;
  // R2.1 STREETS: winner-stays scoreboard card (online rooms + offline versus
  // sets) and the CHANGE FIGHTERS path back to a QoL-speaking lobby.
  renderSetScoreCard();
  $("#changeFightersButton").hidden = !(state.mode === "online" && onlineSession.lobby.remoteQol >= 1);
  if (state.mode === "online") {
    onlineSession.rematchVotes.clear();
    updateOnlineRematchUi();
    persistOnlineResume(true);
  }
  // Wave 19: a decided PHILLY OPEN match reuses this whole victory treatment,
  // then routes back to the bracket — the loop buttons make no sense here.
  const bracketOutcome = bracketSession.lastOutcome;
  $("#bracketContinueButton").hidden = !bracketOutcome;
  if (bracketOutcome) {
    $("#resultEyebrow").textContent = bracketOutcome.complete
      ? "THE PHILLY OPEN · CHAMPIONSHIP DECIDED"
      : `THE PHILLY OPEN · ${bracketOutcome.roundName}`;
    $("#bracketContinueButton").textContent = bracketOutcome.complete
      ? "CROWN THE CHAMPION →"
      : "BACK TO THE BRACKET →";
    $("#rematchButton").hidden = true;
    $("#newStageButton").hidden = true;
    $("#reselectButton").hidden = true;
    $("#changeFightersButton").hidden = true;
  } else {
    $("#rematchButton").hidden = false;
    $("#reselectButton").hidden = false;
  }
}

// 5.3 (sweep #30): the two coaching lines under the win quote. The recap is
// the fight's own damage attribution — the biggest single source of the health
// the player lost — and the coach card is the lesson that answers it. Both are
// suppressed wherever the digest is not the player's own fight: demo, replay,
// tournament, online, and the CPU-in-seat-0 flows the records fold already
// refuses. The digest folds at progressionMatchEnd, which runs BEFORE
// showResult on every match-end path, so this reads the sealed match.
function renderResultRecap() {
  const recap = $("#resultRecap");
  const digest = lastFightDigest;
  const eligible = !replayPlayback.active
    && !demoSession.active
    && !["demo", "tournament", "online"].includes(state.mode)
    && !sideIsCpuControlled(0)
    && Boolean(digest)
    && digest.rounds > 0
    && digest.fighterId === (state.fighters[0]?.def?.id || "");
  if (recap) {
    recap.textContent = eligible ? fightRecapLine(digest) : "";
    recap.hidden = !eligible;
  }
  if (!eligible) {
    renderCoachCard("#resultCoach", null);
    return null;
  }
  return renderCoachCard("#resultCoach", currentLessonRecommendation(digest));
}

function showSameFightersStageSelect() {
  if (state.screen !== "result" || state.mode !== "versus") return false;
  state.locks = [true, true];
  state.selectingPlayer = 1;
  state.phase = "idle";
  showStageSelect();
  $("#fightButton").textContent = "FIGHT NEW STAGE →";
  return true;
}

function showArcadeLadder(clearedMatch) {
  const run = state.arcadeRun;
  const next = currentArcadeMatch(run);
  const nextDef = arcadeOpponentDef(next);
  const clearedDef = arcadeOpponentDef(clearedMatch);
  renderArcadeRoute();
  $("#arcadeLadderTitle").textContent = next?.kind === "boss" ? "FINAL AUTHORITY"
    : next?.kind === "rival" ? "SETTLE THE RIVALRY"
      : "THE STREET OPENS";
  $("#arcadeLadderMessage").textContent = next?.kind === "boss"
    ? "THE BLACK BOOK OPENS. THE COMMISSIONER IS WAITING AT THE VET."
    : `${clearedDef?.name || "ONE FIGHTER"} CROSSED OUT · ${nextDef?.name || "THE NEXT CHALLENGER"} STEPS FORWARD.`;
  $("#arcadeContinueButton").textContent = next?.kind === "boss" ? "ENTER FINAL BOUT →"
    : next?.kind === "rival" ? "FACE YOUR RIVAL →"
      : "NEXT FIGHT →";
  showScreen("ladder");
}

// ===========================================================================
// v2.1 PROGRESSION — arcade ending sequence: three treated story panels over
// art the game already ships (the 4x4 specials atlas + the roster portrait),
// an SF2-style credits roll, then the classic resting ending card. Pure DOM
// overlay, so it reads identically under the 2D canvas and CINEMA 3D. Every
// beat is skippable with any attack button / tap / pad confirm; reduced
// motion swaps crossfade+pan for instant cuts and a static credits list.
// ===========================================================================

const endingSequence = {
  active: false,
  def: null,
  panels: [],
  step: -1,
  timer: 0,
};

const ENDING_PANEL_NUMERALS = ["I", "II", "III"];

function clearEndingSequenceTimer() {
  window.clearTimeout(endingSequence.timer);
  endingSequence.timer = 0;
}

function cancelEndingSequence() {
  clearEndingSequenceTimer();
  endingSequence.active = false;
  endingSequence.step = -1;
  $("#endingScreen").classList.remove("sequencing");
  $("#endingPanels").hidden = true;
  $("#endingCredits").hidden = true;
}

function scheduleEndingAdvance(ms) {
  clearEndingSequenceTimer();
  endingSequence.timer = window.setTimeout(() => {
    endingSequence.timer = 0;
    advanceEndingSequence();
  }, ms);
}

function renderEndingPanel(step) {
  const panel = endingSequence.panels[step];
  const def = endingSequence.def;
  if (!panel || !def) return;
  const art = $("#endingPanelArt");
  const isPortrait = panel.art === "portrait";
  art.classList.toggle("portrait", isPortrait);
  art.classList.toggle("atlas", !isPortrait);
  art.style.backgroundImage = isPortrait
    ? `url("assets/fighters/${def.id}.webp")`
    : `url("${posesSheetUrl(def)}")`;
  if (isPortrait) {
    art.style.backgroundPosition = "";
  } else {
    // Frame one 4x4 atlas cell exactly like the victory pose treatment does.
    const frame = clamp(Math.round(panel.frame ?? 0), 0, 15);
    art.style.backgroundPosition = `${((frame % 4) / 3) * 100}% ${(Math.floor(frame / 4) / 3) * 100}%`;
  }
  const panelEl = $("#endingPanel");
  panelEl.dataset.treat = panel.treat || "night";
  $("#endingPanelIndex").textContent = `PART ${ENDING_PANEL_NUMERALS[step] || step + 1} · ${def.name}`;
  $("#endingPanelTitle").textContent = panel.title;
  $("#endingPanelText").textContent = panel.text;
  // Crossfade + slow pan; the global reduced-motion kill-rule flattens both
  // into an instant cut.
  restartCssAnimation(panelEl, "enter");
  modeFxDebug.endingPanelsShown += 1;
  scheduleEndingAdvance(state.accessibility.reducedMotion ? 5600 : 7400);
}

function renderEndingCredits() {
  const reduced = state.accessibility.reducedMotion;
  const crawl = $("#endingCreditsCrawl");
  crawl.innerHTML = `
    <div class="credits-heading"><b>${ARCADE_CREDITS.heading}</b><span>${ARCADE_CREDITS.subheading}</span></div>
    <div class="credits-section">${ARCADE_CREDITS.castTitle}</div>
    ${roster.map((def) => `<div class="credit-cast"><img src="assets/fighters/${def.id}.webp" alt="" draggable="false"><b>${def.name}</b><span>${def.title}</span></div>`).join("")}
    <div class="credit-row"><span>${ARCADE_CREDITS.bossCredit.role}</span><b>${ARCADE_CREDITS.bossCredit.name}</b></div>
    <div class="credits-section">${ARCADE_CREDITS.crewTitle}</div>
    ${ARCADE_CREDITS.crew.map((row) => `<div class="credit-row"><span>${row.role}</span><b>${row.name}</b></div>`).join("")}
    <div class="credit-finale">${ARCADE_CREDITS.finale}</div>`;
  $("#endingPanels").hidden = true;
  const container = $("#endingCredits");
  container.classList.toggle("static", reduced);
  container.hidden = false;
  modeFxDebug.creditsRolls += 1;
  if (reduced) {
    crawl.classList.remove("roll");
    scheduleEndingAdvance(9000);
  } else {
    crawl.style.setProperty("--credits-ms", "30s");
    restartCssAnimation(crawl, "roll");
    scheduleEndingAdvance(30800);
  }
}

function finishEndingSequence() {
  cancelEndingSequence();
  // The resting ending card (replay / title / daily share) takes the screen.
  restartCssAnimation($("#endingScreen").querySelector(".ending-copy"), "enter");
}

function advanceEndingSequence() {
  if (!endingSequence.active) return false;
  if (state.screen !== "ending") {
    cancelEndingSequence();
    return false;
  }
  clearEndingSequenceTimer();
  endingSequence.step += 1;
  if (endingSequence.step < endingSequence.panels.length) renderEndingPanel(endingSequence.step);
  else if (endingSequence.step === endingSequence.panels.length) renderEndingCredits();
  else finishEndingSequence();
  return true;
}

function beginEndingSequence(def, panels) {
  endingSequence.active = true;
  endingSequence.def = def;
  endingSequence.panels = [...panels];
  endingSequence.step = -1;
  $("#endingScreen").classList.add("sequencing");
  $("#endingCredits").hidden = true;
  $("#endingPanels").hidden = false;
  modeFxDebug.endingSequences += 1;
  advanceEndingSequence();
}

// Any attack button (either seat's bindings), Enter or Space skips the
// current ending beat. Pad confirm routes in via menuPadLoop; taps via the
// pointer handlers on the panel/credits containers.
function endingSkipKeyCode(code) {
  if (code === "Enter" || code === "Space") return true;
  return keyMaps.some((map) => [map.lp, map.hp, map.lk, map.hk].includes(code));
}

function handleEndingKey(event) {
  if (!endingSequence.active || state.screen !== "ending") return false;
  if (!endingSkipKeyCode(event.code)) return false;
  event.preventDefault();
  advanceEndingSequence();
  return true;
}

function showArcadeEnding() {
  const run = state.arcadeRun;
  const ending = getArcadeEnding(run?.playerId);
  const def = roster.find(({ id }) => id === run?.playerId);
  if (!ending || !def) {
    showScreen("title");
    return;
  }
  const screen = $("#endingScreen");
  screen.style.setProperty("--ending-color", ending.color);
  $("#endingTitle").textContent = ending.title;
  $("#endingQuote").textContent = ending.quote;
  $("#endingStory").textContent = ending.story;
  $("#endingArt").style.backgroundImage = `url("${posesSheetUrl(def)}")`;
  renderArcadeRoute();
  updateDailyBanners();
  showScreen("ending");
  // v2.1 PROGRESSION: the 3-panel resolution + credits roll runs first; the
  // card above is the sequence's resting state (and the fallback if a fighter
  // ever ships without panels).
  const panels = endingPanelsFor(def.id);
  if (panels?.length) beginEndingSequence(def, panels);
  else cancelEndingSequence();
}

function resolveMatchResult(winner) {
  // R2.1 STREETS: a finished REPLAY never touches records, sets or the ring —
  // it verifies determinism against the recorded outcome and returns to the
  // theater. Intercepted before every mode route.
  if (replayPlayback.active) {
    finishReplayPlayback(winner);
    return;
  }
  // R2.1 STREETS: bank the finished match into the replay ring and fold the
  // first-to-N set (meta paths — observation only, never during resimulation).
  if (!rollbackResimulating) {
    // Wave 19: close the spectator broadcast BEFORE the recorder is banked
    // (finalize resets the frame map the flush reads).
    if (state.mode === "online") flushSpectateAtResult(winner);
    finalizeReplayRecording(winner);
    foldSetResult(winner);
    // Wave 19: fold a PHILLY OPEN bout into the bracket before showResult
    // reads the outcome (meta only — never during resimulation).
    if (bracketSession.playing && bracketSession.current) recordBracketMatchResult(winner);
    // Loser-picks-stage latch (side 0 is always the host seat online).
    if (state.mode === "online" && onlineSession.matchConfig) {
      onlineSession.lastLoserRole = winner === 0 ? "guest" : "host";
    }
  }
  // Release 1.8 GRIND: mode routing. Survival and Block War resolve their
  // single-round bouts here; arcade (and the Daily Jawn riding it) keeps the
  // ladder flow but gains the SF2 tally + initials loop.
  if (state.mode === "survival" && state.survivalRun) {
    resolveSurvivalResult(winner);
    return;
  }
  if (state.mode === "team" && state.teamBattle) {
    resolveTeamResult(winner);
    return;
  }
  if (state.mode !== "arcade" || !state.arcadeRun) {
    // v2.1 PROGRESSION: versus/online matches fold into the records book here
    // (meta path — observation only, never during resimulation).
    progressionMatchEnd(winner);
    showResult(winner);
    return;
  }
  const outcome = recordArcadeResult(state.arcadeRun, winner === 0);
  if (winner !== 0) {
    // The Daily Jawn is one attempt — a defeat ends the run (score recorded,
    // streak broken) with no continues, then initials if the total charts.
    if (dailySession.active && !dailySession.finished) {
      finishDailyRun(false);
      progressionMatchEnd(winner);
      maybeEnterInitials(() => showResult(winner));
      return;
    }
    progressionMatchEnd(winner);
    showResult(winner);
    return;
  }
  const tallyContext = finalizeBoutTally();
  // v2.1 PROGRESSION: fold the cleared bout (after the tally banks so the
  // ledger sees the run score), and ink the ladder clear itself.
  progressionMatchEnd(0);
  if (outcome.completed) {
    progressionRunEnd("arcade", {
      fighterId: state.arcadeRun.playerId,
      finalDifficulty: !dailySession.active && state.aiDifficulty === "final",
    });
  }
  const proceed = () => {
    if (outcome.completed) {
      if (dailySession.active && !dailySession.finished) finishDailyRun(true);
      maybeEnterInitials(() => showArcadeEnding());
      return;
    }
    prepareArcadeOpponent(true);
    showArcadeLadder(outcome.match);
  };
  if (tallyContext) {
    const cleared = arcadeOpponentDef(outcome.match)?.name || "";
    showBoutTally(tallyContext, proceed, {
      title: outcome.completed ? "ARCADE CLEARED" : `${outcome.match.label} CLEARED`,
      sub: cleared ? `${cleared} DEFEATED · ×${tallyContext.multiplier} DIFFICULTY` : "",
    });
  } else proceed();
}

function updateHud() {
  if (rollbackResimulating) return;
  if (!state.fighters.length) return;
  // 5.3: two digest signals that have no single sim event — the highest Grit
  // the player ever held (dozens of gain sites) and whether the street ever
  // put an object down. Sampled here because updateHud is already the
  // once-per-frame presentation read and is resim-exempt by its first line.
  if (state.screen === "fight" && state.fighters.length === 2 && !sideIsCpuControlled(0)) {
    const digest = progressionMatch.digest;
    digest.meterPeak = Math.max(digest.meterPeak, clamp(state.fighters[0].meter || 0, 0, GRIT_RULES.maximum));
    if (state.stageWeapon && state.stageWeapon.phase !== "gone") digest.weaponOffered = true;
  }
  const sideTags = $$(".side-tag");
  const seatTag = (side) => (state.mode !== "demo" ? `P${side + 1}` : `CPU ${side + 1}`);
  if (sideTags[0]) sideTags[0].textContent = seatTag(0);
  if (sideTags[1]) sideTags[1].textContent = seatTag(1);
  state.fighters.forEach((fighter, side) => {
    const prefix = side === 0 ? "p1" : "p2";
    $(`#${prefix}Name`).textContent = fighter.def.name;
    const health = clamp(fighter.health, 0, 100) / 100;
    const healthBar = $(`#${prefix}Health`);
    healthBar.style.transform = `scaleX(${health})`;
    healthBar.classList.toggle("danger", health <= 0.25);
    // The damage ghost (#p1Damage/#p2Damage) is driven per rendered frame by
    // updateDamageGhosts() — hold-then-drain — so it is not synced here.
    $(`#${prefix}Meter`).style.transform = `scaleX(${clamp(fighter.meter, 0, 100) / 100})`;
    $(`#${prefix}Grit`).textContent = String(Math.floor(fighter.meter));
    $(`#${prefix}Meter`).closest(".grit-row").classList.toggle("full", fighter.meter >= GRIT_RULES.superCost);
    // Round pips only rebuild when the win count changes (updateHud fires on
    // every hit and timer tick, which would restart the flip constantly). The
    // freshly earned pip carries .flip for the 180° flash-flip entrance.
    const roundsEl = $(`#${prefix}Rounds`);
    const wins = state.rounds[side];
    if (roundsEl.dataset.wins !== String(wins)) {
      const previousWins = Number(roundsEl.dataset.wins || 0);
      roundsEl.dataset.wins = String(wins);
      roundsEl.innerHTML = [0, 1].map((round) => {
        const won = wins > round;
        const fresh = won && wins > previousWins && round === wins - 1;
        if (fresh) hudFxDebug.pipFlips += 1;
        return `<i class="${won ? (fresh ? "won flip" : "won") : ""}"></i>`;
      }).join("");
    }
  });
  state.fighters.forEach((fighter, side) => {
    const prefix = `p${side + 1}`;
    const profile = getThrowable(fighter.kitId);
    $(`#${prefix}ObjectName`).textContent = profile ? profile.name : "—";
    $(`#${prefix}Objects`).innerHTML = profile
      ? Array.from({ length: profile.usesPerRound }, (_, index) => `<i class="${index < fighter.throwableUses ? "left" : ""}"></i>`).join("")
      : "";
  });
  // Final-10-seconds urgency: red heartbeat pulse, quickening under 5. The
  // red comes from the static .low class (not the animation) so reducedMotion
  // keeps a calm steady red once the CSS kill-rule flattens the keyframes.
  const timerEl = $("#timer");
  const timerValue = state.mode === "training" ? "∞" : String(Math.ceil(state.timer)).padStart(2, "0");
  const timerLow = state.mode !== "training" && state.phase === "fight" && state.timer <= 10;
  timerEl.classList.toggle("low", timerLow);
  timerEl.classList.toggle("critical", timerLow && state.timer <= 5);
  if (timerEl.dataset.value !== timerValue) {
    timerEl.dataset.value = timerValue;
    timerEl.textContent = timerValue;
    if (timerLow) {
      restartCssAnimation(timerEl, "tick");
      hudFxDebug.timerPulses += 1;
      // w51 clock truth: the red heartbeat gets a sound. One synthesised
      // tick per displayed second on the same edge (rising pitch ladder,
      // buzzer at :00) and the once-per-round "TEN SECONDS" announcer call
      // at :10, both behind the updateHud rollback guard above so replays
      // and resims stay silent. timerTicks and timerPulses must agree.
      hudFxDebug.timerTicks += 1;
      clockTickAudio(state.timer);
      clockCallout();
    }
  }
  if (!timerLow) timerEl.classList.remove("tick");
  const battle = state.teamBattle;
  $("#roundLabel").textContent = state.mode === "training" ? "TRAINING"
    : state.mode === "demo" ? `DEMO · ROUND ${state.round}`
      : state.mode === "replay" ? `REPLAY · ROUND ${state.round}`
        : state.mode === "survival" ? `GAUNTLET · BOUT ${(currentSurvivalBout(state.survivalRun)?.index ?? 0) + 1}`
          : state.mode === "team" && battle ? `BLOCK WAR · ${teamFightersRemaining(battle, 0)}V${teamFightersRemaining(battle, 1)}`
            : `ROUND ${state.round}`;
  const finishing = state.phase === "finish" && state.finishWinner === 0;
  const superReady = state.phase === "fight" && state.fighters[0]?.meter >= GRIT_RULES.superCost;
  setTouchPrompt(finishing ? "final" : superReady ? "super" : "");
}

// ---------------------------------------------------------------------------
// 5.1 (sweep #30): first-run control card. A newcomer used to reach ROUND 1
// without ever being told J/K/N/M or "hold away to block". The card sits in
// a corner through the first human fight's round-1 intro and the opening
// seconds (it is NOT allowed to stretch the intro clock: a replay of that
// fight would re-run with the stock 2.1 s intro and desync), shows the four
// buttons for the device actually in the player's hands — keyboard bindings,
// pad glyphs in the detected label set, or the touch cluster — plus the
// block rule, the active style's special command and the grab. Dismissed by
// a tap/click, Escape, or its own timer; shown once per install.
// ---------------------------------------------------------------------------
const CONTROL_CARD_KEY = "final-blow-control-card";
const CONTROL_CARD_MS = 9500;
const controlCard = { visible: false, timer: 0, shows: 0 };

function controlCardSeen() {
  try {
    return localStorage.getItem(CONTROL_CARD_KEY) === "1";
  } catch {
    return false;
  }
}

function controlCardDevice() {
  if (assignedPadBySide[0] !== null || getPad(0)) return "pad";
  if (getComputedStyle($("#touchControls")).display !== "none") return "touch";
  return "keyboard";
}

function controlCardLines(device = controlCardDevice()) {
  const style = state.controlStyle;
  const buttons = device === "pad"
    ? ATTACK_BUTTONS.map((action) => `${padButtonLabel(padMap[action], activePadLabelSet())} ${BUTTON_LABELS[action]}`)
    : device === "keyboard"
      ? ATTACK_BUTTONS.map((action) => `${formatKeyCode(keyMaps[0][action])} ${BUTTON_LABELS[action]}`)
      : ["LP", "HP", "LK", "HK"].map((label) => `${label} PAD`);
  const move = device === "keyboard"
    ? `${formatKeyCode(keyMaps[0].left)} ${formatKeyCode(keyMaps[0].right)} WALK · ${formatKeyCode(keyMaps[0].up)} JUMP · ${formatKeyCode(keyMaps[0].down)} CROUCH`
    : device === "pad" ? "STICK OR D-PAD WALKS · UP JUMPS · DOWN CROUCHES"
      : "LEFT PAD WALKS · UP JUMPS · DOWN CROUCHES";
  return [
    ["MOVE", move],
    // 5.3 (sweep #31 audit): BLOCK and GRAB were the last two hard-coded
    // command strings on this card — GRAB even disagreed with the move list,
    // which has always said TOWARD/AWAY + LP OR LK.
    ["BLOCK", commandLabel("block", style)],
    ["BUTTONS", buttons.join(" · ")],
    ["SPECIAL", commandLabel("commandSpecial", style)],
    ["GRAB", commandLabel("throw", style)],
  ];
}

function showControlCard() {
  const card = $("#controlCard");
  if (!card) return false;
  $("#controlCardLines").innerHTML = controlCardLines()
    .map(([name, text]) => `<span><b>${name}</b>${text}</span>`).join("");
  card.hidden = false;
  controlCard.visible = true;
  controlCard.shows += 1;
  window.clearTimeout(controlCard.timer);
  controlCard.timer = window.setTimeout(() => hideControlCard(), CONTROL_CARD_MS);
  return true;
}

function hideControlCard() {
  const card = $("#controlCard");
  window.clearTimeout(controlCard.timer);
  if (!card || !controlCard.visible) return false;
  controlCard.visible = false;
  card.hidden = true;
  // The touch flick tip waited its turn behind the card (two coaching lines
  // at once is noise); it takes the prompt now if the pad is on screen.
  if (state.screen === "fight" && !state.paused) maybeCoachTouchFlick();
  return true;
}

function maybeShowControlCard() {
  // No screen check here: startMatch announces ROUND 1 a few lines before
  // showScreen("fight"), and showScreen only tears the card down when the
  // destination is NOT the fight screen.
  if (state.round !== 1) return false;
  if (!["arcade", "versus", "survival", "team"].includes(state.mode)) return false;
  if (replayPlayback.active || demoSession.active || controlCardSeen()) return false;
  try {
    localStorage.setItem(CONTROL_CARD_KEY, "1");
  } catch {
    // Storage refused: the card shows this once and again next load.
  }
  return showControlCard();
}

// 5.x phone flick-to-dash discoverability (sweep #41): a transient coaching
// line on the touch prompt. The super and finish labels always outrank it —
// the hint only fills the prompt while it would otherwise be empty, and it
// expires on its own timer so the HUD refresh cadence never matters.
const touchHint = { text: "", until: 0, timer: 0 };
let touchPromptKind = "";

function showTouchHint(text, ms = 3200) {
  touchHint.text = text;
  touchHint.until = performance.now() + ms;
  window.clearTimeout(touchHint.timer);
  touchHint.timer = window.setTimeout(() => setTouchPrompt(touchPromptKind), ms + 16);
  setTouchPrompt(touchPromptKind);
}

// The first three touch-controlled fights open with the flick tip; after that
// the player has either found it or the prompt would be nagging. Counted in
// storage so it is per install, not per page load.
const TOUCH_FLICK_COACH_KEY = "final-blow-touch-flick-coach";
const TOUCH_FLICK_COACH_LIMIT = 3;

function maybeCoachTouchFlick() {
  if (state.mode === "demo" || replayPlayback.active) return;
  if (getComputedStyle($("#touchControls")).display === "none") return;
  // 5.1: never alongside the first-run control card — hideControlCard()
  // re-invokes this once the card is gone, so the tip is deferred, not lost.
  if (controlCard.visible) return;
  let shown = 0;
  try {
    shown = Number(localStorage.getItem(TOUCH_FLICK_COACH_KEY)) || 0;
  } catch {
    // Storage refused: coach once for this page load and move on.
  }
  if (shown >= TOUCH_FLICK_COACH_LIMIT) return;
  try {
    localStorage.setItem(TOUCH_FLICK_COACH_KEY, String(shown + 1));
  } catch {
    // Same: nothing to persist means the tip simply shows again next time.
  }
  showTouchHint("FLICK THE PAD TO DASH · DOUBLE-TAP WORKS TOO", 4200);
}

function setTouchPrompt(kind = "") {
  touchPromptKind = kind;
  const prompt = $("#touchPrompt");
  const actions = $(".touch-action");
  const hintActive = !kind && Boolean(touchHint.text) && performance.now() < touchHint.until;
  const label = kind === "final" ? `FINISH HIM · ${commandLabel("finalBlow", state.controlStyle)}`
    : kind === "super" ? `SUPER READY · ${commandLabel("super", state.controlStyle)}`
      : hintActive ? touchHint.text
        : "";
  prompt.textContent = label;
  prompt.hidden = !label;
  prompt.classList.toggle("ready", kind === "final");
  prompt.classList.toggle("super-ready", kind === "super");
  prompt.classList.toggle("hint", hintActive);
  actions.classList.toggle("ready", kind === "final");
  actions.classList.toggle("super-ready", kind === "super");
}

function resetTrainingPosition(countReset = true) {
  if (state.mode !== "training") return;
  state.fighters = makeMatchFighters();
  state.particles.length = 0;
  state.effects.length = 0;
  state.traps.length = 0;
  state.projectiles.length = 0;
  state.hitstop = 0;
  state.phase = "fight";
  state.phaseTime = 0;
  resetTrainingScenario(state.training);
  selectTrainingTrial(state.training, state.fighters[0].kitId, state.training.trialIndex);
  if (state.training.infiniteGrit) state.fighters.forEach((fighter) => { fighter.meter = GRIT_RULES.maximum; });
  if (countReset) state.training.resets += 1;
  state.training.lastDamage = 0;
  updateHud();
  updateTrainingUi();
}

function renderTrainingTrials() {
  if (state.mode !== "training" || !state.fighters.length) return;
  const fighterId = state.fighters[0].kitId;
  const trials = comboTrialsForFighter(fighterId);
  const select = $("#trainingTrialSelect");
  if (state.training.trialFighterId !== fighterId) selectTrainingTrial(state.training, fighterId, 0);
  // R1.9: options carry the tier tag + a check for earned medals, so the
  // rebuild key includes the medal count for this fighter.
  const counts = fighterMedalCounts(trialMedals, fighterId);
  const stamp = `${fighterId}:${counts.total}`;
  if (select.dataset.stamp !== stamp) {
    select.dataset.stamp = stamp;
    select.dataset.fighterId = fighterId;
    select.innerHTML = trials.map((trial, index) => {
      const medal = medalForTrial(trialMedals, fighterId, trial.id);
      return `<option value="${index}">${index + 1} · ${trial.name} · ${trial.tier.toUpperCase()}${medal ? " ✓" : ""}</option>`;
    }).join("");
  }
  select.value = String(state.training.trialIndex);
  $("#trainingTrialMedals").innerHTML = counts.total ? medalMarkup(counts) : "";
}

function updateTrainingUi(input = {}) {
  if (rollbackResimulating) return;
  if (state.mode !== "training" || !state.fighters.length) return;
  const [player] = state.fighters;
  const combo = player.combo.snapshot(state.simulationTick);
  if (combo.damage > 0) state.training.lastDamage = combo.damage;
  // R1.9: per-tick training feeds — frame meter cells, the arcade input
  // column, and the FIGHT SCHOOL walk/setup babysitter. All render-side; this
  // function already early-returns during rollback resimulation.
  feedFrameMeter();
  feedInputColumn(input);
  renderInputColumn();
  schoolTick();
  renderSchoolPanel();
  const limbSuffix = input.limb === "kick" ? "K" : "P";
  const labels = [
    ["left", "←"], ["right", "→"], ["down", "↓"], ["jump", "↑"],
    ["light", `L${limbSuffix}`], ["heavy", `H${limbSuffix}`], ["special", "SPECIAL"],
    ["enhanced", "EX"], ["throw", input.throwBack ? "BACK THROW" : "THROW"], ["super", "SUPER"],
  ].filter(([action]) => input[action]).map(([, label]) => label);
  const inputLabel = labels.join("+");
  // Training always shows the live grab rule so the SF2 proximity command is learnable.
  const opponent = state.fighters[1];
  const grabReady = inProximityGrabRange(player, opponent) && !player.attacking;
  $("#trainingGrabHint").textContent = grabReady
    ? "IN GRAB RANGE · TOWARD + LP/LK THROWS FORWARD · AWAY + LP/LK THROWS BACK"
    : `GRAB: STEP IN CLOSE, THEN ${commandLabel("throw", state.controlStyle).replace(/^CLOSE \+ /, "")}`;
  $("#trainingGrabHint").classList.toggle("ready", grabReady);
  if (inputLabel && (inputLabel !== state.training.lastInputLabel
    || state.simulationTick - state.training.lastInputFrame > 6)) {
    state.training.inputHistory.push(inputLabel);
    state.training.inputHistory = state.training.inputHistory.slice(-12);
    state.training.lastInputLabel = inputLabel;
    state.training.lastInputFrame = state.simulationTick;
  } else if (!inputLabel) {
    state.training.lastInputLabel = "";
  }
  const snapshot = trainingSnapshot(state.training);
  renderTrainingTrials();
  const move = snapshot.lastMove;
  $("#trainingDamage").textContent = Number(snapshot.lastDamage).toFixed(1).replace(/\.0$/, "");
  $("#trainingCombo").textContent = `${combo.hits} HIT`;
  // v5.1 TEMPO TELLS: the line grows `R12+6 WHIFF · RE-ARM 4F` once the
  // swing whiffs (noteWhiff merges the tax into lastMove at the tax site).
  $("#trainingFrames").textContent = trainingFrameDataLabel(move);
  $("#trainingAdvantage").textContent = snapshot.lastAdvantage === null
    ? move ? `${move.onHit >= 0 ? "+" : ""}${move.onHit} HIT · ${move.onBlock >= 0 ? "+" : ""}${move.onBlock} BLOCK` : "—"
    : `${snapshot.lastAdvantage >= 0 ? "+" : ""}${snapshot.lastAdvantage} ACTUAL`;
  // Release 1.7: Perfect Guard practice readout (player just-defends landed).
  $("#trainingPerfectGuards").textContent = String(snapshot.perfectGuards);
  // R1.9: the arcade input column (left edge) replaced the flat INPUT line;
  // this line keeps the dummy/reset status readout only.
  $("#trainingInputs").textContent = `DUMMY: ${snapshot.dummyMode.toUpperCase()}  //  RESETS: ${snapshot.resets}  //  ${snapshot.lastResult || "READY"}`;
  $("#trainingTrialSteps").innerHTML = `TRIAL: ${snapshot.trial.steps.map((step, index) => `<span class="${step.complete ? "done" : index === snapshot.trial.step ? "next" : ""}">${step.label}</span>`).join(" › ") || "—"}`;
  $("#trainingTrialStatus").textContent = `${snapshot.trial.status}${snapshot.trial.complete ? ` · ${snapshot.trial.completions} CLEAR` : ""}`;
  $("#trainingDummySelect").value = snapshot.dummyMode;
  $("#trainingRecoverToggle").checked = snapshot.autoRecover;
  $("#trainingGritToggle").checked = snapshot.infiniteGrit;
  $("#trainingHitboxToggle").checked = snapshot.showHitboxes;
  $("#trainingFrameMeterToggle").checked = snapshot.showFrameMeter;
  $("#trainingRecordButton").textContent = snapshot.recordingActive ? "STOP & PLAY" : "RECORD P2";
  $("#trainingPlaybackButton").disabled = snapshot.recordingFrames === 0;
  $("#trainingPlaybackButton").textContent = snapshot.dummyMode === "playback"
    ? `PLAYING ${snapshot.recordingFrames}F` : `PLAY LOOP ${snapshot.recordingFrames || "—"}F`;
}

// 5.1 (sweep #31): the dialog's SPECIALS / ENHANCED / SUPER lines were static
// classic copy. Elements carrying data-style-copy are templates rendered for
// the live style whenever the option changes.
function renderControlStyleCopy() {
  $$("[data-style-copy]").forEach((element) => {
    if (!element.dataset.template) element.dataset.template = element.textContent;
    element.textContent = styleCopy(element.dataset.template, state.controlStyle);
  });
}

function syncNewOptionsUi() {
  renderControlStyleCopy();
  $("#goreToggle").checked = state.graphicFatalities;
  $("#stageWeaponToggle").checked = state.stageWeaponsEnabled;
  $("#controlStyleSelect").value = state.controlStyle;
  $("#reducedMotionToggle").checked = state.accessibility.reducedMotion;
  $("#highContrastToggle").checked = state.accessibility.highContrast;
  $("#colorAssistSelect").value = state.accessibility.colorAssist;
  $("#shakeSelect").value = String(state.accessibility.shakeScale);
  $("#touchHandednessSelect").value = state.touchSettings.handedness;
  $("#touchScale").value = String(Math.round(state.touchSettings.scale * 100));
  $("#touchOpacity").value = String(Math.round(state.touchSettings.opacity * 100));
  $("#touchScaleValue").textContent = `${Math.round(state.touchSettings.scale * 100)}%`;
  $("#touchOpacityValue").textContent = `${Math.round(state.touchSettings.opacity * 100)}%`;
  $("#touchHapticsToggle").checked = state.touchSettings.haptics;
  $("#soundCaptionsToggle").checked = state.soundCaptions;
  $("#visualQualitySelect").value = state.visualQuality;
  $("#attractModeToggle").checked = state.attractEnabled;
  if ($("#cabinetModeToggle")) $("#cabinetModeToggle").checked = state.cabinetMode;
}

function getPad(index) {
  return [...(navigator.getGamepads?.() || [])].filter(Boolean)[index] || null;
}

function buttonValue(pad, index) {
  return pad?.buttons[index]?.pressed || (pad?.buttons[index]?.value || 0) > 0.55;
}

function readInput(side) {
  const map = keyMaps[side];
  const pad = getPad(side);
  assignedPadBySide[side] = pad?.index ?? null;
  const previous = previousPads.get(pad?.index) || [];
  const axisX = pad ? pad.axes[0] || 0 : 0;
  const axisY = pad ? pad.axes[1] || 0 : 0;
  const held = (action) => keys.has(map[action]) || (side === 0 && touch.has(action));
  const edge = (action) => {
    let active = false;
    if (pressed.has(map[action])) {
      active = true;
      pressed.delete(map[action]);
    }
    const touchToken = `${action}:pressed`;
    if (side === 0 && touch.has(touchToken)) {
      active = true;
      touch.delete(touchToken);
    }
    return active;
  };
  const padEdge = (index) => Boolean(pad && buttonValue(pad, index) && !previous[index]);
  const left = held("left") || axisX < -0.42 || buttonValue(pad, 14);
  const right = held("right") || axisX > 0.42 || buttonValue(pad, 15);
  const down = held("down") || axisY > 0.52 || buttonValue(pad, 13);
  const upHeld = held("up") || Boolean(pad && (axisY < -0.65 || buttonValue(pad, 12)));
  const up = edge("up") || (upHeld && !previous[20]);

  // The four combat buttons are the only attack inputs. Everything else is
  // reached by the directional control, a motion, or a two-button chord.
  const raw = { fourButton: true, left, right, down, up, jump: up };
  for (const button of ATTACK_BUTTONS) {
    raw[button] = edge(button) || padEdge(padMap[button]);
    raw[`${button}Held`] = held(button) || Boolean(buttonValue(pad, padMap[button]));
  }

  // Arm the finishing window only once every combat button is released, so the
  // KO-causing press or a held button can never roll straight into a finisher.
  const attackHeld = ATTACK_BUTTONS.some((button) => raw[`${button}Held`]);
  if (state.phase === "finish" && state.finishWinner === side) {
    if (!attackHeld) state.finishArmed[side] = true;
  } else {
    state.finishArmed[side] = false;
  }

  if (pad) {
    const next = pad.buttons.map((button) => button.pressed || button.value > 0.55);
    next[20] = axisY < -0.65 || buttonValue(pad, 12);
    previousPads.set(pad.index, next);
  }
  return raw;
}

function activeControlStyle(side) {
  return state.mode === "online"
    ? normalizeControlStyle(onlineSession.matchConfig?.controlStyles?.[side])
    : state.controlStyle;
}

// --- v2.9 FLOW: demo choreography plumbing ---------------------------------
// The choreographer receives a plain-data view of the two fighters (never the
// live objects) and reports back through raw inputs; its own state lives on
// demoSession exactly like superShown. Everything here is scoped to
// state.mode === "demo", so ranked/vs/arcade CPU behaviour is untouched.

function demoChoreoFighterView(fighter) {
  return {
    x: fighter.x,
    facing: fighter.facing,
    grounded: fighter.grounded,
    down: fighter.down,
    pendingKnockdown: fighter.pendingKnockdown,
    wakeupFrames: fighter.wakeupFrames,
    hitstunFrames: fighter.hitstunFrames,
    blockstunFrames: fighter.blockstunFrames,
    dizzyFrames: fighter.dizzyFrames,
    tauntFrames: fighter.tauntFrames,
    attacking: Boolean(fighter.attacking),
    // v2.9 FLOW round 2: the sim only opens a cancel window on a CONFIRMED
    // hit (tryAttackCancel bails on an empty attackConnected). The
    // choreographer used to chain off "a move came out", so a whiffed poke
    // queued a link that could never cancel — measured, that single mistake
    // was 63% of all abandoned directives and it is exactly the "press,
    // nothing happens, stand there, reset" cadence on screen.
    attackConnected: Boolean(fighter.attackConnected),
    // v2.9 FLOW: crouch edges feed the choreographer's crouchTrans beat, and
    // crouch/guard/vx together are how the choreographer's liveliness
    // watchdog knows a fighter has stopped moving on screen.
    crouch: Boolean(fighter.crouch),
    guarding: Boolean(fighter.guarding),
    grabbed: Boolean(fighter.grabbed),
    grabbing: Boolean(fighter.grabbing),
    meter: fighter.meter,
    stunMeter: fighter.stunMeter,
    throwableUses: fighter.throwableUses,
    carriedWeapon: Boolean(fighter.carriedWeapon),
    dashFrames: fighter.dashFrames,
    dashDirection: fighter.dashDirection || 0,
    vx: fighter.vx,
    vy: fighter.vy,
    // v2.9 FLOW round 4. `health` is how the choreographer notices a LOPSIDED
    // exhibition early enough to hand the trailing fighter the stage (a
    // dominated fighter finished a whole exhibition at 6 of 30 moves).
    // `juggleCount` / `wallBounceUsed` are the two flags that decide whether a
    // victim can still be armed for a corner wall bounce — the only
    // deterministic route to a wall splat — so chasing the beat against a
    // victim whose conversion is already spent is now avoidable.
    health: fighter.health,
    juggleCount: fighter.juggleCount,
    wallBounceUsed: Boolean(fighter.wallBounceUsed),
  };
}

function demoChoreoView() {
  return {
    tick: state.simulationTick,
    phase: state.phase,
    stageMinX: MOVEMENT_RULES.stageMinX,
    stageMaxX: MOVEMENT_RULES.stageMaxX,
    weapon: state.stageWeapon ? { phase: state.stageWeapon.phase, x: state.stageWeapon.x } : null,
    fighters: state.fighters.map(demoChoreoFighterView),
  };
}

// Beat observation from the sim call sites (dizzy, knockdown, wall splat,
// grab, taunt, pickup, round end). Guarded exactly like the other meta
// observers: demo only, never during a rollback resimulation.
function demoChoreoBeat(side, beat) {
  if (rollbackResimulating || state.mode !== "demo" || !demoSession.choreo) return;
  demoSession.choreo.noteBeat(side, beat);
}

function aiInput(fighter, opponent, dt) {
  fighter.aiClock -= dt;
  const input = { left: false, right: false, down: false, guard: false, jump: false, light: false, heavy: false, special: false, enhanced: false, throw: false, super: false, final: false };
  if (isPassiveDifficulty(fighter.aiBrain?.difficulty)) return input;
  const cpuFinisher = state.mode === "demo" || state.mode === "tournament" || fighter.side === 1;
  if (state.phase === "finish" && state.finishWinner === fighter.side && cpuFinisher) {
    // v2.9 FLOW round 2 (demo only): the attract loop spent ~2 seconds of
    // every round with the winner standing in front of a frozen victim
    // waiting out the brain's ordinary reaction clock — measured, only 54%
    // of an exhibition was actual fighting. The demo commits to its Final
    // Blow promptly instead. Arcade/tournament/versus pacing is untouched.
    if (state.mode === "demo") fighter.aiClock = Math.min(fighter.aiClock, DEMO_FINISHER_REACTION);
    input.final = fighter.aiClock <= 0;
    if (input.final) fighter.aiClock = 2;
    return input;
  }
  if (state.mode === "demo" && state.phase === "fight" && !demoSession.superShown) {
    const distance = Math.abs(opponent.x - fighter.x);
    const towardRight = opponent.x > fighter.x;
    if (distance > 245) {
      input.right = towardRight;
      input.left = !towardRight;
    } else if (fighter.side === demoSession.superSide) {
      input.super = true;
      demoSession.superShown = true;
    } else {
      input.guard = true;
    }
    return input;
  }
  const brainInput = stepAiBrain(fighter.aiBrain, {
    frame: state.simulationTick,
    self: fighter,
    opponent,
    roll: random(),
  });
  // v2.9 FLOW: the demo choreographer rides on top of the live brain. The
  // brain still observes every tick (so natural windows resume seamlessly);
  // a scripted input simply outranks it while a showcase directive runs.
  if (state.mode === "demo" && demoSession.choreo) {
    const view = demoChoreoView();
    if (fighter.side === 0) demoSession.choreo.observe(view);
    const scripted = demoSession.choreo.step(fighter.side, view);
    if (scripted) return scripted;
  }
  return brainInput;
}

function readQaInput(side) {
  const override = qaInputOverrides[side];
  if (!override || override.frames <= 0) return null;
  override.frames -= 1;
  const input = { ...override.input };
  if (override.frames <= 0) qaInputOverrides[side] = null;
  return input;
}

function rememberCommand(side, token) {
  const history = commandHistory[side];
  const frame = state.simulationTick;
  if (!history.length || history.at(-1).token !== token || frame - history.at(-1).frame > 9) history.push({ token, frame });
  while (history.length > 9 || (history[0] && frame - history[0].frame > 108)) history.shift();
}

function commandMatches(side, sequence) {
  const tokens = commandHistory[side].map((item) => item.token);
  let cursor = tokens.length - 1;
  for (let i = sequence.length - 1; i >= 0; i -= 1) {
    while (cursor >= 0 && tokens[cursor] !== sequence[i]) cursor -= 1;
    if (cursor < 0) return false;
    cursor -= 1;
  }
  return true;
}

// Directions are recorded as discrete state changes rather than per-frame holds
// so a steady down-forward hold cannot fake a repeated quarter-circle motion.
const directionTokenState = ["", ""];

function directionStateToken(input, fighter) {
  const absolute = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  const horizontal = absolute === 0 ? "" : absolute === fighter.facing ? "forward" : "back";
  if (input.down && horizontal) return `down-${horizontal}`;
  if (input.down) return "down";
  return horizontal;
}

function recordDirection(side, input, fighter) {
  const token = directionStateToken(input, fighter);
  if (token === directionTokenState[side]) return;
  directionTokenState[side] = token;
  if (!token) return;
  for (const part of token.split("-")) rememberCommand(side, part);
}

function recordInput(side, input, fighter) {
  recordDirection(side, input, fighter);
  if (input.punch) rememberCommand(side, "punch");
  if (input.kick) rememberCommand(side, "kick");
  if (input.enhanced) rememberCommand(side, "enhanced");
}

function tryFinish(side, input) {
  if (state.phase !== "finish" || state.finishWinner !== side) return false;
  if (!input.final) return false;
  // Input resolution only emits `final` for a fresh LP (A) or LK (B). There is
  // intentionally no distance check: the winner can finish from anywhere.
  const type = state.graphicFatalities ? (input.finisherVariant === 1 ? 1 : 0) : 0;
  finishRound(side, type);
  // R1.9 FIGHT SCHOOL: the LP/LK Final Blow window lesson validates on the
  // executed finisher (guarded meta observation, announce() pattern).
  if (!rollbackResimulating && side === 0 && state.mode === "training") {
    schoolEvent({ type: "finisher" });
  }
  return true;
}

function directionContext(fighter, input) {
  const absolute = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  return {
    absolute,
    forwardHeld: absolute === fighter.facing,
    backHeld: absolute === -fighter.facing,
  };
}

const advancedActions = new Set([
  "throwObject",
  "enhancedThrowObject",
  "commandSpecial",
  "launcher",
  "driveHeavy",
  "enhanced",
  "guardReversal",
  "super",
  ...KIT_ACTIONS,
]);

function beginAttack(fighter, action, input = {}, { reversal = false, force = false, cancelledFrom = "", limb = "", backThrow = null } = {}) {
  if (!force && (fighter.attacking || fighter.attackRearmFrames > 0 || fighter.stun > 0 || fighter.down || fighter.wakeupFrames > 0)) {
    // v5.1 TEMPO TELLS: a press that reaches here with ONLY the re-arm gap in
    // the way is the press the 4.5 rule eats (tryStartBufferedAttack has
    // already consumed the buffer entry). Stamp it so the body can flash
    // "not yet" and the mash is audible: before this the drop was silent.
    if (!fighter.attacking && fighter.attackRearmFrames > 0 && fighter.stun <= 0 && !fighter.down && fighter.wakeupFrames <= 0) {
      noteRearmDrop(fighter);
    }
    return false;
  }
  const actionGroup = fighterActionGroup(action);
  if (actionGroup === "throw" && !fighter.grounded) return false;
  if (advancedActions.has(action) && !fighter.grounded) return false;
  const direction = directionContext(fighter, input);
  const moveContext = {
    airborne: !fighter.grounded,
    crouching: fighter.crouch || Boolean(input.down),
    forwardHeld: direction.forwardHeld,
    limb: limb || input.limb || "punch",
  };
  const throwObjectAction = action === "throwObject" || action === "enhancedThrowObject";
  if (throwObjectAction && fighter.throwableUses <= 0) return false;
  if (throwObjectAction) {
    const profile = getThrowable(fighter.kitId);
    const activeObjects = state.projectiles.filter((projectile) => projectile.ownerSide === fighter.side && projectile.throwable === profile?.id);
    if (profile && activeObjects.length >= profile.maxActive) return false;
  }
  const throwObjectProfile = throwObjectAction
    ? createThrowObjectMove(fighter.kitId, {
      strength: input.heavy ? "heavy" : "light",
      enhanced: action === "enhancedThrowObject",
    })
    : null;
  if (throwObjectAction && !throwObjectProfile) return false;
  const kitMove = throwObjectProfile
    ? createAttackInstance(throwObjectProfile.baseKind, { ...throwObjectProfile, profileId: throwObjectProfile.id })
    : createFighterMove(fighter.kitId, action, moveContext);
  // The EX throwable carries its Grit price on the profile itself; the pip
  // cost below is shared with the base throw.
  const gritCost = throwObjectProfile
    ? (throwObjectProfile.gritCost || 0)
    : kitMove
      ? fighterActionCost(fighter.kitId, action, moveContext)
      : gritCostForAction(action);
  if (fighter.meter < gritCost) return false;
  const validLink = !cancelledFrom
    && fighter.linkWindow?.connected === "hit"
    && fighter.linkWindow.expiresFrame >= state.simulationTick
    && ["light", "heavy"].includes(actionGroup);
  const linkedFrom = validLink ? fighter.linkWindow.profileId : "";
  fighter.attacking = kitMove || (advancedActions.has(action)
    ? createAdvancedMove(action)
    : createCombatMove(action, moveContext));
  // R1.9 LEGEND: one-button specials trade ~10% damage. Deterministic: the
  // style is shared match config online (matchConfig.controlStyles) and the
  // single local setting offline, so both rollback peers scale identically.
  // CPU-driven seats never pay the tax.
  if (legendScaledAction(action) && activeControlStyle(fighter.side) === "legend"
    && !sideIsCpuControlled(fighter.side)) {
    fighter.attacking.damage = Number((fighter.attacking.damage * LEGEND_DAMAGE_SCALE).toFixed(4));
    fighter.attacking.chipDamage = Number(((fighter.attacking.chipDamage || 0) * LEGEND_DAMAGE_SCALE).toFixed(4));
  }
  if (fighter.def.boss) {
    fighter.attacking.damage = Number((fighter.attacking.damage * 1.08).toFixed(4));
    fighter.attacking.chipDamage = Number(((fighter.attacking.chipDamage || 0) * 1.08).toFixed(4));
    if (fighter.attacking.advanceSpeed) fighter.attacking.advanceSpeed *= 1.04;
  }
  fighter.attackSerial += 1;
  fighter.attacking.attackSerial = fighter.attackSerial;
  // Release 1.7 wave 11: QA counter for the derived forward command kicks
  // (their derive suffixes are the stable signature).
  if (!rollbackResimulating && /-(step-knee|axe-kick|slide)$/.test(fighter.attacking.profileId || "")) {
    mechFxDebug.commandKicks += 1;
  }
  // v2.1 PROGRESSION: per-move usage tally (render-only meta counters on the
  // mechFxDebug pattern; the guard keeps resimulated ticks from double-counting).
  if (!rollbackResimulating) progressionNoteMove(fighter);
  // v2.9 FLOW: demo coverage — every started move reports its action+context
  // so the choreographer's checklist and the recorded ids agree exactly.
  if (!rollbackResimulating && state.mode === "demo" && demoSession.choreo) {
    demoSession.choreo.noteMove(fighter.side, action, moveContext);
  }
  if (throwObjectProfile) {
    fighter.throwableUses = Math.max(0, fighter.throwableUses - 1);
    fighter.throwableSpawned = false;
    updateHud();
  }
  if (actionGroup === "throw") {
    fighter.attacking.backThrow = Boolean(backThrow ?? input.throwBack);
  }
  const activeFlow = fighter.def.id === "ali"
    && fighter.rhythmStacks > 0
    && state.simulationTick <= fighter.rhythmExpiresFrame;
  if (activeFlow) {
    const flow = fighter.rhythmStacks;
    fighter.attacking.rhythmBoost = flow;
    fighter.attacking.damage = Number((fighter.attacking.damage * (1 + flow * 0.035)).toFixed(4));
    if (fighter.attacking.advanceSpeed) fighter.attacking.advanceSpeed *= 1 + flow * 0.055;
    fighter.attacking.hitstunFrames += flow;
  }
  if (state.mode === "training" && fighter.side === 0) {
    // R1.9: the S/A/R computation is the shared attackFrameData helper now, so
    // this readout, the frame meter and the move list all agree by construction.
    const move = fighter.attacking;
    const data = attackFrameData(move);
    state.training.lastMove = {
      name: move.moveName || prettyProfileName(move.profileId, fighter.kitId) || move.kind,
      startup: data.startup,
      active: data.active,
      recovery: data.recovery,
      onHit: data.onHit,
      onBlock: data.onBlock,
      level: data.level,
    };
    state.training.lastAdvantage = null;
  }
  // 5.3: what the player actually SPENT — the GRIT ECONOMY rule needs the
  // difference between "had none" and "banked it and never cashed out".
  if (!rollbackResimulating && gritCost > 0 && fighter.side === 0 && !sideIsCpuControlled(0)) {
    progressionMatch.digest.meterSpent += gritCost;
  }
  fighter.meter = clamp(fighter.meter - gritCost, 0, GRIT_RULES.maximum);
  fighter.attackTime = 0;
  fighter.attackFrame = 0;
  fighter.attackHit = false;
  fighter.attackHits = 0;
  fighter.armorHits = 0;
  fighter.lastAttackHitFrame = -Infinity;
  fighter.attackConnected = "";
  fighter.cancelledFrom = cancelledFrom;
  // BLOCK ECONOMY: a fresh (non-cancel) swing opens a new string, so its
  // blocked special-into-special budget resets; tryAttackCancel spends it.
  if (!cancelledFrom) fighter.blockedSpecialCancels = 0;
  fighter.linkedFrom = linkedFrom;
  fighter.counterTriggered = false;
  fighter.trapDeployed = false;
  fighter.projectileSpawnFrames.clear();
  fighter.linkWindow = null;
  fighter.block = false;
  fighter.guarding = false;
  fighter.blockstunFrames = force ? 0 : fighter.blockstunFrames;
  fighter.hitstunFrames = force ? 0 : fighter.hitstunFrames;
  fighter.stun = force ? 0 : fighter.stun;
  fighter.dashFrames = 0;
  fighter.queuedDashDirection = 0;
  fighter.lastHitResult = reversal ? "reversal" : "";
  // BLOCK ECONOMY: reversal invulnerability is granted when the move is a
  // real reversal (wake-up window, guard reversal) or when it is paid for
  // (EX and super, gritCost > 0). Before this, every free back special and
  // launcher carrying reversalInvulnerableFrames was hurtbox-less from frame
  // 0 in NEUTRAL too, so Benny/Cyraxx/Ali could press ↓← at any time and hit
  // through anything. The field itself stays on the move so the same special
  // is still a genuine wake-up reversal.
  const invulnerableStart = reversal || (fighter.attacking.reversalInvulnerableFrames > 0 && gritCost > 0);
  if (invulnerableStart) {
    fighter.invulnerableFrames = Math.max(
      fighter.invulnerableFrames,
      fighter.attacking.reversalInvulnerableFrames || DEFENSE_RULES.reversalWindowFrames,
    );
  }
  if (reversal) {
    const label = action === "guardReversal" ? "GRIT REVERSAL" : "REVERSAL";
    fighter.lastHitResult = action === "guardReversal" ? "guard-reversal" : "reversal";
    spawnCombatText(fighter.x, fighter.y - fighter.height - 25, label, fighter.def.accent);
  }
  if (fighter.attacking.kind === "special") fighter.specialGlow = fighter.attacking.superMove ? 1.25 : 0.7;
  if (fighter.attacking.kind === "heavy" || fighter.attacking.kind === "special") spawnSweat(fighter, 4, 1.1);
  if (fighter.attacking.superMove) {
    if ($("#flashToggle").checked) state.flash = Math.max(state.flash, 0.22);
    state.hitstop = Math.max(state.hitstop, 0.09);
    spawnCombatText(fighter.x, fighter.y - fighter.height - 35, "FULL GRIT SUPER", fighter.def.accent);
    // Wave 7: portrait cut-in band + screen-space distortion ring, latched
    // module-level on the announce() pattern (rollback guard + tick dedupe).
    latchSuperPresentation(fighter);
  }
  if (linkedFrom) spawnCombatText(fighter.x, fighter.y - fighter.height - 20, "LINK", fighter.def.accent);
  // Release 1.7A CLEAN HITS: move names remain available in the move list and
  // training data, but normal play no longer narrates each attack over the
  // fighters. Tactical callouts such as COUNTER, LOW and GUARD CRUSH remain.
  updateHud();
  sound(attackSwingCue(fighter.attacking, actionGroup), fighter);
  // Release 1.6 LOUD: synthesized pre-impact whoosh layered under the swing
  // sample (guards + tier gating live inside).
  impactSwingWhoosh(fighter.attacking);
  return true;
}

const bufferedActions = [
  "jump",
  "throwObject",
  "enhancedThrowObject",
  "taunt",
  "throw",
  "super",
  "enhanced",
  "launcher",
  "driveHeavy",
  "commandSpecial",
  "light",
  "heavy",
  "special",
  ...KIT_ACTIONS,
];

function bufferActionInputs(fighter, input) {
  const limbPayload = input.limb === "kick" ? { limb: "kick" } : null;
  const throwPayload = input.throwBack ? { back: true } : null;
  for (const action of bufferedActions) {
    if (!input[action]) continue;
    const payload = action === "light" || action === "heavy" ? limbPayload
      : action === "throw" ? throwPayload
        : null;
    fighter.inputBuffer.push(action, state.simulationTick, payload);
  }
  fighter.inputBuffer.prune(state.simulationTick);
}

function trackDirectionalPresses(fighter, input) {
  const previous = fighter.previousDirectionalInput;
  for (const direction of ["left", "right"]) {
    if (input[direction] && !previous[direction]
      && fighter.directionTapTracker.press(direction, state.simulationTick)) {
      fighter.queuedDashDirection = direction === "right" ? 1 : -1;
    }
  }
  previous.left = Boolean(input.left);
  previous.right = Boolean(input.right);
}

// 5.3 CLOSE RANGE: two ranges, not one. `PROXIMITY_GRAB_RANGE` is what a
// throw REACHES (checked at the press and again at contact); the attempt band
// is where the press still COMMITS to the grab. Between them the throw comes
// out and misses — the whiff risk that used to be a free advancing light.
const PROXIMITY_GRAB_RANGE = THROW_RULES.grabRange;
const PROXIMITY_GRAB_ATTEMPT_RANGE = THROW_RULES.attemptRange;

function grabStateEligible(fighter, opponent) {
  return Boolean(opponent)
    && fighter.grounded
    && opponent.grounded
    && !opponent.down
    && opponent.wakeupFrames <= 0
    && opponent.hitstunFrames <= 0
    && opponent.blockstunFrames <= 0
    && opponent.throwInvulnerableFrames <= 0;
}

function inProximityGrabRange(fighter, opponent) {
  return grabStateEligible(fighter, opponent)
    && Math.abs(opponent.x - fighter.x) <= PROXIMITY_GRAB_RANGE;
}

// The commit band. Every state gate is identical — a press during a
// blockstring is still the frame trap, never a whiffed grab — only the
// distance is wider.
function inProximityGrabAttemptRange(fighter, opponent) {
  return grabStateEligible(fighter, opponent)
    && Math.abs(opponent.x - fighter.x) <= PROXIMITY_GRAB_ATTEMPT_RANGE;
}

/**
 * SF2-style proximity throw: touching a valid opponent and pressing toward or
 * away plus LP or LK grabs instead of throwing out the ordinary normal.
 *
 * 5.3 CLOSE RANGE: the press commits out to PROXIMITY_GRAB_ATTEMPT_RANGE
 * (140px scaled) while the throw only reaches PROXIMITY_GRAB_RANGE (104px
 * scaled), so →+LP just outside the clinch is a whiffed grab with a real
 * punish window instead of the old no-loss option-select (throw / tech /
 * safe advancing light). Beyond the attempt band the press is still an
 * ordinary normal.
 */
function applyProximityGrab(fighter, normalized) {
  if (state.phase !== "fight") return;
  if (!normalized.light || normalized.heavy || normalized.throw) return;
  if (fighter.attacking || fighter.hitstunFrames > 0 || fighter.blockstunFrames > 0) return;
  const direction = directionContext(fighter, normalized);
  if (!direction.forwardHeld && !direction.backHeld) return;
  // 5.3 CLOSE RANGE: a fighter already IN a clinch is ANSWERING the hold, and
  // the shortcut has to convert there too or the reaction tech would be
  // unreachable from a pad — the victim is lifted off the floor mid-clinch, so
  // the grounded and range gates below would refuse the very press the tech
  // window is waiting for. Nothing starts a move: updateFighter returns early
  // for a grabbed fighter; the press exists only to stamp lastThrowInputFrame,
  // which is what updateGrabHolds reads.
  if (!fighter.grabbed
    && !inProximityGrabAttemptRange(fighter, state.fighters[1 - fighter.side])) return;
  normalized.throw = true;
  normalized.throwBack = direction.backHeld;
  normalized.light = false;
  normalized.punch = false;
  normalized.kick = false;
}

function prepareFighterInput(fighter, input) {
  const side = fighter.side;
  const finishing = state.phase === "finish" && state.finishWinner === side;
  // Release 1.7 wave 11: double-tap-Down tracker for the taunt chord. Runs on
  // the raw down state before resolution, entirely on snapshotted fighter
  // fields, so both rollback peers arm and expire the window identically. A
  // second press only counts after a genuine release (dash-style edge), so a
  // slow quarter-circle can never arm it.
  const downHeld = Boolean(input?.down);
  if (downHeld && !fighter.downTapHeld) {
    if (state.simulationTick - fighter.downTapLastTick <= TAUNT_RULES.doubleTapWindowFrames) {
      fighter.tauntArmedUntilTick = state.simulationTick + TAUNT_RULES.armFrames;
    }
    fighter.downTapLastTick = state.simulationTick;
  }
  fighter.downTapHeld = downHeld;
  const tauntArmed = state.simulationTick <= fighter.tauntArmedUntilTick;
  const source = input?.fourButton
    ? resolveFourButtonInput(input, {
      facing: fighter.facing,
      style: activeControlStyle(side),
      meter: fighter.meter,
      finishing,
      finishArmed: state.finishArmed[side],
      tauntArmed,
    })
    : input;
  // The taunt travels as light+heavy+kick — a combination nothing else emits —
  // so remote bits, QA overrides and the AI's direct taunt flag all decode to
  // the same deliberate input.
  const tauntPressed = Boolean(source.taunt
    || (source.light && source.heavy && source.limb === "kick"));
  const normalPress = !tauntPressed && Boolean(source.light || source.heavy);
  const limb = source.limb === "kick" ? "kick" : "punch";
  const normalized = {
    left: Boolean(source.left),
    right: Boolean(source.right),
    down: Boolean(source.down),
    guard: Boolean(source.guard),
    jump: Boolean(source.jump),
    light: Boolean(source.light),
    heavy: Boolean(source.heavy),
    special: Boolean(source.special),
    enhanced: Boolean(source.enhanced),
    throw: Boolean(source.throw),
    throwBack: Boolean(source.throwBack),
    super: Boolean(source.super || (source.final && state.phase === "fight")),
    final: Boolean(source.final),
    finisherVariant: Number.isInteger(source.finisherVariant) ? source.finisherVariant : 0,
    limb,
    taunt: tauntPressed,
    punch: !tauntPressed && Boolean(source.punch ?? (normalPress && limb === "punch")),
    kick: !tauntPressed && Boolean(source.kick ?? (normalPress && limb === "kick")),
  };
  if (tauntPressed) {
    normalized.light = false;
    normalized.heavy = false;
  }
  for (const action of advancedActions) normalized[action] = Boolean(normalized[action] || source[action]);
  // R1.9: LEGEND expands its single special pulse against the held direction
  // here, inside the sim, identically on both rollback peers. The airborne
  // flag keeps the air special reachable from the one button.
  Object.assign(normalized, applyControlStyle(normalized, activeControlStyle(side), fighter.facing, {
    airborne: !fighter.grounded,
  }));
  recordInput(side, normalized, fighter);
  if (state.phase === "fight") {
    const command = recognizeFighterCommand(
      fighter.kitId,
      commandHistory[side],
      state.simulationTick,
      // The chord limb splits the down-back EX read: punch chord = EX back
      // special, kick chord = EX personal throwable.
      { limb: normalized.enhanced ? normalized.limb : "" },
    ) || recognizeCombatCommand(commandHistory[side], state.simulationTick);
    const terminal = command?.terminal
      || (command?.action === "commandSpecial" ? "special" : "heavy");
    const affordable = command?.action !== "super" || fighter.meter >= GRIT_RULES.superCost;
    if (command && affordable && normalized[terminal]) {
      normalized[command.action] = true;
      normalized.punch = false;
      normalized.kick = false;
      normalized.light = false;
      normalized.heavy = false;
      normalized.enhanced = false;
      commandHistory[side].splice(0, command.endIndex + 1);
      // R1.9: motion-recognition flash for the training input column — a
      // render-side latch on the announce() pattern, fired exactly when the
      // recognizer consumes the tokens.
      if (!rollbackResimulating && state.mode === "training" && side === 0) {
        latchInputColumnFlash(command.action, fighter);
      }
    }
    // A completed motion always beats the proximity grab shortcut, so close-range
    // command specials stay reachable while touching an opponent.
    applyProximityGrab(fighter, normalized);
    bufferActionInputs(fighter, normalized);
    trackDirectionalPresses(fighter, normalized);
    if (normalized.throw) fighter.lastThrowInputFrame = state.simulationTick;
  }
  return normalized;
}

function recoverFromDizzy(fighter) {
  fighter.dizzyFrames = 0;
  fighter.dizzyTotalFrames = 0;
  fighter.dizzyMashCount = 0;
  fighter.stunMeter = 0;
  fighter.stunDecayDelay = 0;
  // A long immunity after recovery is what makes dizzy loops impossible.
  fighter.stunImmuneFrames = STUN_RULES.immuneFrames;
  fighter.hitstunFrames = 0;
  fighter.stun = 0;
  fighter.invulnerableFrames = Math.max(fighter.invulnerableFrames, 6);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 40, "SHAKE IT OFF", fighter.def.accent);
  sound("block", fighter);
}

function enterDizzy(fighter, attacker) {
  // Release 1.8 GRIND: score attack — dizzying the CPU banks a tally bonus
  // (guarded meta bookkeeping; no sim state involved).
  awardDizzyScore(attacker);
  // v2.1 PROGRESSION: per-match dizzy tally for the attacker (guarded).
  if (!rollbackResimulating && (attacker?.side === 0 || attacker?.side === 1)) {
    progressionMatch.dizzies[attacker.side] += 1;
  }
  // v2.9 FLOW: the dizzy animation belongs to the wobbling fighter.
  demoChoreoBeat(fighter.side, "dizzy");
  fighter.dizzyFrames = STUN_RULES.dizzyFrames;
  fighter.dizzyTotalFrames = STUN_RULES.dizzyFrames;
  fighter.dizzyMashCount = 0;
  fighter.stunMeter = 0;
  fighter.stunDecayDelay = 0;
  fighter.attacking = null;
  fighter.attackFrame = 0;
  fighter.attackTime = 0;
  fighter.hitstunFrames = 0;
  fighter.blockstunFrames = 0;
  fighter.stun = 0;
  fighter.block = false;
  fighter.guarding = false;
  fighter.dashFrames = 0;
  fighter.queuedDashDirection = 0;
  fighter.inputBuffer.clear();
  fighter.lastHitResult = "dizzy";
  state.hitstop = Math.max(state.hitstop, 0.16);
  state.shake = Math.max(state.shake, 0.34);
  if ($("#flashToggle").checked) state.flash = Math.max(state.flash, 0.2);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 52, "DIZZY", "#ffd54a");
  duckMusic(0.55, 620);
  // w51 announcer truth: a dizzy is a stun the fighter recovers from, so it
  // must not play knockout.mp3 (the same reviewed KO groan a real KO uses —
  // for the Commissioner/Devil their ko take is "the book hitting the
  // floor"). The stars get their own synthesised ring instead; the fighter's
  // dazed voice bark still layers over it below.
  dizzyRingAudio(fighter);
  // Wave 15: the dizzy flutters in the hands (all gates inside).
  combatHaptic("dizzy");
  // Wave 9: dazed voice bark layered over the ring (guarded + tick-deduped).
  fighterReactiveCue(fighter, "dizzy");
  // Wave 6: camera pop on the dizzy trigger (render-only latch, guarded +
  // tick-deduped inside).
  latchDizzyCameraPunch(fighter);
}

// Mashing buttons and directions shortens the dizzy but never removes the punish
// window: the timer can never drop below STUN_RULES.minimumDizzyFrames elapsed.
function relieveDizzy(fighter, input) {
  const pressed = Boolean(input.light || input.heavy || input.special
    || input.enhanced || input.super || input.jump || input.throw);
  const directional = Boolean(input.left || input.right || input.down);
  if (!pressed && !(directional && state.simulationTick % 4 === 0)) return;
  fighter.dizzyMashCount += 1;
  const elapsed = fighter.dizzyTotalFrames - fighter.dizzyFrames;
  const floor = Math.max(0, STUN_RULES.minimumDizzyFrames - elapsed);
  fighter.dizzyFrames = Math.max(floor, fighter.dizzyFrames - STUN_RULES.mashRelief);
}

// Release 1.7 wave 11 — the punishable taunt. ~45 fully vulnerable frames in
// the fighter's victory pose. The voice line is drawn from state.rng HERE, in
// the simulation, so both rollback peers rotate identically (the draw itself
// must never be resim-guarded — only the audible side effects are).
function performTaunt(fighter) {
  if (fighter.tauntFrames > 0) return;
  fighter.tauntFrames = TAUNT_RULES.durationFrames;
  fighter.tauntTotalFrames = TAUNT_RULES.durationFrames;
  fighter.tauntArmedUntilTick = -Infinity;
  fighter.vx = 0;
  fighter.block = false;
  fighter.guarding = false;
  fighter.crouch = false;
  const lines = FIGHTER_TAUNT_LINES[fighter.kitId]?.length || TAUNT_RULES.voiceLines;
  fighter.tauntLine = Math.floor(random() * lines) % lines;
  if (!rollbackResimulating) {
    mechFxDebug.taunts += 1;
    // v2.1 PROGRESSION: Black Book showboat entry (guarded, P1 seat only).
    progressionEvent("taunt", {}, fighter.side);
  }
  // v2.9 FLOW: demo coverage beat (guarded inside).
  demoChoreoBeat(fighter.side, "taunt");
  spawnCombatText(fighter.x, fighter.y - fighter.height - 44, "TAUNT", fighter.def.accent);
  stirCrowd(0.25, "", { side: fighter.side });
  // v5.1 KO MOMENT: the crowd answers the showboat out loud. 0.25 sits under
  // the 0.5 swell latch, so this is its own render-side cue (resim-guarded
  // inside): an "oooh" at taunt level, never the roar.
  playCrowdVoice("ooh", 0.25, { source: "taunt" });
  fighterTauntCue(fighter, fighter.tauntLine);
}

function interruptTaunt(fighter) {
  fighter.tauntFrames = 0;
  fighter.tauntTotalFrames = 0;
}

function completeTaunt(fighter) {
  fighter.tauntTotalFrames = 0;
  if (fighter.tauntGritGranted) return;
  fighter.tauntGritGranted = true;
  fighter.meter = clamp(fighter.meter + TAUNT_RULES.gritBonus, 0, GRIT_RULES.maximum);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 40, `+${TAUNT_RULES.gritBonus} GRIT`, fighter.def.accent);
  updateHud();
}

function addStun(victim, attacker, attack, { counter = false, blocked = false } = {}) {
  if (victim.stunImmuneFrames > 0 || victim.dizzyFrames > 0) return;
  const gain = stunGainForAttack(attack, { counter, blocked });
  if (gain <= 0) return;
  victim.stunMeter = Number((victim.stunMeter + gain).toFixed(3));
  victim.stunDecayDelay = STUN_RULES.decayGraceFrames;
  if (victim.stunMeter >= STUN_RULES.threshold) enterDizzy(victim, attacker);
}

function enterKnockdown(fighter) {
  // v2.9 FLOW: demo coverage beat (guarded inside; no-op outside the demo).
  demoChoreoBeat(fighter.side, "knockdown");
  fighter.pendingKnockdown = false;
  // Landing before reaching the wall forfeits the pending bounce conversion.
  fighter.wallBounceArmed = 0;
  if (fighter.tauntFrames > 0) interruptTaunt(fighter);
  // 5.3: the one entry point every knockdown funnels through (guarded meta).
  if (!rollbackResimulating && fighter.side === 0 && !sideIsCpuControlled(0)) {
    progressionMatch.digest.knockdownsTaken += 1;
  }
  fighter.down = true;
  fighter.knockdownFrames = DEFENSE_RULES.knockdownFrames;
  fighter.wakeupFrames = 0;
  fighter.hitstunFrames = 0;
  fighter.blockstunFrames = 0;
  fighter.vx *= 0.28;
  fighter.vy = 0;
  fighter.attacking = null;
  // Release 1.7: a fresh knockdown resets the wake-up option and any pending
  // air-recovery eligibility — the juggle is over.
  fighter.wakeOption = "";
  fighter.airTechArmed = false;
  fighter.airHitstunFrames = 0;
  fighter.airTechFlipFrames = 0;
  fighter.airTechTaxPending = false;
  fighter.inputBuffer.clear();
}

// v5.3 SPECTACLE (ko-collapse): the plain KO's collapse, spent at the
// finish->roundover edge. It is enterKnockdown and nothing else — the same
// flags, the same countdown, so the crumple -> KO-lie drawing, the prone
// down-tilt (2D `downTiltFor`, CINEMA 3D `proneTransform` over the same host
// bridge member) and the settle on the boards all come for free in both
// renderers, and the sim gains no new field to snapshot.
//
// The three lines before it undo what the STAND-OFF needed: checkKnockout
// parked the victim on 99 stun and 5940 hitstun frames so he would stay dazed
// and upright for the 6 s window, and the pose read is ordered
// dizzy -> hitstun -> down, so a body left holding either of those would draw
// a standing reel over a fighter who is lying on the street. A KO'd fighter
// is not reeling and is not in hitstun; he is on the floor.
function collapseKoLoser(fighter) {
  fighter.stun = 0;
  fighter.hitstunFrames = 0;
  fighter.dizzyFrames = 0;
  fighter.dizzyTotalFrames = 0;
  fighter.guardCrushFrames = 0;
  enterKnockdown(fighter);
}

// The moment the collapsing body reaches the boards — the crumple band's last
// tick, ~117 ms after the flag, never the phase edge with the fighter still
// upright. It is the knockdown landing the game already has: a small dust
// puff (force floors at 0.55, so 8 motes and a 102 px floor ring), the scuff
// scar, and the thud, which resolves `hit-heavy` -> the shared body-hit take
// through the 5.1 per-play jitter (±8% pitch, ±1.5 dB, no two consecutive
// draws alike — engine/shared-sfx.mjs). No fighter has a signature hit-heavy
// take, so the shared pool is always what plays here.
const KO_COLLAPSE_LANDING_VELOCITY = 320;

function spawnKoCollapseLanding(fighter) {
  spawnKnockdownImpact(fighter, KO_COLLAPSE_LANDING_VELOCITY);
}

// Release 1.7: guard gauge — the addStun mirror for BLOCKED pressure. Fed
// from the blocked branch of hit() where blockstunFrames is set; immune and
// already-crushed defenders take no pressure, and a Perfect Guard absorbs the
// gain entirely inside guardGainForAttack.
function addGuardPressure(victim, attacker, attack, { perfect = false } = {}) {
  if (victim.guardImmuneFrames > 0 || victim.guardCrushFrames > 0) return;
  const gain = guardGainForAttack(attack, { blocked: true, perfect });
  if (gain <= 0) return;
  victim.guardMeter = Number((victim.guardMeter + gain).toFixed(3));
  victim.guardDecayDelay = GUARD_RULES.decayGraceFrames;
  if (victim.guardMeter >= GUARD_RULES.threshold) enterGuardCrush(victim, attacker);
}

// GUARD CRUSH: the enterDizzy path re-used for the shattered guard — the
// fighter is briefly helpless, with its own immunity window on recovery so a
// crush can never loop. All spectacle routes through the existing wave 1-9
// systems from this sim event, never the other way round.
function enterGuardCrush(fighter, attacker) {
  fighter.guardMeter = 0;
  fighter.guardDecayDelay = 0;
  fighter.guardCrushFrames = GUARD_RULES.crushFrames;
  fighter.guardCrushTotalFrames = GUARD_RULES.crushFrames;
  fighter.attacking = null;
  fighter.attackFrame = 0;
  fighter.attackTime = 0;
  fighter.hitstunFrames = 0;
  fighter.blockstunFrames = 0;
  fighter.stun = 0;
  fighter.block = false;
  fighter.guarding = false;
  fighter.dashFrames = 0;
  fighter.queuedDashDirection = 0;
  fighter.inputBuffer.clear();
  fighter.lastHitResult = "guard-crush";
  state.hitstop = Math.max(state.hitstop, 0.14);
  state.shake = Math.max(state.shake, 0.3);
  if ($("#flashToggle").checked) state.flash = Math.max(state.flash, 0.16);
  if (!rollbackResimulating) {
    mechFxDebug.guardCrushes += 1;
    // v2.1 PROGRESSION: the crusher's ledger tally (guarded, P1 seat only).
    if (attacker) progressionEvent("guardCrush", {}, attacker.side);
  }
  spawnCombatText(fighter.x, fighter.y - fighter.height - 52, "GUARD CRUSH", "#7de8ff");
  // Announcer letter-slam banner + its spoken bank cue (announce() carries the
  // resim guard and books the guardcrush announcer bank).
  announce("GUARD CRUSH", "", 1.05);
  duckMusic(0.55, 620);
  sound("block", fighter);
  // Wave 9: crush-specific reactive voice bark (guarded + tick-deduped).
  fighterReactiveCue(fighter, "crush");
  // Wave 6: camera punch-in on the shatter (render-only latch).
  latchGuardCrushCameraPunch(fighter);
  if (attacker) state.lastImpactSide = attacker.side;
}

function recoverFromGuardCrush(fighter) {
  fighter.guardCrushFrames = 0;
  fighter.guardCrushTotalFrames = 0;
  fighter.guardMeter = 0;
  fighter.guardDecayDelay = 0;
  // The long immunity after recovery is what makes crush loops impossible.
  fighter.guardImmuneFrames = GUARD_RULES.immuneFrames;
  fighter.hitstunFrames = 0;
  fighter.stun = 0;
  fighter.invulnerableFrames = Math.max(fighter.invulnerableFrames, 6);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 40, "GUARD RESTORED", fighter.def.accent);
  sound("block", fighter);
}

// Release 1.7: air recovery (juggle tech) — escapes the juggle into a brief
// invulnerable back-flip; the landing tax is applied by applyFighterPhysics.
function performAirRecovery(fighter) {
  // 5.3: an air tech is a tech too — the OFF THE FLOOR rule reads both.
  if (!rollbackResimulating && fighter.side === 0 && !sideIsCpuControlled(0)) {
    progressionMatch.digest.techs += 1;
  }
  fighter.pendingKnockdown = false;
  fighter.wallBounceArmed = 0;
  fighter.hitstunFrames = 0;
  fighter.stun = 0;
  fighter.airTechArmed = false;
  fighter.airHitstunFrames = 0;
  fighter.airTechFlipFrames = AIR_RECOVERY_RULES.flipFrames;
  fighter.airTechTaxPending = true;
  fighter.invulnerableFrames = Math.max(fighter.invulnerableFrames, AIR_RECOVERY_RULES.invulnerableFrames);
  fighter.vx = -fighter.facing * AIR_RECOVERY_RULES.driftVelocityX;
  fighter.vy = Math.min(fighter.vy, AIR_RECOVERY_RULES.liftVelocityY);
  fighter.lastHitResult = "air-tech";
  if (!rollbackResimulating) mechFxDebug.airRecoveries += 1;
  spawnCombatText(fighter.x, fighter.y - fighter.height - 44, "AIR TECH", fighter.def.accent);
  // Wave 9: the throw-tech shout reads naturally on an air tech too.
  fighterReactiveCue(fighter, "tech");
}

function advanceFighterTimers(fighter) {
  fighter.justWoke = false;
  fighter.hitFlash = Math.max(0, fighter.hitFlash - SIMULATION_STEP_SECONDS);
  fighter.specialGlow = Math.max(0, fighter.specialGlow - SIMULATION_STEP_SECONDS);
  fighter.invulnerableFrames = Math.max(0, fighter.invulnerableFrames - 1);
  fighter.throwInvulnerableFrames = Math.max(0, fighter.throwInvulnerableFrames - 1);
  fighter.dashCooldownFrames = Math.max(0, fighter.dashCooldownFrames - 1);
  fighter.attackRearmFrames = Math.max(0, fighter.attackRearmFrames - 1);
  fighter.reversalWindowFrames = Math.max(0, fighter.reversalWindowFrames - 1);
  fighter.throwTechFlashFrames = Math.max(0, fighter.throwTechFlashFrames - 1);
  fighter.confirmWindowFrames = Math.max(0, fighter.confirmWindowFrames - 1);
  fighter.landingRecoveryFrames = Math.max(0, fighter.landingRecoveryFrames - 1);
  fighter.stunImmuneFrames = Math.max(0, fighter.stunImmuneFrames - 1);
  fighter.slowFrames = Math.max(0, (fighter.slowFrames || 0) - 1);
  if (fighter.dizzyFrames > 0) {
    fighter.dizzyFrames -= 1;
    if (fighter.dizzyFrames === 0) recoverFromDizzy(fighter);
  } else if (fighter.stunDecayDelay > 0) {
    fighter.stunDecayDelay -= 1;
  } else if (fighter.stunMeter > 0) {
    fighter.stunMeter = Math.max(0, Number((fighter.stunMeter - STUN_RULES.decayPerFrame).toFixed(3)));
  }
  // Release 1.7: guard gauge clocks — the stun decay chain mirrored exactly.
  fighter.guardImmuneFrames = Math.max(0, fighter.guardImmuneFrames - 1);
  fighter.airTechFlipFrames = Math.max(0, fighter.airTechFlipFrames - 1);
  if (fighter.guardCrushFrames > 0) {
    fighter.guardCrushFrames -= 1;
    if (fighter.guardCrushFrames === 0) recoverFromGuardCrush(fighter);
  } else if (fighter.guardDecayDelay > 0) {
    fighter.guardDecayDelay -= 1;
  } else if (fighter.guardMeter > 0) {
    fighter.guardMeter = Math.max(0, Number((fighter.guardMeter - GUARD_RULES.decayPerFrame).toFixed(3)));
  }
  // Release 1.7: airborne-hitstun clock for the juggle-tech window.
  if (!fighter.grounded && fighter.pendingKnockdown) fighter.airHitstunFrames += 1;
  else fighter.airHitstunFrames = 0;
  if (fighter.rhythmStacks > 0 && state.simulationTick > fighter.rhythmExpiresFrame) {
    fighter.rhythmStacks = 0;
    fighter.rhythmExpiresFrame = 0;
    fighter.rhythmLastAttackSerial = -1;
    if (fighter.def.id === "ali") spawnCombatText(fighter.x, fighter.y - fighter.height - 20, "FLOW LOST", fighter.def.accent);
  }

  if (fighter.down && fighter.grounded) {
    // v5.3 SPECTACLE (ko-collapse): a DECIDED round's KO lie holds. The
    // knockdown countdown is 48 ticks and the roundover hold is 294, so
    // without this the loser stands up 0.8 s into the winner's curtain call
    // and plays a wake-up rung off a KO. The countdown still runs (the
    // crumple -> KO-lie handover reads it); it floors at 1, so `wakeupFrames`
    // is never armed and the result screen and the rematch open on a clean
    // fighter. Purely derived from snapshotted fields — see
    // engine/bookends koCollapseHolds — so a resim agrees without a new field.
    const koLie = koCollapseHolds({
      phase: state.phase,
      finisher: Boolean(state.finisher),
      finisherType: state.finisherType,
      health: fighter.health,
      down: true,
    });
    if (koLie && fighter.knockdownFrames <= 1) {
      fighter.knockdownFrames = 1;
    } else {
      fighter.knockdownFrames = Math.max(0, fighter.knockdownFrames - 1);
      if (koLie && koCollapseThudTick(fighter.knockdownFrames, DEFENSE_RULES.knockdownFrames)) {
        spawnKoCollapseLanding(fighter);
      }
      if (fighter.knockdownFrames === 0) {
        fighter.down = false;
        fighter.wakeupFrames = DEFENSE_RULES.wakeupFrames;
        // 5.3 CLOSE RANGE: the throw immunity is no longer a flat 40 on EVERY
        // knockdown. 40 is the anti-throw-loop rule and belongs to throws and
        // techs; a strike knockdown pays 8, so a command grab is a legal (and
        // readable) wake-up option instead of a mechanical impossibility.
        fighter.throwInvulnerableFrames = fighter.throwKnockdown
          ? DEFENSE_RULES.throwInvulnerableFrames
          : DEFENSE_RULES.strikeKnockdownThrowImmuneFrames;
        fighter.throwKnockdown = false;
      }
    }
  } else if (fighter.wakeupFrames > 0) {
    fighter.wakeupFrames -= 1;
    // 5.3 OKIZEME: the last rising frames carry hurtboxes, so their stun
    // clocks have to run too — otherwise a meaty's hitstun would freeze until
    // the fighter finished standing up and the move's frame data would lie.
    fighter.hitstunFrames = Math.max(0, fighter.hitstunFrames - 1);
    fighter.blockstunFrames = Math.max(0, fighter.blockstunFrames - 1);
    if (fighter.wakeupFrames === 0) {
      // A meaty that connected (or was blocked) on the rising frames cancels
      // the reversal grant: you were touched before you stood up, so there is
      // no invulnerable window to reverse out of. Without this a landed meaty
      // handed the victim 4 invulnerable frames mid-hitstun and dropped the
      // combo it had just earned.
      const meatied = fighter.hitstunFrames > 0 || fighter.blockstunFrames > 0;
      fighter.juggleCount = 0;
      // The combo is over: the once-per-combo wall bounce re-arms with it.
      fighter.wallBounceUsed = false;
      // Release 1.7: a quick rise trades a slightly shorter reversal window
      // for getting up early. The delay option keeps the full window.
      const reversalFrames = meatied ? 0 : fighter.wakeOption === "quick"
        ? Math.max(1, DEFENSE_RULES.reversalWindowFrames - WAKEUP_RULES.quickRiseReversalPenaltyFrames)
        : DEFENSE_RULES.reversalWindowFrames;
      fighter.justWoke = !meatied;
      fighter.reversalWindowFrames = reversalFrames;
      fighter.invulnerableFrames = reversalFrames;
      fighter.wakeOption = "";
      spawnSweat(fighter, 5, 0.9);
    }
  } else {
    fighter.hitstunFrames = Math.max(0, fighter.hitstunFrames - 1);
    fighter.blockstunFrames = Math.max(0, fighter.blockstunFrames - 1);
  }
  fighter.stun = Math.max(fighter.hitstunFrames, fighter.blockstunFrames) / SIMULATION_HZ;
}

function startDash(fighter, direction) {
  const forward = direction === fighter.facing;
  fighter.dashDirection = direction;
  fighter.dashFrames = forward ? fighter.movement.forwardDashFrames : fighter.movement.backDashFrames;
  fighter.dashCooldownFrames = fighter.dashFrames + fighter.movement.dashCooldownFrames;
  fighter.queuedDashDirection = 0;
  fighter.block = false;
  fighter.guarding = false;
  fighter.crouch = false;
  if (!forward) fighter.invulnerableFrames = Math.max(fighter.invulnerableFrames, fighter.movement.backDashInvulnerableFrames);
  spawnFootDust(fighter, 6, 30, direction);
  sound("dash", fighter);
}

function spawnFootDust(fighter, count, spread, kick) {
  const total = Math.max(2, Math.round(count * state.performance.particleScale));
  for (let index = 0; index < total; index += 1) {
    const side = kick !== 0 ? -Math.sign(kick) : (visualRandom() < 0.5 ? -1 : 1);
    state.particles.push({
      kind: "dust",
      x: fighter.x + (visualRandom() - 0.5) * spread,
      y: FLOOR - 2,
      vx: side * (30 + visualRandom() * 130) + kick * 60,
      vy: -25 - visualRandom() * 85,
      gravity: 400,
      drag: 0.955,
      life: 0.2 + visualRandom() * 0.3,
      max: 0.5,
      size: 3 + visualRandom() * 7,
      color: visualRandom() > 0.4 ? "#777067" : "#4e4a46",
    });
  }
}

// SF2-style sweat spray: below 40% health, heavy exertions (big attacks,
// wake-ups, landings) fling glinting droplets off the fighter's head — harder
// still under 25%. Presentation-only: visualRandom + checksum-exempt
// state.particles, trimmed by the shared particle budget.
function spawnSweat(fighter, count, energy = 1) {
  if (fighter.health > 40) return;
  const strain = fighter.health < 25 ? 1.35 : 1;
  const total = Math.max(2, Math.round(count * strain * state.performance.particleScale));
  const headY = fighter.y - fighter.height * 0.94;
  for (let index = 0; index < total; index += 1) {
    const angle = -Math.PI / 2 + (visualRandom() - 0.5) * 2.3;
    const speed = (110 + visualRandom() * 210) * energy;
    state.particles.push({
      kind: "sweat",
      x: fighter.x + (visualRandom() - 0.5) * 34,
      y: headY + (visualRandom() - 0.5) * 20,
      vx: Math.cos(angle) * speed + fighter.vx * 0.12,
      vy: Math.sin(angle) * speed - 40,
      gravity: 780,
      drag: 0.982,
      life: 0.24 + visualRandom() * 0.26,
      max: 0.5,
      size: 1.8 + visualRandom() * 2.2,
      color: index % 3 ? "#d9f1ff" : "#9fd7ff",
    });
  }
}

function spawnKnockdownImpact(fighter, landingVelocity) {
  const force = clamp(Math.abs(landingVelocity) / 760, 0.55, 1.35);
  const count = Math.max(5, Math.round(14 * force * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const direction = visualRandom() < 0.5 ? -1 : 1;
    state.particles.push({
      kind: "dust",
      x: fighter.x + (visualRandom() - 0.5) * 54,
      y: FLOOR - 3,
      vx: direction * (40 + visualRandom() * 210) * force,
      vy: -35 - visualRandom() * 150 * force,
      gravity: 440,
      drag: 0.96,
      life: 0.25 + visualRandom() * 0.42,
      max: 0.67,
      size: 4 + visualRandom() * 10,
      color: visualRandom() > 0.4 ? "#777067" : "#4e4a46",
    });
  }
  state.effects.push({
    kind: "floorImpact", x: fighter.x, y: FLOOR - 4,
    width: 62 + force * 74, life: 0.44, max: 0.44, color: "#b7a99a",
  });
  // The arena wears the fight: a persistent mark under the impact, in the
  // flavour this stage's floor leaves (5.3: crack/skid on asphalt, splinter
  // on the boards, splash on the wet deck, cracked tile and spilled food at
  // the buffet, a dented rut in Janney's rubble).
  pushStageScar(fighter.x, force, { cause: "knockdown" });
  if (state.graphicFatalities) {
    const life = 2.4 + force;
    state.effects.push({
      kind: "bloodDecal", tier: "heavy", x: fighter.x, y: FLOOR + 3,
      width: 28 + force * 34, life, max: life, color: "#65060c",
    });
  }
  applyViolenceResponse(force > 1.08 ? "throw" : "heavy", {
    side: state.fighters[1 - fighter.side] ? 1 - fighter.side : -1,
    splatX: fighter.x,
  });
  sound("hit-heavy", state.fighters[state.lastImpactSide] || fighter);
}

// --- Corner wall-splat (wave 4): the arena edge answers a slammed fighter ---
// A vertical dust column erupts off the invisible wall, stage-toned debris
// chips spray and tumble down, and a tall shock ellipse marks the slam.
// Fired from applyFighterPhysics when the stage clamp actually arrests a fast
// hitstun/knockdown flight. Presentation only: everything lands in the
// checksum-exempt particle/effect arrays. The per-side cooldown tick lives
// module-level on the documented superDimLevel pattern (never snapshotted):
// re-executing the same or an earlier tick after a rollback restore re-fires
// the spawn (the restored arrays lost it), while the strictly-later ticks of a
// normal wall grind dedupe inside the window.
const WALL_SPLAT_COOLDOWN_TICKS = 22;
const wallSplatLastTick = [-Infinity, -Infinity];

function spawnWallImpact(fighter, wallDirection) {
  const tick = state.simulationTick;
  const last = wallSplatLastTick[fighter.side];
  if (tick > last && tick - last < WALL_SPLAT_COOLDOWN_TICKS) return;
  wallSplatLastTick[fighter.side] = tick;
  // v2.9 FLOW: demo coverage beat — counted per distinct splat (the cooldown
  // above dedupes wall grinds exactly like the presentation burst).
  demoChoreoBeat(fighter.side, "wallsplat");
  // Wave 7: a wall splat is a heavy moment — kick the RGB-split impulse.
  // Module-level render-only latch; profile/accessibility gates apply at draw.
  if (!rollbackResimulating) aberrationImpulse = Math.max(aberrationImpulse, 0.55);
  // Wave 15: the corner answers in the hands too — double pulse.
  combatHaptic("wallSplat");
  const wallX = wallDirection < 0
    ? MOVEMENT_RULES.stageMinX - 30
    : MOVEMENT_RULES.stageMaxX + 30;
  const impactY = fighter.y - fighter.height * 0.55;
  const force = clamp(Math.abs(fighter.vx) / 640, 0.6, 1.3);
  // 5.3 SPECTACLE (#19): the arena EDGE wears the fight too. Until now a
  // wall splat left dust that blew away in half a second and nothing else,
  // even though it is the loudest thing that happens to the geometry. The
  // mark stands up on the wall (wall: ±1) at the height the body hit it,
  // in the stage material's own flavour.
  pushStageScar(
    wallDirection < 0 ? MOVEMENT_RULES.stageMinX : MOVEMENT_RULES.stageMaxX,
    force,
    { cause: "wall", wall: wallDirection, y: impactY },
  );
  const dustCount = Math.max(5, Math.round(15 * force * state.performance.particleScale));
  for (let index = 0; index < dustCount; index += 1) {
    state.particles.push({
      kind: "dust",
      x: wallX + wallDirection * visualRandom() * 10,
      y: FLOOR - visualRandom() * (fighter.height + 44),
      vx: -wallDirection * (30 + visualRandom() * 170) * force,
      vy: -60 - visualRandom() * 240 * force,
      gravity: 420,
      drag: 0.955,
      life: 0.22 + visualRandom() * 0.4,
      max: 0.62,
      size: 3.5 + visualRandom() * 8,
      color: visualRandom() > 0.4 ? "#777067" : "#4e4a46",
    });
  }
  const chipCount = Math.max(3, Math.round(8 * force * state.performance.particleScale));
  for (let index = 0; index < chipCount; index += 1) {
    state.particles.push({
      kind: "debris",
      x: wallX,
      y: impactY + (visualRandom() - 0.5) * fighter.height * 0.8,
      vx: -wallDirection * (60 + visualRandom() * 260) * force,
      vy: -120 - visualRandom() * 190,
      gravity: 980,
      drag: 0.985,
      spin: (visualRandom() - 0.5) * 18,
      rotation: visualRandom() * Math.PI,
      life: 0.34 + visualRandom() * 0.42,
      max: 0.76,
      size: 2.4 + visualRandom() * 3.6,
      color: visualRandom() > 0.5 ? "#8a8175" : "#635c52",
    });
  }
  state.effects.push({
    kind: "wallShock",
    x: wallX - wallDirection * 6,
    y: impactY,
    size: 66 + force * 44,
    direction: -wallDirection,
    life: 0.3,
    max: 0.3,
    color: "#e9dfc8",
  });
  state.shake = Math.max(state.shake, 0.2 * force); // checksum-exempt, like flash
}

function applyFighterPhysics(fighter, dt) {
  fighter.vy += GRAVITY * dt;
  // Wave 17 — the Pinelands Devil's wing-glide: his authored movement caps
  // descent speed during any CONTROLLED airborne state, so his jump hangs
  // like something that owns the air. Pure function of already-snapshotted
  // fields (vy, grounded, hitstun/knockdown/grab state) and a static kit
  // constant: rollback resimulation reproduces it exactly and no new state
  // field exists to snapshot. Hitstun, juggles, knockdowns and grabs fall at
  // full gravity like everyone else — the wings only work when he does.
  const glideCap = fighter.movement.glideFallCap;
  if (glideCap > 0 && fighter.vy > glideCap && !fighter.grounded
    && !fighter.down && !fighter.pendingKnockdown && !fighter.grabbed
    && fighter.hitstunFrames === 0 && fighter.dizzyFrames === 0) {
    fighter.vy = glideCap;
  }
  fighter.x += fighter.vx * dt;
  fighter.y += fighter.vy * dt;
  if (fighter.y >= FLOOR) {
    const landed = !fighter.grounded;
    const landingVelocity = fighter.vy;
    const violentLanding = landed && fighter.pendingKnockdown;
    fighter.y = FLOOR;
    fighter.vy = 0;
    fighter.grounded = true;
    if (fighter.pendingKnockdown) {
      enterKnockdown(fighter);
      if (violentLanding) spawnKnockdownImpact(fighter, landingVelocity);
    }
    else if (landed && fighter.attacking?.profileId.startsWith("air-")) {
      fighter.attacking = null;
      fighter.attackTime = 0;
      fighter.attackFrame = 0;
      fighter.landingRecoveryFrames = DEFENSE_RULES.airAttackLandingRecoveryFrames;
      // An attack on the way down supersedes the air-tech tax — same price.
      fighter.airTechTaxPending = false;
      fighter.airTechFlipFrames = 0;
      spawnFootDust(fighter, 8, 48, 0);
      spawnSweat(fighter, 3, 1);
    } else if (landed && fighter.airTechTaxPending) {
      // Release 1.7: the air-recovery landing tax — the existing air-attack
      // landing recovery, so a read meaty still punishes the escape.
      fighter.airTechTaxPending = false;
      fighter.airTechFlipFrames = 0;
      fighter.juggleCount = 0;
      fighter.wallBounceUsed = false;
      fighter.landingRecoveryFrames = Math.max(fighter.landingRecoveryFrames, DEFENSE_RULES.airAttackLandingRecoveryFrames);
      spawnFootDust(fighter, 8, 48, 0);
      spawnSweat(fighter, 3, 1);
    } else if (landed && !fighter.down) {
      // Even an empty jump costs a few frames on the way down.
      fighter.landingRecoveryFrames = Math.max(fighter.landingRecoveryFrames, DEFENSE_RULES.landingRecoveryFrames);
      spawnFootDust(fighter, 6, 44, 0);
      spawnSweat(fighter, 3, 0.8);
    }
  } else {
    fighter.grounded = false;
  }
  const preClampX = fighter.x;
  fighter.x = clamp(fighter.x, MOVEMENT_RULES.stageMinX, MOVEMENT_RULES.stageMaxX);
  if (fighter.x !== preClampX && (fighter.hitstunFrames > 0 || fighter.pendingKnockdown)) {
    const wallDirection = preClampX < MOVEMENT_RULES.stageMinX ? -1 : 1;
    // Release 1.7 wave 11: the armed knockdown converts at the wall into the
    // splat freeze + juggleable rebound. Otherwise the wave-4 presentation
    // splat fires exactly as before: hitstun bleeds vx 10% per tick before
    // physics runs, so a cornered victim reaches the clamp with 0.9x the
    // attack's push — 220 keeps the burst for heavy/special/throw-grade
    // slams (push 260-405+, arriving at 234+) and never light pokes
    // (145-210, arriving under 190).
    if (fighter.wallBounceArmed === wallDirection && !fighter.wallBounceUsed) {
      performWallBounce(fighter, wallDirection);
    } else if (Math.abs(fighter.vx) > 220) {
      spawnWallImpact(fighter, wallDirection);
    }
  }
}

// Release 1.7 wave 11 — the wall-bounce conversion itself. Pure snapshotted
// fighter state plus state.hitstop (already in the combat snapshot); all
// spectacle routes through the existing wave 1-9 systems from this sim event.
function performWallBounce(fighter, wallDirection) {
  fighter.wallBounceArmed = 0;
  fighter.wallBounceUsed = true;
  // The bounce consumes a juggle point, so juggleLimit:2 still bounds the combo.
  fighter.juggleCount += 1;
  fighter.pendingKnockdown = true;
  fighter.grounded = false;
  fighter.vx = -wallDirection * WALL_BOUNCE_RULES.reboundVelocityX;
  fighter.vy = WALL_BOUNCE_RULES.reboundVelocityY;
  fighter.hitstunFrames = Math.max(fighter.hitstunFrames, WALL_BOUNCE_RULES.hitstunFrames);
  fighter.stun = Math.max(fighter.hitstunFrames, fighter.blockstunFrames) / SIMULATION_HZ;
  // Brief splat freeze — state.hitstop is sim state in the rollback snapshot.
  state.hitstop = Math.max(state.hitstop, WALL_BOUNCE_RULES.splatFreezeSeconds);
  if (!rollbackResimulating) mechFxDebug.wallBounces += 1;
  // The rebound arc outlives the ordinary 38-frame combo gap while the victim
  // is completely helpless, so the attacker's combo stays open through it —
  // the conversion counts (and scales) as the same combo.
  const attacker = state.fighters[1 - fighter.side];
  // v2.1 PROGRESSION: wall-bounce conversion ledger event (guarded).
  if (!rollbackResimulating && attacker) progressionEvent("wallBounce", {}, attacker.side);
  if (attacker) {
    attacker.combo.graceUntilFrame = Math.max(
      attacker.combo.graceUntilFrame ?? -Infinity,
      state.simulationTick + WALL_BOUNCE_RULES.comboGraceFrames,
    );
  }
  // Spectacle through the existing systems: the wave-4 splat, the crowd surge
  // (0.75 clears the crowdFlashPicks flashbulb threshold), combat text, the
  // announcer bank and the shared violence response.
  spawnWallImpact(fighter, wallDirection);
  // v5.3 CROWD DEPTH: the wall splat is the flinch beat — the people standing
  // within CROWD_FLINCH.radius of the corner rock back from it.
  stirCrowd(0.75, "", { side: attacker ? attacker.side : -1, splatX: fighter.x });
  applyViolenceResponse("heavy", { side: attacker ? attacker.side : -1 });
  spawnCombatText(
    fighter.x - wallDirection * 46,
    fighter.y - fighter.height - 50,
    "WALL BOUNCE",
    "#ffd54a",
  );
  announcerSay("wallbounce");
  sound("hit-heavy", fighter);
}

const attackActionPriority = [...TOURNAMENT_ACTION_PRIORITY];

function bufferedAction(fighter, actions = attackActionPriority) {
  return actions.find((action) => fighter.inputBuffer.has(action, state.simulationTick)) || null;
}

function tryStartBufferedAttack(fighter, input, actions = attackActionPriority, options = {}) {
  for (const action of actions) {
    const entry = fighter.inputBuffer.consume(action, state.simulationTick);
    if (!entry) continue;
    const started = beginAttack(fighter, action, input, {
      ...options,
      reversal: Boolean(options.reversalActions?.includes(action)),
      limb: entry.payload?.limb,
      backThrow: action === "throw" ? Boolean(entry.payload?.back) : null,
    });
    if (started) return true;
  }
  return false;
}

function tryGuardReversal(fighter, input) {
  if (!fighter.grounded || fighter.blockstunFrames <= 0 || fighter.meter < GRIT_RULES.guardReversalCost) return false;
  const direction = directionContext(fighter, input);
  const enhanced = fighter.inputBuffer.has("enhanced", state.simulationTick);
  const directionalSpecial = direction.forwardHeld
    && (fighter.inputBuffer.has("special", state.simulationTick)
      || fighter.inputBuffer.has("commandSpecial", state.simulationTick));
  if (!enhanced && !directionalSpecial) return false;
  if (enhanced) fighter.inputBuffer.consume("enhanced", state.simulationTick);
  else fighter.inputBuffer.consume(["commandSpecial", "special"], state.simulationTick);
  return beginAttack(fighter, "guardReversal", input, { force: true, reversal: true });
}

function tryAttackCancel(fighter, input) {
  const current = fighter.attacking;
  if (!current || !fighter.attackConnected) return false;
  const action = bufferedAction(fighter, attackActionPriority.filter((candidate) => candidate !== "throw"));
  const actionGroup = fighterActionGroup(action);
  if (current.rhythmCancel && fighter.rhythmStacks < (current.rhythmCancelStacks || 2)) return false;
  // BLOCK ECONOMY: the string's blocked special-into-special budget rides
  // along so a second blocked voltage/flow cancel is refused (see
  // SPECIAL_CANCEL_RULES). The refusal is silent: the move simply finishes on
  // its own recovery, which is the punish window the blocker earned.
  const connectedBefore = fighter.attackConnected;
  const cancelBudget = { blockedSpecialCancels: fighter.blockedSpecialCancels };
  if (!action || !canCancelAttack(current, actionGroup, fighter.attackFrame, connectedBefore, cancelBudget)) return false;
  const queuedLimb = fighter.inputBuffer.entries.find((entry) => entry.action === action)?.payload?.limb;
  const moveContext = {
    airborne: !fighter.grounded,
    crouching: fighter.crouch,
    limb: queuedLimb || input.limb || "punch",
    ...directionContext(fighter, input),
  };
  const gritCost = createFighterMove(fighter.kitId, action, moveContext)
    ? fighterActionCost(fighter.kitId, action, moveContext)
    : gritCostForAction(action);
  if (fighter.meter < gritCost) return false;
  const consumed = fighter.inputBuffer.consume(action, state.simulationTick);
  const cancelLimb = consumed?.payload?.limb || queuedLimb || "";
  const previousMove = current.profileId;
  const voltageCancel = Boolean(current.rushCancel
    && ["special", "commandSpecial", "enhanced"].includes(actionGroup));
  const flowCancel = Boolean(current.rhythmCancel
    && fighter.rhythmStacks >= (current.rhythmCancelStacks || 2));
  fighter.attacking = null;
  const started = beginAttack(fighter, action, input, { cancelledFrom: previousMove, limb: cancelLimb });
  if (!started) {
    fighter.attacking = current;
    return false;
  }
  // BLOCK ECONOMY: a blocked special-into-special cancel spends one unit of
  // the string's budget. beginAttack keeps the counter because the cancel
  // passed cancelledFrom, so this is the only place it moves.
  if (connectedBefore === "block" && isSpecialIntoSpecialCancel(current, actionGroup)) {
    fighter.blockedSpecialCancels += 1;
  }
  fighter.confirmWindowFrames = 12;
  const chain = ["light", "heavy", "launcher", "driveHeavy"].includes(actionGroup);
  spawnCombatText(
    fighter.x + fighter.facing * 35,
    fighter.y - fighter.height - 22,
    voltageCancel ? "VOLTAGE CANCEL" : flowCancel ? "FLOW CANCEL" : chain ? "CHAIN" : "HIT CONFIRM",
    fighter.def.accent,
  );
  return true;
}

function tryStartupChordOverride(fighter, input) {
  const current = fighter.attacking;
  if (!current || fighter.attackConnected) return false;
  let action = null;
  const bufferedEnhanced = bufferedAction(fighter, [
    "enhancedLauncher",
    "enhancedBackSpecial",
    "enhancedCommandSpecial",
    "enhanced",
  ]);
  // The super and enhanced chords are two buttons, so the first of the pair can
  // land a frame early and start an ordinary normal. Let the chord take over
  // during that normal's startup rather than eating the input.
  if (fighter.attackFrame <= 6
    && ["heavy", "special"].includes(current.kind)
    && fighter.inputBuffer.has("super", state.simulationTick)
    && fighter.meter >= GRIT_RULES.superCost) action = "super";
  else if (fighter.attackFrame <= 6
    && ["heavy", "special"].includes(current.kind)
    && bufferedEnhanced
    && fighter.meter >= GRIT_RULES.enhancedSpecialCost) action = bufferedEnhanced;
  else if (fighter.attackFrame <= 3
    && ["light", "heavy"].includes(current.kind)
    && fighter.inputBuffer.has("throw", state.simulationTick)) action = "throw";
  if (!action) return false;
  const consumedOverride = fighter.inputBuffer.consume(action, state.simulationTick);
  const previousMove = current.profileId;
  fighter.attacking = null;
  const started = beginAttack(fighter, action, input, {
    cancelledFrom: previousMove,
    backThrow: action === "throw" ? Boolean(consumedOverride?.payload?.back) : null,
  });
  if (!started) {
    fighter.attacking = current;
    return false;
  }
  spawnCombatText(fighter.x, fighter.y - fighter.height - 18, fighterActionGroup(action) === "enhanced" ? "ENHANCED" : "THROW", fighter.def.accent);
  return true;
}

function updateFighter(fighter, opponent, input, dt) {
  fighter.animTime += dt;
  advanceFighterTimers(fighter);
  // Release 1.7: remember whether a guard was already held so the Perfect
  // Guard start tick below only stamps genuinely fresh guard inputs.
  const wasGuarding = fighter.guarding;
  fighter.block = false;
  fighter.guarding = false;
  fighter.crouch = false;

  if (tryFinish(fighter.side, input)) return;
  if (state.phase !== "fight") return;
  // A live grab owns both fighters until updateGrabHolds releases them.
  if (fighter.grabbed) {
    fighter.inputBuffer.clear();
    return;
  }
  if (fighter.grabbing) {
    fighter.vx = 0;
    if (fighter.attacking) {
      fighter.attackFrame = Math.min(fighter.attackFrame + 1, fighter.attacking.activeEndFrame);
      fighter.attackTime = fighter.attackFrame * SIMULATION_STEP_SECONDS;
    }
    return;
  }
  if (fighter.dizzyFrames > 0) {
    relieveDizzy(fighter, input);
    fighter.vx *= 0.82;
    fighter.inputBuffer.clear();
    applyFighterPhysics(fighter, dt);
    return;
  }
  // Release 1.7: GUARD CRUSH reuses the dizzy handling path — briefly
  // helpless, but with no mash relief so the punish window is always real.
  if (fighter.guardCrushFrames > 0) {
    fighter.vx *= 0.82;
    fighter.inputBuffer.clear();
    applyFighterPhysics(fighter, dt);
    return;
  }
  // Release 1.7 wave 11: the taunt hold. Fully vulnerable — no guard, no
  // actions, ordinary hurtboxes — and interruptible only by being hit or
  // grabbed. Completing it uninterrupted banks the once-per-round Grit.
  if (fighter.tauntFrames > 0) {
    fighter.tauntFrames -= 1;
    fighter.vx *= 0.8;
    fighter.crouch = false;
    if (fighter.tauntFrames === 0) completeTaunt(fighter);
    applyFighterPhysics(fighter, dt);
    return;
  }
  // Release 1.7: wake-up options. Up during the knockdown quick-rises, Down
  // held delays the getaway — both from input bits already in the protocol.
  if (fighter.down && fighter.knockdownFrames > 1 && !fighter.wakeOption) {
    const bufferedJump = fighter.inputBuffer.consume("jump", state.simulationTick);
    const option = resolveWakeOption({ jump: Boolean(input.jump || bufferedJump), down: input.down });
    if (option === "quick") {
      fighter.wakeOption = "quick";
      fighter.knockdownFrames = Math.max(1, fighter.knockdownFrames - WAKEUP_RULES.quickRiseFrames);
      if (!rollbackResimulating) mechFxDebug.quickRises += 1;
      spawnCombatText(fighter.x, fighter.y - fighter.height - 30, "QUICK RISE", fighter.def.accent);
      if (!rollbackResimulating && state.mode === "training" && fighter.side === 0) schoolEvent({ type: "wake", option: "quick" });
    } else if (option === "delay") {
      fighter.wakeOption = "delay";
      fighter.knockdownFrames += WAKEUP_RULES.delayFrames;
      if (!rollbackResimulating) mechFxDebug.wakeDelays += 1;
      spawnCombatText(fighter.x, fighter.y - fighter.height - 30, "DELAYED", "#8a93a5");
      if (!rollbackResimulating && state.mode === "training" && fighter.side === 0) schoolEvent({ type: "wake", option: "delay" });
    }
  }
  const flowSpeed = fighter.def.id === "ali" ? 1 + fighter.rhythmStacks * 0.045 : 1;

  if (fighter.blockstunFrames > 0 && tryGuardReversal(fighter, input)) {
    // The reversal replaces blockstun and continues into normal attack processing.
  } else if (fighter.blockstunFrames > 0) {
    fighter.block = true;
    fighter.guarding = true;
    fighter.crouch = fighter.guardHeight === "low";
    fighter.vx *= 0.84;
  } else if (fighter.hitstunFrames > 0 || fighter.pendingKnockdown) {
    // An armed wall-bounce flight holds its carry velocity to the wall; every
    // other hitstun flight bleeds 10% per tick exactly as before.
    if (!fighter.wallBounceArmed) fighter.vx *= 0.9;
    // Release 1.7: air recovery (juggle tech). Any attack button once the
    // airborne-hitstun window opens — armed only when the last hit was
    // neither knockdown-final nor a super — techs out of the juggle. The
    // buffered press is only consumed once the window is genuinely open, so
    // early mashes are not eaten.
    if (!fighter.grounded && fighter.pendingKnockdown && fighter.airTechArmed
      && fighter.airHitstunFrames >= AIR_RECOVERY_RULES.minimumHitstunFrames) {
      const buffered = fighter.inputBuffer.consume(["light", "heavy", "special"], state.simulationTick);
      const pressed = Boolean(buffered || input.light || input.heavy || input.special);
      if (canAirRecover(fighter, pressed)) {
        performAirRecovery(fighter);
        if (!rollbackResimulating && state.mode === "training" && fighter.side === 0) schoolEvent({ type: "airTech" });
      }
    }
  } else if (fighter.down || fighter.wakeupFrames > 0 || fighter.landingRecoveryFrames > 0 || fighter.throwTechFlashFrames > 0) {
    fighter.vx *= 0.72;
    // 5.3 OKIZEME: the vulnerable rising frames can be GUARDED. The riser
    // still cannot attack, dash, jump or walk — but a held back (or down-back)
    // makes the wake-up a high/low read instead of a free hit, which is what
    // keeps the meaty a mix-up rather than a tax on being knocked down.
    // `crouch` deliberately stays false so the rise animation is untouched;
    // only guardHeight moves, and getHurtboxes already treats a low guard as
    // the crouch shape (which is what the rising body wears anyway).
    if (isWakeupVulnerable(fighter)) {
      const risingDirection = directionContext(fighter, input);
      fighter.guardHeight = input.down ? "low" : "high";
      fighter.guarding = risingDirection.backHeld || Boolean(input.guard);
      fighter.block = fighter.guarding;
    }
  } else if (!fighter.attacking) {
    const direction = directionContext(fighter, input);
    if (!fighter.grounded) {
      fighter.queuedDashDirection = 0;
      const bufferedAirAttack = fighter.inputBuffer.consume(["special", "heavy", "light"], state.simulationTick);
      if (bufferedAirAttack) {
        beginAttack(fighter, bufferedAirAttack.action, input, { limb: bufferedAirAttack.payload?.limb });
      }
    } else {
      fighter.crouch = input.down;
      fighter.guardHeight = fighter.crouch ? "low" : "high";
      // SF2 directional guarding: hold away to block, down-away to crouch-block.
      // Crouching alone never blocks and there is no dedicated guard button.
      fighter.guarding = direction.backHeld || Boolean(input.guard);
      fighter.block = fighter.guarding;

      if (fighter.justWoke && fighter.inputBuffer.has("special", state.simulationTick)) {
        fighter.inputBuffer.consume("special", state.simulationTick);
        beginAttack(fighter, "special", input, { reversal: true });
      } else {
        const commandAction = bufferedAction(fighter, [
          "super",
          "enhancedLauncher",
          "enhancedBackSpecial",
          "enhancedCommandSpecial",
          "enhanced",
          "enhancedThrowObject",
          "launcher",
          "backSpecial",
          "driveHeavy",
          "commandSpecial",
          "taunt",
        ]);
        if (commandAction === "taunt") {
          fighter.inputBuffer.consume("taunt", state.simulationTick);
          performTaunt(fighter);
        } else if (commandAction) {
          fighter.inputBuffer.consume(commandAction, state.simulationTick);
          beginAttack(fighter, commandAction, input, {
            reversal: fighter.reversalWindowFrames > 0
              && ["commandSpecial", "backSpecial", "launcher", "enhancedLauncher"].includes(commandAction),
          });
        } else if (fighter.queuedDashDirection && fighter.dashCooldownFrames === 0 && !fighter.crouch) {
          startDash(fighter, fighter.queuedDashDirection);
        }
      }

      if (fighter.dashFrames <= 0 && !fighter.attacking) {
        // Carrying a stage weapon is too heavy to jump with, but it must not
        // freeze the fighter in place either: the walk still runs below.
        const carryProfile = fighter.carriedWeapon ? stageWeaponProfile() : null;
        const jumpBuffered = fighter.inputBuffer.has("jump", state.simulationTick);
        if (carryProfile?.carryBlocksJump && jumpBuffered) {
          fighter.inputBuffer.consume("jump", state.simulationTick);
          if (fighter.carryFrames % 30 === 0) {
            spawnCombatText(fighter.x, fighter.y - fighter.height - 18, "TOO HEAVY", "#8a93a5");
          }
        }
        if (!carryProfile?.carryBlocksJump && fighter.inputBuffer.has("jump", state.simulationTick)) {
          fighter.inputBuffer.consume("jump", state.simulationTick);
          fighter.vy = fighter.movement.jumpVelocityY;
          fighter.vx = direction.forwardHeld ? fighter.facing * fighter.movement.forwardJumpVelocityX
            : direction.backHeld ? -fighter.facing * fighter.movement.backJumpVelocityX
              : fighter.movement.neutralJumpVelocityX;
          fighter.grounded = false;
          fighter.block = false;
          fighter.guarding = false;
          // v2.1 PROGRESSION: no-jump-round observation latch (guarded).
          if (!rollbackResimulating) progressionMatch.jumped[fighter.side] = true;
          sound("jump", fighter);
        } else {
          if (fighter.crouch) fighter.vx = 0;
          else if (direction.absolute) {
            const speed = direction.forwardHeld ? fighter.movement.forwardWalkSpeed : fighter.movement.backWalkSpeed;
            const snare = fighter.slowFrames > 0 ? 0.55 : 1;
            const carry = fighter.carriedWeapon ? (stageWeaponProfile()?.carryWalkScale ?? 1) : 1;
            fighter.vx = direction.absolute * speed * flowSpeed * snare * carry;
          } else fighter.vx = 0;
          if (Math.abs(fighter.vx) > 20) fighter.walkTime += dt;
          // v3.5 BACK-WALK: the stride clock rides the same tick, but SIGNED
          // along facing and scaled by the share of this fighter's own forward
          // walk speed he is actually making — so a retreat at `backWalkSpeed`
          // steps at the rate the ground goes past, and winds the four-key
          // cycle BACKWARDS. Full-speed forward walk returns exactly `dt`.
          fighter.strideTime += strideClockAdvance(fighter.vx, fighter.facing,
            fighter.movement.forwardWalkSpeed / STRIDE_CADENCE, dt);
        }

        // Down + HP over a grounded weapon picks it up; outside pickup range the
        // same press stays an ordinary crouching HP. While carrying, the weapon
        // *replaces* HP entirely, so a heavy press either throws it or is
        // swallowed rather than leaking out as a normal.
        if (fighter.carriedWeapon) {
          const threw = tryThrowStageWeapon(fighter, input);
          fighter.inputBuffer.consume("heavy", state.simulationTick);
          if (threw) return;
        } else if (tryPickUpStageWeapon(fighter, input)) {
          fighter.inputBuffer.consume("heavy", state.simulationTick);
          return;
        }
        tryStartBufferedAttack(fighter, input, attackActionPriority, {
          reversalActions: fighter.reversalWindowFrames > 0
            ? ["special", "commandSpecial", "backSpecial", "launcher", "enhancedLauncher"]
            : [],
        });
      }
    }
  }

  if (fighter.dashFrames > 0 && !fighter.attacking) {
    const forward = fighter.dashDirection === fighter.facing;
    fighter.vx = fighter.dashDirection * (forward ? fighter.movement.forwardDashSpeed : fighter.movement.backDashSpeed) * flowSpeed;
    // Ghost trail: a fading echo of the sprite every other tick of a dash.
    // MOTION FIX 2: echo caps — each ghost lives ~4 ticks (≤2 filmstrip
    // frames), inherits the fighter's CURRENT atlas cell every frame it is
    // drawn (the side field lets the draw pass read the live pose), and
    // decays 60% → 20% opacity instead of a flat wash.
    if (state.performance.trailScale > 0 && !state.accessibility.reducedMotion
      && state.simulationTick % 2 === 0) {
      // v2.7 FRAMES: ghosts stay base-bank smears — a motion pose (the dash
      // stretch cell) contributes its base fallback frame instead of muting
      // the trail.
      // v5.2 LOCOMOTION (bookends): the dash draws the ext5 launch / stretch /
      // brake now, whose fallback is the MOTION link it stands in for and only
      // then the base cell — one level of fallback found no base frame and the
      // trail went silent on every fighter whose ext5 sheet was decoded (the
      // browser smoke's "a dash must leave a ghost trail" caught it once the
      // sheet was ready before the probe). The chain is walked to its base cell.
      const ghostPose = fighterAnimationPose(fighter);
      const ghostFrame = baseFallbackFrame(ghostPose);
      if (ghostFrame >= 0) {
        state.effects.push({
          kind: "afterimage", fighterId: fighter.def.id, side: fighter.side,
          frame: ghostFrame,
          x: fighter.x, y: fighter.y, facing: fighter.facing,
          size: fighterRenderSize(fighter.def.id),
          life: 0.07, max: 0.07, color: fighter.def.accent,
        });
      }
    }
    fighter.dashFrames -= 1;
    fighter.block = false;
    fighter.guarding = false;
    if (!forward && fighter.dashFrames >= fighter.movement.backDashFrames - fighter.movement.backDashInvulnerableFrames) {
      fighter.invulnerableFrames = Math.max(fighter.invulnerableFrames, 1);
    }
  }

  if (fighter.attacking) {
    fighter.attackFrame += 1;
    fighter.attackTime = fighter.attackFrame * SIMULATION_STEP_SECONDS;
    const attack = fighter.attacking;
    maybeDeployTrap(fighter, attack);
    maybeSpawnThrowable(fighter, attack);
    maybeSpawnProjectile(fighter, attack);
    if (attack.retreatSpeed && fighter.attackFrame < attack.activeEndFrame) fighter.vx = -fighter.facing * attack.retreatSpeed;
    else if (attack.advanceSpeed && fighter.attackFrame < attack.activeEndFrame) fighter.vx = fighter.facing * attack.advanceSpeed;
    else fighter.vx *= fighter.grounded ? 0.82 : 0.985;
    fighter.crouch = attack.profileId.startsWith("crouch-");
    // v4.4 TEMPO: the active window closed on nothing — extend this instance's
    // recovery. The instance is per-swing and rollback-cloned, so the stretch
    // is deterministic and the follow-through pose simply holds longer.
    if (!attack.whiffTaxed && fighter.attackFrame >= attack.activeEndFrame && !fighter.attackConnected) {
      attack.whiffTaxed = true;
      const whiffTax = whiffRecoveryFrames(attack);
      attack.whiffTaxFrames = whiffTax;
      attack.totalFrames += whiffTax;
      // v5.1 TEMPO TELLS: the moment the tax lands is the moment the tell
      // starts (fringe, ghost, WHIFF text, lab readout).
      noteWhiff(fighter, attack, whiffTax);
    }
    const cancelled = tryStartupChordOverride(fighter, input) || tryAttackCancel(fighter, input);
    if (!cancelled && fighter.attackFrame >= attack.totalFrames) {
      fighter.linkWindow = fighter.attackConnected ? {
        profileId: attack.profileId,
        connected: fighter.attackConnected,
        expiresFrame: state.simulationTick + DEFAULT_INPUT_BUFFER_FRAMES,
      } : null;
      fighter.attackRearmFrames = fighter.attackConnected ? 0 : ATTACK_REARM_FRAMES;
      fighter.attacking = null;
      fighter.attackTime = 0;
      fighter.attackFrame = 0;
    }
  }

  // Release 1.7: Perfect Guard — stamp the tick a FRESH guard began. Blockstun
  // holds guarding true continuously, so a held guard keeps its original
  // stamp; only releasing and re-tapping back can arm a new just-defend.
  // BLOCK ECONOMY: that re-tap now counts INSIDE blockstun too (Garou-style
  // tap-tap just-defend). Before, guarding never went false during a string,
  // so only its first hit could ever be perfect-guarded and a blockstring
  // was 'nothing I can do'. The edge is the directional back input only: the
  // engine-internal input.guard channel the CPU's defend intent drives never
  // re-arms, so the CPU's just-defend rate stays close to the authored
  // perfectGuardChance (a retreat-intent flip inside blockstun can still
  // produce a tap, but decisions are 7-28 frames apart and it reads as a
  // legitimately late tap).
  const backTapped = directionContext(fighter, input).backHeld;
  const guardTapEdge = backTapped && !fighter.guardInputHeld;
  fighter.guardInputHeld = backTapped;
  if (fighter.guarding && (!wasGuarding || (fighter.blockstunFrames > 0 && guardTapEdge))) {
    // 5.3 OKIZEME: a guard held up on the way OFF THE FLOOR can never be a
    // just-defend. The rising guard (added this pass) goes from false to true
    // on the first vulnerable frame, so without this exclusion every meaty
    // that a riser blocked would land inside the 4-frame Perfect Guard window
    // and pay the blocker Grit — a knockdown would have been better than
    // neutral. The rising guard is a real block; it is simply never perfect.
    fighter.guardStartedTick = fighter.wakeupFrames > 0 ? -Infinity : state.simulationTick;
  }

  applyFighterPhysics(fighter, dt);
}

function maybeDeployTrap(fighter, attack) {
  const profile = attack?.trap;
  if (!profile || fighter.trapDeployed || fighter.attackFrame < profile.deployFrame) return;
  fighter.trapDeployed = true;
  const color = profile.color || "#ff3fbf";
  const offsets = profile.offsets || [110];
  const newTraps = offsets.map((offset, index) => ({
    id: `${fighter.side}-${state.simulationTick}-${index}`,
    ownerSide: fighter.side,
    x: clamp(fighter.x + fighter.facing * offset, MOVEMENT_RULES.stageMinX + 12, MOVEMENT_RULES.stageMaxX - 12),
    y: FLOOR,
    radius: profile.radius,
    damage: profile.damage,
    chipDamage: profile.chipDamage,
    hitstunFrames: profile.hitstunFrames,
    blockstunFrames: profile.blockstunFrames,
    push: profile.push,
    knockdown: profile.knockdown,
    armFrames: profile.armFramesByIndex?.[index] ?? profile.armFrames,
    lifeFrames: profile.lifetimeFrames,
    maxLifeFrames: profile.lifetimeFrames,
    enhanced: offsets.length > 1,
    color,
  }));
  const ownerTraps = state.traps.filter((trap) => trap.ownerSide === fighter.side);
  const removeCount = Math.max(0, ownerTraps.length + newTraps.length - (profile.maxOwned || 2));
  if (removeCount) {
    const retired = new Set(ownerTraps.slice(0, removeCount).map((trap) => trap.id));
    state.traps = state.traps.filter((trap) => !retired.has(trap.id));
  }
  state.traps.push(...newTraps);
  for (const trap of newTraps) {
    state.effects.push({ kind: "paintDeploy", x: trap.x, y: trap.y - 8, life: 0.48, max: 0.48, color });
  }
  spawnCombatText(fighter.x + fighter.facing * 82, fighter.y - fighter.height - 16, newTraps.length > 1 ? "DOUBLE TRAP" : "TRAP SET", color);
  sound("special", fighter);
}

function triggerPaintTrap(trap, victim) {
  const owner = state.fighters[trap.ownerSide];
  if (!owner) return;
  const blocked = canGuardAttack({
    level: ATTACK_LEVELS.LOW,
    guardHeight: victim.guardHeight,
    guarding: victim.guarding,
    grounded: victim.grounded,
  });
  let damage = trap.chipDamage;
  if (!blocked) {
    const comboResult = owner.combo.registerHit(state.simulationTick, victim.juggleCount);
    damage = trap.damage * comboResult.damageScale;
    owner.combo.addDamage(damage);
    // Release 1.8 GRIND: score attack — a landed trap scores as a special
    // (guarded meta bookkeeping inside; never touches sim state).
    awardHitScore(owner, "special");
  }
  victim.health = blocked
    ? Math.max(1, victim.health - damage)
    : clamp(victim.health - damage, 0, 100);
  victim.lastDamageFrame = state.simulationTick;
  // v2.1 PROGRESSION: damage-source latch (guarded meta observation).
  if (!rollbackResimulating) {
    progressionNoteDamage(victim.side, { chip: blocked, amount: damage, kind: "special", level: ATTACK_LEVELS.LOW });
    progressionNoteLanded(owner.side, { blocked, kind: "special" });
  }
  victim.blockstunFrames = blocked ? trap.blockstunFrames : 0;
  victim.hitstunFrames = blocked ? 0 : trap.hitstunFrames;
  victim.stun = Math.max(victim.hitstunFrames, victim.blockstunFrames) / SIMULATION_HZ;
  victim.vx = owner.facing * trap.push * (blocked ? 0.26 : 1);
  victim.lastHitResult = blocked ? "blocked-low-trap" : "paint-trap";
  victim.lastHitLevel = ATTACK_LEVELS.LOW;
  victim.hitFlash = 0.13;
  if (!blocked) {
    victim.attacking = null;
    victim.attackTime = 0;
    victim.attackFrame = 0;
    victim.attackHit = false;
    victim.dashFrames = 0;
    victim.queuedDashDirection = 0;
    if (trap.knockdown) {
      victim.pendingKnockdown = true;
      victim.throwKnockdown = false;
      victim.grounded = false;
      victim.vy = -245;
      // Trap knockdowns are knockdown-final: no air tech.
      victim.airTechArmed = false;
      victim.airHitstunFrames = 0;
    }
  }
  owner.meter = clamp(owner.meter + 13 * GRIT_RULES.hitGainMultiplier, 0, GRIT_RULES.maximum);
  victim.meter = clamp(victim.meter + 13 * GRIT_RULES.damageTakenGainMultiplier, 0, GRIT_RULES.maximum);
  owner.attackConnected = blocked ? "block" : "hit";
  state.effects.push({ kind: "paintTrapBurst", x: trap.x, y: trap.y - 24, life: 0.62, max: 0.62, color: trap.color });
  if (!blocked) pushBattleDamageMark(victim, "special");
  spawnHit(trap.x, trap.y - 63, owner.def, "special", blocked, { direction: owner.facing });
  spawnCombatText(trap.x, trap.y - 112, blocked ? "WET BLOCK" : "WET PAINT!", trap.color);
  applyViolenceResponse("special", { blocked, side: owner.side });
  state.lastImpactSide = owner.side;
  sound(blocked ? "block" : "hit-heavy", blocked ? victim : owner);
  updateHud();
}

function updatePaintTraps() {
  if (!state.traps.length) return;
  for (const trap of state.traps) {
    trap.lifeFrames -= 1;
    trap.armFrames = Math.max(0, trap.armFrames - 1);
    if (trap.lifeFrames <= 0 || trap.armFrames > 0) continue;
    const victim = state.fighters[1 - trap.ownerSide];
    // 5.3 OKIZEME: one predicate for "can a strike touch this body", shared
    // with getHurtboxes — so a trap is armed against the vulnerable rising
    // frames exactly like a fist is.
    if (!victim || !victim.grounded || !isStrikeVulnerable(victim)) continue;
    if (Math.abs(victim.x - trap.x) > trap.radius) continue;
    trap.triggered = true;
    triggerPaintTrap(trap, victim);
  }
  state.traps = state.traps.filter((trap) => trap.lifeFrames > 0 && !trap.triggered);
}

function maybeSpawnThrowable(fighter, attack) {
  if (!attack?.throwableId || fighter.throwableSpawned) return;
  if (fighter.attackFrame < attack.activeStartFrame) return;
  const profile = getThrowable(fighter.kitId);
  if (!profile) return;
  const variant = attack.throwableVariant && profile.variants?.[attack.throwableVariant]
    ? profile.variants[attack.throwableVariant]
    : null;
  const flight = variant ? { ...profile, ...variant } : profile;
  const enhanced = Boolean(attack.enhancedThrowable);
  fighter.throwableSpawned = true;
  const scale = FIGHTER_SCALE;
  // Release 1.7 wave 11: an EX variant may author extraSpawns — additional
  // projectiles released on the same active frame, each merging its own
  // overrides over the EX flight (pizza slices, twin blades, dub plates).
  const releases = [flight, ...(flight.extraSpawns || []).map((extra) => ({ ...flight, ...extra }))];
  releases.forEach((release, index) => {
    state.projectiles.push({
      id: `${fighter.side}-obj-${state.simulationTick}${index ? `-${index}` : ""}`,
      ownerSide: fighter.side,
      throwable: profile.id,
      x: fighter.x + fighter.facing * release.spawnX * scale,
      y: FLOOR + release.spawnY * scale,
      vx: fighter.facing * release.speed * scale,
      vy: release.launchY * scale,
      gravity: release.gravity * scale,
      direction: fighter.facing,
      width: release.width * scale,
      height: release.height * scale,
      hazardWidth: release.hazardWidth * scale,
      damage: release.damage,
      chipDamage: release.chipDamage,
      hitstunFrames: release.hitstunFrames,
      blockstunFrames: release.blockstunFrames,
      push: Math.round(release.push * scale),
      level: release.level,
      knockdown: Boolean(release.knockdown),
      lifeFrames: release.lifeFrames,
      maxLifeFrames: release.lifeFrames,
      armFrames: 0,
      maxArmFrames: 0,
      bouncesLeft: release.bounces,
      bounceDamping: release.bounceDamping,
      hazardFrames: release.hazardFrames,
      hazardArmFrames: release.hazardArmFrames || 0,
      hazard: false,
      spin: release.spin,
      spinAngle: 0,
      wobble: release.wobble,
      tether: release.tether ? { ...release.tether } : null,
      slowFrames: release.slowFrames,
      staggerFrames: release.staggerFrames,
      impactLabel: release.impactLabel,
      variant: attack.throwableVariant || "low",
      color: fighter.def.accent,
      style: profile.style,
      sequenceIndex: index,
      enhanced,
    });
  });
  if (enhanced && !rollbackResimulating) {
    mechFxDebug.exThrowables += 1;
    // v2.1 PROGRESSION: EX throwable ledger event (guarded, P1 seat only).
    progressionEvent("exThrowable", {}, fighter.side);
  }
  sound("throw", fighter);
  if (!rollbackResimulating) objectSound(profile.style);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 46, flight.name, fighter.def.accent);
}

function maybeSpawnProjectile(fighter, attack) {
  const profile = attack?.projectile;
  if (!profile) return;
  const spawnFrames = profile.spawnFrames || [attack.activeStartFrame];
  for (let index = 0; index < spawnFrames.length; index += 1) {
    const spawnFrame = spawnFrames[index];
    if (fighter.attackFrame < spawnFrame || fighter.projectileSpawnFrames.has(spawnFrame)) continue;
    fighter.projectileSpawnFrames.add(spawnFrame);
    const yOffset = profile.yOffsets?.[index] ?? profile.yOffsets?.[0] ?? -110;
    const xOffset = profile.xOffsets?.[index] ?? profile.xOffsets?.[0] ?? 78;
    const armFrames = profile.armFramesByIndex?.[index] ?? profile.armFrames ?? 0;
    const projectile = {
      id: `${fighter.side}-${state.simulationTick}-${index}`,
      ownerSide: fighter.side,
      x: fighter.x + fighter.facing * xOffset * FIGHTER_SCALE,
      y: FLOOR + yOffset * FIGHTER_SCALE,
      vx: fighter.facing * profile.speed * FIGHTER_SCALE,
      direction: fighter.facing,
      width: profile.width * FIGHTER_SCALE,
      height: profile.height * FIGHTER_SCALE,
      damage: profile.damage,
      chipDamage: profile.chipDamage,
      hitstunFrames: profile.hitstunFrames,
      blockstunFrames: profile.blockstunFrames,
      push: profile.push,
      level: profile.level,
      knockdown: Boolean(profile.knockdown),
      lifeFrames: profile.lifeFrames,
      maxLifeFrames: profile.lifeFrames,
      armFrames,
      maxArmFrames: armFrames,
      color: profile.color || fighter.def.accent,
      style: profile.style || "orb",
      sequenceIndex: index,
      enhanced: spawnFrames.length > 1,
    };
    const owned = state.projectiles.filter((item) => item.ownerSide === fighter.side
      && !item.throwable && !item.stageWeapon);
    if (owned.length >= (profile.maxOwned || 2)) {
      const oldest = owned[0];
      state.projectiles = state.projectiles.filter((item) => item.id !== oldest.id);
    }
    state.projectiles.push(projectile);
    state.effects.push({ kind: projectile.style === "feedback" ? "feedbackTelegraph" : "projectileLaunch", x: projectile.x, y: projectile.y, life: 0.35, max: 0.35, color: projectile.color });
    sound("special", fighter);
  }
}

const THROWABLE_IMPACT_COLORS = Object.freeze({
  pizza: ["#e8b23a", "#c4402a", "#f4e3b0"],
  mouse: ["#cfd6e2", "#7fe9ff", "#8a93a5"],
  loogie: ["#b9e37a", "#dff3b8", "#89b84f"],
  wires: ["#4f5b70", "#ff3fbf", "#9aa6bb"],
  xacto: ["#dfe6f0", "#ff5a4a", "#9fb0c6"],
  golfball: ["#ffffff", "#e6ecf5", "#c8d3e2"],
  bedbugs: ["#7a3a2c", "#c4552f", "#3d1f17"],
  vinyl: ["#1b1b1f", "#d8d8d2", "#ff4fb9"],
  cane: ["#aeb6c6", "#d6b56b", "#5a6274"],
});

// Each object breaks, splatters or settles in its own way.
function spawnThrowableImpact(projectile, phase) {
  if (!projectile.throwable) return;
  const palette = THROWABLE_IMPACT_COLORS[projectile.style] || ["#d8d8d2"];
  const settling = phase === "settle";
  const count = Math.max(4, Math.round((settling ? 12 : 20) * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const angle = settling ? -Math.PI * (0.15 + visualRandom() * 0.7) : visualRandom() * Math.PI * 2;
    const speed = (settling ? 60 : 140) + visualRandom() * (settling ? 110 : 300);
    state.particles.push({
      x: projectile.x,
      y: projectile.y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: 0.2 + visualRandom() * 0.36,
      max: 0.56,
      size: 2 + visualRandom() * (projectile.style === "pizza" ? 7 : 5),
      color: palette[Math.floor(visualRandom() * palette.length)] || palette[0],
    });
  }
  if (!rollbackResimulating) objectSound(projectile.style);
  state.effects.push({
    kind: "objectImpact",
    style: projectile.style,
    settling,
    x: projectile.x,
    y: projectile.y,
    life: 0.3,
    max: 0.3,
    color: palette[0],
  });
}

// Jez's mouse keeps its cable: a clean hit reels the victim in, a block just
// retracts it harmlessly, and a whiff leaves him in his long recovery.
function applyThrowableTether(projectile, victim, owner, blocked) {
  const tether = projectile.tether;
  if (!tether) return;
  if (blocked) {
    spawnCombatText(projectile.x, projectile.y - 40, "CABLE SLIPS", owner.def.accent);
    return;
  }
  const holdDistance = tether.holdDistance * FIGHTER_SCALE;
  const target = owner.x + owner.facing * holdDistance;
  victim.x = clamp(target, MOVEMENT_RULES.stageMinX, MOVEMENT_RULES.stageMaxX);
  victim.vx = 0;
  // Release 1.7 wave 11: the EX reel is a guaranteed launcher — the victim is
  // popped airborne beside the owner, juggleable but never techable (the
  // whole point of paying the Grit).
  if (tether.launch) {
    victim.grounded = false;
    victim.pendingKnockdown = true;
    victim.throwKnockdown = false;
    victim.vy = Math.round((tether.launchVelocityY ?? -520) * FIGHTER_SCALE);
    victim.airTechArmed = false;
    victim.airHitstunFrames = 0;
    spawnCombatText((owner.x + victim.x) * 0.5, victim.y - victim.height - 30, "REELED LAUNCH", owner.def.accent);
    state.shake = Math.max(state.shake, 0.3);
    return;
  }
  victim.vy = 0;
  victim.grounded = true;
  victim.pendingKnockdown = false;
  spawnCombatText((owner.x + victim.x) * 0.5, victim.y - victim.height - 30, "GET OVER HERE", owner.def.accent);
  state.shake = Math.max(state.shake, 0.26);
}

function triggerProjectile(projectile, victim) {
  const owner = state.fighters[projectile.ownerSide];
  if (!owner) return;
  const blocked = canGuardAttack({
    level: projectile.level,
    guardHeight: victim.guardHeight,
    guarding: victim.guarding,
    grounded: victim.grounded,
  });
  const armored = !blocked
    && victim.attacking?.armorFrames > 0
    && victim.attackFrame <= victim.attacking.armorFrames
    && victim.armorHits < 1;
  const counter = !blocked && !armored && isCounterHit(victim);
  let comboResult = { damageScale: 1 };
  if (!blocked) comboResult = owner.combo.registerHit(state.simulationTick, victim.juggleCount);
  const baseDamage = projectile.damage
    * (counter ? DEFENSE_RULES.counterDamageMultiplier : 1)
    * comboResult.damageScale
    * (armored ? 0.65 : 1);
  const damage = blocked ? projectile.chipDamage : baseDamage;
  victim.health = blocked ? Math.max(1, victim.health - damage) : clamp(victim.health - damage, 0, 100);
  victim.lastDamageFrame = state.simulationTick;
  // v2.1 PROGRESSION: damage-source latch + personal-throwable-landed event
  // (guarded meta observation on the announce() pattern).
  if (!rollbackResimulating) {
    progressionNoteDamage(victim.side, {
      chip: blocked,
      weapon: Boolean(projectile.stageWeapon),
      throwable: Boolean(projectile.throwable),
      amount: damage,
      kind: "special",
    });
    progressionNoteLanded(owner.side, {
      blocked: blocked || armored,
      kind: "special",
      throwable: Boolean(projectile.throwable),
    });
    if (!blocked && !armored && projectile.throwable) {
      progressionEvent("throwableLand", { fighterId: owner.def.id }, owner.side);
    }
  }
  victim.blockstunFrames = blocked ? projectile.blockstunFrames : 0;
  victim.hitstunFrames = blocked || armored ? 0 : projectile.hitstunFrames + (counter ? DEFENSE_RULES.counterHitstunBonusFrames : 0);
  victim.stun = Math.max(victim.hitstunFrames, victim.blockstunFrames) / SIMULATION_HZ;
  const hitDirection = Math.sign(projectile.vx) || projectile.direction || owner.facing;
  victim.vx = hitDirection * projectile.push * (blocked ? 0.27 : armored ? 0.12 : 1);
  const resultKind = projectile.style === "feedback" ? "feedback-echo" : "projectile";
  victim.lastHitResult = blocked ? `blocked-${projectile.level}-${resultKind}` : armored ? "armor" : counter ? `counter-${resultKind}` : projectile.style === "feedback" ? "feedback-echo" : `${projectile.level}-projectile`;
  victim.lastHitLevel = projectile.level;
  victim.hitFlash = 0.13;
  if (!blocked && !armored) {
    // Release 1.8 GRIND: score attack — projectiles/thrown objects score as
    // specials (guarded meta bookkeeping; never touches sim state).
    awardHitScore(owner, "special", { counter });
    owner.combo.addDamage(damage);
    victim.attacking = null;
    victim.attackTime = 0;
    victim.attackFrame = 0;
    victim.attackHit = false;
    victim.dashFrames = 0;
    victim.queuedDashDirection = 0;
    if (projectile.knockdown) {
      victim.pendingKnockdown = true;
      victim.throwKnockdown = false;
      victim.grounded = false;
      victim.vy = -245;
      // Projectile knockdowns are knockdown-final: no air tech.
      victim.airTechArmed = false;
    }
    victim.airHitstunFrames = 0;
  } else if (armored) {
    victim.armorHits += 1;
    spawnCombatText(victim.x, victim.y - victim.height - 18, "SEISMIC ARMOR", victim.def.accent);
  }
  if (projectile.throwable) {
    applyThrowableTether(projectile, victim, owner, blocked);
    if (!blocked && !armored) {
      if (projectile.staggerFrames) {
        victim.hitstunFrames += projectile.staggerFrames;
        victim.stun = Math.max(victim.stun, victim.hitstunFrames / SIMULATION_HZ);
      }
      if (projectile.slowFrames) {
        victim.slowFrames = Math.max(victim.slowFrames || 0, projectile.slowFrames);
        spawnCombatText(victim.x, victim.y - victim.height - 24, "SNARED", owner.def.accent);
      }
    }
    spawnThrowableImpact(projectile, "hit");
    if (!blocked && !armored && projectile.impactLabel) {
      spawnCombatText(projectile.x, projectile.y - 58, projectile.impactLabel, owner.def.accent);
    }
    if (projectile.hazard) projectile.lifeFrames = 0;
  }
  owner.attackConnected = blocked ? "block" : "hit";
  owner.confirmWindowFrames = 12;
  // BLOCK ECONOMY: a projectile pays its owner once (gritPaid latches on the
  // projectile, which is rollback-cloned with it) — 15 on hit, 6 on block —
  // so a wall of blocked orbs no longer funds a super in five seconds. The
  // defender's 0.45x share of the old flat 15 is unchanged.
  if (!projectile.gritPaid) {
    projectile.gritPaid = true;
    owner.meter = clamp(owner.meter + projectileGritGain({ blocked }), 0, GRIT_RULES.maximum);
  }
  victim.meter = clamp(victim.meter + 15 * GRIT_RULES.damageTakenGainMultiplier, 0, GRIT_RULES.maximum);
  state.effects.push({ kind: projectile.style === "feedback" ? "feedbackBurst" : "projectileBurst", x: projectile.x, y: projectile.y, life: 0.5, max: 0.5, color: projectile.color });
  const impactTier = projectile.stageWeapon ? "weapon" : projectile.throwable ? "heavy" : "special";
  // 5.3 SPECTACLE (#19): a stage weapon that connects sprays its own mess
  // onto the floor under the impact as well as bruising the victim.
  if (projectile.stageWeapon) {
    pushStageScar(projectile.x, blocked ? 0.9 : 1.1, { cause: "weapon", weaponStyle: projectile.style });
  }
  if (!blocked && !armored) pushBattleDamageMark(victim, impactTier);
  spawnHit(projectile.x, projectile.y, owner.def, impactTier, blocked, { direction: hitDirection, counter });
  if (projectile.style === "feedback") spawnCombatText(projectile.x, projectile.y - 86, blocked ? "ECHO BLOCK" : "FEEDBACK ECHO!", projectile.color);
  else if (counter) spawnCombatText(projectile.x, projectile.y - 72, "COUNTER", projectile.color);
  else if (!blocked && projectile.level === ATTACK_LEVELS.LOW) spawnCombatText(projectile.x, projectile.y - 61, colorAssistActive() ? "\u25bc LOW SHOT" : "LOW SHOT", assistColor("low", projectile.color));
  applyViolenceResponse(impactTier, { blocked, counter, side: owner.side });
  state.lastImpactSide = owner.side;
  projectile.hit = true;
  // 5.1 FIGHT SCHOOL: thrown objects never went through observeTrainingHit,
  // so THE JAWN and STREET FURNITURE observe the projectile impact here. The
  // serial is offset past any fighter attackSerial so the dedupe latch can
  // never mistake it for the swing that released it.
  if (!rollbackResimulating && state.mode === "training" && owner.side === 0 && !blocked && !armored) {
    schoolEvent({
      type: "hit",
      action: projectile.stageWeapon ? "stageWeapon" : projectile.throwable ? "throwObject" : "projectile",
      limb: "punch",
      attackSerial: 1000000 + state.simulationTick,
      back: false,
      dizzy: victim.dizzyFrames > 0,
    });
  }
  sound(blocked ? "block" : "hit-heavy", blocked ? victim : owner);
  updateHud();
}

function updateProjectiles(dt) {
  for (const projectile of state.projectiles) {
    if (projectile.hit) continue;
    projectile.lifeFrames -= 1;
    projectile.armFrames = Math.max(0, (projectile.armFrames || 0) - 1);
    if (projectile.throwable) {
      const phase = stepThrowable(projectile, {
        dt,
        floorY: FLOOR,
        minX: MOVEMENT_RULES.stageMinX - 140,
        maxX: MOVEMENT_RULES.stageMaxX + 140,
      });
      if (phase === "bounce" && !rollbackResimulating) objectSound(projectile.style);
      // 5.3 SPECTACLE (#19): a thrown stage weapon that hits the floor
      // leaves ITS mark, not the floor's — glass where the bottle burst,
      // slush where the cup went, a dent where the brick landed. A stage
      // weapon carries bounces: 0 and no hazard frames, so stepThrowable
      // answers "expired" the instant it touches down (only "bounce" for a
      // weapon that ever gets bounces); the floor check keeps a weapon that
      // simply flew off the side of the stage from marking anything.
      if ((phase === "bounce" || phase === "expired") && projectile.stageWeapon
        && projectile.y >= FLOOR - projectile.height * 0.5 - 1) {
        pushStageScar(projectile.x, 1.05, { cause: "weapon", weaponStyle: projectile.style });
      }
      if (phase === "settle") {
        projectile.armFrames = projectile.hazardArmFrames || 0;
        projectile.maxArmFrames = projectile.armFrames;
        spawnThrowableImpact(projectile, "settle");
      }
      if (phase === "expired") {
        projectile.lifeFrames = 0;
        spawnThrowableImpact(projectile, "expire");
      }
    } else {
      projectile.x += projectile.vx * dt;
    }
    if (projectile.lifeFrames <= 0
      || projectile.x < MOVEMENT_RULES.stageMinX - 160
      || projectile.x > MOVEMENT_RULES.stageMaxX + 160) continue;
    if (projectile.armFrames > 0) continue;
    if (!projectile.throwable && !projectile.stageWeapon) {
      const projectileBox = {
        x: projectile.x - projectile.width * 0.5,
        y: projectile.y - projectile.height * 0.5,
        width: projectile.width,
        height: projectile.height,
      };
      const rival = state.projectiles.find((other) => other !== projectile
        && other.ownerSide !== projectile.ownerSide
        && !other.throwable && !other.stageWeapon && !other.hit
        && other.lifeFrames > 0
        && (other.armFrames || 0) <= 0
        && boxesOverlap(projectileBox, {
          x: other.x - other.width * 0.5,
          y: other.y - other.height * 0.5,
          width: other.width,
          height: other.height,
        }));
      if (rival) {
        projectile.hit = true;
        rival.hit = true;
        state.effects.push({ kind: "projectileClash", x: (projectile.x + rival.x) * 0.5, y: (projectile.y + rival.y) * 0.5, life: 0.36, max: 0.36, color: "#ffffff" });
        spawnCombatText((projectile.x + rival.x) * 0.5, Math.min(projectile.y, rival.y) - 48, "CLASH", "#7fe9ff");
        sound("block");
        continue;
      }
    }
    const victim = state.fighters[1 - projectile.ownerSide];
    // 5.3 OKIZEME: a projectile meaty is legal on the vulnerable rising
    // frames, on the same predicate the hurtboxes use.
    if (!isStrikeVulnerable(victim)) continue;
    const projectileBox = {
      x: projectile.x - projectile.width * 0.5,
      y: projectile.y - projectile.height * 0.5,
      width: projectile.width,
      height: projectile.height,
    };
    if (!getHurtboxes(victim).some((hurtbox) => boxesOverlap(projectileBox, hurtbox))) continue;
    triggerProjectile(projectile, victim);
  }
  state.projectiles = state.projectiles.filter((projectile) => !projectile.hit
    && projectile.lifeFrames > 0
    && projectile.x >= MOVEMENT_RULES.stageMinX - 160
    && projectile.x <= MOVEMENT_RULES.stageMaxX + 160);
}

function spawnCombatText(x, y, label, color = "#fff") {
  state.effects.push({ kind: "combatText", label, x, y, life: 0.72, max: 0.72, color });
}

// v5.1 TEMPO TELLS: monotonic sim-side totals (guarded against resimulation
// like progressionMatch) so a smoke probe can prove a scripted whiff was
// noticed and that a mash inside the gap was eaten. snapshot().violence and
// qa.tempo() read them; nothing in the sim does.
const tempoFxDebug = { whiffTells: 0, rearmDrops: 0 };

// The moment the tax lands (the active window closed on nothing). Stamps the
// fighter's whiffTell for both renderers, floats WHIFF at the hand, and
// merges the real tail into the lab's lastMove — which used to be snapshotted
// at attack START and so always showed the authored R.
function noteWhiff(fighter, attack, taxFrames) {
  fighter.whiffTell = {
    tick: state.simulationTick,
    taxFrames,
    rearmFrames: ATTACK_REARM_FRAMES,
    kind: attack.kind,
    profileId: attack.profileId,
  };
  if (!rollbackResimulating) tempoFxDebug.whiffTells += 1;
  // 5.3 CLOSE RANGE: a whiffed THROW is the new commitment — count it apart
  // from the general whiff tell so a probe can prove the risk exists.
  if (!rollbackResimulating && attack.kind === "throw") mechFxDebug.throwWhiffs += 1;
  // Exempt moves (projectile, trap, hurled object) tax nothing because they
  // connect later through what they spawned — no WHIFF for those.
  if (taxFrames > 0) {
    spawnCombatText(
      fighter.x + fighter.facing * 44,
      fighter.y - fighter.height * 0.74,
      TEMPO_TELL_RULES.textLabel,
      TEMPO_TELL_RULES.textColor,
    );
  }
  if (state.mode === "training" && fighter.side === 0 && state.training.lastMove) {
    state.training.lastMove = noteWhiffOnMove(state.training.lastMove, taxFrames, ATTACK_REARM_FRAMES);
  }
}

// A press the re-arm gap ate (beginAttack refused it with only the gap in
// the way). The stamp drives the eaten-press flash; the click is voiced for
// human seats only — the CPU's own mash is not feedback anyone needs.
function noteRearmDrop(fighter) {
  fighter.rearmDropTick = state.simulationTick;
  if (rollbackResimulating) return;
  tempoFxDebug.rearmDrops += 1;
  if (!sideIsCpuControlled(fighter.side)) sound("rearm-drop", fighter);
}

/**
 * Every fighter throws with its own hold, release and impact. The numbers are
 * deliberately small and data-driven so the grab game can be retuned without
 * touching the simulation. `hold` is the length of the visible clinch in frames,
 * `lift` raises the victim during the hold, `launch` scales the release arc and
 * `spin` rotates the held victim so grapplers read differently from strikers.
 */
const THROW_STYLES = Object.freeze({
  deathblow: { hold: 17, lift: 78, offset: 62, spin: -0.5, launch: 1.22, drop: 1.35, shake: 0.42, label: "SLAM" },
  jez: { hold: 12, lift: 22, offset: 54, spin: -1.15, launch: 0.94, drop: 1, shake: 0.26, label: "TRIP" },
  alan: { hold: 18, lift: 66, offset: 58, spin: -0.72, launch: 1.16, drop: 1.2, shake: 0.38, label: "CLINCH" },
  post: { hold: 14, lift: 48, offset: 66, spin: -0.4, launch: 1.08, drop: 1, shake: 0.28, label: "TOSS" },
  benny: { hold: 11, lift: 30, offset: 52, spin: -0.85, launch: 1.02, drop: 1.05, shake: 0.24, label: "DROP" },
  donald: { hold: 15, lift: 52, offset: 70, spin: -0.3, launch: 1.3, drop: 0.9, shake: 0.32, label: "HEAVE" },
  cyraxx: { hold: 12, lift: 34, offset: 56, spin: -0.6, launch: 1, drop: 1, shake: 0.26, label: "SHOVE" },
  ali: { hold: 13, lift: 70, offset: 50, spin: -1.35, launch: 1.12, drop: 1.1, shake: 0.3, label: "JUDO" },
  // Wave 17: the Devil's wing-grab — the highest lift in the game (the wings
  // do the work), a hard spin, and a downward flick that reads like dropped
  // prey rather than a wrestler's slam.
  devil: { hold: 12, lift: 92, offset: 58, spin: -1, launch: 1.14, drop: 1.3, shake: 0.32, label: "SNATCH" },
  commissioner: { hold: 16, lift: 60, offset: 64, spin: -0.65, launch: 1.24, drop: 1.25, shake: 0.4, label: "HOOK" },
});

const DEFAULT_THROW_STYLE = Object.freeze({
  hold: 14, lift: 48, offset: 58, spin: -0.7, launch: 1.05, drop: 1.05, shake: 0.3, label: "THROW",
});

function throwStyle(fighter) {
  return THROW_STYLES[fighter?.def?.id] || DEFAULT_THROW_STYLE;
}

function beginGrabHold(attacker, victim, attack) {
  // v2.9 FLOW: demo coverage beat — a grab actually connected.
  demoChoreoBeat(attacker.side, "throw");
  const style = throwStyle(attacker);
  const back = Boolean(attack.backThrow);
  attacker.grabbing = {
    victim: victim.side,
    frame: 0,
    total: style.hold,
    // 5.3 CLOSE RANGE: the tick the hold began, so the clinch tech can tell a
    // FRESH answering grab from the one the victim had already buffered
    // (which the pre-contact window at hit() has already resolved).
    startTick: state.simulationTick,
    back,
    damage: attack.damage,
    push: attack.push,
    meter: attack.meter,
    profileId: attack.profileId,
    moveName: attack.moveName || style.label,
  };
  victim.grabbed = { attacker: attacker.side, frame: 0, total: style.hold, back, startTick: state.simulationTick };
  victim.attacking = null;
  victim.attackFrame = 0;
  victim.attackTime = 0;
  victim.vx = 0;
  victim.vy = 0;
  victim.down = false;
  victim.grounded = true;
  victim.hitstunFrames = 0;
  victim.blockstunFrames = 0;
  victim.pendingKnockdown = false;
  victim.inputBuffer.clear();
  victim.combo.reset();
  attacker.attackHit = true;
  attacker.attackHits += 1;
  attacker.attackConnected = "hit";
  attacker.lastHitResult = "grab";
  victim.lastHitResult = "grabbed";
  state.hitstop = Math.max(state.hitstop, 0.06);
  spawnCombatText(
    (attacker.x + victim.x) * 0.5,
    Math.min(attacker.y, victim.y) - 190,
    attacker.grabbing.moveName,
    attacker.def.accent,
  );
  sound("throw", attacker);
}

// ---------------------------------------------------------------------------
// Stage weapons
// ---------------------------------------------------------------------------

function resetStageWeapon() {
  for (const fighter of state.fighters) {
    fighter.carriedWeapon = null;
    fighter.carryFrames = 0;
  }
  // Release 1.8 GRIND: the Weapons Rain house rule forces stage weapons on
  // for the match even when the persisted toggle is off — the rule comes from
  // matchRules (mutator config), so both peers derive the same answer.
  if (!state.stageWeaponsEnabled && !state.matchRules.weaponsRain) {
    state.stageWeapon = null;
    return;
  }
  const plan = planStageWeapon(state.stage, {
    matchSeed: state.matchSeed,
    round: state.round,
    minX: MOVEMENT_RULES.stageMinX,
    maxX: MOVEMENT_RULES.stageMaxX,
  });
  state.stageWeapon = plan
    ? { ...plan, phase: "pending", y: FLOOR, holder: -1, frames: 0, roundStartTick: state.simulationTick }
    : null;
  // v2.9 FLOW: attract exhibitions are short showcase rounds — a weapon
  // planned for the ordinary 16-62 second contest window simply never arrives
  // before the KO, which is why the pickup beat was 0-for-10 on every weapon
  // stage. Demo mode alone pulls the arrival forward; the slot comes from the
  // already-seeded plan, so this stays deterministic and never touches
  // ranked, vs, arcade, tournament or online rounds.
  if (state.mode === "demo" && state.stageWeapon) {
    state.stageWeapon.spawnFrame = 210 + (state.stageWeapon.slot % 4) * 40;
  }
}

function stageWeaponProfile() {
  return state.stageWeapon ? getStageWeapon(state.stageWeapon.stageId) : null;
}

// 5.3 SPECTACLE (#18): what comes off the furniture with the weapon. One
// entry per arrival `debris` kind — the puff at the source when the object is
// knocked loose, and the bigger burst where it finally lands.
const WEAPON_ARRIVAL_DEBRIS = Object.freeze({
  grit: { colors: ["#7d7468", "#4c463f"], count: 9, speed: 160, size: 7, gravity: 520, drag: 0.95 },
  feathers: { colors: ["#cfd6e2", "#9aa3b2"], count: 12, speed: 95, size: 9, gravity: 70, drag: 0.9 },
  steam: { colors: ["#e6eef8", "#b9c9dc"], count: 8, speed: 80, size: 13, gravity: -70, drag: 0.93 },
  spray: { colors: ["#9fe4ff", "#d9f6ff"], count: 11, speed: 175, size: 6, gravity: 640, drag: 0.96 },
  brickdust: { colors: ["#c98a5a", "#7a4a30"], count: 12, speed: 185, size: 8, gravity: 560, drag: 0.95 },
});

function spawnWeaponArrivalDebris(kind, x, y, scale = 1) {
  if (rollbackResimulating) return 0;
  const spec = WEAPON_ARRIVAL_DEBRIS[kind] || WEAPON_ARRIVAL_DEBRIS.grit;
  const count = Math.max(3, Math.round(spec.count * scale * state.performance.particleScale));
  for (let index = 0; index < count; index += 1) {
    const angle = -Math.PI * 0.5 + (visualRandom() - 0.5) * 2.4;
    const speed = spec.speed * scale * (0.45 + visualRandom() * 0.85);
    state.particles.push({
      kind: "dust",
      x: x + (visualRandom() - 0.5) * 26 * scale,
      y: y - visualRandom() * 12,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      gravity: spec.gravity,
      drag: spec.drag,
      life: 0.3 + visualRandom() * 0.5,
      max: 0.8,
      size: spec.size * (0.6 + visualRandom() * 0.8),
      color: spec.colors[visualRandom() < 0.5 ? 0 : 1],
    });
  }
  return count;
}

function announceWeaponArrival(profile) {
  spawnCombatText(state.stageWeapon.x, FLOOR - 210, profile.cue, "#ffd54a");
  state.effects.push({
    kind: "guard",
    style: profile.style,
    attackKind: "stage-weapon",
    x: state.stageWeapon.x,
    y: FLOOR - 40,
    life: 0.5,
    max: 0.5,
    color: "#ffd54a",
  });
  // 5.3: the arrival now STARTS at a piece of the stage — the station stairs,
  // the stands, the boardwalk rail, the steam counter, a deck chair, the lot
  // wall — so the beat opens with that furniture being disturbed (a puff at
  // the source plus the object's own scrape) and the clatter is saved for the
  // moment it actually hits the floor.
  const arrival = getWeaponArrival(state.stageWeapon.stageId);
  if (arrival) {
    const origin = weaponArrivalOrigin(state.stageWeapon.stageId, state.stageWeapon.x, {
      floor: FLOOR,
      minX: MOVEMENT_RULES.stageMinX,
      maxX: MOVEMENT_RULES.stageMaxX,
    });
    spawnWeaponArrivalDebris(arrival.debris, origin.x, origin.y, 0.7);
  }
  if (!rollbackResimulating) objectSound(profile.style);
}

// The moment the arrival path reaches the floor: the burst, the clatter and
// the first battle scar of the beat, all on the landing slot.
function landWeaponArrival(profile) {
  const weapon = state.stageWeapon;
  const arrival = getWeaponArrival(weapon.stageId);
  spawnWeaponArrivalDebris(arrival?.debris || "grit", weapon.x, FLOOR - 4, 1.25);
  state.effects.push({
    kind: "floorImpact", x: weapon.x, y: FLOOR - 4,
    width: 58, life: 0.4, max: 0.4, color: arrival?.tint || "#b7a99a",
  });
  pushStageScar(weapon.x, 0.95, { cause: "weapon", weaponStyle: profile.style });
  if (!rollbackResimulating) sound("stage-weapon");
}

function updateStageWeapon() {
  const weapon = state.stageWeapon;
  if (!weapon) return;
  const profile = stageWeaponProfile();
  if (!profile) return;
  weapon.frames += 1;
  // Release 1.8 GRIND: Weapons Rain house rule — a "gone" weapon re-plans the
  // next deterministic drop after a fixed cooldown. All counters live on the
  // snapshotted weapon object and the plan derives from matchSeed + wave, so
  // the rain is identical on both rollback peers and across resims.
  if (weapon.phase === "gone" && state.matchRules.weaponsRain && !state.finisher && state.phase === "fight") {
    weapon.rainFrames = (weapon.rainFrames || 0) + 1;
    if (weapon.rainFrames >= state.matchRules.weaponRespawnFrames) {
      const wave = (weapon.wave || 0) + 1;
      const plan = planStageWeapon(state.stage, {
        matchSeed: hashSeed(state.matchSeed, "weapons-rain", wave),
        round: state.round,
        minX: MOVEMENT_RULES.stageMinX,
        maxX: MOVEMENT_RULES.stageMaxX,
      });
      if (plan) {
        state.stageWeapon = {
          ...plan,
          spawnFrame: 60,
          phase: "pending",
          y: FLOOR,
          holder: -1,
          frames: 0,
          wave,
          roundStartTick: state.simulationTick,
        };
      }
    }
    return;
  }
  if (weapon.phase === "pending") {
    // spawnFrame counts from the start of the round, not from match boot.
    if (state.simulationTick - weapon.roundStartTick < weapon.spawnFrame) return;
    if (!canWeaponArrive({
      phase: state.phase,
      hitstop: state.hitstop,
      finisherActive: Boolean(state.finisher),
      superActive: state.fighters.some((fighter) => fighter.attacking?.superMove),
      anyKnockdown: state.fighters.some((fighter) => fighter.down || fighter.knockdownFrames > 0 || fighter.pendingKnockdown),
      paused: state.paused,
    })) return;
    weapon.phase = "telegraph";
    weapon.frames = 0;
    announceWeaponArrival(profile);
    return;
  }
  if (weapon.phase === "telegraph") {
    if (weapon.frames >= profile.telegraphFrames) {
      weapon.phase = "ground";
      weapon.frames = 0;
      landWeaponArrival(profile);
    }
    return;
  }
  if (weapon.phase === "ground") {
    if (weapon.frames >= profile.groundFrames) {
      weapon.phase = "gone";
      spawnCombatText(weapon.x, FLOOR - 120, "GONE", "#8a93a5");
    }
    return;
  }
  if (weapon.phase === "held") {
    const holder = state.fighters[weapon.holder];
    if (holder) holder.carryFrames = Math.min(holder.carryFrames, profile.carryFrames);
    if (!holder || holder.carriedWeapon !== weapon.weaponId) {
      dropStageWeapon(holder, true);
      return;
    }
    weapon.x = holder.x;
    holder.carryFrames += 1;
    // A dropped weapon after too long stops it being a permanent upgrade.
    if (holder.carryFrames >= profile.carryFrames) dropStageWeapon(holder, true);
  }
}

function tryPickUpStageWeapon(fighter, input) {
  const weapon = state.stageWeapon;
  if (!weapon || weapon.phase !== "ground") return false;
  if (fighter.carriedWeapon) return false;
  // The passive dummy never arms itself — but makeFighter hands EVERY seat a
  // brain, and FIGHT SCHOOL runs on "passive", so this guard used to refuse
  // the human player too (measured: standing 5 px over the object in the
  // STREET FURNITURE lesson, ↓ + HP did nothing). CPU-controlled seats only.
  if (sideIsCpuControlled(fighter.side) && isPassiveDifficulty(fighter.aiBrain?.difficulty)) return false;
  if (!input.down || !input.heavy) return false;
  const profile = stageWeaponProfile();
  if (!canPickUpWeapon(fighter, weapon, { range: profile.pickupRange, scale: FIGHTER_SCALE })) return false;
  weapon.phase = "held";
  weapon.holder = fighter.side;
  weapon.frames = 0;
  // v2.9 FLOW: demo coverage beat — the stage weapon actually got picked up.
  demoChoreoBeat(fighter.side, "weaponPickup");
  fighter.carriedWeapon = weapon.weaponId;
  fighter.carryFrames = 0;
  fighter.inputBuffer.consume("heavy", state.simulationTick);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 40, profile.name, fighter.def.accent);
  if (!rollbackResimulating) objectSound(profile.style);
  if (!rollbackResimulating && fighter.side === 0 && !sideIsCpuControlled(0)) {
    progressionMatch.digest.weaponPickups += 1;
  }
  if (!rollbackResimulating && state.mode === "training" && fighter.side === 0) schoolEvent({ type: "pickup" });
  updateHud();
  return true;
}

function dropStageWeapon(fighter, expire = false) {
  const weapon = state.stageWeapon;
  if (!weapon) return;
  if (fighter) {
    fighter.carriedWeapon = null;
    fighter.carryFrames = 0;
  }
  weapon.phase = expire ? "gone" : "ground";
  weapon.holder = -1;
  weapon.frames = 0;
  updateHud();
}

// The held weapon replaces HP until it leaves the fighter's hands.
function tryThrowStageWeapon(fighter, input) {
  const weapon = state.stageWeapon;
  if (!weapon || weapon.phase !== "held" || weapon.holder !== fighter.side) return false;
  if (!fighter.carriedWeapon || fighter.attacking) return false;
  if (!input.heavy && !input.throwWeapon) return false;
  const profile = stageWeaponProfile();
  // The press that picks the weapon up must not also throw it: the fighter is
  // still bringing it up to throwing height.
  if (fighter.carryFrames < profile.pickupFrames) return false;
  const direction = directionContext(fighter, input);
  // Forward is the committed attacking throw; neutral or away is a safer toss.
  const committed = direction.forwardHeld;
  const scale = FIGHTER_SCALE;
  fighter.carriedWeapon = null;
  fighter.carryFrames = 0;
  weapon.phase = "thrown";
  weapon.holder = -1;
  fighter.attacking = createAttackInstance("special", {
    id: `stage-weapon-${profile.id}`,
    profileId: `stage-weapon-${profile.id}`,
    cancelProfileId: "stage-weapon",
    kind: "special",
    level: profile.level,
    moveName: profile.name,
    startupFrames: committed ? profile.throwStartupFrames : Math.max(6, profile.throwStartupFrames - 4),
    activeFrames: profile.throwActiveFrames,
    recoveryFrames: committed ? profile.throwRecoveryFrames : profile.dropRecoveryFrames,
    range: 0,
    damage: 0,
    chipDamage: 0,
    push: 0,
    meter: 6,
    hitstunFrames: 0,
    blockstunFrames: 0,
    hitboxes: [],
  });
  fighter.attackFrame = 0;
  fighter.attackTime = 0;
  fighter.attackHit = false;
  fighter.attackHits = 0;
  fighter.inputBuffer.consume("heavy", state.simulationTick);
  state.projectiles.push({
    id: `weapon-${state.simulationTick}`,
    ownerSide: fighter.side,
    throwable: profile.id,
    stageWeapon: true,
    x: fighter.x + fighter.facing * 66 * scale,
    y: FLOOR - 130 * scale,
    vx: fighter.facing * (committed ? profile.speed : profile.dropSpeed) * scale,
    vy: (committed ? profile.launchY : profile.dropLaunchY) * scale,
    gravity: profile.gravity * scale,
    direction: fighter.facing,
    width: profile.width * scale,
    height: profile.height * scale,
    hazardWidth: 0,
    damage: committed ? profile.damage : profile.damage * 0.6,
    chipDamage: profile.chipDamage,
    hitstunFrames: profile.hitstunFrames,
    blockstunFrames: profile.blockstunFrames,
    push: Math.round(profile.push * scale),
    level: profile.level,
    knockdown: Boolean(profile.knockdown),
    lifeFrames: profile.lifeFrames,
    maxLifeFrames: profile.lifeFrames,
    armFrames: 0,
    maxArmFrames: 0,
    bouncesLeft: profile.bounces,
    bounceDamping: 0.4,
    hazardFrames: 0,
    hazard: false,
    spin: profile.spin,
    spinAngle: 0,
    wobble: 0,
    tether: null,
    slowFrames: profile.slowFrames || 0,
    staggerFrames: profile.staggerFrames || 0,
    color: "#ffd54a",
    style: profile.style,
    sequenceIndex: 0,
    enhanced: false,
  });
  if (!rollbackResimulating) objectSound(profile.style);
  spawnCombatText(fighter.x, fighter.y - fighter.height - 46, committed ? profile.name : "TOSS", fighter.def.accent);
  updateHud();
  return true;
}

function updateGrabHolds() {
  for (const attacker of state.fighters) {
    const grab = attacker.grabbing;
    if (!grab) continue;
    const victim = state.fighters[grab.victim];
    if (!victim || victim.grabbed?.attacker !== attacker.side) {
      attacker.grabbing = null;
      continue;
    }
    const style = throwStyle(attacker);
    grab.frame += 1;
    victim.grabbed.frame = grab.frame;
    // 5.3 CLOSE RANGE: the REACTION tech. CONTROLS.md has promised since 1.1C
    // that "a tech cancels any clinch that had already started" and until now
    // nothing here checked — the only tech was the 6 frames BEFORE contact,
    // which a human cannot react to. A fresh throw press inside the first
    // `clinchTechWindowFrames` of the hold breaks it. Keyed on
    // lastThrowInputFrame (a plain rollback-carried fighter field, still
    // written for a grabbed fighter because prepareFighterInput runs before
    // updateFighter drops the victim's buffer), so resimulation agrees.
    if (grab.frame <= DEFENSE_RULES.clinchTechWindowFrames
      && Number.isFinite(victim.lastThrowInputFrame)
      && victim.lastThrowInputFrame >= (grab.startTick ?? -Infinity)) {
      techThrow(attacker, victim, { clinch: true });
      continue;
    }
    const progress = Math.min(1, grab.frame / Math.max(1, grab.total));
    // The victim rides the thrower's hand through the clinch, then gets released.
    const direction = grab.back ? -attacker.facing : attacker.facing;
    victim.x = clamp(
      attacker.x + attacker.facing * style.offset * (1 - progress * 0.35),
      MOVEMENT_RULES.stageMinX,
      MOVEMENT_RULES.stageMaxX,
    );
    victim.y = FLOOR - style.lift * Math.sin(progress * Math.PI);
    victim.grounded = victim.y >= FLOOR - 0.5;
    victim.vx = 0;
    victim.vy = 0;
    victim.facing = -attacker.facing;
    victim.cinematicRotation = style.spin * Math.sin(progress * Math.PI) * attacker.facing;
    attacker.vx = 0;
    if (grab.frame >= grab.total) resolveGrabThrow(attacker, victim, grab, style, direction);
  }
}

function resolveGrabThrow(attacker, victim, grab, style, direction) {
  attacker.grabbing = null;
  victim.grabbed = null;
  victim.cinematicRotation = 0;
  // Release 1.8 GRIND: score attack — a completed grab scores as a throw.
  awardHitScore(attacker, "throw");
  victim.health = clamp(victim.health - grab.damage, 0, 100);
  victim.lastDamageFrame = state.simulationTick;
  // v2.1 PROGRESSION: damage-source latch (guarded meta observation).
  if (!rollbackResimulating) {
    progressionNoteDamage(victim.side, { amount: grab.damage, throwMove: true });
    if (victim.side === 0 && !sideIsCpuControlled(0)) progressionMatch.digest.throwsTaken += 1;
    progressionNoteLanded(attacker.side, { kind: "throw" });
  }
  victim.lastHitResult = ATTACK_LEVELS.THROW;
  victim.juggleCount = 0;
  victim.wallBounceUsed = false;
  victim.wallBounceArmed = 0;
  victim.pendingKnockdown = true;
  // 5.3 CLOSE RANGE: only a knockdown that CAME FROM A THROW pays the long
  // 40-frame post-throw immunity on the way up — that is what stops the throw
  // loop. A strike knockdown pays the short one, which is what gives okizeme
  // back to the grapplers.
  victim.throwKnockdown = true;
  victim.grounded = false;
  // Throws are never air-techable.
  victim.airTechArmed = false;
  victim.airHitstunFrames = 0;
  victim.vx = direction * grab.push * style.launch;
  victim.vy = -371 * style.drop;
  victim.x = clamp(
    attacker.x + direction * style.offset,
    MOVEMENT_RULES.stageMinX,
    MOVEMENT_RULES.stageMaxX,
  );
  victim.hitFlash = 0.16;
  attacker.combo.reset();
  attacker.meter = clamp(attacker.meter + grab.meter * GRIT_RULES.hitGainMultiplier, 0, GRIT_RULES.maximum);
  victim.meter = clamp(victim.meter + grab.meter * GRIT_RULES.damageTakenGainMultiplier, 0, GRIT_RULES.maximum);
  applyViolenceResponse("throw", { side: attacker.side, splatX: victim.x });
  state.shake = Math.max(state.shake, style.shake * 1.2);
  state.lastImpactSide = attacker.side;
  const impactX = victim.x;
  const impactY = FLOOR - 60;
  pushBattleDamageMark(victim, "throw");
  spawnHit(impactX, impactY, attacker.def, "throw", false, { direction });
  spawnCombatText(impactX, impactY - 78, grab.back ? "BACK THROW" : "THROW", attacker.def.accent);
  sound("hit-heavy", attacker);
  if (state.mode === "training" && attacker.side === 0) {
    state.training.lastResult = grab.back ? "BACK THROW" : "THROW";
    state.training.lastDamage = grab.damage;
  }
  updateHud();
}

function clearGrabState(fighter) {
  if (fighter.grabbing) {
    const victim = state.fighters[fighter.grabbing.victim];
    if (victim?.grabbed?.attacker === fighter.side) victim.grabbed = null;
    fighter.grabbing = null;
  }
  if (fighter.grabbed) {
    const attacker = state.fighters[fighter.grabbed.attacker];
    if (attacker?.grabbing?.victim === fighter.side) attacker.grabbing = null;
    fighter.grabbed = null;
  }
}

/**
 * 5.3 CLOSE RANGE: the tech has two flavours and they read differently.
 * `clinch: false` is the pre-contact tech (hands clash before the hold) —
 * unchanged. `clinch: true` is the new REACTION tech: the victim answered
 * inside the first `clinchTechWindowFrames` of a hold that had already
 * started, which is what CONTROLS.md has promised since 1.1C and what the
 * code never did. It shoves harder, flashes longer, prints its own label and
 * snaps its own break cue so a player can tell "I got out" from "we clashed".
 */
function techThrow(attacker, victim, { clinch = false } = {}) {
  clearGrabState(attacker);
  clearGrabState(victim);
  attacker.attackHit = true;
  attacker.attacking = null;
  victim.attacking = null;
  attacker.inputBuffer.consume("throw", state.simulationTick);
  victim.inputBuffer.consume("throw", state.simulationTick);
  const push = clinch ? THROW_RULES.clinchTechPushback : THROW_RULES.techPushback;
  const flash = clinch ? THROW_RULES.clinchTechFlashFrames : THROW_RULES.techFlashFrames;
  attacker.vx = -attacker.facing * push;
  victim.vx = attacker.facing * push;
  attacker.throwInvulnerableFrames = DEFENSE_RULES.throwInvulnerableFrames;
  victim.throwInvulnerableFrames = DEFENSE_RULES.throwInvulnerableFrames;
  attacker.throwTechFlashFrames = flash;
  victim.throwTechFlashFrames = flash;
  attacker.lastHitResult = "throw-tech";
  victim.lastHitResult = "throw-tech";
  state.hitstop = Math.max(state.hitstop, clinch ? 0.095 : 0.075);
  state.shake = Math.max(state.shake, clinch ? 0.15 : 0.11);
  const midX = (attacker.x + victim.x) * 0.5;
  spawnCombatText(midX, Math.min(attacker.y, victim.y) - 205,
    clinch ? "CLINCH TECH" : "THROW TECH", clinch ? "#9dff9c" : "#68f5ff");
  sound("block", victim);
  if (clinch) {
    // The break is visible as well as audible: a burst of sweat off both
    // bodies and a hit ring at the point the hold came apart.
    spawnFootDust(attacker, 7, 34, -attacker.facing);
    spawnFootDust(victim, 7, 34, attacker.facing);
    spawnHit(midX, Math.min(attacker.y, victim.y) - 118, victim.def, "block", true, { direction: attacker.facing });
    clinchTechBreak();
    if (!rollbackResimulating) mechFxDebug.clinchTechs += 1;
  }
  // Wave 9: tech shout from the escaping fighter (guarded + tick-deduped).
  fighterReactiveCue(victim, "tech");
  // v2.1 PROGRESSION: the escapee's grab-tech tally (guarded meta counter).
  if (!rollbackResimulating) {
    progressionMatch.techs[victim.side] += 1;
    if (victim.side === 0 && !sideIsCpuControlled(0)) progressionMatch.digest.techs += 1;
  }
}

function triggerSouthpawCounter(counterFighter, incomingFighter, incomingAttack, collision) {
  const stance = counterFighter.attacking;
  if (!stance
    || counterFighter.counterTriggered
    || !Number.isFinite(stance.counterWindowFrom)
    || counterFighter.attackFrame < stance.counterWindowFrom
    || counterFighter.attackFrame > stance.counterWindowTo
    || incomingAttack.level === ATTACK_LEVELS.THROW
    || (incomingAttack.superMove && !stance.counterSuper)) return false;

  counterFighter.counterTriggered = true;
  counterFighter.attackHit = true;
  counterFighter.attackHits = 1;
  counterFighter.attackConnected = "hit";
  counterFighter.lastHitResult = "counter-punch";
  counterFighter.attackFrame = Math.max(counterFighter.attackFrame, stance.activeStartFrame);
  counterFighter.attackTime = counterFighter.attackFrame * SIMULATION_STEP_SECONDS;
  const comboResult = counterFighter.combo.registerHit(state.simulationTick, incomingFighter.juggleCount);
  const damage = stance.counterDamage * comboResult.damageScale;
  counterFighter.combo.addDamage(damage);
  incomingFighter.health = clamp(incomingFighter.health - damage, 0, 100);
  incomingFighter.lastDamageFrame = state.simulationTick;
  incomingFighter.attacking = null;
  incomingFighter.attackTime = 0;
  incomingFighter.attackFrame = 0;
  incomingFighter.attackHit = false;
  incomingFighter.attackConnected = "";
  incomingFighter.hitstunFrames = stance.counterHitstunFrames;
  incomingFighter.blockstunFrames = 0;
  incomingFighter.stun = stance.counterHitstunFrames / SIMULATION_HZ;
  incomingFighter.vx = counterFighter.facing * stance.counterPush;
  incomingFighter.pendingKnockdown = true;
  incomingFighter.throwKnockdown = false;
  incomingFighter.grounded = false;
  // The Southpaw counter launch is knockdown-final: no air tech.
  incomingFighter.airTechArmed = false;
  incomingFighter.airHitstunFrames = 0;
  incomingFighter.vy = stance.counterLaunchVelocityY;
  incomingFighter.lastHitResult = "southpaw-countered";
  incomingFighter.hitFlash = 0.17;
  incomingFighter.dashFrames = 0;
  incomingFighter.queuedDashDirection = 0;
  counterFighter.meter = clamp(counterFighter.meter + 24, 0, GRIT_RULES.maximum);
  incomingFighter.meter = clamp(incomingFighter.meter + 12, 0, GRIT_RULES.maximum);
  const impact = collision?.point || {
    x: incomingFighter.x - counterFighter.facing * 28,
    y: incomingFighter.y - 132,
  };
  pushBattleDamageMark(incomingFighter, "special");
  spawnHit(impact.x, impact.y, counterFighter.def, "special", false, { direction: counterFighter.facing, counter: true });
  state.effects.push({ kind: "counterPunch", x: impact.x, y: impact.y, life: 0.62, max: 0.62, color: counterFighter.def.accent });
  spawnCombatText(impact.x, impact.y - 128, "COUNTER-PUNCH!", counterFighter.def.accent);
  applyViolenceResponse("special", { counter: true, side: counterFighter.side });
  state.lastImpactSide = counterFighter.side;
  if ($("#flashToggle").checked) state.flash = Math.max(state.flash, 0.11);
  sound("hit-heavy", counterFighter);
  updateHud();
  return true;
}

function registerAliFlow(attacker, attack) {
  if (attacker.def.id !== "ali"
    || attack.level === ATTACK_LEVELS.THROW
    || attacker.rhythmLastAttackSerial === attack.attackSerial) return;
  const continuing = attacker.rhythmStacks > 0 && state.simulationTick <= attacker.rhythmExpiresFrame;
  attacker.rhythmStacks = continuing ? Math.min(3, attacker.rhythmStacks + 1) : 1;
  attacker.rhythmExpiresFrame = state.simulationTick + 96;
  attacker.rhythmLastAttackSerial = attack.attackSerial;
  attacker.specialGlow = Math.max(attacker.specialGlow, 0.35 + attacker.rhythmStacks * 0.12);
  const massive = attacker.rhythmStacks === 3;
  spawnCombatText(
    attacker.x,
    attacker.y - attacker.height - 88,
    massive ? "MASSIVE FLOW!" : `FLOW ${attacker.rhythmStacks}/3`,
    massive ? "#ff4fb9" : attacker.def.accent,
  );
  state.effects.push({
    kind: "flowPulse",
    x: attacker.x,
    y: attacker.y - 112,
    life: massive ? 0.7 : 0.42,
    max: massive ? 0.7 : 0.42,
    color: massive ? "#ff4fb9" : attacker.def.accent,
    stacks: attacker.rhythmStacks,
  });
  if (massive && $("#flashToggle").checked) state.flash = Math.max(state.flash, 0.06);
}

// R1.9: shared trial/school observation for every landed player hit. Lives in
// one helper because the grab path returns out of hit() before the ordinary
// flow — throws and throw-type back specials must still advance trials and
// FIGHT SCHOOL. Sim-visible state is only the trial machine the lab already
// owned; medals/school are guarded meta on the announce() pattern.
function observeTrainingHit(attacker, victim, attack) {
  if (state.mode !== "training" || attacker.side !== 0) return;
  // 5.1: the guard reversal is an advanced move with no kitAction, so it used
  // to report as a plain "special" — the SPLIT SECOND lesson needs its name.
  const action = attack.kitAction || (attack.profileId === "guard-reversal" ? "guardReversal" : attack.kind);
  const limb = attack.limb || "punch";
  const trialProgress = recordTrainingTrialHit(state.training, {
    fighterId: attacker.kitId,
    action,
    limb,
    attackSerial: attack.attackSerial,
    frame: state.simulationTick,
  });
  if (rollbackResimulating) return;
  // Medal persistence: first completion of a trial banks its tier medal. Demo
  // playback completes trials too but never earns the medal.
  if (trialProgress.complete && !trialDemo.active) {
    const trial = comboTrialsForFighter(attacker.kitId)[state.training.trialIndex];
    if (trial && !medalForTrial(trialMedals, attacker.kitId, trial.id)) {
      awardTrialMedal(trialMedals, attacker.kitId, trial);
      saveTrialMedals();
      trainingFxDebug.medalAwards += 1;
      state.training.lastResult = `${trial.tier.toUpperCase()} MEDAL · ${trial.name}`;
      refreshTrialMedalBadges();
    }
  }
  schoolEvent({
    type: "hit",
    action,
    limb,
    attackSerial: attack.attackSerial,
    back: Boolean(attack.backThrow),
    dizzy: victim.dizzyFrames > 0,
  });
}

function hit(attacker, victim, attack, collision) {
  if (triggerSouthpawCounter(victim, attacker, attack, collision)) return;
  if (attack.level === ATTACK_LEVELS.THROW) {
    if (!victim.grounded || victim.throwInvulnerableFrames > 0 || victim.down || victim.wakeupFrames > 0) return;
    if (victim.grabbed || attacker.grabbing) return;
    // 5.3 CLOSE RANGE: the UNIVERSAL throw (kind "throw") only lands inside
    // its documented reach at the moment of CONTACT, not merely at the press.
    // Its authored hitbox reaches 152-167 world units while the grab range is
    // 119, so before this a throw pressed at 119 still landed after the victim
    // had walked ~38 units away and a backdash could not escape a grab it had
    // already seen. Command grabs (level THROW, kind "special") are unaffected
    // — their reach is authored per move and is the whole point of the move.
    if (attack.kind === "throw" && Math.abs(victim.x - attacker.x) > PROXIMITY_GRAB_RANGE) return;
    const recentThrowInput = state.simulationTick - victim.lastThrowInputFrame <= DEFENSE_RULES.throwTechWindowFrames;
    if (recentThrowInput
      || victim.attacking?.level === ATTACK_LEVELS.THROW) {
      techThrow(attacker, victim);
      return;
    }
    // Release 1.7 wave 11: getting grabbed punishes the taunt too.
    if (victim.tauntFrames > 0) interruptTaunt(victim);
    observeTrainingHit(attacker, victim, attack);
    beginGrabHold(attacker, victim, attack);
    return;
  }

  attacker.attackHit = true;
  attacker.attackHits += 1;
  attacker.lastAttackHitFrame = attacker.attackFrame;
  const blocked = canGuardAttack({
    level: attack.level,
    guardHeight: victim.guardHeight,
    guarding: victim.guarding,
    grounded: victim.grounded,
  });
  // Release 1.7: Perfect Guard — the block STARTED within the just-defend
  // window of this impact. Purely derived from existing frame counters.
  const perfect = blocked && isPerfectGuard(victim.guardStartedTick, state.simulationTick);
  // R1.9 FIGHT SCHOOL: guard lessons validate on the block itself (the
  // LOW/OVERHEAD combat-text hook level), landed-hit lessons below. Both are
  // meta observations on the announce() guard pattern.
  if (!rollbackResimulating && state.mode === "training" && blocked && victim.side === 0) {
    schoolEvent({ type: "block", level: attack.level, perfect });
  }
  if (!blocked) observeTrainingHit(attacker, victim, attack);
  const armored = !blocked
    && attack.level !== ATTACK_LEVELS.THROW
    && victim.attacking?.armorFrames > 0
    && victim.attackFrame <= victim.attacking.armorFrames
    && victim.armorHits < 1;
  attacker.attackConnected = blocked ? "block" : "hit";
  attacker.confirmWindowFrames = 12;
  const counter = !blocked && !armored && attack.level !== ATTACK_LEVELS.THROW && isCounterHit(victim);
  // 5.3 OKIZEME: this strike landed on the rising frames — read BEFORE the
  // wake clock is touched anywhere downstream so the label is truthful.
  const meaty = victim.wakeupFrames > 0;
  const wasJuggle = !victim.grounded || victim.pendingKnockdown;
  // v2.9 FLOW: demo coverage beats — a genuine counter-hit, and a hit landed
  // on an already-launched victim (the strict juggle read). Guarded inside.
  if (!blocked && !armored) {
    if (counter) demoChoreoBeat(attacker.side, "counterhit");
    if (!victim.grounded && victim.pendingKnockdown) demoChoreoBeat(attacker.side, "juggle");
  }
  let comboResult = { hitNumber: 1, damageScale: 1 };
  if (!blocked && attack.level !== ATTACK_LEVELS.THROW) {
    comboResult = attacker.combo.registerHit(state.simulationTick, victim.juggleCount);
    if ((attack.maxHits || 1) > 1 && attacker.attackHits > 1) {
      comboResult.damageScale = Math.max(comboResult.damageScale, COMBO_RULES.multiHitFloor);
    }
  } else if (!blocked) attacker.combo.reset();
  const baseDamage = attack.damage
    * (counter ? DEFENSE_RULES.counterDamageMultiplier : 1)
    * comboResult.damageScale
    * (armored ? 0.65 : 1);
  // A Perfect Guard takes zero chip and sheds blockstun frames.
  const damage = blocked ? (perfect ? 0 : attack.chipDamage) : baseDamage;
  victim.health = blocked
    ? Math.max(1, victim.health - damage)
    : clamp(victim.health - damage, 0, 100);
  victim.lastDamageFrame = state.simulationTick;
  // v2.1 PROGRESSION: damage-source latch (chip / stage-weapon) read only at
  // round end; a Perfect Guard deals nothing so it never becomes "the last
  // word". Guarded meta observation — no sim state involved.
  if (!rollbackResimulating && !(blocked && perfect)) {
    progressionNoteDamage(victim.side, {
      chip: blocked,
      weapon: String(attack.profileId || "").startsWith("stage-weapon-"),
      amount: damage,
      kind: attack.kind,
      level: attack.level,
      superMove: Boolean(attack.superMove),
    });
    if (attacker.attackHits === 1) {
      progressionNoteLanded(attacker.side, {
        blocked: blocked || armored,
        kind: attack.kind,
        superMove: Boolean(attack.superMove),
        // Attack instances carry no "enhanced" flag — a Grit price IS the
        // flag, and the super is already claimed by the branch above.
        enhanced: Number(attack.gritCost) > 0,
      });
    }
    if (!blocked && !armored && attack.superMove && attacker.attackHits === 1) {
      progressionMatch.supers[attacker.side] += 1;
    }
  }
  victim.blockstunFrames = blocked
    ? Math.max(1, attack.blockstunFrames - (perfect ? PERFECT_GUARD_RULES.blockstunReductionFrames : 0))
    : 0;
  victim.hitstunFrames = blocked || armored ? 0 : attack.hitstunFrames + (counter ? DEFENSE_RULES.counterHitstunBonusFrames : 0);
  victim.stun = Math.max(victim.hitstunFrames, victim.blockstunFrames) / SIMULATION_HZ;
  // Release 1.7: blocked hits pressure the guard gauge exactly where the
  // blockstun is set; a full gauge shatters into GUARD CRUSH inside.
  if (blocked) addGuardPressure(victim, attacker, attack, { perfect });
  if (state.mode === "training" && attacker.side === 0) {
    const remainingRecovery = Math.max(0, (attack.durationFrames || 0) - attacker.attackFrame);
    state.training.lastAdvantage = (victim.blockstunFrames || victim.hitstunFrames) - remainingRecovery;
    state.training.lastResult = blocked ? (perfect ? "PERFECT GUARD" : "BLOCK") : armored ? "ARMOR" : "HIT";
  }
  // Training readout: the player's own Perfect Guards are counted for practice.
  if (state.mode === "training" && perfect && victim.side === 0) state.training.perfectGuards += 1;
  // A back throw sends the victim behind the thrower, which is how corners get
  // swapped in SF2. Everything else pushes along the attacker's facing.
  const pushDirection = attack.backThrow ? -attacker.facing : attacker.facing;
  // A Perfect Guard also sheds most of the block pushback, holding ground.
  victim.vx = pushDirection * attack.push * (blocked ? (perfect ? 0.12 : 0.28) : armored ? 0.12 : 1);
  victim.guardHeight = victim.crouch ? "low" : victim.guardHeight;
  victim.lastHitResult = victim.guardCrushFrames > 0 ? "guard-crush"
    : blocked ? (perfect ? "perfect-guard" : `blocked-${attack.level}`)
      : armored ? "armor" : counter ? "counter" : attack.level;
  victim.lastHitLevel = attack.level;
  if (!blocked && !armored) {
    // Release 1.8 GRIND: score attack — clean hits score by move class
    // (guarded meta bookkeeping inside; never touches sim state).
    awardHitScore(attacker, attack.superMove ? "super" : attack.kind, { counter });
    attacker.combo.addDamage(damage);
    registerAliFlow(attacker, attack);
    if (wasJuggle) victim.juggleCount += 1;
    // Release 1.7 wave 11: a landed hit punishes the taunt — no Grit.
    if (victim.tauntFrames > 0) interruptTaunt(victim);
    victim.attacking = null;
    victim.attackTime = 0;
    victim.attackFrame = 0;
    victim.attackHit = false;
    victim.dashFrames = 0;
    victim.queuedDashDirection = 0;
    const finalAttackHit = attacker.attackHits >= (attack.maxHits || 1);
    const shouldKnockDown = (attack.knockdown && (!attack.knockdownOnFinal || finalAttackHit))
      || attack.level === ATTACK_LEVELS.THROW;
    // Release 1.7 wave 11: corner wall-bounce arming. A knockdown-class
    // heavy/special connecting with the victim already within one body width
    // of the wall it is being pushed toward converts, once per combo, when
    // the flight actually reaches that wall (applyFighterPhysics). The bounce
    // will consume a juggle point, so it is never armed with the juggle
    // budget already spent.
    victim.wallBounceArmed = 0;
    if ((shouldKnockDown || attack.juggleLift)
      && qualifiesForWallBounce(attack)
      && !victim.wallBounceUsed
      && victim.juggleCount < (attack.juggleLimit || COMBO_RULES.juggleLimit)) {
      const wallX = pushDirection > 0 ? MOVEMENT_RULES.stageMaxX : MOVEMENT_RULES.stageMinX;
      const bodyWidth = victim.width * WALL_BOUNCE_RULES.proximityBodyWidths;
      if (Math.abs(wallX - victim.x) <= bodyWidth) {
        victim.wallBounceArmed = pushDirection;
        // The armed flight commits to the wall: the carry velocity always
        // reaches the clamp before the knockdown landing can clear the arm.
        victim.vx = pushDirection * Math.max(Math.abs(victim.vx), WALL_BOUNCE_RULES.carryVelocityX);
      }
    }
    if (shouldKnockDown) {
      // 5.3 CLOSE RANGE: a strike knockdown pays the SHORT throw immunity on
      // the way up (DEFENSE_RULES.strikeKnockdownThrowImmuneFrames), so a
      // sweep or a launcher is finally worth something to a grappler.
      victim.pendingKnockdown = true;
      victim.throwKnockdown = false;
      victim.grounded = false;
      victim.vy = attack.level === ATTACK_LEVELS.THROW ? -371
        : attack.launchVelocityY || -259 - attack.damage * 3.5;
    } else if (attack.juggleLift) {
      victim.pendingKnockdown = true;
      victim.throwKnockdown = false;
      victim.grounded = false;
      victim.vy = attack.juggleLift;
    }
    // Release 1.7: air recovery arming — every clean hit restarts the
    // airborne-hitstun clock. Authored launches (launchVelocityY juggle
    // starters, juggleLift mid-hits) and plain juggle hits stay escapable —
    // the classic tech read against launchers — while knockdown-final tumbles
    // (sweeps, air heavies, specials, a multi-hit's closing knockdown) and
    // every super hit still ride to the floor.
    victim.airHitstunFrames = 0;
    const authoredLaunch = Boolean(attack.launchVelocityY || attack.juggleLift);
    victim.airTechArmed = !attack.superMove && (authoredLaunch || !shouldKnockDown);
  } else if (armored) {
    victim.armorHits += 1;
    spawnCombatText(victim.x, victim.y - victim.height - 18, "SEISMIC ARMOR", victim.def.accent);
  }
  victim.hitFlash = 0.12;
  if (!blocked && !armored) {
    // Release 1.8 GRIND: Sudden Death house rule — the round's FIRST clean
    // melee hit instantly dizzies its victim. The one-shot flag is sim state
    // (snapshotted + checksummed) and the rule itself comes from matchRules,
    // which both rollback peers derive from the same mutator config.
    if (state.matchRules.suddenDeathDizzy && !state.suddenDeathHitDone) {
      state.suddenDeathHitDone = true;
      if (victim.dizzyFrames <= 0 && victim.stunImmuneFrames <= 0) enterDizzy(victim, attacker);
    }
    addStun(victim, attacker, attack, { counter, blocked });
    if (victim.carriedWeapon) dropStageWeapon(victim, false);
  }
  // BLOCK ECONOMY: a blocked hit pays the attacker half (attackGritGain);
  // the defender's share is untouched, so blocking correctly is close to
  // Grit-neutral instead of funding the attacker's super.
  attacker.meter = clamp(attacker.meter + attackGritGain(attack, { blocked }), 0, GRIT_RULES.maximum);
  victim.meter = clamp(victim.meter + attack.meter * GRIT_RULES.damageTakenGainMultiplier, 0, GRIT_RULES.maximum);
  // Release 1.7: a Perfect Guard banks bonus Grit for the defender.
  if (perfect) victim.meter = clamp(victim.meter + PERFECT_GUARD_RULES.gritBonus, 0, GRIT_RULES.maximum);
  const impactTier = attack.superMove ? "super"
    : attack.kind === "throw" ? "throw"
      : attack.kind === "special" ? "special"
        : attack.kind === "heavy" ? "heavy" : "light";
  if (!blocked && !armored) pushBattleDamageMark(victim, impactTier);
  applyViolenceResponse(impactTier, {
    blocked,
    counter,
    final: attack.superMove && attacker.attackHits >= (attack.maxHits || 1),
    damage: attack.damage,
    side: attacker.side,
    // A super or a weapon landing this close to the crowd is the second
    // flinch beat; the tiers below it only stir.
    splatX: impactTier === "super" || impactTier === "weapon" ? victim.x : null,
  });
  const impact = collision?.point || { x: victim.x - attacker.facing * 22, y: victim.y - 105 };
  spawnHit(impact.x, impact.y, attacker.def, impactTier, blocked, { direction: attacker.facing, counter });
  if (attack.superMove) {
    state.effects.push({ kind: "super", x: impact.x, y: impact.y, life: 0.55, max: 0.55, color: attacker.def.accent });
    // Ordinary hits get a glint, not a whiteout — the full-strength flash is
    // reserved for supers, dizzies and guard crushes so it means something.
    if ($("#flashToggle").checked) state.flash = Math.max(state.flash, attacker.attackHits >= attack.maxHits ? 0.1 : 0.04);
  }
  // 5.3 OKIZEME: a strike that lands on the vulnerable rising frames is a
  // MEATY and says so — the read is worth naming, exactly like COUNTER.
  if (meaty) {
    spawnCombatText(impact.x, impact.y - 88, blocked ? "MEATY BLOCKED" : "MEATY", blocked ? "#8fd8ff" : "#ffca4a");
    if (!rollbackResimulating) mechFxDebug.meaties += 1;
  }
  if (counter) spawnCombatText(impact.x, impact.y - 74, "COUNTER", attacker.def.accent);
  // R1.9 color assist: the two mixup callouts pick up the colorblind-safe
  // palette plus a distinct glyph each (drop-arrow / down-chevron) so the cue
  // never rides on hue alone. Standard palette keeps the shipped label text
  // exactly (smoke tests read combatTextLabels).
  else if (!blocked && attack.level === ATTACK_LEVELS.OVERHEAD) {
    spawnCombatText(impact.x, impact.y - 70, colorAssistActive() ? "⤓ OVERHEAD" : "OVERHEAD", assistColor("overhead", attacker.def.accent));
  } else if (!blocked && attack.level === ATTACK_LEVELS.LOW) {
    spawnCombatText(impact.x, impact.y - 64, colorAssistActive() ? "▼ LOW" : "LOW", assistColor("low", attacker.def.accent));
  }
  else if (!blocked && attack.level === ATTACK_LEVELS.THROW) spawnCombatText(impact.x, impact.y - 72, "THROW", attacker.def.accent);
  // Release 1.7: Perfect Guard flash — a cyan ring plus PERFECT combat text
  // (checksum-exempt state.effects, same channel every hit spark uses).
  if (perfect) {
    if (!rollbackResimulating) {
      mechFxDebug.perfectGuards += 1;
      // 5.3: a Perfect Guard deals nothing, so it never reaches
      // progressionNoteDamage — it has to book its own block here or the
      // SPLIT SECOND rule would read a perfect fight as "never blocked".
      if (victim.side === 0 && !sideIsCpuControlled(0)) {
        progressionMatch.digest.blocks += 1;
        progressionMatch.digest.perfectGuards += 1;
      }
      // v2.1 PROGRESSION: the defender's Perfect Guard ledger event (guarded).
      progressionEvent("perfectGuard", {}, victim.side);
    }
    state.effects.push({
      kind: "shockRing", x: impact.x, y: impact.y,
      size: 78, life: 0.3, max: 0.3, color: "#63f2ff",
    });
    spawnCombatText(impact.x, impact.y - 80, "PERFECT", "#63f2ff");
  }
  sound(attackImpactCue(attack, blocked), blocked ? victim : attacker);
  // The distinct 'tink' variant layered over the block cue on a just-defend.
  if (perfect) perfectGuardTink();
  updateHud();
  state.lastImpactSide = attacker.side;
}

// R1.9 FIGHT SCHOOL: the Final Blow lesson needs the REAL finish flow, which
// training otherwise short-circuits. Armed only while the school's finisher
// step is live and the dummy went down — training is strictly offline, so a
// meta read here can never touch rollback determinism.
function schoolFinisherArmed() {
  if (!schoolSession.active || !schoolSession.machine) return false;
  const lesson = fightSchoolLesson(schoolSession.machine);
  return lesson?.steps[schoolSession.machine.step]?.kind === "finisher";
}

function checkKnockout() {
  if (state.phase !== "fight" || !state.fighters.some((fighter) => fighter.health <= 0)) return;
  if (state.mode === "training"
    && !(schoolFinisherArmed() && state.fighters[1].health <= 0 && state.fighters[0].health > 0)) {
    const winner = state.fighters[0].health <= 0 ? 1 : 0;
    if (state.training.autoRecover) {
      state.training.lastResult = `${state.fighters[winner].def.name.toUpperCase()} RESET`;
      resetTrainingPosition(true);
    } else {
      state.fighters.forEach((fighter) => {
        fighter.health = Math.max(1, fighter.health);
        fighter.pendingKnockdown = false;
      });
      state.training.lastResult = "KO HELD · RESET WHEN READY";
      updateHud();
      updateTrainingUi();
    }
    return;
  }
  const [first, second] = state.fighters;
  const winner = first.health <= 0 && second.health <= 0
    ? state.lastImpactSide ?? 0
    : first.health <= 0 ? 1 : 0;
  const attacker = state.fighters[winner];
  const victim = state.fighters[1 - winner];
  for (const fighter of state.fighters) clearGrabState(fighter);
  state.phase = "finish";
  state.phaseTime = 6;
  state.finishWinner = winner;
  victim.down = false;
  victim.pendingKnockdown = false;
  victim.knockdownFrames = 0;
  victim.wakeupFrames = 0;
  victim.stun = 99;
  victim.hitstunFrames = 5940;
  attacker.attacking = null;
  duckMusic(0.34, 1900);
  stirCrowd(1.4, "", { side: winner, splatX: victim.x });
  announce("FINISH THEM", "LP = A  ·  LK = B  ·  ANY DISTANCE", 2.2);
  if (!rollbackResimulating) setTouchPrompt("final");
  updateHud();
  sound("finish");
  // Wave 6: KO freeze-frame punch-in on the killing hit (render-only latch,
  // guarded + tick-deduped inside).
  latchKoCameraPunch();
}

function resolveCombatInteractions() {
  const contacts = state.fighters.map((attacker, side) => {
    if (!attacker.attacking) return null;
    const maximumHits = attacker.attacking.maxHits || 1;
    if (attacker.attackHits >= maximumHits) return null;
    if (attacker.attackHits > 0
      && attacker.attackFrame - attacker.lastAttackHitFrame < (attacker.attacking.rehitFrames || Infinity)) return null;
    const victim = state.fighters[1 - side];
    // The juggle limit exists to stop separate attacks being strung together in
    // the air. A single authored multi-hit move is already bounded by its own
    // maxHits and rehitFrames, so its later hits are exempt.
    const rehitOfSameMove = attacker.attackHits > 0;
    const juggleLimit = attacker.attacking.juggleLimit || COMBO_RULES.juggleLimit;
    if (!rehitOfSameMove
      && (!victim.grounded || victim.pendingKnockdown)
      && victim.juggleCount >= juggleLimit) return null;
    const collision = findBoxCollision(attacker, victim);
    return collision ? { attacker, victim, attack: attacker.attacking, collision } : null;
  }).filter(Boolean);
  for (const contact of contacts) {
    if (contact.attack.level === ATTACK_LEVELS.THROW && contact.attacker.attacking !== contact.attack) continue;
    hit(contact.attacker, contact.victim, contact.attack, contact.collision);
  }
  checkKnockout();
}

function updateComboState() {
  for (const attacker of state.fighters) {
    const defender = state.fighters[1 - attacker.side];
    const defenderInCombo = Boolean(defender
      && (defender.hitstunFrames > 0 || defender.pendingKnockdown || !defender.grounded));
    attacker.combo.tick(state.simulationTick, defenderInCombo);
    if (rollbackResimulating) continue;
    const readout = $(`#p${attacker.side + 1}Combo`);
    if (!readout) continue;
    const combo = attacker.combo.snapshot(state.simulationTick);
    readout.classList.toggle("active", combo.visible);
    const fx = comboFxState[attacker.side];
    const numberEl = readout.querySelector("b");
    if (combo.visible && combo.hits !== fx.hits) {
      numberEl.textContent = String(combo.hits);
      // Physical hit-pop on every increment (scale overshoot back to 1).
      if (combo.hits > fx.hits) restartCssAnimation(numberEl, "pop");
    }
    // Heat tiers: styling escalates at 3 / 5 / 8+ hits and the label upgrades.
    const tier = !combo.visible ? 0 : combo.hits >= 8 ? 3 : combo.hits >= 5 ? 2 : combo.hits >= 3 ? 1 : 0;
    if (tier !== fx.tier) {
      readout.classList.toggle("hot", tier >= 1);
      readout.classList.toggle("blazing", tier >= 2);
      readout.classList.toggle("inferno", tier >= 3);
      readout.querySelector("span").textContent = tier >= 3 ? "FINAL COMBO" : tier >= 2 ? "SAVAGE COMBO" : "HIT COMBO";
      if (tier > fx.tier) hudFxDebug.comboHeat += 1;
      fx.tier = tier;
    }
    fx.hits = combo.visible ? combo.hits : 0;
    // The damage line counts up toward the real total instead of jumping.
    const damageTarget = Math.round(combo.damage);
    fx.damageShown = !combo.visible || damageTarget < fx.damageShown
      ? damageTarget
      : Math.min(damageTarget, fx.damageShown + Math.max(1, (damageTarget - fx.damageShown) * 0.22));
    const damageLabel = Math.round(fx.damageShown);
    if (damageLabel !== fx.damageWritten) {
      fx.damageWritten = damageLabel;
      readout.querySelector("em").textContent = `${damageLabel} DAMAGE`;
    }
  }
}

// Hitstop is the freeze that lets the eye register a hit before anything else
// moves; it climbed toward genre values (6f light through 13f super) in the
// readability pass. The freeze no longer eats inputs — simulatePreparedGameTick
// keeps reading and buffering through it — so the longer stops make the fight
// easier to follow without loosening a single link.
const VIOLENCE_TIERS = Object.freeze({
  light: Object.freeze({ particles: 10, speed: 250, life: 0.72, size: 4.2, shake: 0.16, hitstop: 0.1, crowd: 0.12, decal: false }),
  heavy: Object.freeze({ particles: 22, speed: 430, life: 1.08, size: 6.2, shake: 0.31, hitstop: 0.167, crowd: 0.34, decal: true }),
  special: Object.freeze({ particles: 30, speed: 520, life: 1.24, size: 7.2, shake: 0.43, hitstop: 0.2, crowd: 0.56, decal: true }),
  throw: Object.freeze({ particles: 26, speed: 470, life: 1.18, size: 7, shake: 0.46, hitstop: 0.2, crowd: 0.62, decal: true }),
  weapon: Object.freeze({ particles: 28, speed: 540, life: 1.28, size: 7.6, shake: 0.5, hitstop: 0.217, crowd: 0.68, decal: true }),
  super: Object.freeze({ particles: 44, speed: 700, life: 1.58, size: 9, shake: 0.76, hitstop: 0.25, crowd: 1.05, decal: true }),
});

function violenceTier(kind = "light") {
  return VIOLENCE_TIERS[kind] || VIOLENCE_TIERS.light;
}

function applyViolenceResponse(kind, { blocked = false, counter = false, final = false, damage = 0, side = -1, splatX = null } = {}) {
  // Wave 15: every screen response has a matching hand response — phone
  // vibration plus pad dual-rumble (toggle, resim guard and rate cap all
  // live inside combatHaptic).
  combatHaptic(kind, { damage, blocked, counter });
  if (blocked) {
    state.shake = Math.max(state.shake, 0.1);
    state.hitstop = Math.max(state.hitstop, 0.067);
    return;
  }
  const profile = violenceTier(kind);
  const counterScale = counter ? 1.22 : 1;
  state.shake = Math.max(state.shake, profile.shake * counterScale);
  const hitstop = kind === "super" && !final ? 0.15 : profile.hitstop;
  state.hitstop = Math.max(state.hitstop, hitstop * counterScale);
  // v5.3 CROWD DEPTH: the attacker's side rides the stir, so half the crowd
  // cheers this hit and half winces at it.
  stirCrowd(profile.crowd * counterScale, "", { side, splatX });
}

function spawnHit(x, y, def, attackKind, blocked, { direction = 1, counter = false } = {}) {
  // Wave 6: directional camera recoil on landed heavy-class hits plus the
  // counter-hit punch-in (render-only latches, guarded + tick-deduped inside).
  latchImpactCinema(x, y, attackKind, blocked, direction, counter);
  // CINEMA 3D impact latch: null when 3D is off (zero-cost), presentation-only
  // when on — the bridge guards rollbackResimulating + tick-dedupes inside,
  // following the announce()/latch pattern above.
  if (cinema3dBridge.onHit) {
    // v2.6 ELEMENTS: the payload carries the attacker's element id so the 3D
    // impact layer re-tints its protection-mask-joined burst stack per kit.
    cinema3dBridge.onHit({
      x, y, kind: attackKind, blocked, direction, counter, tick: state.simulationTick,
      element: fighterElementKit(def)?.id || null,
    });
  }
  if (blocked) {
    const count = Math.max(3, Math.round(8 * state.performance.particleScale));
    for (let index = 0; index < count; index += 1) {
      const angle = visualRandom() * Math.PI * 2;
      const speed = 90 + visualRandom() * 220;
      state.particles.push({
        kind: "guardSpark", x, y,
        vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
        gravity: 420, drag: 0.975,
        life: 0.16 + visualRandom() * 0.2, max: 0.36,
        size: 1.5 + visualRandom() * 4, color: visualRandom() > 0.5 ? "#f5f7ff" : def.accent,
      });
    }
    state.effects.push({ kind: "guard", x, y, life: 0.28, max: 0.28, color: def.accent });
    return;
  }

  const tierName = VIOLENCE_TIERS[attackKind] ? attackKind : attackKind === "throw-object" ? "weapon" : "light";
  const profile = violenceTier(tierName);
  // Release 1.6 LOUD: layered synth components under the hit sample by
  // violence tier (rollback guard + toggles live inside).
  impactLayerAudio(tierName, { counter });
  // Wave 9: counter-hit attacker bark (guarded + tick-deduped inside).
  if (counter) fighterReactiveCue(def.id, "counter");
  const graphicScale = state.graphicFatalities ? 1 : 0.34;
  const counterScale = counter ? 1.26 : 1;
  const count = Math.max(4, Math.round(profile.particles * graphicScale * counterScale * state.performance.particleScale));
  const bloodPalette = state.graphicFatalities
    ? ["#8f0710", "#bd0c18", "#e32632", "#5b060b"]
    : ["#7e1520", "#a52a34"];
  for (let index = 0; index < count; index += 1) {
    const spread = (visualRandom() - 0.5) * 1.65;
    const speed = 90 + visualRandom() * profile.speed * counterScale;
    state.particles.push({
      kind: "blood",
      x: x + (visualRandom() - 0.5) * 8,
      y: y + (visualRandom() - 0.5) * 12,
      vx: direction * (speed * (0.38 + visualRandom() * 0.7)) + Math.sin(spread) * speed * 0.34,
      vy: -80 - Math.cos(spread) * speed * (0.26 + visualRandom() * 0.5),
      gravity: 860,
      drag: 0.982,
      life: 0.28 + visualRandom() * profile.life,
      max: profile.life + 0.28,
      size: 1.8 + visualRandom() * profile.size * graphicScale,
      color: bloodPalette[Math.floor(visualRandom() * bloodPalette.length) % bloodPalette.length],
    });
  }
  state.effects.push({
    kind: "bloodBurst", tier: tierName, direction, x, y,
    life: tierName === "super" ? 0.52 : 0.34,
    max: tierName === "super" ? 0.52 : 0.34,
    color: "#d41120",
  });
  // Impact light spill (wave 4): heavy-tier and counter hits briefly become a
  // one-shot light source that tints the surrounding stage with the attacker's
  // spark colour. Carried on the existing impactFlash effect (same life/max,
  // so sparkLine/shockRing/impactFlash counts are untouched); the flash toggle
  // gates it at push time exactly like the full-screen flashes.
  const spillTier = ["heavy", "special", "super", "weapon"].includes(tierName) || counter;
  state.effects.push({
    kind: "impactFlash", tier: tierName, x, y,
    life: tierName === "super" ? 0.22 : 0.12,
    max: tierName === "super" ? 0.22 : 0.12,
    color: "#fff4df",
    spill: spillTier && $("#flashToggle").checked ? def.accent : null,
  });
  if (counter) {
    // Counter-hit focus burst (wave 4): a distinct gold ring of anime speed
    // lines converging on the impact point, layered with the victim's
    // inverted flash pop in drawFighter so counters read instantly.
    state.effects.push({
      kind: "counterFocus", x, y,
      life: 0.3, max: 0.3, color: "#ffd94f",
    });
  }
  // MOTION FIX 1: the evolving hitspark — the shared spawn site every landed
  // hit, special and super inherits. THREE beats, ~6 ticks total (effects
  // keep ticking through hitstop): a one-frame white flash, then radiating
  // shards cut from the spark flipbook at a per-hit randomized rotation and
  // count, then gone. Shard cells re-hash every sim tick so no two rendered
  // frames share a silhouette — the static spoked-ring "wheel" is dead.
  ensureElementMedia();
  state.effects.push({
    kind: "hitSpark", tier: tierName, x, y, direction,
    life: 0.15, max: 0.15,
    color: def.accent,
    shards: 5 + Math.floor(visualRandom() * 4),
    baseRot: visualRandom() * Math.PI * 2,
    seed: Math.floor(visualRandom() * 4096),
    size: (tierName === "super" ? 96 : tierName === "special" ? 74 : tierName === "light" ? 44 : 60)
      * (counter ? 1.25 : 1),
  });
  // White-hot speed-line sparks along the hit direction, drawn additively so
  // they bloom against the dark stages; a shock ring joins the heavy tiers.
  // MOTION FIX 3: the ring is 2-3 frame punctuation (0.26 → 0.12) — it
  // finishes its whole expansion during the impact hold instead of freezing
  // mid-bloom as a decal.
  const ringSizes = { heavy: 74, special: 96, super: 128, weapon: 82 };
  if (ringSizes[tierName] || counter) {
    state.effects.push({
      kind: "shockRing", x, y,
      size: (ringSizes[tierName] || 64) * (counter ? 1.3 : 1),
      life: 0.12, max: 0.12, color: "#fff2d8",
    });
  }
  const sparkCount = Math.max(3, Math.round((tierName === "light" ? 4 : 9)
    * counterScale * state.performance.particleScale));
  for (let index = 0; index < sparkCount; index += 1) {
    const cone = (visualRandom() - 0.5) * 1.9;
    const sparkSpeed = 260 + visualRandom() * 520;
    state.particles.push({
      kind: "sparkLine", x, y,
      vx: direction * Math.cos(cone) * sparkSpeed,
      vy: Math.sin(cone) * sparkSpeed - 40,
      gravity: 320, drag: 0.94,
      life: 0.1 + visualRandom() * 0.18, max: 0.28,
      size: 1.2 + visualRandom() * 2.2,
      color: index % 3 ? "#fff6db" : def.accent,
    });
  }
  if (profile.decal && state.graphicFatalities) {
    const decalLife = 2.8 + visualRandom() * 2.4;
    state.effects.push({
      kind: "bloodDecal", tier: tierName,
      x: clamp(x + direction * (28 + visualRandom() * 68), 28, W - 28),
      y: FLOOR + 3,
      width: 24 + visualRandom() * (tierName === "super" ? 82 : 46),
      life: decalLife, max: decalLife, color: "#72060d",
    });
  }
}

// A body that ends a lunge inside the opponent slides back out at this rate
// (px per fighter per tick) instead of teleporting apart in one step. Ordinary
// walking contact produces corrections far below the cap, so normal pushing is
// untouched; only the big post-pass-through overlaps ease, resolving a full
// body overlap in roughly four to six frames.
const SEPARATION_MAX_STEP_X = 14;

// Pass-through is the armored lunges' identity, but only while the move is
// actually travelling. Once the active window closes, the pushbox re-engages
// and the eased correction walks the pair apart through the recovery.
function attackPassesThrough(fighter) {
  return Boolean(fighter.attacking?.ignorePushbox)
    && fighter.attackFrame <= fighter.attacking.activeEndFrame;
}

function separateFighters() {
  const [a, b] = state.fighters;
  if (!a || !b) return;
  if (a.grabbing || b.grabbing || a.grabbed || b.grabbed) return;
  if (attackPassesThrough(a) || attackPassesThrough(b)) return;
  const positions = resolveArenaCollision(
    {
      x: a.x,
      y: a.y,
      grounded: a.grounded,
      side: a.side,
      halfWidth: a.crouch ? a.movement.crouchingPushboxHalfWidth : a.movement.standingPushboxHalfWidth,
    },
    {
      x: b.x,
      y: b.y,
      grounded: b.grounded,
      side: b.side,
      halfWidth: b.crouch ? b.movement.crouchingPushboxHalfWidth : b.movement.standingPushboxHalfWidth,
    },
    { floorY: FLOOR },
  );
  a.x += clamp(positions.aX - a.x, -SEPARATION_MAX_STEP_X, SEPARATION_MAX_STEP_X);
  b.x += clamp(positions.bX - b.x, -SEPARATION_MAX_STEP_X, SEPARATION_MAX_STEP_X);
}

// Offset of the opponent along the fighter's own facing: positive in front,
// negative behind. That sign is what lets the reach test tell a close cross-up
// (still reachable, keep the lock) from an opponent stranded across the stage.
function turnContext(fighter, opponent) {
  return {
    opponentOffset: (opponent.x - fighter.x) * fighter.facing,
    scale: FIGHTER_SCALE,
    allowance: HURTBOX_MAX_EXTENT,
  };
}

function updateFacings() {
  const [a, b] = state.fighters;
  if (!a || !b || state.finisher) return;
  // Grabs pose both fighters explicitly and finishers are fully scripted; both
  // still keep the axis current so whatever follows resumes oriented correctly.
  const posed = a.grabbing || b.grabbing || a.grabbed || b.grabbed;
  // Preserve a move's committed direction while it can still hit, so cross-ups
  // punish whiffs instead of auto-correcting the hitbox. The moment the last
  // hitbox window closes, the fighter snaps back onto the pair's axis.
  const resolved = resolvePairFacing({
    previousAxis: state.facingAxis,
    aX: a.x,
    bX: b.x,
    aFacing: a.facing,
    bFacing: b.facing,
    aCanTurn: !posed && fighterCanTurn(a, turnContext(a, b)),
    bCanTurn: !posed && fighterCanTurn(b, turnContext(b, a)),
  });
  state.facingAxis = resolved.axis;
  if (posed) return;
  a.facing = resolved.aFacing;
  b.facing = resolved.bFacing;
}

function resolveFighterState(fighter) {
  if (state.finisher) return FIGHTER_STATES.FINISHER;
  if (fighter.down || fighter.knockdownFrames > 0) return FIGHTER_STATES.KNOCKDOWN;
  if (fighter.wakeupFrames > 0) return FIGHTER_STATES.WAKEUP;
  if (fighter.dizzyFrames > 0) return FIGHTER_STATES.HITSTUN;
  // Release 1.7: GUARD CRUSH is helpless — it reads as hitstun to every
  // downstream system, exactly like dizzy.
  if (fighter.guardCrushFrames > 0) return FIGHTER_STATES.HITSTUN;
  if (fighter.grabbing || fighter.grabbed) return FIGHTER_STATES.THROW;
  if (fighter.throwTechFlashFrames > 0) return FIGHTER_STATES.THROW_TECH;
  if (fighter.blockstunFrames > 0) return FIGHTER_STATES.BLOCKSTUN;
  if (fighter.hitstunFrames > 0 || fighter.pendingKnockdown) return FIGHTER_STATES.HITSTUN;
  if (fighter.attacking?.level === ATTACK_LEVELS.THROW) return FIGHTER_STATES.THROW;
  if (fighter.attacking) return FIGHTER_STATES.ATTACK;
  if (!fighter.grounded) return FIGHTER_STATES.JUMP;
  if (fighter.dashFrames > 0) return FIGHTER_STATES.DASH;
  if (fighter.block) return FIGHTER_STATES.BLOCK;
  if (fighter.crouch) return FIGHTER_STATES.CROUCH;
  if (Math.abs(fighter.vx) > 20) return FIGHTER_STATES.WALK;
  return FIGHTER_STATES.IDLE;
}

function syncFighterStateMachines() {
  for (const fighter of state.fighters) {
    transitionFighterState(fighter, resolveFighterState(fighter), state.simulationTick);
  }
}

function simulatePreparedGameTick(dt, input0 = {}, input1 = {}) {
  const skippedFlow = trySkipFightFlow(input0, input1);
  if (skippedFlow && state.phase === "fight") {
    input0 = {};
    input1 = {};
  }
  // Shake and flash decay through the freeze — with the longer readability
  // hitstop they would otherwise hold at full blast for the whole stop and
  // read as more chaos, not more punctuation.
  state.shake = Math.max(0, state.shake - dt * 2.8);
  state.flash = Math.max(0, state.flash - dt);
  if (state.hitstop > 0) {
    state.hitstop = Math.max(0, state.hitstop - dt);
    // MOTION FIX 4: NOTHING FREEZES. The fighters hold the impact, but the
    // VFX keep living straight through the stop — sparks fly on, rings
    // finish expanding, dust drifts, decals burn out. Particles/effects are
    // checksum-exempt visual state already ticked inside the sim path, so
    // advancing them during the freeze changes zero rollback behaviour.
    advanceVisualEffects(dt);
    // The freeze must not eat inputs. Both fighters' raw inputs still run the
    // full input pipeline — motion history, taunt taps, action buffering into
    // the rollback-snapshotted FrameInputBuffer — while physics stays frozen,
    // so a link pressed during the stop comes out the other side intact. The
    // returned resolved input is deliberately discarded; nothing may act yet.
    if (state.fighters.length === 2) {
      prepareFighterInput(state.fighters[0], input0);
      prepareFighterInput(state.fighters[1], input1);
    }
    return;
  }
  state.phaseTime = Math.max(0, state.phaseTime - dt);

  updateFacings();
  if (state.phase === "intro") {
    input0 = {};
    input1 = {};
    // Release 1.8 GRIND — Block War walk-in: an incoming teammate strolls to
    // their slot during the intro. Pure dt math on snapshotted plain fields
    // (introWalkTarget), so it is deterministic and rollback-safe by shape.
    updateIntroWalkIns(dt);
    if (state.phaseTime <= 0) {
      state.phase = "fight";
      for (const fighter of state.fighters) fighter.introWalkTarget = null;
      updateFlowSkipHint();
      // v5.3 SPECTACLE: the round opens on a stinger over the bed. Every
      // round reaches this edge (resetRound always returns to "intro"), and
      // the skip path below fires the same cue, so ROUND 2 with the intro
      // skipped still gets its downbeat.
      playMusicStinger("roundstart", { source: `round${state.round}` });
    }
  }

  input0 = prepareFighterInput(state.fighters[0], input0);
  input1 = prepareFighterInput(state.fighters[1], input1);

  updateFighter(state.fighters[0], state.fighters[1], input0, dt);
  updateFighter(state.fighters[1], state.fighters[0], input1, dt);
  updateGrabHolds();
  updateStageWeapon();
  // Release 1.8 GRIND: Infinite Grit house rule — meters pinned full, exactly
  // the training-lab precedent. Derived from matchRules (mutator config), so
  // both rollback peers agree; the pin re-derives identically on resim.
  if (state.matchRules.infiniteGrit) {
    let gritHudDirty = false;
    for (const fighter of state.fighters) {
      if (fighter.meter < GRIT_RULES.maximum) gritHudDirty = true;
      fighter.meter = GRIT_RULES.maximum;
    }
    if (gritHudDirty) updateHud();
  }
  // v5.3: one fixed step of the crowd's decay, and — once the room has
  // settled — the author with it, so the next authorless stir cannot inherit
  // the last hit's side (engine/crowd-reaction.mjs).
  decayCrowdReaction(state);
  const superActive = state.fighters.some((fighter) => fighter.attacking?.superMove);
  superDimLevel = clamp(superDimLevel + (superActive ? 0.09 : -0.055), 0, 1);
  // Wave 6 win-pose curtain call, eased beside superDimLevel on the same
  // deliberately-unsnapshotted pattern. Keyed off a fatality-free roundover so
  // the finisher cinematic always owns its own frame.
  const winPoseActive = state.phase === "roundover" && !state.finisher && state.finisherType < 0;
  roundOverDimLevel = clamp(roundOverDimLevel + (winPoseActive ? 0.045 : -0.06), 0, 1);
  // 2.8: the killing blow dims the street to a spotlight on the kill (reuses
  // the wave-6 pool rig at draw time; eases out with the cinematic hold).
  const fatalitySpotActive = Boolean(state.finisher?.fatalityTriggered) && state.graphicFatalities;
  fatalitySpotLevel = clamp(fatalitySpotLevel + (fatalitySpotActive ? 0.05 : -0.07), 0, 1);
  if (state.finisher) updateFinisher(dt);
  else {
    updateProjectiles(dt);
    updatePaintTraps();
    resolveCombatInteractions();
    separateFighters();
    updateFacings();
  }
  updateComboState();
  syncFighterStateMachines();

  if (state.mode === "training") {
    let trainingHudDirty = false;
    if (state.training.infiniteGrit) {
      state.fighters.forEach((fighter) => {
        if (fighter.meter < GRIT_RULES.maximum) trainingHudDirty = true;
        fighter.meter = GRIT_RULES.maximum;
      });
    }
    if (state.training.autoRecover && state.phase === "fight") {
      state.fighters.forEach((fighter) => {
        const ready = state.simulationTick - fighter.lastDamageFrame >= 90
          && fighter.hitstunFrames === 0
          && fighter.blockstunFrames === 0
          && !fighter.pendingKnockdown;
        if (!ready || fighter.health >= 100) return;
        fighter.health = Math.min(100, fighter.health + 0.45);
        trainingHudDirty = true;
      });
    }
    if (trainingHudDirty) updateHud();
  }

  if (state.phase === "fight" && state.mode !== "training") {
    state.timerCarry += dt;
    if (state.timerCarry >= 1) {
      state.timer = Math.max(0, state.timer - Math.floor(state.timerCarry));
      state.timerCarry %= 1;
      updateHud();
    }
    if (state.timer <= 0) {
      const winner = state.fighters[0].health >= state.fighters[1].health ? 0 : 1;
      finishRound(winner, -1);
    }
  } else if (state.phase === "finish" && state.phaseTime <= 0) {
    finishRound(state.finishWinner, -1);
  } else if (state.phase === "roundover" && state.phaseTime <= 0) {
    const winner = state.rounds[0] > state.rounds[1] ? 0 : 1;
    // Release 1.8 GRIND: rounds-to-win is match config now — survival and
    // Block War pairings are single-round, and the One-Round Showdown house
    // rule shortens versus sets the same way.
    if (state.rounds[winner] >= roundsToWinValue()) resolveMatchResult(winner);
    else resetRound();
  }

  advanceVisualEffects(dt);
  updateTrainingUi(input0);
}

// MOTION FIX 4: the particle/effect integration, extracted so the hitstop
// freeze can keep the VFX alive while the fighters hold. Called once per sim
// tick from simulatePreparedGameTick (frozen and unfrozen paths alike).
// Everything in here is checksum-exempt visual state on the existing pattern.
function advanceVisualEffects(dt) {
  for (const particle of state.particles) {
    particle.life -= dt;
    particle.vy += (particle.gravity ?? 720) * dt;
    particle.x += particle.vx * dt;
    particle.y += particle.vy * dt;
    particle.vx *= particle.drag ?? 0.985;
    if (Number.isFinite(particle.spin)) particle.rotation = (particle.rotation || 0) + particle.spin * dt;
    if (particle.kind === "arterial" && particle.y >= FLOOR - 2 && particle.vy > 0) {
      particle.life = 0;
      // 2.8: budgets live in engine/gore.mjs — floor + wall stains sum to the
      // historical 56 cap so a long spray cannot evict combat text and other
      // effects from the trimmed effect budget. Critic round (M2): at the cap
      // the OLDEST stain recycles, so a long bleed keeps painting the street.
      const stainLife = 3.4 + visualRandom() * 2.2;
      pushBloodDecal({
        stain: true, tier: "light",
        x: clamp(particle.x, 24, W - 24), y: FLOOR + 3,
        // 2.8: the stain's footprint follows the droplet that made it.
        width: 6 + particle.size * 4.4 + visualRandom() * 11,
        life: stainLife, max: stainLife, color: "#6b050c",
      }, (effect) => effect.stain && !effect.wall);
      for (let splash = 0; splash < 2; splash += 1) {
        state.particles.push({
          kind: "blood", x: particle.x, y: FLOOR - 3,
          vx: (visualRandom() - 0.5) * 130, vy: -40 - visualRandom() * 90,
          gravity: 900, drag: 0.98,
          life: 0.18 + visualRandom() * 0.2, max: 0.38,
          size: 1.4 + visualRandom() * 2, color: "#a50713",
        });
      }
    } else if (particle.kind === "arterial" && particle.life > 0
      && ((particle.x <= MOVEMENT_RULES.stageMinX - 14 && particle.vx < 0)
        || (particle.x >= MOVEMENT_RULES.stageMaxX + 14 && particle.vx > 0))) {
      // 2.8: droplets that reach an arena bound splatter on the wall and run,
      // instead of sailing through it. Wall budget shares the 56-stain cap.
      particle.life = 0;
      const stainLife = 3.8 + visualRandom() * 2.4;
      if (STAGE_WALL_SURFACES[state.stage] === false) {
        // 2.8 critic round (S3): open bound — nothing to catch the droplet,
        // so it carries past the line and lands as one more floor stain.
        pushBloodDecal({
          stain: true, tier: "light",
          x: clamp(particle.x, 24, W - 24), y: FLOOR + 3,
          width: 5 + particle.size * 3.6 + visualRandom() * 9,
          life: stainLife, max: stainLife, color: "#6b050c",
        }, (effect) => effect.stain && !effect.wall);
        continue;
      }
      const wall = particle.x <= MOVEMENT_RULES.stageMinX - 14 ? -1 : 1;
      pushBloodDecal({
        stain: true, wall,
        x: wall < 0 ? MOVEMENT_RULES.stageMinX - 16 : MOVEMENT_RULES.stageMaxX + 16,
        y: Math.min(particle.y, FLOOR - 12),
        width: 5 + particle.size * 3.2 + visualRandom() * 8,
        run: 10 + visualRandom() * 26,
        life: stainLife, max: stainLife, color: "#71060d",
      }, (effect) => Boolean(effect.wall));
      goreFxDebug.wallStains += 1;
    }
  }
  state.particles = state.particles.filter((particle) => particle.life > 0);
  // 2.8 critic round (M2): while a graphic fatality holds the frame, the
  // aftermath decals STOP AGEING OUT — floor/wall stains, smears and the
  // pool keep their paint until scene teardown (MK aftermath accumulates;
  // it never dissolves mid-hold while the wound still dribbles). The decal's
  // own age clock keeps running so soak/spread still evolve, and the normal
  // fade tail resumes the moment the finisher releases the scene.
  const goreHoldFreeze = Boolean(state.finisher?.fatalityTriggered) && state.graphicFatalities;
  for (const effect of state.effects) {
    if (effect.kind === "bloodDecal" || effect.kind === "fatalityPool") {
      effect.age = (effect.age || 0) + dt;
      if (!goreHoldFreeze) effect.life -= dt;
    } else {
      effect.life -= dt;
    }
    if (effect.kind === "fatalityProjectile") {
      const killCollapse = Boolean(state.finisher?.fatalityTriggered) && state.graphicFatalities;
      if (killCollapse) {
        // 2.8 critic round (M3): collapse the money-shot blocker — the sigil
        // shrinks toward the impact point over ~25 ticks, its spin dies, and
        // it eases down to rest on the floor beside the body.
        effect.killSettle = Math.min(1, (effect.killSettle || 0) + dt * 2.4);
        effect.focusScale = Math.max(0.3, (effect.focusScale || 1) - dt * 4.2);
      }
      effect.spinAngle += (effect.spin || 8) * dt * (1 - (effect.killSettle || 0) * 0.94);
      effect.width = effect.baseWidth * (effect.focusScale || 1);
      effect.height = effect.baseHeight * (effect.focusScale || 1);
      if (effect.landed) {
        if (killCollapse) {
          effect.x = lerp(effect.x, effect.targetX, Math.min(1, dt * 5.5));
          effect.y = lerp(effect.y, effect.targetY, Math.min(1, dt * 5.5));
        } else {
          effect.x = effect.targetX;
          effect.y = effect.targetY;
        }
      } else {
        effect.flightProgress = clamp((effect.flightProgress || 0) + dt / .3, 0, 1);
        const progress = effect.flightProgress;
        const eased = progress * progress * (3 - 2 * progress);
        effect.x = lerp(effect.startX, effect.targetX, eased);
        effect.y = lerp(effect.startY, effect.targetY, eased) - Math.sin(progress * Math.PI) * 62;
        effect.landed = progress >= 1;
        effect.hazard = effect.landed && ["wires", "bedbugs"].includes(effect.style);
      }
      continue;
    }
    if (effect.kind !== "severedLimb" || effect.resting) continue;
    effect.vy += (effect.gravity || 1080) * dt;
    effect.x += effect.vx * dt;
    effect.y += effect.vy * dt;
    effect.vx *= effect.drag || .988;
    effect.rotation += effect.spin * dt;
    const floorY = FLOOR - (effect.limb.endsWith("leg") ? 22 : 16);
    if (effect.y < floorY || effect.vy <= 0) continue;
    effect.y = floorY;
    if (!effect.bounced && effect.vy > 170) {
      effect.vy *= -.28;
      effect.vx *= .66;
      effect.spin *= .58;
      effect.bounced = true;
      // 2.8: the limb's landing skids blood across the floor — smear-class
      // streaks along the skid direction plus a short wet splash. Critic
      // round (S4): two wider streaks so the skid is actually locatable.
      if (state.graphicFatalities) {
        const skidDirection = Math.sign(effect.vx) || 1;
        for (let streak = 0; streak < 2; streak += 1) {
          const smearLife = 3.2 + visualRandom() * 2;
          pushBloodDecal({
            smear: true,
            x: clamp(effect.x + skidDirection * streak * 30, 30, W - 30), y: FLOOR + 3,
            width: 44 + visualRandom() * 40,
            direction: skidDirection,
            life: smearLife, max: smearLife, color: "#5c040b",
          }, (decal) => decal.smear);
          goreFxDebug.smears += 1;
        }
      }
      for (let splash = 0; splash < 4; splash += 1) {
        state.particles.push({
          kind: "blood", x: effect.x, y: floorY + 8,
          vx: (visualRandom() - 0.5) * 180 + effect.vx * 0.2,
          vy: -50 - visualRandom() * 110,
          gravity: 950, drag: 0.975,
          life: 0.2 + visualRandom() * 0.22, max: 0.42,
          size: 1.6 + visualRandom() * 2.2, color: "#8c0712",
        });
      }
    } else {
      effect.vy = 0;
      effect.vx = 0;
      effect.spin = 0;
      effect.resting = true;
    }
  }
  state.effects = state.effects.filter((effect) => effect.life > 0);
  state.particles = trimVisualBudget(state.particles, state.performance.particleBudget);
  state.effects = trimVisualBudget(state.effects, state.performance.effectBudget);
}

function simulateOfflineGameTick(dt) {
  // No hitstop short-circuit here: inputs must be read on every tick so
  // presses during the freeze reach the buffer. simulatePreparedGameTick owns
  // the freeze itself and stops everything but the input pipeline.
  const rngDrawsBefore = rngDrawSerial;
  const bothCpu = state.mode === "demo" || state.mode === "tournament";
  // R1.9: a running trial demo drives the player seat through the QA-style
  // scripted input path (training mode only; readQaInput still outranks it so
  // probes can interrupt a demo).
  let input0 = readQaInput(0)
    || trialDemoInput()
    || (bothCpu ? aiInput(state.fighters[0], state.fighters[1], dt) : readInput(0));
  const manualTrainingInput = state.mode === "training" && state.training.dummyMode === "record"
    ? readInput(1) : null;
  let trainingDummy = state.mode === "training"
    ? trainingDummyInput(state.training, state.simulationTick, {
      attackLevel: state.fighters[0]?.attacking?.level,
      attackConnected: state.fighters[0]?.attackConnected,
      comboHits: state.fighters[0]?.combo.snapshot(state.simulationTick).hits || 0,
      hitstunFrames: state.fighters[1]?.hitstunFrames || 0,
      blockstunFrames: state.fighters[1]?.blockstunFrames || 0,
      wakeupFrames: state.fighters[1]?.wakeupFrames || 0,
      down: Boolean(state.fighters[1]?.down),
      justWoke: Boolean(state.fighters[1]?.justWoke),
      manualInput: manualTrainingInput,
    })
    : null;
  if (trainingDummy?.trainingKnockdown && state.fighters[1]) {
    enterKnockdown(state.fighters[1]);
    trainingDummy = { ...trainingDummy, trainingKnockdown: false };
  }
  const cpuOpponent = state.mode === "arcade"
    || state.mode === "survival"
    || (state.mode === "team" && state.teamBattle?.cpu)
    || bothCpu
    // Wave 19: a bracket versus match with a CPU in the P2 seat.
    || (state.mode === "versus" && bracketSession.playing && bracketSession.matchCpu[1])
    || (state.mode === "training" && trainingDummy === null);
  let input1 = readQaInput(1)
    || (cpuOpponent
      ? aiInput(state.fighters[1], state.fighters[0], dt)
      : trainingDummy || readInput(1));
  // R2.1 STREETS: record the confirmed input pair entering the sim (resolved
  // sender-side to the action vocabulary exactly like the online encode path)
  // plus the count of gameplay rng draws the AI consumed above, so playback
  // can burn the identical draws. Pure observation — inputs pass through
  // untouched.
  if (replayRecorder.active && replayRecorder.kind === "offline") {
    recordOfflineReplayFrame(input0, input1, rngDrawSerial - rngDrawsBefore);
  }
  simulatePreparedGameTick(dt, input0, input1);
}

function maybeSendOnlineChecksum() {
  const rollback = onlineSession.rollback;
  if (!rollback || !onlineSession.peer?.connected) return;
  const metrics = rollback.metrics();
  const confirmed = Math.min(metrics.frame, metrics.confirmedRemoteFrame + 1, metrics.acknowledgedLocalFrame + 1);
  const checkpoint = Math.floor(confirmed / 60) * 60;
  if (checkpoint <= 0 || checkpoint <= onlineSession.lastChecksumSentFrame) return;
  const checksum = rollback.checksumAt(checkpoint);
  if (!checksum) return;
  onlineSession.lastChecksumSentFrame = checkpoint;
  sendOnlineControl({ type: "checksum", matchId: onlineSession.matchConfig?.matchId, frame: checkpoint, checksum });
}

// Raw four-button reads must be resolved to the action vocabulary BEFORE they
// are encoded: inputToBits only knows action fields, so encoding the raw
// object silently drops every attack button. Resolution happens sender-side
// against the local fighter's current state — that is what the dedicated
// limb/taunt wire bits exist for — and the sim's own resolve branch only runs
// for objects still carrying fourButton, so nothing resolves twice.
function resolveSideInput(side, raw) {
  if (!raw?.fourButton) return raw;
  const fighter = state.fighters[side];
  if (!fighter) return raw;
  return resolveFourButtonInput(raw, {
    facing: fighter.facing,
    style: activeControlStyle(side),
    meter: fighter.meter,
    finishing: state.phase === "finish" && state.finishWinner === side,
    finishArmed: state.finishArmed[side],
    tauntArmed: state.simulationTick <= fighter.tauntArmedUntilTick,
  });
}

function resolveOnlineLocalInput() {
  const raw = readQaInput(0) || readInput(0);
  return resolveSideInput(onlineLocalSide(), raw);
}

function simulateOnlineGameTick() {
  const rollback = onlineSession.rollback;
  if (!rollback || onlineSession.networkPaused) return;
  const localInput = resolveOnlineLocalInput();
  const result = rollback.advance(inputToBits(localInput));
  if (onlineSession.peer?.connected) onlineSession.peer.sendInput(rollback.inputPacket());
  if (!result.advanced) {
    updateOnlineHud("warning");
    return;
  }
  state.simulationTick = rollback.frame;
  maybeSendOnlineChecksum();
  checkPendingOnlineChecksums();
  const metrics = rollback.metrics();
  if (metrics.frame - onlineSession.lastPersistedFrame >= 60) {
    onlineSession.lastPersistedFrame = metrics.frame;
    persistOnlineResume(true);
  }
  // Wave 19: relay confirmed frames to any spectator seats (host only, low
  // cadence, chunked far inside the signaling rate/size caps).
  maybePumpSpectate(metrics);
  // R2.1 STREETS: connection-meter recent window (~2s). Depth reads the last
  // rollback's size while it is fresh; stalls are the delta over the window.
  connMeter.recentRollbackDepth = metrics.frame - metrics.lastRollbackFrame <= 120 ? metrics.lastRollbackFrames : 0;
  if (!connMeter.baseline || metrics.frame - connMeter.baseline.frame >= 120) {
    connMeter.recentStalled = connMeter.baseline ? Math.max(0, metrics.stalledFrames - connMeter.baseline.stalledFrames) : 0;
    connMeter.baseline = { frame: metrics.frame, stalledFrames: metrics.stalledFrames };
  }
  updateOnlineHud(metrics.frame - metrics.lastRollbackFrame < 30 ? "warning" : "sync");
}

function simulateGameTick(dt) {
  if (state.screen !== "fight" || !state.fighters.length) return;
  if (document.body.classList.contains("orientation-blocked")) return;
  if (state.paused) return;
  // R2.1 STREETS: replay playback owns the sim while active — the recorded
  // pairs are the only inputs, at the theater's own pause/speed cadence.
  if (replayPlayback.active) {
    simulateReplayTick();
    return;
  }
  if (state.mode === "online" && onlineSession.matchActive) simulateOnlineGameTick();
  else simulateOfflineGameTick(dt);
}

function drawCover(image, offsetX = 0) {
  if (!image.complete || !image.naturalWidth) {
    const gradient = ctx.createLinearGradient(0, 0, 0, H);
    gradient.addColorStop(0, "#0a1d35");
    gradient.addColorStop(1, "#100507");
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, W, H);
    return;
  }
  const scale = Math.max(W / image.naturalWidth, H / image.naturalHeight);
  const dw = image.naturalWidth * scale;
  const dh = image.naturalHeight * scale;
  ctx.drawImage(image, (W - dw) * 0.5 + offsetX, (H - dh) * 0.5, dw, dh);
}

function finisherRealityAmount() {
  const finisher = state.finisher;
  if (!finisher) return 0;
  const duration = state.accessibility.reducedMotion ? .16 : .42;
  const linear = clamp(finisher.elapsed / duration, 0, 1);
  return linear * linear * (3 - 2 * linear);
}

function drawRealityBreakAtmosphere(time, amount) {
  if (amount <= .01) return;
  ctx.save();
  ctx.globalAlpha = amount;
  ctx.globalCompositeOperation = "screen";
  const warm = ctx.createRadialGradient(W * .12, H * .32, 10, W * .12, H * .32, W * .55);
  warm.addColorStop(0, "rgba(255,164,78,.22)");
  warm.addColorStop(1, "rgba(255,110,48,0)");
  ctx.fillStyle = warm;
  ctx.fillRect(0, 0, W, H);
  const cold = ctx.createRadialGradient(W * .82, H * .26, 15, W * .82, H * .26, W * .56);
  cold.addColorStop(0, "rgba(104,194,255,.2)");
  cold.addColorStop(1, "rgba(70,120,255,0)");
  ctx.fillStyle = cold;
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = "source-over";
  const dustCount = state.performance.shadows ? 28 : 12;
  for (let mote = 0; mote < dustCount; mote += 1) {
    const clock = state.accessibility.reducedMotion ? mote * 19 : state.simulationTick + mote * 37;
    const x = ((mote * 181 + clock * (.18 + mote % 4 * .07)) % (W + 80)) - 40;
    const y = 80 + ((mote * 113 + clock * (.08 + mote % 3 * .04)) % Math.max(1, FLOOR - 120));
    const glow = .14 + (mote % 5) * .035;
    ctx.globalAlpha = amount * glow;
    ctx.fillStyle = mote % 3 ? "#d8c2a1" : "#9fc9dc";
    ctx.beginPath();
    ctx.arc(x, y, 1 + mote % 3 * .65, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  presentationDebug.realisticLighting += 1;
}

function drawStage(time) {
  const center = state.fighters.length ? (state.fighters[0].x + state.fighters[1].x) * 0.5 : W * 0.5;
  const parallax = (center - W * 0.5) * -0.035;
  const reality = finisherRealityAmount();
  drawCover(stageImages[state.stage], parallax);
  drawRackFocus(parallax);
  drawTimeOfDayHorizon();
  const shade = ctx.createLinearGradient(0, 0, 0, H);
  shade.addColorStop(0, "rgba(0,8,18,.12)");
  shade.addColorStop(0.58, "rgba(0,0,0,.03)");
  shade.addColorStop(1, "rgba(2,3,5,.74)");
  ctx.fillStyle = shade;
  ctx.fillRect(0, 0, W, H);

  drawCrowd(time);
  drawStageAmbient(state.simulationTick, center, state.crowdReaction);
  if (state.stage === "vet") drawVetAtmosphere(time);
  drawStageWeather(state.simulationTick, center);

  ctx.fillStyle = "rgba(6,8,11,.26)";
  ctx.fillRect(0, FLOOR, W, H - FLOOR);
  ctx.strokeStyle = state.stage === "vet" ? "rgba(255,177,50,.18)" : "rgba(70,190,240,.16)";
  ctx.lineWidth = 2;
  for (let x = -100; x < W + 200; x += 150) {
    ctx.beginPath();
    ctx.moveTo(x, FLOOR);
    ctx.lineTo(W * 0.5 + (x - W * 0.5) * 1.65, H);
    ctx.stroke();
  }
  drawStageScars();
  drawPracticalLights(time, state.simulationTick, center, state.crowdReaction);
  // Overlaying the plate after the normal arena dressing gives us a true
  // crossfade without an expensive full-canvas CSS filter. At 1.0 it cleanly
  // replaces every arcade layer beneath it.
  if (reality > .01 && finalBlowRealityImage.complete && finalBlowRealityImage.naturalWidth) {
    ctx.save();
    ctx.globalAlpha = reality;
    drawCover(finalBlowRealityImage, parallax * .18);
    ctx.restore();
    presentationDebug.realisticBackdrops += 1;
  }
  drawRealityBreakAtmosphere(time, reality);
  updateRoundWinBeatLatch();
  drawRoundWinBeat(state.simulationTick, center);
}

const POSTURE_BY_ID = Object.fromEntries(
  [...POSTURES, ...TAILGATE_POSTURES, ...BOARDWALK_POSTURES, ...BUFFET_POSTURES, ...POOLSIDE_POSTURES]
    .map((posture) => [posture.id, posture]),
);

function resetCrowd() {
  state.crowd = createCrowd(state.stage, { seed: hashSeed(state.matchSeed, state.round) });
  if (state.crowd.people.some((person) => person.sprite)) ensureCrowdMedia();
  resetCrowdReaction(state);
}

// Big moments ripple through the crowd, then it goes back to its routes.
// v5.0 AMBIENT REACTIONS: a presentation-side pulse the stage life reacts to
// (floodlights flare, moths scatter, the wok flares). Latched from the crowd
// stir and from the KO phase change; never sim state, never resimulated.
// The thresholds, the decay and the KO latch are engine/ambient.mjs (tested);
// this file keeps the resim guard and the tick.
const ambientObs = createAmbientObs();

function pulseAmbient(kind, amount) {
  if (rollbackResimulating) return;
  pulseAmbientLatch(ambientObs, kind, amount, state.simulationTick);
}

// v5.1 STAGE KO BEATS: the one read every stage layer shares. The KO latch
// (phase edge into finish/roundover) and the level at `frame`, then the
// crowd's KO hold folded in as the KO beat — whichever of the two is
// stronger drives the furniture (engine/ambient.mjs ambientSurge). The
// atmosphere passes run inside drawCrowd, before drawStageAmbient, so this is
// called more than once per frame; the phase latch is one-shot per edge and
// the hold latch idempotent, so the extra reads change nothing.
function readAmbientPulse(frame, reduced) {
  const koPulse = ambientPhaseChange(ambientObs, state.phase, state.screen);
  if (koPulse) pulseAmbient(koPulse.kind, koPulse.amount);
  const { pulseAge, pulse, ko } = ambientPulseLevel(ambientObs, frame, reduced);
  return { pulseAge, pulse, ko };
}

function stageKoBeat(reduced = state.accessibility.reducedMotion) {
  updateCrowdKoHoldLatch();
  return ambientKoBeat(crowdKoHoldAge(), reduced);
}

function stageSurge(frame, reduced = state.accessibility.reducedMotion) {
  const level = readAmbientPulse(frame, reduced);
  // pulseAge rides along raw: the synced cycles (splashes, steam, pigeons)
  // run 60 ticks, longer than the 48-tick level, so they key off the latch
  // age rather than the surge's age (which reads -1 once the level is gone).
  return { ...ambientSurge(level, stageKoBeat(reduced)), pulseAge: level.pulseAge };
}

// A soft-edged horizontal band of light (the pass-through window, the pool
// surface, a street-level flash): fades in and out vertically so it reads as
// a lit plane in the plate, not a painted rectangle.
function ambientBand(x, y, width, height, rgb, alpha) {
  if (alpha <= 0.002) return;
  const gradient = ctx.createLinearGradient(0, y, 0, y + height);
  gradient.addColorStop(0, `rgba(${rgb},0)`);
  gradient.addColorStop(0.35, `rgba(${rgb},${alpha})`);
  gradient.addColorStop(0.65, `rgba(${rgb},${alpha})`);
  gradient.addColorStop(1, `rgba(${rgb},0)`);
  ctx.fillStyle = gradient;
  ctx.fillRect(x, y, width, height);
}

// v5.3 CROWD DEPTH: `side` is who landed it (0/1, or -1 for an authorless
// stir — a taunt, a stage beat — which keeps the pre-5.3 read where everyone
// past threshold cheers). `splatX` marks a wall splat / near-KO blow the
// people standing near it flinch away from, whoever they are here for.
function stirCrowd(amount = 1, kind = "", { side = -1, splatX = null } = {}) {
  // v5.3 (sweep #52): the state machine — the 1.4 ceiling, the author, the
  // splat mark, the 0.7 ambient threshold and the 0.5 swell threshold — is
  // engine/crowd-reaction.mjs. It returns what still needs a side effect.
  const { pulseKind, swell } = stirCrowdReaction(state, amount, { side, splatX, tick: state.simulationTick });
  if (pulseKind) pulseAmbient(pulseKind, amount);
  // Release 1.6 LOUD: big stirs also latch a one-shot crowd swell/gasp for
  // the render-side crowd bus (guarded + tick-deduped inside the latch).
  // v5.1: the kind rides along so a "ko" stir gets the KO swell and roar.
  if (swell) latchCrowdSwell(amount, kind);
}

// v4.7 BYSTANDERS: painted crowd sheets (assets/crowd/, built by
// tools/build_crowd_sheets.py). Lazy like the element media — never in the
// install shell — and the vector figure below keeps drawing until they land.
const crowdSheets = { manifest: null, images: new Map(), requested: false };

function ensureCrowdMedia() {
  if (crowdSheets.requested) return;
  crowdSheets.requested = true;
  // v5.1: the voiced crowd warms with the painted one (twelve small takes,
  // 18-49 KB each) so the first KO of the session does not miss its roar.
  ensureCrowdVoiceMedia();
  fetch("assets/crowd/MANIFEST.json")
    .then((response) => (response.ok ? response.json() : null))
    .then((manifest) => {
      if (!manifest?.variants) return;
      crowdSheets.manifest = manifest;
      for (const entry of Object.values(manifest.variants)) {
        for (const name of entry.sheets || []) {
          if (crowdSheets.images.has(name)) continue;
          const image = new Image();
          image.src = `assets/crowd/${name}`;
          crowdSheets.images.set(name, image);
        }
      }
    })
    .catch(() => {});
}

// v5.3 CROWD DEPTH: the sheet family a variant paints from. Most variants own
// theirs; a BORROWING variant (Somerset) gets a view onto a subset of another
// bank's characters, so `person.sprite.character` still indexes 0..n-1 the way
// the seeded deal produced it and nothing downstream knows the difference.
const crowdVariantViews = new Map();

function crowdVariantEntry(variantId = state.crowd?.variant) {
  const manifest = crowdSheets.manifest;
  if (!manifest || !variantId) return null;
  const direct = manifest.variants?.[variantId];
  if (direct) return direct;
  const loan = CROWD_SPRITE_BORROW[variantId];
  const source = loan && manifest.variants?.[crowdSheetVariant(variantId)];
  if (!source) return null;
  let view = crowdVariantViews.get(variantId);
  if (!view || view.source !== source) {
    view = {
      source,
      sheets: source.sheets,
      characters: loan.characters.map((index) => source.characters[index]),
    };
    crowdVariantViews.set(variantId, view);
  }
  return view;
}

// A borrowed bank is lit for the stage it was painted for, so the borrower
// re-grades it once per sheet into a cached canvas rather than per draw. The
// tailgate people were shot under lot floodlights; Somerset is sodium lamps
// under the El, so `night` multiplies them cool and drops them ~26%.
const CROWD_GRADES = Object.freeze({
  night: Object.freeze({ multiply: "#8095b8", wash: "rgba(38,66,112,.22)" }),
});
const crowdGradedSheets = new Map();

function crowdGradedSheet(name, grade) {
  const image = crowdSheets.images.get(name);
  if (!image?.complete || !image.naturalWidth) return null;
  const recipe = CROWD_GRADES[grade];
  if (!recipe) return image;
  const key = `${name}|${grade}`;
  const cached = crowdGradedSheets.get(key);
  if (cached && cached.width === image.naturalWidth) return cached;
  const canvas = document.createElement("canvas");
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const paint = canvas.getContext("2d");
  paint.drawImage(image, 0, 0);
  paint.globalCompositeOperation = "multiply";
  paint.fillStyle = recipe.multiply;
  paint.fillRect(0, 0, canvas.width, canvas.height);
  paint.globalCompositeOperation = "source-atop";
  paint.fillStyle = recipe.wash;
  paint.fillRect(0, 0, canvas.width, canvas.height);
  // multiply/source-atop both leave the keyed transparency alone, but the
  // multiply pass paints the whole rect, so the alpha is re-cut from the
  // original sheet.
  paint.globalCompositeOperation = "destination-in";
  paint.drawImage(image, 0, 0);
  crowdGradedSheets.set(key, canvas);
  return canvas;
}

function crowdSpriteCharacter(person) {
  const variant = crowdVariantEntry();
  const character = variant?.characters?.[person.sprite?.character];
  if (!character) return null;
  const image = crowdGradedSheet(variant.sheets[character.sheet], state.crowd?.grade || "");
  if (!image) return null;
  return { character, image, sheet: variant.sheets[character.sheet] };
}

// A painted bystander stands where the vector figure would: feet on the
// person's y, mirrored by direction, the same contact shadow, layer alpha and
// fatality-hold dim. Columns: stand / weight-shift / cheer / stride. Walkers
// alternate stride and stand on the gait clock (the classic two-frame crowd
// step); idlers shift their weight on a personal timer; a stirred crowd
// throws its arms up person by person past each one's own threshold.
// Which painted cell a person wears this tick, and their walk bob — shared by
// the 2D draw and the CINEMA 3D billboards so both renderers agree.
// v5.3 CROWD DEPTH: the same tick now resolves to THREE different reads.
// `x` is where the person is standing this tick (sim space, pre-parallax), so
// the flinch can measure the distance to a wall splat and both the wince and
// the flinch can lean AWAY from what happened rather than all one way.
function crowdSpriteFrame(person, gait, paused, reaction, x = person.originX) {
  const reducedMotion = state.accessibility.reducedMotion;
  const frame = state.simulationTick;
  // v5.1 KO MOMENT: through the hold a person past their threshold pumps
  // between the cheer and weight-shift cells on their own shift timer and
  // bounces on the spot, so a crowd that is up for five seconds never freezes.
  const holdColumn = crowdKoHoldAge() >= 0 && !reducedMotion ? crowdKoHoldColumn(person.sprite, frame, reaction) : -1;
  const flinch = crowdFlinchLevel(x, state.crowdSplatX, frame - state.crowdSplatTick);
  // Away from the splat while one is fresh; otherwise away from the fight.
  const awayFrom = flinch > 0 ? state.crowdSplatX : crowdFightCentre();
  const mood = crowdMemberMood(person.sprite, {
    reaction,
    stirSide: state.crowdStirSide,
    holdColumn,
    flinch,
    awaySign: x >= awayFrom ? 1 : -1,
    reducedMotion,
  });
  let column = mood.column;
  if (column < 0) {
    if (!paused && !reducedMotion) column = Math.sin(gait) > 0 ? 3 : 0;
    else if (!reducedMotion && ((frame + person.sprite.shiftOffset) % person.sprite.shiftPeriod) < person.sprite.shiftLength) column = 1;
    else column = 0;
  }
  const posture = POSTURE_BY_ID[person.posture] || POSTURES[0];
  let bob = paused || reducedMotion ? 0 : Math.abs(Math.sin(gait)) * posture.bob * 2.4;
  if (mood.mood === "cheer" && holdColumn === 2) bob = Math.abs(Math.sin(frame * 0.19 + person.sprite.shiftOffset)) * CROWD_KO_HOLD.bobPx;
  return { column, bob: bob - mood.duck, tilt: mood.tilt, mood: mood.mood };
}

function crowdFightCentre() {
  return state.fighters.length ? (state.fighters[0].x + state.fighters[1].x) * 0.5 : W * 0.5;
}

function drawCrowdSprite(person, layer, x, gait, paused, reaction, simX = x) {
  if (!person.sprite) return false;
  const resolved = crowdSpriteCharacter(person);
  if (!resolved) return false;
  const { character, image } = resolved;
  const { column, bob, tilt } = crowdSpriteFrame(person, gait, paused, reaction, simX);
  const cell = character.cells[column] || character.cells[0];
  const scale = layer.scale * person.height;
  // The vector figure stands ~134px tall at scale 1; match it so the crowd's
  // depth bands and the 25/35-visible framing tests keep their meaning.
  const drawScale = (134 * scale) / Math.max(1, cell.h);
  const holdDim = 1 - fatalitySpotLevel * 0.62;
  ctx.save();
  ctx.globalAlpha = layer.alpha * 0.45 * holdDim;
  ctx.fillStyle = "rgba(0,0,0,.8)";
  ctx.beginPath();
  ctx.ellipse(x, person.y + 2, 20 * layer.scale * person.width, 5 * layer.scale, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.save();
  ctx.translate(x, person.y - bob);
  // v5.3 CROWD DEPTH: the wince/flinch lean, about the feet. Applied BEFORE
  // the mirror so a left-facing person leans the same screen direction as a
  // right-facing one standing beside them.
  if (tilt) ctx.rotate(tilt);
  ctx.scale(person.direction, 1);
  ctx.globalAlpha = layer.alpha * holdDim;
  ctx.drawImage(image, cell.x, cell.y, cell.w, cell.h,
    -(cell.cx - cell.x) * drawScale, -(cell.baseline - cell.y) * drawScale,
    cell.w * drawScale, cell.h * drawScale);
  ctx.restore();
  return true;
}

function drawPedestrian(person, layer, x, gait, paused, reaction, simX = x) {
  if (drawCrowdSprite(person, layer, x, gait, paused, reaction, simX)) return;
  // v5.3 CROWD DEPTH: a painted-only crowd never falls back to the vector
  // figure — see crowd.mjs `paintedOnly`.
  if (state.crowd?.paintedOnly) return;
  const posture = POSTURE_BY_ID[person.posture] || POSTURES[0];
  const scale = layer.scale * person.height;
  const step = paused ? 0 : Math.sin(gait) * posture.stride;
  const bob = paused ? 0 : Math.abs(Math.sin(gait)) * posture.bob * 2.4;
  // A big moment makes them flinch and hunch briefly, without leaving their route.
  const flinch = reaction * (0.25 + person.pace * 0.2);
  const lean = posture.lean + flinch * 0.3;

  // Contact shadow so the pedestrian sits on the pavement rather than floating.
  // 2.8 critic round (J1): background pedestrians drop further back during
  // the fatality hold — at full spotlight they read as pale ghosts hovering
  // behind the kill, so the hold fades them toward the dark.
  const holdDim = 1 - fatalitySpotLevel * 0.62;
  ctx.save();
  ctx.globalAlpha = layer.alpha * 0.45 * holdDim;
  ctx.fillStyle = "rgba(0,0,0,.8)";
  ctx.beginPath();
  ctx.ellipse(x, person.y + 2, 20 * layer.scale * person.width, 5 * layer.scale, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(x, person.y - bob);
  ctx.scale(scale * person.direction, scale);
  ctx.globalAlpha = layer.alpha * holdDim;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // Roughly seven-heads tall, with the legs taking a little under half the body.
  const headY = -124;
  const shoulderY = -100;
  const hipY = -56;

  // Legs. A permanent stance offset keeps the two legs separate even when the
  // stride is near zero, otherwise a standing figure collapses into one post.
  ctx.strokeStyle = person.trousers;
  ctx.lineWidth = 10 * person.width;
  ctx.beginPath();
  ctx.moveTo(-4, hipY);
  ctx.lineTo(step * 20 - 8, 0);
  ctx.moveTo(4, hipY);
  ctx.lineTo(-step * 20 + 9, 0);
  ctx.stroke();

  ctx.save();
  // Everything above the hips leans forward by posture.
  ctx.translate(0, hipY);
  ctx.rotate(lean * 0.45);
  ctx.translate(0, -hipY);

  // Torso: a tapered coat rather than a single fat stroke, so it reads as a body.
  const shoulderHalf = 12 * person.width;
  const hipHalf = 8.5 * person.width;
  ctx.fillStyle = person.coat;
  ctx.beginPath();
  ctx.moveTo(-shoulderHalf, shoulderY + person.shoulderSlope * 5);
  ctx.lineTo(shoulderHalf, shoulderY - person.shoulderSlope * 5);
  ctx.lineTo(hipHalf, hipY + 4);
  ctx.lineTo(-hipHalf, hipY + 4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(8,11,16,.55)";
  ctx.lineWidth = 2.2;
  ctx.stroke();

  // Arms swing out of phase with the legs.
  const swing = paused ? 0 : Math.sin(gait + Math.PI) * posture.armSwing;
  // Arms hang clear of the torso silhouette so the figure reads as a person.
  ctx.strokeStyle = person.coat;
  ctx.lineWidth = 6.5 * person.width;
  ctx.beginPath();
  ctx.moveTo(shoulderHalf - 2, shoulderY + 5);
  ctx.lineTo(swing * 14 + shoulderHalf + 4, hipY + 12);
  ctx.moveTo(-shoulderHalf + 2, shoulderY + 5);
  ctx.lineTo(-swing * 14 - shoulderHalf - 3, hipY + 14);
  ctx.stroke();

  if (person.hasBag && layer.detail !== "low") {
    ctx.fillStyle = person.accent;
    ctx.fillRect(person.bagSide * 13 - 5, hipY + 2, 11, 15);
  }

  // Tailgate props ride in the raised hand: cups, cans, flags and handmade signs.
  if (person.prop && layer.detail !== "low") {
    const handX = swing * 14 + shoulderHalf + 4;
    const handY = hipY + 12;
    ctx.save();
    ctx.translate(handX, handY);
    if (person.prop === "cup") {
      ctx.fillStyle = "#d8dde2";
      ctx.beginPath();
      ctx.moveTo(-4, -9); ctx.lineTo(4, -9); ctx.lineTo(3, 2); ctx.lineTo(-3, 2);
      ctx.closePath(); ctx.fill();
    } else if (person.prop === "can") {
      ctx.fillStyle = "#a6adb4";
      ctx.fillRect(-3.5, -10, 7, 11);
      ctx.fillStyle = person.accent;
      ctx.fillRect(-3.5, -6, 7, 3);
    } else if (person.prop === "flag") {
      ctx.strokeStyle = "#8d949b";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(0, 4); ctx.lineTo(0, -34); ctx.stroke();
      ctx.fillStyle = person.accent;
      ctx.beginPath();
      ctx.moveTo(1, -34); ctx.lineTo(22, -28); ctx.lineTo(1, -20);
      ctx.closePath(); ctx.fill();
    } else if (person.prop === "plate") {
      ctx.fillStyle = "#eceff2";
      ctx.beginPath();
      ctx.ellipse(0, -3, 10, 3.6, 0, 0, Math.PI * 2);
      ctx.fill();
      // A heap of crab legs piled well past the rim.
      ctx.fillStyle = "#e2743a";
      for (let leg = 0; leg < 4; leg += 1) {
        ctx.save();
        ctx.translate((leg - 1.5) * 4, -6);
        ctx.rotate((leg - 1.5) * 0.4);
        ctx.fillRect(-1.4, -8, 2.8, 9);
        ctx.restore();
      }
    } else if (person.prop === "bigcup") {
      // An absurd souvenir cup, straw and all.
      ctx.fillStyle = person.accent;
      ctx.beginPath();
      ctx.moveTo(-7, -20); ctx.lineTo(7, -20); ctx.lineTo(5, 3); ctx.lineTo(-5, 3);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = "#ff5aa8";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(3, -20); ctx.lineTo(9, -32); ctx.stroke();
    } else if (person.prop === "phone") {
      ctx.fillStyle = "#1c2026";
      ctx.fillRect(-3, -20, 7, 12);
      ctx.fillStyle = "#7fe9ff";
      ctx.fillRect(-2, -19, 5, 10);
    } else if (person.prop === "bag") {
      ctx.fillStyle = person.accent;
      ctx.fillRect(-8, -6, 18, 20);
      ctx.strokeStyle = "#2b3138";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(1, -6, 7, Math.PI, 0); ctx.stroke();
    } else if (person.prop === "towel") {
      ctx.fillStyle = person.accent;
      ctx.fillRect(-4, -14, 16, 22);
    } else if (person.prop === "tongs") {
      ctx.strokeStyle = "#d5dce8";
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(-2, 2); ctx.lineTo(12, -6);
      ctx.moveTo(-2, 6); ctx.lineTo(12, -1);
      ctx.stroke();
    } else if (person.prop === "sign") {
      ctx.fillStyle = "#e6e9ec";
      ctx.fillRect(-2, -34, 26, 18);
      ctx.strokeStyle = "#1c4f42";
      ctx.lineWidth = 2;
      ctx.strokeRect(-2, -34, 26, 18);
      // Hand-scrawled marks, never real text or a logo.
      ctx.beginPath();
      ctx.moveTo(2, -28); ctx.lineTo(20, -28);
      ctx.moveTo(2, -23); ctx.lineTo(14, -23);
      ctx.stroke();
      ctx.strokeStyle = "#8d949b";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(11, -16); ctx.lineTo(11, 2); ctx.stroke();
    }
    ctx.restore();
  }

  // Neck and head, dropped forward for the hunched postures.
  ctx.strokeStyle = "#7d6c5e";
  ctx.lineWidth = 5 * person.width;
  ctx.beginPath();
  ctx.moveTo(0, shoulderY + 3);
  ctx.lineTo(2, headY + 12);
  ctx.stroke();

  ctx.save();
  ctx.translate(2, headY + 6);
  ctx.rotate(person.headTilt + posture.headDrop * 0.9);
  ctx.fillStyle = "#8d7a69";
  ctx.beginPath();
  ctx.ellipse(0, 0, 8 * person.width, 9.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "rgba(8,11,16,.5)";
  ctx.lineWidth = 1.8;
  ctx.stroke();
  if (person.facePaint && layer.detail === "high") {
    ctx.fillStyle = "#1c4f42";
    ctx.fillRect(-8 * person.width, -3, 16 * person.width, 3.5);
  }
  if (person.hasHood) {
    ctx.fillStyle = person.coat;
    ctx.beginPath();
    ctx.ellipse(-2, -2, 11 * person.width, 11.5, 0, Math.PI * 0.82, Math.PI * 2.1);
    ctx.fill();
  } else if (person.hasHat) {
    ctx.fillStyle = person.accent;
    ctx.fillRect(-11 * person.width, -12, 22 * person.width, 4.5);
    ctx.fillRect(-7 * person.width, -17, 14 * person.width, 6);
  }
  ctx.restore();
  ctx.restore();
  ctx.restore();
}

// One rowdy background scuffle. Readable and physical, never graphic: shoving,
// shirt-grabbing, wild misses, wrestling, friends pulling people apart.
// The choreography of one scuffle / pool-incident loop on a frame: where each
// member stands in group space, how they lean and reach, and which painted
// cell they wear. Shared by drawScuffle and the CINEMA 3D billboards.
function scuffleMembers(group, frame, reaction, celebrate = false) {
  const phase = scufflePhase(group, frame);
  const beat = Math.sin(phase * Math.PI * 2);
  const clash = Math.max(0, Math.sin(phase * Math.PI * 2 - 0.6));
  const swing = group.reach * (0.4 + clash * 0.6) * (1 + reaction * 0.25);
  const members = [];
  const add = (offsetX, lean, armReach, tilt = 0) => members.push({ offsetX, lean, armReach, tilt });
  // v5.1 KO MOMENT: through the hold every group drops its quarrel for the
  // celebrate choreography (the pool incidents already run it — they have no
  // case of their own — so this only turns the tailgate's fights into a cheer).
  const kind = celebrate ? "celebrate" : group.kind;
  switch (kind) {
    case "argue":
      add(-16, 0.2 + beat * 0.06, swing * 0.7);
      add(18, -0.2 - beat * 0.06, -swing * 0.7, 0.04);
      break;
    case "shove":
      add(-18 - clash * 8, 0.26, swing);
      add(20 + clash * 12, -0.3, -swing * 0.4, -clash * 0.16);
      break;
    case "shirtgrab":
      add(-13, 0.3, swing * 0.55);
      add(14, -0.32, -swing * 0.55, beat * 0.08);
      break;
    case "swing":
      add(-20, 0.16 + clash * 0.2, swing * 1.3);
      add(24, -0.34, -swing * 0.3, -clash * 0.22);
      break;
    case "wrestle":
      add(-10, 0.44, swing * 0.4, beat * 0.1);
      add(11, -0.46, -swing * 0.4, -beat * 0.1);
      break;
    case "separate":
      add(-26, 0.3, swing);
      add(26, -0.3, -swing);
      // The friend in the middle, arms out, holding them apart.
      add(0, -0.05, swing * 0.9, 0);
      break;
    case "tableflip":
      add(-24, 0.34, swing);
      add(26, -0.24, -swing * 0.5, clash * 0.2);
      break;
    default:
      // celebrate
      add(-22, -0.1, -swing * 1.2);
      add(0, -0.06, swing * 1.2);
      add(23, -0.12, -swing);
  }
  members.forEach((member, index) => {
    const reaching = Math.abs(member.armReach) > group.reach * 0.55;
    const armsUp = kind === "celebrate" || (kind === "separate" && index === 2) || (clash > 0.5 && kind !== "wrestle");
    member.column = armsUp ? (reaching ? 3 : 2) : reaching ? 3 : 0;
    member.character = group.characters ? group.characters[index % group.characters.length] : null;
  });
  return { phase, beat, clash, swing, members };
}

function drawScuffle(group, frame, centre, reaction) {
  const { phase, clash, members } = scuffleMembers(group, frame, reaction, crowdKoHoldAge() >= 0);
  // v5.3: a plate-anchored crowd rides the plate's own parallax factor.
  const drawX = group.x + (centre - W * 0.5) * -(state.crowd?.parallax || 0.2);
  if (drawX < -110 || drawX > W + 110) return;

  ctx.save();
  ctx.translate(drawX, group.y);
  ctx.scale(group.scale * group.flip, group.scale);
  ctx.globalAlpha = 0.82;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // v4.7 BYSTANDERS: with the painted bank in, each member is one of the
  // stage's painted characters — lunging on the stride cell while reaching,
  // standing between beats, arms up for the peacemaker and the celebrants —
  // facing the way the arm reaches, leaning about the feet. The vector
  // brawler stays as the fallback until the sheets land.
  const brawler = (member, shirt) => {
    const { offsetX, lean, armReach, tilt } = member;
    const resolved = member.character !== null && crowdSheets.manifest ? crowdSpriteCharacter({ sprite: { character: member.character } }) : null;
    if (resolved) {
      const cell = resolved.character.cells[member.column] || resolved.character.cells[0];
      const drawScale = 112 / Math.max(1, cell.h);
      ctx.save();
      ctx.translate(offsetX, 0);
      ctx.rotate(tilt + lean * 0.35);
      ctx.scale(armReach < 0 ? -1 : 1, 1);
      ctx.drawImage(resolved.image, cell.x, cell.y, cell.w, cell.h,
        -(cell.cx - cell.x) * drawScale, -(cell.baseline - cell.y) * drawScale, cell.w * drawScale, cell.h * drawScale);
      ctx.restore();
      return;
    }
    if (state.crowd?.paintedOnly) return;
    ctx.save();
    ctx.translate(offsetX, 0);
    ctx.rotate(tilt);
    ctx.strokeStyle = "#232a30";
    ctx.lineWidth = 9;
    ctx.beginPath();
    ctx.moveTo(-3, -46); ctx.lineTo(-9, 0);
    ctx.moveTo(3, -46); ctx.lineTo(10, 0);
    ctx.stroke();
    ctx.save();
    ctx.translate(0, -46);
    ctx.rotate(lean);
    ctx.translate(0, 46);
    ctx.fillStyle = shirt;
    ctx.beginPath();
    ctx.moveTo(-11, -88); ctx.lineTo(11, -88); ctx.lineTo(8, -44); ctx.lineTo(-8, -44);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = "rgba(8,11,16,.5)";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.strokeStyle = shirt;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(9, -84); ctx.lineTo(armReach, -66);
    ctx.moveTo(-9, -84); ctx.lineTo(-armReach * 0.4, -52);
    ctx.stroke();
    ctx.fillStyle = "#8d7a69";
    ctx.beginPath();
    ctx.ellipse(2, -100, 8, 9.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    ctx.restore();
  };

  members.forEach((member, index) => brawler(member, group.shirts[index % group.shirts.length]));
  if (group.kind === "tableflip") {
    const lift = clash * 26;
    ctx.save();
    ctx.translate(2, -22 - lift);
    ctx.rotate(clash * 0.5);
    ctx.fillStyle = "#6b7078";
    ctx.fillRect(-30, -6, 60, 7);
    ctx.strokeStyle = "#4e545b";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(-22, 1); ctx.lineTo(-26, 20);
    ctx.moveTo(22, 1); ctx.lineTo(26, 20);
    ctx.stroke();
    ctx.restore();
  }
  // A puff of dust at the peak of the clash so the scuffle reads as a fight
  // rather than two people standing close together.
  if (clash > 0.72) {
    // v5.3: a graded crowd gets its dust graded too. The tailgate's cream
    // puff is lot-floodlight dust; the same four circles on Somerset's dark
    // wet street read as bright bokeh balls, so night halves and cools them.
    const night = state.crowd?.grade === "night";
    ctx.globalAlpha = (clash - 0.72) * (night ? 1.0 : 2.2);
    ctx.fillStyle = night ? "rgba(150,162,180,.34)" : "rgba(214,206,190,.55)";
    for (let index = 0; index < 4; index += 1) {
      const puffX = (index - 1.5) * 13;
      const puffY = -18 - Math.abs(Math.sin(phase * 9 + index)) * 12;
      ctx.beginPath();
      ctx.arc(puffX, puffY, 5 + index, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

// v4.8 CINEMA 3D CROWD: the painted crowd resolved for this tick as billboard
// specs — sim-space feet position, cell, facing, alpha — so the 3D world draws
// exactly the people, poses and reactions the 2D canvas draws.
function crowdBillboards() {
  const crowd = state.crowd;
  const out = [];
  const variant = crowdVariantEntry(crowd?.variant);
  if (!crowd || !variant || state.screen !== "fight") return out;
  // v5.3 CROWD DEPTH: the grade the borrowing stage draws its loaned bank
  // under, and the step a stationed person is standing on, both ride the spec
  // so the 3D layer needs no stage table of its own.
  const grade = crowd.grade || "";
  const frame = state.simulationTick;
  // v5.1 KO MOMENT: the 3D crowd reads the same held reaction as the canvas,
  // so the arms-up cells, the pumps and the celebrate scuffles carry over.
  updateCrowdKoHoldLatch();
  const reaction = crowdDrawReaction();
  const celebrate = crowdKoHoldAge() >= 0;
  const holdDim = 1 - fatalitySpotLevel * 0.62;
  crowd.people.forEach((person, index) => {
    if (!person.sprite) return;
    const layer = CROWD_LAYERS.find((entry) => entry.id === person.layer);
    const { x, gait, paused } = crowdPosition(person, layer, frame, crowd.span, crowd.minX);
    if (x < -70 || x > W + 70) return;
    const character = variant.characters[person.sprite.character];
    if (!character) return;
    const { column, bob, tilt, mood } = crowdSpriteFrame(person, gait, paused, reaction, x);
    out.push({
      key: `p${index}`, x, y: person.y - bob, layer: layer.id, height: person.height,
      direction: person.direction, alpha: layer.alpha * holdDim, tilt, mood, grade,
      lift: person.lift || 0,
      sheet: variant.sheets[character.sheet], cell: character.cells[column] || character.cells[0],
    });
  });
  (crowd.scuffles || []).forEach((group, groupIndex) => {
    const { members } = scuffleMembers(group, frame, reaction, celebrate);
    members.forEach((member, index) => {
      const character = member.character === null ? null : variant.characters[member.character];
      if (!character) return;
      out.push({
        key: `s${groupIndex}-${index}`, x: group.x + member.offsetX * group.scale * group.flip, y: group.y,
        layer: "scuffle", height: group.scale * 0.84, direction: (member.armReach < 0 ? -1 : 1) * group.flip,
        alpha: 0.82 * holdDim, tilt: (member.tilt + member.lean * 0.35) * group.flip,
        mood: "scuffle", grade, lift: 0,
        sheet: variant.sheets[character.sheet], cell: character.cells[member.column] || character.cells[0],
      });
    });
  });
  return out;
}

// Six tapped steel kegs plus tables, coolers and grills. The split placement
// keeps the fight lane clear while making the Eagles tailgate unmistakable.
function drawTailgateProps(frame, centre) {
  const spots = [90, 215, 360, 920, 1065, 1190];
  for (let index = 0; index < spots.length; index += 1) {
    const x = spots[index] + (centre - W * 0.5) * -0.14;
    if (x < -80 || x > W + 80) continue;
    const y = 498 + (index % 3) * 8;
    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.translate(x, y);

    // The keg body remains readable against both the plate and animated fans.
    const steel = ctx.createLinearGradient(-18, 0, 18, 0);
    steel.addColorStop(0, "#59636a");
    steel.addColorStop(0.22, "#d9e0e3");
    steel.addColorStop(0.55, "#87939a");
    steel.addColorStop(0.78, "#edf1f2");
    steel.addColorStop(1, "#4c555c");
    ctx.fillStyle = steel;
    ctx.beginPath();
    ctx.ellipse(0, -31, 18, 6, 0, Math.PI, 0);
    ctx.lineTo(18, -3);
    ctx.ellipse(0, -3, 18, 6, 0, 0, Math.PI);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(24,31,35,.75)";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(0, -31, 18, 6, 0, 0, Math.PI * 2);
    ctx.ellipse(0, -17, 18, 5, 0, 0, Math.PI * 2);
    ctx.ellipse(0, -3, 18, 6, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Pump, tap and a small green cup make the interaction legible.
    ctx.strokeStyle = "#cbd3d7";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, -36); ctx.lineTo(0, -52); ctx.lineTo(9, -52);
    ctx.stroke();
    ctx.fillStyle = "#10171a";
    ctx.fillRect(-3, -57, 6, 9);
    ctx.fillStyle = "#1c6a56";
    ctx.fillRect(11, -14, 9, 12);

    if (index === 1 || index === 4) {
      // Folding table with green cups beside the keg.
      ctx.fillStyle = "#4a5057";
      ctx.fillRect(-46, -25, 27, 5);
      ctx.strokeStyle = "#3a4046";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(-42, -20); ctx.lineTo(-44, 2);
      ctx.moveTo(-24, -20); ctx.lineTo(-22, 2);
      ctx.stroke();
      ctx.fillStyle = "#1f765f";
      ctx.fillRect(-41, -34, 7, 9);
      ctx.fillRect(-31, -32, 7, 7);
    }

    if (index === 2 || index === 3) {
      // Grill smoke behind the two innermost keg stations.
      ctx.fillStyle = "#4a5057";
      ctx.fillRect(25, -27, 28, 6);
      const smoke = 12 + Math.sin(frame * 0.03 + index) * 5;
      const gradient = ctx.createRadialGradient(39, -44, 2, 39, -44, smoke * 2.4);
      gradient.addColorStop(0, "rgba(214,222,228,.2)");
      gradient.addColorStop(1, "rgba(214,222,228,0)");
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(39, -44, smoke * 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
  ctx.globalAlpha = 1;
}

// Gulls, a moving ride car and neon haze over the boardwalk.
// v4.7 AMBIENT: per-stage background life on top of the plates. Everything
// here is a pure function of the simulation tick (replay/rollback-exact) and
// pinned to plate landmarks measured in canvas space; sky elements ride a
// small negative parallax like the gulls. Frozen under reduced motion, skipped
// on the battery profile like the weather field.
function ambientGlow(x, y, radius, rgb, alpha) {
  if (alpha <= 0.002) return;
  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, `rgba(${rgb},${alpha})`);
  gradient.addColorStop(1, `rgba(${rgb},0)`);
  ctx.fillStyle = gradient;
  ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
}

function ambientGull(x, y, flap, size, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = "rgba(236,240,246,.9)";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x - size, y + flap * 0.5);
  ctx.quadraticCurveTo(x - size * 0.5, y - flap, x, y);
  ctx.quadraticCurveTo(x + size * 0.5, y - flap, x + size, y + flap * 0.5);
  ctx.stroke();
  ctx.restore();
}

function ambientFirework(frame, period, salt, minX, maxX, minY, maxY) {
  const cycle = Math.floor(frame / period);
  const age = frame % period;
  if (age > 84) return;
  const x = minX + presentationHash01(cycle, salt, 1) * (maxX - minX);
  const y = minY + presentationHash01(cycle, salt, 2) * (maxY - minY);
  const hue = Math.floor(presentationHash01(cycle, salt, 3) * 360);
  const fade = 1 - age / 84;
  ctx.save();
  ctx.globalAlpha = fade * 0.85;
  ctx.fillStyle = `hsl(${hue} 90% 70%)`;
  for (let spark = 0; spark < 16; spark += 1) {
    const angle = (spark / 16) * Math.PI * 2 + presentationHash01(cycle, salt, spark) * 0.3;
    const speed = 1.4 + presentationHash01(cycle, salt, spark + 40) * 0.9;
    const sx = x + Math.cos(angle) * speed * age;
    const sy = y + Math.sin(angle) * speed * age + age * age * 0.012;
    ctx.beginPath();
    ctx.arc(sx, sy, 1.6 + fade * 1.4, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  if (age < 12) ambientGlow(x, y, 70, "255,230,190", (12 - age) / 12 * 0.35);
}

function drawStageAmbient(frame, centre, reaction) {
  if (state.performance.trailScale === 0) return;
  const reduced = state.accessibility.reducedMotion;
  const f = reduced ? 0 : frame;
  const skyX = (centre - W * 0.5) * -0.06;
  const stage = state.stage;
  // v5.0 AMBIENT REACTIONS: a KO is a pulse too, latched on the phase change.
  // 0..1 over the first ~40 ticks after a big moment, then gone.
  const { pulseAge, pulse, ko } = readAmbientPulse(frame, reduced);
  // v5.1 STAGE KO BEATS: the crowd's KO hold is the stage's KO beat (flash
  // decays over the same 48 ticks, hold rides the whole roundover), and the
  // four stages below the Vet draw from the stronger of pulse and flash.
  // Furniture pinned to painted landmarks rides the plate's own parallax
  // (drawCover's -0.035), sky pieces the wider skyX like the gulls.
  const beat = stageKoBeat(reduced);
  const surge = ambientSurge({ pulseAge, pulse }, beat);
  const plateX = (centre - W * 0.5) * -0.035;
  ctx.save();
  if (stage === "vet") {
    // Floodlights breathe, a blimp crawls the sky, fireworks pop over the bowl.
    for (const [lx, ly] of [[125, 88], [1230, 232]]) {
      ambientGlow(lx + skyX * 0.5, ly, 90 + pulse * 120, "255,236,190", 0.09 + Math.sin(f * 0.03 + lx) * 0.035 + pulse * 0.28);
    }
    // A big moment sets off a burst over the bowl right now (and a KO two).
    if (pulse > 0) {
      ambientFirework(pulseAge, 100000, 71 + ambientObs.pulseTick, 420, 860, 80, 170);
      if (ko) ambientFirework(Math.max(0, pulseAge - 14), 100000, 93 + ambientObs.pulseTick, 300, 980, 60, 160);
    }
    if (!reduced) {
      const blimpX = ((f * 0.32 + 700) % (W + 760)) - 380 + skyX;
      const blimpY = 66 + Math.sin(f * 0.008) * 5;
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = "#8d96a3";
      ctx.beginPath();
      ctx.ellipse(blimpX, blimpY, 62, 17, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#5c6470";
      ctx.fillRect(blimpX - 12, blimpY + 15, 24, 7);
      ctx.beginPath();
      ctx.moveTo(blimpX - 58, blimpY - 4); ctx.lineTo(blimpX - 74, blimpY - 14); ctx.lineTo(blimpX - 70, blimpY + 6);
      ctx.closePath(); ctx.fill();
      ctx.globalAlpha = 1;
      if (f % 70 < 9) ambientGlow(blimpX + 48, blimpY - 8, 9, "255,70,60", 0.9);
      ambientFirework(f, 560, 11, 380, 900, 70, 180);
      ambientFirework(f + 233, 740, 29, 300, 980, 60, 170);
    }
  } else if (stage === "wildwood") {
    // The wheel's rim lights turn, the sign chases, a plane crosses, a ship
    // sits on the horizon. v5.1 STAGE KO BEATS: a big hit sends a bright
    // sector chasing round the rim (a lap every 18 ticks) and floods the
    // WILDWOOD letters pink-gold with the chase bulbs stuttering under it;
    // the KO strobes the rim in 6-tick alternation, holds every chase bulb
    // lit for the whole roundover and puts two fireworks up over the pier.
    const cx = 222 + skyX, cy = 240, radius = 83;
    const chaseAngle = surge.age >= 0 ? surge.age * 0.35 : 0;
    const rimStrobe = surge.ko && surge.level > 0 ? Math.floor(surge.age / 6) % 2 : -1;
    for (let bulb = 0; bulb < 18; bulb += 1) {
      const angle = (bulb / 18) * Math.PI * 2 + f * 0.007;
      const hue = (bulb * 40 + f * 0.6) % 360;
      const bx = cx + Math.cos(angle) * radius, by = cy + Math.sin(angle) * radius;
      // Angular distance to the chasing sector, folded to 0..PI.
      const gap = Math.abs((((angle - chaseAngle) % (Math.PI * 2)) + Math.PI * 3) % (Math.PI * 2) - Math.PI);
      const inSector = surge.level > 0 && gap < 0.9;
      const strobed = rimStrobe >= 0 && bulb % 2 === rimStrobe;
      ctx.fillStyle = `hsla(${hue}, 95%, 72%, .75)`;
      ctx.beginPath();
      ctx.arc(bx, by, 2.4 + (inSector || strobed ? surge.level * 2.2 : 0), 0, Math.PI * 2);
      ctx.fill();
      if (inSector) ambientGlow(bx, by, 14 + surge.level * 12, "255,240,220", surge.level * (1 - gap / 0.9) * 0.9);
      if (strobed) ambientGlow(bx, by, 12, "255,250,240", surge.level * 0.85);
    }
    if (surge.level > 0) ambientGlow(cx, cy, radius + 40 + surge.level * 40, "255,190,230", surge.level * 0.28);
    // The sign: pink-gold flood over the letters while a surge is live.
    if (surge.level > 0) {
      ambientGlow(520 + plateX, 165, 250, "255,170,200", surge.level * 0.42);
      ambientGlow(850 + plateX, 165, 250, "255,196,150", surge.level * 0.42);
    }
    // Chase bulbs under the letters: the idle 1-in-7 chase, 4x faster on a
    // pulse; the KO hold burns every bulb (stuttering through the flash,
    // then a solid double-speed chase for the rest of the roundover).
    for (let bulb = 0; bulb < 28; bulb += 1) {
      const chase = ((bulb - Math.floor(f * (0.18 + pulse * 0.6 + (beat.hold ? 0.18 : 0)))) % 7 + 7) % 7 === 0;
      const held = beat.hold && ambientStutter(presentationHash01(Math.floor(f / 3), 23, bulb), beat.flash) > 0.5;
      if (!chase && !held) continue;
      const alpha = held ? 0.55 + beat.flash * 0.4 : 0.55 + surge.level * 0.35;
      ambientGlow(368 + bulb * 24 + skyX * 0.3, 234, 7 + surge.level * 5, "255,228,200", alpha);
    }
    // The KO's fireworks over the pier (the pulse burst below stays).
    if (beat.hold) {
      ambientFirework(beat.age, 100000, 53 + crowdKoHold.startTick, 120, 560, 60, 200);
      if (beat.age >= 22) ambientFirework(beat.age - 22, 100000, 59 + crowdKoHold.startTick, 200, 640, 50, 180);
    }
    if (!reduced) {
      const planeX = W + 200 - ((f * 0.85) % (W + 460)) + skyX;
      const planeY = 52 + Math.sin(f * 0.004) * 4;
      ctx.fillStyle = "rgba(210,216,226,.55)";
      ctx.fillRect(planeX - 7, planeY, 14, 2);
      if (f % 50 < 6) ambientGlow(planeX - 8, planeY + 1, 7, "255,80,70", 0.9);
      if ((f + 25) % 50 < 4) ambientGlow(planeX + 8, planeY + 1, 7, "230,240,255", 0.9);
    }
    if (pulse > 0) ambientFirework(pulseAge, 100000, 37 + ambientObs.pulseTick, 420, 980, 70, 150);
    const shipX = 1040 - ((f * 0.04) % 820) + skyX * 0.4;
    for (let light = 0; light < 5; light += 1) {
      ambientGlow(shipX + light * 7, 365 + (light % 2), 4, "255,214,150", 0.55);
    }
  } else if (stage === "buffet") {
    // Kitchen staff cross the pass-through, a wok flares, pendants breathe.
    // v5.1 STAGE KO BEATS: a big hit throws the wok — a fireball climbing out
    // of the pass with a white-hot core — stutters the five pendants and
    // rattles the tray line (specular glints hopping along the sneeze guard);
    // the steam-table plumes erupt in drawBuffetAtmosphere and the heat lamps
    // flare in drawPracticalLights off the same surge. The KO floods the
    // whole pass-through window with kitchen light.
    const crossing = (period, salt, direction, speed, y, height) => {
      const age = (f + salt) % period;
      const duration = 840 / speed;
      if (age > duration) return;
      const progress = age / duration;
      const x = direction > 0 ? 250 + progress * 840 : 1090 - progress * 840;
      const bob = Math.abs(Math.sin(age * 0.35)) * 2;
      ctx.fillStyle = "rgba(24,20,18,.58)";
      ctx.beginPath();
      ctx.ellipse(x, y + 12 - bob, 9, 10, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillRect(x - 12, y + 22 - bob, 24, height);
      ctx.fillStyle = "rgba(235,235,235,.5)";
      ctx.fillRect(x - 7, y - bob, 14, 9);
    };
    if (!reduced) {
      crossing(700, 0, 1, 4.2, 132, 36);
      crossing(1130, 410, -1, 3.3, 136, 34);
    }
    const flare = (f + 170) % 330;
    if (flare < 14) ambientGlow(1040, 158, 60, "255,170,70", (14 - flare) / 14 * 0.6);
    if (surge.level > 0) {
      // The fireball climbs ~30 px out of the pass as it fades.
      const climb = (1 - surge.level) * 30;
      ambientGlow(1040 + plateX, 150 - climb, 60 + surge.level * 110, "255,190,90", surge.level * 0.9);
      ambientGlow(1040 + plateX, 128 - climb, 30 + surge.level * 40, "255,240,200", surge.level * 0.7);
    }
    if (beat.flash > 0) ambientBand(230 + plateX, 122, 900, 100, "255,228,180", beat.flash * 0.55);
    for (const [index, px] of [40, 330, 640, 940, 1240].entries()) {
      const stutter = ambientStutter(presentationHash01(Math.floor(f / 3), 7, index), surge.level);
      ambientGlow(px + plateX, 74, 46 + surge.level * 30, "255,196,120", (0.08 + Math.sin(f * 0.05 + px) * 0.03 + surge.level * 0.22) * stutter);
    }
    if (surge.level > 0) {
      // Tray rattle: ten glints hop along the tray line, each on its own beat.
      for (let glint = 0; glint < 10; glint += 1) {
        const hop = Math.max(0, Math.sin(surge.age * 0.55 + glint * 1.1)) * surge.level * 9;
        ambientGlow(150 + glint * 110 + plateX, 322 - hop, 14, "255,240,220", surge.level * 0.8);
      }
    }
  } else if (stage === "cruise") {
    // Funnel smoke, gulls over the water, a ship on the horizon. v5.1 STAGE
    // KO BEATS: a big hit flashes the pool and the wet deck and stutters the
    // party string under the bar awning; the five splash plumes fire together
    // in drawPoolDeckAtmosphere. The KO sounds the horn (updateCrowdAudio) —
    // a steam jet off the funnel with the horn light on it — and puts six
    // gulls up off the port rail.
    if (!reduced) {
      for (let puff = 0; puff < 7; puff += 1) {
        const age = (f + puff * 41) % 290;
        const t = age / 290;
        ctx.globalAlpha = (1 - t) * 0.32;
        ctx.fillStyle = "#d9dde3";
        ctx.beginPath();
        ctx.arc(740 + skyX + t * 150 + Math.sin(age * 0.05 + puff) * 6, 18 - t * 70, 7 + t * 22, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
      for (let gull = 0; gull < 5; gull += 1) {
        const lane = gull % 2 === 0 ? -1 : 1;
        const gx = ((f * (0.35 + gull * 0.07) + gull * 260 + pulse * 90 * (gull + 1)) % (W + 260)) - 130;
        const gy = 90 + gull * 34 + Math.sin(f * 0.012 + gull) * 16 - pulse * 40;
        if (gx > 330 && gx < 960) continue;
        ambientGull(gx + skyX * (1 + lane * 0.2), gy, Math.sin(f * 0.28 + gull * 1.7) * 4, 8 + (gull % 3) * 2, 0.75);
      }
    }
    const shipX = 40 + ((f * 0.03) % 260) + skyX * 0.3;
    ctx.fillStyle = "rgba(226,232,240,.6)";
    ctx.fillRect(shipX, 296, 26, 5);
    ctx.fillRect(shipX + 6, 291, 12, 5);
    // The party string under the awning: 26 warm bulbs, a soft idle glow,
    // stuttering hard while a surge is live.
    for (let bulb = 0; bulb < 26; bulb += 1) {
      const stutter = ambientStutter(presentationHash01(Math.floor(f / 3), 11, bulb), surge.level);
      ambientGlow(350 + bulb * 26 + plateX, 308, 6 + surge.level * 5, "255,214,150", (0.35 + surge.level * 0.3) * stutter);
    }
    if (surge.level > 0) {
      // Pool surface and wet deck flash — the 'pool-deck flash' of the 5.0 note.
      ambientBand(200 + plateX, 402, 880, 96, "150,235,255", surge.level * 0.55);
      ambientGlow(640 + plateX, 450, 300, "170,240,255", surge.level * 0.35);
      ambientBand(0, 500, W, 110, "255,244,214", surge.level * 0.28);
    }
    if (beat.hold) {
      // Horn: a steam jet climbs off the funnel for ~40 ticks under the light.
      const jet = Math.min(1, beat.age / 40);
      const funnelX = 745 + skyX;
      for (let puff = 0; puff < 4; puff += 1) {
        const t = Math.max(0, jet - puff * 0.12);
        if (t <= 0) continue;
        ctx.globalAlpha = (1 - t) * 0.75;
        ctx.fillStyle = "#f4f7fa";
        ctx.beginPath();
        ctx.arc(funnelX + t * 30 + puff * 6, 14 - t * 70 - puff * 10, 8 + t * 22, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
      ambientGlow(funnelX, 22, 40 + beat.flash * 50, "255,240,200", beat.flash * 0.9);
      // Six gulls up off the port rail, fanning out over 90 ticks.
      if (beat.age < 90) {
        const t = beat.age / 90;
        for (let gull = 0; gull < 6; gull += 1) {
          const gx = 110 + gull * 34 + plateX + t * (180 + gull * 55);
          const gy = 330 - t * (210 + gull * 28) + Math.sin(beat.age * 0.3 + gull) * 6;
          ambientGull(gx, gy, Math.sin(beat.age * 0.45 + gull * 1.3) * 4, 7 + (gull % 3) * 2, 0.8 * (1 - t * 0.5));
        }
      }
    }
  } else if (stage === "janney") {
    // Moths orbit the sodium lamp, TVs flicker in the rowhouses, a car's
    // lights sweep the far street, a plane blinks over the roofs.
    if (!reduced) {
      for (let moth = 0; moth < 6; moth += 1) {
        const a = f * (0.09 + moth * 0.013) + moth * 1.3;
        const r = (9 + Math.sin(f * 0.031 + moth * 2.1) * 8 + moth * 2) * (1 + pulse * 2.4);
        ctx.fillStyle = "rgba(255,236,190,.85)";
        ctx.beginPath();
        ctx.arc(533 + skyX * 0.4 + Math.cos(a) * r, 140 + Math.sin(a * 1.4) * r * 0.55, 1.3, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    for (const [wx, wy, ww, wh, salt] of [[62, 38, 22, 20, 1], [137, 38, 22, 20, 2], [196, 182, 22, 24, 3], [1050, 188, 22, 26, 4]]) {
      const flicker = presentationHash01(Math.floor(f / 5), salt);
      if (flicker > 0.45) ambientGlow(wx + ww * 0.5 + skyX * 0.4, wy + wh * 0.5, 26, "150,190,255", 0.12 + flicker * 0.2);
      if (ko) ambientGlow(wx + ww * 0.5 + skyX * 0.4, wy + wh * 0.5, 30, "240,245,255", pulse * 0.5);
    }
    if (!reduced) {
      const pass = f % 760;
      if (pass < 160) {
        const x = 330 + (pass / 160) * 380 + skyX * 0.5;
        ambientGlow(x, 196, 90, "255,225,170", 0.16);
        ambientGlow(x + 14, 200, 8, "255,250,230", 0.9);
        ambientGlow(x + 30, 200, 8, "255,250,230", 0.9);
      }
      const planeX = ((f * 0.55) % (W + 300)) - 150 + skyX;
      if (f % 46 < 5) ambientGlow(planeX, 44, 6, "255,90,80", 0.85);
      if ((f + 23) % 46 < 3) ambientGlow(planeX + 10, 44, 6, "220,235,255", 0.85);
    }
  } else if (stage === "somerset") {
    // The corner signal cycles, headlights come up the side street, pigeons
    // peck the wet sidewalk and scatter now and then. v5.1 STAGE KO BEATS: a
    // big hit surges the nine station lamps under the El and the SOMERSET
    // sign, stutters the corner signal and the storefront neon (the El's
    // window band on the pavement flares in drawPracticalLights); the KO
    // sends a second train through at speed — 60 ticks end to end, lit
    // windows smeared into a streak, its band sweeping the wet street — and
    // lights the whole street level for the flash.
    const cycle = f % 720;
    const signal = cycle < 380 ? "255,64,50" : cycle < 440 ? "255,190,60" : "80,230,120";
    ambientGlow(1193 + skyX * 0.3, 67, 9 + surge.level * 8, signal, 0.85 * ambientStutter(presentationHash01(Math.floor(f / 4), 17, 0), surge.level));
    if (surge.level > 0) {
      const lamps = [[150, 100], [670, 100], [615, 205], [45, 240], [190, 268], [410, 280], [460, 300], [760, 285], [1240, 95]];
      for (const [index, [lx, ly]] of lamps.entries()) {
        const stutter = ambientStutter(presentationHash01(Math.floor(f / 4), 13, index), surge.level * 0.6);
        ambientGlow(lx + plateX, ly, 22 + surge.level * 70, "255,214,140", surge.level * 0.75 * stutter);
      }
      ambientGlow(600 + plateX, 292, 90 + surge.level * 60, "120,255,170", surge.level * 0.55);
      ambientGlow(60 + plateX, 300, 30 + surge.level * 30, "255,90,70", surge.level * 0.6 * ambientStutter(presentationHash01(Math.floor(f / 3), 19, 0), surge.level));
    }
    if (beat.hold && beat.age < 60) {
      const t = beat.age / 60;
      const tx = -460 + t * (W + 920) + plateX;
      ctx.fillStyle = "rgba(200,210,220,.5)";
      ctx.fillRect(tx, 154, 430, 58);
      ambientBand(tx - 120, 160, 670, 36, "255,225,150", 0.35);
      for (let x = tx + 24; x < tx + 410; x += 53) {
        ctx.fillStyle = "rgba(255,232,160,.95)";
        ctx.fillRect(x, 166, 34, 22);
        ambientGlow(x + 17, 177, 40, "255,225,150", 0.5);
      }
      ambientGlow(tx + 215, 560, 300, "255,208,116", 0.35 * (1 - t * 0.3));
    }
    if (beat.flash > 0) {
      ambientBand(0, 380, W, 240, "255,225,180", beat.flash * 0.35);
      ambientGlow(640 + plateX, 300, 520, "255,225,180", beat.flash * 0.3);
    }
    if (!reduced) {
      const pass = f % 820;
      if (pass < 170) {
        const t = pass / 170;
        const x = 385 + t * 175 + skyX * 0.5;
        const size = 4 + t * 10;
        ambientGlow(x, 286, 40 + t * 60, "255,236,200", 0.14 + t * 0.12);
        ambientGlow(x - size, 288, size, "255,250,235", 0.9);
        ambientGlow(x + size, 288, size, "255,250,235", 0.9);
      }
      for (let bird = 0; bird < 3; bird += 1) {
        const scatter = ambientSyncedCycle(pulseAge, bird * 4, 60, (f + bird * 90) % 900);
        const fly = scatter < 60 ? scatter / 60 : 0;
        const bx = 150 + bird * 26 + skyX * 0.2 + fly * (60 + bird * 20) + (scatter >= 60 ? 0 : 0);
        const by = 332 + (bird % 2) * 4 - fly * (90 + bird * 15) + (fly ? 0 : Math.abs(Math.sin(f * 0.11 + bird)) * -2);
        ctx.fillStyle = "rgba(120,124,132,.9)";
        ctx.beginPath();
        ctx.ellipse(bx, by, 5, 3.2, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(bx + 4, by - 2, 1.8, 0, Math.PI * 2);
        ctx.fill();
        if (fly) ambientGull(bx, by - 3, Math.sin(f * 0.5 + bird) * 4, 6, 0.7);
      }
    }
    if (reaction > 0.6) ambientGlow(640, 250, 260, "255,220,180", (reaction - 0.6) * 0.08);
  }
  ctx.restore();
}

function drawBoardwalkAtmosphere(frame, centre) {
  ctx.save();
  // Seagulls drifting over the ocean.
  ctx.globalAlpha = 0.5;
  ctx.strokeStyle = "#d8dee6";
  ctx.lineWidth = 2;
  for (let index = 0; index < 6; index += 1) {
    const gullX = ((frame * (0.6 + index * 0.18) + index * 230) % (W + 160)) - 80
      + (centre - W * 0.5) * -0.06;
    const gullY = 150 + index * 17 + Math.sin(frame * 0.02 + index) * 9;
    const flap = Math.sin(frame * 0.16 + index * 1.4) * 5;
    ctx.beginPath();
    ctx.moveTo(gullX - 8, gullY + flap);
    ctx.quadraticCurveTo(gullX, gullY - 3, gullX + 8, gullY + flap);
    ctx.stroke();
  }
  // A ride car climbing the coaster behind the sign.
  const rideT = (frame % 420) / 420;
  ctx.globalAlpha = 0.75;
  ctx.fillStyle = "#ffd54a";
  ctx.fillRect(200 + rideT * 260 + (centre - W * 0.5) * -0.08, 300 - Math.sin(rideT * Math.PI) * 58, 14, 8);
  // Sea haze rolling along the railing line.
  const haze = ctx.createLinearGradient(0, 400, 0, 520);
  haze.addColorStop(0, "rgba(150,180,205,0)");
  haze.addColorStop(0.5, `rgba(150,180,205,${0.06 + Math.sin(frame * 0.008) * 0.02})`);
  haze.addColorStop(1, "rgba(150,180,205,0)");
  ctx.globalAlpha = 1;
  ctx.fillStyle = haze;
  ctx.fillRect(0, 400, W, 120);
  ctx.restore();
}

// Steam bursts, swaying pendant lights and rattling trays over the crab legs.
function drawBuffetAtmosphere(frame, centre, reaction) {
  ctx.save();
  // v5.1 STAGE KO BEATS: all seven plumes erupt together on a surge — the
  // rise shoots to full in 10 ticks, the plume grows and brightens with the
  // level and settles back over its 48 ticks (measured idle: 0.16 peak alpha).
  const surge = stageSurge(frame);
  const erupt = surge.level > 0 ? Math.min(1, surge.age / 10) : 0;
  for (let index = 0; index < 7; index += 1) {
    const x = 120 + index * 165 + (centre - W * 0.5) * -0.1;
    if (x < -60 || x > W + 60) continue;
    // Steam pulses on their own rhythm rather than all together.
    const pulse = (frame * (0.012 + index * 0.002) + index * 1.7) % (Math.PI * 2);
    const rise = Math.max((Math.sin(pulse) + 1) * 0.5, erupt);
    const size = 16 + rise * 26 + surge.level * 24;
    const top = 430 - rise * 46 - surge.level * 18;
    const gradient = ctx.createRadialGradient(x, top, 2, x, top, size);
    gradient.addColorStop(0, `rgba(240,244,248,${0.16 * (1 - rise * 0.55) + surge.level * 0.34})`);
    gradient.addColorStop(1, "rgba(240,244,248,0)");
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(x, top, size, 0, Math.PI * 2);
    ctx.fill();
  }
  // Pendant lights swaying, harder right after a big hit (and hardest on a surge).
  const sway = (0.02 + reaction * 0.05 + surge.level * 0.12) * Math.sin(frame * 0.03);
  ctx.globalAlpha = 0.4;
  ctx.strokeStyle = "#f2c98a";
  ctx.lineWidth = 2;
  for (let index = 0; index < 6; index += 1) {
    const x = 150 + index * 200 + (centre - W * 0.5) * -0.1;
    ctx.beginPath();
    ctx.moveTo(x, 60);
    ctx.lineTo(x + Math.sin(sway + index) * 12, 132);
    ctx.stroke();
  }
  ctx.restore();
}

// Splashes in the pool, traffic on the slide and heat shimmer over the deck.
function drawPoolDeckAtmosphere(frame, centre, reaction) {
  ctx.save();
  // Splash plumes where the pool sits behind the fight floor. v5.1 STAGE KO
  // BEATS: all five fire together for the 60 ticks after a pulse (each 3
  // ticks behind the last), bigger with the level; the KO adds a cannonball
  // in the middle of the pool — eleven drops on an 80 px spread.
  const surge = stageSurge(frame);
  const plumes = surge.ko && surge.hold && surge.age < 60 ? 6 : 5;
  for (let index = 0; index < plumes; index += 1) {
    const cannonball = index === 5;
    const idle = (frame * (0.9 + index * 0.25) + index * 137) % 260;
    const cycle = cannonball ? surge.age : ambientSyncedCycle(surge.pulseAge, index * 3, 60, idle);
    if (cycle < 0 || cycle > 60) continue;
    const life = cycle / 60;
    const x = (cannonball ? 640 : 220 + index * 210) + (centre - W * 0.5) * -0.12;
    if (x < -60 || x > W + 60) continue;
    const drops = cannonball ? 11 : 7;
    ctx.globalAlpha = (1 - life) * (0.65 + surge.level * 0.3);
    ctx.fillStyle = "#dff4ff";
    for (let drop = 0; drop < drops; drop += 1) {
      const angle = (drop / drops) * Math.PI - Math.PI;
      const spread = life * (cannonball ? 80 : 46 + surge.level * 20);
      ctx.beginPath();
      ctx.arc(x + Math.cos(angle) * spread, 452 + Math.sin(angle) * spread * 0.5, (cannonball ? 6 : 4 + surge.level * 2) - life * 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // A rider running the slide.
  const slideT = (frame % 300) / 300;
  ctx.globalAlpha = 0.8;
  ctx.fillStyle = "#ffd24a";
  ctx.beginPath();
  ctx.arc(150 + slideT * 120 + (centre - W * 0.5) * -0.1, 300 + Math.sin(slideT * Math.PI) * 90, 7, 0, Math.PI * 2);
  ctx.fill();
  // Heat shimmer over the hot deck, stronger when the crowd is stirred.
  const shimmer = ctx.createLinearGradient(0, 470, 0, 560);
  shimmer.addColorStop(0, "rgba(255,244,214,0)");
  shimmer.addColorStop(0.5, `rgba(255,244,214,${0.05 + reaction * 0.05 + Math.sin(frame * 0.02) * 0.015})`);
  shimmer.addColorStop(1, "rgba(255,244,214,0)");
  ctx.globalAlpha = 1;
  ctx.fillStyle = shimmer;
  ctx.fillRect(0, 470, W, 90);
  ctx.restore();
}

function drawVacantLotCat(cat, x, gait, paused, startled) {
  const scale = cat.scale;
  const step = paused ? 0 : Math.sin(gait) * 4.2;
  const crouch = startled ? 2 : 0;
  ctx.save();
  ctx.translate(x, cat.y + crouch);
  ctx.scale(scale * cat.direction, scale);
  ctx.globalAlpha = 0.9;
  ctx.fillStyle = "rgba(0,0,0,.55)";
  ctx.beginPath();
  ctx.ellipse(0, 3, 18, 4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = cat.coat;
  ctx.beginPath();
  ctx.ellipse(0, -9, 17, 9, startled ? -0.08 : 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(15, -15, 7, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(10, -20); ctx.lineTo(12, -29); ctx.lineTo(16, -21);
  ctx.moveTo(16, -21); ctx.lineTo(21, -28); ctx.lineTo(21, -18);
  ctx.fill();
  ctx.strokeStyle = cat.coat;
  ctx.lineWidth = 5;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-14, -10);
  ctx.quadraticCurveTo(-31, -23 - cat.tailCurl * 5, -27, -39 + cat.tailCurl * 4);
  ctx.stroke();
  ctx.lineWidth = 3.5;
  ctx.beginPath();
  ctx.moveTo(-8, -4); ctx.lineTo(-9 + step, 1);
  ctx.moveTo(6, -4); ctx.lineTo(8 - step, 1);
  ctx.stroke();
  ctx.fillStyle = startled ? "#ffd96a" : "#9fc6a8";
  ctx.beginPath(); ctx.arc(17, -16, 1.2, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

// The generated stage already contains parked cars. These tiny suspension and
// reflection shifts make two of them feel occupied without drawing people or
// showing anything explicit.
function drawJanneyAtmosphere(frame, centre, reaction, crowd) {
  const parallax = (centre - W * 0.5) * -0.12;
  for (const [index, baseX] of [122, 1158].entries()) {
    const phase = frame * (0.031 + index * 0.004) + index * 2.4;
    const rock = Math.sin(phase) * (1.5 + reaction * 0.9);
    const x = baseX + parallax;
    const y = index ? 426 : 420;
    ctx.save();
    ctx.translate(x, y + Math.abs(rock) * 0.5);
    ctx.rotate(rock * 0.0025 * (index ? -1 : 1));
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = index ? "#8eb1bb" : "#77899a";
    ctx.beginPath();
    ctx.roundRect(-74, -18, 148, 32, 8);
    ctx.fill();
    ctx.globalAlpha = 0.24;
    ctx.fillStyle = "#ffd28a";
    ctx.fillRect(index ? -63 : 53, -8 + rock * 0.25, 10, 4);
    ctx.restore();
  }
  for (const cat of crowd.cats || []) {
    const position = catPosition(cat, frame, crowd.span, crowd.minX, reaction);
    const drawX = position.x + (centre - W * 0.5) * -0.2;
    if (drawX < -45 || drawX > W + 45) continue;
    drawVacantLotCat(cat, drawX, position.gait, position.paused, position.startled);
  }
  // A restrained dusk glow catches dust above the open fight floor.
  const glow = ctx.createRadialGradient(W * 0.5, 440, 40, W * 0.5, 440, 430);
  glow.addColorStop(0, "rgba(255,197,123,.06)");
  glow.addColorStop(1, "rgba(79,92,157,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 260, W, 300);
}

function drawCrowd(time) {
  const crowd = state.crowd;
  if (!crowd) return;
  const centre = state.fighters.length ? (state.fighters[0].x + state.fighters[1].x) * 0.5 : W * 0.5;
  // v5.1 KO MOMENT: the held reaction (the sim value outside the hold).
  updateCrowdKoHoldLatch();
  const reaction = crowdDrawReaction();
  const frame = state.simulationTick;
  // Cheapest possible culling: skip anyone whose parallaxed x is off screen.
  // A hard-stirred crowd pops scattered phone flashes; the pick hashes
  // (window, person) so it can never perturb the visualRandom stream.
  const flashPicks = crowdFlashPicks(crowd, frame, reaction);
  const flashSpots = [];
  let personIndex = -1;
  for (const person of crowd.people) {
    personIndex += 1;
    const layer = CROWD_LAYERS.find((entry) => entry.id === person.layer);
    const { x, gait, paused } = crowdPosition(person, layer, frame, crowd.span, crowd.minX);
    // v5.3: a plate-anchored crowd (Somerset's stationed bystanders) rides the
    // plate's own parallax factor, or it slides off its own doorway.
    const drawX = x + (centre - W * 0.5) * -(crowd.parallax || layer.parallax);
    if (drawX < -70 || drawX > W + 70) continue;
    drawPedestrian(person, layer, drawX, gait, paused, reaction, x);
    const flashPick = flashPicks.length ? flashPicks.find((pick) => pick.index === personIndex) : null;
    if (flashPick) {
      const scale = layer.scale * person.height;
      // v5.3: the starburst sits ON the phone — the manifest's per-cell hand
      // point through the same blit maths drawCrowdSprite uses — instead of a
      // fixed head-height offset that could land beside a souvenir cup.
      let spot = { x: drawX + person.direction * 8 * scale, y: person.y - 118 * scale, size: 8 + 9 * layer.scale };
      const resolved = crowdSpriteCharacter(person);
      if (resolved) {
        const { column, bob } = crowdSpriteFrame(person, gait, paused, reaction, x);
        const cell = resolved.character.cells[column] || resolved.character.cells[0];
        if (cell.hand) {
          const drawScale = (134 * scale) / Math.max(1, cell.h);
          spot = {
            x: drawX + (cell.hand.x - cell.cx) * drawScale * person.direction,
            y: person.y - bob - (cell.baseline - cell.hand.y) * drawScale,
            size: 6 + 8 * layer.scale,
          };
        }
      }
      flashSpots.push([spot, flashPick]);
    }
  }
  ctx.globalAlpha = 1;
  for (const [spot, pick] of flashSpots) drawCrowdFlash(spot, pick);

  for (const group of crowd.scuffles || []) drawScuffle(group, frame, centre, reaction);
  if (crowd.variant === "tailgate") {
    drawTailgateProps(frame, centre);
    // Cups thrown into the air when the crowd is stirred hardest.
    if (reaction > 0.5) {
      ctx.globalAlpha = Math.min(0.7, (reaction - 0.5) * 1.6);
      ctx.fillStyle = "#d8dde2";
      for (let index = 0; index < 14; index += 1) {
        const cupX = ((index * 97 + frame * 2.4) % (W + 60)) - 30;
        const cupY = 470 - Math.abs(Math.sin(frame * 0.05 + index)) * 90;
        ctx.fillRect(cupX, cupY, 6, 8);
      }
      ctx.globalAlpha = 1;
    }
    return;
  }

  if (crowd.variant === "boardwalk") {
    drawBoardwalkAtmosphere(frame, centre);
    return;
  }
  if (crowd.variant === "buffet") {
    drawBuffetAtmosphere(frame, centre, reaction);
    return;
  }
  if (crowd.variant === "poolside") {
    drawPoolDeckAtmosphere(frame, centre, reaction);
    return;
  }
  if (crowd.variant === "vacantLot") {
    drawJanneyAtmosphere(frame, centre, reaction, crowd);
    return;
  }

  // Somerset keeps the old K&A motion layer: a passing El train, warm windows,
  // and wind-blown litter over the photoreal street plate. The people are baked
  // into that plate so their deep folded postures stay genuinely realistic.
  const trainX = ((time * 0.08) % (W + 650)) - 500;
  ctx.fillStyle = "rgba(157,166,174,.42)";
  ctx.fillRect(trainX, 154, 430, 58);
  ctx.fillStyle = "rgba(23,60,92,.48)";
  ctx.fillRect(trainX, 196, 430, 7);
  for (let x = trainX + 24; x < trainX + 410; x += 53) {
    ctx.fillStyle = "rgba(255,211,105,.75)";
    ctx.fillRect(x, 166, 34, 22);
  }
  for (let index = 0; index < 5; index += 1) {
    const litterX = ((frame * (0.5 + index * 0.2) + index * 260) % (W + 120)) - 60;
    const litterY = 528 + Math.sin(frame * 0.02 + index) * 7 + index * 4;
    ctx.globalAlpha = 0.3;
    ctx.fillStyle = "#7d8794";
    ctx.fillRect(litterX, litterY, 7, 4);
  }
  ctx.globalAlpha = 1;
}

function drawVetAtmosphere(time) {
  for (let i = 0; i < 5; i += 1) {
    const x = 110 + i * 275 + Math.sin(time * 0.0002 + i) * 10;
    const y = 492 + (i % 2) * 23;
    const smoke = 19 + Math.sin(time * 0.001 + i) * 7;
    const gradient = ctx.createRadialGradient(x, y - 40, 2, x, y - 40, smoke * 2.5);
    gradient.addColorStop(0, "rgba(210,220,225,.13)");
    gradient.addColorStop(1, "rgba(210,220,225,0)");
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(x, y - 40, smoke * 2.5, 0, Math.PI * 2);
    ctx.fill();
  }
}

// v2.7 FRAMES: the pose selector emits descriptors that may name the motion
// bank; this resolver holds them only while the fighter's sheet is loaded AND
// the manifest accepts the cell, else the descriptor's own fallback (exactly
// the pre-2.7 cell) draws. Every consumer — drawFighter, the observers, the
// CINEMA 3D bridge — reads through here, so both renderers always agree.
function fighterAnimationPose(fighter) {
  // v2.9 critic round 2 (B4): a move with no kit art of its own draws from the
  // shared banks, and those banks are where a prop can leak into a bare-handed
  // swing. The gate is passed here, at the single resolution choke point, so
  // it covers every present and future beat of a kit-less move — not just the
  // recovery cell the critics happened to catch.
  const bareHanded = Boolean(fighter.attacking) && bareHandedAttack(fighter.attacking);
  // v5.0 FULL SWING: the resolved drawing is substituted with its same-family
  // strike/reaction cell when the fighter's sheet has one. Timing untouched.
  const resolvedPose = resolveMotionPose(
    fighterPoseDescriptor(fighter),
    (cell, bank) => motionBankCellDrawable(fighter.def.id, cell, bank),
    fighter.def.id,
    { bareHanded },
  );
  const swung = swingResolve(resolvedPose, swingContext(fighter, { roundDecided: state.phase === "finish" || state.phase === "roundover" || state.phase === "result" }), (cell, bank) => motionBankCellDrawable(fighter.def.id, cell, bank));
  // v5.3 SPECIALS: last, because it is the only rule that reads the KIT bank —
  // everything above resolves the authored banks and may still land on a
  // specials cell as its terminal fallback.
  const pose = specialsGenerationPose(fighter.def.id, swung);
  recordPoseTrace(fighter, pose);
  return pose;
}

// v5.0 QA (engineering pass): the pose TRANSITIONS per side, so a probe can
// assert the ORDER a strike's drawings arrived in (the 5.0 acceptance
// evidence — jab `ext2:0 -> ext3:0 -> ext3:2 -> ext2:1 -> unified:7` — was
// read off by eye from frame attribution, and pose() reports only the
// current cell). Written at the single resolution choke point above, deduped
// against the previous entry so the several reads per tick (draw, observers,
// the CINEMA 3D bridge, pose()) record one transition; only the LIVE fighter
// on each side is traced, never a ghost or a preview body. 64 entries is
// four seconds of a busy exchange at the ~4-6 transitions a normal makes.
const POSE_TRACE_SIZE = 64;
const poseTrace = [[], []];

function recordPoseTrace(fighter, pose) {
  const side = fighter.side;
  if ((side !== 0 && side !== 1) || state.fighters?.[side] !== fighter) return;
  const ring = poseTrace[side];
  const last = ring.length ? ring[ring.length - 1] : null;
  if (last && last.bank === pose.bank && last.frame === pose.frame) return;
  ring.push({ tick: state.simulationTick, bank: pose.bank, frame: pose.frame });
  if (ring.length > POSE_TRACE_SIZE) ring.shift();
}

// Showcase rotation (taunt + round-win): the match seed and banked rounds pick
// deterministically between the kit victory cell, the motion alternate win
// pose and the second signature — pure snapshotted sim state, never
// Math.random, so rollback resimulation and both online peers agree.
// v5.2 LOCOMOTION: the showcase is the fighter's OWN cell first — the ext5
// victory under the curtain-call spotlight, the ext5 taunt for the taunt —
// over the exact rotation below, which is what draws when the sheet is not
// on the fighter (and what the kit's specials:15 read has always been).
function showcasePick() {
  return (((state.matchSeed >>> 0) + state.rounds[0] + state.rounds[1]) >>> 0) % 3;
}

function showcasePoseDescriptor(fighter, ext5Cell = UNIFIED_EXT5_CELLS.victory) {
  const victory = fighter.kit.victory;
  const pick = showcasePick();
  const rotation = pick === 1 ? motionPose(MOTION_CELLS.victory2, victory.bank, victory.frame)
    : pick === 2 ? motionPose(MOTION_CELLS.sig2, victory.bank, victory.frame)
      : { bank: victory.bank, frame: victory.frame };
  return unifiedExt5Pose(ext5Cell, rotation);
}

// v5.2 LOCOMOTION (bookends): the plain-KO curtain call, by mode — the value
// finishRound sets, read again by the win pose to know how far into the hold
// it is (phaseTime counts down; both are snapshotted, so a resim agrees).
function roundWinHoldSeconds() {
  return state.mode === "demo" ? DEMO_KO_HOLD_SECONDS : ROUND_WIN_HOLD_SECONDS;
}

// v5.2 LOCOMOTION (bookends): a fighter inside a Final Blow draws the key's
// same-generation cell over the base cell the sim stored in cinematicFrame
// (engine/finisher-scripts, finisherCinematicPose). The victim's body at rest
// is the ext4 KO cell only when his sprite is drawn WHOLE — under the graphic
// fatality's band slicing the rest stays the upright-plan wall splat laid
// down by the script's own rotation. Pure reads of snapshotted state plus the
// gore toggle (presentation, like the atlas gate itself).
function cinematicPoseDescriptor(fighter, fallback) {
  const finisher = state.finisher;
  if (!finisher || state.fighters?.length !== 2 || state.fighters[fighter.side] !== fighter) return fallback;
  const role = fighter.side === finisher.winner ? "attacker" : "victim";
  const plainBody = role === "victim" && !(state.graphicFatalities && finisher.fatalityTriggered);
  return finisherCinematicPose(sampleFinisher(finisher.script.keys, finisher.elapsed), role, fallback, { plainBody });
}

// v4.0: the one options object every ext-aware beat track is handed, frozen so
// a track cannot mutate the caller's capability answer.
const EXTENDED = Object.freeze({ extended: true });
// v4.1: the same object for a fighter whose cell 20 is a real descent, so the
// jump arc can own the whole airborne chain 8 -> 19 -> 9 -> 20. Only the jump
// arc reads `descend`; every other track destructures `extended` alone and is
// handed this object unchanged, which keeps "one capability answer per pose"
// true rather than nearly true.
const EXTENDED_DESCEND = Object.freeze({ extended: true, descend: true });
// v5.2 LOCOMOTION (ext5-air): the same three answers with `air` — the ext5
// apex tuck, descent and air recover drawable — which only the jump arc
// reads (every other track destructures what it knows and ignores the rest).
// Frozen for the same reason: a track cannot mutate the caller's answer.
const AIR = Object.freeze({ air: true });
const EXTENDED_AIR = Object.freeze({ extended: true, air: true });
const EXTENDED_DESCEND_AIR = Object.freeze({ extended: true, descend: true, air: true });
// Idle breaths per second on a fighter with an ext sheet. Two drawings at 7.5/s
// is 8 ticks each at 60fps — exactly MOTION_HOLD_BUDGET, so the most-seen beat
// in the game sits precisely at the limit the budget sets rather than holding
// one drawing for as long as the player stands still.
const IDLE_BREATH_RATE = 7.5;

function fighterPoseDescriptor(fighter) {
  const base = (frame) => ({ bank: "base", frame });
  // v3.0 UNIFIED: `uni(cell, pose)` puts the unified drawing ON TOP of the
  // exact 2.9 descriptor for that beat. It is a pure descriptor edit — the
  // per-fighter ALL-SIXTEEN-OR-NOTHING gate lives in unifiedCellDrawable, so
  // for the two fighters not on the bank every one of these calls resolves
  // straight through to `pose` and the read is byte-identical to 2.9.
  //
  // v3.0 critic round (RULE 2): the bank owns CONNECTED REGIONS, not every
  // beat it has a drawing for. Routed below, and nowhere else:
  //
  //   GROUNDED NEUTRAL  idle (the breathing cycle and every tail that hands
  //                     back to it), the four walk keys (walkCyclePose),
  //                     crouch, crouch-transition (enter, leave and the
  //                     landing gather), guard (the stance, blockstun's
  //                     recovery, the throw-tech and both attack tails).
  //   REACTIONS         light-hit (the flat recoil, the clinch flinch and the
  //                     reaction snap), big-hit (the heavy opener and the
  //                     launched victim), stagger (the reaction fold and the
  //                     storm writhe), knockdown.
  //
  // RETIRED from routing and drawn by nobody: jump-rise, jump-tuck, punch-
  // extension, kick-extension. Each sat inside a motion chain and was cutting
  // it; see UNIFIED_RETIRED_CELLS in engine/fighter-kits.mjs for the measured
  // boundaries. The art stays on the sheet and inside the 16/16 accept gate.
  const uni = (cell, pose) => unifiedPose(cell, pose);
  // v4.0 — THE EXT SHEET. `ext` is this fighter's ONE capability answer, read
  // once per pose so every beat below agrees about which key arrays to use.
  // A fighter whose ext sheet is not whole or not yet decoded takes `false`
  // through every branch, which is the byte-identical 3.5 read (the five 3.0
  // holdouts shipped that way until 4.1 / 5.2 put the whole roster on it).
  const ext = unifiedFighterExtReady(fighter.def.id);
  // v5.2 LOCOMOTION (ext5-air): `air` rides the same object. A fighter with
  // no ext sheet but the ext5 air cells (deathblow, post, donald, the devil)
  // takes AIR, so his plain arc un-retires the unified rise and tuck ahead
  // of the ext5 apex, descent and recover — one family, takeoff to touchdown.
  const air = unifiedFighterAirReady(fighter.def.id);
  const extOpt = ext
    ? (unifiedFighterExtDescendReady(fighter.def.id)
      ? (air ? EXTENDED_DESCEND_AIR : EXTENDED_DESCEND)
      : (air ? EXTENDED_AIR : EXTENDED))
    : (air ? AIR : undefined);
  // v4.9 IN-BETWEENS: the third capability answer. `beatOpt` carries the ext
  // answer and adds `inbetween` when this fighter's ext2 sheet is whole, so
  // the strike tracks (light cock, heavy load, recovery, throw reach/release)
  // pick up his own drawings; without the sheet every track is byte-identical.
  const ext2 = unifiedFighterExt2Ready(fighter.def.id);
  const beatOpt = ext2 ? Object.freeze({ ...(extOpt || {}), inbetween: true }) : extOpt;
  // The BREATHING IDLE, and the only place a unified fighter's idle comes from.
  // 3.0 collapsed the idle to ONE drawing on purpose — the base bank's
  // four-cell breathing cycle is 9.5-22.5 dE of costume away from the unified
  // walk keys, so cycling base cells under a unified walk IS the strobe — and
  // recorded the cost as real and accepted. The ext sheet's cell 16 is that
  // cost being paid back: the same stance one breath later, from the same
  // generation, so the idle breathes on TWO drawings with no costume delta at
  // all. It alternates every 8 ticks, which is exactly MOTION_HOLD_BUDGET.
  // `fallback` is the caller's own pre-4.0 base read, passed in rather than
  // rebuilt here: the neutral idle and the three tails that hand back to it do
  // NOT share one base fallback (the neutral read cycles raw cells 0-3, the
  // tails cycle the semantic map's `roles.idle`), and collapsing them would
  // change what an unsheeted fighter draws.
  const breathingIdle = (fallback) => {
    const held = uni(UNIFIED_CELLS.idle, fallback);
    if (!ext) return held;
    return Math.floor(fighter.animTime * IDLE_BREATH_RATE) % 2 === 1
      ? unifiedExtPose(UNIFIED_EXT_CELLS.idleBreathe, held)
      : held;
  };
  const rolesIdle = () => base(roles.idle[Math.floor(fighter.animTime * 5) % roles.idle.length]);
  // v2.9 critic round: every beat below that used to hand off to a hardcoded
  // base index now resolves through the per-fighter semantic map — base(12)
  // is a deep squat and base(13) an attack pose (or, on deathblow, a whole
  // different costume) on most of the roster. See BASE_CELL_ROLES.
  const roles = baseCellRoles(fighter.def.id);
  // v5.2 LOCOMOTION (bookends): a Final Blow draws the script's own
  // same-generation cell over the base index the sim stores here.
  if (fighter.cinematicFrame !== null) return cinematicPoseDescriptor(fighter, base(fighter.cinematicFrame));
  // v2.9 critic round (B4): the airborne `thrown` cell is gated to the actual
  // LIFT window. It was applied from grab frame 0, which snapped the victim
  // ~80 degrees from standing idle to flat-on-his-back in ONE tick and then
  // floated him horizontally at hip height for the hitstop ticks with his
  // feet nominally on the floor. During the clinch the victim now wears the
  // authored standing flinch, so attacker (throw-grab, seizing at chest
  // height) and victim agree in space; the loose-limbed hurl key takes over
  // once the throw has genuinely lifted him off the floor and the cinematic
  // rotation is engaged.
  if (fighter.grabbed) {
    // v2.9 critic round 2 (B7): the two halves of a throw must occupy the SAME
    // SPACE. Round 1 moved the gate off "grab frame 0" and onto "18px of
    // lift", which is not a hurl — it is a fighter still standing on the
    // attacker's shins. Measured: the victim wore motion2:11 (a fully
    // horizontal airborne body) while 16-30px off the floor, drawn at the
    // attacker's knee height and intersecting his legs, while the attacker's
    // two-handed seize reached into empty air above him.
    //
    // The horizontal key is now gated on an ACTUAL AIRBORNE HURL: clear of the
    // attacker's own standing height, or genuinely committed to the cinematic
    // rotation. Through the clinch the victim keeps the authored standing
    // flinch, which is drawn at chest height where the grab actually is.
    const lifted = FLOOR - fighter.y;
    const hurling = !fighter.grounded
      && (lifted > THROW_HURL_LIFT_PX || Math.abs(fighter.cinematicRotation) > 0.55);
    return hurling
      ? motion2Pose(MOTION2_CELLS.thrown, "base", roles.hit)
      : uni(UNIFIED_CELLS.lightHit, motion2Pose(MOTION2_CELLS.lightHit, "base", roles.hit));
  }
  // v2.9 FLOW: the throw attacker wears the authored two-handed seize through
  // the grab hold; the fallback is exactly what the kit's throw art showed.
  if (fighter.grabbing) {
    // v2.9 critic round 2 (B1): the CLINCH. The authored two-handed seize was
    // held for 21 straight ticks — the grab froze mid-air while the victim
    // animated underneath it. The kit's own throw art brackets it now: kit
    // seize, the authored hold, then the kit lift, so the clinch has a
    // beginning, a middle and an end on cells that all ship today.
    //
    // Paced by the GRAB's own counter, not attackFrame: attackFrame is frozen
    // for the whole hold, which is exactly why one drawing owned all of it.
    const kitPose = fighter.attacking
      ? attackAnimationPose(fighter.attacking, fighter.attackFrame, beatOpt) : null;
    // v2.9 final round: the kit-less fallback was the HARDCODED index 8 — the
    // last raw base index left in this file after the semantic map landed.
    // base:8 is deathblow's GUARD cell, so his throw drew the same stance
    // twice fifteen ticks apart with the hurl in between; it is a braced wide
    // stance on ali and a STRIKE on four of the roster, which is exactly the
    // class of assumption BASE_CELL_ROLES exists to kill. The map's own guard
    // read is what this branch always meant — a two-handed seize is the
    // fighter squared up and set — and it is certified non-attack per fighter.
    const fallback = kitPose && !isAuthoredBank(kitPose.bank)
      ? { bank: kitPose.bank, frame: kitPose.frame }
      : uni(UNIFIED_CELLS.guard, { bank: "base", frame: roles.guard });
    const hold = fighter.grabbing;
    const clinch = clamp((hold.frame || 0) / Math.max(1, hold.total || 1), 0, 0.999);
    return beatPoseAt(throwClinchKeys(beatOpt), clinch, fallback);
  }
  if (fighter.dizzyFrames > 0 || fighter.guardCrushFrames > 0) {
    // v2.9 critic round (B5): a REAL woozy loop. The 2.9 read alternated the
    // authored rubber-legs key with base(13) every ~10 ticks, which meant
    // benny threw a HIGH KICK every other beat while dizzy (and ali swung the
    // mic, and deathblow changed trousers). The authored sway now owns the
    // whole state and the procedural dizzy wobble in fighterMotionTransform
    // — lateral drift + rotation, amplitude collapsing with the drain bar —
    // supplies the motion the second cell was faking. The fallback is the
    // map's stagger read, never an attack cell.
    return motion2Pose(MOTION2_CELLS.dizzy, "base",
      Number.isInteger(roles.stagger) ? roles.stagger : roles.hit);
  }
  // Release 1.7: air-recovery back-flip tuck. v2.7 FRAMES: the spin window
  // wears the authored tuck ball, the tail arches into the airrec footing key.
  if (fighter.airTechFlipFrames > 0) {
    const flip = 1 - fighter.airTechFlipFrames / AIR_RECOVERY_RULES.flipFrames;
    // v3.0 critic round (RULE 2): tuck -> air-recovery is a two-cell motion
    // chain. Routing the unified tuck into it put a 8.18 dE mean crossing
    // between them (7.56 on deathblow) to remove none; retired, it is
    // crossing-free.
    // v5.2 LOCOMOTION (ext5-air): the substitution table draws this pair as
    // the ext5 apex tuck (the ball) and the ext5 air recover (the tail) on a
    // fighter with the sheet — both motion cells are accepted on all ten, so
    // the table always sees them and the chain below needs no ext5 descriptor.
    return flip < 0.6
      ? motionPose(MOTION_CELLS.tuck, "base", 13)
      : motionPose(MOTION_CELLS.airrec, "base", 13);
  }
  // Release 1.7 wave 11: the taunt holds the fighter's victory pose frame
  // (v2.7: rotated with the motion alternates).
  if (fighter.tauntFrames > 0 && fighter.kit?.victory) {
    return showcasePoseDescriptor(fighter, UNIFIED_EXT5_CELLS.taunt);
  }
  // v2.7 FRAMES: signature intro stance — each side holds its own manifest
  // signature cell through the walk-on, releasing to idle before FIGHT!.
  const entrance = state.phase === "intro" ? introEntranceCell(state.phaseTime) : null;
  if (entrance !== null && fighter.grounded && !fighter.attacking && fighter.kit?.victory) {
    const cell = (((state.matchSeed >>> 0) + fighter.side) % 2) ? MOTION_CELLS.sig2 : MOTION_CELLS.sig1;
    // v5.2 LOCOMOTION (bookends): the walk-on is TWO beats from the fighter's
    // own sheet — entrance A (ext5:9) for the first half, entrance B (ext5:10)
    // for the second, on both fighters — then the unified idle for the 0.95 s
    // before FIGHT! (engine/bookends). The motion signature the seed-and-side
    // pick chose rides under both beats, so a held ext5 sheet reads as before.
    return unifiedExt5Pose(entrance, motionPose(cell, "base", Math.floor(fighter.animTime * 5) % 4));
  }
  // v2.7 FRAMES: round-win pose under the curtain-call spotlight — the winner
  // holds the showcase rotation (same convention the camera settle uses to
  // pick its subject).
  if (state.phase === "roundover" && !state.finisher && state.finisherType < 0
    && state.fighters?.length === 2 && fighter.kit?.victory
    && fighter.grounded && !fighter.down && !fighter.attacking
    && fighter.hitstunFrames === 0 && fighter.knockdownFrames === 0) {
    const other = state.fighters[1 - fighter.side];
    const winner = fighter.side === 0 ? fighter.health >= other.health : fighter.health > other.health;
    // v5.2 LOCOMOTION (bookends): the victory through the "<name> WINS" call,
    // then the taunt as the second beat on the picks that were the rotation's
    // own second drawings (engine/bookends roundWinShowcaseCell).
    if (winner) {
      const hold = roundWinHoldSeconds();
      return showcasePoseDescriptor(fighter, roundWinShowcaseCell(showcasePick(), hold - state.phaseTime, hold));
    }
  }
  // MOTION FIX 4 + 11: victim REACTION TRACKS through the scripted super
  // storms — a pure function of both fighters' snapshotted sim state, so it
  // replays identically under rollback and feeds both renderers. Instead of
  // pinning the single hit cell for the whole storm: the Commissioner's
  // FINAL AUTHORITY walks flinch → staggered recoil → bound slump, and the
  // Devil's BARRENS CURSE walks impact recoil → sagging writhe, all from
  // existing hit (15) / dizzy (12,13) atlas cells.
  if (fighter.hitstunFrames > 0 && !fighter.down && fighter.knockdownFrames === 0
    && fighter.cinematicFrame === null && state.fighters?.length === 2) {
    const stormCaster = state.fighters[1 - fighter.side];
    const storm = stormCaster?.attacking?.superMove ? stormCaster.attacking : null;
    if (storm && stormCaster.attackFrame >= storm.activeStartFrame
      && (stormCaster.def.vfx === "authority" || stormCaster.def.vfx === "barrens")) {
      const span = Math.max(1, storm.activeEndFrame - storm.activeStartFrame);
      const phase = clamp((stormCaster.attackFrame - storm.activeStartFrame) / span, 0, 1);
      // BODY-FIRST: the storm tracks advance one key PER LANDED HIT — the
      // combo tracker is sim state, so each seal/curse tick visibly knocks
      // the victim into the next pose (tick cadence stays as a backstop).
      const hitBeat = ((stormCaster.combo?.hits || 0) + Math.floor(stormCaster.attackFrame / 9)) % 2;
      // v2.9 critic round: these VICTIM tracks were written against the same
      // assumed grammar as the reaction track (base 12 "slumped", base 13
      // "staggered recoil") and are wrong on the same nine fighters — the
      // Commissioner's seal made benny high-kick between binds. Both tracks
      // now key off the map's certified non-attack recoil cells and the
      // authored bank; the beat shapes are unchanged.
      const writhe = Number.isInteger(roles.stagger) ? roles.stagger : roles.hit;
      if (stormCaster.def.vfx === "authority") {
        // v3.0: the two alternating bands are the SAME unified drawing (the
        // authored light-hit and the map's flat recoil collapse onto cell 12),
        // so the per-hit alternation would freeze. The off-beat takes the
        // unified STAGGER instead — which is what "staggered recoil" says —
        // and both bands keep their exact 2.9 cell underneath.
        if (phase < 0.25) return uni(UNIFIED_CELLS.lightHit, base(roles.hit));    // flinch at onset
        if (phase < 0.72) {                                                       // per-hit staggered recoil
          return hitBeat
            ? uni(UNIFIED_CELLS.stagger, motion2Pose(MOTION2_CELLS.lightHit, "base", writhe))
            : uni(UNIFIED_CELLS.lightHit, base(roles.hit));
        }
        return motion2Pose(MOTION2_CELLS.dizzy, "base", roles.crouch);            // bound / slumped at the bind
      }
      if (phase < 0.4) return uni(UNIFIED_CELLS.lightHit, base(roles.hit));       // curse impact recoil
      return hitBeat                                                              // per-hit sagging writhe
        ? motion2Pose(MOTION2_CELLS.dizzy, "base", roles.crouch)
        : uni(UNIFIED_CELLS.stagger, motion2Pose(MOTION2_CELLS.lightHit, "base", writhe));
    }
  }
  // v2.7 FRAMES: slammed victims — wall pin, launch arc, knockdown collapse.
  // All pure snapshotted sim reads: the clamp pins x exactly at the arena
  // bound while a slammed fighter is in flight (or still carrying slam-grade
  // push into the wall — the same 220 threshold the wave-4 splat spawn uses,
  // so light corner pokes never wear it), the ballistic sign splits launch
  // (bighit) from the juggle fall (airrec), and the last ~120px of a
  // knockdown fall wear the crumple key before the flat slam.
  if (fighter.hitstunFrames > 0 || fighter.pendingKnockdown) {
    if (fighterWallPin(fighter)) return motionPose(MOTION_CELLS.wallsplat, "base", roles.down);
    if (!fighter.grounded) {
      // 2.7 critic round: the crumple (knees buckling) engages only in the
      // last ~55px of the fall — the old 120px band had victims kneeling on
      // air for a dozen frames before touchdown.
      if (fighter.pendingKnockdown && fighter.vy > 0 && FLOOR - fighter.y < 55) {
        return motionPose(MOTION_CELLS.crumple, "base", roles.down);
      }
      // v2.9 FLOW: a hurled throw victim keeps the loose-limbed thrown key
      // through the rising arc of the hurl, before the launched-victim reads
      // (bighit/airrec/crumple) take over on the way down.
      if (fighter.lastHitResult === ATTACK_LEVELS.THROW && fighter.vy < 0) {
        return motion2Pose(MOTION2_CELLS.thrown, "base", roles.down);
      }
      return fighter.vy < -120
        ? uni(UNIFIED_CELLS.bigHit, motionPose(MOTION_CELLS.bighit, "base", roles.down))
        : motionPose(MOTION_CELLS.airrec, "base", roles.down);
    }
  }
  if (fighter.down || fighter.knockdownFrames > 0) {
    // The first beats of the knockdown keep the mid-collapse key (ext4:9
    // through the substitution). v5.3 SPECTACLE (ko-collapse): the band
    // length is KO_COLLAPSE_CRUMPLE_TICKS now — the same 7 it has always
    // been, named so the collapse's landing beat (the thud and the dust,
    // spent on the tick this band hands over) and this drawing read ONE
    // number and cannot drift apart.
    if (fighter.down && fighter.knockdownFrames > DEFENSE_RULES.knockdownFrames - KO_COLLAPSE_CRUMPLE_TICKS) {
      return motionPose(MOTION_CELLS.crumple, "base", roles.down);
    }
    // The KO lie: on a decided round against a fighter at 0 health the
    // resolver's `ko` context turns this rung into ext4:15 (swingSubstitute),
    // which is the drawing 5.0 paid for and nothing had ever reached.
    return uni(UNIFIED_CELLS.knockdown, base(roles.down));
  }
  // v2.6 BODY-FIRST (core 2): EVERY hit sequences the victim through a
  // progressive stagger — head-snap -> torso fold -> stagger step -> recover
  // ease — clocked by ticks since the opponent's combo tracker registered the
  // impact (sim state that keeps counting through hitstop), so multi-hit
  // moves restart the track on every hit, rollback replays it identically,
  // and both renderers consume the same keys. The rotation/backstep
  // transforms riding these keys live in fighterMotionTransform; the
  // authored super-storm tracks above stay the strongest versions. Airborne
  // victims keep the flying hit cell (the juggle read).
  if (fighter.hitstunFrames > 0 && fighter.grounded && fighter.knockdownFrames === 0
    && fighter.cinematicFrame === null && state.fighters?.length === 2) {
    const striker = state.fighters[1 - fighter.side];
    const sinceHit = state.simulationTick - (striker?.combo?.lastHitFrame ?? -Infinity);
    if (sinceHit >= 0 && sinceHit <= 44) {
      // v2.9 final round (R4): the per-hit alternation is gone. It selected
      // between `roles.hit` and `fold`, which are the same frame on seven of
      // ten fighters, so it alternated a cell with itself. Multi-hit moves
      // re-key the whole track on every landed hit (sinceHit resets), which is
      // the real re-key and is untouched.
      // v2.7 FRAMES: a landed heavy/special opens the reaction on the
      // authored big-hit key (body bent backward) instead of the flat hit
      // cell; lights keep the tighter head snap.
      // v2.9 critic round (B5): the WHOLE reaction track is authored or
      // map-resolved. It used to hand off to base(hitKey ? 13 : 12) and then
      // base(hitKey ? 15 : 13) — base(13) is an ATTACK POSE on nine of ten
      // fighters (benny high-kicks, ali swings the mic, the devil launches an
      // airborne claw lunge) and a costume swap on deathblow, while base(12)
      // is a deep squat that dropped the victim mid-stagger. Every beat below
      // is either an authored key or a cell the map certifies as non-attack;
      // the per-hit alternation that made multi-hit moves re-key is kept.
      // v2.9 critic round 2 (B1/M5): the track is a KEY LIST now. Round 1 kept
      // the light-vs-heavy opening weight the critics praised but converged
      // the two tracks four ticks in — the heavy dropped out of the big-hit
      // bend straight into motion2:9, the SAME cell the light track was
      // already wearing, with a 60-70 degree torso jump and no in-between —
      // and then BOTH tracks pinned one base cell for 6-7 ticks and the guard
      // cell for a dozen more.
      //
      // The opening weights are untouched. The MIDDLES are now different
      // drawings: the heavy sags through the authored rubber-legs key before
      // it reaches the head-jolt, the light folds through the authored guard
      // flinch. The tail hands back to the IDLE CYCLE rather than freezing on
      // the guard cell, so the last third of a long reaction breathes.
      // motion3's react-mid pair drops into the second band of each track.
      const heavyTrack = Boolean(striker.attacking && striker.attacking.kind !== "light");
      // v2.9 final round (R4) — THE TAIL COLLAPSE. Round 2's ladder read
      // `base(hitKey ? roles.hit : fold)` at 0.30 and `base(fold)` at 0.44,
      // and `fold` IS `roles.hit` on seven of ten fighters (only deathblow,
      // the commissioner and cyraxx have a distinct stagger cell). Those two
      // bands were therefore the SAME DRAWING held for ~12-13 ticks at the end
      // of every ground reaction, and the per-hit `hitKey` alternation that
      // was supposed to break it could only alternate between a cell and
      // itself. The band edges and the cells they resolve to now come from
      // ONE table in fighter-kits.mjs (reactionFallbackCells), which
      // guarantees consecutive bands are different frames and drops the
      // third band entirely rather than repeat one when the sheet cannot
      // supply three distinct non-attack drawings.
      const tail = reactionFallbackCells(roles);
      // v3.0 critic round (M1): the unified rung for a band comes from
      // unifiedReactionLadder — the SAME table reactionTrackKeys stacks onto
      // its chains — so the track and this fallback cannot drift out of step.
      // The first 3.0 cut had them a band apart, which is what made the light
      // reaction play stagger -> rubber-legs -> STAGGER AGAIN for 6-8 ticks.
      // The BASE read below is untouched 2.9: snap / fold / settle-or-idle /
      // idle over the same band groups, so a non-unified fighter is
      // byte-identical.
      return beatPoseAt(reactionTrackKeys(heavyTrack, extOpt), sinceHit / 44, (key) => {
        const at = key ? key.at : 0;
        const idle = () => rolesIdle();
        const rung = unifiedReactionCellAt(at, heavyTrack, extOpt);
        // v4.0: a rung is a GRAMMAR cell now (0-23), so `unifiedRungPose`
        // dispatches it to the main or the ext bank. `unifiedReactionCellAt`
        // and `reactionTrackKeys` are handed the same `extOpt`, so the track
        // and this fallback still read one table and cannot drift a band apart
        // — which is the M1 bug, and the reason the rung comes from a table at
        // all rather than being written out twice.
        if (at < REACTION_BANDS[2]) return unifiedRungPose(rung, base(tail.snap));
        if (at < REACTION_BANDS[4]) return unifiedRungPose(rung, base(tail.fold));
        if (at < REACTION_BANDS[5]) {
          return unifiedRungPose(rung, tail.settle !== null ? base(tail.settle) : idle());
        }
        return unifiedRungPose(rung, idle());
      });
    }
    return uni(UNIFIED_CELLS.lightHit, base(roles.hit));
  }
  // v2.9 FLOW: standing guarded contact wears the authored guard-flinch key
  // for the WHOLE blockstun window — checked before the hit-flash read below
  // so the flash ticks of a blocked contact flinch instead of borrowing the
  // clean-hit cell (crouch blockstun keeps the crouch guard cell — the
  // flinch is a standing pose). The fallback tracks the exact pre-2.9 read:
  // the hit cell while the contact flash decays, then the guard cell.
  // v2.9 critic round (B5): the flinch and the guard it returns to are now
  // the SAME STANCE HEIGHT. Standing guard used to draw base(12), a deep
  // squat on ali / benny / deathblow / donald / post, so a blocked hit
  // (block-hit is a standing flinch) made them stand UP ~80px INTO the punch
  // and drop back down after. Both reads resolve through the map's `guard`.
  // v5.3 (sweep #52): the ORDER of the four contact branches — standing
  // blockstun, crouch blockstun, the flash on a guard, the flash on a hit —
  // is engine/pose-precedence.mjs, asserted exhaustively over the snapshot
  // space instead of pinned by a regex over the shape of this ladder. The
  // DRAWINGS stay here, one per branch.
  const contact = contactPoseBranch(fighter);
  if (contact === POSE_BRANCHES.blockstunStanding) {
    // v2.9 critic round 2 (B1/M4): the flinch owned all 17 ticks of blockstun.
    // It now owns the IMPACT and the stance recovers behind it, which is what
    // blockstun actually looks like — and it is the drawing whose 15% height
    // mismatch with the guard cell the guard-flinch scale correction fixes, so
    // the shorter it is held the smaller that seam is. The fallbacks track the
    // exact pre-fix read: the hit cell while the contact flash decays, then
    // the guard cell.
    //
    // The flinch key owns the impact now, so the fallback is the STANCE for
    // the whole window — round 1's read borrowed the clean-hit cell while the
    // contact flash decayed, which put a 2-tick hit pose in the middle of a
    // block once the flinch stopped owning the whole thing.
    return beatPoseAt(blockstunKeys(), blockstunPhase(fighter.blockstunFrames, motionObs[fighter.side]?.blockstunTotal),
      uni(UNIFIED_CELLS.guard, base(roles.guard)));
  }
  // v5.1 EXT4 ROUTING — CROUCH BLOCKSTUN. The branch above is gated on
  // `!crouch` because the authored flinch is a standing cover, and the crouch
  // stance branch below then held unified:5 through the whole window: a
  // low-blocked heavy produced no pose change at all. The ext3 crouch guard
  // (forearms crossed, still crouched) owns the impact band now, paced by the
  // same observer clock; the recovery bands are empty and resolve to the
  // crouch read the stance branch draws, so a fighter without the cell is
  // byte-identical and the flinch hands back to exactly the drawing it left.
  // v5.2 LOCOMOTION: with the fighter's ext5 crouch guard flinch drawable
  // (`flinch`, the capability answer for this track) the impact band opens
  // on it and the crouch guard takes the settle — an impact and a settle,
  // like the standing block. ali's flinch is held, so he reads the 5.1 track.
  if (contact === POSE_BRANCHES.blockstunCrouch) {
    const flinch = swingCellDrawable(fighter.def.id, UNIFIED_EXT5_CELLS.crouchGuardFlinch, UNIFIED_EXT5_BANK);
    return beatPoseAt(crouchBlockstunKeys({ flinch }),
      blockstunPhase(fighter.blockstunFrames, motionObs[fighter.side]?.blockstunTotal),
      uni(UNIFIED_CELLS.crouch, base(roles.crouch)));
  }
  // v5.1: a BLOCKED contact's flash keeps the stance. The flash outlives a
  // jab's 4-tick blockstun, and this read used to borrow the clean-hit cell
  // for the flash's remaining ticks — a 4-tick hit read on a block (measured:
  // unified:12 / ext4:1 at ticks 63-66 after a blocked jab, blockstun 0,
  // guarding). No hitstun and a guard up is a block, not a hit.
  if (contact === POSE_BRANCHES.flashGuardCrouch) return uni(UNIFIED_CELLS.crouch, base(roles.crouch));
  if (contact === POSE_BRANCHES.flashGuardStand) return uni(UNIFIED_CELLS.guard, base(roles.guard));
  if (contact === POSE_BRANCHES.flashHit) return uni(UNIFIED_CELLS.lightHit, base(roles.hit));
  // v2.9 FLOW: sequenced wake-up — getup-a (knee up, hand pushing off) into
  // getup-b (half-risen crouch) across the recovery countdown, ending the
  // teleport-to-feet. Pure helper in fighter-kits.mjs; fallbacks exact.
  if (fighter.wakeupFrames > 0) {
    // v2.9 critic round 2 (M3): the rise END was fixed in round 1 and the
    // START then hard-cut — base:15 (flat on his back, a horizontal body)
    // straight to motion2:14 (kneeling, hand on the floor) in ONE tick, about
    // 90 degrees of torso rotation and ~150px of head rise with nothing in
    // between. The track opens on the authored crumple key (the collapse pose,
    // which is exactly the missing in-between played backwards) and the rise
    // transform opens with a matching pitch. Passing the real countdown length
    // keeps the bands honest instead of assuming 16.
    return wakeupMotionPose(fighter.wakeupFrames, roles, DEFENSE_RULES.wakeupFrames);
  }
  if (fighter.throwTechFlashFrames > 0) return uni(UNIFIED_CELLS.guard, base(roles.guard));
  // v2.9 critic round 2 — TURNAROUND PRECEDENCE. Measured across ~2800 fight
  // ticks, the authored pivot key drew for 0-1 ticks TOTAL: it sat below the
  // guard/crouch and attack branches, and a grounded facing flip essentially
  // only happens in exactly those states. Pushbox separation forbids ground
  // crossings, so a cross-up is almost always a jump — and the fighter who
  // actually flips is the DEFENDER, who is holding guard or crouching when it
  // resolves. The key existed and never once reached the screen.
  //
  // The 3-tick latch now outranks guard, crouch and the crouch-entry
  // in-between. It deliberately stays BELOW hitstun, blockstun, knockdown,
  // wake-up, grabs and dizzy: being hit outranks turning around. The fallback
  // is the exact cell the guard/crouch branch below would have drawn, so a
  // missing sheet changes nothing.
  const turnObs = motionObs[fighter.side];
  if (turnObs?.turnFrames > 0 && fighter.grounded && !fighter.attacking) {
    // v5.2 LOCOMOTION: the pivot is the fighter's own (ext5:3, a mid-turn
    // body seen from behind) over the exact 2.9 chain, so the three latch
    // ticks sit between two unified rungs on one sheet family instead of
    // dropping to the motion2 generation for the turn.
    return unifiedExt5Pose(UNIFIED_EXT5_CELLS.turnaround, motion2Pose(MOTION2_CELLS.turnaround, "base",
      fighter.crouch ? roles.crouch
        : fighter.block ? roles.guard
          : Math.abs(fighter.vx) > 22
            ? 4 + Math.floor(fighter.walkTime * 10) % 4
            : Math.floor(fighter.animTime * 5) % 4));
  }
  // v2.9 FLOW: 2-3 ticks of the authored half-lowered in-between entering
  // crouch (the leave side lives past the movement branches below). The
  // latch is render-only observer state — never advanced during rollback
  // resimulation (updateMotionObservers runs only in draw()).
  if (fighter.crouch && !fighter.block
    && motionObs[fighter.side]?.crouchTransFrames > 0) {
    return uni(UNIFIED_CELLS.crouchTrans, motion2Pose(MOTION2_CELLS.crouchTrans, "base", roles.crouch));
  }
  // v2.9 critic round (B5): crouching keeps the low stance; STANDING guard
  // gets the map's braced standing cell instead of borrowing the crouch.
  //
  // v3.5 BACK-WALK — THE OWNER'S "NOBODY WALKS BACKWARDS, THEY SLIDE". This
  // branch used to read `if (block || blockstun || crouch)` and it sat ABOVE
  // the locomotion branch, so on a game with SF2 directional guarding — where
  // holding away sets `block` on every single tick — a RETREAT could never
  // reach the walk cycle. Every fighter on the roster drew one frozen
  // unified:7 while his x slid, on all ten sheets, which is exactly the glide
  // that was reported. `groundedStanceBeat` is the whole decision, and it is
  // in engine/fighter-kits.mjs so the tests and both renderers share it: the
  // stance still owns blockstun, crouch-guard and a STANDING hold, and a
  // fighter who is genuinely moving falls through to the walk cycle below.
  // See that function for the guard-state judgement call in full.
  const stance = groundedStanceBeat({
    block: fighter.block,
    blockstunFrames: fighter.blockstunFrames,
    crouch: fighter.crouch,
    grounded: fighter.grounded,
    vx: fighter.vx,
    dashExiting: turnObs?.dashExitFrames > 0,
  });
  if (stance === "crouch") return uni(UNIFIED_CELLS.crouch, base(roles.crouch));
  if (stance === "guard") return uni(UNIFIED_CELLS.guard, base(roles.guard));
  // stance === "walk" deliberately falls through. `block` is only ever set on
  // a grounded, non-attacking, non-dashing tick, so the branches between here
  // and the locomotion branch cannot claim it — except the crouch-LEAVE
  // in-between, which is the correct drawing for standing up out of a
  // crouch-guard and lasts two ticks.
  if (fighter.attacking) {
    const attack = fighter.attacking;
    const kitPose = attackAnimationPose(attack, fighter.attackFrame, beatOpt);
    // v2.9 critic round 2 (B1): the throw ATTACKER's recovery. Measured 31
    // ticks (round 1) then 25 frozen on the kit's release cell, because BOTH
    // attackFrame and attackTime stop advancing through a throw's cinematic —
    // so nothing inside the attack timeline could pace it. The render observer
    // clocks it instead: release -> follow-through -> stance -> the authored
    // motion3 recovery key. The fallback is the kit cell, exactly as before.
    const throwRecover = motionObs[fighter.side]?.throwRecoverFrames ?? -1;
    if (attack.kind === "throw" && throwRecover >= 0 && kitPose) {
      return beatPoseAt(throwRecoveryKeys(beatOpt),
        clamp(throwRecover / THROW_RECOVERY_RENDER_TICKS, 0, 0.999),
        // v2.9 final round (R7): three tiers, not two. The old split put the
        // kit cell under every band below 0.74, so the track's two empty
        // bands both resolved to it and the follow-through key sat BETWEEN
        // two stretches of one drawing — the rewind hitch. Bands now land on
        // the kit release, the stance, and the breathing idle in that order.
        (key) => (!key || key.at < 0.26
          ? { bank: kitPose.bank, frame: kitPose.frame }
          : key.at < 0.78 ? uni(UNIFIED_CELLS.guard, base(roles.guard))
            : breathingIdle(rolesIdle())));
    }
    if (kitPose) {
      // BODY-FIRST (spec 10): the Commissioner's storm is ONE full cane-swing
      // arc — the cane RAISES (windup cell), strikes through both active
      // cells and carries into the follow-through cell across the 40-frame
      // window — instead of the old two-cell toggle. The per-hit extension
      // pulse in fighterMotionTransform re-lunges the swing on every landed
      // seal, so the arc reads as driving the multi-hits.
      if (attack.superMove && fighter.def.vfx === "authority"
        && fighter.attackFrame >= attack.activeStartFrame
        && fighter.attackFrame < attack.activeEndFrame
        && attack.animation?.frames?.length === 4) {
        const span = Math.max(1, attack.activeEndFrame - attack.activeStartFrame);
        const phase = (fighter.attackFrame - attack.activeStartFrame) / span;
        const index = phase < 0.22 ? 0 : phase < 0.52 ? 1 : phase < 0.82 ? 2 : 3;
        return { bank: attack.animation.bank, frame: attack.animation.frames[index] };
      }
      return kitPose;
    }
    const startup = attack.active[0];
    const activeEnd = attack.active[1];
    const time = fighter.attackTime;
    const frames = attack.kind === "light" ? [8, 9, 10, 11]
      : attack.kind === "heavy" ? [8, 13, 13, 11]
        : [8, 13, 14, 11];
    // v2.7 FRAMES: authored smear / full-extension / follow-through keys ride
    // the kit-less normals timeline, each falling back to the exact base cell
    // this path showed before.
    const beat = attackMotionBeat(attack, fighter.attackFrame, beatOpt);
    // v2.9 FLOW: the authored anticipation key re-skins the late startup
    // ticks (windup → smear → extension → follow reads as one swing), and
    // air normals wear the authored jumping-strike key through their active
    // window instead of the borrowed ground punch cells.
    // v2.9 critic round 2 (B1): both of those beats used to be ONE cell for
    // their whole window — 17 ticks on deathblow's heavy-kick chamber, 30 on
    // an air normal. They carry key tracks now; the fallback per band is the
    // exact base cell this path showed before, and the bare-hand gate in
    // resolveMotionPose keeps a prop out of every one of them.
    if (beat?.beat === "windup") {
      return beatPoseAt(beat.keys, beat.phase, { bank: "base", frame: frames[1] });
    }
    // v4.9 IN-BETWEENS: a light's anticipation (and a crouching heavy's) on
    // the fighter's own cocked limb. The fallback is the exact pre-4.9 startup
    // read — base 8 for the first 48% of the startup, then base 9.
    if (beat?.beat === "cock") {
      return beatPoseAt(beat.keys, beat.phase, () => base(time < startup * 0.48 ? frames[0] : frames[1]));
    }
    // v2.9 final round (T3): the heavy KICK's arc bridge. The two ticks the
    // punch spends on its smear flash are spent here HOLDING THE CHAMBER cell
    // while fighterMotionTransform rotates the body back onto the support leg
    // along the arc the kick is about to travel — there is no leg smear
    // anywhere in the four banks, so the in-between has to be a transform, and
    // the drawing under it must be the chamber rather than the generic base
    // strike cell the un-handled beat used to fall through to.
    // v5.2: the arc CONTINUES the compress band's drawing, so it degrades the
    // same way that band does — through the fighter's own crouch transition
    // before the base cell. The devil is the one fighter whose motion2:4 is
    // rejected (an all-fours prowl), and base 13 is his AIRBORNE claw lunge:
    // two ticks of it played between his compress and his kick on every
    // heavy kick until his ext sheet put the unified read under it.
    if (beat?.beat === "kickArc") {
      const arc = motion2Pose(beat.cell, "base", frames[1]);
      return ext ? { ...arc, fallback: uni(UNIFIED_CELLS.crouchTrans, arc.fallback) } : arc;
    }
    if (beat?.beat === "airAttack") {
      return beatPoseAt(beat.keys, beat.phase, (key) => ({
        bank: "base",
        frame: !key || key.at <= 0 ? frames[1] : key.at < 0.9 ? frames[2] : frames[3],
      }));
    }
    // v2.9 critic round 2 (B1): the RECOVERY. Round 1 sequenced the startup
    // and the active window and left `return base(frames[3])` to own the whole
    // recovery — measured 20 ticks on deathblow's heavy kick, 23 on donald's
    // heavy punch, 22 on the Commissioner's, 17 on ali's, 18 on post's. The
    // per-band fallbacks are the exact cells this path showed before (the
    // recovery cell, then the map's guard, then the breathing idle), so a
    // missing bank still lands byte-for-byte on the pre-fix read.
    if (beat?.beat === "recover") {
      return beatPoseAt(beat.keys, beat.phase, (key) => {
        if (!key || key.at < 0.46) return base(frames[3]);
        if (key.at < 0.66) return uni(UNIFIED_CELLS.guard, base(roles.guard));
        return breathingIdle(rolesIdle());
      });
    }
    if (beat?.beat === "smear") return motionPose(beat.cell, "base", frames[1]);
    if (beat?.beat === "extension") {
      // v3.0 critic round (RULE 2) — THE EXTENSION IS RETIRED FROM THE BANK.
      //
      // The first 3.0 cut routed unified:10/11 here on the reasoning that the
      // bank owns the beat. It does own a DRAWING of it; it does not own the
      // beat's neighbours. The extension sits between the motion smear before
      // it and the motion follow-through after it, and motion/motion2 are one
      // generation (deathblow motion:0 vs motion2:6 measures 2.62 dE), so
      // dropping a unified cell in the middle cut a chain that was already
      // consistent: the swing went 2 generation crossings to 5, and the
      // follow-through boundary 3.87 -> 6.95 dE, into deathblow's 7.29-7.45
      // known-bad strobe band with no flash over it. Off the route it is the
      // 2.9 read exactly — windup -> smear -> extension -> follow, one
      // generation end to end — and the cells stay on the sheet.
      return motionPose(beat.cell, "base", frames[2]);
    }
    if (time < startup * 0.48) return base(frames[0]);
    if (time < startup) return base(frames[1]);
    if (time <= activeEnd) {
      // BODY-FIRST: non-lights three-beat the active window — the recovery
      // cell arrives a third early as the follow-through key, so the active
      // hold never freezes on one cell (kit-less fallback path).
      if (attack.kind !== "light"
        && (time - startup) / Math.max(0.001, activeEnd - startup) >= 0.67) {
        return beat?.beat === "follow"
          ? motionPose(beat.cell, "base", frames[3])
          : base(frames[3]);
      }
      return base(frames[2]);
    }
    return base(frames[3]);
  }
  if (!fighter.grounded) {
    // v2.7 FRAMES: the mid-flip tumbling band wears the authored tuck ball.
    // The band derives from the same pure ballistic-arc progress the flip
    // rotation in fighterMotionTransform maps onto its eased turn, so the
    // ball appears while the sprite is genuinely rotating and unwraps before
    // touchdown. Skipped under reduced motion exactly like the rotation.
    // 2.7 critic round J2: donald's band opens almost immediately — his base
    // ascent cell (13) is the golf swing with a baked golden crescent, which
    // a plain jump was wearing for ~10 ticks before the tuck engaged.
    // v2.9 critic round 2 (B1): the tuck owned the band from 0.22 to 0.82 of
    // the arc — 28 consecutive ticks covering the rise, the APEX and most of
    // the DESCENT on one drawing, the longest hold in the whole build after
    // the air normal. The band is a key TRACK now: rise -> tuck -> [apex] ->
    // [descend] -> air-recovery -> landing gather. Four real body plans today
    // and six once motion3's two jump keys land, with the fallback of every
    // band the exact cell the pre-fix read showed at that instant.
    if (!state.accessibility.reducedMotion && !fighter.attacking
      && fighter.hitstunFrames === 0 && !fighter.pendingKnockdown
      && fighter.dizzyFrames === 0) {
      const launch = fighter.movement.jumpVelocityY || -720;
      const apex = (launch * launch) / (2 * GRAVITY);
      const height = Math.max(0, FLOOR - fighter.y);
      const progress = fighter.vy < 0
        ? 0.5 * (1 - clamp(fighter.vy / launch, 0, 1))
        : 0.5 + 0.5 * clamp(1 - height / Math.max(1, apex), 0, 1);
      const bandStart = fighter.def.id === "donald" ? 0.06 : 0.22;
      return beatPoseAt(jumpArcKeys(bandStart, extOpt), progress, (key) => (
        // The ascent fell back to base 13, the descent to the deep gather 12.
        !key || key.at < 0.76 ? base(13) : base(12)
      ));
    }
    // v2.9 FLOW: the ascent band between takeoff and the bank-1 tuck wears
    // the authored rising key (knees starting to draw up) — the base ascent
    // cell was a full air pose arriving instantly at takeoff (and donald's
    // is the golf swing). Covers the reduced-motion path too: it is a pose
    // key, not a transform.
    // v3.0 critic round (RULE 2): the unified jump-rise is retired from the
    // route — every band after it (tuck, apex, descent, air-recovery, landing
    // gather) is motion-family, and the first cut's unified tuck handed to
    // motion:11 at 7.56 dE and held it 15+ ticks in mid-air. See jumpArcKeys.
    // v5.2 LOCOMOTION (ext5-air): with the `air` answer the arc above is one
    // family end to end (the rise and tuck un-retired ahead of the ext5 apex
    // tuck, descent and air recover, the ext3 gather, then the unified crouch
    // transition below); this reduced-motion / non-neutral read keeps its
    // motion2 rise and the land cell, which the substitution draws as ext3:10.
    if (fighter.vy < 0) return motion2Pose(MOTION2_CELLS.jumpRise, "base", 13);
    // BODY-FIRST (spec 4): the descent cell advances BEFORE touchdown — the
    // legs gather on the crouch cell through the last ~110px of the fall
    // (about five ticks), so the frozen late-fall pair is deduped and the
    // landing squash arrives on a fresh key. v2.7: the authored deep gather.
    if (FLOOR - fighter.y < 110) return motionPose(MOTION_CELLS.land, "base", 12);
    return uni(UNIFIED_CELLS.knockdown, base(roles.down));
  }
  // v2.7 FRAMES: the landing-recovery window holds the authored full-squat
  // compress under the existing squash-stretch transform.
  // v2.9 critic round 2 (B1): the touchdown CONTINUES the jump arc's last key
  // instead of re-showing the airborne gather. The arc hands over on the
  // half-crouch as the feet plant, so the landing is gather -> plant -> stand
  // (two drawings under the squash) rather than one cell held from 78px above
  // the street all the way through the compress. Fallback is the exact cell
  // this branch has always shown.
  if (fighter.landingRecoveryFrames > 0) {
    return uni(UNIFIED_CELLS.crouchTrans, motion2Pose(MOTION2_CELLS.crouchTrans, "base", 12));
  }
  // v2.9 FLOW: grounded facing flip wears the authored mid-pivot key for the
  // 2-3 latch ticks; leaving crouch shows the half-lowered in-between on the
  // way back up. Both latches are render-only observer state (never advanced
  // during rollback resimulation) and both fall back to the exact cell the
  // pre-2.9 read showed at that moment.
  const transObs = turnObs;
  if (transObs?.crouchTransFrames > 0 && !fighter.crouch && fighter.grounded) {
    return uni(UNIFIED_CELLS.crouchTrans,
      motion2Pose(MOTION2_CELLS.crouchTrans, "base", Math.floor(fighter.animTime * 5) % 4));
  }
  if (fighter.dashFrames > 0) {
    // BODY-FIRST (spec 6) + 2.7 critic round + v2.9 FLOW + v2.9 critic round 2
    // (B1/M1/M2). The 2.7 wave fixed the dash EXIT and left the ENTRY exactly
    // as it was: one tick of upright idle at vx 0, then a fully horizontal
    // lunge at vx 622, a 90-degree body rotation in a single tick with no
    // anticipation whatsoever. And the stretch cell then owned ten ticks.
    //
    // The authored brake key is a MID-LUNGE body — one foot planted, torso
    // pitched, arms trailing — which is the missing in-between at BOTH ends of
    // a dash, so it now bookends the stretch: launch -> stretch -> brake.
    // Fallbacks are the exact cells the pre-fix read showed (the walk cycle on
    // the way in, the base gather on the way out).
    // Pure sim read — startDash sets dashFrames from exactly this pair, so the
    // progress replays identically under rollback and in both renderers.
    const total = Math.max(1, (fighter.dashDirection === fighter.facing
      ? fighter.movement.forwardDashFrames : fighter.movement.backDashFrames) || 1);
    const dashProgress = clamp(1 - fighter.dashFrames / total, 0, 0.999);
    return beatPoseAt(dashKeys(), dashProgress, (key) => (
      !key || key.at >= 0.68
        ? base(12)
        : base(5 + Math.floor(fighter.walkTime * 18) % 3)
    ));
  }
  // v2.9 critic round 2 (M2): the dash EXIT TAIL. The brake key got two ticks,
  // landing the torso at roughly 45 degrees, and then the very next tick drew
  // the neutral idle while the fighter was still carrying 622px/s — a 45-degree
  // torso snap plus a full leg gather in ONE tick, with the feet skating. The
  // brake now owns the whole velocity decay, so the upright cell arrives only
  // once the fighter has genuinely stopped. The fallback is the base gather
  // cell the 2.7 bridge used, exactly as the in-dash brake key does.
  // v5.2 LOCOMOTION: the exit tail wears the fighter's OWN brake (ext5:2),
  // the same drawing the dash's last band left on, over the exact 2.9 chain.
  // Emitted directly rather than through the substitution table because the
  // devil's motion2 brake is rejected: for him the chain below resolves
  // base:12, which the table never sees, and the dash would leave the family
  // on its last four ticks.
  if (transObs?.dashExitFrames > 0 && fighter.grounded && !fighter.crouch
    && Math.abs(fighter.vx) > MOTION_RULES.dashBrakeReleaseSpeed) {
    return unifiedExt5Pose(UNIFIED_EXT5_CELLS.dashBrake, motion2Pose(MOTION2_CELLS.dashBrake, "base", 12));
  }
  if (Math.abs(fighter.vx) > WALK_POSE_MIN_SPEED && !(transObs?.dashExitFrames > 0)) {
    // v2.10 WALK — the SELF-CONTAINED four-key cycle (assets/walk).
    //
    // The 2.9 read interleaved the motion2 walk-a/b pair with the base walk
    // cells every ~6 ticks and was withdrawn, because the two banks cannot be
    // blended (different generations: build, cap, decal and boots all part,
    // the devil's pair is an all-fours prowl against an upright bipedal base
    // cycle, donald's is club-less against a club-carrying base walk) — and
    // because neither bank is a cycle on its own. The base bank's four walk
    // cells are near-duplicate redraws of ONE stride phase: adjacent-key
    // silhouette IoU runs 0.86-0.93 and, pointed at those cells, the 2.10
    // gate fails phase alternation, plant alternation and lead-leg inversion
    // on every fighter. The legs never swap; the apparent motion is the x
    // translation alone, which is the shuffle-glide.
    //
    // So this bank is neither a patch nor a blend: it is four keys of one
    // stride generated in a SINGLE pass — contact-left, passing-left,
    // contact-right, passing-right — played 0→1→2→3→0 and never interleaved
    // with the base cells. Build, costume and grading match across the four
    // keys by construction, and keys 0/2 carry genuinely opposite lead legs.
    //
    // Cadence is unchanged: the key index rides the same `walkTime * 10`
    // phase the base cycle has always used, so locomotion speed still drives
    // it, and the fallback on each descriptor is exactly the base cell that
    // phase used to show. Eight of ten fighters have no accepted sheet and so
    // still render that base cell, byte-identically to 2.9.
    //
    // v3.5 BACK-WALK: the phase source is the SIGNED, speed-scaled stride
    // clock rather than the flat `walkTime`. Advancing forwards at the kit's
    // own walk speed the two are the same number, so a forward walk is the
    // shipped read unchanged; retreating winds the clock backwards and the
    // identical four keys play in reverse — the legs un-step, which is what
    // walking backwards looks like — at the cadence `backWalkSpeed` earns,
    // so a slow retreat takes fewer, shorter-looking steps instead of the
    // same ten a second the forward walk takes over more ground.
    return walkCyclePose(fighter.strideTime, roles, { extended: ext });
  }
  // v3.0: the neutral idle. A unified fighter has exactly ONE idle drawing
  // where the base bank has a four-cell breathing cycle, and that is a real
  // cost measured and accepted here: the base cycle's adjacent-cell silhouette
  // IoU runs 0.26-0.98, so on most of the roster it is a slow sway and on
  // benny it is genuinely four drawings. It cannot be kept. Every base idle
  // cell is 9.5-22.5 dE of costume away from the unified walk keys, so
  // cycling base cells under a unified walk IS the strobe. The procedural
  // breathing scaleY and the idle bob in drawFighter still run underneath.
  return breathingIdle(base(Math.floor(fighter.animTime * 5) % 4));
}

function drawAtlasFrame(atlas, frame, size) {
  const cell = 320;
  ctx.drawImage(atlas, (frame % 4) * cell, Math.floor(frame / 4) * cell, cell, cell, -size * 0.5, -size, size, size);
}

// ---------------------------------------------------------------------------
// Tinted silhouette infrastructure. One persistent atlas-cell-sized offscreen:
// the requested frame is drawn in, then flooded with a colour via source-in,
// yielding a flat tinted cut-out of the sprite. Shared by the stage rim light,
// the dizzy double-vision ghosts and the Grit-ready flare, and intended for
// reuse by any future tinted-copy pass (wave 2). The last atlas/frame/colour
// key is cached so repeated blits of the same tint skip the rebuild.
// ---------------------------------------------------------------------------
const SILHOUETTE_CELL = 320;
const silhouetteScratch = document.createElement("canvas");
silhouetteScratch.width = SILHOUETTE_CELL;
silhouetteScratch.height = SILHOUETTE_CELL;
const silhouetteScratchCtx = silhouetteScratch.getContext("2d");
let silhouetteScratchKey = "";

function tintedSilhouette(atlas, frame, color) {
  const key = `${atlas.src}|${frame}|${color}`;
  if (key !== silhouetteScratchKey) {
    silhouetteScratchKey = key;
    silhouetteScratchCtx.globalCompositeOperation = "source-over";
    silhouetteScratchCtx.clearRect(0, 0, SILHOUETTE_CELL, SILHOUETTE_CELL);
    silhouetteScratchCtx.drawImage(
      atlas,
      (frame % 4) * SILHOUETTE_CELL, Math.floor(frame / 4) * SILHOUETTE_CELL,
      SILHOUETTE_CELL, SILHOUETTE_CELL,
      0, 0, SILHOUETTE_CELL, SILHOUETTE_CELL,
    );
    silhouetteScratchCtx.globalCompositeOperation = "source-in";
    silhouetteScratchCtx.fillStyle = color;
    silhouetteScratchCtx.fillRect(0, 0, SILHOUETTE_CELL, SILHOUETTE_CELL);
  }
  return silhouetteScratch;
}

// Blit a tinted silhouette with the exact footprint drawAtlasFrame uses, so
// callers can layer it under/over the real sprite in the same transform space.
function drawSilhouetteFrame(atlas, frame, size, color) {
  ctx.drawImage(tintedSilhouette(atlas, frame, color), -size * 0.5, -size, size, size);
}

// ---------------------------------------------------------------------------
// v2.9 critic round (M1) — POSE-CROSSFADE GHOST CELL.
//
// The crossfade's outgoing cell, intersected with the INCOMING cell's alpha.
// The 2.6 ghost used a fixed "clip everything below 72% of the cell" rect,
// which encodes the assumption that a fighter's head occupies the top 28% of
// its cell. That holds for standing base cells and fails for most authored
// motion/motion2 keys — the dash stretch is a horizontal body, so its HEAD
// sits mid-cell, survived the clip, and drew a fully readable second face at
// the live fighter's hip on every dash->brake seam.
//
// Masking by the live silhouette is a hard guarantee rather than a tuned
// threshold: no pixel can appear where the new pose is not already opaque, so
// no bank switch can produce a second readable figure. Built in cell space at
// SILHOUETTE_CELL and blitted with drawAtlasFrame's footprint; `liveRatio` is
// renderSize/fadeSize so a sheet-adjust mismatch (the Commissioner's banks,
// the corrected crouch cell) still lines the mask up with what actually drew.
// One scratch, keyed like the others so a held crossfade pays nothing.
// ---------------------------------------------------------------------------
// Blur radius in CELL pixels (320px cells drawing at ~387px, so ~1.2 world px
// each). A face is ~50 cell px across, so 9px reliably destroys features while
// leaving the body's colour mass intact.
// v2.9 critic round 2 (B5). Round 1 added the blur and it was never reaching
// the seam the critics were looking at (see the sameCycle fix in drawFighter),
// and 9px over a 320px cell does not destroy a chest logo even when it does
// run. The softened ghost is now blurred HARD, desaturated to a grey mass and
// dimmed, so what is left is colour weight with no features in it — which is
// all a crossfade needs to kill a pose snap.
const GHOST_SOFTEN_BLUR = 17;
const GHOST_SOFTEN_FILTER = `blur(${GHOST_SOFTEN_BLUR}px) saturate(0.25) brightness(0.82)`;
// Alpha ceiling for a softened (big-delta) ghost vs an adjacent-key one. The
// round-1 cap was a flat 0.3 for both.
const GHOST_SOFT_ALPHA = 0.17;
const GHOST_CYCLE_ALPHA = 0.3;
const ghostScratch = document.createElement("canvas");
ghostScratch.width = SILHOUETTE_CELL;
ghostScratch.height = SILHOUETTE_CELL;
const ghostScratchCtx = ghostScratch.getContext("2d");
let ghostScratchKey = "";

function poseGhostCell(fadeAtlas, fadeFrame, liveAtlas, liveFrame, liveRatio, soften) {
  if (!liveAtlas?.complete || !liveAtlas.naturalWidth) return null;
  const ratio = Number.isFinite(liveRatio) && liveRatio > 0 ? liveRatio : 1;
  const key = `${fadeAtlas.src}|${fadeFrame}|${liveAtlas.src}|${liveFrame}|${ratio.toFixed(4)}|${soften ? 1 : 0}`;
  if (key !== ghostScratchKey) {
    ghostScratchKey = key;
    const cell = SILHOUETTE_CELL;
    ghostScratchCtx.globalCompositeOperation = "source-over";
    ghostScratchCtx.filter = "none";
    ghostScratchCtx.clearRect(0, 0, cell, cell);
    // Masking alone is not enough: the outgoing dash-stretch cell is a
    // HORIZONTAL body, so its head sits mid-cell and lands squarely ON the
    // incoming pose's torso — inside the silhouette, but still a legible
    // second face. Softening the outgoing art destroys the features while
    // keeping its colour mass, so the fade still does its job (killing the
    // pose snap) with nothing readable in it. Only pose changes that are not
    // adjacent keys of one cycle are softened — the walk and idle cycles,
    // where the crossfade genuinely earns its keep, stay crisp.
    ghostScratchCtx.filter = soften ? GHOST_SOFTEN_FILTER : "none";
    ghostScratchCtx.drawImage(
      fadeAtlas,
      (fadeFrame % 4) * cell, Math.floor(fadeFrame / 4) * cell, cell, cell,
      0, 0, cell, cell,
    );
    ghostScratchCtx.filter = "none";
    // The live cell is bottom-centre anchored exactly like drawAtlasFrame, so
    // the intersection is taken in world-consistent space even when the two
    // banks draw at different sizes.
    const live = cell * ratio;
    ghostScratchCtx.globalCompositeOperation = "destination-in";
    ghostScratchCtx.drawImage(
      liveAtlas,
      (liveFrame % 4) * cell, Math.floor(liveFrame / 4) * cell, cell, cell,
      (cell - live) * 0.5, cell - live, live, live,
    );
    ghostScratchCtx.globalCompositeOperation = "source-over";
  }
  return ghostScratch;
}

// ---------------------------------------------------------------------------
// Battle-damage compositor: one atlas-cell scratch per side. The current frame
// is drawn in, then the fighter's accumulated bruise/cut marks are stamped
// with source-atop so they clip to the sprite's alpha and ride the animation.
// The result blits with drawAtlasFrame's exact footprint. Keyed on
// atlas/frame/mark revision/gore so held poses reuse the composite; a frame
// change costs one cell draw plus at most BATTLE_DAMAGE_MARK_CAP gradients.
// ---------------------------------------------------------------------------
const damageScratches = [document.createElement("canvas"), document.createElement("canvas")];
const damageScratchContexts = damageScratches.map((scratch) => {
  scratch.width = SILHOUETTE_CELL;
  scratch.height = SILHOUETTE_CELL;
  return scratch.getContext("2d");
});
const damageScratchKeys = ["", ""];

// 5.3 SPECTACLE (#48): the marks as a DRAWING, on a foreign context — the
// same pattern the projectile / trap painters use. The 2D path composites it
// into its source-atop scratch cell; the CINEMA 3D fighter layer paints it
// into a 320px decal canvas bound as a second sampler on the sprite shader.
// Cell-space (320px atlas cell) coordinates, authored about (0,0) of the cell,
// so mirroring and the HD swap both come for free.
function paintBattleDamageWith(c, side) {
  const gore = state.graphicFatalities;
  for (const mark of battleDamageMarks[side]) {
    // Blood-red cuts honour the GRAPHIC FATALITIES toggle; with it off every
    // mark renders as a plain bruise.
    const bloody = mark.cut && gore;
    c.save();
    c.translate(mark.x, mark.y);
    c.rotate(mark.lean);
    c.scale(1, bloody ? 1.45 : 0.85);
    const smear = c.createRadialGradient(0, 0, mark.size * 0.15, 0, 0, mark.size);
    if (bloody) {
      smear.addColorStop(0, "rgba(122,10,18,0.68)");
      smear.addColorStop(0.55, "rgba(88,8,16,0.44)");
      smear.addColorStop(1, "rgba(60,6,12,0)");
    } else {
      smear.addColorStop(0, "rgba(56,32,56,0.6)");
      smear.addColorStop(0.55, "rgba(42,26,46,0.38)");
      smear.addColorStop(1, "rgba(28,18,34,0)");
    }
    c.fillStyle = smear;
    c.beginPath();
    c.arc(0, 0, mark.size, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }
}

function drawDamagedAtlasFrame(side, atlas, frame, size) {
  const scratchCtx = damageScratchContexts[side];
  const gore = state.graphicFatalities;
  const key = `${atlas.src}|${frame}|${damageDecalKey(battleDamageRevision[side], gore)}`;
  if (key !== damageScratchKeys[side]) {
    damageScratchKeys[side] = key;
    scratchCtx.globalCompositeOperation = "source-over";
    scratchCtx.clearRect(0, 0, SILHOUETTE_CELL, SILHOUETTE_CELL);
    scratchCtx.drawImage(
      atlas,
      (frame % 4) * SILHOUETTE_CELL, Math.floor(frame / 4) * SILHOUETTE_CELL,
      SILHOUETTE_CELL, SILHOUETTE_CELL,
      0, 0, SILHOUETTE_CELL, SILHOUETTE_CELL,
    );
    scratchCtx.globalCompositeOperation = "source-atop";
    paintBattleDamageWith(scratchCtx, side);
    scratchCtx.globalCompositeOperation = "source-over";
  }
  ctx.drawImage(damageScratches[side], -size * 0.5, -size, size, size);
}

function activeGraphicFatality(fighter) {
  const finisher = state.finisher;
  if (!state.graphicFatalities || !finisher?.fatalityTriggered || fighter.side === finisher.winner) return null;
  const attacker = state.fighters[finisher.winner];
  const scriptId = attacker?.def.finisherScriptId || attacker?.def.id || "deathblow";
  const snapshot = graphicFatalitySnapshot(scriptId, finisher.type, finisher.elapsed, finisher.fatalityAt);
  // 2.8: the draw side needs the attacker's script id to select the
  // signature gore treatment (devil's scorched cuts etc.).
  snapshot.scriptId = scriptId;
  // 2.8 critic round: the snapshot's aftermath must keep flowing through the
  // hold (finisher.elapsed saturates at the script duration ~0.5s in).
  const live = finisherAftermathSeconds(finisher);
  if (live > snapshot.aftermath) {
    snapshot.aftermath = live;
    snapshot.reveal = Math.min(1, live / 0.42);
    snapshot.settle = Math.min(1, live / 1.15);
  }
  return snapshot;
}

// 2.8: per-frame wound-compositing context, set by drawGraphicFatalityVictim
// before the family branches so drawFatalityCut/drawFatalityStump can
// composite the victim's OWN atlas pixels (never painted-from-scratch
// anatomy) without threading four more arguments through every call site.
let fatalityWoundCtx = null; // { atlas, frame, size, aftermath, time, scorch }

function drawFatalityAtlasBand(atlas, frame, size, top, bottom, transform = {}) {
  const y = -size + top * size;
  const height = Math.max(1, (bottom - top) * size);
  ctx.save();
  ctx.translate(transform.x || 0, transform.y || 0);
  ctx.rotate(transform.rotation || 0);
  ctx.scale(transform.scaleX || 1, transform.scaleY || 1);
  ctx.globalAlpha *= transform.alpha ?? 1;
  if (transform.filter) ctx.filter = transform.filter;
  ctx.beginPath();
  ctx.rect(-size * .52, y, size * 1.04, height);
  ctx.clip();
  drawAtlasFrame(atlas, frame, size);
  // 2.8 critic round (M4): the razor-straight clip seams read as screenshot
  // slices — every INTERIOR edge of a real piece re-stamps the victim's OWN
  // atlas pixels in a thin strip, darkened/reddened with a small tear
  // offset, so the lip exists ONLY on the body (never floating paint) and
  // separated pieces read TORN, not cropped. Skipped for the thin dissolve/
  // glitch strips whose identity is the clean signal slice.
  if (state.graphicFatalities && (transform.alpha ?? 1) > 0.12 && height >= size * 0.14) {
    const tornEdge = (edgeY, into) => {
      ctx.save();
      ctx.beginPath();
      ctx.rect(-size * .52, into > 0 ? edgeY : edgeY - size * 0.028, size * 1.04, size * 0.028);
      ctx.clip();
      ctx.globalAlpha *= 0.55;
      ctx.filter = "brightness(0.32) sepia(1) hue-rotate(-40deg) saturate(4.6) contrast(1.45)";
      drawAtlasFrame(atlas, frame, size);
      ctx.globalAlpha *= 0.7;
      ctx.filter = "brightness(0.16) sepia(1) hue-rotate(-42deg) saturate(5) contrast(1.75)";
      ctx.translate(2.2, into * 1.9);
      drawAtlasFrame(atlas, frame, size);
      ctx.restore();
    };
    if (top > 0.001) tornEdge(y, 1);
    if (bottom < 0.999) tornEdge(y + height, -1);
  }
  ctx.restore();
}

function drawFatalityCut(size, yRatio, fatality, width = .32) {
  const y = -size + yRatio * size;
  const wound = fatalityWoundCtx;
  // 2.8: progressive wound compositing — a thin strip of the victim's OWN
  // atlas pixels either side of the cut, re-stamped darkened/reddened with a
  // small tear offset (identity holds; nothing painted from scratch). The
  // tissue deepens over the aftermath; devil's curse scorches it dark.
  if (wound?.atlas) {
    const depth = Math.min(1, 0.45 + wound.aftermath * 0.5);
    ctx.save();
    ctx.beginPath();
    ctx.rect(-size * width * 0.72, y - size * 0.038, size * width * 1.44, size * 0.076);
    ctx.clip();
    ctx.globalAlpha *= 0.32 + 0.22 * depth;
    ctx.filter = wound.scorch
      ? "brightness(0.24) saturate(0.4) contrast(1.6)"
      : "brightness(0.4) sepia(1) hue-rotate(-38deg) saturate(4.6) contrast(1.35)";
    ctx.translate(0, 1.6);
    drawAtlasFrame(wound.atlas, wound.frame, size);
    ctx.globalAlpha *= 0.6;
    ctx.filter = wound.scorch
      ? "brightness(0.12) saturate(0.2) contrast(1.9)"
      : "brightness(0.24) sepia(1) hue-rotate(-40deg) saturate(5) contrast(1.6)";
    ctx.translate(0, -3.4);
    drawAtlasFrame(wound.atlas, wound.frame, size);
    ctx.restore();
  }
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.strokeStyle = bloodTint(fatality.palette[0]);
  ctx.fillStyle = bloodTint(fatality.palette[1]);
  ctx.shadowColor = bloodTint(fatality.palette[0]);
  ctx.shadowBlur = 13;
  // 2.8 critic round: the seam stroke hugs the body's actual cross-section
  // instead of spanning the full band width, and the drip beads sit tight on
  // the cut line — the old wide rows floated beside a rotated/lying body.
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(-size * width * 0.58, y);
  ctx.quadraticCurveTo(0, y + 7, size * width * 0.58, y - 2);
  ctx.stroke();
  for (let drop = 0; drop < 4; drop += 1) {
    const x = (drop - 1.5) * size * width * 0.3;
    ctx.beginPath();
    ctx.ellipse(x, y + 5 + (drop % 2) * 3, 2.6 + drop % 2 * 1.6, 5.5 + drop % 3 * 2.4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  // 2.8: wet specular glints riding the fresh viscera through the existing
  // lighting language — additive beads that shimmer and dry out over ~3s.
  if (wound && state.performance.shadows) {
    // 2.8 critic round (M4): the wet read must actually land — bigger,
    // brighter beads that shimmer while fresh and dry out over ~3s.
    const wet = Math.max(0, 1 - wound.aftermath / 3.2);
    if (wet > 0.05) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.fillStyle = "#ffe9ec";
      for (let glint = 0; glint < 5; glint += 1) {
        const gx = (glint - 2) * size * width * 0.46 + Math.sin(wound.time * 0.011 + glint * 2.6) * 4;
        const shimmer = 0.5 + 0.5 * Math.sin(wound.time * 0.019 + glint * 1.9);
        ctx.globalAlpha = wet * (0.35 + shimmer * 0.45);
        ctx.beginPath();
        ctx.ellipse(gx, y + 3 + (glint % 2) * 3, 3.4, 1.9, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }
  }
}

function drawFatalitySkeleton(size, fatality, pulse) {
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha *= .44 + pulse * .38;
  ctx.strokeStyle = "#fff9d8";
  ctx.shadowColor = fatality.palette[0];
  ctx.shadowBlur = 18;
  ctx.lineWidth = 6;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.arc(0, -size * .72, size * .07, 0, Math.PI * 2);
  ctx.moveTo(0, -size * .64); ctx.lineTo(0, -size * .34);
  ctx.moveTo(-size * .13, -size * .56); ctx.lineTo(size * .13, -size * .56);
  ctx.moveTo(-size * .12, -size * .55); ctx.lineTo(-size * .2, -size * .34);
  ctx.moveTo(size * .12, -size * .55); ctx.lineTo(size * .2, -size * .34);
  ctx.moveTo(0, -size * .34); ctx.lineTo(-size * .13, -size * .08);
  ctx.moveTo(0, -size * .34); ctx.lineTo(size * .13, -size * .08);
  ctx.stroke();
  for (let rib = 0; rib < 4; rib += 1) {
    ctx.beginPath();
    ctx.ellipse(0, -size * (.56 - rib * .055), size * (.1 - rib * .008), size * .033, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawFatalityStump(size, fatality, direction) {
  const leg = fatality.limb.endsWith("leg");
  const side = fatality.limb.startsWith("left") ? -1 : 1;
  const x = side * direction * size * (leg ? .14 : .22);
  const y = -size * (leg ? .29 : .61);
  const radius = size * (leg ? .055 : .045);
  const rotation = side * direction * (leg ? .18 : -.32);
  const wound = fatalityWoundCtx;
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.translate(x, y);
  ctx.rotate(rotation);
  // 2.8: believable cross-section. The dark tissue ring is the victim's OWN
  // atlas pixels stamped back through an elliptical clip (recolored, never
  // painted anatomy), around a muscle ring, a pale bone core with a marrow
  // shadow, hanging shreds and a slow drip while the wound is fresh.
  if (wound?.atlas) {
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, radius * 1.42, radius * 1.14, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.rotate(-rotation);
    ctx.translate(-x, -y);
    ctx.filter = wound.scorch
      ? "brightness(0.2) saturate(0.35) contrast(1.7)"
      : "brightness(0.3) sepia(1) hue-rotate(-40deg) saturate(5) contrast(1.5)";
    drawAtlasFrame(wound.atlas, wound.frame, size);
    ctx.restore();
  }
  // 2.8 critic round (M4): a torn cross-section everywhere, not a bullseye.
  // Layered tissue with a dark blood lip, off-origin muscle bundles, an
  // IRREGULAR splintered bone with a marrow hint, shreds bridging the cut,
  // and wet glints big enough to actually read, drying over ~3s.
  const gore = bloodTint(fatality.palette[0]);
  const goreDeep = bloodTint(fatality.palette[1]);
  ctx.shadowColor = gore;
  ctx.shadowBlur = 16;
  // lumpy dermis silhouette (three overlapping lobes break the circle read)
  ctx.fillStyle = goreDeep;
  ctx.beginPath();
  ctx.ellipse(0, 0, radius * 1.26, radius * 1.02, 0.14, 0, Math.PI * 2);
  ctx.ellipse(radius * 0.3, -radius * 0.24, radius * 0.9, radius * 0.7, 0.5, 0, Math.PI * 2);
  ctx.ellipse(-radius * 0.3, radius * 0.26, radius * 0.86, radius * 0.66, -0.4, 0, Math.PI * 2);
  ctx.fill();
  ctx.shadowBlur = 0;
  // dark congealed blood lip hugging the rim
  ctx.strokeStyle = "#38020a";
  ctx.lineWidth = radius * 0.22;
  ctx.beginPath();
  ctx.ellipse(0, 0, radius * 1.12, radius * 0.9, 0.14, 0, Math.PI * 2);
  ctx.stroke();
  // muscle bundles in two close reds, off-origin
  for (let bundle = 0; bundle < 4; bundle += 1) {
    const lobe = bundle * 1.57 + 0.45;
    ctx.fillStyle = bundle % 2 ? gore : "#8f0713";
    ctx.beginPath();
    ctx.ellipse(
      Math.cos(lobe) * radius * 0.32, Math.sin(lobe) * radius * 0.24 + 1,
      radius * (0.42 + (bundle % 3) * 0.09), radius * (0.3 + (bundle % 2) * 0.08),
      lobe, 0, Math.PI * 2,
    );
    ctx.fill();
  }
  // radial fibre strokes pulling the meat toward the bone
  ctx.strokeStyle = "rgba(56,2,10,0.8)";
  ctx.lineWidth = 1.1;
  for (let fibre = 0; fibre < 5; fibre += 1) {
    const angle = fibre * 1.35 + 0.4;
    ctx.beginPath();
    ctx.moveTo(Math.cos(angle) * radius * 0.2, Math.sin(angle) * radius * 0.16);
    ctx.lineTo(Math.cos(angle) * radius * 0.78, Math.sin(angle) * radius * 0.62);
    ctx.stroke();
  }
  // splintered bone: jagged polygon with two long splinter spikes — a broken
  // shaft end, never a smooth rounded rod. Fixed constants, deterministic.
  ctx.save();
  ctx.translate(-radius * 0.14, -radius * 0.12);
  ctx.rotate(-0.35);
  ctx.fillStyle = "#f2e5c8";
  ctx.beginPath();
  const boneR = radius * 0.3;
  const spikes = [1, 0.62, 1.5, 0.7, 1.05, 0.6, 1.7, 0.66, 0.95, 0.58];
  for (let point = 0; point < spikes.length; point += 1) {
    const angle = (point / spikes.length) * Math.PI * 2;
    const reach = boneR * spikes[point];
    if (point === 0) ctx.moveTo(Math.cos(angle) * reach, Math.sin(angle) * reach * 0.82);
    else ctx.lineTo(Math.cos(angle) * reach, Math.sin(angle) * reach * 0.82);
  }
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(148,116,78,0.75)";
  ctx.lineWidth = 1;
  ctx.stroke();
  // marrow hint: dark warm core inside the shaft
  ctx.fillStyle = "#a5773f";
  ctx.beginPath();
  ctx.ellipse(boneR * 0.08, boneR * 0.06, boneR * 0.42, boneR * 0.3, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#5e3c1c";
  ctx.beginPath();
  ctx.ellipse(boneR * 0.14, boneR * 0.1, boneR * 0.2, boneR * 0.13, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  if (wound) {
    const aftermath = wound.aftermath;
    const sway = Math.sin(wound.time * 0.012) * Math.max(0, 1 - aftermath / 2.2) * 2.2;
    ctx.lineCap = "round";
    // shreds BRIDGING the cut mouth — strands still connected across the tear
    ctx.strokeStyle = goreDeep;
    ctx.lineWidth = 1.7;
    for (let bridge = 0; bridge < 2; bridge += 1) {
      const by = (bridge - 0.5) * radius * 0.5;
      ctx.beginPath();
      ctx.moveTo(-radius * (0.95 - bridge * 0.2), by);
      ctx.quadraticCurveTo(sway * 0.6, by + radius * (0.34 + bridge * 0.2), radius * (0.9 - bridge * 0.14), by - 1);
      ctx.stroke();
    }
    // hanging shreds swaying slightly, stilling as the body does
    ctx.strokeStyle = gore;
    ctx.lineWidth = 2.4;
    for (let shred = 0; shred < 3; shred += 1) {
      const sx = (shred - 1) * radius * 0.62;
      ctx.beginPath();
      ctx.moveTo(sx, radius * 0.4);
      ctx.quadraticCurveTo(sx + sway, radius * (1 + shred * 0.32), sx + sway * 1.4, radius * (1.5 + shred * 0.4));
      ctx.stroke();
    }
    // slow drip: a dark thread lengthening from the low edge, beading off
    const drip = Math.min(radius * 2.6, aftermath * 14);
    if (drip > 2) {
      ctx.strokeStyle = "#5c040b";
      ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.moveTo(radius * 0.3, radius * 0.7);
      ctx.lineTo(radius * 0.3, radius * 0.7 + drip);
      ctx.stroke();
      ctx.fillStyle = "#7a0611";
      ctx.beginPath();
      ctx.arc(radius * 0.3, radius * 0.7 + drip, 1.9, 0, Math.PI * 2);
      ctx.fill();
    }
    // wet glints answering the stage light while fresh — a sheen crescent
    // plus two specular beads, all drying out over ~3s (2.8 critic round M4).
    if (state.performance.shadows) {
      const wet = Math.max(0, 1 - aftermath / 3.2);
      if (wet > 0.05) {
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        const shimmer = 0.5 + 0.5 * Math.sin(wound.time * 0.017);
        ctx.strokeStyle = "#ffd9de";
        ctx.globalAlpha = wet * (0.4 + shimmer * 0.35);
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.ellipse(0, 0, radius * 0.78, radius * 0.6, 0.14, -2.7, -1.45);
        ctx.stroke();
        ctx.fillStyle = "#ffeef1";
        ctx.globalAlpha = wet * (0.5 + shimmer * 0.4);
        ctx.beginPath();
        ctx.ellipse(-radius * 0.42, -radius * 0.3, radius * 0.24, radius * 0.13, -0.4, 0, Math.PI * 2);
        ctx.ellipse(radius * 0.34, -radius * 0.12, radius * 0.14, radius * 0.09, 0.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }
  }
  ctx.restore();
}

function drawGraphicFatalityVictim(atlas, frame, size, fatality, time, mirror = 1, bodyRotation = 0) {
  const reveal = fatality.reveal;
  const settle = fatality.settle;
  const force = fatality.separation;
  const direction = state.finisher?.direction || 1;
  // 2.8: arm the wound-compositing context for the cut/stump helpers.
  fatalityWoundCtx = {
    atlas, frame, size,
    aftermath: fatality.aftermath || 0,
    time,
    scorch: Boolean(signatureGore(fatality.scriptId || "deathblow").scorch),
  };
  const whole = (transform = {}) => drawFatalityAtlasBand(atlas, frame, size, 0, 1, transform);
  // Authored drift band: kept for the dissolve/glitch treatments whose whole
  // identity IS the non-physical strip motion.
  const band = (top, bottom, x, y, rotation = 0, extra = {}) => drawFatalityAtlasBand(
    atlas,
    frame,
    size,
    top,
    bottom,
    { x: x * direction * force * settle, y: y * force * settle, rotation: rotation * direction * settle, ...extra },
  );
  // 2.8 critic round (M6): separated pieces obey gravity. The authored hover
  // offsets become a burst velocity (engine/gore.mjs scatterBandOffset):
  // each piece flies out, takes one damped floor bounce, and settles onto
  // the ground plane with a blood smudge under its resting spot — nothing
  // hangs motionless mid-air. Transforms are recorded so the cut overlays
  // and the stump ride their OWN piece instead of floating at the standing
  // pose (M1). Pure closed-form of the aftermath clock — deterministic.
  const piecesDrawn = [];
  // The slam scripts lay the victim's sprite down with a big cinematic
  // rotation, so "down" in this local space is NOT down on screen. The
  // ballistics run in WORLD space — burst out, fall to the street, bounce,
  // rest — and the resulting world offset is mapped back through the render
  // transform (rotation + mirror) the band actually draws under.
  const cosBody = Math.cos(bodyRotation);
  const sinBody = Math.sin(bodyRotation);
  const victimWorldX = state.finisher ? state.fighters[1 - state.finisher.winner].x : W * 0.5;
  const scatterPiece = (top, bottom, x, y, rotation = 0, extra = {}, delay = 0) => {
    // world height of the piece centre above the feet/street line
    const centreLocalY = size * ((top + bottom) / 2 - 1);
    const fall = Math.max(0, -cosBody * centreLocalY - size * 0.12);
    const scatter = scatterBandOffset(
      x * direction * force,
      y * force,
      fall,
      Math.max(0, (fatality.aftermath || 0) - delay),
    );
    // pieces stop at the arena bounds instead of sailing off-frame (a script
    // that ends the kill at the wall would otherwise scatter half the body
    // out of the shot)
    scatter.x = clamp(scatter.x,
      MOVEMENT_RULES.stageMinX + 26 - victimWorldX,
      MOVEMENT_RULES.stageMaxX - 26 - victimWorldX);
    const localX = (cosBody * scatter.x + sinBody * scatter.y) * mirror;
    const localY = -sinBody * scatter.x + cosBody * scatter.y;
    const transform = {
      x: localX,
      y: localY,
      rotation: rotation * direction * scatter.progress,
      ...extra,
    };
    drawFatalityAtlasBand(atlas, frame, size, top, bottom, transform);
    piecesDrawn.push({ top, bottom, transform });
    return transform;
  };
  const cutAt = (transform, yRatio, width = .32) => {
    ctx.save();
    ctx.translate(transform?.x || 0, transform?.y || 0);
    ctx.rotate(transform?.rotation || 0);
    if (transform && transform.alpha !== undefined) ctx.globalAlpha *= transform.alpha;
    drawFatalityCut(size, yRatio, fatality, width);
    ctx.restore();
  };

  ctx.save();
  if (fatality.family === "rupture") {
    scatterPiece(0, .28, -74, -92, -.86);
    const torso = scatterPiece(.28, .52, 38, -42, .33);
    const waist = scatterPiece(.52, .73, -48, 12, -.25);
    const legs = scatterPiece(.73, 1, 64, 34, .5);
    cutAt(torso, .28);
    cutAt(waist, .52, .37);
    cutAt(legs, .73, .3);
  } else if (fatality.family === "slice") {
    const pieces = Math.max(3, Math.min(5, fatality.pieces));
    const transforms = [];
    for (let index = 0; index < pieces; index += 1) {
      const top = index / pieces;
      const bottom = (index + 1) / pieces;
      const side = index % 2 ? 1 : -1;
      transforms.push(scatterPiece(top, bottom, side * (42 + index * 12), -20 - index * 7, fatality.angle + side * .08));
    }
    for (let index = 0; index < pieces - 1; index += 1) {
      cutAt(transforms[index + 1], (index + 1) / pieces, .36 - index * .025);
    }
  } else if (fatality.family === "crush") {
    const compression = 1 - reveal * .68;
    whole({
      y: size * .28 * reveal,
      scaleX: 1 + reveal * .34,
      scaleY: compression,
      filter: "contrast(1.28) saturate(.72) brightness(.72)",
    });
    if (reveal > .46) {
      scatterPiece(0, .34, -54, -28, -.32, { alpha: reveal * .9 }, .19);
      const mid = scatterPiece(.34, .68, 45, 10, .22, { alpha: reveal * .82 }, .19);
      cutAt(mid, .43, .4);
    }
  } else if (fatality.family === "dissolve") {
    const strips = Math.max(6, Math.min(10, fatality.pieces));
    for (let index = 0; index < strips; index += 1) {
      const top = index / strips;
      const bottom = (index + 1) / strips;
      const wave = Math.sin(index * 2.4 + time * .018);
      band(top, bottom, wave * (26 + index * 5), 18 + index * 5, wave * .06, {
        alpha: 1 - reveal * (.25 + index / strips * .48),
        filter: `saturate(${1 + reveal * 1.8}) contrast(${1 + reveal * .5})`,
      });
    }
    ctx.globalAlpha *= .58 + reveal * .34;
    ctx.fillStyle = bloodTint(fatality.palette[0]);
    for (let drop = 0; drop < 20; drop += 1) {
      const angle = drop * 2.399;
      const radius = (28 + (drop % 6) * 16) * reveal;
      ctx.beginPath();
      ctx.arc(Math.cos(angle) * radius, -size * .42 + Math.sin(angle) * radius + settle * 72, 5 + drop % 5 * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (fatality.family === "electrocute") {
    const pulse = (Math.sin(time * .045) + 1) * .5;
    if (settle < .62) {
      whole({
        x: (pulse - .5) * 18,
        filter: pulse > .46 ? "brightness(2.2) contrast(1.7) grayscale(1)" : "brightness(.18) contrast(2)",
      });
      drawFatalitySkeleton(size, fatality, pulse);
    } else {
      // the charred pieces let go and drop once the arc releases (~.71s in)
      scatterPiece(0, .26, -52, -70, -.58, { filter: "brightness(.2) saturate(0)" }, .71);
      scatterPiece(.26, .55, 38, -22, .28, { filter: "brightness(.2) saturate(0)" }, .71);
      const hips = scatterPiece(.55, .77, -44, 18, -.2, { filter: "brightness(.2) saturate(0)" }, .71);
      scatterPiece(.77, 1, 50, 28, .42, { filter: "brightness(.2) saturate(0)" }, .71);
      cutAt(hips, .55, .33);
    }
  } else if (fatality.family === "launch") {
    const body = scatterPiece(.25, 1, 0, 22, .18, { filter: "contrast(1.15) brightness(.72)" });
    scatterPiece(0, .25, 135, -205, -1.65, { scaleX: .96, scaleY: .96 });
    cutAt(body, .25, .24);
    if (fatality.pieces > 3) {
      scatterPiece(.36, .61, -48, -16, -.22, { alpha: reveal });
      const hip = scatterPiece(.61, .82, 55, 23, .31, { alpha: reveal });
      cutAt(hip, .61, .32);
    }
  } else if (fatality.family === "glitch") {
    const strips = Math.max(7, Math.min(12, fatality.pieces));
    for (let index = 0; index < strips; index += 1) {
      const top = index / strips;
      const bottom = (index + 1) / strips;
      const glitch = ((index * 47) % 9 - 4) * 9 * reveal;
      band(top, bottom, glitch, index % 3 === 0 ? -18 : 8, (index % 2 ? .04 : -.04) * reveal, {
        alpha: 1 - reveal * (index % 3 === 0 ? .48 : .18),
        filter: index % 2 ? "hue-rotate(75deg) contrast(1.45)" : "hue-rotate(-35deg) contrast(1.6)",
      });
    }
    ctx.globalCompositeOperation = "screen";
    ctx.fillStyle = fatality.palette[0];
    for (let line = 0; line < 9; line += 1) {
      ctx.globalAlpha = .25 + (line % 3) * .16;
      ctx.fillRect(-size * .45 + ((line * 71) % 90), -size * (.9 - line * .09), size * (.25 + (line % 4) * .08), 3 + line % 3 * 3);
    }
  } else if (fatality.family === "implode") {
    if (settle < .5) {
      const compression = 1 - settle * 1.05;
      whole({ scaleX: compression, scaleY: compression, y: -size * .34 * (1 - compression), filter: "contrast(1.5) brightness(.72)" });
    } else {
      const pieces = Math.max(5, Math.min(8, fatality.pieces));
      let cutTransform = null;
      for (let index = 0; index < pieces; index += 1) {
        const top = index / pieces;
        const bottom = (index + 1) / pieces;
        const angle = index * Math.PI * 2 / pieces;
        const transform = scatterPiece(top, bottom, Math.cos(angle) * 86, Math.sin(angle) * 72 - 26, (index - pieces / 2) * .16, {}, .575);
        if (top <= .48 && bottom >= .48) cutTransform = transform;
      }
      cutAt(cutTransform, .48, .42);
    }
  } else {
    whole();
  }
  // The stump rides the piece that contains it (2.8 critic round, M1/M6) —
  // it must never float at the standing pose while its band lies elsewhere.
  const stumpRatio = fatality.limb.endsWith("leg") ? .71 : .39;
  const host = piecesDrawn.find((piece) => piece.top <= stumpRatio && piece.bottom >= stumpRatio);
  ctx.save();
  if (host) {
    ctx.translate(host.transform.x || 0, host.transform.y || 0);
    ctx.rotate(host.transform.rotation || 0);
  }
  drawFatalityStump(size, fatality, direction);
  ctx.restore();
  fatalityWoundCtx = null;
  ctx.restore();
}

function drawAttackVfx(fighter, time, activePower) {
  const attack = fighter.attacking;
  if (!attack || activePower <= 0) return;
  const strong = attack.kind === "special";
  const reach = attack.kind === "special" ? 178 : attack.kind === "heavy" ? 125 : 90;
  const pulse = 0.82 + Math.sin(time * 0.022) * 0.18;
  ctx.save();
  ctx.globalAlpha = clamp(activePower * (strong ? 1 : 0.72), 0, 1);
  ctx.globalCompositeOperation = "screen";
  ctx.strokeStyle = fighter.def.accent;
  ctx.fillStyle = fighter.def.accent;
  ctx.shadowColor = fighter.def.accent;
  ctx.shadowBlur = strong ? 26 : 13;
  ctx.lineCap = "round";

  // Swipe ribbon (wave 4): heavies and specials trace a tapered additive arc
  // that sweeps with the swing — wide and bright at the fist, thinning to
  // nothing at the trail's start. Shared pass ahead of the per-fighter vfx
  // branches; pure render math off attackTime, jittered by presentationHash01
  // so rollback and the mirror pass replay it identically.
  // MOTION FIX 4: once the hit lands the ribbon dissipates within ~9 ticks
  // (ticks keep advancing through hitstop) — it whips through and is gone
  // instead of hanging frozen at full brightness over the impact hold.
  const ribbonFade = motionObs[fighter.side]?.ribbonFade ?? 1;
  if ((attack.kind === "heavy" || attack.kind === "special")
    && state.performance.trailScale > 0 && !state.accessibility.reducedMotion
    && ribbonFade > 0.05) {
    const progress = clamp(fighter.attackTime / attack.duration, 0, 1);
    if (progress > 0.12) {
      const eased = Math.sin(Math.min(1, progress * 1.15) * Math.PI * 0.5);
      const startAngle = -2.3;
      const headAngle = startAngle + eased * 2.65;
      const tailAngle = Math.max(startAngle, headAngle - 1.6);
      const segments = Math.max(3, Math.round(7 * state.performance.trailScale));
      const seed = (attack.attackSerial || 0) * 7 + fighter.side * 131;
      const pivotX = 8;
      const pivotY = -126;
      const headWidth = strong ? 19 : 13;
      ctx.save();
      for (let seg = 0; seg < segments; seg += 1) {
        const t0 = seg / segments;
        const t1 = (seg + 1) / segments;
        const a0 = lerp(tailAngle, headAngle, t0);
        const a1 = lerp(tailAngle, headAngle, t1);
        const r0 = reach * (0.62 + 0.3 * t0) * (0.97 + presentationHash01(seed, seg) * 0.06);
        const r1 = reach * (0.62 + 0.3 * t1) * (0.97 + presentationHash01(seed, seg + 1) * 0.06);
        ctx.globalAlpha = clamp(activePower, 0, 1) * (0.12 + 0.62 * t1 * t1)
          * ribbonFade * ribbonFade;
        ctx.lineWidth = Math.max(1, headWidth * t1);
        ctx.beginPath();
        ctx.moveTo(pivotX + Math.cos(a0) * r0, pivotY + Math.sin(a0) * r0);
        ctx.quadraticCurveTo(
          pivotX + Math.cos((a0 + a1) * 0.5) * (r0 + r1) * 0.515,
          pivotY + Math.sin((a0 + a1) * 0.5) * (r0 + r1) * 0.515,
          pivotX + Math.cos(a1) * r1,
          pivotY + Math.sin(a1) * r1,
        );
        ctx.stroke();
        // White-hot core on the leading edge so the arc pops off dark stages.
        // BODY-FIRST (spec 7): SPECIALS ONLY — on heavies the near-invisible
        // accent ribbon left this core floating as an orphan thin white
        // slash; the heavy's smear is the limb wedge, which carries its own
        // attached hot edge.
        if (seg === segments - 1 && strong) {
          ctx.strokeStyle = "#fff6df";
          ctx.globalAlpha = clamp(activePower, 0, 1) * 0.5 * ribbonFade * ribbonFade;
          ctx.lineWidth = Math.max(1, headWidth * 0.34);
          ctx.stroke();
          ctx.strokeStyle = fighter.def.accent;
        }
      }
      ctx.restore();
      if (!reflectionPassActive) presentationDebug.swipeRibbons += 1;
    }
  }

  if (fighter.def.vfx === "seismic") {
    // BODY-FIRST (spec 8): the ground answer is a textured CRACKED-STREET
    // decal in the stage-scar language — chalky scuff pad, pale chipped
    // edges over dark fissures fanning forward from the impact — replacing
    // the old dashed vector ellipse + zigzag strokes that read as a diagram.
    // Deterministic per swing (attackSerial-hashed) and drawn in the
    // fighter's local space, so it rides the extension lunge and mirrors
    // with the body.
    const crackSeed = (attack.attackSerial || 0) * 13 + fighter.side * 57;
    const spread = strong ? 1 : 0.62;
    ctx.save();
    ctx.globalCompositeOperation = "source-over";
    ctx.shadowBlur = 0;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.globalAlpha = clamp(activePower, 0, 1) * 0.4;
    ctx.fillStyle = "rgba(196,184,164,0.6)";
    ctx.beginPath();
    ctx.ellipse(64 * spread, -3, 58 * spread, 11 * spread, 0, 0, Math.PI * 2);
    ctx.fill();
    for (let crack = 0; crack < (strong ? 5 : 3); crack += 1) {
      const fan = -0.55 + presentationHash01(crackSeed, crack) * 1.1; // forward fan
      const jags = 3 + Math.floor(presentationHash01(crackSeed, crack + 9) * 2);
      const rootX = 26 + presentationHash01(crackSeed, crack + 17) * 30;
      for (const [style, width, lift, alphaMul] of [
        ["rgba(240,230,208,0.85)", 3.1, -1.3, 0.95],
        ["rgba(12,10,9,0.94)", 2.1, 0, 0.8],
      ]) {
        ctx.strokeStyle = style;
        ctx.lineWidth = width * (strong ? 1.3 : 1);
        ctx.globalAlpha = clamp(activePower, 0, 1) * alphaMul;
        ctx.beginPath();
        ctx.moveTo(rootX, -2 + lift);
        let px = rootX;
        let py = -2;
        for (let jag = 0; jag < jags; jag += 1) {
          const bend = fan + (presentationHash01(crackSeed, crack * 7 + jag) - 0.5) * 1.2;
          const length = (14 + presentationHash01(crackSeed, crack * 11 + jag) * 22) * spread;
          px += Math.cos(bend) * length;
          py += Math.sin(bend) * length * 0.3; // floor foreshortening
          ctx.lineTo(px, py + lift);
        }
        ctx.stroke();
      }
    }
    ctx.restore();
  } else if (fighter.def.vfx === "paint") {
    for (let i = 0; i < (strong ? 11 : 6); i += 1) {
      const x = 44 + i * 13;
      const y = -126 + Math.sin(i * 2.1 + time * 0.018) * (22 + i * 2);
      ctx.globalAlpha = activePower * (0.45 + (i % 3) * 0.2);
      ctx.beginPath(); ctx.arc(x, y, 3 + (i % 4) * 2.1, 0, Math.PI * 2); ctx.fill();
    }
  } else if (fighter.def.vfx === "voltage") {
    ctx.lineWidth = strong ? 8 : 4;
    for (let row = -1; row <= 1; row += 1) {
      ctx.beginPath(); ctx.moveTo(24, -130 + row * 22);
      for (let i = 1; i <= 6; i += 1) ctx.lineTo(24 + i * reach / 6, -130 + row * 22 + (i % 2 ? -12 : 12));
      ctx.stroke();
    }
  } else if (fighter.def.vfx === "neon") {
    ctx.lineWidth = strong ? 12 : 6;
    ctx.beginPath(); ctx.arc(28, -128, reach * 0.78, -1.12, 1.1); ctx.stroke();
    ctx.strokeStyle = fighter.def.color;
    ctx.lineWidth *= 0.38;
    ctx.beginPath(); ctx.arc(34, -128, reach * 0.66, -1.05, 1.03); ctx.stroke();
  } else if (fighter.def.vfx === "steel") {
    ctx.lineWidth = strong ? 8 : 4;
    ctx.beginPath(); ctx.arc(reach * 0.72, -118, 34 * pulse, 0, Math.PI * 2); ctx.stroke();
    for (let i = -2; i <= 2; i += 1) {
      ctx.beginPath(); ctx.moveTo(38, -118 + i * 17); ctx.lineTo(reach + 24, -118 + i * 8); ctx.stroke();
    }
  } else if (fighter.def.vfx === "gilded") {
    ctx.lineWidth = strong ? 16 : 8;
    ctx.beginPath(); ctx.arc(20, -130, reach * 0.86, -1.15, 1.15); ctx.stroke();
  } else if (fighter.def.vfx === "feedback") {
    ctx.lineWidth = strong ? 8 : 4;
    for (let i = 0; i < 4; i += 1) {
      ctx.globalAlpha = activePower * (1 - i * 0.18);
      ctx.beginPath(); ctx.ellipse(48 + i * 35, -128, 17 + i * 9, 49 + i * 8, 0, 0, Math.PI * 2); ctx.stroke();
    }
  } else if (fighter.def.vfx === "bass") {
    ctx.lineWidth = strong ? 10 : 5;
    for (let i = 0; i < 4; i += 1) {
      ctx.globalAlpha = activePower * (1 - i * 0.17);
      ctx.beginPath(); ctx.arc(42, -125, 35 + i * 31, -0.9, 0.9); ctx.stroke();
    }
  } else if (fighter.def.vfx === "authority") {
    ctx.strokeStyle = fighter.def.accent;
    ctx.lineWidth = strong ? 9 : 5;
    ctx.beginPath();
    ctx.moveTo(18, -172);
    ctx.lineTo(reach + 28, -84);
    ctx.stroke();
    ctx.fillStyle = "#f7e4ae";
    for (let seal = 0; seal < 3; seal += 1) {
      ctx.globalAlpha = activePower * (0.85 - seal * 0.18);
      ctx.strokeRect(62 + seal * 36, -158 + seal * 18, 26, 26);
    }
  }
  ctx.restore();
}

function drawPaintTraps(time) {
  for (const trap of state.traps) {
    ctx.save();
    ctx.translate(trap.x, trap.y);
    drawPaintTrapWith(ctx, trap, time);
    if (state.debug) {
      ctx.globalAlpha = 0.82;
      ctx.strokeStyle = "#ffef5a";
      ctx.setLineDash([7, 5]);
      ctx.strokeRect(-trap.radius, -80, trap.radius * 2, 84);
      ctx.setLineDash([]);
    }
    ctx.restore();
  }
}

// The trap drawing itself, origin at the trap's floor point, on ANY 2D
// context: the 2D world pass hands it the game canvas; CINEMA 3D paints it
// into an impostor canvas over the host bridge (world-objects.mjs), so both
// renderers draw Post's hazard from one function. Presentation-only reads.
function drawPaintTrapWith(c, trap, time) {
  const armed = trap.armFrames <= 0;
  const life = clamp(trap.lifeFrames / trap.maxLifeFrames, 0, 1);
  const pulse = 1 + Math.sin(time * 0.009 + trap.x * 0.02) * 0.08;
  c.globalAlpha = Math.min(1, life * 1.8) * (armed ? 0.9 : 0.58);
  c.fillStyle = trap.color;
  c.shadowColor = trap.color;
  c.shadowBlur = armed ? 21 : 9;
  c.beginPath();
  c.ellipse(0, 1, trap.radius * 0.86 * pulse, 14 * pulse, 0, 0, Math.PI * 2);
  c.fill();
  c.globalAlpha *= 0.55;
  c.fillStyle = "#fff2c6";
  for (let spot = 0; spot < 6; spot += 1) {
    const angle = spot * 2.4;
    c.beginPath();
    c.ellipse(Math.cos(angle) * trap.radius * 0.52, -3 + Math.sin(angle) * 7, 6 + spot % 3 * 2, 3, angle, 0, Math.PI * 2);
    c.fill();
  }
  c.globalAlpha = Math.min(1, life * 1.8);
  c.fillStyle = "#d9d9d9";
  c.fillRect(-7, -23, 14, 25);
  c.fillStyle = trap.color;
  c.fillRect(-7, -18, 14, 10);
  c.strokeStyle = armed ? "#fff" : trap.color;
  c.lineWidth = armed ? 3 : 2;
  c.globalAlpha *= armed ? 0.75 : 0.35;
  c.beginPath();
  c.ellipse(0, 0, trap.radius * pulse, 20 * pulse, 0, 0, Math.PI * 2);
  c.stroke();
}

// Each personal object is drawn as a recognisable physical thing rather than a
// recoloured orb, so its flight path and weight read at a glance.
function drawThrowable(projectile, time, life) {
  drawThrowableWith(ctx, projectile, time, life);
}

// Same drawing on ANY 2D context. CINEMA 3D paints each live object through
// this into a per-object impostor canvas (renderer/three/world-objects.mjs),
// so the painted pizza wheel, cane, needle... are the SAME drawings in both
// renderers. `options.cable === false` skips the mouse's trailing cable
// (world-space geometry the 3D layer draws as its own line).
function drawThrowableWith(c, projectile, time, life, options = {}) {
  const w = projectile.width;
  const h = projectile.height;
  const angle = projectile.spinAngle || 0;
  const wobble = projectile.wobble ? Math.sin(time * 0.02) * projectile.wobble * 0.01 : 0;
  c.globalAlpha = Math.min(1, life * 2.2);
  switch (projectile.style) {
    case "pizza": {
      if (cinema3dDressingActive()) {
        // CINEMA 3D: the painted pizza-on-cutter wheel (crust blisters,
        // mottled cheese, cupped pepperoni, rusted steel rim with a cold
        // specular) + radial motion smear ghosts trailing the spin. The
        // classic 2D primitives below stay byte-identical with 3D off.
        const hd = fatalityPizzaCanvas();
        const rim = fatalityPizzaRimCanvas();
        c.rotate(angle + wobble);
        const d = w * 1.04;
        c.drawImage(hd, -d / 2, -d / 2, d, d);
        // trailing RIM ghosts: the motion blur lives on the spinning edge —
        // the face detail stays printed once (no doubled pepperoni).
        c.save();
        c.globalAlpha *= 0.3;
        c.rotate(-0.1);
        c.drawImage(rim, -d / 2, -d / 2, d, d);
        c.rotate(-0.12);
        c.globalAlpha *= 0.55;
        c.drawImage(rim, -d / 2, -d / 2, d, d);
        c.restore();
        // rim speed smears: short bright arcs whipping off the cutting edge
        c.strokeStyle = "rgba(255,244,225,0.55)";
        c.lineCap = "round";
        c.lineWidth = Math.max(1.5, w * 0.02);
        for (let s = 0; s < 3; s += 1) {
          const a0 = s * 2.1 + 0.4;
          c.beginPath();
          c.arc(0, 0, w * 0.52, a0, a0 + 0.5);
          c.stroke();
        }
        break;
      }
      c.rotate(angle + wobble);
      c.fillStyle = "#e8b23a";
      c.beginPath();
      c.arc(0, 0, w * 0.5, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#c9812a";
      c.beginPath();
      c.arc(0, 0, w * 0.42, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#f2e2b4";
      c.beginPath();
      c.arc(0, 0, w * 0.36, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#c4402a";
      for (let i = 0; i < 6; i += 1) {
        const a = (i / 6) * Math.PI * 2;
        c.beginPath();
        c.arc(Math.cos(a) * w * 0.2, Math.sin(a) * w * 0.2, w * 0.06, 0, Math.PI * 2);
        c.fill();
      }
      c.strokeStyle = "rgba(120,70,20,.5)";
      c.lineWidth = 2;
      for (let i = 0; i < 8; i += 1) {
        const a = (i / 8) * Math.PI * 2;
        c.beginPath();
        c.moveTo(0, 0);
        c.lineTo(Math.cos(a) * w * 0.5, Math.sin(a) * w * 0.5);
        c.stroke();
      }
      break;
    }
    case "mouse": {
      // Cable trailing back toward the thrower.
      const owner = state.fighters[projectile.ownerSide];
      if (owner && options.cable !== false) {
        const back = (owner.x - projectile.x) * (Math.sign(projectile.vx) || 1);
        c.strokeStyle = "#8a93a5";
        c.lineWidth = 3;
        c.beginPath();
        c.moveTo(0, 0);
        for (let i = 1; i <= 8; i += 1) {
          const t = i / 8;
          c.lineTo(back * t, Math.sin(t * Math.PI * 2 + time * 0.02) * 9 * (1 - t));
        }
        c.stroke();
      }
      c.rotate(Math.sin(angle) * 0.2);
      c.fillStyle = "#e3e8f0";
      c.beginPath();
      c.ellipse(0, 0, w * 0.5, h * 0.5, 0, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#5b6474";
      c.fillRect(-w * 0.06, -h * 0.5, w * 0.12, h * 0.42);
      c.fillStyle = "#7fe9ff";
      c.beginPath();
      c.arc(w * 0.18, 0, h * 0.14, 0, Math.PI * 2);
      c.fill();
      break;
    }
    case "loogie": {
      c.fillStyle = "#b9e37a";
      c.beginPath();
      c.ellipse(0, 0, w * 0.5, h * 0.42, Math.atan2(projectile.vy, projectile.vx) * 0.35, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "rgba(223,243,184,.75)";
      c.beginPath();
      c.ellipse(-w * 0.12, -h * 0.12, w * 0.18, h * 0.16, 0, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = "rgba(137,184,79,.7)";
      c.lineWidth = 2;
      c.beginPath();
      c.moveTo(-w * 0.5, h * 0.1);
      c.quadraticCurveTo(-w * 0.9, 0, -w * 1.2, h * 0.2);
      c.stroke();
      break;
    }
    case "wires": {
      const uncoiled = projectile.hazard;
      c.strokeStyle = "#4f5b70";
      c.lineWidth = 4;
      const coils = uncoiled ? 5 : 7;
      for (let i = 0; i < coils; i += 1) {
        const spread = uncoiled ? w * 0.5 : w * 0.3;
        c.strokeStyle = i % 2 ? "#4f5b70" : "#7b3fa0";
        c.beginPath();
        if (uncoiled) {
          c.moveTo(-spread + (i / coils) * spread * 2, h * 0.2);
          c.quadraticCurveTo(
            -spread + ((i + 0.5) / coils) * spread * 2,
            h * 0.2 - 16 - Math.sin(time * 0.01 + i) * 5,
            -spread + ((i + 1) / coils) * spread * 2,
            h * 0.2,
          );
        } else {
          c.arc(0, 0, w * 0.2 + i * 3, angle + i, angle + i + 4.2);
        }
        c.stroke();
      }
      break;
    }
    case "xacto": {
      c.save();
      c.globalCompositeOperation = "screen";
      c.globalAlpha = 0.35 + Math.abs(Math.sin(time * 0.022)) * 0.55;
      c.strokeStyle = "#ffffff";
      c.lineWidth = 2;
      c.beginPath(); c.moveTo(-w * 0.85, 0); c.lineTo(-w * 0.2, 0); c.stroke();
      c.restore();
      c.rotate(Math.atan2(projectile.vy, Math.abs(projectile.vx)));
      c.fillStyle = "#2b3038";
      c.fillRect(-w * 0.5, -h * 0.5, w * 0.45, h);
      c.fillStyle = "#dfe6f0";
      c.beginPath();
      c.moveTo(-w * 0.05, -h * 0.5);
      c.lineTo(w * 0.5, 0);
      c.lineTo(-w * 0.05, h * 0.5);
      c.closePath();
      c.fill();
      c.strokeStyle = "rgba(255,255,255,.7)";
      c.lineWidth = 1.5;
      c.beginPath();
      c.moveTo(-w * 0.05, 0);
      c.lineTo(w * 0.5, 0);
      c.stroke();
      break;
    }
    case "golfball": {
      c.globalAlpha *= 0.52;
      c.fillStyle = "#ffffff";
      for (let trail = 1; trail <= 3; trail += 1) {
        c.beginPath();
        c.arc(-w * (0.55 + trail * 0.32), 0, Math.max(2, w * (0.15 - trail * 0.025)), 0, Math.PI * 2);
        c.fill();
      }
      c.globalAlpha = Math.min(1, life * 2.2);
      c.rotate(angle);
      c.fillStyle = "#ffffff";
      c.beginPath();
      c.arc(0, 0, w * 0.5, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "rgba(150,165,185,.55)";
      for (let i = 0; i < 7; i += 1) {
        const a = (i / 7) * Math.PI * 2;
        c.beginPath();
        c.arc(Math.cos(a) * w * 0.24, Math.sin(a) * w * 0.24, w * 0.06, 0, Math.PI * 2);
        c.fill();
      }
      break;
    }
    case "bedbugs": {
      const swarm = projectile.hazard ? 9 : 6;
      for (let i = 0; i < swarm; i += 1) {
        const phase = time * 0.01 + i * 1.7;
        const bx = Math.cos(phase) * w * (projectile.hazard ? 0.45 : 0.28);
        const by = Math.sin(phase * 1.4) * h * 0.3;
        c.fillStyle = i % 3 ? "#7a3a2c" : "#c4552f";
        c.beginPath();
        c.ellipse(bx, by, 6, 4.4, phase, 0, Math.PI * 2);
        c.fill();
        c.strokeStyle = "rgba(40,20,14,.8)";
        c.lineWidth = 1.2;
        for (let leg = -1; leg <= 1; leg += 2) {
          c.beginPath();
          c.moveTo(bx, by);
          c.lineTo(bx + leg * 6, by + Math.sin(phase * 3) * 4);
          c.stroke();
        }
      }
      break;
    }
    case "vinyl": {
      c.save();
      c.globalAlpha = 0.22 + Math.abs(Math.sin(time * 0.018)) * 0.2;
      c.strokeStyle = "#ff4fb9";
      c.lineWidth = 2;
      for (let ring = 1; ring <= 2; ring += 1) {
        c.beginPath();
        c.ellipse(0, 0, w * (0.5 + ring * 0.22), h * (0.32 + ring * 0.12), 0, 0, Math.PI * 2);
        c.stroke();
      }
      c.restore();
      c.rotate(angle);
      c.fillStyle = "#16161a";
      c.beginPath();
      c.arc(0, 0, w * 0.5, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = "rgba(216,216,210,.28)";
      c.lineWidth = 1.4;
      for (let r = 3; r < 5; r += 1) {
        c.beginPath();
        c.arc(0, 0, w * 0.5 * (r / 6), 0, Math.PI * 2);
        c.stroke();
      }
      c.fillStyle = "#ff4fb9";
      c.beginPath();
      c.arc(0, 0, w * 0.17, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#16161a";
      c.beginPath();
      c.arc(0, 0, w * 0.04, 0, Math.PI * 2);
      c.fill();
      break;
    }
    // Wave 16 — the Commissioner's steel cane: a hard end-over-end steel shaft
    // with a gold crook and ferrule, so the flat authority throw reads at a
    // glance against every other object in the set.
    case "cane": {
      c.rotate(angle);
      const shaft = w * 0.94;
      // steel shaft with a cold top highlight
      c.fillStyle = "#3b4150";
      c.fillRect(-shaft * 0.5, -h * 0.18, shaft, h * 0.36);
      c.fillStyle = "rgba(214,222,236,.5)";
      c.fillRect(-shaft * 0.5, -h * 0.18, shaft, h * 0.12);
      // gold crook handle
      c.strokeStyle = "#d6b56b";
      c.lineWidth = h * 0.3;
      c.beginPath();
      c.arc(-shaft * 0.5, -h * 0.5, h * 0.42, Math.PI * 0.15, Math.PI * 1.2);
      c.stroke();
      // gold ferrule tip
      c.fillStyle = "#d6b56b";
      c.fillRect(shaft * 0.5 - w * 0.08, -h * 0.22, w * 0.08, h * 0.44);
      break;
    }
    case "needle": {
      c.rotate(Math.atan2(projectile.vy, Math.abs(projectile.vx) || 1));
      c.fillStyle = "#cfd6e2";
      c.fillRect(-w * 0.5, -h * 0.35, w * 0.7, h * 0.7);
      c.fillStyle = "#e9edf5";
      c.beginPath();
      c.moveTo(w * 0.2, -h * 0.2);
      c.lineTo(w * 0.5, 0);
      c.lineTo(w * 0.2, h * 0.2);
      c.closePath();
      c.fill();
      c.fillStyle = "#ff6b5a";
      c.fillRect(-w * 0.5, -h * 0.5, w * 0.16, h);
      break;
    }
    case "bottle": {
      c.rotate(angle);
      c.fillStyle = "rgba(96,148,72,.92)";
      c.beginPath();
      c.moveTo(-w * 0.32, h * 0.5);
      c.lineTo(w * 0.32, h * 0.5);
      c.lineTo(w * 0.32, -h * 0.05);
      c.lineTo(w * 0.14, -h * 0.3);
      c.lineTo(w * 0.14, -h * 0.5);
      c.lineTo(-w * 0.14, -h * 0.5);
      c.lineTo(-w * 0.14, -h * 0.3);
      c.lineTo(-w * 0.32, -h * 0.05);
      c.closePath();
      c.fill();
      c.fillStyle = "rgba(240,248,220,.55)";
      c.fillRect(-w * 0.2, -h * 0.02, w * 0.1, h * 0.42);
      c.fillStyle = "#d8b24a";
      c.fillRect(-w * 0.3, h * 0.06, w * 0.6, h * 0.2);
      break;
    }
    case "pigeon": {
      c.rotate(angle * 0.6);
      c.fillStyle = "#6f7684";
      c.beginPath();
      c.ellipse(0, 0, w * 0.42, h * 0.32, 0, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#8c93a3";
      c.beginPath();
      c.ellipse(-w * 0.28, -h * 0.1, w * 0.16, h * 0.2, 0.4, 0, Math.PI * 2);
      c.fill();
      c.fillStyle = "#585f6c";
      c.beginPath();
      c.ellipse(w * 0.3, -h * 0.16, w * 0.14, h * 0.16, 0, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = "#ff9a4a";
      c.lineWidth = 3;
      c.beginPath();
      c.moveTo(-w * 0.1, h * 0.28);
      c.lineTo(-w * 0.24, h * 0.5);
      c.stroke();
      break;
    }
    case "tongs": {
      c.rotate(angle);
      c.strokeStyle = "#d5dce8";
      c.lineWidth = 4;
      c.beginPath();
      c.moveTo(-w * 0.5, -h * 0.4);
      c.lineTo(w * 0.5, 0);
      c.moveTo(-w * 0.5, h * 0.4);
      c.lineTo(w * 0.5, 0);
      c.stroke();
      c.strokeStyle = "#9fb0c6";
      c.lineWidth = 2;
      c.beginPath();
      c.arc(-w * 0.5, 0, h * 0.4, -1.4, 1.4);
      c.stroke();
      break;
    }
    case "cup": {
      c.rotate(angle * 0.5);
      c.fillStyle = "#ff5aa8";
      c.beginPath();
      c.moveTo(-w * 0.34, -h * 0.5);
      c.lineTo(w * 0.34, -h * 0.5);
      c.lineTo(w * 0.22, h * 0.5);
      c.lineTo(-w * 0.22, h * 0.5);
      c.closePath();
      c.fill();
      c.fillStyle = "rgba(255,255,255,.55)";
      c.fillRect(-w * 0.3, -h * 0.44, w * 0.6, h * 0.12);
      c.strokeStyle = "#7fe9ff";
      c.lineWidth = 4;
      c.beginPath();
      c.moveTo(w * 0.1, -h * 0.5);
      c.lineTo(w * 0.34, -h * 0.9);
      c.stroke();
      break;
    }
    // 5.3 SPECTACLE: Janney's half brick. A fired-clay block with a broken
    // end (the half it snapped at), a mortar crumb line along the bottom and
    // a lit top face, so it reads as masonry at 48x26 rather than a red bar.
    case "brick": {
      c.rotate(angle);
      const bw = w * 0.5;
      const bh = h * 0.5;
      c.fillStyle = "#8d4432";
      c.beginPath();
      c.moveTo(-bw, -bh);
      c.lineTo(bw * 0.78, -bh);
      // the snapped end: a ragged vertical break
      c.lineTo(bw, -bh * 0.42);
      c.lineTo(bw * 0.84, 0);
      c.lineTo(bw, bh * 0.5);
      c.lineTo(bw * 0.8, bh);
      c.lineTo(-bw, bh);
      c.closePath();
      c.fill();
      // sunlit top face
      c.fillStyle = "rgba(214,132,92,0.85)";
      c.fillRect(-bw, -bh, bw * 1.72, bh * 0.42);
      // shadowed underside + clinging mortar crumbs
      c.fillStyle = "rgba(48,24,16,0.55)";
      c.fillRect(-bw, bh * 0.46, bw * 1.7, bh * 0.54);
      c.fillStyle = "rgba(206,198,182,0.75)";
      for (let crumb = 0; crumb < 4; crumb += 1) {
        const cx = -bw + bw * 0.42 * crumb + bw * 0.1;
        c.fillRect(cx, bh * 0.52, bw * 0.2, bh * 0.24);
      }
      // pitted face: three dark aggregate specks
      c.fillStyle = "rgba(58,28,18,0.5)";
      for (let pit = 0; pit < 3; pit += 1) {
        c.fillRect(-bw * 0.6 + pit * bw * 0.52, -bh * 0.1 + (pit % 2) * bh * 0.3, bw * 0.14, bh * 0.18);
      }
      break;
    }
    default: {
      c.fillStyle = projectile.color;
      c.beginPath();
      c.arc(0, 0, w * 0.5, 0, Math.PI * 2);
      c.fill();
    }
  }
  c.globalAlpha = 1;
}

// The grounded weapon and its arrival telegraph. Both fighters can see exactly
// where and when it lands, so the pickup is always contestable.
function drawStageWeapon(time) {
  const weapon = state.stageWeapon;
  if (!weapon || !["telegraph", "ground"].includes(weapon.phase)) return;
  const profile = stageWeaponProfile();
  if (!profile) return;
  const telegraphing = weapon.phase === "telegraph";
  const progress = telegraphing ? clamp(weapon.frames / Math.max(1, profile.telegraphFrames), 0, 1) : 1;
  const remaining = telegraphing ? 1 : 1 - clamp(weapon.frames / Math.max(1, profile.groundFrames), 0, 1);
  // 5.3 SPECTACLE (#18): the arrival comes off a named piece of this stage
  // and travels its own path to the slot. The landing MARK stays exactly
  // where and when it was (the pickup has to be as contestable as it was in
  // 5.2) but wears the stage's colour, and the vertical gold drop-streak is
  // gone — the object's real path is the telegraph now.
  const arrival = getWeaponArrival(weapon.stageId);
  const tint = arrival?.tint || "#ffd54a";
  const origin = arrival ? weaponArrivalOrigin(weapon.stageId, weapon.x, {
    floor: FLOOR,
    minX: MOVEMENT_RULES.stageMinX,
    maxX: MOVEMENT_RULES.stageMaxX,
  }) : null;
  const poseAt = (p) => (telegraphing
    ? weaponArrivalPose(weapon.stageId, weapon.x, p, {
      floor: FLOOR,
      minX: MOVEMENT_RULES.stageMinX,
      maxX: MOVEMENT_RULES.stageMaxX,
    })
    : { x: weapon.x, y: FLOOR, angle: 0, leg: "rest", airborne: false });
  ctx.save();
  ctx.translate(weapon.x, FLOOR);

  // MOTION FIX 9: the landing marker is a ground SCORCH/SCUFF — a warm
  // irregular burn patch with ragged scuff strokes in the stage-scar visual
  // language — instead of a clean gold vector ellipse. Same pulse, same
  // footprint, so the pickup stays exactly as contestable/readable as before.
  const markPulse = telegraphing ? 0.35 + 0.4 * Math.abs(Math.sin(time * 0.012)) : 0.28 + remaining * 0.3;
  const markReach = 46 * FIGHTER_SCALE * (telegraphing ? 0.6 + progress * 0.6 : 1);
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = markPulse * 0.85;
  const scorch = ctx.createRadialGradient(0, 4, 3, 0, 4, markReach);
  scorch.addColorStop(0, "rgba(255,213,74,0.55)");
  scorch.addColorStop(0.55, "rgba(214,142,38,0.28)");
  scorch.addColorStop(1, "rgba(120,70,18,0)");
  ctx.fillStyle = scorch;
  ctx.save();
  ctx.scale(1, 0.3);
  ctx.beginPath();
  ctx.arc(0, 13, markReach, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.restore();
  // Ragged scuff strokes: short charred flecks at hashed angles/reach — the
  // irregular edge that makes it a burn mark, not a ring. Every third fleck
  // takes the stage's arrival colour (feather grey, slush blue, brick red)
  // so the slot is already wearing what is about to land on it.
  ctx.lineCap = "round";
  for (let fleck = 0; fleck < 7; fleck += 1) {
    const angle = fleck * 0.9 + presentationHash01(Math.round(weapon.x), fleck) * 0.8;
    const reach = markReach * (0.55 + presentationHash01(fleck, 11) * 0.5);
    const fx = Math.cos(angle) * reach;
    const fy = 4 + Math.sin(angle) * reach * 0.28;
    ctx.globalAlpha = markPulse * (0.5 + (fleck % 3) * 0.18);
    ctx.strokeStyle = fleck % 3 === 2 ? tint : fleck % 2 ? "#c98a2e" : "#3a2c16";
    ctx.lineWidth = 2.5 + (fleck % 3);
    ctx.beginPath();
    ctx.moveTo(fx, fy);
    ctx.lineTo(fx + Math.cos(angle) * 10, fy + Math.sin(angle) * 3);
    ctx.stroke();
  }
  ctx.restore();

  if (telegraphing && arrival && origin) {
    // The source flourish: the furniture being disturbed. Short strokes
    // kicking off the stairs / rail / counter / chair / wall, fading out over
    // the first third of the arrival, so the eye starts THERE and follows the
    // object down instead of watching a column of light.
    const kick = clamp(1 - progress / 0.35, 0, 1);
    if (kick > 0.01) {
      ctx.save();
      ctx.translate(origin.x, origin.y);
      ctx.globalAlpha = kick * 0.75;
      ctx.strokeStyle = tint;
      ctx.lineCap = "round";
      for (let spoke = 0; spoke < 5; spoke += 1) {
        const angle = -Math.PI * 0.5 + (spoke - 2) * 0.42;
        const reach = 10 + (1 - kick) * 22 + presentationHash01(spoke, 7) * 10;
        ctx.lineWidth = 3 - spoke * 0.3;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle) * 6, Math.sin(angle) * 6);
        ctx.lineTo(Math.cos(angle) * reach, Math.sin(angle) * reach);
        ctx.stroke();
      }
      ctx.globalAlpha = kick * 0.4;
      ctx.fillStyle = tint;
      ctx.beginPath();
      ctx.ellipse(0, 6, 20, 5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    // The path itself: ghost puffs sampled BACKWARD along the choreography,
    // so a lob draws its arc, a slide draws the counter line and a skitter
    // draws the scrape it just made.
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.fillStyle = tint;
    for (let step = 1; step <= 6; step += 1) {
      const p = progress - step * 0.05;
      if (p <= 0) break;
      const ghost = poseAt(p);
      ctx.globalAlpha = 0.34 * (1 - step / 7);
      ctx.beginPath();
      ctx.ellipse(ghost.x, ghost.y - 12, 10 - step, (10 - step) * (ghost.airborne ? 1 : 0.45), 0, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // The object, on its path (or resting on the slot once it has landed).
  const pose = poseAt(progress);
  ctx.save();
  ctx.globalAlpha = telegraphing ? clamp(progress * 4, 0, 1) : 1;
  ctx.translate(pose.x, pose.y - profile.height * 0.5 * FIGHTER_SCALE
    + (telegraphing ? 0 : Math.sin(time * 0.006) * 2));
  drawThrowable({
    style: profile.style,
    width: profile.width * FIGHTER_SCALE,
    height: profile.height * FIGHTER_SCALE,
    spinAngle: telegraphing ? pose.angle : 0,
    vx: 1,
    vy: 0,
    color: "#ffd54a",
    ownerSide: -1,
    hazard: false,
  }, time, 1);

  if (profile.glint) {
    ctx.globalCompositeOperation = "screen";
    ctx.globalAlpha = 0.4 + 0.6 * Math.abs(Math.sin(time * 0.02));
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    for (const angle of [0, Math.PI / 2]) {
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * -22, Math.sin(angle) * -22);
      ctx.lineTo(Math.cos(angle) * 22, Math.sin(angle) * 22);
      ctx.stroke();
    }
  }
  ctx.restore();

  // Name tag so the object is identifiable without knowing the stage. It
  // stays over the SLOT, never over the travelling object: the tag is the
  // contest read ("it lands there"), not a label stuck to the prop.
  ctx.save();
  ctx.globalAlpha = telegraphing ? progress : 0.55 + remaining * 0.45;
  ctx.font = "900 15px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillStyle = "#ffd54a";
  ctx.strokeStyle = "rgba(0,0,0,.75)";
  ctx.lineWidth = 4;
  ctx.strokeText(profile.name, weapon.x, FLOOR - profile.height * FIGHTER_SCALE - 26);
  ctx.fillText(profile.name, weapon.x, FLOOR - profile.height * FIGHTER_SCALE - 26);
  ctx.restore();
}

function drawProjectiles(time) {
  for (const projectile of state.projectiles) {
    const direction = Math.sign(projectile.vx) || projectile.direction || 1;
    const life = clamp(projectile.lifeFrames / projectile.maxLifeFrames, 0, 1);
    const pulse = 1 + Math.sin(time * 0.018 + projectile.x * 0.03) * 0.11;
    // Travelling light pool (wave 4): every projectile and thrown object casts
    // an additive colour glow onto the floor beneath it, brightening as it
    // flies lower. Sibling of the throwable ground shadow; the battery
    // profile (shadows off) skips it.
    if (state.performance.shadows && projectile.y < FLOOR + 4) {
      const height = Math.max(0, FLOOR - projectile.y);
      const closeness = clamp(1 - height / 620, 0.25, 1);
      const reach = ((projectile.width || 44) * 1.6 + 52) * (0.8 + closeness * 0.4);
      const channels = /^#[0-9a-fA-F]{6}/.test(projectile.color || "")
        ? hexToRgbChannels(projectile.color)
        : "255,240,200";
      const glowAlpha = 0.42 * closeness * Math.min(1, life * 2) * pulse;
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.translate(projectile.x, FLOOR + 4);
      ctx.scale(1, 0.24);
      const poolGlow = ctx.createRadialGradient(0, 0, 6, 0, 0, reach);
      poolGlow.addColorStop(0, `rgba(${channels},${clamp(glowAlpha, 0, 0.55).toFixed(3)})`);
      poolGlow.addColorStop(1, `rgba(${channels},0)`);
      ctx.fillStyle = poolGlow;
      ctx.beginPath();
      ctx.arc(0, 0, reach, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      presentationDebug.projectileGlows += 1;
    }
    // MOTION FIX 10: the lobbed charm reads as ONE continuous arc — an
    // analytic mist tail integrated BACKWARD along the exact ballistic path
    // (x−vxΔ, y−vyΔ+½gΔ²), so however sparsely the flight is sampled, every
    // frame carries the arc it just travelled. Fading pine-mist puffs + a
    // thin path core, drawn before the orb so the head stays crisp.
    if (projectile.throwable && projectile.style === "charm"
      && !state.accessibility.reducedMotion && state.performance.trailScale > 0) {
      const gravity = projectile.gravity ?? 1200;
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      let prevTailX = projectile.x;
      let prevTailY = projectile.y;
      for (let step = 1; step <= 9; step += 1) {
        const dtBack = step * 0.055;
        const tailX = projectile.x - (projectile.vx || 0) * dtBack;
        const tailY = projectile.y - (projectile.vy || 0) * dtBack + 0.5 * gravity * dtBack * dtBack;
        const fadeTail = (1 - step / 10) * Math.min(1, life * 2.2);
        const radius = Math.max(7, (projectile.width || 40) * (0.36 - step * 0.02));
        // Connective core along the path so the arc reads as one stroke...
        ctx.strokeStyle = `rgba(140,255,94,${(0.3 * fadeTail).toFixed(3)})`;
        ctx.lineWidth = Math.max(2, radius * 0.55);
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(prevTailX, prevTailY);
        ctx.lineTo(tailX, tailY);
        ctx.stroke();
        // ...wrapped in soft pine-mist puffs that hang and thin behind it.
        const mist = ctx.createRadialGradient(tailX, tailY, 1, tailX, tailY, radius * 2.4);
        mist.addColorStop(0, `rgba(140,255,94,${(0.42 * fadeTail).toFixed(3)})`);
        mist.addColorStop(0.6, `rgba(107,212,74,${(0.2 * fadeTail).toFixed(3)})`);
        mist.addColorStop(1, "rgba(107,212,74,0)");
        ctx.fillStyle = mist;
        ctx.beginPath();
        ctx.arc(tailX, tailY, radius * 2.4, 0, Math.PI * 2);
        ctx.fill();
        prevTailX = tailX;
        prevTailY = tailY;
      }
      ctx.restore();
    }
    ctx.save();
    ctx.translate(projectile.x, projectile.y);
    ctx.scale(direction, 1);
    if (projectile.throwable) {
      // Ground shadow so the arc and landing point read clearly.
      ctx.save();
      ctx.scale(direction, 1);
      ctx.fillStyle = "rgba(0,0,0,.34)";
      ctx.beginPath();
      ctx.ellipse(0, FLOOR - projectile.y, projectile.width * 0.34, 7, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      drawThrowable(projectile, time, life);
      ctx.restore();
      continue;
    }
    drawProjectileBodyWith(ctx, projectile, time, life, pulse);
    ctx.restore();
  }
}

// The non-throwable projectile body (feedback rings / the default orb + trail)
// in the projectile's own frame — origin at its centre, x already mirrored to
// its direction — on ANY 2D context, for the same reason drawThrowableWith
// exists: CINEMA 3D paints it into an impostor over the host bridge.
function drawProjectileBodyWith(c, projectile, time, life, pulse) {
  if (projectile.style === "feedback") {
    const armed = projectile.armFrames <= 0;
    const charge = projectile.maxArmFrames
      ? 1 - clamp(projectile.armFrames / projectile.maxArmFrames, 0, 1)
      : 1;
    c.globalCompositeOperation = "screen";
    c.globalAlpha = Math.min(0.95, life * 1.6) * (0.38 + charge * 0.62);
    c.shadowColor = projectile.color;
    c.shadowBlur = armed ? 30 : 17;
    c.strokeStyle = projectile.color;
    c.lineWidth = armed ? 6 : 3;
    if (!armed) c.setLineDash([9, 7]);
    for (let ring = 0; ring < 3; ring += 1) {
      const phase = (time * 0.004 + ring * 0.29) % 1;
      const radiusX = projectile.width * (0.2 + phase * 0.34) * pulse;
      const radiusY = projectile.height * (0.23 + phase * 0.28) * pulse;
      c.globalAlpha *= 0.82;
      c.beginPath();
      c.ellipse(0, 0, radiusX, radiusY, Math.sin(time * 0.002 + ring) * 0.13, 0, Math.PI * 2);
      c.stroke();
    }
    c.setLineDash([]);
    c.globalAlpha = armed ? 0.9 : 0.48;
    c.fillStyle = armed ? "#efffe8" : projectile.color;
    for (let slice = -2; slice <= 2; slice += 1) {
      const jitter = Math.sin(time * 0.03 + slice * 2.1) * 9;
      c.fillRect(-projectile.width * 0.38 + jitter, slice * projectile.height * 0.16 - 3, projectile.width * (0.7 - Math.abs(slice) * 0.08), armed ? 5 : 3);
    }
    if (state.debug) {
      c.globalCompositeOperation = "source-over";
      c.globalAlpha = 0.85;
      c.strokeStyle = "#ffef5a";
      c.strokeRect(-projectile.width * 0.5, -projectile.height * 0.5, projectile.width, projectile.height);
    }
    return;
  }
  c.globalCompositeOperation = "screen";
  c.globalAlpha = Math.min(1, life * 2);
  const trail = c.createLinearGradient(-105, 0, 20, 0);
  trail.addColorStop(0, `${projectile.color}00`);
  trail.addColorStop(0.55, `${projectile.color}78`);
  trail.addColorStop(1, projectile.color);
  c.fillStyle = trail;
  c.beginPath();
  c.moveTo(-112, 0);
  c.quadraticCurveTo(-32, -projectile.height * 0.5, 15, 0);
  c.quadraticCurveTo(-32, projectile.height * 0.5, -112, 0);
  c.fill();
  c.shadowColor = projectile.color;
  c.shadowBlur = 24;
  c.fillStyle = "#fff5b8";
  c.beginPath();
  c.ellipse(0, 0, projectile.width * 0.34 * pulse, projectile.height * 0.4 * pulse, 0, 0, Math.PI * 2);
  c.fill();
  c.strokeStyle = projectile.color;
  c.lineWidth = 5;
  c.beginPath();
  c.arc(0, 0, projectile.height * 0.48 * pulse, 0, Math.PI * 2);
  c.stroke();
  c.strokeStyle = "rgba(255,255,255,.82)";
  c.lineWidth = 2;
  c.beginPath();
  c.arc(-4, -4, projectile.height * 0.18, -2.7, -0.3);
  c.stroke();
  if (state.debug) {
    c.globalCompositeOperation = "source-over";
    c.globalAlpha = 0.85;
    c.strokeStyle = "#ffef5a";
    c.strokeRect(-projectile.width * 0.5, -projectile.height * 0.5, projectile.width, projectile.height);
  }
}

// 330 was 62.4% of the playable fight area; FIGHTER_SCALE lifts the roster into
// the 68-74% MK/SF2 band, and the per-fighter adjust keeps body types distinct
// without letting anyone leave that band.
const FIGHTER_RENDER_BASE = 330;
const FIGHTER_SIZE_ADJUST = Object.freeze({
  deathblow: 1.068, jez: 0.995, alan: 1.062, post: 1.04,
  benny: 1, donald: 1.02, cyraxx: 1.02, ali: 0.99, devil: 1.05, commissioner: 1.03,
});

// Per-fighter correction when a pose comes from the specials move sheet, whose
// cells frame the body slightly differently. Shared by drawFighter and the
// cast-shadow pass so both size a specials frame identically.
//
// v5.3 SPECIALS: re-derived for the regenerated sheets. A specials sheet has
// exactly ONE standing cell (the victory pose), so unlike a unified/ext sheet
// it has no standing reference to normalise against — the scale is measured
// against the sheet it replaces instead. The regeneration redraws the SAME 16
// actions, so shipped drawn height / new drawn height is that sheet's scale
// relative to the shipped one per action, and the MEDIAN over the 16 is robust
// to the few poses whose height genuinely changed. Times the shipped adjust,
// every special keeps the world size it ships at today on the new drawing.
// (assets/moves/MANIFEST.json `sheetAdjustFrom` records each derivation;
// tools/swing/install_specials.py is the measurement.)
//
//   deathblow 1.14 x 1.0131 -> 1.155   post   1.02 x 1.0041 -> 1.024
//   jez       1.03 x 0.9823 -> 1.012   donald 1.04 x 1.0398 -> 1.081
//   alan      1.06 x 0.9486 -> 1.005   devil  1.04 x 0.9664 -> 1.005
//   ali       1.04 x 0.9228 -> 0.960   benny  1.02 x 0.8453 -> 0.862
//   cyraxx    1.05 x 0.9103 -> 0.956
//
// The Commissioner is UNCHANGED at 1.02: he has no specials sheet at all (his
// kit poses address his combat atlas), so nothing about his bank moved.
const MOVE_SHEET_ADJUST = Object.freeze({
  deathblow: 1.155, jez: 1.012, alan: 1.005, post: 1.024, benny: 0.862,
  donald: 1.081, cyraxx: 0.956, ali: 0.96, devil: 1.005, commissioner: 1.02,
});

// v5.3: the generation the 5.3 sheets replaced, kept whole under
// assets/moves/legacy as the per-cell fallback (a cell whose action drifted in
// the regeneration is accept:false in assets/moves/MANIFEST.json). It is the
// SHIPPED art, so it keeps the SHIPPED table: a rejected cell draws exactly as
// it does today, at the size it does today, in both renderers.
const MOVE_SHEET_LEGACY_ADJUST = Object.freeze({
  deathblow: 1.14, jez: 1.03, alan: 1.06, post: 1.02, benny: 1.02,
  donald: 1.04, cyraxx: 1.05, ali: 1.04, devil: 1.04, commissioner: 1.02,
});

// v2.7 FRAMES: motion-bank world-size correction. The motion sheets share the
// base banks' build normalisation (tallest standing frame → 95.6% cell
// height; MANIFEST.json `scale` records each sheet's build scale), so almost
// every fighter matches base-cell world size at 1. The Commissioner's older
// base atlas normalises to the full cell (320px vs 306px measured), so his
// motion cells scale up to meet it.
// v2.9 critic round (M5): re-tuned. 1.046 was fitted to the Commissioner's
// 320px OUTLIER cell (base 10, the cane raised overhead — the tallest of his
// frames 0-11, which is what his older sheet's global normalisation filled
// the cell with). His STANDING cells measure 311-316, so the correct match
// against the authored banks' 306px standing cells is 316/306 = 1.033; the
// old value carried ~1.3% of built-in error on every cell that is not the
// outlier.
const MOTION_SHEET_ADJUST = Object.freeze({ commissioner: 1.033 });

// v2.10 WALK: the walk sheets do NOT share the motion banks' normalisation.
// Each one is scaled so its tallest key matches that fighter's own measured
// BASE WALK cell height (deathblow 304px, jez 304px), which is how their
// world size is verified — so the correction is 1.0 by construction and this
// table exists for a future sheet that cannot be normalised that way. Kept
// separate from MOTION_SHEET_ADJUST precisely so a Commissioner-style base
// registration outlier cannot silently inherit the wrong correction.
const WALK_SHEET_ADJUST = Object.freeze({});

// v3.0 UNIFIED: the unified sheets DO share the motion banks' build rule —
// MANIFEST.json records `targetH: 306` on every one of them, taken from the
// tallest STANDING figure, which is the motion2 convention exactly. So the one
// fighter whose older base atlas normalises to the full cell instead needs the
// same +3.3% here that he needs on banks 1-3. Verified by measurement this
// wave: his base standing cells are 311-316px and his unified walk keys peak
// at 306, so 316/306 = 1.033; every other fighter's base standing cells are
// 305-306 and take 1.
//
// Kept as its own table rather than folded into MOTION_SHEET_ADJUST for the
// same reason the walk bank has one: a future unified sheet built to a
// different normalisation must not silently inherit a correction fitted to
// this one.
const UNIFIED_SHEET_ADJUST = Object.freeze({ commissioner: 1.033 });

// v4.6 PRONE: how far a downed fighter's DRAWING still has to be tilted to
// lie on the street. The old fixed 1.35rad lay-down assumed an upright hit
// pose; the unified knockdown cell is authored flat on every sheet, and four
// base cells (donald, cyraxx, ali, devil) are drawn already falling back, so
// the fixed tilt stood those bodies on their heads with the feet in the air.
// Measured once per (fighter, bank, frame) from the cell's alpha: the
// principal axis of the opaque pixels gives the body's recline from vertical
// and the tilt supplies only the remainder. Render-only; never touches the sim.
const DOWN_TILT_RADIANS = 1.35;
const downTiltCache = new Map();
function downTiltFor(fighterId, bank, frame) {
  const key = `${fighterId}:${bank}:${frame}`;
  const cached = downTiltCache.get(key);
  if (cached !== undefined) return cached;
  const atlas = paletteAtlas(fighterId, 0, bank);
  const width = atlas?.naturalWidth || atlas?.width || 0;
  if (!width || (atlas instanceof HTMLImageElement && !atlas.complete)) return DOWN_TILT_RADIANS;
  const cell = Math.floor(width / 4);
  const sample = 64;
  let data;
  try {
    const scratch = document.createElement("canvas");
    scratch.width = sample;
    scratch.height = sample;
    const sctx = scratch.getContext("2d", { willReadFrequently: true });
    sctx.drawImage(atlas, (frame % 4) * cell, Math.floor(frame / 4) * cell, cell, cell, 0, 0, sample, sample);
    data = sctx.getImageData(0, 0, sample, sample).data;
  } catch {
    downTiltCache.set(key, DOWN_TILT_RADIANS);
    return DOWN_TILT_RADIANS;
  }
  let n = 0, sx = 0, sy = 0, sxx = 0, syy = 0, sxy = 0;
  for (let y = 0; y < sample; y += 1) {
    for (let x = 0; x < sample; x += 1) {
      if (data[(y * sample + x) * 4 + 3] <= 64) continue;
      n += 1; sx += x; sy += y; sxx += x * x; syy += y * y; sxy += x * y;
    }
  }
  let tilt = DOWN_TILT_RADIANS;
  if (n >= 16) {
    const mx = sx / n, my = sy / n;
    const cxx = sxx / n - mx * mx, cyy = syy / n - my * my, cxy = sxy / n - mx * my;
    const spread = Math.hypot(cxx - cyy, 2 * cxy);
    const anisotropy = spread / Math.max(1e-6, cxx + cyy);
    const major = 0.5 * Math.atan2(2 * cxy, cxx - cyy);
    const recline = Math.abs(Math.PI / 2 - Math.abs(major));
    // A compact, roundish drawing (a crumpled body) has no axis to lay down.
    tilt = anisotropy < 0.2 ? 0 : clamp(DOWN_TILT_RADIANS - recline, 0, DOWN_TILT_RADIANS);
  }
  downTiltCache.set(key, tilt);
  return tilt;
}

function bankSheetAdjust(fighterId, bank) {
  if (bank === "specials") return MOVE_SHEET_ADJUST[fighterId] || 1;
  if (bank === SPECIALS_LEGACY_BANK) return MOVE_SHEET_LEGACY_ADJUST[fighterId] || 1;
  // v2.9 FLOW: the motion2 sheets share the motion bank's build
  // normalisation, so the Commissioner's +4.6% correction applies to both
  // authored banks from the same table (both renderers read it).
  // v2.9 critic round 2: motion3 is MASS-MATCHED to the motion2 sheet by its
  // own build rule, so it inherits the same correction from the same table.
  if (bank === "motion" || bank === "motion2" || bank === "motion3") {
    return MOTION_SHEET_ADJUST[fighterId] || 1;
  }
  if (bank === "walk") return WALK_SHEET_ADJUST[fighterId] || 1;
  if (bank === UNIFIED_BANK) return UNIFIED_SHEET_ADJUST[fighterId] || 1;
  // v4.0: UNIFIED_EXT_BANK deliberately has NO branch here, and adding one is a
  // bug. The ext sheet does need the Commissioner's +3.3% — it is the same
  // generation at the same global scale — but CINEMA 3D's own sheet-adjust
  // chain tests `bankName === UNIFIED_BANK` and has no ext branch, so a
  // correction applied here would land on the 2D canvas only and the two
  // renderers would draw him at different sizes. It is folded into
  // UNIFIED_EXT_CELL_ADJUST instead, which both renderers read through
  // cellDrawAdjust. Adding it here as well would multiply the two.
  return 1;
}

function fighterRenderSize(fighterId) {
  return FIGHTER_RENDER_BASE * FIGHTER_SCALE * (FIGHTER_SIZE_ADJUST[fighterId] || 1);
}

// Deterministic 0..1 hash for aura embers: pure function of an integer seed so
// positions replay identically across rollback resimulation without touching
// either RNG stream.
function emberHash(seed) {
  const scrambled = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
  return scrambled - Math.floor(scrambled);
}

// ---------------------------------------------------------------------------
// v5.1 TEMPO TELLS — the whiff tax and the re-arm gap, on the body.
//
// Both draw inside drawFighter's local space (origin at the feet, +x toward
// the opponent after the mirror, the same space the super-ready outline and
// the dizzy ghosts use). Phase and strength come from whiffTellState()
// (engine/tempo-tells.mjs), the one function the CINEMA 3D fighter layer
// reads too, so the fringe burns on the same ticks in both worlds.
//
// UNDER the sprite (drawTempoTellUnder):
//   whiff — a solid red fringe (an enlarged red silhouette; the sprite covers
//           all but a ~4-6 px rim) that burns hotter through the taxed tail,
//           plus 1-2 red ghosts of the extension cell falling back behind
//           the follow-through. The cell is remembered for the gap.
//   rearm — the fringe fading across the 4-frame gap, and the remembered
//           extension cell dropping away behind the idle body: "the swing
//           is still costing you".
// OVER the sprite (drawTempoTellOver):
//   rearm — a muted pale wash: the body goes grey for the gap (disarmed).
//   eaten press — a sharper white pop for 6 ticks, so a mash reads as
//           "not yet" even after the gap has closed.
//   whiff — a thin dust crescent in front of the fist that fades through
//           the taxed tail (the swipe of a swing that met air).
// Reduced motion keeps the fringe, wash and pop (gameplay information, like
// the super-ready aura) and drops the ghosts and the swipe; the battery
// profile's trailScale drops the ghosts. Counted into presentationDebug so
// a probe can prove a whiff reached the screen.
// ---------------------------------------------------------------------------
function drawTempoTellUnder(fighter, tell, atlas, frame, renderSize) {
  const reducedMotion = state.accessibility.reducedMotion;
  const trailScale = state.performance.trailScale;
  const red = TEMPO_TELL_RULES.whiffColor;
  if (tell.phase === "whiff") {
    whiffGhostCells[fighter.side] = { atlas, frame, renderSize, tick: state.simulationTick };
    ctx.save();
    ctx.globalAlpha = 0.6 + 0.3 * tell.strength;
    const outline = 1.05 + 0.02 * tell.strength;
    ctx.scale(outline, outline);
    drawSilhouetteFrame(atlas, frame, renderSize, red);
    ctx.restore();
    presentationDebug.whiffFringes += 1;
    if (!reducedMotion && trailScale > 0) {
      const copies = Math.max(1, Math.round(TEMPO_TELL_RULES.ghostTrailCopies * trailScale));
      for (let copy = 1; copy <= copies; copy += 1) {
        ctx.save();
        ctx.globalCompositeOperation = "screen";
        ctx.globalAlpha = (0.36 / copy) * (0.6 + 0.4 * tell.strength);
        ctx.translate(-copy * 17, copy * 2);
        drawSilhouetteFrame(atlas, frame, renderSize, red);
        ctx.restore();
        presentationDebug.whiffGhosts += 1;
      }
    }
    return;
  }
  if (tell.phase === "rearm") {
    ctx.save();
    ctx.globalAlpha = 0.7 * tell.strength;
    ctx.scale(1.045, 1.045);
    drawSilhouetteFrame(atlas, frame, renderSize, red);
    ctx.restore();
    presentationDebug.whiffFringes += 1;
    const ghost = whiffGhostCells[fighter.side];
    if (ghost && !reducedMotion && trailScale > 0
      && state.simulationTick - ghost.tick <= 40 && ghost.atlas?.complete && ghost.atlas.naturalWidth) {
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.globalAlpha = 0.34 * tell.strength;
      ctx.translate(-10 - (1 - tell.strength) * 18, 3);
      drawSilhouetteFrame(ghost.atlas, ghost.frame, ghost.renderSize, red);
      ctx.restore();
      presentationDebug.whiffGhosts += 1;
    }
  }
}

// ---------------------------------------------------------------------------
// 5.3 OKIZEME — the wake-up vulnerable window, on the body.
//
// Before this pass a knockdown was 64-76 frames in which nothing could be
// timed against the riser, so there was nothing to draw. Now the last 4-8
// rising frames (see wakeupVulnerableFrames — the count moves with the
// quick-rise / delayed-rise option) carry hurtboxes, and the attacker has to
// SEE that window open or the meaty is a guess about invisible state.
//
// The read is a hot amber rim that pops on the frame the body becomes real
// and burns brighter as the window closes, plus a low ground arc under the
// feet — deliberately amber, so it never reads as the whiff fringe's red or
// the super aura's accent. Gameplay information, so reduced motion and the
// battery profile keep it (they only ever drop trails); it draws in
// drawFighter's local space with the origin at the feet, like every other
// body tell. Counted into presentationDebug so a probe can prove it reached
// the screen on the same ticks the hurtboxes existed.
// ---------------------------------------------------------------------------
const WAKEUP_TELL_COLOR = "#ffb347";

function drawWakeupTell(fighter, atlas, frame, renderSize) {
  const window = wakeupVulnerableFrames(fighter.wakeOption);
  // 1 on the first vulnerable frame → ~0 as the fighter finishes standing up.
  const progress = 1 - (fighter.wakeupFrames - 1) / Math.max(1, window);
  ctx.save();
  ctx.globalAlpha = 0.55 + 0.35 * progress;
  const outline = 1.055 + 0.025 * progress;
  ctx.scale(outline, outline);
  drawSilhouetteFrame(atlas, frame, renderSize, WAKEUP_TELL_COLOR);
  ctx.restore();
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = 0.5 + 0.4 * progress;
  ctx.lineWidth = 3;
  ctx.strokeStyle = WAKEUP_TELL_COLOR;
  ctx.beginPath();
  ctx.ellipse(0, -6, renderSize * (0.2 + 0.06 * progress), 11 + 4 * progress, 0, Math.PI, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
  presentationDebug.wakeupTells += 1;
}

function drawTempoTellOver(fighter, tell, atlas, frame, renderSize) {
  const reducedMotion = state.accessibility.reducedMotion;
  if (tell.phase === "rearm") {
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.globalAlpha = 0.42 * tell.strength;
    drawSilhouetteFrame(atlas, frame, renderSize, TEMPO_TELL_RULES.rearmColor);
    ctx.restore();
    presentationDebug.rearmFlashes += 1;
  }
  if (tell.dropFlash > 0) {
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.globalAlpha = 0.55 * tell.dropFlash;
    drawSilhouetteFrame(atlas, frame, renderSize, "#ffffff");
    ctx.restore();
    presentationDebug.rearmDropFlashes += 1;
  }
  if (tell.phase === "whiff" && !reducedMotion) {
    // The swipe: a crescent about the same shoulder pivot the heavy limb
    // wedge uses, on the fist side, thinning and fading through the tail.
    const tailProgress = tell.taxed && tell.taxFrames > 0 ? 1 - tell.taxLeft / tell.taxFrames : 0;
    const fade = 1 - tailProgress * 0.85;
    const pivotX = 8;
    const pivotY = -renderSize * 0.62;
    const reach = renderSize * (0.5 + tailProgress * 0.06);
    ctx.save();
    ctx.lineCap = "round";
    ctx.globalAlpha = 0.7 * fade;
    ctx.strokeStyle = "rgba(255,244,236,0.9)";
    ctx.lineWidth = 3.5 * fade + 0.5;
    ctx.beginPath();
    ctx.arc(pivotX, pivotY, reach, -0.95 + tailProgress * 0.25, 0.45 + tailProgress * 0.2);
    ctx.stroke();
    ctx.globalAlpha = 0.55 * fade;
    ctx.strokeStyle = TEMPO_TELL_RULES.whiffColor;
    ctx.lineWidth = 2 * fade + 0.5;
    ctx.beginPath();
    ctx.arc(pivotX, pivotY, reach * 0.9, -0.8 + tailProgress * 0.25, 0.4 + tailProgress * 0.2);
    ctx.stroke();
    ctx.restore();
  }
}

function hexToRgbChannels(hex) {
  const value = parseInt(hex.slice(1, 7), 16);
  return `${(value >> 16) & 255},${(value >> 8) & 255},${value & 255}`;
}

// Soft contact shadow: radius/alpha derive from jump height, the ellipse
// stretches with dashes and lunges, and an accent bounce joins in while a
// special glows or the super spotlight is up. Pure function of existing render
// state; the battery profile keeps the original single flat ellipse.
function drawContactShadow(fighter, jump, renderSize, lunge) {
  const baseRadius = renderSize * 0.24;
  if (!state.performance.shadows) {
    ctx.fillStyle = "rgba(0,0,0,.58)";
    ctx.beginPath();
    ctx.ellipse(0, jump + 5, baseRadius, 15, 0, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  const airFade = clamp(1 - jump / 430, 0.22, 1);
  const stretch = 1 + Math.abs(lunge) / (renderSize * 0.9) + (fighter.dashFrames > 0 ? 0.35 : 0);
  const radius = baseRadius * (0.66 + 0.34 * airFade) * stretch;
  const alpha = 0.62 * airFade;
  ctx.save();
  ctx.translate(0, jump + 5);
  ctx.scale(1, 15 / baseRadius);
  const soft = ctx.createRadialGradient(0, 0, radius * 0.1, 0, 0, radius);
  soft.addColorStop(0, `rgba(0,0,0,${alpha.toFixed(3)})`);
  soft.addColorStop(0.62, `rgba(0,0,0,${(alpha * 0.44).toFixed(3)})`);
  soft.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = soft;
  ctx.beginPath();
  ctx.arc(0, 0, radius, 0, Math.PI * 2);
  ctx.fill();
  const accentStrength = Math.max(
    clamp(fighter.specialGlow, 0, 1) * 0.5,
    superDimLevel > 0.02 ? superDimLevel * 0.42 : 0,
  );
  if (accentStrength > 0.02 && !state.accessibility.highContrast) {
    // Match the warm spotlight pools during a super, the accent otherwise.
    const tone = superDimLevel > 0.02 ? "255,214,150" : hexToRgbChannels(fighter.def.accent);
    const bounce = ctx.createRadialGradient(0, 0, radius * 0.05, 0, 0, radius * 0.9);
    bounce.addColorStop(0, `rgba(${tone},${(accentStrength * 0.5).toFixed(3)})`);
    bounce.addColorStop(1, `rgba(${tone},0)`);
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = bounce;
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.9, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  if (!reflectionPassActive) presentationDebug.contactShadows += 1;
}

// Ali's rhythm-stack rings, origin at the fighter's FEET (pre-mirror, so the
// arc always opens screen-right the way it always has). Split out of
// drawFighter so the CINEMA 3D overlay pass can draw the same rings at the
// projected feet: FLOW 1/2/3 is his mechanic, not decoration.
function drawRhythmRings(fighter, time) {
  if (fighter.def.id !== "ali" || fighter.rhythmStacks <= 0) return;
  ctx.save();
  ctx.translate(0, -112);
  ctx.globalCompositeOperation = "screen";
  ctx.strokeStyle = fighter.rhythmStacks === 3 ? "#ff4fb9" : fighter.def.accent;
  ctx.shadowColor = fighter.def.accent;
  ctx.shadowBlur = 17 + fighter.rhythmStacks * 4;
  for (let ring = 0; ring < fighter.rhythmStacks; ring += 1) {
    ctx.globalAlpha = 0.24 + ring * 0.07;
    ctx.lineWidth = 3 + ring;
    ctx.beginPath();
    ctx.arc(0, 0, 72 + ring * 22 + Math.sin(time * 0.01 + ring) * 6, -1.12, 1.12);
    ctx.stroke();
  }
  ctx.restore();
}

function drawFighter(fighter, time) {
  const jump = FLOOR - fighter.y;
  const attack = fighter.attacking;
  const attackProgress = attack ? clamp(fighter.attackTime / attack.duration, 0, 1) : 0;
  const attackSwing = attack ? Math.sin(attackProgress * Math.PI) : 0;
  const startupPower = attack && fighter.attackTime < attack.active[0]
    ? Math.sin((fighter.attackTime / attack.active[0]) * Math.PI) : 0;
  const activePower = attack && fighter.attackTime >= attack.active[0] && fighter.attackTime <= attack.active[1]
    ? 1 : attack ? Math.max(0, attackSwing * 0.42) : 0;
  const moving = Math.abs(fighter.vx) > 22 && fighter.grounded && !attack;
  // Idle/walk pulse in pixels of chest travel. Applied further down as a
  // feet-anchored scaleY (the breathing pattern), never as a translate: the
  // feet and both shadows must stay glued to the floor line, or the fighter
  // reads as hovering. The old whole-sprite bob translate was exactly that
  // hover — the contact shadow rode up and down with it while the cast
  // shadow stayed planted, so the ground contact never agreed with itself.
  const bob = fighter.cinematicFrame === null && fighter.grounded && !fighter.stun && !fighter.block
    ? Math.sin((moving ? fighter.walkTime * 20 : fighter.animTime * 10) + fighter.side * 2) * (moving ? 1.8 : 2.7) : 0;
  const pose = fighterAnimationPose(fighter);
  // Wave 16: the side's palette pick decides which cached atlas draws.
  const atlas = paletteAtlas(fighter.def.id, fighter.side, pose.bank);
  const frame = pose.frame;
  const graphicFatality = activeGraphicFatality(fighter);
  const reality = finisherRealityAmount();
  const sizeAdjust = FIGHTER_SIZE_ADJUST[fighter.def.id] || 1;
  // v2.9 critic round (M3): the per-cell adjust rides the whole-sheet one.
  // The base bank's deep-squat crouch cells are drawn 1.13x-1.33x oversized
  // (the artist filled the cell with a folded body), so entering crouch
  // ballooned the figure in one tick against the correctly-normalised motion2
  // crouch-trans key that precedes it. Correcting renderSize keeps MASS
  // constant across the handoff — the shadow scales with it, as it already
  // does for the sheet adjust.
  // v2.9 critic round 2 (M4): cellDrawAdjust rolls the oversized-crouch
  // correction together with the new guard-flinch height reconciliation, so
  // both renderers apply exactly one scale rule per cell.
  // v3.0: `unified` tells cellDrawAdjust which bank supplies this fighter's
  // STANDING GUARD, because that is what the authored block-flinch is being
  // height-matched to. Nothing else in the correction changes — the unified
  // sheets are one global scale each and mutually registered, so no unified
  // cell takes a per-cell adjust.
  const unifiedActive = unifiedFighterReady(fighter.def.id);
  const moveSheetAdjust = bankSheetAdjust(fighter.def.id, pose.bank)
    * cellDrawAdjust(fighter.def.id, pose.bank, frame, { unified: unifiedActive });
  const renderSize = fighterRenderSize(fighter.def.id) * moveSheetAdjust;
  // v2.9 critic round (M5) + round 2 (B2): per-cell floor registration PLUS
  // the ramped airborne body-centre anchor, in world pixels. Floor-anchoring
  // an airborne cell is what made a 156px-tall tuck hand off from a 281px-tall
  // jump-rise by dropping the head half a body height on the tick vy was most
  // negative — the fighter plummeting while rising fastest. Above the street
  // every airborne cell registers to the same body-centre row instead, so no
  // airborne bank switch can move the body at all; the correction ramps to
  // zero at ground contact so takeoff and touchdown stay feet-planted.
  const floorFix = cellVerticalOffset(fighter.def.id, pose.bank, frame,
    fighter.grounded ? 0 : Math.max(0, FLOOR - fighter.y)) / 320 * renderSize;
  const attackKind = attack?.kind;
  const lunge = attackSwing * (attackKind === "special" ? 68 : attackKind === "heavy" ? 46 : 29);
  const crouchScale = fighter.crouch ? 0.88 : 1;
  const crouchDrop = fighter.crouch ? 21 : 0;
  const reducedMotion = state.accessibility.reducedMotion;
  // Breathing idle: chest-rise scaleY whose rate and depth grow as health
  // drops, so a gassed fighter visibly heaves before any UI is checked.
  // Transform math only — health/animTime are render-safe reads.
  // BODY-FIRST (spec 9): super storms breathe — the long held active windows
  // (the Devil's curse sequence especially) keep the idle chest-rise alive
  // instead of pinning the sprite solid between authored keys.
  const breathing = fighter.cinematicFrame === null && fighter.grounded && !fighter.down
    && (!attack || attack.superMove) && !fighter.stun && !fighter.block
    && fighter.dizzyFrames <= 0 && fighter.guardCrushFrames <= 0;
  const fatigue = clamp(1 - fighter.health / 100, 0, 1);
  // 2.8 critic round (S5): the WINNER keeps breathing through the fatality
  // hold — a slow time-based chest-rise + sway instead of a statue lock.
  // Render-only read of the snapshotted finisher; reduced motion stays still.
  const finisherHoldWinner = Boolean(state.finisher?.fatalityTriggered)
    && state.finisher.winner === fighter.side && !reducedMotion;
  const breath = breathing
    ? Math.sin(fighter.animTime * (5.2 + fatigue * 5.6) + fighter.side * 1.9)
      * (0.009 + fatigue * 0.015) * (reducedMotion ? 0.5 : 1)
    : finisherHoldWinner ? Math.sin(time * 0.0042 + fighter.side) * 0.011 : 0;
  // Hunched-forward exhaustion lean once idle health dips under 25%.
  const exhausted = breathing && !moving && fighter.health < 25 ? 1 - fighter.health / 25 : 0;
  // Hit-reaction smear intensity: normalised from the decaying hitFlash timer
  // (0.11-0.22s), gated exactly like the attack trails.
  const hitSmear = state.performance.trailScale > 0 && !reducedMotion
    ? clamp(fighter.hitFlash / 0.14, 0, 1)
    : 0;
  // v5.1 TEMPO TELLS: which tell (whiff tail / re-arm gap / eaten press) this
  // body wears this frame. Render-only read of snapshotted sim fields.
  const tempoTell = whiffTellState(fighter, state.simulationTick);
  const tempoTellLive = !reflectionPassActive && !graphicFatality
    && (tempoTell.phase !== "none" || tempoTell.dropFlash > 0)
    && Boolean(atlas?.complete && atlas.naturalWidth);
  // 5.3 OKIZEME: is this body inside the meaty window this frame?
  const wakeupTellLive = !reflectionPassActive && !graphicFatality
    && isWakeupVulnerable(fighter)
    && Boolean(atlas?.complete && atlas.naturalWidth);

  ctx.save();
  ctx.translate(fighter.x, fighter.y);
  drawContactShadow(fighter, jump, renderSize, lunge);

  drawRhythmRings(fighter, time);

  // v5.2 LOCOMOTION (bookends): a prone cinematic cell (the victim's KO lie)
  // sheds the lie it already carries before the script's rotation is applied
  // — the same rule the CINEMA 3D rig reads through the host bridge.
  const cineRotation = cinematicDrawRotation(pose.bank, frame, fighter.cinematicRotation || 0);
  if (cineRotation) ctx.rotate(cineRotation);
  if (finisherHoldWinner) ctx.rotate(Math.sin(time * 0.0012 + 0.8) * 0.011);
  if (fighter.cinematicScale !== 1) ctx.scale(fighter.cinematicScale, fighter.cinematicScale);

  // v4.6 PRONE: tilt the drawing only as far as it still needs to lie down.
  const downTilt = fighter.down ? downTiltFor(fighter.def.id, pose.bank, frame) : 0;
  if (downTilt > 0) {
    const share = downTilt / DOWN_TILT_RADIANS;
    ctx.rotate(-fighter.facing * downTilt);
    ctx.translate(-fighter.facing * 45 * share, 17 * share);
  }

  // Release 1.7: air-recovery back-flip — one backward rotation across the
  // flip window. Render-only read of a snapshotted frame counter.
  if (fighter.airTechFlipFrames > 0 && !reducedMotion) {
    const flip = 1 - fighter.airTechFlipFrames / AIR_RECOVERY_RULES.flipFrames;
    ctx.rotate(fighter.facing * flip * Math.PI * 2);
  }

  // v2.6 MOTION: the shared movement-animation transform. Jump flips pivot
  // about the body centre (the somersault axis); dash/walk lean, recoil
  // wobble and dizzy sway pivot about the feet. Same layer feeds poseRig in
  // the 3D renderer, so both worlds animate identically.
  const motion = fighterMotionTransform(fighter);
  if (motion.flipRotation !== 0) {
    const flipPivot = renderSize * 0.52;
    ctx.translate(0, -flipPivot);
    ctx.rotate(motion.flipRotation);
    ctx.translate(0, flipPivot);
  }
  if (motion.rotation !== 0) ctx.rotate(motion.rotation);
  // v2.6 BODY-FIRST: the shared world-space body offset — attack-extension
  // lunge toward the target / victim stagger step away from it. Applied
  // PRE-mirror so mixed-authored sheets can never flip the direction.
  if (motion.offsetX !== 0 || motion.offsetY !== 0) ctx.translate(motion.offsetX, motion.offsetY);
  // MOTION FIX 4: victims never freeze solid — a 1-2px pose shiver rides
  // every hold window (hitstop and the multi-hit super storms), re-hashed
  // per sim tick so it trembles through the freeze instead of pinning.
  if (!reducedMotion && fighter.hitstunFrames > 0 && fighter.cinematicFrame === null
    && (state.hitstop > 0 || state.fighters[1 - fighter.side]?.attacking?.superMove)) {
    const trembleTick = state.simulationTick * 2 + fighter.side * 17;
    ctx.translate(
      (presentationHash01(trembleTick, 3) - 0.5) * 3.2,
      (presentationHash01(trembleTick, 7) - 0.5) * 1.8,
    );
  }

  // The mirror combines the fighter's numeric facing with the direction the
  // AUTHORED cell actually points (atlas-facing.mjs) — post's sheets mix
  // left- and right-facing art, so facing alone drew him looking away from
  // the opponent while his attacks still extended the right way.
  const renderMirror = fighter.facing * atlasFrameFacing(fighter.def.id, pose.bank, frame);
  if (!reflectionPassActive) {
    presentationDebug.lastFighterMirror[fighter.side] = {
      fighterId: fighter.def.id, bank: pose.bank, frame, facing: fighter.facing, mirror: renderMirror,
    };
    // v2.9 FLOW: count motion2 cells the moment they actually draw.
    // v2.9 round 4: PER CELL as well. The demo's `turnaround` beat read as
    // FIRING while motion2:5 drew for zero frames, because the beat counter
    // watched a sim edge (a grounded facing flip) and the cell it stands for
    // sits behind a whole precedence chain in fighterPoseDescriptor. A blanket
    // motion2 total could not tell those apart. This tally is instrumentation
    // ONLY — read by qa.probe()/qa.demoCoverage(), never by the sim or the
    // choreographer, so nothing here can perturb determinism.
    if (pose.bank === "motion2") {
      presentationDebug.motion2Cells += 1;
      presentationDebug.motion2CellDraws[frame] = (presentationDebug.motion2CellDraws[frame] || 0) + 1;
    }
    // v2.10 WALK: same, plus the key index so a burst can watch it advance.
    if (pose.bank === "walk") {
      presentationDebug.walkCells += 1;
      presentationDebug.lastWalkKey[fighter.side] = pose.frame;
    }
    // v2.9 final round (T6) — THE TURNAROUND AUDIT, AT THE DRAW SITE.
    //
    // qa.demoCoverage() reported the turnaround beat FIRING while the demo
    // critic measured motion2:5 at zero frames on screen, so the counter and
    // the screen disagreed. The counter watches a sim edge (a grounded facing
    // flip); this watches the pixels. While the 3-tick latch is live, every
    // frame either draws the pivot key or names — by bank:frame — the drawing
    // that took the slot instead, which identifies both classes of failure at
    // once: a pose branch that outranked it (a different cell), and the
    // descriptor being emitted but falling back through the accept mask (the
    // pivot's own fallback cell). Instrumentation only.
    if (motionObs[fighter.side]?.turnFrames > 0) {
      // v5.2: the pivot is the ext5 turnaround on a fighter with the sheet,
      // the motion2 key underneath it otherwise — both are the pivot drawn.
      if ((pose.bank === "motion2" && frame === MOTION2_CELLS.turnaround)
        || (pose.bank === UNIFIED_EXT5_BANK && frame === UNIFIED_EXT5_CELLS.turnaround)) {
        presentationDebug.turnaroundDraws += 1;
      } else {
        const blockedBy = `${pose.bank}:${frame}`;
        presentationDebug.turnaroundBlocked[blockedBy] =
          (presentationDebug.turnaroundBlocked[blockedBy] || 0) + 1;
      }
    }
  }
  ctx.scale(renderMirror, 1);
  ctx.translate(lunge - startupPower * 8,
    floorFix + crouchDrop - attackSwing * (attackKind === "special" ? 13 : 5));
  ctx.rotate(-attackSwing * (attackKind === "heavy" ? 0.07 : 0.025));
  ctx.scale(1 + activePower * 0.045 - startupPower * 0.025, crouchScale + startupPower * 0.035 - activePower * 0.025);
  // Breathing + idle pulse + exhaustion posture: the origin sits at the feet,
  // so the chest-rise anchors correctly and the hunch pivots forward over the
  // toes. The bob rides the same feet-anchored scale — its pixel amplitude
  // becomes chest travel over the sprite height, and the feet never move.
  const idlePulse = breath - bob / (renderSize * 0.85);
  if (idlePulse !== 0) ctx.scale(1, 1 + idlePulse);
  if (breathing && !reflectionPassActive) presentationDebug.breathing += 1;
  if (exhausted > 0) ctx.rotate(0.085 * exhausted * (reducedMotion ? 0.5 : 1));
  // Impact squash-and-recover, decaying with the same hitFlash the smear uses.
  if (hitSmear > 0) ctx.scale(1 + hitSmear * 0.05, 1 - hitSmear * 0.06);
  // v2.6 MOTION squash & stretch: rise stretch / launch squat / landing squash
  // from the shared motion layer, feet-anchored like every scale above it.
  if (motion.scaleX !== 1 || motion.scaleY !== 1) ctx.scale(motion.scaleX, motion.scaleY);
  if (motion.stretchActive && !reflectionPassActive) presentationDebug.squashStretchFrames += 1;

  if (fighter.specialGlow > 0) {
    const glow = ctx.createRadialGradient(0, -135, 16, 0, -135, 178);
    glow.addColorStop(0, `${fighter.def.accent}88`);
    glow.addColorStop(1, `${fighter.def.accent}00`);
    ctx.fillStyle = glow;
    ctx.fillRect(-205, -335, 410, 350);
  }

  // Super-ready Grit aura: the moment the meter can pay for a super, a pulsing
  // accent under-glow wraps the sprite and embers rise off the shoulders.
  // Render-only read of snapshotted sim state (same check as the HUD grit-row
  // "full" class); ember positions are hashed from the simulation tick so no
  // visualRandom is consumed and rollback has nothing to re-wind. Kept under
  // highContrast because super-ready is gameplay information, not decoration.
  const superReady = state.phase === "fight" && fighter.cinematicFrame === null
    && fighter.meter >= GRIT_RULES.superCost;
  if (!reflectionPassActive) {
    if (superReady && !gritReadyLatched[fighter.side]) {
      gritReadyLatched[fighter.side] = true;
      gritFlareLevel[fighter.side] = 1;
    } else if (!superReady && gritReadyLatched[fighter.side]) {
      gritReadyLatched[fighter.side] = false;
    }
  }
  if (superReady) {
    const pulse = reducedMotion ? 0.5 : 0.5 + Math.sin(time * 0.006 + fighter.side * 2.4) * 0.5;
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.globalAlpha = 0.5 + pulse * 0.3;
    const auraReach = renderSize * 0.6;
    const aura = ctx.createRadialGradient(0, -renderSize * 0.32, 14, 0, -renderSize * 0.32, auraReach);
    aura.addColorStop(0, `${fighter.def.accent}8c`);
    aura.addColorStop(0.55, `${fighter.def.accent}3c`);
    aura.addColorStop(1, `${fighter.def.accent}00`);
    ctx.fillStyle = aura;
    ctx.fillRect(-auraReach, -renderSize * 0.32 - auraReach, auraReach * 2, auraReach * 2);
    if (atlas?.complete && atlas.naturalWidth) {
      // Pulsing accent outline: a slightly enlarged silhouette behind the
      // sprite leaves a charged fringe all the way around the body (the KI/SF3
      // max-meter read). Feet-anchored scale keeps it grounded.
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.32 + pulse * 0.26;
      const outline = 1.03 + pulse * 0.012;
      ctx.scale(outline, outline);
      drawSilhouetteFrame(atlas, frame, renderSize, fighter.def.accent);
      ctx.restore();
    }
    if (!reducedMotion && state.performance.trailScale > 0) {
      const emberCount = Math.max(3, Math.round(7 * state.performance.trailScale));
      ctx.globalCompositeOperation = "lighter";
      ctx.shadowColor = fighter.def.accent;
      ctx.shadowBlur = 9;
      for (let ember = 0; ember < emberCount; ember += 1) {
        const cycleFrames = 66 + (ember % 3) * 14;
        const clock = state.simulationTick + ember * 31;
        const progress = (clock % cycleFrames) / cycleFrames;
        const jitter = emberHash(Math.floor(clock / cycleFrames) * 13 + ember * 7 + fighter.side * 101);
        const emberX = (jitter - 0.5) * renderSize * 0.44 + Math.sin((progress + jitter) * Math.PI * 2) * 5;
        const emberY = -renderSize * (0.66 + progress * 0.32);
        ctx.globalAlpha = (1 - progress) * 0.85;
        ctx.fillStyle = ember % 2 ? fighter.def.accent : "#fff3d8";
        ctx.beginPath();
        ctx.arc(emberX, emberY, 2.4 + jitter * 2.6, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
    if (!reflectionPassActive) presentationDebug.gritAuras += 1;
  }

  drawAttackVfx(fighter, time, activePower);
  if (fighter.carriedWeapon) {
    const carried = stageWeaponProfile();
    if (carried) {
      ctx.save();
      ctx.translate(52 * FIGHTER_SCALE, -150 * FIGHTER_SCALE);
      drawThrowable({
        style: carried.style,
        width: carried.width * FIGHTER_SCALE,
        height: carried.height * FIGHTER_SCALE,
        spinAngle: 0.4,
        vx: 1,
        vy: 0,
        color: "#ffd54a",
        ownerSide: -1,
        hazard: false,
      }, time, 1);
      ctx.restore();
    }
  }

  if (atlas?.complete && atlas.naturalWidth) {
    // BODY-FIRST (spec 8): trail copies stay OUT of the mirror — the band
    // only ever shows fragments of them, which read as sprite debris.
    const baseTrails = state.accessibility.reducedMotion || reflectionPassActive
      ? 0
      : attack ? (attackKind === "special" ? 3 : activePower > 0.8 ? 2 : 0) : 0;
    const trails = Math.floor(baseTrails * state.performance.trailScale);
    for (let index = trails; index >= 1; index -= 1) {
      ctx.save();
      ctx.translate(-index * (13 + activePower * 8), index * 1.5);
      ctx.globalAlpha = 0.08 + (trails - index) * 0.045;
      ctx.globalCompositeOperation = "screen";
      ctx.filter = "saturate(1.65) brightness(1.35)";
      ctx.shadowColor = fighter.def.accent;
      ctx.shadowBlur = 22;
      drawAtlasFrame(atlas, frame, renderSize);
      ctx.restore();
    }

    // MOTION FIX 2 + 9: the attack echo, rebuilt to the echo caps. It now
    // exists ONLY through the active window (the old startup echo sat behind
    // long heavy wind-ups for 7 filmstrip frames as an idle-pose body
    // double), always inherits the CURRENT atlas cell, and is capped at 30%
    // alpha. Heavies drop the body copy entirely — their smear is the limb
    // wedge below (a stretched arc of the swinging arm), which is the
    // anime-smear read the body double was failing to be.
    if (!reflectionPassActive && attack && !graphicFatality
      && attackKind === "special"
      && state.performance.trailScale > 0 && !reducedMotion && activePower > 0.3) {
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.globalAlpha = 0.28 * activePower;
      ctx.rotate(-0.14 * activePower);
      ctx.translate(-(15 + activePower * 13), -2);
      ctx.scale(1 + 0.12 * activePower, 1 - 0.04 * activePower);
      drawSilhouetteFrame(atlas, frame, renderSize, fighter.def.accent);
      ctx.restore();
      presentationDebug.attackSmears += 1;
    }
    // MOTION FIX 9: heavy limb smear — a tapered wedge of the swinging arm
    // stretched along the swing arc through the active frames, wide and hot
    // at the fist, thinning to nothing behind it. Shares the ribbon's pivot
    // and sweep math so wedge and ribbon read as one motion; fades with the
    // same post-contact ribbon fade so nothing hangs through hitstop.
    if (!reflectionPassActive && attack && !graphicFatality
      && attackKind === "heavy"
      && state.performance.trailScale > 0 && !reducedMotion && activePower > 0.2) {
      const wedgeFade = motionObs[fighter.side]?.ribbonFade ?? 1;
      // BODY-FIRST (spec 7): the wedge dies as the body enters its
      // follow-through beat — the old version hung its arc over the victim
      // for the whole fade while the fist was already down.
      const swingProgress = clamp(fighter.attackTime / attack.duration, 0, 1);
      if (wedgeFade > 0.05 && swingProgress < 0.72) {
        const progress = swingProgress;
        const eased = Math.sin(Math.min(1, progress * 1.15) * Math.PI * 0.5);
        const headAngle = -2.3 + eased * 2.65;
        const pivotX = 8;
        const pivotY = -renderSize * 0.62;
        const reach = renderSize * 0.52;
        ctx.save();
        ctx.globalCompositeOperation = "screen";
        const wedgeGrad = ctx.createRadialGradient(pivotX, pivotY, reach * 0.2, pivotX, pivotY, reach * 1.05);
        wedgeGrad.addColorStop(0, `${fighter.def.accent}00`);
        wedgeGrad.addColorStop(0.62, `${fighter.def.accent}66`);
        wedgeGrad.addColorStop(1, "#fff6df55");
        ctx.fillStyle = wedgeGrad;
        ctx.globalAlpha = 0.5 * activePower * wedgeFade * wedgeFade;
        ctx.beginPath();
        ctx.moveTo(pivotX + Math.cos(headAngle - 0.85) * reach * 0.3,
          pivotY + Math.sin(headAngle - 0.85) * reach * 0.3);
        ctx.arc(pivotX, pivotY, reach * 1.02, headAngle - 0.85, headAngle);
        ctx.closePath();
        ctx.fill();
        // BODY-FIRST (spec 7): the standalone "hot leading edge" stroke is
        // DEAD — with the accent wedge barely visible it floated as an
        // orphan thin white slash with no limb under it (the critic's
        // burst-heavy-8). The gradient wedge + the extension transform now
        // carry the swing read.
        ctx.restore();
        presentationDebug.attackSmears += 1;
      }
    }

    if (!reflectionPassActive && state.performance.shadows && !graphicFatality
      && !state.accessibility.highContrast) {
      // Stage-keyed rim light: a tinted silhouette peeking 2-3px past the edge
      // that faces the arena's key light. The sprite draw below covers all but
      // the lit edge; the colour warms while the super spotlight is up.
      const rim = STAGE_RIM_LIGHTS[state.stage] || STAGE_RIM_LIGHTS.somerset;
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.35;
      ctx.translate(rim.direction * fighter.facing * 3, -2);
      drawSilhouetteFrame(atlas, frame, renderSize, stageRimColor());
      ctx.restore();
      presentationDebug.rimLights += 1;
    }

    if (!reflectionPassActive && !graphicFatality && state.performance.trailScale > 0
      && !state.accessibility.highContrast && state.projectiles.length) {
      // Projectile rim light (wave 4): the nearest incoming projectile or
      // thrown object tints the fighter's silhouette edge on the side facing
      // it, brightening as it closes in — same offset-silhouette technique as
      // the stage rim pass above. Render-only read of state.projectiles.
      let nearest = null;
      let nearestDistance = 300;
      const chestY = fighter.y - fighter.height * 0.55;
      for (const projectile of state.projectiles) {
        const distance = Math.hypot(projectile.x - fighter.x, projectile.y - chestY);
        if (distance < nearestDistance) {
          nearest = projectile;
          nearestDistance = distance;
        }
      }
      if (nearest) {
        const strength = clamp(1 - nearestDistance / 300, 0, 1);
        const towardLocal = (Math.sign(nearest.x - fighter.x) || 1) * fighter.facing;
        const tint = /^#[0-9a-fA-F]{6}/.test(nearest.color || "") ? nearest.color : "#ffe9b8";
        ctx.save();
        ctx.globalCompositeOperation = "screen";
        ctx.globalAlpha = 0.55 * strength;
        ctx.translate(towardLocal * 5, -2);
        drawSilhouetteFrame(atlas, frame, renderSize, tint);
        ctx.restore();
        presentationDebug.projectileGlows += 1;
      }
    }

    // v5.1 TEMPO TELLS, under the sprite: whiff fringe + extension-cell ghosts.
    if (tempoTellLive) drawTempoTellUnder(fighter, tempoTell, atlas, frame, renderSize);

    // 5.3 OKIZEME, under the sprite: the wake-up vulnerable rim + ground arc.
    if (wakeupTellLive) drawWakeupTell(fighter, atlas, frame, renderSize);

    if (!reflectionPassActive && hitSmear > 0) {
      // Directional hit-reaction smear: stretched additive ghosts trailing
      // opposite the knockback on the frames the white hit flash is live.
      const knock = Math.abs(fighter.vx) > 30 ? Math.sign(fighter.vx) : -fighter.facing;
      const localKnock = knock * fighter.facing;
      const copies = Math.max(1, Math.round(2 * state.performance.trailScale));
      for (let copy = 1; copy <= copies; copy += 1) {
        ctx.save();
        ctx.globalCompositeOperation = "screen";
        ctx.globalAlpha = (0.22 * hitSmear) / copy;
        ctx.translate(-localKnock * copy * 26 * hitSmear, 0);
        ctx.scale(1 + copy * 0.06 * hitSmear, 1 - copy * 0.03 * hitSmear);
        drawAtlasFrame(atlas, frame, renderSize);
        ctx.restore();
        presentationDebug.hitSmears += 1;
      }
    }

    if (!reflectionPassActive && fighter.dizzyFrames > 0
      && state.performance.trailScale > 0 && !reducedMotion) {
      // Dizzy double vision: two hue-split silhouette ghosts sway apart and
      // drift back; the amplitude collapses with the drain bar so recovery is
      // telegraphed. Time-driven only — no RNG, mobile-cheap tinted blits.
      const drain = fighter.dizzyFrames / Math.max(1, fighter.dizzyTotalFrames);
      // v2.6 MOTION: sway amplitude up (7 → 10) — rides with the new dizzy
      // body-sway rotation in fighterMotionTransform.
      const sway = Math.sin(time * 0.008 + fighter.side * 1.7) * 10 * (0.35 + 0.65 * drain);
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.globalAlpha = 0.28;
      ctx.translate(sway, -1.5);
      drawSilhouetteFrame(atlas, frame, renderSize, "rgb(255,120,170)");
      ctx.translate(-sway * 2, 3);
      drawSilhouetteFrame(atlas, frame, renderSize, "rgb(110,205,255)");
      ctx.restore();
      presentationDebug.dizzyGhosts += 2;
    }

    ctx.save();
    ctx.shadowColor = fighter.specialGlow > 0 ? fighter.def.accent : "rgba(0,0,0,.9)";
    ctx.shadowBlur = state.performance.shadows ? fighter.specialGlow > 0 ? 25 : 9 : 0;
    ctx.shadowOffsetY = 6;
    if (fighter.hitFlash > 0) {
      ctx.filter = HIT_FLASH_FILTER;
    } else if (fighter.block) ctx.filter = "brightness(.82) saturate(.78)";
    else if (!graphicFatality && fighter.health < 25 && !state.accessibility.highContrast) {
      // Last-legs grade: drained, slightly desaturated and contrasty. Lowest
      // priority in the filter chain — hit flash and block keep precedence.
      ctx.filter = "saturate(.68) contrast(1.14) brightness(.93)";
      if (!reflectionPassActive) presentationDebug.lastLegs += 1;
    }
    if (graphicFatality) {
      drawGraphicFatalityVictim(atlas, frame, renderSize, graphicFatality, time,
        renderMirror, cineRotation);
    }
    else if (!reflectionPassActive && state.performance.shadows && battleDamageMarks[fighter.side].length) {
      // Accumulating battle damage: composite the accrued marks onto this
      // frame's sprite. The mirror pass and the battery profile stay on the
      // plain atlas blit so the extra composite never doubles up.
      drawDamagedAtlasFrame(fighter.side, atlas, frame, renderSize);
      presentationDebug.battleDamage += battleDamageMarks[fighter.side].length;
    } else drawAtlasFrame(atlas, frame, renderSize);
    ctx.restore();

    // v5.1 TEMPO TELLS, over the sprite: re-arm wash, eaten-press pop, swipe.
    if (tempoTellLive) drawTempoTellOver(fighter, tempoTell, atlas, frame, renderSize);

    // v2.6 MOTION pose cross-fade (spec 3): the previous atlas cell lingers
    // 2-3 sim frames at falling alpha OVER the fresh pose (keeps the fighter
    // silhouette solid — no see-through frames), killing the pose snap.
    // Armed/paced by updateMotionObservers; skipped during hitstop freezes,
    // the dismemberment compositor, battery, and the mirror pass.
    // MOTION FIX 5: ghost discipline — alpha caps at 30% and the fade is
    // skipped entirely mid-flip where the rotating transform would smear the
    // old cell across the sky.
    if (!reflectionPassActive && !graphicFatality && state.hitstop <= 0
      && Math.abs(motion.flipRotation) < 0.3) {
      const fadeObs = motionObs[fighter.side];
      if (fadeObs.fadeLeft > 0 && (fadeObs.fadeBank !== pose.bank || fadeObs.fadeFrame !== frame)) {
        const fadeAtlas = paletteAtlas(fighter.def.id, fighter.side, fadeObs.fadeBank);
        if (fadeAtlas?.complete && fadeAtlas.naturalWidth) {
          const fadeAdjust = bankSheetAdjust(fighter.def.id, fadeObs.fadeBank)
            * baseCellDrawAdjust(fighter.def.id, fadeObs.fadeBank, fadeObs.fadeFrame);
          const fadeSize = fighterRenderSize(fighter.def.id) * fadeAdjust;
          // v2.9 critic round (M1): the ghost is MASKED BY THE INCOMING
          // POSE'S OWN SILHOUETTE instead of a fixed rectangle. The old clip
          // cut "everything below 72% of the cell height", which assumes the
          // head lives in the top 28% — false for most motion/motion2 cells.
          // At the dash->brake seam the outgoing horizontal dash-stretch
          // cell's head survived that clip and a fully legible SECOND FACE
          // rendered at the fighter's hip; at walk seams a second arm, hand,
          // shoe or decal read at 30% alpha.
          //
          // Intersecting with the live silhouette makes a readable second
          // figure impossible BY CONSTRUCTION — the fade can only soften
          // pixels the new cell already covers. It also self-scales with the
          // pose delta: near-identical poses (walk, idle) still cross-
          // dissolve fully, a big bank switch contributes interior blending
          // only, and nothing can ever appear OUTSIDE the live body.
          // v2.9 critic round 2 (B5): the "same cycle" exemption was the bug.
          // It said "adjacent keys of one CYCLE", but it tested for adjacent
          // keys of one SHEET ROW — and only the BASE bank has cycles in its
          // rows (idle 0-3, walk 4-7). Row 0 of the motion bank is punch-ext /
          // kick-ext / smear-h / smear-v: four completely different poses. So
          // every kit-less standing heavy handed motion:2 to motion:0, scored
          // "same cycle", and drew its outgoing full-extension cell CRISP and
          // UNSOFTENED over the incoming one — two fully readable shark logos
          // for the three fade ticks, which is precisely what the critics saw.
          // The exemption is now what it always claimed to be: base-bank idle
          // and walk rows only. Everything else softens.
          // v3.0: the unified bank's cells 0-4 ARE a cycle — one idle and the
          // four keys of one stride, authored in one generation — so they earn
          // the same crisp cross-dissolve the base bank's idle and walk rows
          // do. Without this every walk key handoff on a unified fighter took
          // the SOFTENED big-delta ghost, which is a quality step down from
          // 2.9 on the most-seen transition in the game. Note the exemption
          // spans idle -> walk here where the base bank's cannot: on the base
          // sheet those are two different rows, and B5 is explicit that the
          // test is "adjacent keys of one CYCLE" — which, on this bank, they
          // are. Any other unified pair (guard, crouch, a reaction) still
          // softens.
          // v4.0: the cycle SPANS TWO BANKS now — the idle alternates 0 <-> 16
          // and the walk runs 1 -> 17 -> 2 -> 3 -> 18 -> 4, so four of the six
          // stride handoffs and every breath cross from `unified` to
          // `unified-ext`. A bank-equality test here would have sent all of
          // them back to the softened big-delta ghost, undoing the 3.0 fix on
          // the most-seen transition in the game. isUnifiedCycleCell owns the
          // membership question so both renderers answer it the same way.
          const unifiedCycle = isUnifiedCycleCell(pose.bank, frame)
            && isUnifiedCycleCell(fadeObs.fadeBank, fadeObs.fadeFrame);
          const sameCycle = unifiedCycle
            || (pose.bank === "base" && fadeObs.fadeBank === "base"
              && Math.floor(fadeObs.fadeFrame / 4) === Math.floor(frame / 4)
              && Math.floor(frame / 4) <= 1);
          const ghost = poseGhostCell(fadeAtlas, fadeObs.fadeFrame, atlas, frame,
            renderSize / fadeSize, !sameCycle);
          if (ghost) {
            ctx.save();
            // The fighter must never be SEE-THROUGH during a fade: the live
            // cell is already on the canvas at full opacity and the ghost only
            // ever composites OVER it, source-over, never replacing it. The
            // alpha here is the ghost's own, and it is explicitly capped —
            // lower for a softened big-delta switch than for a cycle
            // cross-dissolve, because a big-delta ghost is doing less work.
            const ceiling = sameCycle ? GHOST_CYCLE_ALPHA : GHOST_SOFT_ALPHA;
            ctx.globalCompositeOperation = "source-over";
            ctx.globalAlpha = Math.min(ceiling,
              ceiling * (fadeObs.fadeLeft / MOTION_RULES.crossfadeFrames) + 0.05);
            ctx.drawImage(ghost, -fadeSize * 0.5, -fadeSize, fadeSize, fadeSize);
            ctx.restore();
            presentationDebug.poseCrossfades += 1;
          }
        }
      }
    }

    // The roster portraits are substantially higher resolution than an atlas
    // cell. A restrained soft-light pass brings their skin/fabric/material
    // detail into the slow cinematic poses without replacing the authored
    // animation or disturbing the dismemberment compositor.
    const portrait = fighterImages[fighter.def.id];
    if (reality > .01 && !reflectionPassActive && !graphicFatality
      && portrait?.complete && portrait.naturalWidth && !state.accessibility.highContrast) {
      const portraitHeight = renderSize * 1.02;
      const portraitWidth = portraitHeight * portrait.naturalWidth / portrait.naturalHeight;
      ctx.save();
      ctx.globalCompositeOperation = "soft-light";
      ctx.globalAlpha = reality * .2;
      ctx.drawImage(portrait, -portraitWidth * .5, -portraitHeight, portraitWidth, portraitHeight);
      ctx.restore();
      presentationDebug.realisticPortraits += 1;
    }

    const flare = gritFlareLevel[fighter.side];
    if (flare > 0.01 && !reflectionPassActive && !graphicFatality) {
      // One-time threshold flare the frame the meter banks a super: a bright
      // full-body silhouette flash that decays over ~0.3s.
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = (reducedMotion ? 0.4 : 0.8) * flare;
      drawSilhouetteFrame(atlas, frame, renderSize, "#fff6da");
      ctx.restore();
    }
  } else {
    ctx.fillStyle = fighter.def.color;
    ctx.fillRect(-48, -205, 96, 205);
  }

  if (fighter.block) {
    ctx.strokeStyle = `${fighter.def.accent}dd`;
    ctx.shadowColor = fighter.def.accent;
    ctx.shadowBlur = 17;
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.arc(35, -139, 85, -1.18, 1.18);
    ctx.stroke();
  }
  ctx.restore();

  if (fighter.stun > 0.4 && !fighter.down) {
    ctx.fillStyle = fighter.def.accent;
    ctx.font = "900 22px Arial";
    ctx.textAlign = "center";
    ctx.fillText("✦", fighter.x, fighter.y - fighter.height - 38 + Math.sin(time * 0.02) * 8);
  }
}

function drawLimb(x1, y1, x2, y2, width, skin, cloth) {
  ctx.lineCap = "round";
  ctx.strokeStyle = cloth;
  ctx.lineWidth = width + 6;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(lerp(x1, x2, 0.62), lerp(y1, y2, 0.62));
  ctx.stroke();
  ctx.strokeStyle = skin;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(lerp(x1, x2, 0.58), lerp(y1, y2, 0.58));
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

function drawWeapon(fighter, handX, handY, swing) {
  ctx.save();
  ctx.translate(handX, handY);
  ctx.rotate(-0.35 + swing * 1.25);
  ctx.strokeStyle = fighter.def.accent;
  ctx.fillStyle = fighter.def.accent;
  ctx.lineCap = "round";
  ctx.lineWidth = 8;
  switch (fighter.def.weapon) {
    case "gauntlets":
      ctx.fillRect(-12, -18, 42, 36);
      ctx.fillStyle = "#303741";
      for (let i = 0; i < 3; i += 1) ctx.fillRect(20 + i * 7, -15 + i * 3, 11, 8);
      break;
    case "signblade":
      ctx.shadowBlur = 20;
      ctx.shadowColor = fighter.def.accent;
      ctx.fillRect(-4, -12, 18, 20);
      ctx.fillRect(8, -94, 10, 100);
      ctx.fillRect(-4, -102, 34, 13);
      break;
    case "reelchain":
      ctx.beginPath();
      ctx.arc(10, -5, 21, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([7, 6]);
      ctx.beginPath();
      ctx.moveTo(25, -20);
      ctx.lineTo(73, -71);
      ctx.stroke();
      ctx.setLineDash([]);
      break;
    case "posthammer":
      ctx.fillRect(6, -75, 9, 86);
      ctx.fillRect(-20, -89, 61, 25);
      break;
    case "caneblade":
      ctx.beginPath();
      ctx.moveTo(5, 8);
      ctx.lineTo(12, -94);
      ctx.quadraticCurveTo(36, -113, 47, -89);
      ctx.stroke();
      break;
    case "golfclub":
      ctx.strokeStyle = "#eee6c8";
      ctx.beginPath();
      ctx.moveTo(5, 8);
      ctx.lineTo(17, -91);
      ctx.stroke();
      ctx.fillStyle = fighter.def.accent;
      ctx.fillRect(10, -100, 43, 18);
      break;
    case "micstaff":
      ctx.fillRect(7, -99, 8, 113);
      ctx.beginPath();
      ctx.arc(11, -107, 15, 0, Math.PI * 2);
      ctx.fill();
      break;
    case "micchucks":
      ctx.beginPath();
      ctx.moveTo(7, -10);
      ctx.lineTo(20, -55);
      ctx.moveTo(30, -66);
      ctx.lineTo(55, -99);
      ctx.stroke();
      ctx.setLineDash([4, 4]);
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(20, -55);
      ctx.lineTo(30, -66);
      ctx.stroke();
      break;
  }
  ctx.restore();
}

function drawFinisherImpact(effect, alpha) {
  const spread = (effect.final ? 155 : 72) * effect.power;
  const growth = 1 - alpha;
  ctx.globalCompositeOperation = "screen";
  ctx.lineCap = "round";
  ctx.fillStyle = effect.color;
  ctx.strokeStyle = effect.color;

  if (effect.style === "seismic") {
    ctx.lineWidth = effect.final ? 11 : 6;
    ctx.beginPath(); ctx.ellipse(0, 94, spread * (.35 + growth), 18 + growth * 38, 0, 0, Math.PI * 2); ctx.stroke();
    for (let i = -4; i <= 4; i += 1) {
      ctx.beginPath(); ctx.moveTo(i * 12, 45); ctx.lineTo(i * 24, 85); ctx.lineTo(i * 43, 112 + (i % 2) * 12); ctx.stroke();
    }
  } else if (effect.style === "neon") {
    ctx.lineWidth = effect.final ? 10 : 5;
    ctx.rotate((effect.variant ? -1 : 1) * growth * .7);
    for (let i = 0; i < 3; i += 1) {
      const radius = spread * (.28 + i * .22 + growth * .28);
      ctx.beginPath(); ctx.arc(0, 0, radius, i * .7, i * .7 + Math.PI * 1.35); ctx.stroke();
    }
    ctx.strokeStyle = effect.secondary;
    ctx.beginPath();
    for (let i = 0; i < 8; i += 1) {
      const angle = i * Math.PI / 4;
      const radius = i % 2 ? spread * .32 : spread * .6;
      const x = Math.cos(angle) * radius;
      const y = Math.sin(angle) * radius;
      if (!i) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath(); ctx.stroke();
  } else if (effect.style === "steel") {
    ctx.lineWidth = effect.final ? 12 : 6;
    ctx.beginPath(); ctx.arc(0, 0, spread * (.3 + growth * .55), 0, Math.PI * 2); ctx.stroke();
    for (let i = 0; i < 12; i += 1) {
      const angle = i * Math.PI / 6;
      ctx.beginPath(); ctx.moveTo(Math.cos(angle) * 18, Math.sin(angle) * 18); ctx.lineTo(Math.cos(angle) * spread, Math.sin(angle) * spread); ctx.stroke();
    }
  } else if (effect.style === "paint") {
    for (let i = 0; i < (effect.final ? 26 : 12); i += 1) {
      const angle = i * 2.399 + effect.variant;
      const radius = spread * (.15 + ((i * 37) % 100) / 120) * (0.45 + growth);
      ctx.globalAlpha = alpha * (.48 + (i % 3) * .2);
      ctx.fillStyle = i % 3 ? effect.color : effect.secondary;
      ctx.beginPath(); ctx.arc(Math.cos(angle) * radius, Math.sin(angle) * radius, 4 + (i % 5) * 3, 0, Math.PI * 2); ctx.fill();
    }
  } else if (effect.style === "voltage") {
    ctx.lineWidth = effect.final ? 9 : 5;
    for (let branch = 0; branch < (effect.final ? 9 : 5); branch += 1) {
      const angle = branch * Math.PI * 2 / (effect.final ? 9 : 5);
      ctx.save(); ctx.rotate(angle); ctx.beginPath(); ctx.moveTo(0, 0);
      for (let step = 1; step <= 6; step += 1) ctx.lineTo(step * spread / 6, (step % 2 ? -1 : 1) * (8 + branch % 3 * 4));
      ctx.stroke(); ctx.restore();
    }
  } else if (effect.style === "gilded") {
    ctx.lineWidth = effect.final ? 18 : 9;
    for (let i = 0; i < 3; i += 1) {
      ctx.globalAlpha = alpha * (1 - i * .2);
      ctx.beginPath(); ctx.arc(-spread * .2, 0, spread * (.45 + i * .18 + growth * .2), -1.15, 1.15); ctx.stroke();
    }
  } else if (effect.style === "feedback") {
    ctx.lineWidth = effect.final ? 10 : 5;
    for (let i = 0; i < 5; i += 1) {
      ctx.globalAlpha = alpha * (1 - i * .13);
      const radius = spread * (.22 + i * .18 + growth * .22);
      ctx.beginPath(); ctx.ellipse(0, 0, radius, radius * (.55 + i * .06), i % 2 ? .2 : -.2, 0, Math.PI * 2); ctx.stroke();
    }
  } else if (effect.style === "bass") {
    ctx.lineWidth = effect.final ? 12 : 6;
    ctx.beginPath(); ctx.arc(0, 0, 20 + growth * 28, 0, Math.PI * 2); ctx.fill();
    for (let i = 0; i < 5; i += 1) {
      ctx.globalAlpha = alpha * (1 - i * .14);
      ctx.beginPath(); ctx.arc(0, 0, spread * (.25 + i * .19 + growth * .16), -1.1, 1.1); ctx.stroke();
    }
  }
}

// --- CINEMA 3D fatality dressing -------------------------------------------
// True while the CINEMA 3D presentation is ON (toggle + eligible + loaded),
// including during scripted finishers where the world temporarily renders 2D.
// Every caller keeps the classic 2D path byte-identical when this is false.
function cinema3dDressingActive() {
  return Boolean(cinema3dBridge.renderer?.ready && state.cinema3d && cinema3dAllowed());
}

// One-time offscreen canvases for the 3D-mode fatality frame: an actually
// painted pizza-on-cutter wheel and a dimensional blood droplet sprite.
// Built lazily on first 3D fatality; nothing allocates per frame.
const fatalityDressing = { pizza: null, pizzaRim: null, droplet: null };

// Rim-only copy of the pizza wheel (outer steel + crust edge): the spin
// ghosts draw THIS, so the motion blur lives on the wheel's rim where a
// spinning disc actually smears, instead of double-printing the pepperoni.
function fatalityPizzaRimCanvas() {
  if (fatalityDressing.pizzaRim) return fatalityDressing.pizzaRim;
  const source = fatalityPizzaCanvas();
  const c = document.createElement("canvas");
  c.width = c.height = source.width;
  const p = c.getContext("2d");
  p.drawImage(source, 0, 0);
  p.globalCompositeOperation = "destination-out";
  const hole = p.createRadialGradient(c.width / 2, c.width / 2, c.width * 0.24,
    c.width / 2, c.width / 2, c.width * 0.4);
  hole.addColorStop(0, "rgba(0,0,0,1)");
  hole.addColorStop(1, "rgba(0,0,0,0)");
  p.fillStyle = hole;
  p.fillRect(0, 0, c.width, c.height);
  p.globalCompositeOperation = "source-over";
  fatalityDressing.pizzaRim = c;
  return c;
}

function fatalityPizzaCanvas() {
  if (fatalityDressing.pizza) return fatalityDressing.pizza;
  const size = 512;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const p = c.getContext("2d");
  const cx = size / 2;
  const hash = (n) => {
    const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
    return s - Math.floor(s);
  };
  // --- rusted steel cutter wheel under the pizza ---------------------------
  const steel = p.createRadialGradient(cx, cx, size * 0.3, cx, cx, size * 0.5);
  steel.addColorStop(0, "#565049");
  steel.addColorStop(0.82, "#6a635a");
  steel.addColorStop(1, "#4a443e");
  p.fillStyle = steel;
  p.beginPath();
  p.arc(cx, cx, size * 0.5 - 2, 0, Math.PI * 2);
  p.fill();
  // rust blotches riding the exposed rim
  for (let i = 0; i < 26; i += 1) {
    const a = hash(i) * Math.PI * 2;
    const rr = size * (0.435 + hash(i + 40) * 0.05);
    p.fillStyle = `rgba(${122 + Math.round(hash(i + 7) * 30)},${64 + Math.round(hash(i + 13) * 18)},38,${(0.35 + hash(i + 3) * 0.4).toFixed(2)})`;
    p.beginPath();
    p.ellipse(cx + Math.cos(a) * rr, cx + Math.sin(a) * rr,
      size * (0.012 + hash(i + 21) * 0.02), size * (0.008 + hash(i + 33) * 0.012), a, 0, Math.PI * 2);
    p.fill();
  }
  // sharpened cutting edge + cold specular arc (the metal must read METAL)
  p.lineWidth = size * 0.012;
  p.strokeStyle = "#b9bfc7";
  p.beginPath();
  p.arc(cx, cx, size * 0.488, 0, Math.PI * 2);
  p.stroke();
  p.lineWidth = size * 0.016;
  p.strokeStyle = "rgba(240,246,252,0.95)";
  p.beginPath();
  p.arc(cx, cx, size * 0.488, Math.PI * 1.12, Math.PI * 1.62);
  p.stroke();
  p.lineWidth = size * 0.01;
  p.strokeStyle = "rgba(18,16,14,0.8)";
  p.beginPath();
  p.arc(cx, cx, size * 0.488, Math.PI * 0.1, Math.PI * 0.55);
  p.stroke();
  // --- crust ring with charred blisters ------------------------------------
  const crustR = size * 0.42;
  const crust = p.createRadialGradient(cx, cx, size * 0.3, cx, cx, crustR);
  crust.addColorStop(0, "#c9873c");
  crust.addColorStop(0.75, "#d99a48");
  crust.addColorStop(1, "#a86a2a");
  p.fillStyle = crust;
  p.beginPath();
  p.arc(cx, cx, crustR, 0, Math.PI * 2);
  p.fill();
  for (let i = 0; i < 34; i += 1) {
    const a = (i / 34) * Math.PI * 2 + hash(i + 60) * 0.18;
    const rr = size * (0.365 + hash(i + 71) * 0.045);
    const blister = size * (0.012 + hash(i + 82) * 0.016);
    p.fillStyle = hash(i + 90) > 0.42 ? "rgba(122,70,26,0.85)" : "rgba(58,30,12,0.8)";
    p.beginPath();
    p.arc(cx + Math.cos(a) * rr, cx + Math.sin(a) * rr, blister, 0, Math.PI * 2);
    p.fill();
    p.fillStyle = "rgba(240,196,120,0.5)";
    p.beginPath();
    p.arc(cx + Math.cos(a) * rr - blister * 0.3, cx + Math.sin(a) * rr - blister * 0.35, blister * 0.4, 0, Math.PI * 2);
    p.fill();
  }
  // --- cheese field: mottled melt over sauce -------------------------------
  const cheeseR = size * 0.335;
  p.fillStyle = "#b04226"; // sauce base peeking through
  p.beginPath();
  p.arc(cx, cx, cheeseR, 0, Math.PI * 2);
  p.fill();
  for (let i = 0; i < 120; i += 1) {
    const a = hash(i + 200) * Math.PI * 2;
    const rr = Math.sqrt(hash(i + 210)) * cheeseR * 0.96;
    const blob = size * (0.02 + hash(i + 220) * 0.035);
    const tone = hash(i + 230);
    p.fillStyle = tone > 0.62 ? "rgba(242,220,143,0.9)" : tone > 0.25 ? "rgba(232,201,106,0.9)" : "rgba(214,178,84,0.85)";
    p.beginPath();
    p.ellipse(cx + Math.cos(a) * rr, cx + Math.sin(a) * rr, blob, blob * (0.6 + hash(i + 240) * 0.5), a, 0, Math.PI * 2);
    p.fill();
  }
  // browned cheese bubbles
  for (let i = 0; i < 26; i += 1) {
    const a = hash(i + 300) * Math.PI * 2;
    const rr = Math.sqrt(hash(i + 310)) * cheeseR * 0.9;
    p.fillStyle = `rgba(168,112,40,${(0.3 + hash(i + 320) * 0.35).toFixed(2)})`;
    p.beginPath();
    p.arc(cx + Math.cos(a) * rr, cx + Math.sin(a) * rr, size * (0.006 + hash(i + 330) * 0.01), 0, Math.PI * 2);
    p.fill();
  }
  // deep sauce gaps torn into the melt: the dark accents that keep the face
  // readable through the finisher bloom + saturation drain
  for (let i = 0; i < 12; i += 1) {
    const a = hash(i + 500) * Math.PI * 2;
    const rr = Math.sqrt(hash(i + 510)) * cheeseR * 0.85;
    p.fillStyle = `rgba(112,30,16,${(0.55 + hash(i + 520) * 0.3).toFixed(2)})`;
    p.beginPath();
    p.ellipse(cx + Math.cos(a) * rr, cx + Math.sin(a) * rr,
      size * (0.014 + hash(i + 530) * 0.022), size * (0.008 + hash(i + 540) * 0.012),
      a * 1.7, 0, Math.PI * 2);
    p.fill();
  }
  // edge shadow ring seating the cheese under the crust lip
  p.lineWidth = size * 0.014;
  p.strokeStyle = "rgba(88,44,14,0.7)";
  p.beginPath();
  p.arc(cx, cx, cheeseR * 0.99, 0, Math.PI * 2);
  p.stroke();
  // --- pepperoni: cupped discs with grease glints --------------------------
  for (let i = 0; i < 8; i += 1) {
    const a = (i / 8) * Math.PI * 2 + hash(i + 400) * 0.7;
    const rr = i === 7 ? cheeseR * 0.2 : cheeseR * (0.38 + hash(i + 410) * 0.5);
    const px = cx + Math.cos(a) * rr;
    const py = cx + Math.sin(a) * rr;
    const pr = size * (0.055 + hash(i + 420) * 0.014);
    // flat cured-meat read (the deep sphere gradient read as chocolate)
    const cup = p.createRadialGradient(px - pr * 0.2, py - pr * 0.24, pr * 0.3, px, py, pr);
    cup.addColorStop(0, "#c8523a");
    cup.addColorStop(0.7, "#b03a2a");
    cup.addColorStop(0.92, "#8a251a");
    cup.addColorStop(1, "#6e1a12");
    p.fillStyle = cup;
    p.beginPath();
    p.arc(px, py, pr, 0, Math.PI * 2);
    p.fill();
    // charred cup rim + grease specular
    p.lineWidth = pr * 0.16;
    p.strokeStyle = "rgba(52,12,8,0.75)";
    p.beginPath();
    p.arc(px, py, pr * 0.92, Math.PI * 0.1, Math.PI * 1.1);
    p.stroke();
    p.fillStyle = "rgba(255,214,178,0.85)";
    p.beginPath();
    p.ellipse(px - pr * 0.3, py - pr * 0.34, pr * 0.16, pr * 0.1, -0.6, 0, Math.PI * 2);
    p.fill();
  }
  // top-light: soft directional sheen across the whole face
  const sheen = p.createLinearGradient(0, 0, size, size);
  sheen.addColorStop(0, "rgba(255,240,210,0.16)");
  sheen.addColorStop(0.45, "rgba(255,240,210,0)");
  sheen.addColorStop(1, "rgba(30,10,4,0.18)");
  p.fillStyle = sheen;
  p.beginPath();
  p.arc(cx, cx, crustR, 0, Math.PI * 2);
  p.fill();
  // hub + bolt
  p.fillStyle = "#2c2a28";
  p.beginPath();
  p.arc(cx, cx, size * 0.055, 0, Math.PI * 2);
  p.fill();
  p.lineWidth = size * 0.008;
  p.strokeStyle = "#9aa0a8";
  p.stroke();
  p.fillStyle = "#e8edf2";
  p.beginPath();
  p.arc(cx - size * 0.014, cx - size * 0.016, size * 0.014, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.pizza = c;
  return c;
}

// Round-4 blood grammar (Kimberly-paint reference): a DIRECTIONAL teardrop —
// fat glossy head pointing +x, comma tail whipping back along -x — so every
// draw site can aim it along a velocity. Deep arterial reds (no browns), a
// hot core inside the head, a dark wet rim, one bright specular kiss.
function fatalityDropletCanvas() {
  if (fatalityDressing.droplet) return fatalityDressing.droplet;
  const size = 96;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const p = c.getContext("2d");
  // comma body: tail tip (12,47) -> top edge -> around the head -> sagging
  // bottom edge back to the tip.
  const body = () => {
    p.beginPath();
    p.moveTo(12, 47);
    p.bezierCurveTo(30, 37, 44, 31, 60, 31);
    p.arc(60, 48, 17, -Math.PI / 2, Math.PI / 2);
    p.bezierCurveTo(42, 66, 26, 57, 12, 47);
    p.closePath();
  };
  const grad = p.createRadialGradient(64, 43, 3, 60, 48, 42);
  grad.addColorStop(0, "#f3312c");
  grad.addColorStop(0.4, "#c00a18");
  grad.addColorStop(0.78, "#7c0411");
  grad.addColorStop(1, "#4a020c");
  p.fillStyle = grad;
  body();
  p.fill();
  // dark wet rim
  p.strokeStyle = "rgba(40,0,8,0.85)";
  p.lineWidth = 2.4;
  body();
  p.stroke();
  // hot arterial core inside the head
  const core = p.createRadialGradient(63, 44, 1, 63, 44, 11);
  core.addColorStop(0, "rgba(255,92,72,0.85)");
  core.addColorStop(1, "rgba(255,92,72,0)");
  p.fillStyle = core;
  p.beginPath();
  p.arc(63, 44, 11, 0, Math.PI * 2);
  p.fill();
  // specular kiss + glint on the head's upper-left (lamp side)
  p.fillStyle = "rgba(255,226,216,0.92)";
  p.beginPath();
  p.ellipse(56, 40, 6.2, 3.4, -0.5, 0, Math.PI * 2);
  p.fill();
  p.fillStyle = "rgba(255,255,255,0.95)";
  p.beginPath();
  p.arc(66, 38, 1.9, 0, Math.PI * 2);
  p.fill();
  // faint warm floor-bounce along the belly
  p.fillStyle = "rgba(255,122,88,0.28)";
  p.beginPath();
  p.ellipse(58, 58, 9, 2.6, 0.15, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.droplet = c;
  return c;
}

// Depth layering support: the same teardrop rendered through a tiny buffer so
// it comes back soft-edged — the FAR band of the gore field draws this one,
// while near droplets stay sharp (big sharp near, small soft far).
function fatalityDropletSoftCanvas() {
  if (fatalityDressing.dropletSoft) return fatalityDressing.dropletSoft;
  const sharp = fatalityDropletCanvas();
  const tiny = document.createElement("canvas");
  tiny.width = tiny.height = 20;
  tiny.getContext("2d").drawImage(sharp, 0, 0, 20, 20);
  const c = document.createElement("canvas");
  c.width = c.height = sharp.width;
  const p = c.getContext("2d");
  p.imageSmoothingEnabled = true;
  p.globalAlpha = 0.85;
  p.drawImage(tiny, 0, 0, c.width, c.height);
  fatalityDressing.dropletSoft = c;
  return c;
}

// Floor-hit splat: an irregular wet blot with RADIAL TAILS and satellite
// beads — what a droplet becomes the frame after it lands. Squashed by the
// caller onto the ground plane.
function fatalitySplatCanvas() {
  if (fatalityDressing.splat) return fatalityDressing.splat;
  const size = 128;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const p = c.getContext("2d");
  const cx = size / 2;
  const hash = (n) => {
    const s = Math.sin(n * 91.7 + 47.3) * 24634.5;
    return s - Math.floor(s);
  };
  p.lineCap = "round";
  // radial tails first (under the body): tapered strokes ending in beads
  for (let tail = 0; tail < 7; tail += 1) {
    const a = tail * 0.897 + hash(tail) * 0.5;
    const len = size * (0.2 + hash(tail + 9) * 0.22);
    const tx = cx + Math.cos(a) * len;
    const ty = cx + Math.sin(a) * len;
    p.strokeStyle = "rgba(122,4,17,0.9)";
    p.lineWidth = 4.5 - hash(tail + 4) * 2;
    p.beginPath();
    p.moveTo(cx + Math.cos(a) * size * 0.1, cx + Math.sin(a) * size * 0.1);
    p.quadraticCurveTo(cx + Math.cos(a) * len * 0.6, cx + Math.sin(a) * len * 0.6, tx, ty);
    p.stroke();
    p.fillStyle = "rgba(150,8,20,0.92)";
    p.beginPath();
    p.arc(tx, ty, 2.6 + hash(tail + 13) * 2, 0, Math.PI * 2);
    p.fill();
  }
  // satellite micro-beads flung past the tails
  for (let dot = 0; dot < 6; dot += 1) {
    const a = dot * 1.13 + 0.4;
    const len = size * (0.34 + hash(dot + 21) * 0.12);
    p.fillStyle = "rgba(140,6,18,0.8)";
    p.beginPath();
    p.arc(cx + Math.cos(a) * len, cx + Math.sin(a) * len, 1.6 + hash(dot + 27) * 1.4, 0, Math.PI * 2);
    p.fill();
  }
  // irregular blot body: overlapping lobes, dark rim tone under a hot centre
  const lobes = [[0, 0, 0.17], [0.09, 0.04, 0.12], [-0.1, 0.05, 0.1], [0.03, -0.08, 0.11]];
  for (const [ox, oy, r] of lobes) {
    const g = p.createRadialGradient(cx + ox * size, cx + oy * size, 1, cx + ox * size, cx + oy * size, r * size);
    g.addColorStop(0, "rgba(178,10,24,0.98)");
    g.addColorStop(0.72, "rgba(112,4,16,0.95)");
    g.addColorStop(1, "rgba(64,2,10,0.85)");
    p.fillStyle = g;
    p.beginPath();
    p.arc(cx + ox * size, cx + oy * size, r * size, 0, Math.PI * 2);
    p.fill();
  }
  // wet lamp streak
  p.fillStyle = "rgba(255,206,196,0.55)";
  p.beginPath();
  p.ellipse(cx - size * 0.05, cx - size * 0.06, size * 0.07, size * 0.025, -0.4, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.splat = c;
  return c;
}

// Round-3 debris variety (critic item 2): the lens pass mixes FOUR distinct
// sprites — glossy droplet (above), a matte torn MEAT CHUNK with a fat seam,
// a pale BONE FLECK, and an elongated SPLASH RIVULET — so the gore field
// stops reading as one pepperoni ellipse stamped 31 times. All lit from
// upper-left (the lamp) with a dark underside.
function fatalityChunkCanvas() {
  if (fatalityDressing.chunk) return fatalityDressing.chunk;
  const size = 96;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const p = c.getContext("2d");
  const cx = size / 2;
  // irregular torn polygon
  p.fillStyle = "#7c0d16";
  p.beginPath();
  p.moveTo(cx - size * 0.3, cx - size * 0.08);
  p.lineTo(cx - size * 0.12, cx - size * 0.3);
  p.lineTo(cx + size * 0.16, cx - size * 0.24);
  p.lineTo(cx + size * 0.32, cx + size * 0.02);
  p.lineTo(cx + size * 0.18, cx + size * 0.26);
  p.lineTo(cx - size * 0.1, cx + size * 0.3);
  p.lineTo(cx - size * 0.28, cx + size * 0.12);
  p.closePath();
  p.fill();
  // darker muscle striations
  p.strokeStyle = "#4e050c";
  p.lineWidth = 2.5;
  for (const [y0, y1] of [[-0.12, 0.08], [0.02, 0.2], [-0.22, -0.05]]) {
    p.beginPath();
    p.moveTo(cx - size * 0.2, cx + size * y0);
    p.quadraticCurveTo(cx, cx + size * (y0 + y1) * 0.5 + 3, cx + size * 0.2, cx + size * y1);
    p.stroke();
  }
  // fat seam + lamp-side highlight
  p.fillStyle = "rgba(232,206,178,0.85)";
  p.beginPath();
  p.ellipse(cx - size * 0.08, cx - size * 0.16, size * 0.12, size * 0.05, -0.4, 0, Math.PI * 2);
  p.fill();
  p.fillStyle = "rgba(214,80,72,0.7)";
  p.beginPath();
  p.ellipse(cx - size * 0.14, cx - size * 0.06, size * 0.08, size * 0.05, -0.5, 0, Math.PI * 2);
  p.fill();
  // dark underside
  p.fillStyle = "rgba(30,2,6,0.6)";
  p.beginPath();
  p.ellipse(cx + size * 0.06, cx + size * 0.2, size * 0.2, size * 0.08, 0.2, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.chunk = c;
  return c;
}
function fatalityBoneCanvas() {
  if (fatalityDressing.bone) return fatalityDressing.bone;
  const size = 64;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const p = c.getContext("2d");
  const cx = size / 2;
  p.lineCap = "round";
  // shard shaft with a snapped, flared end
  p.strokeStyle = "#e6d3b2";
  p.lineWidth = size * 0.14;
  p.beginPath();
  p.moveTo(cx - size * 0.24, cx + size * 0.16);
  p.lineTo(cx + size * 0.2, cx - size * 0.14);
  p.stroke();
  p.strokeStyle = "#f4e8cd";
  p.lineWidth = size * 0.07;
  p.beginPath();
  p.moveTo(cx - size * 0.22, cx + size * 0.13);
  p.lineTo(cx + size * 0.18, cx - size * 0.14);
  p.stroke();
  // splintered tip + marrow fleck + blood stain at the root
  p.fillStyle = "#f4e8cd";
  p.beginPath();
  p.moveTo(cx + size * 0.16, cx - size * 0.2);
  p.lineTo(cx + size * 0.32, cx - size * 0.24);
  p.lineTo(cx + size * 0.22, cx - size * 0.06);
  p.closePath();
  p.fill();
  p.fillStyle = "#b89a74";
  p.beginPath();
  p.arc(cx + size * 0.12, cx - size * 0.1, size * 0.045, 0, Math.PI * 2);
  p.fill();
  p.fillStyle = "rgba(150,12,16,0.85)";
  p.beginPath();
  p.ellipse(cx - size * 0.22, cx + size * 0.16, size * 0.1, size * 0.07, 0.5, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.bone = c;
  return c;
}
function fatalityRivuletCanvas() {
  if (fatalityDressing.rivulet) return fatalityDressing.rivulet;
  const w = 48;
  const h = 128;
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const p = c.getContext("2d");
  // elongated tear: fat glossy head, whipping thin tail
  const grad = p.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, "rgba(196,32,28,0.98)");
  grad.addColorStop(0.4, "rgba(150,12,16,0.95)");
  grad.addColorStop(1, "rgba(80,2,10,0.2)");
  p.fillStyle = grad;
  p.beginPath();
  p.moveTo(w * 0.5, h * 0.04);
  p.bezierCurveTo(w * 0.92, h * 0.16, w * 0.72, h * 0.42, w * 0.58, h * 0.66);
  p.quadraticCurveTo(w * 0.5, h * 0.86, w * 0.44, h * 0.97);
  p.quadraticCurveTo(w * 0.38, h * 0.8, w * 0.34, h * 0.6);
  p.bezierCurveTo(w * 0.2, h * 0.36, w * 0.14, h * 0.14, w * 0.5, h * 0.04);
  p.closePath();
  p.fill();
  // glossy head kiss
  p.fillStyle = "rgba(255,182,170,0.8)";
  p.beginPath();
  p.ellipse(w * 0.4, h * 0.14, w * 0.12, h * 0.045, -0.4, 0, Math.PI * 2);
  p.fill();
  fatalityDressing.rivulet = c;
  return c;
}

function drawFatalityPool(effect, alpha) {
  // 2.8 critic round (M2): the pool spreads and soaks on its own AGE clock,
  // which keeps running while the fatality hold freezes decal lifetimes —
  // the aftermath accumulates monotonically instead of dissolving mid-hold.
  const age = effect.age ?? ((effect.max || 1) - effect.life);
  const growth = Math.min(1, age / 3.2);
  const scale = effect.scale || 1;
  const soak = bloodSoak(age);
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.scale(effect.direction || 1, 1);
  ctx.globalAlpha = Math.min(1, alpha * 1.8);
  const pool = ctx.createRadialGradient(0, 0, 4, 0, 0, 116 * scale);
  pool.addColorStop(0, effect.color);
  pool.addColorStop(.54, effect.secondary);
  pool.addColorStop(1, "rgba(40,0,8,0)");
  ctx.fillStyle = pool;
  ctx.beginPath();
  ctx.ellipse(0, 0, (42 + growth * 112) * scale, 8 + growth * 25, 0, 0, Math.PI * 2);
  ctx.fill();
  if (soak > 0.05) {
    ctx.globalAlpha = Math.min(1, alpha * 1.5) * soak * 0.55;
    ctx.fillStyle = "#200105";
    ctx.beginPath();
    ctx.ellipse(0, 0, (36 + growth * 98) * scale, 7 + growth * 20, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // 2.8 critic round (M4): the CINEMA 3D wet dressing is the DEFAULT now —
  // darkened blood core, a glossy lamp streak that dies as the pool soaks
  // matte, and directional spatter with dimensional cores + run-tails
  // instead of flat matte ellipses.
  const core = ctx.createRadialGradient(0, 0, 2, 0, 0, 72 * scale);
  core.addColorStop(0, "rgba(60,2,8,0.85)");
  core.addColorStop(0.6, "rgba(96,6,12,0.4)");
  core.addColorStop(1, "rgba(60,2,8,0)");
  ctx.globalAlpha = Math.min(1, alpha * 1.6);
  ctx.fillStyle = core;
  ctx.beginPath();
  ctx.ellipse(0, 0, (34 + growth * 74) * scale, 6 + growth * 15, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = Math.min(1, alpha * 1.2) * 0.55 * (1 - soak * 0.6);
  ctx.fillStyle = "rgba(210,236,225,0.5)"; // lamp streak on the wet surface
  ctx.beginPath();
  ctx.ellipse(10 * scale, -2, (20 + growth * 30) * scale, 2.6 + growth * 3, -0.06, 0, Math.PI * 2);
  ctx.fill();
  const droplet = fatalityDropletCanvas();
  for (let drop = 0; drop < 13; drop += 1) {
    const angle = drop * 2.399 + (effect.family === "glitch" ? .4 : 0);
    const reach = (24 + growth * 118) * (.45 + (drop % 5) * .14) * scale;
    const dx = Math.cos(angle) * reach;
    const dy = Math.sin(angle) * reach * .22;
    const size = (7 + drop % 4 * 4.5) * (1 + growth * 0.3);
    ctx.globalAlpha = alpha * (.44 + drop % 3 * .2);
    // run-tail streaking back toward the pool centre
    ctx.strokeStyle = effect.color;
    ctx.lineCap = "round";
    ctx.lineWidth = Math.max(1.6, size * 0.22);
    ctx.beginPath();
    ctx.moveTo(dx * 0.55, dy * 0.55);
    ctx.lineTo(dx, dy);
    ctx.stroke();
    ctx.save();
    ctx.translate(dx, dy);
    if (drop % 4 === 0) {
      // landed hit: splat with radial tails flattened onto the floor plane
      ctx.rotate(angle * 0.3);
      ctx.scale(1.3, 0.45);
      ctx.drawImage(fatalitySplatCanvas(), -size * 1.4, -size * 1.4, size * 2.8, size * 2.8);
    } else {
      // teardrop head pointing away from the pool, kept shallow so the
      // spatter lies ON the floor plane instead of standing up out of it
      ctx.rotate(Math.sin(angle) * 0.35);
      ctx.scale(1.3, 0.55);
      ctx.drawImage(droplet, -size * 0.85, -size * 0.85, size * 1.7, size * 1.7);
    }
    ctx.restore();
  }
  if (["rupture", "launch", "crush"].includes(effect.family)) {
    ctx.globalAlpha = alpha * .82;
    ctx.fillStyle = "#e9d6b1";
    ctx.strokeStyle = "#6d0c19";
    ctx.lineWidth = 4;
    ctx.rotate(-.18);
    ctx.beginPath();
    ctx.rect(-31, -13, 62, 14);
    ctx.fill();
    ctx.stroke();
  }
  ctx.restore();
}

// CINEMA 3D painted severed limb (round-3, critic item 2): the flat capsule
// strokes read as a pink rubber glove on a teal toy — this builds a properly
// PAINTED limb sprite once per (limb, palette): shaded torn sleeve, modelled
// forearm + curled fist (or jeans + boot), a real gore stump (blood ring,
// bone, hanging shreds), warm rim light from the wheel's glow along one edge
// and a cool night kiss on the other, matching the fighters' rendered-paint
// language. Built lazily, cached; the classic 2D primitives are untouched.
const severedLimbCache = new Map();

// Round-4 (ship-review item 2): the severed arm is composited from the
// VICTIM'S OWN ATLAS PIXELS. Frame 10 of the shared 4x4 grammar is the fully
// extended straight punch — a clean horizontal forearm + fist painted in the
// fighter's own rendered language (Jez: bare muscled forearm, wrist wrap,
// black glove, torn blue gi at the shoulder). HD sheet when ready (same map
// the super close-up warms), SD atlas as fallback, null before either loads.
// 2.7 critic round: renderer/hd holds sheets for SOME fighters only (devil
// has none — the authoritative list is renderer/hd/MANIFEST.json, mirrored
// here so no code path ever REQUESTS an HD sheet that does not exist: with
// ?renderer=3d the old unconditional warm-ups 404'd on every devil bout).
// Absent entries skip silently and the SD atlas draws, exactly like an HD
// sheet that never finished loading.
//
// v5.3 SPECIALS: the eight renderer/hd/<id>-specials sheets are RETIRED and
// deleted. They were 2x upscales of the base-generation specials art, and 5.3
// redrew that art in the unified generation — so an HD swap would have put the
// OLD generation on the 3D rig's whole specials bank and in the super-portrait
// close-up while the 2D canvas drew the new one. The rule the wave is built on
// is that a bank is ONE generation; a stale HD variant is the same fault with
// an extra download. Regenerating them at 2x is a separate job (the SD sheets
// are the masters); until then the specials bank is SD in both renderers,
// which is what every other authored bank already does.
const HD_SHEETS = new Set([
  "alan", "ali", "benny", "commissioner", "cyraxx", "deathblow",
  "donald", "jez", "post",
]);

function hdSheetPath(fighterId, bank = "base") {
  // Only the combat atlas has an HD variant; every other bank is SD-only and
  // must never be requested from renderer/hd/.
  return bank === "base" && HD_SHEETS.has(fighterId) ? `renderer/hd/${fighterId}.webp` : null;
}

function severedArmAtlasSource(victimId) {
  const sd = fighterAtlases[victimId];
  if (!sd?.complete || !sd.naturalWidth) return null;
  const hdPath = hdSheetPath(victimId);
  if (hdPath && !superPortraitHdImages.has(hdPath)) {
    const img = new Image();
    img.src = hdPath;
    superPortraitHdImages.set(hdPath, img);
  }
  const hd = hdPath ? superPortraitHdImages.get(hdPath) : null;
  const atlas = hd?.complete && hd.naturalWidth ? hd : sd;
  const cell = atlas.naturalWidth / 4;
  const x0 = 2 * cell; // frame 10 = column 2, row 2
  const y0 = 2 * cell;
  return {
    atlas,
    tag: atlas === hd ? "hd" : "sd",
    // crop: deltoid through glove knuckles (cell-normalised, grammar-level)
    sx: x0 + cell * 0.4609, sy: y0 + cell * 0.1875,
    sw: cell * 0.5234, sh: cell * 0.1953,
    // arm axis anchors in atlas pixels: mid-shoulder -> fist knuckles
    axAx: x0 + cell * 0.5312, axAy: y0 + cell * 0.2969,
    axBx: x0 + cell * 0.9609, axBy: y0 + cell * 0.2734,
  };
}

function severedLimbPaintedCanvas(effect, victimId = null, warmSide = 1) {
  const leg = effect.limb.endsWith("leg");
  const armSrc = !leg && victimId ? severedArmAtlasSource(victimId) : null;
  const key = `${leg ? "leg" : "arm"}:${victimId || "-"}:${armSrc ? armSrc.tag : "painted"}:${warmSide}`
    + `:${effect.clothColor}:${effect.clothAccent}:${effect.color}:${effect.secondary}`;
  if (severedLimbCache.has(key)) return severedLimbCache.get(key);
  const length = leg ? 92 : 72;
  const thickness = leg ? 30 : 23;
  const scale = 2; // authored at 2x, played back at 1x
  const c = document.createElement("canvas");
  c.width = Math.round(length * 1.5 * scale);
  c.height = Math.round(thickness * 3.2 * scale);
  const p = c.getContext("2d");
  p.scale(scale, scale);
  p.translate(length * 0.75, thickness * 1.6);
  p.lineCap = "round";
  p.lineJoin = "round";
  const shade = (hex, f) => {
    const n = parseInt(hex.replace("#", ""), 16);
    const r = Math.min(255, Math.round(((n >> 16) & 255) * f));
    const g = Math.min(255, Math.round(((n >> 8) & 255) * f));
    const b = Math.min(255, Math.round((n & 255) * f));
    return `rgb(${r},${g},${b})`;
  };
  // Fabric, not roster accent: the raw def.color is a UI hue (Jez's is
  // near-cyan) — pulled 72% toward a night-fabric slate so the sleeve reads
  // as the fighter's CLOTHING under stage light, never a toy shell.
  const mixHex = (hexA, hexB, t) => {
    const a = parseInt((hexA || "#3a5a8c").replace("#", ""), 16);
    const b = parseInt(hexB.replace("#", ""), 16);
    const channel = (sh) => Math.round(((a >> sh) & 255) * (1 - t) + ((b >> sh) & 255) * t)
      .toString(16).padStart(2, "0");
    return `#${channel(16)}${channel(8)}${channel(0)}`;
  };
  const cloth = mixHex(effect.clothColor, "#33415e", 0.72);
  const skin = "#c98b70";
  const gore = effect.color || "#a11220";
  const goreDeep = effect.secondary || "#6d0c19";
  // The limb is built as STACKED TAPERED STROKES (dark underlayer, mid tone,
  // top-half highlight) along a gently sagging axis — round painted forms,
  // no straight bars, no full-length rim rods.
  const sag = leg ? 4 : 2.6;
  const axis = (t) => ({ x: t * length, y: Math.sin((t + 0.42) * 2.4) * sag });
  const strokeAlong = (t0, t1, width, tone, offY = 0, alphaScale = 1) => {
    p.strokeStyle = tone;
    p.globalAlpha = alphaScale;
    p.lineWidth = width;
    p.beginPath();
    const a0 = axis(t0);
    const mid = axis((t0 + t1) / 2);
    const a1 = axis(t1);
    p.moveTo(a0.x, a0.y + offY);
    p.quadraticCurveTo(mid.x, mid.y + offY + 1.2, a1.x, a1.y + offY);
    p.stroke();
    p.globalAlpha = 1;
  };
  const stumpT = -0.42;
  const stumpAt = axis(stumpT);
  if (leg) {
    // thigh->calf in torn jeans, boot at the far end
    strokeAlong(-0.36, 0.3, thickness * 1.04, shade(cloth, 0.62));
    strokeAlong(-0.36, 0.3, thickness * 0.9, cloth);
    strokeAlong(-0.34, 0.26, thickness * 0.4, shade(cloth, 1.3), -thickness * 0.2, 0.85);
    // knee crease + fold shadows
    p.strokeStyle = shade(cloth, 0.55);
    p.lineWidth = 1.8;
    for (const fx of [-0.12, 0.05, 0.2]) {
      const at = axis(fx);
      p.beginPath();
      p.moveTo(at.x, at.y - thickness * 0.3);
      p.quadraticCurveTo(at.x + 2.5, at.y, at.x + 1, at.y + thickness * 0.32);
      p.stroke();
    }
    // boot: rounded leather mass + heel + pale sole line
    const bootAt = axis(0.42);
    p.fillStyle = "#1a1c22";
    p.beginPath();
    p.ellipse(bootAt.x + thickness * 0.16, bootAt.y + 1, thickness * 0.52, thickness * 0.42, 0.12, 0, Math.PI * 2);
    p.fill();
    p.beginPath();
    p.ellipse(bootAt.x + thickness * 0.62, bootAt.y + thickness * 0.16, thickness * 0.34, thickness * 0.28, 0.3, 0, Math.PI * 2);
    p.fill();
    p.fillStyle = "#2e323c"; // top-light on the toe
    p.beginPath();
    p.ellipse(bootAt.x + thickness * 0.5, bootAt.y - thickness * 0.08, thickness * 0.24, thickness * 0.12, 0.3, 0, Math.PI * 2);
    p.fill();
    p.strokeStyle = "#565c68";
    p.lineWidth = 2.2;
    p.beginPath();
    p.moveTo(bootAt.x + thickness * 0.1, bootAt.y + thickness * 0.36);
    p.quadraticCurveTo(bootAt.x + thickness * 0.5, bootAt.y + thickness * 0.44, bootAt.x + thickness * 0.86, bootAt.y + thickness * 0.3);
    p.stroke();
  } else if (armSrc) {
    // --- HERO PROP: the victim's actual arm, cut off his sprite -------------
    // The atlas punch-arm is clipped to a lumpy capsule along the limb axis,
    // sheared off at the stump on a wedge plane, then dressed: torn sleeve
    // lip with hanging threads, layered gore cross-section (dermis, muscle
    // wedges, bone ring with marrow, wet sheen), warm wheel-glow rim on the
    // screen-down edge (warmSide) and a night-cool key opposite.
    const armPath = () => {
      p.beginPath();
      for (const [t, r] of [[-0.6, 0.64], [-0.48, 0.7], [-0.34, 0.68], [-0.2, 0.62], [-0.06, 0.56],
        [0.08, 0.5], [0.2, 0.46], [0.3, 0.45], [0.4, 0.55], [0.48, 0.62]]) {
        const at = axis(t);
        p.moveTo(at.x + thickness * r, at.y);
        p.arc(at.x, at.y, thickness * r, 0, Math.PI * 2);
      }
    };
    // Cut plane sits INSIDE the sampled torn-sleeve band, so a strip of the
    // victim's actual blue gi survives on the stump side of the sever.
    const cutAt = axis(-0.56);
    // 1) the sampled arm, axis-mapped shoulder->stump so the sever runs
    //    through the torn gi sleeve and the glove stays at the far end
    const dstA = axis(-0.52);
    const dstB = axis(0.5);
    const srcAngle = Math.atan2(armSrc.axBy - armSrc.axAy, armSrc.axBx - armSrc.axAx);
    const dstAngle = Math.atan2(dstB.y - dstA.y, dstB.x - dstA.x);
    const fit = Math.hypot(dstB.x - dstA.x, dstB.y - dstA.y)
      / Math.hypot(armSrc.axBx - armSrc.axAx, armSrc.axBy - armSrc.axAy);
    p.save();
    armPath();
    p.clip();
    p.translate(dstA.x, dstA.y);
    p.rotate(dstAngle - srcAngle);
    p.scale(fit, fit * 1.16); // slight fatten across the axis: hero presence
    p.drawImage(armSrc.atlas, armSrc.sx, armSrc.sy, armSrc.sw, armSrc.sh,
      armSrc.sx - armSrc.axAx, armSrc.sy - armSrc.axAy, armSrc.sw, armSrc.sh);
    p.restore();
    // 2) light story clipped to the same silhouette: cool night key on the
    //    screen-up edge, wheel-glow warmth on the screen-down edge, a soft
    //    core shadow between them so the arm reads ROUND at play distance
    p.save();
    armPath();
    p.clip();
    const bboxX = -length * 0.82;
    const bboxW = length * 1.64;
    const coolG = p.createLinearGradient(0, -warmSide * thickness * 0.78, 0, -warmSide * thickness * 0.08);
    coolG.addColorStop(0, "rgba(150,190,255,0.28)");
    coolG.addColorStop(1, "rgba(150,190,255,0)");
    p.fillStyle = coolG;
    p.fillRect(bboxX, -thickness * 1.55, bboxW, thickness * 3.1);
    const shadeG = p.createLinearGradient(0, warmSide * thickness * 0.05, 0, warmSide * thickness * 0.52);
    shadeG.addColorStop(0, "rgba(26,8,16,0)");
    shadeG.addColorStop(1, "rgba(26,8,16,0.3)");
    p.fillStyle = shadeG;
    p.fillRect(bboxX, -thickness * 1.55, bboxW, thickness * 3.1);
    const warmG = p.createLinearGradient(0, warmSide * thickness * 0.3, 0, warmSide * thickness * 0.78);
    warmG.addColorStop(0, "rgba(255,150,54,0)");
    warmG.addColorStop(1, "rgba(255,158,58,0.5)");
    p.fillStyle = warmG;
    p.fillRect(bboxX, -thickness * 1.55, bboxW, thickness * 3.1);
    p.restore();
    // 3) shear everything past the cut plane off on a wedge angle
    p.save();
    p.translate(cutAt.x, cutAt.y);
    p.rotate(-0.28);
    p.globalCompositeOperation = "destination-out";
    p.fillRect(-length * 1.4, -thickness * 2.4, length * 1.4, thickness * 4.8);
    p.restore();
    // 4) torn sleeve lip biting over the cut, threads whipping off the fray
    p.save();
    p.translate(cutAt.x, cutAt.y);
    p.rotate(-0.28);
    const fray = (n) => {
      const s = Math.sin(n * 61.7 + 13.9) * 15731.3;
      return s - Math.floor(s);
    };
    // gi-blue for the painted sleeve parts: the roster colour is a UI hue
    // (Jez's is near-cyan), pulled hard toward the atlas gi's royal blue so
    // painted cloth and sampled cloth read as the SAME garment
    const gi = mixHex(effect.clothColor, "#31518f", 0.9);
    // the surviving sleeve: a torn cloth band around the upper bicep, clear
    // of the cross-section — jagged fist-side edge, fold shadows, a lit
    // frayed lip on the cut side
    p.beginPath();
    p.moveTo(9.5, -thickness * 0.56);
    for (let seg = 0; seg <= 6; seg += 1) {
      p.lineTo(16.6 + (fray(seg + 51) - 0.5) * 5, -thickness * 0.56 + (seg / 6) * thickness * 1.12);
    }
    p.lineTo(9.5, thickness * 0.56);
    p.closePath();
    p.fillStyle = gi;
    p.fill();
    p.strokeStyle = shade(gi, 0.55); // fold shadows down the band
    p.lineWidth = 1.1;
    for (const fy of [-0.3, 0.02, 0.3]) {
      p.beginPath();
      p.moveTo(11.4, thickness * fy - 2.4);
      p.quadraticCurveTo(13.8, thickness * fy + 0.5, 12.2, thickness * fy + 3.2);
      p.stroke();
    }
    p.strokeStyle = shade(gi, 1.42); // lit frayed lip on the cut side
    p.lineWidth = 1.2;
    p.beginPath();
    p.moveTo(10.2, -thickness * 0.5);
    p.quadraticCurveTo(11.8, 0, 10.4, thickness * 0.5);
    p.stroke();
    for (let tooth = 0; tooth < 7; tooth += 1) {
      const ta = (tooth / 7) * Math.PI * 2 + 0.3;
      const rimX = Math.cos(ta) * thickness * 0.52;
      const rimY = Math.sin(ta) * thickness * 0.46;
      p.fillStyle = fray(tooth) > 0.55 ? shade(gi, 1.22) : shade(gi, 0.82);
      p.beginPath();
      p.moveTo(rimX, rimY - thickness * 0.1);
      p.lineTo(rimX + 2.4 + fray(tooth + 5) * 2.6, rimY + (fray(tooth + 9) - 0.5) * 3);
      p.lineTo(rimX, rimY + thickness * 0.1);
      p.closePath();
      p.fill();
    }
    p.lineCap = "round";
    for (let thread = 0; thread < 3; thread += 1) {
      const ty = (thread - 1) * thickness * 0.26 + 1;
      p.strokeStyle = thread === 1 ? shade(gi, 1.5) : shade(gi, 0.7);
      p.lineWidth = 0.9;
      p.beginPath();
      p.moveTo(-thickness * 0.1, ty);
      p.quadraticCurveTo(
        -thickness * (0.34 + fray(thread + 3) * 0.2),
        ty + warmSide * (2 + fray(thread + 7) * 3.5),
        -thickness * (0.52 + fray(thread + 11) * 0.26),
        ty + warmSide * (5 + fray(thread + 13) * 4),
      );
      p.stroke();
    }
    // 5) the wedge cross-section: asymmetric, wet, torn — NOT a bullseye.
    // Lumpy dark base, off-origin muscle bundles in two close reds with
    // radial fibre strokes, a short skin lip on the lamp side only, a small
    // off-centre bone chip, clots breaking the silhouette, sheen on top.
    const rx = thickness * 0.52;
    const ry = thickness * 0.46;
    p.fillStyle = "#3c020b"; // congealed base, lumpy silhouette
    p.beginPath();
    p.ellipse(0, 0, rx, ry * 0.94, 0.18, 0, Math.PI * 2);
    p.ellipse(rx * 0.2, -ry * 0.26, rx * 0.74, ry * 0.66, 0.5, 0, Math.PI * 2);
    p.ellipse(-rx * 0.22, ry * 0.24, rx * 0.7, ry * 0.62, -0.4, 0, Math.PI * 2);
    p.ellipse(rx * 0.05, ry * 0.4, rx * 0.6, ry * 0.5, 0.9, 0, Math.PI * 2);
    p.fill();
    for (let bundle = 0; bundle < 5; bundle += 1) { // muscle bundles, off-origin
      const a0 = bundle * 1.256 + fray(bundle + 15) * 0.7;
      const wr = rx * (0.5 + fray(bundle + 17) * 0.3);
      const ox = (fray(bundle + 19) - 0.5) * rx * 0.5;
      const oy = (fray(bundle + 21) - 0.5) * ry * 0.5;
      p.fillStyle = bundle % 2 ? "#9c0715" : "#b30d1a";
      p.beginPath();
      p.ellipse(ox, oy, wr, wr * (0.55 + fray(bundle + 25) * 0.3), a0, 0, Math.PI * 2);
      p.fill();
    }
    p.strokeStyle = "rgba(58,2,10,0.8)"; // radial fibre strokes
    p.lineWidth = 1;
    for (let fibre = 0; fibre < 5; fibre += 1) {
      const fa = fibre * 1.35 + 0.5 + fray(fibre + 29) * 0.5;
      p.beginPath();
      p.moveTo(Math.cos(fa) * rx * 0.2, Math.sin(fa) * ry * 0.2);
      p.lineTo(Math.cos(fa) * rx * (0.6 + fray(fibre + 33) * 0.28),
        Math.sin(fa) * ry * (0.6 + fray(fibre + 35) * 0.28));
      p.stroke();
    }
    // short skin lip on the lamp side only (no full outline ring)
    p.lineWidth = 1.5;
    p.strokeStyle = "rgba(235,176,148,0.75)";
    p.beginPath();
    p.ellipse(0, 0, rx * 0.94, ry * 0.92, 0.18, -2.5, -1.3);
    p.stroke();
    // small bone chip high of centre: pale wedge with a marrow fleck and an
    // inner crescent shadow — a chip, not a ring
    p.save();
    p.translate(-rx * 0.26, -ry * 0.3);
    p.rotate(-0.4);
    p.fillStyle = "#f6ecd4";
    p.beginPath();
    p.ellipse(0, 0, thickness * 0.13, thickness * 0.1, 0, 0, Math.PI * 2);
    p.fill();
    p.strokeStyle = "rgba(150,118,80,0.7)";
    p.lineWidth = 0.9;
    p.beginPath();
    p.arc(thickness * 0.02, thickness * 0.02, thickness * 0.09, 0.4, 2.2);
    p.stroke();
    p.fillStyle = "#c59f68";
    p.beginPath();
    p.ellipse(thickness * 0.035, thickness * 0.02, thickness * 0.045, thickness * 0.032, 0.3, 0, Math.PI * 2);
    p.fill();
    p.restore();
    // dark clots riding the rim, breaking any circular read
    p.fillStyle = "#2c0108";
    p.beginPath();
    p.ellipse(rx * 0.6, ry * 0.34, rx * 0.2, ry * 0.14, 0.6, 0, Math.PI * 2);
    p.ellipse(-rx * 0.5, ry * 0.5, rx * 0.16, ry * 0.12, -0.5, 0, Math.PI * 2);
    p.fill();
    // wet sheen crescent + specular pin-lights on the cut's lamp side
    p.strokeStyle = "rgba(255,198,188,0.8)";
    p.lineWidth = 1.6;
    p.beginPath();
    p.arc(1, 0.5, rx * 0.74, -2.8, -1.7);
    p.stroke();
    p.fillStyle = "rgba(255,236,230,0.95)";
    p.beginPath();
    p.arc(-2.4, -3.6, 1.2, 0, Math.PI * 2);
    p.arc(3.4, -1.2, 0.8, 0, Math.PI * 2);
    p.fill();
    // gore shreds sagging off the screen-down lip + two gravity drips
    p.fillStyle = "#7c0512";
    p.beginPath();
    p.moveTo(-rx * 0.3, warmSide * ry * 0.7);
    p.quadraticCurveTo(-rx * 0.16, warmSide * (ry * 0.7 + 4.6), -rx * 0.02, warmSide * ry * 0.74);
    p.closePath();
    p.fill();
    p.beginPath();
    p.moveTo(rx * 0.2, warmSide * ry * 0.78);
    p.quadraticCurveTo(rx * 0.32, warmSide * (ry * 0.78 + 3.4), rx * 0.46, warmSide * ry * 0.7);
    p.closePath();
    p.fill();
    p.strokeStyle = "#a50713";
    p.lineWidth = 2;
    p.beginPath();
    p.moveTo(-rx * 0.1, warmSide * ry * 0.85);
    p.quadraticCurveTo(-rx * 0.16, warmSide * (ry * 0.85 + 5), -rx * 0.1, warmSide * (ry * 0.85 + 8));
    p.stroke();
    p.lineWidth = 1.3;
    p.beginPath();
    p.moveTo(rx * 0.34, warmSide * ry * 0.8);
    p.quadraticCurveTo(rx * 0.3, warmSide * (ry * 0.8 + 3.6), rx * 0.33, warmSide * (ry * 0.8 + 5.6));
    p.stroke();
    p.restore();
    // 6) fine blood flecks blown back along the forearm from the wound
    p.fillStyle = "rgba(156,7,21,0.75)";
    for (let fleck = 0; fleck < 6; fleck += 1) {
      const ft = -0.34 + fray(fleck + 23) * 0.5;
      const at = axis(ft);
      p.beginPath();
      p.ellipse(at.x, at.y + (fray(fleck + 31) - 0.5) * thickness * 0.7,
        1.5 + fray(fleck + 37) * 1.6, 0.8 + fray(fleck + 41) * 0.9,
        fray(fleck + 43) * 3, 0, Math.PI * 2);
      p.fill();
    }
  } else {
    // --- torn tee sleeve over the upper arm ---------------------------------
    strokeAlong(-0.36, -0.08, thickness * 1.02, shade(cloth, 0.6));
    strokeAlong(-0.36, -0.08, thickness * 0.88, cloth);
    strokeAlong(-0.35, -0.1, thickness * 0.36, shade(cloth, 1.34), -thickness * 0.18, 0.85);
    // torn cuff: small cloth-dark triangles biting into the arm
    p.fillStyle = shade(cloth, 0.72);
    const cuffAt = axis(-0.08);
    for (let z = 0; z < 3; z += 1) {
      p.beginPath();
      p.moveTo(cuffAt.x - 2, cuffAt.y - thickness * 0.42 + z * thickness * 0.3);
      p.lineTo(cuffAt.x + thickness * 0.24, cuffAt.y - thickness * 0.3 + z * thickness * 0.3);
      p.lineTo(cuffAt.x - 2, cuffAt.y - thickness * 0.18 + z * thickness * 0.3);
      p.closePath();
      p.fill();
    }
    // sleeve fold shadows
    p.strokeStyle = shade(cloth, 0.52);
    p.lineWidth = 1.6;
    for (const fx of [-0.28, -0.17]) {
      const at = axis(fx);
      p.beginPath();
      p.moveTo(at.x, at.y - thickness * 0.3);
      p.quadraticCurveTo(at.x + 2.2, at.y + 1, at.x + 0.5, at.y + thickness * 0.3);
      p.stroke();
    }
    // --- forearm: rounded skin with a top-half light plane ------------------
    strokeAlong(-0.1, 0.36, thickness * 0.74, shade(skin, 0.68));
    strokeAlong(-0.1, 0.36, thickness * 0.62, skin);
    strokeAlong(-0.08, 0.32, thickness * 0.26, shade(skin, 1.2), -thickness * 0.13, 0.9);
    // tendon hint + wrist crease (short, curved)
    p.strokeStyle = shade(skin, 0.58);
    p.lineWidth = 1.3;
    const tA = axis(0.05);
    const tB = axis(0.3);
    p.beginPath();
    p.moveTo(tA.x, tA.y - thickness * 0.06);
    p.quadraticCurveTo((tA.x + tB.x) / 2, tA.y - thickness * 0.12, tB.x, tB.y - thickness * 0.02);
    p.stroke();
    const wr = axis(0.37);
    p.beginPath();
    p.moveTo(wr.x, wr.y - thickness * 0.2);
    p.quadraticCurveTo(wr.x + 1.6, wr.y, wr.x, wr.y + thickness * 0.18);
    p.stroke();
    // --- curled fist: palm mass, knuckle arc along the top, tucked thumb ----
    const fist = axis(0.48);
    p.fillStyle = shade(skin, 0.82);
    p.beginPath();
    p.ellipse(fist.x + thickness * 0.1, fist.y + 1, thickness * 0.34, thickness * 0.38, -0.12, 0, Math.PI * 2);
    p.fill();
    // knuckle bumps riding the leading arc
    for (let finger = 0; finger < 4; finger += 1) {
      const ka = -1.05 + finger * 0.6;
      const kx = fist.x + thickness * 0.1 + Math.cos(ka) * thickness * 0.32;
      const ky = fist.y + 1 + Math.sin(ka) * thickness * 0.36;
      p.fillStyle = finger % 2 ? skin : shade(skin, 1.1);
      p.beginPath();
      p.ellipse(kx, ky, thickness * 0.12, thickness * 0.1, ka, 0, Math.PI * 2);
      p.fill();
    }
    // finger creases between the knuckles
    p.strokeStyle = shade(skin, 0.55);
    p.lineWidth = 1.2;
    for (let crease = 0; crease < 3; crease += 1) {
      const ca = -0.75 + crease * 0.6;
      p.beginPath();
      p.arc(fist.x + thickness * 0.1, fist.y + 1, thickness * 0.3, ca - 0.14, ca + 0.14);
      p.stroke();
    }
    // thumb wrapping low across the palm
    p.fillStyle = shade(skin, 1.06);
    p.beginPath();
    p.ellipse(fist.x - thickness * 0.02, fist.y + thickness * 0.24, thickness * 0.17, thickness * 0.1, 0.5, 0, Math.PI * 2);
    p.fill();
  }
  // --- gore stump at the shoulder/thigh end (drawn OVER the limb root) -----
  // Torn cross-section: dark rim, meat wedges, off-centre bone chip — an
  // anatomy read, not a glossy ball. (The atlas-composited arm carries its
  // own layered wedge stump + light story above, so this round-3 pass only
  // runs for legs and the no-atlas fallback.)
  if (!armSrc) {
  p.fillStyle = goreDeep;
  p.beginPath();
  p.ellipse(stumpAt.x, stumpAt.y, thickness * 0.44, thickness * 0.4, -0.1, 0, Math.PI * 2);
  p.fill();
  // meat wedges: radial pie segments in two reds
  for (let wedge = 0; wedge < 5; wedge += 1) {
    const a0 = wedge * 1.256 + 0.35;
    const wr = thickness * (0.27 + ((wedge * 37) % 11) / 11 * 0.09);
    p.fillStyle = wedge % 2 ? gore : shade(gore, 0.78);
    p.beginPath();
    p.moveTo(stumpAt.x + Math.cos(a0 + 0.5) * 2, stumpAt.y + Math.sin(a0 + 0.5) * 2);
    p.arc(stumpAt.x, stumpAt.y, wr, a0, a0 + 1.15);
    p.closePath();
    p.fill();
  }
  // wet sheen crescent on the upper lip of the cut
  p.strokeStyle = "rgba(255,158,148,0.55)";
  p.lineWidth = 1.8;
  p.beginPath();
  p.arc(stumpAt.x, stumpAt.y, thickness * 0.32, Math.PI * 1.15, Math.PI * 1.75);
  p.stroke();
  // bone chip: pale, high of centre, with a marrow fleck
  p.fillStyle = "#e6d3b2";
  p.beginPath();
  p.ellipse(stumpAt.x - thickness * 0.11, stumpAt.y - thickness * 0.14, thickness * 0.08, thickness * 0.065, 0.3, 0, Math.PI * 2);
  p.fill();
  p.fillStyle = "#a8906c";
  p.beginPath();
  p.arc(stumpAt.x - thickness * 0.11, stumpAt.y - thickness * 0.14, thickness * 0.028, 0, Math.PI * 2);
  p.fill();
  // one short drip + a flung droplet — restrained
  p.strokeStyle = gore;
  p.lineWidth = 2;
  p.beginPath();
  p.moveTo(stumpAt.x - thickness * 0.12, stumpAt.y + thickness * 0.36);
  p.quadraticCurveTo(stumpAt.x - thickness * 0.18, stumpAt.y + thickness * 0.62, stumpAt.x - thickness * 0.12, stumpAt.y + thickness * 0.8);
  p.stroke();
  p.fillStyle = gore;
  p.beginPath();
  p.ellipse(stumpAt.x - thickness * 0.34, stumpAt.y + thickness * 0.5, 2.1, 2.8, 0.3, 0, Math.PI * 2);
  p.fill();
  // --- light story: SHORT warm dashes on the wheel side, one cool kiss ------
  p.lineCap = "round";
  p.strokeStyle = "rgba(255,166,70,0.55)";
  p.lineWidth = 1.7;
  for (const [d0, d1, hug] of [[-0.3, -0.2, leg ? 0.47 : 0.4], [-0.04, 0.08, leg ? 0.44 : 0.28], [0.22, 0.32, leg ? 0.42 : 0.26]]) {
    const a0 = axis(d0);
    const a1 = axis(d1);
    p.beginPath();
    p.moveTo(a0.x, a0.y + thickness * hug);
    p.quadraticCurveTo((a0.x + a1.x) / 2, (a0.y + a1.y) / 2 + thickness * (hug + 0.04), a1.x, a1.y + thickness * (hug - 0.02));
    p.stroke();
  }
  p.strokeStyle = "rgba(150,190,255,0.35)";
  p.lineWidth = 1.4;
  const c0 = axis(-0.26);
  const c1 = axis(-0.06);
  p.beginPath();
  p.moveTo(c0.x, c0.y - thickness * 0.46);
  p.quadraticCurveTo((c0.x + c1.x) / 2, (c0.y + c1.y) / 2 - thickness * 0.5, c1.x, c1.y - thickness * 0.44);
  p.stroke();
  }
  severedLimbCache.set(key, c);
  return c;
}

function drawSeveredLimb(effect, alpha) {
  const leg = effect.limb.endsWith("leg");
  const length = leg ? 92 : 72;
  const thickness = leg ? 30 : 23;
  {
    // 2.8 critic round (M4): the atlas-composited limb (with its arterial
    // ribbon, motion smear and shed droplets in flight) is the DEFAULT
    // renderer's prop now — the flat teal/pink capsule primitives are gone.
    // The arm samples the victim's own atlas, its warm/cool rims and
    // drips pick the sprite edge that currently faces the wheel/floor, and in
    // flight it drags a motion smear + an arterial ribbon off the stump.
    const victimId = state.finisher
      ? state.fighters[1 - state.finisher.winner]?.def.id || null : null;
    const rotation = effect.rotation || 0;
    const warmSide = Math.cos(rotation) >= 0 ? 1 : -1;
    const painted = severedLimbPaintedCanvas(effect, victimId, warmSide);
    const baseAlpha = Math.min(1, alpha * 4);
    const speed = Math.hypot(effect.vx || 0, effect.vy || 0);
    ctx.save();
    if (!effect.resting && speed > 60) {
      const nx = (effect.vx || 0) / speed;
      const ny = (effect.vy || 0) / speed;
      // arterial ribbon whipping off the stump, bending under gravity
      const ca = Math.cos(rotation);
      const sa = Math.sin(rotation);
      const stumpX = -length * 0.42 * ca;
      const stumpY = -length * 0.42 * sa;
      const trail = Math.min(66, speed * 0.11);
      const endX = stumpX - nx * trail;
      const endY = stumpY - ny * trail + trail * 0.35;
      const ribbonGrad = ctx.createLinearGradient(stumpX, stumpY, endX, endY);
      ribbonGrad.addColorStop(0, "rgba(178,8,22,0.9)");
      ribbonGrad.addColorStop(1, "rgba(80,2,12,0)");
      ctx.strokeStyle = ribbonGrad;
      ctx.lineCap = "round";
      ctx.globalAlpha = baseAlpha * 0.85;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(stumpX, stumpY);
      ctx.quadraticCurveTo(stumpX - nx * trail * 0.55, stumpY - ny * trail * 0.55 + 6, endX, endY);
      ctx.stroke();
      ctx.lineWidth = 2;
      ctx.strokeStyle = "rgba(235,52,44,0.55)";
      ctx.stroke();
      // shed droplets riding the ribbon, heads leading back along it
      const shedDir = Math.atan2(endY - stumpY, endX - stumpX);
      for (const [at, size] of [[0.4, 6.4], [0.72, 4.6], [1.02, 3.2]]) {
        ctx.save();
        ctx.translate(stumpX + (endX - stumpX) * at, stumpY + (endY - stumpY) * at + 1.5);
        ctx.rotate(shedDir);
        ctx.globalAlpha = baseAlpha * (0.85 - at * 0.35);
        ctx.drawImage(fatalityDropletCanvas(), -size, -size, size * 2, size * 2);
        ctx.restore();
      }
      // motion smear on the trailing edge: two rotation-lagged ghosts that
      // hug the limb (a detached copy reads as a second object)
      for (let ghost = 2; ghost >= 1; ghost -= 1) {
        ctx.save();
        ctx.translate(-nx * ghost * 5.5, -ny * ghost * 5.5);
        ctx.rotate(rotation - (effect.spin || 0) * 0.03 * ghost);
        ctx.globalAlpha = baseAlpha * (ghost === 1 ? 0.13 : 0.07);
        ctx.drawImage(painted, -length * 0.75, -thickness * 1.6, painted.width / 2, painted.height / 2);
        ctx.restore();
      }
    }
    ctx.rotate(rotation);
    ctx.globalAlpha = baseAlpha;
    ctx.shadowColor = "rgba(20,0,4,.72)";
    ctx.shadowBlur = 8;
    ctx.drawImage(painted, -length * 0.75, -thickness * 1.6, painted.width / 2, painted.height / 2);
    ctx.restore();
  }
}

function drawFatalityProjectile(effect, alpha) {
  const reveal = clamp((1 - alpha) * 12, 0, 1);
  // 2.8 critic round (M3): once the killing blow lands (gore on), the sigil
  // treatment dies with the collapse — no halo ring, no glow, no floating
  // label. The murder weapon simply rests in the scene at prop scale so the
  // systole window over the body is READABLE.
  const killResting = Boolean(state.finisher?.fatalityTriggered) && state.graphicFatalities;
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = Math.min(1, alpha * 3) * reveal;
  ctx.shadowColor = effect.color;
  // 3D mode: halve the halo glow — the painted wheel carries its own values,
  // and the old glow + bloom washed the face to a soft gold disc.
  const dressedHalo = cinema3dDressingActive();
  if (!killResting) {
    ctx.shadowBlur = (effect.landed ? 22 : 12) * (dressedHalo ? 0.5 : 1);
    ctx.strokeStyle = effect.color;
    ctx.lineWidth = (effect.landed ? 6 : 3) * (dressedHalo ? 0.6 : 1);
    ctx.beginPath();
    ctx.arc(0, 0, Math.max(effect.width, effect.height) * (.58 + (1 - alpha) * .08), 0, Math.PI * 2);
    ctx.stroke();
  } else {
    ctx.shadowBlur = 0;
    ctx.globalAlpha *= 0.92;
  }
  ctx.save();
  ctx.scale(effect.phase === "kill" ? 1.24 : 1.12, effect.phase === "kill" ? 1.24 : 1.12);
  drawThrowable(effect, state.simulationTick * 1000 / SIMULATION_HZ, alpha);
  ctx.restore();
  // The floating world-space focus label collides with the fatality banner
  // (and with the money shot itself) — dropped for every renderer once the
  // fatality is triggered.
  if (!(killResting || (cinema3dDressingActive() && state.finisher?.fatalityTriggered))) {
    ctx.globalAlpha = Math.min(1, alpha * 4);
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "1000 13px Arial Narrow, Arial, sans-serif";
    ctx.lineWidth = 5;
    ctx.strokeStyle = "rgba(0,0,0,.92)";
    ctx.fillStyle = "#fff0df";
    const focusLabel = `${effect.name} · ${effect.phase.toUpperCase()}`;
    ctx.strokeText(focusLabel, 0, -Math.max(38, effect.height * .72));
    ctx.fillText(focusLabel, 0, -Math.max(38, effect.height * .72));
  }
  ctx.restore();
}

function drawProjectileFocusBurst(effect, alpha) {
  const growth = 1 - alpha;
  const radius = (effect.phase === "kill" ? 86 : 52) + growth * (effect.phase === "kill" ? 240 : 145);
  // 3D mode + pizza/vinyl: the burst's energy stays OUTSIDE the painted
  // wheel — centre-rooted rings/spokes were dissolving the face into a red
  // starburst. Rings collapse to the outermost, spokes root past the rim.
  const dressedBurst = cinema3dDressingActive() && ["pizza", "vinyl"].includes(effect.style);
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.shadowBlur = 18;
  ctx.shadowColor = effect.color;
  ctx.strokeStyle = effect.color;
  ctx.fillStyle = effect.color;
  ctx.lineCap = "round";
  ctx.globalAlpha = alpha * .9;
  for (let ring = dressedBurst ? 2 : 0; ring < 3; ring += 1) {
    ctx.lineWidth = Math.max(2, 8 - ring * 2);
    ctx.beginPath();
    ctx.arc(0, 0, radius * (.52 + ring * .22), 0, Math.PI * 2);
    ctx.stroke();
  }
  if (["pizza", "vinyl"].includes(effect.style)) {
    // 3D mode, landed kill wheel: NO spokes at all — at that scale every
    // centre-rooted line lands across the painted face. The outer ring +
    // rim ghosts + spatter carry the energy read.
    if (!(dressedBurst && effect.phase === "kill")) {
      ctx.rotate(state.simulationTick * .16 * effect.direction);
      const spokeRoot = dressedBurst ? 1.02 : 0.18;
      const spokeTip = dressedBurst ? 1.32 : 1;
      for (let spoke = 0; spoke < 12; spoke += 1) {
        const angle = spoke * Math.PI / 6;
        ctx.lineWidth = spoke % 3 === 0 ? 8 : 3;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle) * radius * spokeRoot, Math.sin(angle) * radius * spokeRoot);
        ctx.lineTo(Math.cos(angle) * radius * spokeTip, Math.sin(angle) * radius * spokeTip);
        ctx.stroke();
      }
    }
  } else if (["mouse", "wires"].includes(effect.style)) {
    for (let cable = 0; cable < 7; cable += 1) {
      const offset = (cable - 3) * 13;
      ctx.lineWidth = 3 + cable % 3;
      ctx.beginPath();
      ctx.moveTo(-radius, offset);
      ctx.bezierCurveTo(-radius * .35, offset - 42, radius * .35, offset + 42, radius, offset);
      ctx.stroke();
    }
  } else if (effect.style === "loogie") {
    for (let drop = 0; drop < 16; drop += 1) {
      const angle = drop * 2.399;
      const reach = radius * (.28 + drop % 5 * .14);
      ctx.beginPath();
      ctx.ellipse(Math.cos(angle) * reach, Math.sin(angle) * reach, 8 + drop % 4 * 4, 5 + drop % 3 * 3, angle, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (effect.style === "xacto") {
    for (let cut = -2; cut <= 2; cut += 1) {
      ctx.lineWidth = 4 + (2 - Math.abs(cut)) * 2;
      ctx.beginPath();
      ctx.moveTo(-radius, cut * 18 + radius * .42);
      ctx.lineTo(radius, cut * 18 - radius * .42);
      ctx.stroke();
    }
  } else if (effect.style === "golfball") {
    for (let ball = 0; ball < 8; ball += 1) {
      const x = -radius + ball * radius * .28;
      const y = Math.sin(ball * 1.5) * radius * .35;
      ctx.beginPath();
      ctx.arc(x, y, 5 + ball, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (effect.style === "bedbugs") {
    for (let bug = 0; bug < 24; bug += 1) {
      const angle = bug * 2.399 + state.simulationTick * .03;
      const reach = radius * (.18 + bug % 7 * .11);
      ctx.beginPath();
      ctx.ellipse(Math.cos(angle) * reach, Math.sin(angle) * reach, 7, 4.5, angle, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawCinematicGoreOverlay() {
  if (!state.graphicFatalities || !state.finisher) return;
  const overlays = state.effects.filter((effect) => effect.kind === "lensBlood");
  for (const effect of overlays) {
    const lifeAlpha = clamp(effect.life / effect.max, 0, 1);
    const reveal = clamp((1 - lifeAlpha) * 8, 0, 1);
    const alpha = reveal * Math.min(1, lifeAlpha * 2.2);
    if (alpha <= 0) continue;
    const familySeed = [...effect.family].reduce((total, character) => total + character.charCodeAt(0), 0)
      + effect.variant * 97;
    ctx.save();
    ctx.globalCompositeOperation = "source-over";

    const vignette = ctx.createRadialGradient(W * .5, H * .46, W * .18, W * .5, H * .46, W * .68);
    vignette.addColorStop(0, "rgba(60,0,7,0)");
    vignette.addColorStop(.72, `rgba(96,0,12,${alpha * .12})`);
    vignette.addColorStop(1, `rgba(20,0,4,${alpha * .42})`);
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, W, H);

    // 2.8 critic round (M5): lens blood behaves like LIQUID on the glass.
    // Every droplet is born on a stagger, slides slowly DOWN under gravity
    // while elongating into a run, and dries/fades individually over 2-4s —
    // no pixel-frozen confetti. Deterministic per (drop, familySeed) hash;
    // count and size are cut so the layer accents instead of dominating.
    // Canvas pass, so the DOM HUD always sits above it.
    const age = (effect.max || 1) - effect.life;
    const droplet = fatalityDropletCanvas();
    ctx.shadowColor = "rgba(35,0,4,.8)";
    ctx.shadowBlur = 4;
    for (let drop = 0; drop < 16; drop += 1) {
      const h1 = ((drop * 173 + familySeed * 29) % 1180) / 1180;
      const h2 = ((drop * 97 + familySeed * 43) % 640) / 640;
      const h3 = ((drop * 199 + familySeed * 17) % 97) / 97;
      const h4 = ((drop * 131 + familySeed * 7) % 89) / 89;
      const x = h1 * W;
      const y0 = (0.06 + h2 * 0.74) * H;
      const born = h3 * 0.5;
      const span = 2 + h4 * 2; // each droplet dries on its own 2-4s clock
      const dropAge = age - born;
      if (dropAge <= 0) continue;
      const dry = Math.min(1, dropAge / span);
      const dropAlpha = alpha * Math.min(1, dropAge / 0.12) * (1 - dry)
        * (0.34 + (drop % 4) * 0.11);
      if (dropAlpha <= 0.015) continue;
      const radius = (2.6 + (drop % 5) * 1.5) * (effect.scale || 1);
      // gravity run: the bead crawls down the glass, decelerating as it
      // sheds volume and dries in place
      const run = (26 + h3 * 52) * (1 - Math.exp(-dropAge / 1.15)) * (0.7 + h4 * 0.6);
      const headY = y0 + run;
      // the run it leaves behind: a thinning tinted streak drying above it
      if (run > radius * 0.8) {
        const trail = ctx.createLinearGradient(x, y0, x, headY);
        trail.addColorStop(0, "rgba(74,3,10,0)");
        trail.addColorStop(0.45, "rgba(96,4,13,0.55)");
        trail.addColorStop(1, "rgba(150,7,20,0.85)");
        ctx.strokeStyle = trail;
        ctx.lineCap = "round";
        ctx.globalAlpha = dropAlpha * 0.8;
        ctx.lineWidth = Math.max(1.1, radius * 0.44);
        ctx.beginPath();
        ctx.moveTo(x, y0);
        ctx.lineTo(x, headY);
        ctx.stroke();
      }
      // the bead itself: a teardrop head elongated by its slide, darker as
      // it dries
      ctx.save();
      ctx.translate(x, headY);
      ctx.rotate(Math.PI * 0.5);
      ctx.scale(1 + Math.min(1.1, run / (radius * 7)), 1 - dry * 0.25);
      ctx.globalAlpha = dropAlpha;
      ctx.drawImage(droplet, -radius * 1.35, -radius * 1.35, radius * 2.7, radius * 2.7);
      ctx.restore();
      // wet glint on the fresh bead only
      if (dry < 0.4) {
        ctx.globalAlpha = dropAlpha * (0.4 - dry) * 1.6;
        ctx.fillStyle = "#ffd9de";
        ctx.beginPath();
        ctx.ellipse(x - radius * 0.3, headY - radius * 0.4, radius * 0.32, radius * 0.2, -0.5, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Family accent marks dry off within ~1.5s of the kill instead of
    // sitting printed on the glass for the whole hold (M5).
    const accentFade = clamp(1 - (age - 0.9) / 0.6, 0, 1);
    if (accentFade > 0.02) {
    ctx.fillStyle = effect.color;
    ctx.strokeStyle = effect.secondary;
    ctx.globalAlpha = alpha * .56 * accentFade;
    ctx.lineCap = "round";
    if (["slice", "rupture", "launch"].includes(effect.family)) {
      ctx.lineWidth = effect.family === "slice" ? 19 : 13;
      ctx.beginPath();
      ctx.moveTo(W * .08, H * (effect.family === "launch" ? .76 : .68));
      ctx.quadraticCurveTo(W * .48, H * .25, W * .94, H * (effect.family === "rupture" ? .18 : .34));
      ctx.stroke();
    } else if (["crush", "implode"].includes(effect.family)) {
      ctx.fillStyle = effect.secondary;
      ctx.beginPath();
      ctx.ellipse(W * .5, H * .93, W * .43, H * .1, 0, 0, Math.PI * 2);
      ctx.fill();
    } else if (effect.family === "electrocute") {
      ctx.globalCompositeOperation = "screen";
      ctx.strokeStyle = "#ff3048";
      ctx.lineWidth = 6;
      for (let bolt = 0; bolt < 6; bolt += 1) {
        ctx.beginPath();
        ctx.moveTo((bolt + 1) * W / 7, 0);
        ctx.lineTo((bolt + .7) * W / 7, H * .2);
        ctx.lineTo((bolt + 1.25) * W / 7, H * .42);
        ctx.stroke();
      }
    } else {
      ctx.fillStyle = effect.color;
      for (let strip = 0; strip < 8; strip += 1) {
        ctx.globalAlpha = alpha * accentFade * (.18 + strip % 3 * .1);
        ctx.fillRect((strip * 191 + familySeed) % W, H * (.12 + strip * .1), W * (.08 + strip % 3 * .04), 5 + strip % 3 * 5);
      }
    }
    }
    ctx.restore();
  }
}

// Unmistakable dizzy feedback: a ring of stars orbiting the head plus a label.
function drawDizzyStars(fighter, time) {
  if (!fighter || fighter.dizzyFrames <= 0) return;
  const centreX = fighter.x;
  // Anchor to the DRAWN sprite height, not the collision box, so the stars orbit
  // above the head rather than across the chest.
  const drawnHeight = fighterRenderSize(fighter.def.id) * 0.956;
  const centreY = fighter.y - drawnHeight - 26;
  const remaining = fighter.dizzyFrames / Math.max(1, fighter.dizzyTotalFrames);
  const stars = 5;
  ctx.save();
  ctx.globalAlpha = 0.55 + 0.45 * Math.abs(Math.sin(time * 6));
  for (let index = 0; index < stars; index += 1) {
    const angle = time * 4.4 + (index / stars) * Math.PI * 2;
    const x = centreX + Math.cos(angle) * 52;
    const y = centreY + Math.sin(angle) * 15;
    const size = 7 + Math.sin(angle * 2) * 2.4;
    ctx.fillStyle = index % 2 ? assistColor("dizzy", "#ffd54a") : assistColor("dizzyAlt", "#fff2b8");
    ctx.beginPath();
    for (let point = 0; point < 10; point += 1) {
      const radius = point % 2 ? size * 0.44 : size;
      const pointAngle = (point / 10) * Math.PI * 2 - Math.PI / 2;
      const px = x + Math.cos(pointAngle) * radius;
      const py = y + Math.sin(pointAngle) * radius;
      if (point === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.font = "900 20px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillStyle = assistColor("dizzy", "#ffd54a");
  ctx.strokeStyle = "rgba(0,0,0,.72)";
  ctx.lineWidth = 4;
  ctx.strokeText("DIZZY", centreX, centreY - 30);
  ctx.fillText("DIZZY", centreX, centreY - 30);
  // A thin drain bar shows the dizzy running out, so the punish window is legible.
  ctx.fillStyle = "rgba(0,0,0,.55)";
  ctx.fillRect(centreX - 34, centreY - 22, 68, 5);
  ctx.fillStyle = assistColor("dizzy", "#ffd54a");
  ctx.fillRect(centreX - 34, centreY - 22, 68 * remaining, 5);
  ctx.restore();
}

// Release 1.7: GUARD CRUSH marker — the dizzy-stars pattern with shard motes
// instead of stars, a CRUSHED label and the same legible drain bar. Pure
// render-side reads of snapshotted fields.
function drawGuardCrushMarker(fighter, time) {
  if (!fighter || fighter.guardCrushFrames <= 0 || fighter.dizzyFrames > 0) return;
  const centreX = fighter.x;
  const drawnHeight = fighterRenderSize(fighter.def.id) * 0.956;
  const centreY = fighter.y - drawnHeight - 26;
  const remaining = fighter.guardCrushFrames / Math.max(1, fighter.guardCrushTotalFrames);
  ctx.save();
  ctx.globalAlpha = 0.55 + 0.45 * Math.abs(Math.sin(time * 7));
  // Broken-guard shards tumbling around the head.
  for (let index = 0; index < 6; index += 1) {
    const angle = time * 3.6 + (index / 6) * Math.PI * 2;
    const x = centreX + Math.cos(angle) * 50;
    const y = centreY + Math.sin(angle) * 14;
    const size = 6 + Math.sin(angle * 2) * 2;
    ctx.fillStyle = index % 2 ? assistColor("crush", "#7de8ff") : "#d8f9ff";
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle * 1.7);
    ctx.beginPath();
    ctx.moveTo(0, -size);
    ctx.lineTo(size * 0.8, size * 0.6);
    ctx.lineTo(-size * 0.7, size * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.font = "900 20px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillStyle = assistColor("crush", "#7de8ff");
  ctx.strokeStyle = "rgba(0,0,0,.72)";
  ctx.lineWidth = 4;
  ctx.strokeText("CRUSHED", centreX, centreY - 30);
  ctx.fillText("CRUSHED", centreX, centreY - 30);
  ctx.fillStyle = "rgba(0,0,0,.55)";
  ctx.fillRect(centreX - 34, centreY - 22, 68, 5);
  ctx.fillStyle = assistColor("crush", "#7de8ff");
  ctx.fillRect(centreX - 34, centreY - 22, 68 * remaining, 5);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Scene dressing: reflections, spotlight, afterimages and colour grade.
// All of it is presentation-only — driven by visualRandom or the tick, gated by
// the performance profile, and invisible to rollback checksums.
// ---------------------------------------------------------------------------

// How mirror-like each stage floor is. Wet asphalt and polished tile reflect
// hard; the Vet's dry lot barely does.
const STAGE_REFLECTIONS = Object.freeze({
  somerset: 0.30, vet: 0.15, wildwood: 0.22, buffet: 0.34, cruise: 0.26,
});
const REFLECTION_DEPTH = 128;

function drawFighterReflections(time) {
  if (!state.performance.shadows) return;
  const strength = STAGE_REFLECTIONS[state.stage] ?? 0.18;
  if (strength <= 0) return;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, FLOOR + 1, W, REFLECTION_DEPTH);
  ctx.clip();
  // Mirror the fighters through the floor line. drawFighter may override the
  // filter briefly during hit flashes; the tail fade below keeps that subtle.
  ctx.translate(0, FLOOR * 2 + 8);
  ctx.scale(1, -1);
  reflectionPassActive = true;
  for (const fighter of state.fighters) {
    // BODY-FIRST (spec 8): the mirror LETS GO with height — an airborne
    // fighter's mirrored sprite slid down the band and left orphan
    // leg-fragments (a juggled victim's sprawl cell read as detached shoe
    // chunks under the floor). Same air fade the CINEMA 3D mirror and the
    // cast shadows already use, so the two ground cues finally agree.
    const jump = Math.max(0, FLOOR - fighter.y);
    const airFade = clamp(1 - jump / 170, 0, 1);
    if (airFade <= 0.03) continue;
    ctx.filter = `opacity(${Math.round(strength * airFade * 100)}%)`;
    drawFighter(fighter, time);
  }
  reflectionPassActive = false;
  ctx.filter = "none";
  ctx.restore();
  // Sink the reflection into the floor so it reads as sheen, not a twin.
  const fade = ctx.createLinearGradient(0, FLOOR, 0, FLOOR + REFLECTION_DEPTH);
  fade.addColorStop(0, "rgba(7,10,15,0.05)");
  fade.addColorStop(1, "rgba(7,10,15,0.62)");
  ctx.save();
  ctx.fillStyle = fade;
  ctx.fillRect(0, FLOOR + 1, W, REFLECTION_DEPTH);
  ctx.restore();
}

// Key-light cast shadows: each fighter throws a long, soft, sheared black
// silhouette across the floor away from the stage's key light — the exact
// sibling of drawFighterReflections (same clipped floor band, one sprite draw
// per fighter) but squashed, skewed and black instead of mirrored and tinted.
// Direction and rake come from STAGE_RIM_LIGHTS, so the rim highlight and the
// cast shadow always agree about where the light hangs. Airborne fighters
// slide the whole shadow down-light and fade it, visibly detaching it from
// the feet; while the super spotlight is up the shadows deepen and lengthen
// with superDimLevel. Static transform of snapshotted state — reducedMotion
// safe — and the battery profile (shadows off) skips the pass entirely.
function drawFighterCastShadows() {
  if (!state.performance.shadows) return;
  const rim = STAGE_RIM_LIGHTS[state.stage] || STAGE_RIM_LIGHTS.somerset;
  const away = -rim.direction; // shadows fall away from the key light
  const deepen = clamp(superDimLevel, 0, 1);
  const stretch = (rim.castStretch ?? 0.45) * (1 + deepen * 0.45);
  const shear = away * (rim.castShear ?? 0.55) * (1 + deepen * 0.3);
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, FLOOR + 1, W, REFLECTION_DEPTH);
  ctx.clip();
  for (const fighter of state.fighters) {
    const pose = fighterAnimationPose(fighter);
    const atlas = pose.bank === "specials"
      ? fighterMoveAtlases[fighter.def.id] || fighterAtlases[fighter.def.id]
      : pose.bank === SPECIALS_LEGACY_BANK
        ? fighterMoveLegacyAtlases[fighter.def.id] || fighterAtlases[fighter.def.id]
        : pose.bank === "motion"
        ? fighterMotionAtlases[fighter.def.id] || fighterAtlases[fighter.def.id]
        : fighterAtlases[fighter.def.id];
    if (!atlas?.complete || !atlas.naturalWidth) continue;
    const renderSize = fighterRenderSize(fighter.def.id) * bankSheetAdjust(fighter.def.id, pose.bank);
    const jump = Math.max(0, FLOOR - fighter.y);
    const airFade = clamp(1 - jump / 520, 0.25, 1);
    ctx.save();
    // Feet anchor; height above the floor slides the contact point down-light.
    ctx.translate(fighter.x + away * jump * 0.5, FLOOR + 2 + jump * 0.1);
    ctx.transform(1, 0, shear, 1, 0, 0); // rake the far end down-light
    // Same authored-facing correction the body draw applies, so the cast
    // shadow of a mixed-orientation sheet cannot point opposite its fighter.
    ctx.scale(fighter.facing * atlasFrameFacing(fighter.def.id, pose.bank, pose.frame), -stretch);  // flip into the floor, squashed long
    ctx.globalAlpha = (0.3 + deepen * 0.22) * airFade;
    drawSilhouetteFrame(atlas, pose.frame, renderSize, "#04060a");
    ctx.restore();
    presentationDebug.castShadows += 1;
  }
  ctx.restore();
}

// Classic super presentation: the street goes dark, the fighters stay lit.
function drawSpotlightPool(dim, targets, darkness = 0.58) {
  if (dim <= 0.02) return;
  ctx.fillStyle = `rgba(3,5,16,${(darkness * dim).toFixed(3)})`;
  ctx.fillRect(-120, -120, W + 240, H + 240);
  for (const fighter of targets) {
    const radius = fighterRenderSize(fighter.def.id) * 0.62;
    const glow = ctx.createRadialGradient(
      fighter.x, fighter.y - radius * 0.55, radius * 0.12,
      fighter.x, fighter.y - radius * 0.55, radius,
    );
    glow.addColorStop(0, `rgba(255,244,214,${(0.15 * dim).toFixed(3)})`);
    glow.addColorStop(1, "rgba(255,244,214,0)");
    ctx.fillStyle = glow;
    ctx.fillRect(fighter.x - radius, fighter.y - radius * 1.65, radius * 2, radius * 2.1);
  }
}

function drawSuperSpotlight() {
  drawSpotlightPool(superDimLevel, state.fighters);
}

// Wave 6 win-pose curtain call: the stage dims like the super spotlight while
// only the round winner keeps the warm pool. Static light on the documented
// spotlight pattern, so it stays on under reduced motion; a live finisher
// cinematic owns the frame instead (roundOverDimLevel also stays down then).
function drawWinPoseSpotlight() {
  if (roundOverDimLevel <= 0.02 || state.finisher || state.fighters.length !== 2) return;
  const [first, second] = state.fighters;
  drawSpotlightPool(roundOverDimLevel, [first.health >= second.health ? first : second], 0.44);
}

// 2.8: kill spotlight — while a graphic fatality is triggered the stage dims
// hard and both participants keep their pools (the victim carries the beat,
// the attacker never reads as a frozen cut-out in the dark). Same reuse of
// the iter-13 spotlight machinery as the super/win-pose passes.
function drawFatalitySpotlight() {
  if (fatalitySpotLevel <= 0.02 || !state.finisher || state.fighters.length !== 2) return;
  const victim = state.fighters[1 - state.finisher.winner];
  const attacker = state.fighters[state.finisher.winner];
  // 2.8 critic round (S2): lifted grade floor — 0.5 darkness crushed bright
  // stages (buffet/cruise) to near-black, making dark-red gore, ash and
  // ripple reads illegible. The spotlight still isolates the kill.
  drawSpotlightPool(fatalitySpotLevel, [victim, attacker], 0.34);
}

// Super focus lines (wave 4): while the spotlight dim is up, sparse comic-style
// speed lines converge from past the frame edges onto the super's attacker.
// Pure render pass driven by superDimLevel and snapshotted fighter state; the
// side latch is module-level render-only state on the superDimLevel pattern so
// the lines hold their target while the dim decays after the super ends.
let superFocusSide = 0;

function drawSuperFocusLines(time) {
  if (superDimLevel <= 0.5 || state.accessibility.highContrast) return;
  const attacker = state.fighters.find((fighter) => fighter.attacking?.superMove);
  if (attacker) superFocusSide = attacker.side;
  const target = state.fighters[superFocusSide];
  if (!target) return;
  const reducedMotion = state.accessibility.reducedMotion;
  const count = Math.max(8, Math.round(26 * state.performance.particleScale));
  const cx = target.x;
  const cy = target.y - target.height * 0.62;
  const strength = clamp((superDimLevel - 0.5) / 0.5, 0, 1);
  const spin = reducedMotion ? 0 : time * 0.00022;
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.strokeStyle = target.def.accent;
  ctx.lineCap = "round";
  for (let line = 0; line < count; line += 1) {
    const jitterA = presentationHash01(line, 17);
    const jitterB = presentationHash01(line, 91);
    const angle = (line / count) * Math.PI * 2 + jitterA * 0.5 + spin;
    const outer = 860 + jitterB * 260;
    // Animated lines rush inward on a staggered cycle; reduced motion holds
    // them static at low alpha instead.
    const rush = reducedMotion ? 0.55 : 0.35 + 0.4 * ((time * 0.0011 + jitterA) % 1);
    const inner = outer * (0.4 + rush * 0.3);
    ctx.globalAlpha = (reducedMotion ? 0.05 : 0.05 + jitterB * 0.07) * strength;
    ctx.lineWidth = 1.5 + jitterA * 2.5;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(angle) * outer, cy + Math.sin(angle) * outer);
    ctx.lineTo(cx + Math.cos(angle) * inner, cy + Math.sin(angle) * inner);
    ctx.stroke();
    presentationDebug.focusLines += 1;
  }
  ctx.restore();
}

function drawAfterimages() {
  for (const effect of state.effects) {
    if (effect.kind !== "afterimage") continue;
    const atlas = fighterAtlases[effect.fighterId];
    if (!atlas) continue;
    // MOTION FIX 2: current-pose-only echoes — every frame the ghost lives it
    // re-reads the owner's LIVE atlas cell, so an echo can never show a pose
    // the fighter has already left (the idle-pose body double is dead).
    let frame = effect.frame;
    const owner = Number.isInteger(effect.side) ? state.fighters[effect.side] : null;
    // 2.7 critic round: dash echoes END WITH THE DASH — a ghost whose owner
    // is no longer dashing stops drawing (donald's trail was outliving
    // dashFrames by ~6 ticks, and leftovers re-read the live pose into a
    // body double on the following flip's descent).
    if (owner && owner.def.id === effect.fighterId) {
      if (owner.dashFrames <= 0) continue;
      const livePose = fighterAnimationPose(owner);
      if (livePose.bank === "base") frame = livePose.frame;
      // v2.7 FRAMES: a live motion pose echoes its base fallback cell.
      else if (livePose.bank === "motion" && livePose.fallback?.bank === "base") {
        frame = livePose.fallback.frame;
      }
    }
    ctx.save();
    ctx.translate(effect.x, effect.y);
    ctx.scale(effect.facing * atlasFrameFacing(effect.fighterId, "base", frame), 1);
    // BODY-FIRST (spec 6): the freshest ghost is a horizontal STRETCH-SMEAR
    // of the current cell — a smear of the torso in motion, not a second
    // body; every older ghost sits lower with its head band clipped.
    // 2.7 critic round: alpha CRUSHED below face-readability (25%/22% read
    // as a legible duplicate figure at speed — echoes are a wash, not a
    // second fighter).
    // 5.3 SPECTACLE (#47): the ghost's opacity ladder is engine/vfx-bridge.mjs
    // (afterimageGhost) — the 3D dash trail wears the same wash.
    const ghostAge = 1 - clamp(effect.life / effect.max, 0, 1);
    const ghost = afterimageGhost(ghostAge);
    ctx.globalAlpha = ghost.opacity;
    if (ghost.clipTop > 0) {
      ctx.beginPath();
      ctx.rect(-effect.size * 0.5, -effect.size * (1 - ghost.clipTop), effect.size, effect.size * (1 - ghost.clipTop));
      ctx.clip();
    } else {
      ctx.scale(ghost.scaleX, ghost.scaleY);
    }
    drawAtlasFrame(atlas, frame, effect.size);
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  // MOTION FIX 7: faint arc ribbon under a directional flip — the body
  // centre's ballistic path integrated backward (exact, stateless), stroked
  // as a fading tapered curve through the mid-frames of the arc, so the flip
  // reads as travel along a path rather than a rotating cutout.
  if (state.screen === "fight" && !state.accessibility.reducedMotion
    && state.performance.trailScale > 0) {
    for (let side = 0; side < 2; side += 1) {
      const obs = motionObs[side];
      const fighter = state.fighters[side];
      if (!obs?.flipEligible || obs.flipKind === "neutral" || !fighter || fighter.grounded) continue;
      // 2.7 critic round: the takeoff ribbon is a LAUNCH accent, not a
      // full-arc contrail — it lives ~8 ticks off the ground (fading over
      // the last few) instead of tracing the whole ballistic path.
      if (obs.launchAge < 0 || obs.launchAge > 8) continue;
      const ribbonFade = clamp(1 - (obs.launchAge - 4) / 5, 0.2, 1);
      const launch = Math.abs(fighter.movement.jumpVelocityY || -720);
      const height = Math.max(0, FLOOR - fighter.y);
      // Mid-frames only: skip the very first ticks off the ground.
      if (height < 40 && fighter.vy < -launch * 0.82) continue;
      const centreY = fighter.y - fighterRenderSize(fighter.def.id) * 0.52;
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.lineCap = "round";
      let prevX = fighter.x;
      let prevY = centreY;
      for (let step = 1; step <= 8; step += 1) {
        // Long enough to clear the sprite footprint and read as a path —
        // ~0.56s of flight integrated backward, clipped at the street.
        const dtBack = step * 0.07;
        const tailX = fighter.x - fighter.vx * dtBack;
        const tailY = centreY - fighter.vy * dtBack + 0.5 * GRAVITY * dtBack * dtBack;
        if (tailY > FLOOR - 8) break;
        ctx.globalAlpha = 0.44 * (1 - step / 9) * ribbonFade;
        ctx.strokeStyle = fighter.def.accent;
        ctx.lineWidth = Math.max(2, 12 - step * 1.2);
        ctx.beginPath();
        ctx.moveTo(prevX, prevY);
        ctx.lineTo(tailX, tailY);
        ctx.stroke();
        // Warm core on the freshest stretch of path so the arc reads at a
        // glance while the tail stays a faint wash.
        if (step <= 2) {
          ctx.globalAlpha = 0.3 * ribbonFade;
          ctx.strokeStyle = "#fff2d8";
          ctx.lineWidth = Math.max(1.5, (12 - step * 1.2) * 0.35);
          ctx.stroke();
        }
        prevX = tailX;
        prevY = tailY;
      }
      ctx.restore();
      presentationDebug.arcRibbons += 1;
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
  }
}

// Stage key lights for the fighter rim pass: the colour of each arena's
// dominant practical light and which world-space side it comes from. The rim
// blends toward the warm spotlight tone while the super dim is up.
// castShear/castStretch drive the floor cast-shadow pass: how hard the same
// key light skews the shadow down-light and how long it throws (low harsh
// practicals like the el-track arcs and boardwalk neon throw long, raked
// shadows; the buffet's overhead lanterns keep them short and steep).
const STAGE_RIM_LIGHTS = Object.freeze({
  somerset: Object.freeze({ color: Object.freeze([126, 178, 255]), direction: -1, castShear: 0.66, castStretch: 0.44 }), // cool blue el-track arcs
  vet: Object.freeze({ color: Object.freeze([255, 178, 84]), direction: 1, castShear: 0.5, castStretch: 0.5 }),            // sodium lot floods
  wildwood: Object.freeze({ color: Object.freeze([255, 104, 214]), direction: 1, castShear: 0.76, castStretch: 0.4 }),     // boardwalk neon pink
  buffet: Object.freeze({ color: Object.freeze([255, 190, 108]), direction: -1, castShear: 0.36, castStretch: 0.48 }),     // lantern amber
  cruise: Object.freeze({ color: Object.freeze([108, 226, 255]), direction: -1, castShear: 0.58, castStretch: 0.42 }),     // pool-deck cyan
});
const SUPER_RIM_WARMTH = Object.freeze([255, 214, 150]);

function stageRimColor() {
  const rim = STAGE_RIM_LIGHTS[state.stage] || STAGE_RIM_LIGHTS.somerset;
  const warmth = clamp(superDimLevel, 0, 1);
  const red = Math.round(lerp(rim.color[0], SUPER_RIM_WARMTH[0], warmth));
  const green = Math.round(lerp(rim.color[1], SUPER_RIM_WARMTH[1], warmth));
  const blue = Math.round(lerp(rim.color[2], SUPER_RIM_WARMTH[2], warmth));
  return `rgb(${red},${green},${blue})`;
}

// Per-stage colour grade plus an edge vignette: one soft-light tint pulls each
// arena toward its own palette without crushing the sprite art. Each entry now
// carries a second "late" tint: round 1 → round 3 the evening visibly gets
// later, lerped purely from state.round so it is exact under rollback and
// replay (the fill count in drawStageGrade never changes). Janney finally gets
// the grade entry it was silently missing.
const STAGE_GRADES = Object.freeze({
  somerset: { tint: [44, 74, 110, 0.30], late: [26, 50, 122, 0.38], vignette: 0.30, lateVignette: 0.36 },
  vet: { tint: [96, 74, 40, 0.24], late: [52, 68, 108, 0.30], vignette: 0.26, lateVignette: 0.32 },           // floodlights take over, cooler cast
  wildwood: { tint: [88, 44, 110, 0.26], late: [62, 24, 126, 0.34], vignette: 0.28, lateVignette: 0.34 },     // sky deepens, neon reads hotter
  buffet: { tint: [112, 78, 40, 0.26], late: [98, 56, 54, 0.32], vignette: 0.22, lateVignette: 0.28 },
  cruise: { tint: [40, 104, 118, 0.20], late: [124, 88, 58, 0.26], vignette: 0.18, lateVignette: 0.24 },      // afternoon slides toward golden hour
  janney: { tint: [122, 84, 52, 0.26], late: [86, 54, 132, 0.34], vignette: 0.24, lateVignette: 0.32 },       // early dusk amber → violet
});

function drawStageGrade() {
  if (state.accessibility.highContrast) return;
  // The killing blow drains the colour out of the scene, so the reds of the
  // pool, spray and vignette are the only saturated thing left on screen.
  const finisher = state.finisher;
  if (state.graphicFatalities && finisher?.fatalityTriggered) {
    const aftermath = Math.max(0, finisher.elapsed - finisher.fatalityAt);
    const drain = Math.min(0.55, aftermath * 1.1);
    if (drain > 0.01) {
      ctx.save();
      ctx.globalCompositeOperation = "saturation";
      ctx.fillStyle = `rgba(128,128,128,${drain.toFixed(3)})`;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }
  }
  const grade = STAGE_GRADES[state.stage];
  if (!grade) return;
  const late = timeOfDayLevel();
  const tint = `rgba(${Math.round(lerp(grade.tint[0], grade.late[0], late))},${Math.round(lerp(grade.tint[1], grade.late[1], late))},${Math.round(lerp(grade.tint[2], grade.late[2], late))},${lerp(grade.tint[3], grade.late[3], late).toFixed(3)})`;
  const vignetteStrength = lerp(grade.vignette, grade.lateVignette, late).toFixed(3);
  ctx.save();
  ctx.globalCompositeOperation = "soft-light";
  ctx.fillStyle = tint;
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = "source-over";
  const vignette = ctx.createRadialGradient(W * 0.5, H * 0.44, H * 0.42, W * 0.5, H * 0.52, W * 0.72);
  vignette.addColorStop(0, "rgba(4,6,12,0)");
  vignette.addColorStop(1, `rgba(4,6,12,${vignetteStrength})`);
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function drawFinisherRealityComposite() {
  const reality = finisherRealityAmount();
  if (reality <= .01) return;
  ctx.save();
  ctx.globalCompositeOperation = "soft-light";
  ctx.globalAlpha = reality;
  const splitLight = ctx.createLinearGradient(0, 0, W, H);
  splitLight.addColorStop(0, "rgba(255,142,66,.32)");
  splitLight.addColorStop(.43, "rgba(62,44,46,.08)");
  splitLight.addColorStop(1, "rgba(72,164,230,.28)");
  ctx.fillStyle = splitLight;
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = "source-over";
  const vignette = ctx.createRadialGradient(W * .5, H * .47, H * .18, W * .5, H * .47, W * .7);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(.72, `rgba(4,4,7,${(reality * .08).toFixed(3)})`);
  vignette.addColorStop(1, `rgba(1,2,4,${(reality * .5).toFixed(3)})`);
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);
  presentationDebug.realisticLighting += 1;

  if (state.performance.shadows && !state.accessibility.highContrast) {
    ctx.globalCompositeOperation = "overlay";
    const grainTick = state.accessibility.reducedMotion ? 0 : state.simulationTick;
    for (let grain = 0; grain < 96; grain += 1) {
      const x = (grain * 197 + grainTick * 17) % W;
      const y = (grain * 109 + grainTick * 11) % H;
      ctx.globalAlpha = reality * (.025 + grain % 4 * .008);
      ctx.fillStyle = grain % 2 ? "#e8dfd2" : "#2a3340";
      ctx.fillRect(x, y, 1 + grain % 3, 1 + (grain + 1) % 2);
    }
    presentationDebug.filmGrainPasses += 1;
  }
  ctx.restore();
}

// One combat-text label ("COUNTER", "WET PAINT!", the weapon cue), origin at
// the effect's own point with the caller's shadow already set. The 2D world
// pass calls it from drawParticles; the CINEMA 3D overlay pass calls it at
// the projected point, so the same label reads in both renderers.
function drawCombatTextBody(effect, alpha) {
  ctx.globalAlpha = Math.min(1, alpha * 1.7);
  ctx.translate(0, -(1 - alpha) * 42);
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "900 24px Arial Narrow, Arial, sans-serif";
  ctx.lineWidth = 7;
  ctx.strokeStyle = "rgba(0,0,0,.88)";
  ctx.strokeText(effect.label, 0, 0);
  ctx.fillStyle = effect.color;
  ctx.fillText(effect.label, 0, 0);
}

function drawParticles() {
  for (const particle of state.particles) {
    const alpha = clamp(particle.life / particle.max, 0, 1);
    ctx.save();
    // 5.3 SPECTACLE (#47): the quiet-kind knock-down lives in
    // engine/vfx-bridge.mjs, so a mote mirrored into the 3D cloud carries
    // exactly the weight the canvas gives it.
    ctx.globalAlpha = particleMote(particle).alpha;
    ctx.fillStyle = particle.color;
    ctx.beginPath();
    if (particle.kind === "sparkLine") {
      ctx.globalCompositeOperation = "lighter";
      ctx.strokeStyle = particle.color;
      ctx.lineWidth = particle.size;
      ctx.lineCap = "round";
      ctx.moveTo(particle.x, particle.y);
      ctx.lineTo(particle.x - (particle.vx || 0) * 0.045, particle.y - (particle.vy || 0) * 0.045);
      ctx.stroke();
      ctx.restore();
      continue;
    }
    if (particle.kind === "debris") {
      // Wall-splat chip (wave 4): a stage-toned slab tumbling under the shared
      // spin/rotation integration the gore fragments already use.
      ctx.translate(particle.x, particle.y);
      ctx.rotate(particle.rotation || 0);
      ctx.fillRect(-particle.size, -particle.size * 0.42, particle.size * 2, particle.size * 0.84);
      ctx.restore();
      continue;
    }
    if (particle.kind === "mist") {
      // 2.8: aerosol blood mist / steam / ash — a soft radial puff that
      // billows out and thins as it rises; colour comes from the spawner.
      const channels = hexToRgbChannels(particle.color || "#6b050c");
      const radius = particle.size * (1 + (1 - alpha) * 1.5);
      const puff = ctx.createRadialGradient(particle.x, particle.y, 1, particle.x, particle.y, radius);
      puff.addColorStop(0, `rgba(${channels},${(alpha * 0.3).toFixed(3)})`);
      puff.addColorStop(0.7, `rgba(${channels},${(alpha * 0.13).toFixed(3)})`);
      puff.addColorStop(1, `rgba(${channels},0)`);
      ctx.fillStyle = puff;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      continue;
    }
    if (particle.kind === "sweat") {
      // Glinting droplet: an additive bead stretched along its velocity with a
      // small white highlight trailing it.
      ctx.globalCompositeOperation = "lighter";
      const angle = Math.atan2(particle.vy || 0, particle.vx || 1);
      ctx.ellipse(particle.x, particle.y, particle.size * 1.4, Math.max(0.8, particle.size * 0.5), angle, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = alpha * 0.8;
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.arc(
        particle.x - Math.cos(angle) * particle.size * 0.6,
        particle.y - Math.sin(angle) * particle.size * 0.6,
        Math.max(0.6, particle.size * 0.3), 0, Math.PI * 2,
      );
      ctx.fill();
      ctx.restore();
      continue;
    }
    if (particle.kind === "blood" || particle.kind === "arterial") {
      // 2.8 critic round (M4): dimensional spatter is the DEFAULT — the
      // gradient droplet sprite stretched along its velocity with a thinning
      // smear tail, instead of a flat solid ellipse.
      const angle = Math.atan2(particle.vy || 0, particle.vx || 1);
      const speed = Math.hypot(particle.vx || 0, particle.vy || 0);
      const stretch = 1.2 + Math.min(1.6, speed * 0.0016);
      ctx.strokeStyle = particle.color;
      ctx.lineCap = "round";
      ctx.lineWidth = Math.max(1, particle.size * 0.5);
      ctx.globalAlpha = alpha * 0.55;
      ctx.beginPath();
      ctx.moveTo(particle.x - (particle.vx || 0) * 0.03, particle.y - (particle.vy || 0) * 0.03);
      ctx.lineTo(particle.x, particle.y);
      ctx.stroke();
      ctx.globalAlpha = alpha;
      ctx.translate(particle.x, particle.y);
      ctx.rotate(angle);
      ctx.scale(stretch, 1);
      const dropSize = particle.size * 2.1;
      ctx.drawImage(fatalityDropletCanvas(), -dropSize, -dropSize, dropSize * 2, dropSize * 2);
      ctx.restore();
      continue;
    } else if (particle.kind === "goreFragment") {
      ctx.translate(particle.x, particle.y);
      ctx.rotate(particle.rotation || 0);
      const spikes = particle.spikes || 6;
      for (let point = 0; point < spikes * 2; point += 1) {
        const angle = point * Math.PI / spikes;
        // 2.8 critic round (M4): per-point jitter breaks the symmetric star
        // into a torn irregular chunk in EVERY renderer (the flat
        // throwing-star read was pure clipart).
        const jag = 0.62 + (Math.abs(Math.sin((point * 37.7 + spikes * 91.3 + particle.size * 13.1))) * 0.55);
        const radius = particle.size * jag;
        if (point === 0) ctx.moveTo(Math.cos(angle) * radius, Math.sin(angle) * radius);
        else ctx.lineTo(Math.cos(angle) * radius, Math.sin(angle) * radius);
      }
      ctx.closePath();
    } else if (particle.kind === "dust") {
      ctx.ellipse(particle.x, particle.y, particle.size * 1.5, particle.size * 0.6, 0, 0, Math.PI * 2);
    } else {
      ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
    }
    ctx.fill();
    if (particle.kind === "goreFragment" && particle.bone) {
      ctx.fillStyle = "#ead7b7";
      ctx.fillRect(-particle.size * .58, -2, particle.size * 1.16, 4);
    }
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  for (const effect of state.effects) {
    const alpha = clamp(effect.life / (effect.max || 0.9), 0, 1);
    ctx.save();
    ctx.translate(effect.x, effect.y);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = effect.color;
    ctx.shadowBlur = 25;
    ctx.shadowColor = effect.color;
    if (effect.kind === "combatText") {
      drawCombatTextBody(effect, alpha);
    } else if (effect.kind === "finisherImpact") {
      drawFinisherImpact(effect, alpha);
    } else if (effect.kind === "fatalityProjectile") {
      drawFatalityProjectile(effect, alpha);
    } else if (effect.kind === "projectileFocusBurst") {
      drawProjectileFocusBurst(effect, alpha);
    } else if (effect.kind === "fatalityPool") {
      drawFatalityPool(effect, alpha);
    } else if (effect.kind === "severedLimb") {
      drawSeveredLimb(effect, alpha);
    } else if (effect.kind === "goreShockwave") {
      const growth = 1 - alpha;
      const reach = (54 + growth * 250) * (effect.scale || 1);
      ctx.shadowBlur = 0;
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = effect.color;
      ctx.fillStyle = effect.secondary;
      ctx.lineCap = "round";
      for (let spray = 0; spray < 17; spray += 1) {
        const angle = -1.42 + spray * .18 + (effect.family === "launch" ? -.18 : 0);
        const length = reach * (.38 + (spray % 6) * .12);
        ctx.globalAlpha = alpha * (.28 + spray % 4 * .14);
        // 2.8 critic round (M4): tapered arterial arcs in EVERY renderer —
        // thick dark root fading down a gravity-bent path to a droplet
        // sprite tip; the straight uniform "red spoke" read is gone.
        const tipX = Math.cos(angle) * length * effect.direction;
        const tipY = Math.sin(angle) * length + length * 0.22; // gravity sag
        const sprayGrad = ctx.createLinearGradient(0, 0, tipX, tipY);
        sprayGrad.addColorStop(0, effect.secondary);
        sprayGrad.addColorStop(0.5, effect.color);
        sprayGrad.addColorStop(1, "rgba(96,4,10,0.25)");
        ctx.strokeStyle = sprayGrad;
        ctx.lineWidth = 4.5 + spray % 5;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(
          Math.cos(angle) * length * .55 * effect.direction,
          Math.sin(angle) * length * .45 - 24,
          tipX, tipY,
        );
        ctx.stroke();
        // thinner core pass rides the same arc: reads as a liquid rope
        ctx.globalAlpha *= 0.7;
        ctx.lineWidth = Math.max(1.4, (4.5 + spray % 5) * 0.4);
        ctx.stroke();
        const tipSize = 5 + spray % 4 * 2.4;
        ctx.save();
        ctx.translate(tipX, tipY);
        // teardrop head leads along the arc's end tangent (gravity-drooped)
        ctx.rotate(angle + 0.3);
        ctx.scale(1.5, 0.85);
        ctx.drawImage(fatalityDropletCanvas(), -tipSize, -tipSize, tipSize * 2, tipSize * 2);
        ctx.restore();
      }
    } else if (effect.kind === "lensBlood") {
      // Screen-space pass in drawCinematicGoreOverlay().
    } else if (effect.kind === "bloodBurst") {
      const scale = effect.tier === "super" ? 1.45 : effect.tier === "light" ? 0.7 : 1;
      ctx.shadowBlur = 0;
      ctx.strokeStyle = effect.color;
      ctx.fillStyle = effect.color;
      ctx.lineCap = "round";
      for (let spray = 0; spray < 7; spray += 1) {
        const spread = (spray - 3) * 0.22;
        const reach = (18 + (1 - alpha) * (58 + spray * 7)) * scale;
        ctx.globalAlpha = alpha * (0.45 + spray % 2 * 0.22);
        ctx.lineWidth = (2.5 + spray % 3) * scale;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(effect.direction * reach * 0.55, spread * reach - 18, effect.direction * reach, spread * reach);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(effect.direction * reach, spread * reach, (2 + spray % 3) * scale, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (effect.kind === "impactFlash") {
      const radius = (effect.tier === "super" ? 64 : effect.tier === "light" ? 26 : 42) * alpha;
      ctx.globalCompositeOperation = "screen";
      if (effect.spill && !state.accessibility.highContrast) {
        // Impact light spill (wave 4): one radial gradient splash of the spark
        // colour across the nearby stage, snapping back with the flash's own
        // life. Radius halves on the battery profile and eases down with the
        // effect budget so the balanced tier stays cheap.
        const reach = (effect.tier === "super" ? 500 : 330)
          * (state.performance.shadows ? 1 : 0.5)
          * (0.6 + 0.4 * Math.min(1, state.performance.effectBudget / 220));
        const channels = hexToRgbChannels(effect.spill);
        const spillAlpha = alpha * (effect.tier === "super" ? 0.38 : 0.24);
        ctx.shadowBlur = 0;
        const spill = ctx.createRadialGradient(0, 0, 12, 0, 0, reach);
        spill.addColorStop(0, `rgba(${channels},${spillAlpha.toFixed(3)})`);
        spill.addColorStop(0.55, `rgba(${channels},${(spillAlpha * 0.4).toFixed(3)})`);
        spill.addColorStop(1, `rgba(${channels},0)`);
        ctx.fillStyle = spill;
        ctx.fillRect(-reach, -reach, reach * 2, reach * 2);
        presentationDebug.lightSpills += 1;
      }
      // MOTION FIX 1: the six static rays are gone (they were half of the
      // frozen "wheel" read). The impactFlash is now a single soft white pop
      // that lives only through the front of the effect — the evolving
      // hitSpark effect owns the shard language.
      if (alpha > 0.45) {
        ctx.shadowBlur = 0;
        const pop = ctx.createRadialGradient(0, 0, 2, 0, 0, radius + 14);
        pop.addColorStop(0, "rgba(255,250,238,0.95)");
        pop.addColorStop(0.55, "rgba(255,244,223,0.42)");
        pop.addColorStop(1, "rgba(255,244,223,0)");
        ctx.globalAlpha = (alpha - 0.45) / 0.55;
        ctx.fillStyle = pop;
        ctx.beginPath();
        ctx.arc(0, 0, radius + 14, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (effect.kind === "hitSpark") {
      // MOTION FIX 1: the evolving hitspark. Beat 1 (first ~35% of life):
      // one clean white flash. Beats 2-3: radiating shards cut from the
      // spark flipbook at the per-hit randomized rotation/count, cells and
      // jitter re-hashed EVERY sim tick (ticks advance through hitstop), so
      // the silhouette never repeats between rendered frames; the whole
      // thing is gone in ~6 ticks.
      const age = 1 - alpha;
      ctx.globalCompositeOperation = "lighter";
      ctx.shadowBlur = 0;
      if (age < 0.28) {
        const flash = 1 - age / 0.28;
        const radius = effect.size * (0.32 + age * 0.9);
        const core = ctx.createRadialGradient(0, 0, 2, 0, 0, radius);
        core.addColorStop(0, "rgba(255,255,252,0.98)");
        core.addColorStop(0.6, "rgba(255,246,224,0.5)");
        core.addColorStop(1, "rgba(255,246,224,0)");
        ctx.globalAlpha = 0.65 + 0.35 * flash;
        ctx.fillStyle = core;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();
      } else {
        const spread = (age - 0.28) / 0.72;
        const meta = elementSheets.manifest?.spark;
        const image = elementSheets.images.get("spark");
        const tickJitter = state.simulationTick * 0.31 + effect.seed;
        ctx.shadowColor = effect.color;
        ctx.shadowBlur = 10;
        for (let shard = 0; shard < effect.shards; shard += 1) {
          const angle = effect.baseRot + shard * (Math.PI * 2 / effect.shards)
            + Math.sin(tickJitter + shard * 2.3) * 0.24;
          const reach = effect.size * (0.3 + spread * 0.85);
          const sx = Math.cos(angle) * reach;
          const sy = Math.sin(angle) * reach * 0.82;
          ctx.globalAlpha = Math.min(1, (0.35 + alpha) * (0.7 + ((shard + effect.seed) % 3) * 0.15));
          if (meta && image?.complete && image.naturalWidth) {
            // Shard cell re-hashed per tick — never the same cell two frames.
            const cell = meta.frames[(effect.seed + shard * 5 + state.simulationTick * 3) % 16];
            if (!cell || !cell.w) continue;
            const size = effect.size * (0.72 - spread * 0.24) * (0.8 + (shard % 3) * 0.18);
            const scale = size / Math.max(cell.w, cell.h);
            ctx.save();
            ctx.translate(sx, sy);
            ctx.rotate(angle + Math.PI * 0.5);
            ctx.drawImage(image, cell.x, cell.y, cell.w, cell.h,
              -(cell.cx - cell.x) * scale, -(cell.cy - cell.y) * scale,
              cell.w * scale, cell.h * scale);
            ctx.restore();
          } else {
            // Procedural fallback: a tapered wedge, still tick-jittered.
            ctx.fillStyle = shard % 3 ? "#fff6db" : effect.color;
            const width = effect.size * 0.09 * (1 - spread * 0.4);
            ctx.save();
            ctx.translate(sx, sy);
            ctx.rotate(angle);
            ctx.beginPath();
            ctx.moveTo(-effect.size * 0.3, 0);
            ctx.lineTo(0, -width);
            ctx.lineTo(effect.size * 0.22, 0);
            ctx.lineTo(0, width);
            ctx.closePath();
            ctx.fill();
            ctx.restore();
          }
        }
        ctx.shadowBlur = 0;
      }
    } else if (effect.kind === "bloodDecal") {
      ctx.shadowBlur = 0;
      // 2.8 critic round (M2): decals evolve on their own AGE clock, which
      // keeps running while the fatality hold freezes their lifetimes.
      const decalAge = effect.age ?? ((effect.max || 1) - effect.life);
      if (effect.wall) {
        // 2.8: wall spatter — a flattened smudge against the arena bound
        // whose drip run lengthens as the stain ages, ending in a bead.
        const run = Math.min(effect.run || 18, 4 + decalAge * 26);
        ctx.globalAlpha = Math.min(0.62, alpha * 0.8);
        ctx.fillStyle = effect.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, Math.max(2.6, effect.width * 0.28), effect.width * 0.5, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = Math.min(0.5, alpha * 0.62);
        ctx.fillRect(-1.4, 0, 2.8, run);
        ctx.beginPath();
        ctx.arc(0, run, 2.1, 0, Math.PI * 2);
        ctx.fill();
      } else if (effect.smear) {
        // 2.8: drag smear — an elongated streak with a feathered tail on the
        // trailing side, left by a body sliding through its own pool. Critic
        // round (S4): raised alpha/height so the streak is locatable.
        ctx.globalAlpha = Math.min(0.85, alpha * 0.95);
        ctx.fillStyle = effect.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, effect.width * 0.62, 6.6, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha *= 0.6;
        ctx.beginPath();
        ctx.ellipse(-(effect.direction || 1) * effect.width * 0.5, 0, effect.width * 0.34, 4, 0, 0, Math.PI * 2);
        ctx.fill();
        // a brighter wet core so the streak reads on dark asphalt too
        ctx.globalAlpha = Math.min(0.6, alpha * 0.7);
        ctx.fillStyle = "#8c0712";
        ctx.beginPath();
        ctx.ellipse((effect.direction || 1) * effect.width * 0.16, 0, effect.width * 0.34, 2.6, 0, 0, Math.PI * 2);
        ctx.fill();
      } else {
        // 2.8: floor stains soak in — older blood darkens toward matte.
        const soak = bloodSoak(decalAge);
        ctx.globalAlpha = Math.min(0.68, alpha * 0.82) * (1 - soak * 0.22);
        ctx.fillStyle = soak > 0.55 ? "#43030a" : effect.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, effect.width * 0.5, Math.max(3, effect.width * 0.1), 0, 0, Math.PI * 2);
        ctx.fill();
        for (let drop = 0; drop < 5; drop += 1) {
          const angle = drop * 2.37;
          ctx.beginPath();
          ctx.arc(Math.cos(angle) * effect.width * 0.55, Math.sin(angle) * effect.width * 0.1, 2 + drop % 3, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    } else if (effect.kind === "floorImpact") {
      ctx.shadowBlur = 0;
      ctx.globalAlpha = alpha * 0.55;
      ctx.strokeStyle = effect.color;
      ctx.lineWidth = 5 * alpha;
      ctx.beginPath();
      ctx.ellipse(0, 0, effect.width * (1 - alpha * 0.25), 12 + (1 - alpha) * 12, 0, Math.PI, Math.PI * 2);
      ctx.stroke();
    } else if (effect.kind === "objectImpact") {
      ctx.shadowBlur = 8;
      ctx.lineWidth = effect.settling ? 2 : 5;
      const radius = (effect.settling ? 18 : 30) + (1 - alpha) * 28;
      for (let slash = 0; slash < 5; slash += 1) {
        const angle = slash * Math.PI * 2 / 5;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle) * radius * 0.35, Math.sin(angle) * radius * 0.35);
        ctx.lineTo(Math.cos(angle) * radius, Math.sin(angle) * radius);
        ctx.stroke();
      }
    } else if (effect.kind === "paintDeploy" || effect.kind === "paintTrapBurst") {
      const burst = effect.kind === "paintTrapBurst";
      const radius = (1 - alpha) * (burst ? 138 : 72) + 12;
      ctx.globalCompositeOperation = "screen";
      for (let drop = 0; drop < (burst ? 18 : 9); drop += 1) {
        const angle = drop * 2.399 + (burst ? 0.35 : 0);
        const reach = radius * (0.35 + (drop % 5) * 0.13);
        ctx.globalAlpha = alpha * (0.5 + (drop % 3) * 0.18);
        ctx.fillStyle = effect.color;
        ctx.beginPath();
        ctx.arc(Math.cos(angle) * reach, Math.sin(angle) * reach * 0.45, 4 + (drop % 4) * 2.5, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (effect.kind === "counterPunch") {
      const radius = (1 - alpha) * 126 + 24;
      ctx.globalCompositeOperation = "screen";
      ctx.lineWidth = 12 * alpha;
      ctx.beginPath();
      ctx.arc(0, 0, radius, -1.25, 1.25);
      ctx.stroke();
      for (let ray = 0; ray < 10; ray += 1) {
        const angle = ray * Math.PI * 2 / 10;
        ctx.lineWidth = ray % 2 ? 4 : 8;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
        ctx.lineTo(Math.cos(angle) * radius * 1.35, Math.sin(angle) * radius * 1.35);
        ctx.stroke();
      }
    } else if (effect.kind === "counterFocus") {
      // Counter-hit focus burst (wave 4): gold anime speed lines rushing in on
      // the impact point. Skipped under reduced motion; the color-preserving
      // brightness pop still marks the counter. Deterministic jitter only.
      if (!state.accessibility.reducedMotion) {
        const rush = 1 - alpha;
        ctx.globalCompositeOperation = "screen";
        ctx.shadowBlur = 0;
        ctx.lineCap = "round";
        for (let line = 0; line < 12; line += 1) {
          const jitter = presentationHash01(line, 29);
          const angle = line * (Math.PI * 2 / 12) + jitter * 0.42;
          const outer = (150 + jitter * 70) * (1 - rush * 0.45);
          const inner = outer * (0.36 + rush * 0.36);
          ctx.globalAlpha = alpha * (0.5 + jitter * 0.4);
          ctx.lineWidth = 1.5 + rush * 2 + jitter * 2;
          ctx.beginPath();
          ctx.moveTo(Math.cos(angle) * outer, Math.sin(angle) * outer);
          ctx.lineTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
          ctx.stroke();
        }
        presentationDebug.counterFlashes += 1;
      }
    } else if (effect.kind === "wallShock") {
      // Corner wall-splat (wave 4): a tall shock ellipse hugging the arena
      // edge plus an offset shimmer ring that reads as compressed air coming
      // off the wall. Static, dimmer variant under reduced motion.
      const reducedMotion = state.accessibility.reducedMotion;
      const growth = reducedMotion ? 0.4 : 1 - alpha;
      const size = effect.size || 84;
      ctx.globalCompositeOperation = "screen";
      ctx.shadowBlur = 0;
      ctx.globalAlpha = alpha * (reducedMotion ? 0.4 : 0.85);
      ctx.lineWidth = 2.5 + alpha * 5.5;
      ctx.beginPath();
      ctx.ellipse(0, 0, size * (0.14 + growth * 0.4), size * (0.55 + growth * 1.05), 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha *= 0.45;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(effect.direction * (6 + growth * 16), 0, size * (0.2 + growth * 0.5), size * (0.62 + growth * 1.2), 0, 0, Math.PI * 2);
      ctx.stroke();
      presentationDebug.wallSplats += 1;
    } else if (effect.kind === "flowPulse") {
      const radius = 35 + (1 - alpha) * (80 + effect.stacks * 18);
      ctx.globalCompositeOperation = "screen";
      ctx.strokeStyle = effect.color;
      for (let ring = 0; ring < effect.stacks + 1; ring += 1) {
        ctx.globalAlpha = alpha * (1 - ring * 0.15);
        ctx.lineWidth = 7 - ring;
        ctx.beginPath();
        ctx.arc(0, 0, radius + ring * 18, -1.1, 1.1);
        ctx.stroke();
      }
    } else if (effect.kind === "feedbackTelegraph" || effect.kind === "feedbackBurst") {
      const burst = effect.kind === "feedbackBurst";
      const radius = (1 - alpha) * (burst ? 146 : 76) + 18;
      ctx.globalCompositeOperation = "screen";
      ctx.strokeStyle = effect.color;
      for (let ring = 0; ring < (burst ? 5 : 3); ring += 1) {
        ctx.globalAlpha = alpha * (1 - ring * 0.13);
        ctx.lineWidth = burst ? 8 - ring : 4;
        ctx.beginPath();
        ctx.ellipse(0, 0, radius * (0.42 + ring * 0.18), radius * (0.28 + ring * 0.11), ring % 2 ? 0.18 : -0.18, 0, Math.PI * 2);
        ctx.stroke();
      }
    } else if (effect.kind === "projectileLaunch" || effect.kind === "projectileBurst") {
      const burst = effect.kind === "projectileBurst";
      const radius = (1 - alpha) * (burst ? 112 : 62) + 12;
      ctx.globalCompositeOperation = "screen";
      ctx.fillStyle = effect.color;
      ctx.beginPath();
      ctx.arc(0, 0, radius * 0.34, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = effect.color;
      for (let ray = 0; ray < (burst ? 12 : 7); ray += 1) {
        const angle = ray * Math.PI * 2 / (burst ? 12 : 7);
        ctx.lineWidth = 3 + ray % 3 * 2;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle) * radius * 0.25, Math.sin(angle) * radius * 0.25);
        ctx.lineTo(Math.cos(angle) * radius, Math.sin(angle) * radius);
        ctx.stroke();
      }
    } else if (effect.kind === "slash") {
      ctx.lineWidth = 18 * alpha;
      ctx.beginPath();
      ctx.moveTo(-170, 110);
      ctx.lineTo(160, -150);
      ctx.stroke();
    } else if (effect.kind === "shockRing") {
      const growth = 1 - alpha;
      ctx.globalCompositeOperation = "lighter";
      ctx.shadowBlur = 0;
      ctx.lineWidth = 2.5 + alpha * 5;
      ctx.globalAlpha = alpha * 0.85;
      ctx.beginPath();
      ctx.ellipse(0, 0, (effect.size || 60) * (0.25 + growth), (effect.size || 60) * (0.18 + growth * 0.7), 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalCompositeOperation = "source-over";
    } else if (effect.kind === "afterimage") {
      // Rendered in the world pass before the fighters; nothing to do here.
    } else if (effect.kind === "groundCrackFlash") {
      // v2.6 MOTION heavy-landing crack flash (spec 5): the stage-scar visual
      // language — chalky scuff, pale chipped edge, dark crack — as a ~0.35s
      // flash that fades out completely. Presentation only, no persistence.
      ctx.shadowBlur = 0;
      ctx.rotate(effect.rot);
      ctx.globalAlpha = alpha * 0.4;
      ctx.fillStyle = "rgba(196,184,164,0.6)";
      ctx.beginPath();
      ctx.ellipse(0, 0, effect.scuffW * (1.05 - alpha * 0.2), effect.scuffH, 0, 0, Math.PI * 2);
      ctx.fill();
      for (const [style, width, offsetY, passAlpha] of [
        ["rgba(255,244,222,0.85)", 3.2, -1.4, 0.9],
        ["rgba(10,9,8,0.95)", 2.2, 0, 0.75],
      ]) {
        ctx.globalAlpha = alpha * passAlpha;
        ctx.strokeStyle = style;
        ctx.lineWidth = width;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.beginPath();
        ctx.moveTo(effect.points[0][0], effect.points[0][1] + offsetY);
        for (let index = 1; index < effect.points.length; index += 1) {
          ctx.lineTo(effect.points[index][0], effect.points[index][1] + offsetY);
        }
        ctx.stroke();
      }
    } else if (effect.kind === "guard") {
      const radius = (1 - alpha) * 64 + 42;
      ctx.lineWidth = 9 * alpha;
      ctx.beginPath();
      ctx.arc(0, 0, radius, -1.45, 1.45);
      ctx.stroke();
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, radius + 15, -1.18, 1.18);
      ctx.stroke();
    } else {
      const radius = (1 - alpha) * 165 + 25;
      ctx.lineWidth = 11 * alpha;
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }
}

function drawFinisherOverlay() {
  const finisher = state.finisher;
  if (!finisher) return;
  const attacker = state.fighters[finisher.winner];
  const progress = finisher.elapsed / finisher.script.duration;
  const cinematic = finisherCinematicCamera(state.cinematicZoom);
  const barHeight = 30 + cinematic.intensity * 30 + Math.sin(clamp(progress * 2, 0, 1) * Math.PI * .5) * 7;
  const tint = ctx.createRadialGradient(W * .5, H * .48, 90, W * .5, H * .48, W * .72);
  tint.addColorStop(0, `${attacker.def.accent}${cinematic.shot === "final-impact" ? "2f" : "16"}`);
  tint.addColorStop(.62, "rgba(60,0,8,.08)");
  tint.addColorStop(1, `rgba(0,0,0,${.28 + cinematic.intensity * .24})`);
  ctx.fillStyle = tint;
  ctx.fillRect(0, 0, W, H);
  drawCinematicGoreOverlay();
  ctx.fillStyle = "rgba(0,0,0,.9)";
  ctx.fillRect(0, 0, W, barHeight);
  ctx.fillRect(0, H - barHeight, W, barHeight);
  ctx.fillStyle = attacker.def.accent;
  ctx.fillRect(0, barHeight - 3, W, 3);
  ctx.fillRect(0, H - barHeight, W, 3);

  // CINEMA 3D text layout: the DOM HUD (health bars, grit) covers the TOP
  // letterbox bar in 3D mode, which truncated every meta label into garbage
  // ("CIN...", "REAK", "...ON" peeking around the bars — the critic's
  // shipping blocker). All three meta labels move into the BOTTOM bar, which
  // is actually visible. 2D-off path is byte-identical.
  const dressedOverlay = cinema3dDressingActive();
  const metaY = dressedOverlay ? H - 10 : barHeight - 11;
  ctx.save();
  ctx.textAlign = "left";
  ctx.font = "900 11px Arial Narrow, Arial";
  ctx.fillStyle = attacker.def.accent;
  ctx.globalAlpha = .82;
  ctx.fillText(`CINEMATIC · ${cinematic.shot.replaceAll("-", " ").toUpperCase()}`, 24, metaY);
  if (state.graphicFatalities) {
    const attackerId = attacker.def.finisherScriptId || attacker.def.id;
    const fatality = getGraphicFatality(attackerId, finisher.type);
    ctx.textAlign = "center";
    ctx.fillStyle = "#d90b19";
    ctx.fillText(`REALITY BREAK · ${fatality.special} FATALITY`, W * .5, metaY);
  }
  if (cinematic.shot === "final-impact") {
    ctx.textAlign = "right";
    ctx.fillStyle = "#fff0df";
    ctx.font = "1000 14px Arial Narrow, Arial";
    ctx.fillText("FINAL-HIT SLOW MOTION", W - 24, metaY);
  }
  ctx.restore();

  // 3D mode drops the beat-label block once the fatality banner owns the
  // frame (round-3, critic item 2): "PIZZA WHEEL ARM SEVER" was printing in
  // the banner AND down here — four stacked text elements over one shot.
  if (finisher.beatLife > 0 && !(dressedOverlay && finisher.fatalityTriggered)) {
    const alpha = clamp(finisher.beatLife * 2.2, 0, 1);
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.textAlign = "center";
    ctx.font = "900 17px Arial Narrow, Arial";
    ctx.fillStyle = "white";
    ctx.shadowColor = "black";
    ctx.shadowBlur = 8;
    ctx.fillText(finisher.beatLabel, W * .5, H - barHeight - 16);
    ctx.font = "900 11px Arial";
    ctx.fillStyle = attacker.def.accent;
    // 3D mode: the beats counter rides just under its beat label, clear of
    // the meta line now living in the bottom bar.
    ctx.fillText(`${finisher.impactIndex} / 3 PROJECTILE BEATS`, W * .5,
      dressedOverlay ? H - barHeight - 2 : H - barHeight + 19);
    ctx.restore();
  }

  if (finisher.fatalityTriggered) {
    const attackerId = attacker.def.finisherScriptId || attacker.def.id;
    const fatality = graphicFatalitySnapshot(attackerId, finisher.type, finisher.elapsed, finisher.fatalityAt);
    fatality.aftermath = Math.max(fatality.aftermath, finisherAftermathSeconds(finisher));
    const reveal = fatality.reveal;
    // 2.8 critic round (M3): the title card gets its intro beat (~1s) parked
    // over the frame, then LIFTS out of the victim's screen region — it
    // tucks up under the top letterbox bar at reduced scale while the
    // caption stack fades out, so the strongest arterial window is readable.
    const lift = clamp((fatality.aftermath - 1.05) / 0.5, 0, 1);
    const titleY = lerp(H * .23, barHeight + 30, lift);
    ctx.save();
    ctx.globalAlpha = Math.sin(reveal * Math.PI * .5) * clamp(1.45 - fatality.aftermath * .14, .55, 1);
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.shadowColor = "rgba(0,0,0,.95)";
    ctx.shadowBlur = 18;
    ctx.lineWidth = Math.round(lerp(12, 7, lift));
    ctx.strokeStyle = "rgba(0,0,0,.92)";
    ctx.fillStyle = fatality.palette[0];
    ctx.font = `1000 ${Math.round(lerp(52, 28, lift))}px Arial Narrow, Impact, sans-serif`;
    ctx.strokeText("GRAPHIC FATALITY", W * .5, titleY);
    ctx.fillText("GRAPHIC FATALITY", W * .5, titleY);
    if (lift < 0.98) {
      const captionAlpha = 1 - lift;
      ctx.globalAlpha *= captionAlpha;
      ctx.font = "900 18px Arial Narrow, Arial, sans-serif";
      ctx.lineWidth = 7;
      ctx.fillStyle = "#fff0df";
      // 3D mode: ONE title line under the header (round-3, critic item 2) —
      // the cinematic carries the story; the caption stack is gone.
      const titleLine = dressedOverlay ? fatality.caption : `${fatality.title} · ${fatality.caption}`;
      ctx.strokeText(titleLine, W * .5, titleY + H * .07);
      ctx.fillText(titleLine, W * .5, titleY + H * .07);
      if (!dressedOverlay) {
        ctx.font = "900 14px Arial Narrow, Arial, sans-serif";
        ctx.lineWidth = 6;
        ctx.fillStyle = attacker.def.accent;
        const signatureLine = `${fatality.projectileFinale} · ${fatality.device}`;
        ctx.strokeText(signatureLine, W * .5, titleY + H * .115);
        ctx.fillText(signatureLine, W * .5, titleY + H * .115);
      }
    }
    ctx.restore();
  }
}

// R1.9: hex + alpha helper for the viewer's translucent fills.
function fillWithAlpha(hex, alpha) {
  const value = parseInt(String(hex).replace("#", ""), 16);
  if (!Number.isFinite(value)) return `rgba(255,255,255,${alpha})`;
  return `rgba(${(value >> 16) & 255},${(value >> 8) & 255},${value & 255},${alpha})`;
}

const FRAME_PHASE_ROLES = Object.freeze({
  startup: ["frameStartup", "#59d66d"],
  active: ["frameActive", "#ff4d5e"],
  recovery: ["frameRecovery", "#3fa7ff"],
  hitstun: ["frameStun", "#ffd54a"],
  blockstun: ["frameStun", "#b8985a"],
  // v5.1 TEMPO TELLS: the taxed whiff tail (magenta — neither the active red
  // nor the recovery blue, so "that was the tax" reads at a glance) and the
  // re-arm gap (grey: the fighter is free to move but not to swing).
  whiff: ["frameWhiff", "#ff4fd8"],
  rearm: ["frameRearm", "#8f98a8"],
});

function framePhaseColor(phase) {
  const entry = FRAME_PHASE_ROLES[phase];
  if (!entry) return "#252c35";
  return assistColor(entry[0], entry[1]);
}

/**
 * R1.9: SFV-style frame meter strip — one cell per simulation tick per
 * fighter, colored startup/active/recovery/stun, with the measured ADVANTAGE
 * number rendered at the live edge. Render-only, fed by feedFrameMeter(),
 * gated behind the FRAME METER training toggle.
 */
function drawTrainingFrameMeter() {
  if (state.mode !== "training" || !state.training.showFrameMeter) return;
  if (state.screen !== "fight" || state.fighters.length !== 2) return;
  const cellWidth = 7;
  const cellHeight = 13;
  const originX = 150;
  const width = FRAME_METER_CELLS * (cellWidth + 1) + 12;
  const originY = H - 104;
  ctx.save();
  ctx.fillStyle = "rgba(3,8,13,.82)";
  ctx.fillRect(originX - 34, originY - 8, width + 116, cellHeight * 2 + 30);
  ctx.strokeStyle = "rgba(78,221,245,.5)";
  ctx.strokeRect(originX - 34, originY - 8, width + 116, cellHeight * 2 + 30);
  ctx.font = "900 11px ui-monospace, monospace";
  ctx.textBaseline = "top";
  for (const side of [0, 1]) {
    const history = frameMeter.history[side];
    const rowY = originY + side * (cellHeight + 4);
    ctx.fillStyle = side === 0
      ? assistColor("hurtboxP1", "#35e7ff")
      : assistColor("hurtboxP2", "#ff4dc4");
    ctx.fillText(`P${side + 1}`, originX - 28, rowY + 2);
    for (let index = 0; index < history.length; index += 1) {
      const phase = history[index];
      ctx.fillStyle = phase === "idle" ? "#1c232c" : framePhaseColor(phase);
      ctx.fillRect(originX + index * (cellWidth + 1), rowY, cellWidth, cellHeight);
    }
  }
  const advantage = state.training.lastAdvantage;
  if (Number.isFinite(advantage)) {
    ctx.fillStyle = advantage >= 0
      ? assistColor("frameStartup", "#71f7a1")
      : assistColor("frameActive", "#ff6478");
    ctx.fillText(`${advantage >= 0 ? "+" : ""}${advantage}`, originX + width - 4, originY + 8);
  }
  ctx.restore();
}

function drawDebugOverlay() {
  const trainingBoxes = state.mode === "training" && state.training.showHitboxes;
  if (!state.debug && !trainingBoxes) return;
  ctx.save();
  ctx.lineWidth = 2;
  ctx.font = "700 14px ui-monospace, SFMono-Regular, Menlo, monospace";
  ctx.textBaseline = "top";

  // R1.9 viewer polish: dashed hurtboxes with translucent phase-colored fills
  // (startup/active/recovery from the live move), solid filled hitboxes with
  // attack-level tags, dotted pushbox, and the proximity-grab ring — all
  // through assistColor so the colorblind palettes reach the canvas too.
  for (const fighter of state.fighters) {
    const phase = trainingFramePhase(fighter);
    const hurtColor = fighter.side === 0
      ? assistColor("hurtboxP1", "#35e7ff")
      : assistColor("hurtboxP2", "#ff4dc4");
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = hurtColor;
    const phaseTint = fighter.attacking ? framePhaseColor(phase) : null;
    for (const box of getHurtboxes(fighter)) {
      if (phaseTint) {
        ctx.fillStyle = fillWithAlpha(phaseTint, 0.16);
        ctx.fillRect(box.x, box.y, box.width, box.height);
      }
      ctx.strokeRect(box.x, box.y, box.width, box.height);
    }
    ctx.setLineDash([2, 3]);
    ctx.strokeStyle = fillWithAlpha(assistColor("pushbox", "#6eff7d"), 0.88);
    const pushHalf = fighter.crouch
      ? fighter.movement.crouchingPushboxHalfWidth
      : fighter.movement.standingPushboxHalfWidth;
    ctx.strokeRect(fighter.x - pushHalf, fighter.y - 112, pushHalf * 2, 112);
    ctx.setLineDash([]);
    const hitColor = assistColor("hitbox", "#ffef5a");
    ctx.strokeStyle = hitColor;
    ctx.fillStyle = fillWithAlpha(hitColor, 0.3);
    let levelTagged = false;
    for (const box of getActiveHitboxes(fighter)) {
      ctx.fillRect(box.x, box.y, box.width, box.height);
      ctx.strokeRect(box.x, box.y, box.width, box.height);
      if (!levelTagged && fighter.attacking) {
        levelTagged = true;
        ctx.font = "900 12px ui-monospace, monospace";
        ctx.fillStyle = "#0b0e14";
        ctx.fillRect(box.x, box.y - 15, 9 * String(fighter.attacking.level).length + 8, 14);
        ctx.fillStyle = hitColor;
        ctx.fillText(String(fighter.attacking.level).toUpperCase(), box.x + 4, box.y - 14);
        ctx.font = "700 14px ui-monospace, SFMono-Regular, Menlo, monospace";
      }
    }
  }

  if (trainingBoxes && state.fighters.length === 2) {
    // 104px proximity-grab ring around the player, the same rule the grab
    // hint reads — lights up exactly when a grab would connect.
    const [player, opponent] = state.fighters;
    const grabReady = inProximityGrabRange(player, opponent) && !player.attacking;
    ctx.setLineDash(grabReady ? [] : [7, 6]);
    ctx.lineWidth = grabReady ? 3 : 2;
    ctx.strokeStyle = grabReady
      ? assistColor("frameStartup", "#71f7a1")
      : "rgba(255,255,255,.4)";
    ctx.beginPath();
    ctx.ellipse(player.x, player.y - 6, PROXIMITY_GRAB_RANGE, PROXIMITY_GRAB_RANGE * 0.24, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.lineWidth = 2;
    // On-canvas legend for the viewer.
    const legend = [
      ["STARTUP", framePhaseColor("startup")],
      ["ACTIVE", framePhaseColor("active")],
      ["RECOVERY", framePhaseColor("recovery")],
      ["HITBOX", assistColor("hitbox", "#ffef5a")],
      ["HURTBOX P1", assistColor("hurtboxP1", "#35e7ff")],
      ["HURTBOX P2", assistColor("hurtboxP2", "#ff4dc4")],
      ["GRAB RING 104PX", "#ffffff"],
    ];
    // Right edge, below the training panel and above the school panel, clear
    // of the left-side input history column.
    const legendX = W - 150;
    const legendY = Math.round(H * 0.5);
    ctx.font = "900 10px ui-monospace, monospace";
    ctx.fillStyle = "rgba(0,0,0,.72)";
    ctx.fillRect(legendX, legendY, 136, legend.length * 15 + 10);
    legend.forEach(([label, color], index) => {
      ctx.fillStyle = color;
      ctx.fillRect(legendX + 6, legendY + 6 + index * 15, 9, 9);
      ctx.fillStyle = "#e8eef4";
      ctx.fillText(label, legendX + 20, legendY + 5 + index * 15);
    });
    ctx.font = "700 14px ui-monospace, SFMono-Regular, Menlo, monospace";
  }

  if (!state.debug) {
    ctx.restore();
    return;
  }

  const lines = [
    `SIM ${SIMULATION_HZ}HZ · TICK ${state.simulationTick} · STEPS ${state.simulationSteps}`,
    `ALPHA ${state.simulationAlpha.toFixed(3)} · DROPPED ${state.simulationDroppedSeconds.toFixed(3)}s`,
    `PHASE ${state.phase} · RNG ${state.rng.getState().toString(16).padStart(8, "0")}`,
    ...(onlineSession.rollback ? [(() => {
      const net = onlineSession.rollback.metrics();
      return `NET F${net.frame} · CONF ${net.confirmedRemoteFrame} · ${net.inputDelay}F DELAY · ${net.rollbacks} RB / ${net.resimulatedFrames} RESIM · MAX ${net.maximumRollback}F ${net.maximumResimulationMs.toFixed(3)}MS · DESYNC ${onlineSession.checksumMismatches}`;
    })()] : []),
    ...state.fighters.map((fighter) => {
      const move = fighter.attacking?.profileId || "—";
      const guard = fighter.guarding ? fighter.guardHeight.toUpperCase() : "—";
      const combo = fighter.combo.snapshot(state.simulationTick);
      return `P${fighter.side + 1} ${fighter.combatState.toUpperCase()} F${fighter.stateFrame} · ${move} · GRIT ${Math.floor(fighter.meter)} · FLOW ${fighter.rhythmStacks || 0} · COMBO ${combo.hits}/${combo.damage.toFixed(1)} · JUG ${state.fighters[1 - fighter.side]?.juggleCount || 0} · GUARD ${guard} · GM ${Math.floor(fighter.guardMeter)}${fighter.guardCrushFrames > 0 ? ` CRUSH ${fighter.guardCrushFrames}` : ""} · HS ${fighter.hitstunFrames}/BS ${fighter.blockstunFrames}/KD ${fighter.knockdownFrames} · BUF ${fighter.inputBuffer.snapshot().map((entry) => entry.action).join("/") || "—"}`;
    }),
    ...commandHistory.map((history, side) => `P${side + 1} INPUT ${history.slice(-8).map((entry) => entry.token).join(" › ") || "—"}`),
  ];
  const panelWidth = 980;
  const panelHeight = 18 + lines.length * 19;
  ctx.fillStyle = "rgba(0,0,0,.82)";
  ctx.fillRect(14, 64, panelWidth, panelHeight);
  ctx.strokeStyle = "rgba(70,235,255,.75)";
  ctx.strokeRect(14, 64, panelWidth, panelHeight);
  lines.forEach((line, index) => {
    ctx.fillStyle = index === 0 ? "#5cf3ff" : "#f4f7ff";
    ctx.fillText(line, 25, 74 + index * 19);
  });
  ctx.restore();
}

function finisherCameraTarget() {
  const camera = finisherCinematicCamera(state.cinematicZoom);
  return { x: camera.x, y: camera.y };
}

// ---------------------------------------------------------------------------
// Wave 7 render tech. Offscreen-canvas compositing passes, all module-level
// render-only state on the documented superDimLevel pattern: never
// snapshotted, never read by the simulation, so rollback checksums are
// untouched. Latches set from simulation paths follow the announce() pattern
// (rollbackResimulating guard + simulationTick dedupe). Performance
// discipline: every pass is skipped outright on the battery profile
// (!performance.shadows) and degrades on balanced; offscreen surfaces are
// cached and only ever (re)sized on a backing-store change, never allocated
// per frame.
// ---------------------------------------------------------------------------

// Backing-store scale for the DPR-sharp mode (feature: SHARP RENDER). Logical
// coordinates stay W x H = 1280x720 everywhere; draw() applies a
// setTransform(renderDpr,...) baseline so all existing code is untouched.
let renderDpr = 1;

function createOffscreen(width, height) {
  const surface = document.createElement("canvas");
  surface.width = width;
  surface.height = height;
  return surface;
}

// Cached offscreen surfaces, lazily created once and resized in place only
// when the backing store or profile resolution changes.
const renderSurfaces = {
  bloom: null,
  aberrRed: null,
  aberrCyan: null,
  aberrMask: null,
  crtPattern: null,
  crtVignette: null,
};

function ensureSurface(key, width, height) {
  let surface = renderSurfaces[key];
  if (!surface) {
    surface = createOffscreen(width, height);
    renderSurfaces[key] = surface;
  } else if (surface.width !== width || surface.height !== height) {
    surface.width = width;
    surface.height = height;
  }
  return surface;
}

// --- Frame capture service -------------------------------------------------
// Every pass that resamples the composited frame reads a one-frame-late
// ImageBitmap snapshot instead of drawImage(canvas, ...): sampling the live
// canvas forces a synchronous raster flush/readback that is catastrophically
// slow on software rasterisers (~50ms/frame measured headless), while
// createImageBitmap snapshots asynchronously off the critical path (~1ms).
// One frame of latency is invisible in a soft additive glow or a smear.
// The capture is taken after the stage grade + slow-mo blend and before the
// bloom composite, so the smear accumulates recursively but bloom can never
// feed back into itself.
let frameBitmap = null;
let frameBitmapPending = false;
let slowMoBlurWasActive = false;
// Adaptive refresh cadence. On GPU-composited browsers a capture is a cheap
// texture copy and the snapshot refreshes every frame. Software rasterisers
// (headless QA, --disable-gpu) pay a synchronous full-frame raster per
// capture, so the cadence backs off and the passes composite from a slightly
// stale snapshot instead — the counters and the look survive, the stall is
// amortised.
let frameCaptureCooldown = 0;
let frameCaptureCostEma = 0;

function requestFrameCapture() {
  // Bloom runs on every high/balanced fight frame, and every other consumer
  // (ring, RGB split, slow-mo smear) is inside that same gate — so battery
  // never pays for a single capture.
  if (state.screen !== "fight" || !state.performance.shadows) return;
  if (frameBitmapPending || typeof createImageBitmap !== "function") return;
  if (frameCaptureCooldown > 0) {
    frameCaptureCooldown -= 1;
    return;
  }
  frameBitmapPending = true;
  const started = performance.now();
  const capture = createImageBitmap(canvas);
  // The raster stall, when there is one, is synchronous inside the call.
  const syncCost = performance.now() - started;
  frameCaptureCostEma = frameCaptureCostEma
    ? frameCaptureCostEma * 0.8 + syncCost * 0.2
    : syncCost;
  frameCaptureCooldown = frameCaptureCostEma > 40 ? 7
    : frameCaptureCostEma > 20 ? 3
      : frameCaptureCostEma > 8 ? 1 : 0;
  capture.then((bitmap) => {
    if (frameBitmap) frameBitmap.close();
    frameBitmap = bitmap;
    frameBitmapPending = false;
  }).catch(() => {
    frameBitmapPending = false;
  });
}

// Draw the latest frame snapshot stretched over the full backing store.
function drawFrameBitmap(target) {
  target.drawImage(
    frameBitmap,
    0, 0, frameBitmap.width, frameBitmap.height,
    0, 0, canvas.width, canvas.height,
  );
}

// Sizes the canvas backing store to min(devicePixelRatio, 2) on the desktop
// high profile so atlases and HUD text render at native DPI. CSS sizing
// (width/height 100%) is untouched, so layout, touch mapping and the smoke
// suite's CSS-pixel measurements never change.
function applyBackingStoreResolution() {
  const nativeDpr = Number(window.devicePixelRatio) || 1;
  // Sharp rendering follows the profile, not the pointer type: a phone that
  // earned the high profile renders sharp exactly like a HiDPI desktop
  // (1.9E mobile parity — the old coarse-pointer ban left phones upscaling a
  // 1x backing store across ~3x screens, which is also what let the scanline
  // overlay shred large lettering). The cap stays at the desktop-proven 2x
  // (2560x1440, ~3.7 MP): a denser phone still gets the 2x store scaled to
  // its screen, crisp without allocating a ~7 MP canvas no shipped build has
  // ever driven. Battery/balanced and the sharp-render toggle still force
  // 1x, so constrained devices keep the cheap path.
  const sharp = Boolean(state.sharpRender)
    && state.performance.id === "high"
    && nativeDpr > 1;
  const dpr = sharp ? Math.min(2, nativeDpr) : 1;
  const width = Math.round(W * dpr);
  const height = Math.round(H * dpr);
  if (renderDpr === dpr && canvas.width === width && canvas.height === height) return;
  renderDpr = dpr;
  canvas.width = width;
  canvas.height = height;
  if (frameBitmap) {
    frameBitmap.close();
    frameBitmap = null;
  }
  ctx.setTransform(renderDpr, 0, 0, renderDpr, 0, 0);
}

// --- Feature 1: quarter-res bloom composite --------------------------------
// The whole composited frame is downsampled to a small offscreen, squared
// against itself (a free highlight threshold: midtones collapse, neon and
// spark whites survive) and drawn back full-screen additively — the bilinear
// upscale supplies the soft blur. High: 320x180. Balanced: 160x90 at lower
// alpha. Battery: skipped.
function drawBloomComposite() {
  if (state.screen !== "fight" || !state.performance.shadows || !frameBitmap) return;
  const high = state.performance.id === "high";
  const bloomWidth = high ? 320 : 160;
  const bloomHeight = high ? 180 : 90;
  const surface = ensureSurface("bloom", bloomWidth, bloomHeight);
  const bloomCtx = surface.getContext("2d");
  bloomCtx.globalCompositeOperation = "copy";
  bloomCtx.drawImage(frameBitmap, 0, 0, frameBitmap.width, frameBitmap.height, 0, 0, bloomWidth, bloomHeight);
  // Self-multiply squares the image (a free highlight threshold); squaring
  // twice on high (image^4) keeps the glow to genuine emitters — neon,
  // practicals, sparks — instead of lifting whole bright sprites.
  bloomCtx.globalCompositeOperation = "multiply";
  bloomCtx.drawImage(surface, 0, 0);
  if (high) bloomCtx.drawImage(surface, 0, 0);
  bloomCtx.globalCompositeOperation = "source-over";
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  // "screen" rolls off softly near white, so bright sprites glow without
  // clipping the way straight additive compositing does.
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = high ? 0.34 : 0.18;
  ctx.drawImage(surface, 0, 0, bloomWidth, bloomHeight, 0, 0, canvas.width, canvas.height);
  ctx.restore();
  presentationDebug.bloomPasses += 1;
}

// --- Feature 2: RGB-split chromatic aberration -----------------------------
// Heavy moments only: a render-side impulse (fatal impact, wall splat, super
// ignition) or a super in flight (superDimLevel > 0.5, suppressed during the
// long finisher aftermath so the tear never becomes steady-state). Channel
// isolation: two cached offscreens hold red / cyan multiplied copies of the
// frame, edge-masked (destination-in radial falloff, centre stays sharp) and
// recombined "lighter" at opposite offsets.
let aberrationImpulse = 0;

function chromaticAberrationLevel() {
  const superFlight = !state.finisher && superDimLevel > 0.5
    ? Math.min(1, (superDimLevel - 0.5) * 2.4) : 0;
  return Math.max(aberrationImpulse, superFlight);
}

function ensureAberrationMask(width, height) {
  const cached = renderSurfaces.aberrMask;
  if (cached && cached.width === width && cached.height === height) return cached;
  const surface = ensureSurface("aberrMask", width, height);
  const maskCtx = surface.getContext("2d");
  maskCtx.clearRect(0, 0, width, height);
  const gradient = maskCtx.createRadialGradient(
    width * 0.5, height * 0.5, Math.min(width, height) * 0.22,
    width * 0.5, height * 0.5, Math.max(width, height) * 0.62,
  );
  gradient.addColorStop(0, "rgba(0,0,0,0)");
  gradient.addColorStop(0.55, "rgba(0,0,0,0.3)");
  gradient.addColorStop(1, "rgba(0,0,0,1)");
  maskCtx.fillStyle = gradient;
  maskCtx.fillRect(0, 0, width, height);
  return surface;
}

function drawChromaticAberration() {
  if (aberrationImpulse > 0) aberrationImpulse = Math.max(0, aberrationImpulse - 0.15);
  if (state.screen !== "fight" || !state.performance.shadows || !frameBitmap) return;
  if (state.accessibility.reducedMotion) return;
  const level = chromaticAberrationLevel();
  if (level <= 0.02) return;
  const high = state.performance.id === "high";
  // Balanced degrades to half-res ghost copies (the upscale blurs them a
  // touch, which reads fine for a 2px tear) at a smaller max offset.
  const scale = high ? 1 : 0.5;
  const splitWidth = Math.round(canvas.width * scale);
  const splitHeight = Math.round(canvas.height * scale);
  const mask = ensureAberrationMask(splitWidth, splitHeight);
  const passes = [
    ["aberrRed", "#ff0000"],
    ["aberrCyan", "#00ffff"],
  ];
  for (const [key, channel] of passes) {
    const surface = ensureSurface(key, splitWidth, splitHeight);
    const splitCtx = surface.getContext("2d");
    splitCtx.globalCompositeOperation = "copy";
    splitCtx.drawImage(frameBitmap, 0, 0, frameBitmap.width, frameBitmap.height, 0, 0, splitWidth, splitHeight);
    splitCtx.globalCompositeOperation = "multiply";
    splitCtx.fillStyle = channel;
    splitCtx.fillRect(0, 0, splitWidth, splitHeight);
    splitCtx.globalCompositeOperation = "destination-in";
    splitCtx.drawImage(mask, 0, 0);
    splitCtx.globalCompositeOperation = "source-over";
  }
  const offset = (high ? 3 : 2) * level * renderDpr;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = Math.min(0.85, 0.5 + level * 0.35);
  ctx.drawImage(renderSurfaces.aberrRed, -offset, 0, canvas.width, canvas.height);
  ctx.drawImage(renderSurfaces.aberrCyan, offset, 0, canvas.width, canvas.height);
  ctx.restore();
  presentationDebug.rgbSplits += 1;
}

// --- Feature 3: screen-space distortion ring -------------------------------
// One concurrent refraction ring: concentric annulus slices of the already
// composited frame redrawn with tiny alternating scale offsets around the
// impact point (no per-pixel work). World-space origin is projected through
// the world transform captured just before the restore in draw().
let distortionRing = null;
let distortionRingTick = -1;
let worldScreenTransform = null;

function latchDistortionRing(x, y) {
  if (rollbackResimulating || distortionRingTick === state.simulationTick) return;
  if (distortionRing) return; // cap: 1 concurrent ring
  if (state.accessibility.reducedMotion || !state.performance.shadows) return;
  if (!$("#flashToggle").checked) return;
  distortionRingTick = state.simulationTick;
  distortionRing = { x, y, age: 0, duration: 0.3 };
  hudFxDebug.distortionRings += 1;
}

function drawDistortionRing(dtMs) {
  if (!distortionRing) return;
  const ring = distortionRing;
  ring.age += dtMs / 1000;
  if (ring.age >= ring.duration || state.screen !== "fight"
    || !state.performance.shadows || state.accessibility.reducedMotion) {
    distortionRing = null;
    return;
  }
  if (!frameBitmap) return;
  const matrix = worldScreenTransform;
  const originX = matrix ? matrix.a * ring.x + matrix.c * ring.y + matrix.e : ring.x * renderDpr;
  const originY = matrix ? matrix.b * ring.x + matrix.d * ring.y + matrix.f : ring.y * renderDpr;
  const progress = ring.age / ring.duration;
  const eased = 1 - (1 - progress) ** 2;
  const radius = (36 + eased * 330) * renderDpr;
  const strength = (1 - progress) * 0.028;
  const slices = state.performance.id === "high" ? 4 : 2;
  const sliceDepth = 8 * renderDpr;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  for (let index = 0; index < slices; index += 1) {
    const inner = radius + index * sliceDepth;
    const outer = inner + sliceDepth;
    const magnify = 1 + strength * (index % 2 === 0 ? 1 : -0.7) * (1 - index / (slices + 1));
    ctx.save();
    ctx.beginPath();
    ctx.arc(originX, originY, outer, 0, Math.PI * 2);
    ctx.arc(originX, originY, inner, 0, Math.PI * 2, true);
    ctx.clip();
    ctx.translate(originX, originY);
    ctx.scale(magnify, magnify);
    ctx.translate(-originX, -originY);
    drawFrameBitmap(ctx);
    ctx.restore();
  }
  // Hairline additive rim so the refraction edge reads at speed.
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = 0.1 * (1 - progress);
  ctx.strokeStyle = "#cfe6ff";
  ctx.lineWidth = 1.5 * renderDpr;
  ctx.beginPath();
  ctx.arc(originX, originY, radius + sliceDepth * slices * 0.5, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

// --- Feature 5: slow-mo motion-blur buffer ---------------------------------
// While fatality time dilation runs, the previous frame's capture (the single
// cached copy) is blended over the fresh world at low alpha. Because the next
// capture is taken after this blend, the smear accumulates recursively with a
// 0.35 geometric decay — trailing photographic smears confined to the slow-mo
// window. The first blend after activation is skipped (the standing capture
// predates the window), and nothing leaks out: normal frames simply never
// blend.
function updateSlowMoBlur() {
  const active = state.screen === "fight"
    && (state.finisher?.slowMotionTicks || 0) > 0
    && state.performance.id !== "battery"
    && !state.accessibility.reducedMotion;
  if (!active) {
    slowMoBlurWasActive = false;
    return;
  }
  if (frameBitmap && slowMoBlurWasActive) {
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 0.35;
    drawFrameBitmap(ctx);
    ctx.restore();
    hudFxDebug.sloMoBlurFrames += 1;
  }
  slowMoBlurWasActive = true;
}

// --- Feature 6: CRT display mode -------------------------------------------
// Opt-in arcade-monitor look: cached RGB phosphor-stripe + scanline pattern,
// cached low-res barrel vignette upscaled over the corners, and a faint
// rolling flicker band (gated on #flashToggle and reduced motion). Pure
// screen-space, applied after everything; skipped on battery.
function crtOverlayActive() {
  return Boolean(state.crtMode) && state.performance.id !== "battery";
}

function ensureCrtPattern() {
  if (renderSurfaces.crtPattern) return renderSurfaces.crtPattern;
  const tile = createOffscreen(3, 3);
  const tileCtx = tile.getContext("2d");
  tileCtx.fillStyle = "rgba(255,64,64,0.055)";
  tileCtx.fillRect(0, 0, 1, 3);
  tileCtx.fillStyle = "rgba(64,255,96,0.05)";
  tileCtx.fillRect(1, 0, 1, 3);
  tileCtx.fillStyle = "rgba(80,128,255,0.06)";
  tileCtx.fillRect(2, 0, 1, 3);
  tileCtx.fillStyle = "rgba(4,6,10,0.17)";
  tileCtx.fillRect(0, 2, 3, 1);
  renderSurfaces.crtPattern = ctx.createPattern(tile, "repeat");
  return renderSurfaces.crtPattern;
}

function ensureCrtVignette() {
  if (renderSurfaces.crtVignette) return renderSurfaces.crtVignette;
  const surface = createOffscreen(320, 180);
  const vignetteCtx = surface.getContext("2d");
  const gradient = vignetteCtx.createRadialGradient(160, 90, 74, 160, 90, 208);
  gradient.addColorStop(0, "rgba(0,0,0,0)");
  gradient.addColorStop(0.72, "rgba(0,0,0,0.05)");
  gradient.addColorStop(1, "rgba(0,0,0,0.36)");
  vignetteCtx.fillStyle = gradient;
  vignetteCtx.fillRect(0, 0, 320, 180);
  renderSurfaces.crtVignette = surface;
  return surface;
}

// Offscreen scratch for the 3D-mode CRT pass: the scanline pattern is built
// here first so soft holes can be punched over the fighters (a straight
// destination-out on the main canvas would erase the world beneath).
let crtPunchCanvas = null;
let crtPunchCtx = null;

function drawCrtOverlay(time) {
  if (!crtOverlayActive()) return;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  // CINEMA 3D (critic fix 6): the scanline veil lifts ~50% over the character
  // bodies — full-strength scanlines beat against the sprite texels into
  // moiré on faces. Stage keeps the full CRT flavour; 2D-off path untouched.
  let punched = false;
  if (cinema3dWorldActive() && cinema3dBridge.renderer?.projectSim && state.fighters?.length === 2) {
    if (!crtPunchCanvas || crtPunchCanvas.width !== canvas.width || crtPunchCanvas.height !== canvas.height) {
      crtPunchCanvas = document.createElement("canvas");
      crtPunchCanvas.width = canvas.width;
      crtPunchCanvas.height = canvas.height;
      crtPunchCtx = crtPunchCanvas.getContext("2d");
    }
    const pctx = crtPunchCtx;
    pctx.setTransform(1, 0, 0, 1, 0, 0);
    pctx.clearRect(0, 0, crtPunchCanvas.width, crtPunchCanvas.height);
    pctx.fillStyle = ensureCrtPattern();
    pctx.fillRect(0, 0, crtPunchCanvas.width, crtPunchCanvas.height);
    const px = canvas.width / W;
    pctx.globalCompositeOperation = "destination-out";
    for (const fighter of state.fighters) {
      const feet = cinema3dBridge.renderer.projectSim(fighter.x, fighter.y);
      const head = cinema3dBridge.renderer.projectSim(fighter.x, fighter.y - fighter.height * 1.02);
      if (!feet || !head) continue;
      const cx = feet.x * px;
      const cy = (head.y + feet.y) * 0.5 * px;
      const ry = Math.max(24, (feet.y - head.y) * 0.62 * px);
      const rx = ry * 0.52;
      const hole = pctx.createRadialGradient(cx, cy, ry * 0.25, cx, cy, ry);
      hole.addColorStop(0, "rgba(0,0,0,0.5)");
      hole.addColorStop(0.7, "rgba(0,0,0,0.4)");
      hole.addColorStop(1, "rgba(0,0,0,0)");
      pctx.save();
      pctx.translate(cx, cy);
      pctx.scale(rx / ry, 1);
      pctx.translate(-cx, -cy);
      pctx.fillStyle = hole;
      pctx.beginPath();
      pctx.arc(cx, cy, ry, 0, Math.PI * 2);
      pctx.fill();
      pctx.restore();
    }
    pctx.globalCompositeOperation = "source-over";
    ctx.drawImage(crtPunchCanvas, 0, 0);
    punched = true;
  }
  if (!punched) {
    ctx.fillStyle = ensureCrtPattern();
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  ctx.drawImage(ensureCrtVignette(), 0, 0, canvas.width, canvas.height);
  if ($("#flashToggle").checked && !state.accessibility.reducedMotion) {
    const bandHeight = canvas.height * 0.16;
    const bandY = ((time * 0.055) % (canvas.height + bandHeight)) - bandHeight;
    const gradient = ctx.createLinearGradient(0, bandY, 0, bandY + bandHeight);
    gradient.addColorStop(0, "rgba(255,255,255,0)");
    gradient.addColorStop(0.5, "rgba(255,255,255,0.045)");
    gradient.addColorStop(1, "rgba(255,255,255,0)");
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = gradient;
    ctx.fillRect(0, bandY, canvas.width, bandHeight);
  }
  ctx.restore();
}

// --- Feature 7: super portrait cut-in band ---------------------------------
// FULL GRIT SUPER slams the attacker's roster portrait (the select-screen
// webp art, already preloaded in fighterImages) across a diagonal accent band
// for ~0.7s. Deliberately cheap (one drawImage + gradients), so it runs on
// every profile; reduced motion swaps the sweep for a static fade.
let superCutIn = null;
let superCutInTick = -1;
const SUPER_CUT_IN_SECONDS = 0.7;

// CINEMA 3D cut-in dressing: halftone dot + brush-streak pattern tiles, built
// once on first use. Only the 3D-mode banner draws these; the 2D banner path
// is byte-for-byte untouched.
let cutInHalftonePattern = null;
let cutInBrushPattern = null;
function cutInPatterns() {
  if (cutInHalftonePattern) return { halftone: cutInHalftonePattern, brush: cutInBrushPattern };
  // Tiles authored at 2x and played back through a 0.5 pattern transform:
  // the 1x banner dot screen read visibly aliased (AAA-critic fix 5).
  const dots = document.createElement("canvas");
  dots.width = dots.height = 96;
  const dctx = dots.getContext("2d");
  dctx.fillStyle = "rgba(0,0,0,0.85)";
  for (let y = 0; y < 4; y += 1) {
    for (let x = 0; x < 4; x += 1) {
      const r = (2.1 + ((x * 7 + y * 13) % 5) * 0.55) * 2;
      dctx.beginPath();
      dctx.arc(x * 24 + (y % 2 ? 12 : 0) + 6, y * 24 + 6, r, 0, Math.PI * 2);
      dctx.fill();
    }
  }
  const brush = document.createElement("canvas");
  brush.width = 512;
  brush.height = 128;
  const bctx = brush.getContext("2d");
  for (let i = 0; i < 34; i += 1) {
    const seed = Math.sin((i + 3) * 12.9898) * 43758.5453;
    const jitter = seed - Math.floor(seed);
    bctx.strokeStyle = `rgba(255,255,255,${(0.05 + jitter * 0.16).toFixed(3)})`;
    bctx.lineWidth = (0.8 + jitter * 2.6) * 2;
    const y = jitter * 128;
    bctx.beginPath();
    bctx.moveTo(-24, y + 10);
    bctx.lineTo(536, y - 12);
    bctx.stroke();
  }
  cutInHalftonePattern = dots;
  cutInBrushPattern = brush;
  return { halftone: dots, brush };
}

// Half-scale playback transform for the 2x cut-in tiles (3D banner only).
const CUT_IN_PATTERN_SCALE = new DOMMatrix([0.5, 0, 0, 0.5, 0, 0]);

// CINEMA 3D super portrait (AAA-critic fix 6): a dedicated aggressive
// close-up composed at 2x from the attacker's ACTUAL super wind-up atlas
// frame (HD atlas when available) with a hard white key rim, an accent
// back-rim and a contrast push — not the idle roster art re-pasted. 3D-mode
// only: none of this runs while the classic 2D banner draws.
const superPortraitHdImages = new Map();
const superPortraitCache = new Map();
function superPortrait3d(cut) {
  // v2.7 FRAMES: a motion-bank wind-up (the charge stance) composes from the
  // SD motion sheet — there are NO HD motion sheets, so that bank never
  // requests renderer/hd/.
  const bank = cut.poseBank === "motion" && fighterMotionAtlases[cut.fighterId]?.complete
    ? "motion"
    : cut.poseBank === SPECIALS_LEGACY_BANK && fighterMoveLegacyAtlases[cut.fighterId] ? SPECIALS_LEGACY_BANK
      : cut.poseBank === "specials" && fighterMoveAtlases[cut.fighterId] ? "specials" : "base";
  const sdAtlas = bank === "specials" ? fighterMoveAtlases[cut.fighterId]
    : bank === SPECIALS_LEGACY_BANK ? fighterMoveLegacyAtlases[cut.fighterId]
      : bank === "motion" ? fighterMotionAtlases[cut.fighterId] : fighterAtlases[cut.fighterId];
  if (!sdAtlas?.complete || !sdAtlas.naturalWidth) return null;
  // 2.7 critic round: only warm HD sheets that exist (hdSheetPath returns
  // null for absent fighters/banks — devil, commissioner-specials).
  const hdPath = bank === "motion" ? null : hdSheetPath(cut.fighterId, bank);
  if (hdPath && !superPortraitHdImages.has(hdPath)) {
    const img = new Image();
    img.src = hdPath; // warm in the fighter layer's HTTP cache; SD fallback
    superPortraitHdImages.set(hdPath, img);
  }
  const hd = hdPath ? superPortraitHdImages.get(hdPath) : null;
  const atlas = hd?.complete && hd.naturalWidth ? hd : sdAtlas;
  const key = `${cut.fighterId}:${bank}:${cut.poseFrame}:${atlas === hd ? "hd" : "sd"}`;
  if (superPortraitCache.has(key)) return superPortraitCache.get(key);
  const cellW = atlas.naturalWidth / 4;
  const cellH = atlas.naturalHeight / 4;
  const crop = 0.68; // head + torso + raised fists: the wind-up close-up
  const sx = (cut.poseFrame % 4) * cellW;
  const sy = Math.floor(cut.poseFrame / 4) * cellH;
  const sh = cellH * crop;
  const canvas = document.createElement("canvas");
  canvas.height = 584; // ~2x the on-screen portrait height
  canvas.width = Math.round(584 * (cellW / sh));
  const pctx = canvas.getContext("2d");
  // Tinted stamp helper: the frame silhouette filled with one colour.
  const stamp = document.createElement("canvas");
  stamp.width = canvas.width;
  stamp.height = canvas.height;
  const stampCtx = stamp.getContext("2d");
  const drawFrame = (target) => target.drawImage(atlas, sx, sy, cellW, sh, 0, 0, canvas.width, canvas.height);
  const tinted = (color) => {
    stampCtx.clearRect(0, 0, stamp.width, stamp.height);
    drawFrame(stampCtx);
    stampCtx.globalCompositeOperation = "source-in";
    stampCtx.fillStyle = color;
    stampCtx.fillRect(0, 0, stamp.width, stamp.height);
    stampCtx.globalCompositeOperation = "source-over";
    return stamp;
  };
  // Accent back-rim (down-right) then white key rim (up-left) under the real
  // frame. The rim stamps are BLURRED (critic fix 7): the raw NN-scaled alpha
  // printed a jaggy white staircase matte around the portrait — softened
  // here, the sharp art on top still owns the silhouette.
  pctx.filter = "blur(2.4px)";
  pctx.drawImage(tinted(cut.accent), 9, 7);
  pctx.filter = "blur(1.5px)";
  pctx.drawImage(tinted("rgba(255,255,255,0.95)"), -7, -6);
  pctx.drawImage(tinted("rgba(255,255,255,0.95)"), -3, -3);
  pctx.filter = "contrast(1.14) saturate(1.12)";
  drawFrame(pctx);
  pctx.filter = "none";
  superPortraitCache.set(key, canvas);
  return canvas;
}

// Limb-following super-freeze energy arcs (critic fix 7): jagged bolts that
// START at one emitter (the wind-up's chest/fist zone) and WALK the body —
// each step stays inside the portrait's alpha, hugging the silhouette, so the
// energy traces arms and shoulders instead of scribbling randomly. Two seeded
// variants per portrait, cached; the cut-in flickers between them.
const superArcCache = new Map();
function superPortraitArcs(portrait, accent, variant) {
  const key = `${portrait.width}x${portrait.height}:${accent}:${variant}`;
  if (superArcCache.has(key)) return superArcCache.get(key);
  const w = portrait.width;
  const h = portrait.height;
  const scratch = document.createElement("canvas");
  scratch.width = w;
  scratch.height = h;
  const sctx = scratch.getContext("2d", { willReadFrequently: true });
  sctx.drawImage(portrait, 0, 0);
  const alphaData = sctx.getImageData(0, 0, w, h).data;
  const solid = (x, y) => {
    if (x < 2 || y < 2 || x >= w - 2 || y >= h - 2) return false;
    return alphaData[(Math.round(y) * w + Math.round(x)) * 4 + 3] > 90;
  };
  const canvasOut = document.createElement("canvas");
  canvasOut.width = w;
  canvasOut.height = h;
  const octx = canvasOut.getContext("2d");
  const hash = (n) => {
    const s = Math.sin(n * 127.1 + 311.7 + variant * 53.7) * 43758.5453;
    return s - Math.floor(s);
  };
  // emitter: chest/lead-fist zone of the wind-up crop
  const ex = w * 0.52;
  const ey = h * 0.46;
  octx.lineCap = "round";
  octx.lineJoin = "round";
  for (let arc = 0; arc < 6; arc += 1) {
    let x = ex + (hash(arc * 9 + 1) - 0.5) * w * 0.08;
    let y = ey + (hash(arc * 9 + 2) - 0.5) * h * 0.06;
    let angle = hash(arc * 9 + 3) * Math.PI * 2;
    const points = [[x, y]];
    const step = Math.max(6, w * 0.028);
    for (let s = 0; s < 26; s += 1) {
      angle += (hash(arc * 31 + s) - 0.5) * 1.1;
      let nx = x + Math.cos(angle) * step;
      let ny = y + Math.sin(angle) * step;
      if (!solid(nx, ny)) {
        // hug the silhouette: try tangential turns before giving up — this is
        // what makes the bolt FOLLOW an arm instead of flying off it
        let turned = false;
        for (const dTurn of [0.7, -0.7, 1.3, -1.3, 2.0, -2.0]) {
          const tx = x + Math.cos(angle + dTurn) * step;
          const ty = y + Math.sin(angle + dTurn) * step;
          if (solid(tx, ty)) {
            angle += dTurn;
            nx = tx;
            ny = ty;
            turned = true;
            break;
          }
        }
        if (!turned) break;
      }
      x = nx;
      y = ny;
      points.push([x, y]);
    }
    if (points.length < 5) continue;
    // BLANKA-GRAMMAR BOLT (round-3, critic item 6): drawn segment-by-segment
    // with real WIDTH VARIATION — a fat rooted trunk tapering to a whipped
    // point, jittered per step — in three passes: a soft orange falloff glow,
    // a hot amber body, and a thin WHITE-HOT core. No more uniform noodle.
    const jittered = points.map((pt, p) => [
      pt[0] + (hash(p * 7 + arc) - 0.5) * 3,
      pt[1] + (hash(p * 11 + arc) - 0.5) * 3,
    ]);
    const drawBolt = (pts, rootWidth, seedBase) => {
      const segs = pts.length - 1;
      for (let p = 0; p < segs; p += 1) {
        const t = p / Math.max(1, segs - 1);
        // taper root -> tip with per-segment crackle so no two widths match
        const wSeg = Math.max(0.7, rootWidth * (1 - t * 0.78) * (0.62 + hash(seedBase + p * 13) * 0.76));
        const seg = () => {
          octx.beginPath();
          octx.moveTo(pts[p][0], pts[p][1]);
          octx.lineTo(pts[p + 1][0], pts[p + 1][1]);
          octx.stroke();
        };
        // orange falloff glow
        octx.globalAlpha = 0.3 * (1 - t * 0.4);
        octx.strokeStyle = "rgba(255,118,20,1)";
        octx.lineWidth = wSeg * 3.1;
        seg();
        // hot amber body
        octx.globalAlpha = 0.82;
        octx.strokeStyle = "rgba(255,178,58,1)";
        octx.lineWidth = wSeg;
        seg();
        // white-hot core
        octx.globalAlpha = 0.95;
        octx.strokeStyle = "rgba(255,250,238,1)";
        octx.lineWidth = Math.max(0.6, wSeg * 0.34);
        seg();
      }
    };
    drawBolt(jittered, Math.max(3.4, w * 0.016), arc * 101);
    // BRANCHES: 2 true forks walked off mid points with their own taper —
    // branching is what separates lightning from scribble.
    for (let br = 0; br < 2; br += 1) {
      const rootIndex = Math.floor(jittered.length * (0.3 + hash(arc * 17 + br * 29) * 0.45));
      const root = jittered[rootIndex];
      if (!root) continue;
      let bx = root[0];
      let by = root[1];
      let bAngle = hash(arc * 23 + br * 31) * Math.PI * 2;
      const branchPts = [[bx, by]];
      const bStep = Math.max(4.5, w * 0.02);
      for (let s = 0; s < 7; s += 1) {
        bAngle += (hash(arc * 41 + br * 7 + s) - 0.5) * 1.3;
        let nx = bx + Math.cos(bAngle) * bStep;
        let ny = by + Math.sin(bAngle) * bStep;
        if (!solid(nx, ny)) {
          let turned = false;
          for (const dTurn of [0.8, -0.8, 1.5, -1.5]) {
            const tx = bx + Math.cos(bAngle + dTurn) * bStep;
            const ty = by + Math.sin(bAngle + dTurn) * bStep;
            if (solid(tx, ty)) { bAngle += dTurn; nx = tx; ny = ty; turned = true; break; }
          }
          if (!turned) break;
        }
        bx = nx;
        by = ny;
        branchPts.push([bx, by]);
      }
      if (branchPts.length >= 3) drawBolt(branchPts, Math.max(1.8, w * 0.008), arc * 211 + br * 57);
    }
  }
  // hot emitter knot where every bolt roots
  const knot = octx.createRadialGradient(ex, ey, 2, ex, ey, w * 0.075);
  knot.addColorStop(0, "rgba(255,248,235,0.95)");
  knot.addColorStop(0.4, `${accent}aa`);
  knot.addColorStop(1, "rgba(0,0,0,0)");
  octx.globalAlpha = 1;
  octx.fillStyle = knot;
  octx.fillRect(ex - w * 0.075, ey - w * 0.075, w * 0.15, w * 0.15);
  superArcCache.set(key, canvasOut);
  return canvasOut;
}

function latchSuperPresentation(fighter) {
  if (rollbackResimulating || superCutInTick === state.simulationTick) return;
  superCutInTick = state.simulationTick;
  // poseBank/poseFrame capture the live wind-up pose for the CINEMA 3D
  // close-up portrait; plain data, unread by the classic 2D banner path.
  const pose = fighterAnimationPose(fighter);
  superCutIn = {
    side: fighter.side,
    fighterId: fighter.def.id,
    name: fighter.def.name,
    accent: fighter.def.accent,
    color: fighter.def.color,
    poseBank: pose.bank,
    poseFrame: pose.frame,
    t: 0,
  };
  hudFxDebug.superCutIns += 1;
  latchDistortionRing(fighter.x, fighter.y - fighter.height * 0.6);
  if (state.performance.shadows && !state.accessibility.reducedMotion) {
    aberrationImpulse = Math.max(aberrationImpulse, 0.7);
  }
}

function latchFatalImpactPresentation(x, y) {
  if (rollbackResimulating) return;
  latchDistortionRing(x, y);
  if (state.performance.shadows && !state.accessibility.reducedMotion) {
    aberrationImpulse = Math.max(aberrationImpulse, 1);
  }
}

function drawSuperCutIn(dtMs) {
  if (!superCutIn) return;
  if (state.screen !== "fight") {
    superCutIn = null;
    return;
  }
  const cut = superCutIn;
  cut.t += dtMs / 1000;
  if (cut.t >= SUPER_CUT_IN_SECONDS) {
    superCutIn = null;
    return;
  }
  const reduced = state.accessibility.reducedMotion;
  const progress = clamp(cut.t / SUPER_CUT_IN_SECONDS, 0, 1);
  const alpha = Math.min(clamp(progress / 0.07, 0, 1), clamp((1 - progress) / 0.16, 0, 1));
  const fromLeft = cut.side === 0;
  // CINEMA 3D banner treatment (halftone band, textured type, portrait punch)
  // only fires over the 3D world; the classic 2D banner is untouched.
  const in3d = cinema3dWorldActive();
  // Band held to the upper-middle third: clear of the HUD and low enough to
  // frame the portrait without burying the fighters for its 0.7s life.
  const bandTop = H * 0.19;
  const bandBottom = H * 0.46;
  const tilt = 32;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-60, bandTop + tilt);
  ctx.lineTo(W + 60, bandTop - tilt);
  ctx.lineTo(W + 60, bandBottom - tilt);
  ctx.lineTo(-60, bandBottom + tilt);
  ctx.closePath();
  ctx.clip();
  // Near-opaque dark core with a hard accent wash so the portrait pops on any
  // stage and the band reads as a cut-in, not a tint.
  ctx.globalAlpha = alpha;
  ctx.fillStyle = "rgba(5,7,13,0.93)";
  ctx.fillRect(0, bandTop - tilt, W, bandBottom - bandTop + tilt * 2);
  const wash = ctx.createLinearGradient(fromLeft ? 0 : W, 0, fromLeft ? W : 0, 0);
  wash.addColorStop(0, `${cut.accent}e6`);
  wash.addColorStop(0.4, `${cut.color}55`);
  wash.addColorStop(1, "rgba(8,10,18,0)");
  ctx.fillStyle = wash;
  ctx.fillRect(0, bandTop - tilt, W, bandBottom - bandTop + tilt * 2);
  if (in3d) {
    // Print texture INTO the accent band: a drifting halftone dot screen in
    // the wash's own shadow tone plus raking brush streaks, so the slash
    // reads as inked print, not a flat gradient.
    const { halftone, brush } = cutInPatterns();
    ctx.save();
    ctx.globalAlpha = alpha * 0.5;
    ctx.globalCompositeOperation = "multiply";
    const dotPattern = ctx.createPattern(halftone, "repeat");
    dotPattern.setTransform(CUT_IN_PATTERN_SCALE);
    ctx.translate((fromLeft ? -1 : 1) * cut.t * 160, 0);
    ctx.fillStyle = dotPattern;
    ctx.fillRect(-W, bandTop - tilt, W * 3, bandBottom - bandTop + tilt * 2);
    ctx.restore();
    ctx.save();
    ctx.globalAlpha = alpha * 0.55;
    ctx.globalCompositeOperation = "overlay";
    const brushPattern = ctx.createPattern(brush, "repeat");
    brushPattern.setTransform(CUT_IN_PATTERN_SCALE);
    ctx.translate((fromLeft ? 1 : -1) * cut.t * 420, 0);
    ctx.fillStyle = brushPattern;
    ctx.fillRect(-W, bandTop - tilt, W * 3, bandBottom - bandTop + tilt * 2);
    ctx.restore();
  }
  // Speed lines streak against the sweep (skipped under reduced motion).
  if (!reduced) {
    ctx.globalCompositeOperation = "lighter";
    for (let index = 0; index < 11; index += 1) {
      const seed = Math.sin((index + 1) * 12.9898) * 43758.5453;
      const jitter = seed - Math.floor(seed);
      const lineY = bandTop + 10 + jitter * (bandBottom - bandTop - 20);
      const speed = (1100 + jitter * 1100) * (fromLeft ? 1 : -1);
      const span = W + 700;
      let lineX = (fromLeft ? -350 : W + 350) + speed * cut.t * 1.7;
      // Wrap so the streaks keep flowing for the whole 0.7s hold.
      lineX = fromLeft ? ((lineX + 350) % span) - 350 : ((lineX - W - 350) % span) + W + 350;
      ctx.globalAlpha = alpha * (0.3 + jitter * 0.34);
      ctx.fillStyle = index % 3 === 0 ? cut.accent : "#eef4ff";
      ctx.fillRect(lineX, lineY, (150 + jitter * 240) * (fromLeft ? 1 : -1), 2.5 + jitter * 2.5);
    }
    ctx.globalCompositeOperation = "source-over";
  }
  // Portrait slam: eased slide toward centre (static under reduced motion),
  // riding an accent glow pool so the cutout art separates from the band.
  // CINEMA 3D uses the dedicated 2x wind-up close-up (superPortrait3d) with a
  // speed-line burst behind it; the 2D roster-art path is byte-for-byte
  // unchanged.
  const image = fighterImages[cut.fighterId];
  const closeUp = in3d ? superPortrait3d(cut) : null;
  // 3D deliberate band break (round-3, critic item 6): the portrait's head +
  // shoulders COMMIT past the band's top edge instead of grazing it — drawn
  // after the clip ends, through a top-open window bounded at the band's
  // bottom edge. Geometry is computed here; the actual punch draw happens
  // post-restore so the edge stroke passes BEHIND the figure.
  let breakDraw = null;
  if (closeUp || (image?.complete && image.naturalWidth > 0)) {
    const bustFraction = 0.46; // top of the roster art: head + torso
    const sourceHeight = in3d ? (image?.naturalHeight ?? 1) * bustFraction : image?.naturalHeight ?? 1;
    const portraitHeight = (bandBottom - bandTop) * (closeUp ? 1.46 : in3d ? 1.18 : 2.15);
    const portraitWidth = portraitHeight * (closeUp
      ? closeUp.width / closeUp.height
      : (image?.naturalWidth ?? 1) / sourceHeight);
    const slide = reduced ? 1 : 1 - (1 - clamp(progress / 0.34, 0, 1)) ** 3;
    const targetX = W * 0.5 - portraitWidth * 0.5;
    const startX = fromLeft ? -portraitWidth - 80 : W + 80;
    const portraitX = lerp(startX, targetX, slide)
      + (reduced ? 0 : (fromLeft ? 1 : -1) * (1 - progress) * 30);
    const glowX = portraitX + portraitWidth * 0.5;
    const glowY = (bandTop + bandBottom) * 0.5;
    const glow = ctx.createRadialGradient(glowX, glowY, 12, glowX, glowY, portraitHeight * 0.52);
    glow.addColorStop(0, `${cut.accent}b4`);
    glow.addColorStop(1, "rgba(0,0,0,0)");
    ctx.globalAlpha = alpha;
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = glow;
    ctx.fillRect(0, bandTop - tilt, W, bandBottom - bandTop + tilt * 2);
    ctx.globalCompositeOperation = "source-over";
    if (in3d && closeUp && !reduced) {
      // SPEED-LINE BURST behind the close-up: comic rays converging on the
      // portrait, wound slightly by the band's life (SF6 cut-in energy).
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.lineCap = "round";
      for (let ray = 0; ray < 22; ray += 1) {
        const seed = Math.sin((ray + 5) * 78.233) * 43758.5453;
        const jitter = seed - Math.floor(seed);
        const angle = (ray / 22) * Math.PI * 2 + jitter * 0.4 + cut.t * 0.5;
        const outer = portraitHeight * (0.85 + jitter * 0.7);
        const inner = portraitHeight * (0.34 + jitter * 0.16);
        ctx.globalAlpha = alpha * (0.16 + jitter * 0.3);
        ctx.strokeStyle = ray % 3 === 0 ? cut.accent : "#fff6e6";
        ctx.lineWidth = 1.5 + jitter * 3.5;
        ctx.beginPath();
        ctx.moveTo(glowX + Math.cos(angle) * outer, glowY + Math.sin(angle) * outer);
        ctx.lineTo(glowX + Math.cos(angle) * inner, glowY + Math.sin(angle) * inner);
        ctx.stroke();
      }
      ctx.restore();
      ctx.globalAlpha = alpha;
    }
    if (in3d) {
      // Portrait PUNCH geometry: slams in oversized and slightly rolled,
      // easing to rest over the first quarter of the band's life. Anchored
      // HIGH: the crown clears the band's top edge by a committed margin.
      const punch = reduced ? 1 : clamp(progress / 0.24, 0, 1);
      const punchEase = 1 - (1 - punch) ** 3;
      const punchScale = 1.22 - punchEase * 0.22;
      const punchRot = (fromLeft ? -1 : 1) * (1 - punchEase) * 0.09 - 0.025;
      const pcx = portraitX + portraitWidth * 0.5;
      const pcy = bandTop - 20 + portraitHeight * 0.5;
      breakDraw = () => {
        ctx.save();
        // Top-open window: free above, cut at the band's bottom edge so the
        // torso still exits INTO the band (a raw crop line never shows).
        ctx.beginPath();
        ctx.moveTo(-60, -H);
        ctx.lineTo(W + 60, -H);
        ctx.lineTo(W + 60, bandBottom - tilt);
        ctx.lineTo(-60, bandBottom + tilt);
        ctx.closePath();
        ctx.clip();
        ctx.globalAlpha = alpha;
        ctx.translate(pcx, pcy);
        ctx.rotate(punchRot);
        ctx.scale(punchScale, punchScale);
        if (closeUp) {
          // Mirror the P2 close-up so the wind-up drives INTO the frame.
          if (!fromLeft) ctx.scale(-1, 1);
          ctx.drawImage(closeUp, -portraitWidth * 0.5, -portraitHeight * 0.5, portraitWidth, portraitHeight);
          // Limb-following energy bolts from the chest emitter, flickering
          // between two seeded variants over the band's life.
          if (!reduced) {
            const arcs = superPortraitArcs(closeUp, cut.accent, Math.floor(cut.t * 21) % 2);
            ctx.save();
            ctx.globalCompositeOperation = "lighter";
            ctx.globalAlpha = alpha * (0.75 + 0.25 * Math.sin(cut.t * 47));
            ctx.drawImage(arcs, -portraitWidth * 0.5, -portraitHeight * 0.5, portraitWidth, portraitHeight);
            ctx.restore();
          }
        } else {
          ctx.drawImage(
            image, 0, 0, image.naturalWidth, sourceHeight,
            -portraitWidth * 0.5, -portraitHeight * 0.5, portraitWidth, portraitHeight,
          );
        }
        ctx.restore();
      };
    } else {
      ctx.drawImage(image, portraitX, bandTop - portraitHeight * 0.24, portraitWidth, portraitHeight);
    }
  }
  // Name plate riding the band's lower edge.
  ctx.globalAlpha = alpha;
  ctx.textAlign = fromLeft ? "right" : "left";
  ctx.textBaseline = "alphabetic";
  const nameX = fromLeft ? W - 54 : 54;
  if (in3d) {
    // Textured display type: skewed heavy caps punched in with the portrait,
    // hot accent under-stroke offset like misregistered ink, gradient fill,
    // halftone screen INSIDE the letterforms and a hard black contour.
    const namePunch = reduced ? 1 : clamp((progress - 0.04) / 0.2, 0, 1);
    const nameEase = 1 - (1 - namePunch) ** 3;
    const nameY = bandBottom - 16;
    ctx.save();
    ctx.translate(nameX, nameY);
    ctx.transform(1, 0, -0.24, 1, 0, 0); // slam-forward skew
    ctx.scale(1 + (1 - nameEase) * 0.35, 1 + (1 - nameEase) * 0.35);
    ctx.globalAlpha = alpha * (0.25 + nameEase * 0.75);
    ctx.font = "1000 58px Arial Narrow, Impact, sans-serif";
    // Misregistered accent pass first (offset down-right).
    ctx.fillStyle = cut.accent;
    ctx.fillText(cut.name, 4, 4);
    // Hard contour.
    ctx.lineJoin = "round";
    ctx.lineWidth = 9;
    ctx.strokeStyle = "rgba(3,4,8,.95)";
    ctx.strokeText(cut.name, 0, 0);
    // Gradient body: hot top light falling to steel.
    const nameGrad = ctx.createLinearGradient(0, -48, 0, 6);
    nameGrad.addColorStop(0, "#ffffff");
    nameGrad.addColorStop(0.52, "#f2f5ff");
    nameGrad.addColorStop(0.56, "#c9d2e8");
    nameGrad.addColorStop(1, "#9aa6c4");
    ctx.fillStyle = nameGrad;
    ctx.fillText(cut.name, 0, 0);
    // Halftone screen inside the letterforms only.
    const { halftone } = cutInPatterns();
    ctx.globalAlpha = alpha * 0.3;
    ctx.fillStyle = ctx.createPattern(halftone, "repeat");
    ctx.fillText(cut.name, 0, 0);
    ctx.restore();
  } else {
    ctx.font = "italic 1000 44px Arial Narrow, Impact, sans-serif";
    ctx.lineWidth = 7;
    ctx.strokeStyle = "rgba(0,0,0,.92)";
    ctx.fillStyle = "#f4f7ff";
    ctx.strokeText(cut.name, nameX, bandBottom - 18);
    ctx.fillText(cut.name, nameX, bandBottom - 18);
  }
  ctx.restore();
  // Band edge strokes drawn unclipped so they stay crisp — BEFORE the 3D
  // portrait break, so the top edge line passes BEHIND the figure and the
  // crown reads as a designed break, not a graze.
  ctx.save();
  ctx.globalAlpha = alpha * 0.95;
  ctx.strokeStyle = cut.accent;
  ctx.lineWidth = 3.5;
  ctx.beginPath();
  ctx.moveTo(-60, bandTop + tilt);
  ctx.lineTo(W + 60, bandTop - tilt);
  ctx.moveTo(-60, bandBottom + tilt);
  ctx.lineTo(W + 60, bandBottom - tilt);
  ctx.stroke();
  ctx.restore();
  // 3D-only: the committed band break (no-op in 2D — breakDraw stays null).
  if (breakDraw) {
    ctx.save();
    breakDraw();
    ctx.restore();
  }
}

function draw(time) {
  // Wave 5 HUD observers: phase-edge slash wipe and the hold-then-drain
  // damage ghosts, both driven from observed state in the render loop.
  const hudDtMs = clamp(time - hudFxLastTime, 0, 100) || 16.7;
  hudFxLastTime = time;
  observeFightPhaseWipes();
  updateDamageGhosts(hudDtMs);
  // Wave 6 cinematic camera: observe state and ease the presentation camera
  // before the world transform is built. Runs unconditionally so the camera
  // hard-resets to identity the moment the fight screen goes away.
  updateCinematicCamera(hudDtMs);
  // Release 1.6 LOUD: ease the render-side audio buses (crowd bed, music
  // intensity routing, stage ambience) from observed state. Unconditional so
  // every bed settles/tears down the moment the fight screen goes away.
  updateAudioPresentation(time, hudDtMs);
  // v2.6 MOTION: observe landings/skids/dash starts/hitstun edges and pace
  // the squash/wobble/crossfade counters BEFORE either renderer consumes the
  // shared motion transforms (the 3D renderFrame below reads the same layer).
  updateMotionObservers();
  // v2.6 ELEMENTS: observe special-attack phases (charge/active/release) and
  // integrate the flipbook sprite pool before either renderer draws.
  updateElementalVfx(time);
  // Wave 7 DPR-sharp baseline: all logical-coordinate code below draws through
  // this transform; identity when sharp render is off (renderDpr === 1).
  ctx.setTransform(renderDpr, 0, 0, renderDpr, 0, 0);
  // CINEMA 3D: when the experimental Three.js world renderer is active it
  // draws the world on its own canvas UNDER this one; the 2D canvas is
  // cleared so only the screen-space overlay passes composite on top. When
  // inactive this is a no-op and the 2D path below is untouched.
  const cinema3dWorld = cinema3dWorldActive();
  cinema3dBridge.renderer?.setVisible(cinema3dWorld);
  if (cinema3dWorld) {
    cinema3dBridge.renderer.renderFrame(time, hudDtMs);
    ctx.clearRect(0, 0, W, H);
  }
  // MOTION FIX 12: apex clipping — CINEMA 3D's tighter framing sends a jump
  // apex behind the top HUD band. While any fighter's head projects up into
  // the band, the DOM HUD eases down to ~30% opacity and eases back after,
  // so the flip reads through the chrome instead of being guillotined.
  updateCinema3dHudFade(cinema3dWorld, hudDtMs);
  ctx.save();
  const shakeScale = state.accessibility.reducedMotion ? 0 : state.accessibility.shakeScale;
  const shakeX = state.shake > 0 ? Math.sin((state.simulationTick + 1) * 12.9898) * state.shake * 9 * shakeScale : 0;
  const shakeY = state.shake > 0 ? Math.cos((state.simulationTick + 1) * 7.233) * state.shake * 6 * shakeScale : 0;
  // Recoil/handheld offsets ride beside the existing noise shake translate.
  ctx.translate(shakeX + cinematicCamera.x, shakeY + cinematicCamera.y);
  // 4.3 DEMO PULL-BACK (2D path): the attract demo is watched from the
  // couch, so the whole world draws at DEMO_PULLBACK_ZOOM about the floor
  // centre — feet stay on the floor line, both fighters and their moves sit
  // well inside the frame. The unscaled stage is painted first so the
  // revealed margins continue the backdrop instead of showing black.
  // Presentation-only: nothing here touches the sim.
  const demoPullback = state.mode === "demo" && state.screen === "fight" && !state.finisher && !cinema3dWorld;
  if (demoPullback) {
    drawStage(time);
    ctx.translate(W * .5, FLOOR);
    ctx.scale(DEMO_PULLBACK_ZOOM, DEMO_PULLBACK_ZOOM);
    ctx.translate(-W * .5, -FLOOR);
  }
  if (state.finisher) {
    const camera = finisherCameraTarget();
    ctx.translate(W * .5, H * .53);
    // Fatality dutch tilt rolls the scripted cinematic about screen centre.
    if (cinematicCamera.rotation !== 0) ctx.rotate(cinematicCamera.rotation);
    ctx.scale(state.cinematicZoom, state.cinematicZoom);
    ctx.translate(-camera.x, -camera.y);
  } else if (cinematicCamera.zoom !== 1 || cinematicCamera.rotation !== 0) {
    // Presentation-only zoom punch/dolly about its focus point. Zoom is always
    // >= 1 and the focus stays inside the frame, so the world always covers
    // the canvas; identity (the normal-play state) skips this entirely.
    ctx.translate(cinematicCamera.focusX, cinematicCamera.focusY);
    if (cinematicCamera.rotation !== 0) ctx.rotate(cinematicCamera.rotation);
    ctx.scale(cinematicCamera.zoom, cinematicCamera.zoom);
    ctx.translate(-cinematicCamera.focusX, -cinematicCamera.focusY);
  }
  // Counters reset before drawStage so the stage-level passes (weather,
  // practicals, flashbulbs, occluders) count into the same rendered frame.
  // Unconditional: drawStage runs on every screen, so a gated reset would let
  // the stage counters accumulate without bound outside the fight.
  for (const key of Object.keys(presentationDebug)) {
    // lastFighterMirror and lastWalkKey are LATCHES, not counters: they hold
    // the most recent per-side sprite mirror / walk-cycle key index for the QA
    // probes rather than a per-frame tally, so the counter reset must leave
    // them alone (zeroing lastWalkKey would also swap an array for a number
    // and break the probe's slice()). motion2CellDraws is a CUMULATIVE tally
    // for the same reason and more sharply: zeroing it swaps the map for a
    // number, and the very next per-cell write would throw in module strict
    // mode and take the whole draw pass down with it.
    if (key === "lastFighterMirror" || key === "lastWalkKey"
      || key === "motion2CellDraws"
      // v2.9 final round: cumulative session tallies, not per-frame counts.
      || key === "reactionDrawPriority" || key === "turnaroundDraws"
      || key === "turnaroundBlocked") continue;
    presentationDebug[key] = 0;
  }
  if (state.screen === "fight") {
    gritFlareLevel[0] = Math.max(0, gritFlareLevel[0] - 0.05);
    gritFlareLevel[1] = Math.max(0, gritFlareLevel[1] - 0.05);
  }
  if (!cinema3dWorld) {
    drawStage(time);
    if (state.screen === "fight") {
      drawWallsplatEdgeCover();
      drawSuperSpotlight();
      drawWinPoseSpotlight();
      drawFatalitySpotlight();
      drawSuperFocusLines(time);
      drawFighterCastShadows();
      drawFighterReflections(time);
      drawPaintTraps(time);
      drawStageWeapon(time);
      drawProjectiles(time);
      drawAfterimages();
      const ordered = [...state.fighters].sort((a, b) => a.y - b.y);
      // v2.9 FLOW (2.7 critic J2): during the attacker's 1-2-tick smear /
      // final charge-flash frames the attacker draws LAST — from the P1 seat
      // those flash cells were drawing behind the opponent and getting
      // occluded at the exact moment they exist to be seen. Scoped strictly
      // to the flash beats (attackMotionBeat is the same pure classifier the
      // pose functions use); no general pair-layering change.
      if (ordered.length === 2) {
        const flashIndex = ordered.findIndex((fighter) => {
          if (!fighter.attacking) return false;
          const beat = attackMotionBeat(fighter.attacking, fighter.attackFrame);
          return Boolean(beat && (beat.beat === "smear"
            || (beat.beat === "charge"
              && fighter.attackFrame >= fighter.attacking.activeStartFrame - 4)));
        });
        if (flashIndex === 0) ordered.push(ordered.shift());
        // v2.9 final round (R9) — THE P1-SEAT OCCLUSION.
        //
        // The sort above is `a.y - b.y`, and at point-blank range BOTH
        // fighters are standing on the floor line, so a.y === b.y and the sort
        // is a no-op: the array keeps its state.fighters order and SIDE 1
        // ALWAYS DRAWS LAST. From the P1 seat that means the attacker (side 0)
        // is behind the defender at a distance, but the attacker covers the
        // defender the moment the two overlap — which is exactly when the
        // defender's flinch exists to be read. Every reaction P1 lands is
        // partly hidden behind the fighter that caused it.
        //
        // The REACTING fighter takes draw priority for the length of the
        // reaction. Same mechanism and the same tight scoping as the flash
        // rule above: it applies only while a fighter is actually in hitstun,
        // blockstun or a knockdown, only when the OTHER fighter is not itself
        // reacting (a trade keeps the y sort), and only when the flash rule
        // has not already claimed the ordering — the attacker's own smear
        // frames still win, because those are the two ticks the flash rule
        // exists for.
        if (flashIndex < 0) {
          const reacting = (fighter) => fighter.hitstunFrames > 0 || fighter.blockstunFrames > 0
            || fighter.knockdownFrames > 0 || fighter.down;
          const reactIndex = ordered.findIndex(reacting);
          if (reactIndex === 0 && !reacting(ordered[1])) {
            ordered.push(ordered.shift());
            presentationDebug.reactionDrawPriority += 1;
          }
        }
      }
      ordered.forEach((fighter) => drawFighter(fighter, time));
      state.fighters.forEach((fighter) => drawDizzyStars(fighter, time));
      state.fighters.forEach((fighter) => drawGuardCrushMarker(fighter, time));
      drawParticles();
      drawElementalVfx();
      drawForegroundOccluders(state.fighters.length
        ? (state.fighters[0].x + state.fighters[1].x) * 0.5 : W * 0.5);
    }
  }
  // Wave 7: capture the live world transform so the screen-space distortion
  // ring can project its world-space origin after the restore.
  if (distortionRing) worldScreenTransform = ctx.getTransform();
  ctx.restore();
  // CINEMA 3D gameplay reads: the pure-2D screen art the world pass above
  // skipped (dizzy / guard-crush markers with their drain bars, Ali's rhythm
  // rings, combat text, the stage-weapon name tag) drawn at the projected sim
  // points on the overlay canvas — exactly the CRT-punch pattern.
  if (cinema3dWorld && state.screen === "fight") drawCinema3dOverlayReads(time);
  // CINEMA 3D handles grade/bloom/grain in its own post stack; the 2D
  // frame-capture composites would smear a transparent canvas, so they are
  // skipped while the 3D world is live. UI-readability overlays (letterbox,
  // cut-ins, flash, CRT, debug) still draw on top either way.
  if (!cinema3dWorld) {
    drawStageGrade();
    drawFinisherRealityComposite();
    // Wave 7 screen-space composite passes, in order: slow-mo smear first, then
    // the frame capture (so the smear recursively accumulates but bloom can
    // never feed back into itself), then bloom and the one-shot warps.
    updateSlowMoBlur();
    requestFrameCapture();
    drawBloomComposite();
    drawDistortionRing(hudDtMs);
    drawChromaticAberration();
  }
  drawIntroLetterbox();
  drawElementalWash();
  drawFinisherOverlay();
  if (state.flash > 0) {
// CINEMA 3D carries its own layered impact flash (hit-masked white pop,
    // shockwave ring, embers in the world), so the screen wash is nearly off
    // there. The 2D path keeps the 1.9E cap: at 0.9 the flash erased the
    // whole frame on every multi-hit; supers and finishers still reach it.
    const flashAlpha = cinema3dWorld
      ? clamp(state.flash * 0.4, 0, 0.08)
      : clamp(state.flash * 3, 0, 0.5);
    ctx.fillStyle = `rgba(255,245,220,${flashAlpha})`;
    ctx.fillRect(0, 0, W, H);
  }
  drawSuperCutIn(hudDtMs);
  drawCrtOverlay(time);
  // `time` is the RAF timestamp in ms, the same origin performance.now() uses.
  drawDemoSpeedHud(time);
  drawDebugOverlay();
  drawTrainingFrameMeter();
}

// ---------------------------------------------------------------------------
// v3.2 — the transport readout. A persistent rate chip (so the owner
// always knows what he is looking at) plus a key legend that shows itself for
// nine seconds whenever the transport is armed or touched, then gets out of
// the way. Screen space, after the world restore, top-left — clear of both
// fighters and of the health bars.
// ---------------------------------------------------------------------------
function drawDemoSpeedHud(nowMs) {
  if (!demoSpeedScoped()) return;
  const rateLabel = demoSpeed.paused ? "PAUSED" : `${demoSpeed.rate}x`;
  const accent = demoSpeed.paused ? "#ffb347" : demoSpeed.rate === 1 ? "#4eddf5" : "#8affc1";
  const originX = 26;
  const originY = 122;
  ctx.save();
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.font = "900 20px ui-monospace, monospace";
  const head = `DEMO SPEED · ${rateLabel}`;
  const headWidth = ctx.measureText(head).width + 24;
  ctx.fillStyle = "rgba(4,9,14,.78)";
  ctx.fillRect(originX, originY - 16, headWidth, 32);
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.strokeRect(originX, originY - 16, headWidth, 32);
  ctx.fillStyle = accent;
  ctx.fillText(head, originX + 12, originY + 1);
  if (nowMs < demoSpeed.hintUntilMs) {
    // The legend lives BELOW THE FLOOR LINE, not under the chip: down here it
    // is over the reflection band, clear of both fighters entirely, and it
    // hides itself after nine seconds anyway. Armed on every demo start (see
    // startDemo) and re-armed by any transport key, so the controls announce
    // themselves once and then stay out of the way.
    ctx.font = "900 14px ui-monospace, monospace";
    const lines = [
      `[  ]  RATE  ${DEMO_SPEED_RATES.join(" / ")}      1 2 3 4  DIRECT`,
      "\\ or SPACE  PAUSE      .  STEP ONE FRAME",
      "any other key  EXIT",
    ];
    const width = Math.max(...lines.map((line) => ctx.measureText(line).width)) + 24;
    const legendY = H - 92;
    ctx.fillStyle = "rgba(4,9,14,.74)";
    ctx.fillRect(originX, legendY - 12, width, lines.length * 20 + 10);
    ctx.strokeStyle = "rgba(159,214,255,.45)";
    ctx.lineWidth = 1;
    ctx.strokeRect(originX, legendY - 12, width, lines.length * 20 + 10);
    ctx.fillStyle = "#9fd6ff";
    lines.forEach((line, index) => ctx.fillText(line, originX + 12, legendY + 2 + index * 20));
  }
  ctx.restore();
}

function clearLatchedInputEdges() {
  pressed.clear();
  for (const token of [...touch]) if (token.endsWith(":pressed")) touch.delete(token);
}

function runSimulationStep(dt, tick) {
  if (!(state.mode === "online" && onlineSession.rollback)) state.simulationTick = tick;
  // 5.x flick-to-dash: a queued flick plays its lift/tap/lift/tap on the
  // touch Set one real sim tick at a time, ahead of this tick's readInput.
  pumpTouchFlicks();
  simulateGameTick(dt);
}

function loop(now) {
  const elapsed = Math.max(0, (now - state.lastRenderTime) / 1000 || 0);
  state.lastRenderTime = now;
  // Wave 15: the adaptive governor watches real frame times (all gates,
  // including the online/forced-profile exclusions, live inside).
  feedPerformanceGovernor(elapsed * 1000);
  // v3.2 ADJUSTABLE DEMO SPEED. The rate scales the WALL-CLOCK
  // SECONDS handed to the fixed-step clock, never the step itself: the clock's
  // accumulator crosses `stepSeconds` proportionally less often and every tick
  // it does take still runs at exactly 1/60s, so the tick STREAM is identical
  // and only its cadence against the wall clock changes. That is why this can
  // never perturb physics, frame data or a checksum. See engine/demo-speed.mjs.
  // Demo/training only, never online, never while qa.step owns the clock.
  const speedScaled = demoSpeedActive();
  // Frame-step runs the SAME fixed step through the SAME driver — a single
  // tick, at 1/60s, on the rendered frame the viewer asked for it.
  const steppedFrames = speedScaled ? demoSpeed.takeFrameSteps() : 0;
  for (let index = 0; index < steppedFrames; index += 1) simulationClock.stepOnce(runSimulationStep);
  const simSeconds = speedScaled ? demoSpeed.scale(elapsed) : elapsed;
  // v5.1 #35: an intro art hold hands the clock zero seconds — no tick runs,
  // no accumulator builds, the tick stream resumes exactly where it stood.
  const artHeld = updateIntroArtHold(now);
  const frame = state.qaManualMode
    ? {
      steps: 0,
      tick: simulationClock.tick,
      alpha: state.simulationAlpha,
      droppedSeconds: simulationClock.droppedSeconds,
    }
    : simulationClock.advance(artHeld ? 0 : simSeconds, runSimulationStep);
  state.simulationTick = state.mode === "online" && onlineSession.rollback
    ? onlineSession.rollback.frame : frame.tick;
  state.simulationAlpha = frame.alpha;
  state.simulationSteps = frame.steps + steppedFrames;
  state.simulationDroppedSeconds = frame.droppedSeconds;
  if (frame.steps + steppedFrames > 0) clearLatchedInputEdges();
  draw(now);
  requestAnimationFrame(loop);
}

function musicBaseVolume() {
  return {
    title: 0.23,
    select: 0.27,
    stage: 0.28,
    fight: 0.34,
    result: 0.25,
  }[state.screen] || 0.25;
}

function updateMusicUi() {
  const select = $("#musicSelect");
  if (select) select.value = state.musicChoice;
  const button = $("#trackButton");
  if (button) button.textContent = `♫ ${state.musicChoice === "auto" ? "AUTO · " : ""}${musicTracks[currentTrackIndex].title}`;
}

function updateVolumeUi() {
  const musicSlider = $("#musicVolume");
  const sfxSlider = $("#sfxVolume");
  if (musicSlider) musicSlider.value = String(Math.round(state.musicVolume * 100));
  if (sfxSlider) sfxSlider.value = String(Math.round(state.sfxVolume * 100));
  if ($("#musicVolumeValue")) $("#musicVolumeValue").textContent = `${Math.round(state.musicVolume * 100)}%`;
  if ($("#sfxVolumeValue")) $("#sfxVolumeValue").textContent = `${Math.round(state.sfxVolume * 100)}%`;
}

function applyAccessibilitySettings() {
  document.body.classList.toggle("reduced-motion", state.accessibility.reducedMotion);
  document.body.classList.toggle("high-contrast", state.accessibility.highContrast);
  document.body.dataset.colorAssist = ["standard", "deuteranopia", "protanopia", "tritanopia"].includes(state.accessibility.colorAssist)
    ? state.accessibility.colorAssist : "standard";
  $("#reducedMotionToggle").checked = state.accessibility.reducedMotion;
  $("#highContrastToggle").checked = state.accessibility.highContrast;
  $("#colorAssistSelect").value = document.body.dataset.colorAssist;
  $("#shakeSelect").value = String(state.accessibility.shakeScale);
  applyPerformanceSettings();
}

// ---------------------------------------------------------------------------
// R1.9 wave 15: adaptive runtime performance governor (integration layer).
// The pure hysteresis machine lives in engine/polish.mjs; this layer feeds it
// real render-loop frame times and applies its tier decisions. Hard gates:
// only in AUTO quality (never fighting a user-forced profile), never during
// online matches (fixed presentation pacing for determinism of feel), never
// in CABINET MODE (which pins high), and only while a fight or demo is
// actually rendering. state.performance is render-only and un-checksummed,
// so every decision is rollback-safe by construction.
//
// 5.x memory (sweep #37): the machine used to be nulled the moment a screen
// other than fight/demo rendered, so every fight re-baselined at the static
// tier and a boundary phone stuttered through one 120-frame window (2 s) or
// two steps across a 360-frame cooldown (~8 s) before it landed where the
// previous fight had already landed. Now the machine is RETAINED across the
// result/select/title screens (frozen, not fed — a menu's frame times are not
// fight evidence either way), only dropped when a static gate closes (forced
// profile, cabinet, online), and the landed tier is written to localStorage
// keyed by build + device signature so the first fight of the next session
// starts there too. The seeded start is silent: no COOLING toast for a tier
// the player already lived through.
// ---------------------------------------------------------------------------
const performanceGovernor = { machine: null, steps: 0, lastChange: "", seededFrom: "", remembered: "" };
let governorToastTimer = 0;

// Static gates: closing any of these drops the machine (the old behaviour).
function governorAllowed() {
  return state.visualQuality === "auto"
    && !state.cabinetMode
    && state.mode !== "online";
}

// Feeding gate: the machine only observes frames while a fight or demo is
// actually rendering; elsewhere it is kept alive, untouched.
function governorEligible() {
  return governorAllowed()
    && !document.hidden
    && (state.screen === "fight" || demoSession.active);
}

function governorMemoryStorage() {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function governorMemoryContext() {
  const environment = performanceEnvironment(state.accessibility.reducedMotion);
  const baselineId = resolvePerformanceProfile("auto", environment).id;
  return {
    baselineId,
    key: governorMemoryKey(GAME_VERSION),
    signature: governorMemorySignature({
      userAgent: navigator.userAgent,
      hardwareConcurrency: environment.hardwareConcurrency,
      deviceMemory: environment.deviceMemory,
      baselineId,
    }),
  };
}

function rememberGovernorTier(profileId) {
  const memory = governorMemoryContext();
  performanceGovernor.remembered = writeGovernorMemory(governorMemoryStorage(), memory.key, {
    signature: memory.signature,
    profileId,
  }) ? profileId : "";
}

function createGovernorMachine() {
  const memory = governorMemoryContext();
  const remembered = readGovernorMemory(governorMemoryStorage(), memory.key, memory.signature);
  performanceGovernor.seededFrom = remembered ? "memory" : "static";
  performanceGovernor.remembered = remembered?.profileId || "";
  // createPerformanceGovernor clamps the seed to the baseline, so a stale
  // 'high' memory on a device whose static resolution says balanced is inert.
  return createPerformanceGovernor({
    profileId: remembered?.profileId || state.performance.id,
    baselineId: memory.baselineId,
  });
}

// One-line HUD toast on a tier change, on the sound-caption channel's element
// (same look, own timer) so it never fights an actual caption for long.
function governorToast(text) {
  const caption = $("#soundCaption");
  if (!caption) return;
  window.clearTimeout(governorToastTimer);
  window.clearTimeout(soundCaptionTimer);
  caption.textContent = `◀ ${text} ▶`;
  caption.hidden = false;
  governorToastTimer = window.setTimeout(() => { caption.hidden = true; }, 2400);
}

function applyGovernorChange(change) {
  if (!change) return;
  performanceGovernor.steps += 1;
  performanceGovernor.lastChange = `${change.action}:${change.from}->${change.to}`;
  applyPerformanceSettings();
  rememberGovernorTier(change.to);
  governorToast(change.action === "down"
    ? `AUTO PERFORMANCE · COOLING TO ${change.to.toUpperCase()}`
    : `AUTO PERFORMANCE · RESTORED TO ${change.to.toUpperCase()}`);
}

function feedPerformanceGovernor(frameMs) {
  if (!governorAllowed()) {
    // A static gate closed (online match, forced profile, cabinet): drop the
    // machine so the static resolution rules the profile again. The memory
    // survives, so a later return to AUTO re-seeds from the landed tier
    // instead of re-baselining from scratch.
    if (performanceGovernor.machine) {
      performanceGovernor.machine = null;
      applyPerformanceSettings();
    }
    return;
  }
  // Menus, the result screen, a hidden tab: keep the machine and its
  // cooldown/recovery counters exactly where the last fight left them.
  if (!governorEligible()) return;
  if (!performanceGovernor.machine) {
    performanceGovernor.machine = createGovernorMachine();
    // A remembered tier below the static baseline applies from this frame —
    // that is the whole point: no window of misses, no toast.
    applyPerformanceSettings();
  }
  applyGovernorChange(performanceGovernor.machine.observe(frameMs));
}

// ---------------------------------------------------------------------------
// R1.9 wave 15: combat-event haptics + gamepad dual-rumble.
// Follows the sound() pattern exactly: early-return on rollbackResimulating,
// gated behind the persisted HAPTICS toggle, rate-capped so a multi-hit never
// turns the phone into a hair clipper. Pattern selection is pure
// (hapticPatternFor in engine/polish.mjs); pads rumble per human side via the
// same getPad plumbing readInput uses. Presentation only — nothing here can
// touch the simulation.
// ---------------------------------------------------------------------------
const hapticsDebug = { events: 0, rumbles: 0, suppressed: 0, lastKind: "" };
// Tick latch for the fatality heartbeat pulse (wallSplatLastTick pattern —
// module-level, render-only, never snapshotted).
let lastHeartbeatHapticTick = -Infinity;
const HAPTIC_MIN_GAP_MS = 45;
const HAPTIC_PRIORITY_KINDS = new Set(["ko", "dizzy", "fatalityHeartbeat", "super", "throw", "wallSplat"]);
let lastHapticAt = 0;

function combatHaptic(kind, { damage = 0, blocked = false, counter = false } = {}) {
  if (rollbackResimulating) return;
  if (!state.touchSettings.haptics) return;
  // Nobody is holding anything during the self-running attract loop.
  if (state.mode === "demo" || state.mode === "tournament") return;
  const now = performance.now();
  if (now - lastHapticAt < HAPTIC_MIN_GAP_MS && !HAPTIC_PRIORITY_KINDS.has(kind)) {
    hapticsDebug.suppressed += 1;
    return;
  }
  lastHapticAt = now;
  const pattern = hapticPatternFor(kind, { damage, blocked, counter });
  hapticsDebug.events += 1;
  hapticsDebug.lastKind = pattern.kind;
  try {
    // Chrome logs a console intervention (and ignores the call) for vibrate
    // before any user gesture — keyboard-only sessions would see it on every
    // hit. Only vibrate once the browser reports real user activation.
    if (navigator.userActivation?.hasBeenActive !== false) navigator.vibrate?.(pattern.vibrate);
  } catch {
    // Some browsers throw instead of ignoring vibration without a gesture.
  }
  for (const side of [0, 1]) {
    if (sideIsCpuControlled(side)) continue;
    const pad = getPad(side);
    const actuator = pad?.vibrationActuator;
    if (!actuator?.playEffect) continue;
    hapticsDebug.rumbles += 1;
    try {
      const played = actuator.playEffect("dual-rumble", pattern.rumble);
      played?.catch?.(() => {});
    } catch {
      // A pad may vanish between getPad and playEffect; rumble is best-effort.
    }
  }
}

// ---------------------------------------------------------------------------
// R1.9 wave 15: screen wake lock. Held during fights and the attract demo,
// released on menus/pause/hidden tab, re-acquired on visibilitychange. Silent
// no-op where unsupported, like screen.orientation.lock.
// ---------------------------------------------------------------------------
let wakeLockSentinel = null;
let wakeLockWanted = false;
let wakeLockRequesting = false;

function syncWakeLock() {
  wakeLockWanted = !document.hidden
    && ((state.screen === "fight" && !state.paused) || demoSession.active);
  if (wakeLockWanted && !wakeLockSentinel && !wakeLockRequesting && navigator.wakeLock?.request) {
    wakeLockRequesting = true;
    navigator.wakeLock.request("screen").then((sentinel) => {
      wakeLockRequesting = false;
      wakeLockSentinel = sentinel;
      // The browser can release it on its own (tab hidden); track that.
      sentinel.addEventListener?.("release", () => {
        if (wakeLockSentinel === sentinel) wakeLockSentinel = null;
      });
      // The screen may have changed while the request was in flight.
      if (!wakeLockWanted) syncWakeLock();
    }).catch(() => {
      wakeLockRequesting = false;
    });
  } else if (!wakeLockWanted && wakeLockSentinel) {
    const sentinel = wakeLockSentinel;
    wakeLockSentinel = null;
    try {
      sentinel.release?.()?.catch?.(() => {});
    } catch {
      // Already released.
    }
  }
}

// ---------------------------------------------------------------------------
// R1.9 wave 15: ARCADE CABINET mode. Composes existing pieces into one TV
// preset: high profile pinned, CRT defaulted on at activation, touch HUD
// hidden, fight HUD enlarged ~15%, attract loop + high-score cycling forced,
// cursor auto-hidden at idle, and any pad press on the title dropping
// straight into character select (handled in menuPadLoop).
// ---------------------------------------------------------------------------
let cabinetCursorTimer = 0;

function applyCabinetMode() {
  document.body.classList.toggle("cabinet-mode", state.cabinetMode);
  const marquee = $("#cabinetMarquee");
  if (marquee) marquee.hidden = !(state.cabinetMode && state.screen === "title");
  if (!state.cabinetMode) {
    window.clearTimeout(cabinetCursorTimer);
    cabinetCursorTimer = 0;
    document.body.classList.remove("cabinet-idle");
  } else {
    scheduleCabinetCursorHide();
    scheduleIdleDemo();
  }
  applyPerformanceSettings();
}

function scheduleCabinetCursorHide() {
  window.clearTimeout(cabinetCursorTimer);
  cabinetCursorTimer = window.setTimeout(() => {
    if (state.cabinetMode) document.body.classList.add("cabinet-idle");
  }, 4000);
}

document.addEventListener("mousemove", () => {
  if (!state.cabinetMode) return;
  document.body.classList.remove("cabinet-idle");
  scheduleCabinetCursorHide();
}, { passive: true });

function applyPerformanceSettings() {
  state.visualQuality = normalizeVisualQuality(state.visualQuality);
  // Wave 15 resolution order: CABINET MODE pins high for the TV; otherwise
  // the adaptive governor may hold a stepped-down tier while quality is AUTO;
  // otherwise the static device resolution decides. A user-forced profile
  // always wins because the governor machine only exists under AUTO.
  let resolved = state.cabinetMode
    ? PERFORMANCE_PROFILES.high
    : resolvePerformanceProfile(state.visualQuality, performanceEnvironment(state.accessibility.reducedMotion));
  if (!state.cabinetMode && state.visualQuality === "auto" && performanceGovernor.machine) {
    resolved = PERFORMANCE_PROFILES[performanceGovernor.machine.profile()] || resolved;
  }
  state.performance = resolved;
  document.body.dataset.quality = state.performance.id;
  $("#visualQualitySelect").value = state.visualQuality;
  $("#sharpRenderToggle").checked = Boolean(state.sharpRender);
  $("#crtModeToggle").checked = Boolean(state.crtMode);
  if ($("#cabinetModeToggle")) $("#cabinetModeToggle").checked = Boolean(state.cabinetMode);
  $("#cinema3dToggle").checked = Boolean(state.cinema3d);
  if ($("#meshFightersToggle")) $("#meshFightersToggle").checked = Boolean(state.meshFighters);
  // Profile switches can grant/revoke CINEMA 3D eligibility (battery refuses).
  ensureCinema3d();
  $("#pausePerformance").textContent = `${state.visualQuality.toUpperCase()} VISUALS · ${state.performance.id.toUpperCase()} PROFILE · ${state.performance.particleBudget} FX BUDGET`;
  // Wave 7: quality switches re-apply the DPR-sharp backing store.
  applyBackingStoreResolution();
}

// The movement pad is three rows tall now, so on a short landscape phone the
// button size has to come from the available height rather than a fixed 56px.
const TOUCH_PAD_ROWS = 3;
const TOUCH_PAD_GAP = 5;
const TOUCH_PAD_HEIGHT_SHARE = 0.56;

function touchButtonSize() {
  const available = (window.innerHeight || 720) * TOUCH_PAD_HEIGHT_SHARE - TOUCH_PAD_GAP * (TOUCH_PAD_ROWS - 1);
  const fits = available / TOUCH_PAD_ROWS;
  return Math.round(clamp(Math.min(56, fits) * state.touchSettings.scale, 34, 72));
}

function applyTouchSettings() {
  state.touchSettings.handedness = state.touchSettings.handedness === "left" ? "left" : "standard";
  document.body.classList.toggle("touch-left", state.touchSettings.handedness === "left");
  document.documentElement.style.setProperty("--touch-button-size", `${touchButtonSize()}px`);
  document.documentElement.style.setProperty("--touch-opacity", String(state.touchSettings.opacity));
  $("#touchHandednessSelect").value = state.touchSettings.handedness;
  $("#touchScale").value = String(Math.round(state.touchSettings.scale * 100));
  $("#touchOpacity").value = String(Math.round(state.touchSettings.opacity * 100));
  $("#touchScaleValue").textContent = `${Math.round(state.touchSettings.scale * 100)}%`;
  $("#touchOpacityValue").textContent = `${Math.round(state.touchSettings.opacity * 100)}%`;
  $("#touchHapticsToggle").checked = state.touchSettings.haptics;
}

function saveBindings() {
  localStorage.setItem("final-blow-keymaps", JSON.stringify(keyMaps));
  localStorage.setItem("final-blow-pad-map", JSON.stringify(padMap));
}

function activePadLabelSet() {
  const pad = getPad(0) || getPad(1);
  return detectPadLabelSet(pad?.id || "");
}

function renderBindings() {
  const labels = {
    left: "LEFT", right: "RIGHT", up: "UP / JUMP", down: "DOWN / CROUCH",
    lp: BUTTON_NAMES.lp, hp: BUTTON_NAMES.hp, lk: BUTTON_NAMES.lk, hk: BUTTON_NAMES.hk,
  };
  for (const player of [0, 1]) {
    const container = $(`#p${player + 1}KeyBindings`);
    container.innerHTML = REMAPPABLE_ACTIONS.map((action) => `<button type="button" class="binding-button${pendingKeyBinding?.player === player && pendingKeyBinding.action === action ? " listening" : ""}" data-bind-player="${player}" data-bind-action="${action}"><span>${labels[action]}</span><b>${pendingKeyBinding?.player === player && pendingKeyBinding.action === action ? "PRESS KEY" : formatKeyCode(keyMaps[player][action])}</b></button>`).join("");
  }
  const labelSet = activePadLabelSet();
  $("#padBindings").innerHTML = ATTACK_BUTTONS.map((action) => `<label>${BUTTON_LABELS[action]} · ${labels[action]}<select data-pad-action="${action}">${PAD_BUTTON_LABELS.map((_, button) => `<option value="${button}"${padMap[action] === button ? " selected" : ""}>${padButtonLabel(button, labelSet)}</option>`).join("")}</select></label>`).join("");
  $$('[data-bind-player]').forEach((button) => button.addEventListener("click", () => {
    pendingKeyBinding = { player: Number(button.dataset.bindPlayer), action: button.dataset.bindAction };
    renderBindings();
  }));
  $$('[data-pad-action]').forEach((select) => select.addEventListener("change", () => {
    padMap = remapPadBinding(padMap, select.dataset.padAction, Number(select.value));
    saveBindings();
    renderBindings();
  }));
}

const DIFFICULTY_HINTS = Object.freeze({
  passive: "Never attacks, blocks, techs or moves. A living practice dummy.",
  rookie: "Slow to react and prone to mistakes. Room to learn a matchup.",
  street: "Balanced reactions and pressure. The default fight.",
  pro: "Fast reactions, real punishes and confident meter use.",
  final: "Reads almost everything. Boss-level pressure.",
});

function renderDifficultyOptions() {
  const container = $("#difficultyOptions");
  if (!container) return;
  container.innerHTML = AI_DIFFICULTY_ORDER.map((id) => {
    const selected = state.aiDifficulty === id;
    return `<button type="button" role="radio" class="${id}" data-difficulty="${id}" aria-checked="${selected}">${AI_DIFFICULTIES[id].label}</button>`;
  }).join("");
  $$("[data-difficulty]").forEach((button) => button.addEventListener("click", () => {
    setAiDifficulty(button.dataset.difficulty);
  }));
  $("#difficultyHint").textContent = DIFFICULTY_HINTS[state.aiDifficulty] || "";
}

// The picker is only meaningful when a CPU is actually in the match.
function facesCpuOpponent() {
  return state.mode === "arcade"
    || (state.mode === "team" && state.teamCpu)
    || (state.mode === "training" && state.training.dummyMode === "cpu");
}

function syncDifficultyUi() {
  const bar = $("#difficultyBar");
  if (!bar) return;
  bar.hidden = !(state.screen === "select" && facesCpuOpponent());
  renderDifficultyOptions();
}

function setStageWeapons(enabled) {
  state.stageWeaponsEnabled = Boolean(enabled);
  localStorage.setItem("final-blow-stage-weapons", state.stageWeaponsEnabled ? "1" : "0");
  const toggle = $("#stageWeaponToggle");
  if (toggle) toggle.checked = state.stageWeaponsEnabled;
  if (!state.stageWeaponsEnabled) {
    state.stageWeapon = null;
    state.fighters.forEach((fighter) => { fighter.carriedWeapon = null; fighter.carryFrames = 0; });
  } else if (!state.stageWeapon && state.fighters.length) {
    resetStageWeapon();
  }
  updateHud();
  return state.stageWeaponsEnabled;
}

function setAiDifficulty(difficulty) {
  state.aiDifficulty = normalizeAiDifficulty(difficulty);
  localStorage.setItem("final-blow-ai-difficulty", state.aiDifficulty);
  const select = $("#aiDifficultySelect");
  if (select) select.value = state.aiDifficulty;
  for (const fighter of state.fighters) resetAiBrain(fighter.aiBrain, state.aiDifficulty);
  syncDifficultyUi();
  return state.aiDifficulty;
}

function setTrack(index, restart = true) {
  const next = (index + musicTracks.length) % musicTracks.length;
  const changed = next !== currentTrackIndex;
  currentTrackIndex = next;
  if (changed) {
    fightMusic.pause();
    fightMusic.src = musicTracks[currentTrackIndex].src;
    fightMusic.load();
  } else if (restart) {
    fightMusic.currentTime = 0;
  }
  updateMusicUi();
  syncMusic();
}

function advanceTrack() {
  // Any manual/jukebox advance means the track is no longer stage-matched.
  stageMusicAutoApplied = false;
  setTrack(currentTrackIndex + 1, true);
}

function chooseMusic(choice) {
  stageMusicAutoApplied = false;
  state.musicChoice = choice;
  localStorage.setItem("final-blow-music-choice", choice);
  if (choice !== "auto") setTrack(Number(choice), true);
  else {
    updateMusicUi();
    syncMusic();
  }
}

// Release 1.6: resolve the best-fit track for a stage. Prefers a stage's
// planned todoTrack if that file has been composed and added to musicTracks;
// otherwise falls back to the mapped existing track.
function stageMusicTrackIndex(stageId) {
  const entry = STAGE_MUSIC[stageId];
  if (!entry) return currentTrackIndex;
  if (entry.todoTrack) {
    const pending = musicTracks.findIndex((track) => track.src.includes(entry.todoTrack));
    if (pending >= 0) return pending;
  }
  const index = musicTracks.findIndex((track) => track.title === entry.title);
  return index >= 0 ? index : currentTrackIndex;
}

// Applied at match start when the music mode is AUTO: the header keeps its
// existing "AUTO · <TRACK>" readout, manual track picking is untouched.
function applyAutoStageMusic() {
  if (state.musicChoice !== "auto") return;
  setTrack(stageMusicTrackIndex(state.stage), true);
  stageMusicAutoApplied = true;
}

function syncMusic() {
  if (!state.audioUnlocked) return;
  const enabled = Boolean($("#musicToggle")?.checked);
  fightMusic.loop = state.musicChoice !== "auto";
  // v5.3: the bed's half of the danger crossfade. dangerStemBedGain is 1
  // until the stem starts arriving, so nothing about the ordinary mix moves.
  fightMusic.volume = clamp(
    musicBaseVolume() * state.musicDuck * state.musicVolume * dangerStemBedGain(dangerStemLevel),
    0,
    1,
  );
  if (!enabled || document.hidden || state.paused) {
    fightMusic.pause();
    stopDangerStem();
    return;
  }
  if (fightMusic.paused) fightMusic.play().catch(() => {});
  syncDangerStem();
}

function resetMusicDuck() {
  window.clearTimeout(musicDuckTimer);
  state.musicDuck = 1;
  syncMusic();
}

function duckMusic(amount, duration) {
  if (rollbackResimulating) return;
  window.clearTimeout(musicDuckTimer);
  state.musicDuck = amount;
  syncMusic();
  musicDuckTimer = window.setTimeout(() => {
    state.musicDuck = 1;
    syncMusic();
  }, duration);
}

function stopSfx() {
  [...Object.values(sfxPools).flat(), ...[...fighterSfxPools.values()].flat(), ...[...crowdVoiceBanks.values()].flat()].forEach((sample) => {
    sample.pause();
    sample.currentTime = 0;
  });
}

function fighterSoundId(fighter) {
  if (typeof fighter === "string") return fighter;
  return fighter?.def?.id || fighter?.id || null;
}

// ---------------------------------------------------------------------------
// Wave 9 "voice plumbing" — fighter voice variant banks. Module-level render
// state only (never snapshotted, never read by the simulation): which
// canonical variant files exist on disk. Since 5.1 that answer comes from
// assets/audio/MANIFEST.json (baked from the files by
// tools/audio/build_manifest.mjs, which also measures every take's length);
// the HEAD probe below survives only as the fallback for a missing or
// unreadable manifest, where it still runs exactly once per bank per session
// so missing takes can never spam the network.
// ---------------------------------------------------------------------------

// Monotonic wave-9 voice totals, exposed via snapshot().violence.
const voiceFxDebug = {
  announcerCalls: 0, announcerBanksLoaded: 0, voiceVariantPlays: 0,
  reactiveCues: 0, storyCallouts: 0, onlineMoments: 0,
  // w51: "TEN SECONDS" clock calls (once per round) and decision round-ends
  // that opened on the timeover bank instead of "ko".
  clockCallouts: 0, decisionCalls: 0,
  // 5.1 manifest counters: banks resolved without a request, and media
  // elements actually created for fighter voice (was 3-5 per take, up to
  // 183 per fighter at fight start; now one per take, grown only on overlap).
  manifestBanks: 0, voiceElements: 0,
};
// Every probe HEAD request ever issued — QA asserts this stays flat when the
// same missing bank is requested repeatedly (probe once, cached forever), and
// stays at ZERO for the whole session while the manifest is present.
let voiceProbeRequests = 0;

function probeAudioFile(url) {
  voiceProbeRequests += 1;
  return fetch(url, { method: "HEAD" })
    .then((response) => response.ok)
    .catch(() => false);
}

// The build-time audio manifest, fetched once at boot (before any fighter is
// made, so by the time makeFighter warms a palette the answer is usually
// already here and the bank fills synchronously). `data` is the parsed
// manifest or null once settled; `settled` distinguishes "not yet loaded"
// (banks wait for it) from "missing" (banks probe, the pre-5.1 path).
const audioManifestState = { promise: null, data: null, settled: false };

function loadAudioManifest() {
  if (!audioManifestState.promise) {
    audioManifestState.promise = fetch(AUDIO_MANIFEST_PATH)
      .then((response) => (response.ok ? response.json() : null))
      .then((raw) => parseAudioManifest(raw))
      .catch(() => null)
      .then((manifest) => {
        audioManifestState.data = manifest;
        audioManifestState.settled = true;
        return manifest;
      });
  }
  return audioManifestState.promise;
}
// Fetched at boot like the motion/walk/unified manifests: one small JSON
// request, long before the first makeFighter.
loadAudioManifest();

// `${fighterId}:${cue}` -> { srcs: confirmed variant files, durationsMs,
// probed, source }. How a bank fills depends on what the review left behind:
//   recorded    — the reviewed kick pools. Every path is an accepted take that
//                 ships, so the bank is complete on creation and never probes.
//   probed      — a surviving 1.5 core take. Variant 1 is known to exist;
//                 slots 2 and 3 are speculative (one HEAD each, manifest-less).
//   placeholder — a reactive cue; starts empty and borrows a detuned take
//                 until real files are confirmed.
// With the manifest loaded the probed/placeholder distinction only decides
// what the bank holds while the fetch is in flight: the manifest then names
// every existing take at once (source "manifest", zero requests). A cue
// whose recording was rejected has no palette entry at all, so it never
// reaches this function and can never be requested from the network.
const fighterVoiceBanks = new Map();

function probeFighterVoiceBank(bank, variants, seeded) {
  // One probe pass per bank per session, sequential and stopping at the
  // first gap (banks are contiguous), so a fully-missing bank costs a
  // single request and a present bank grows the rotation in place.
  (async () => {
    const found = variants.slice(0, seeded);
    for (let index = seeded; index < variants.length; index += 1) {
      if (!(await probeAudioFile(variants[index]))) break;
      found.push(variants[index]);
    }
    bank.srcs = found;
    bank.probed = true;
    bank.source = "probe";
  })();
}

function fighterVoiceBank(fighterId, cue) {
  const variants = fighterAudioVariants(fighterId, cue);
  if (!variants) return null;
  const key = `${fighterId}:${cue}`;
  let bank = fighterVoiceBanks.get(key);
  if (bank) return bank;
  // Wave 16: the bank kind is fighter-aware — the Commissioner's core cues
  // probe all slots because no recorded variant 1 exists yet.
  const kind = fighterAudioBankKind(cue, fighterId);
  const manifestDurations = (srcs) => srcs.map((src) => fighterBankFromManifest(audioManifestState.data, fighterId, [src])?.durationsMs[0] || 0);
  if (kind === FIGHTER_AUDIO_BANK_KINDS.recorded) {
    // The review pool is the truth for recorded banks; the manifest only
    // contributes lengths (and cannot trim what the review accepted).
    bank = { key, srcs: [...variants], durationsMs: manifestDurations(variants), probed: true, source: "recorded" };
    fighterVoiceBanks.set(key, bank);
    return bank;
  }
  const seeded = kind === FIGHTER_AUDIO_BANK_KINDS.probed ? 1 : 0;
  bank = { key, srcs: variants.slice(0, seeded), durationsMs: [], probed: false, source: "pending" };
  fighterVoiceBanks.set(key, bank);
  const settleFromManifest = (manifest) => {
    const resolved = fighterBankFromManifest(manifest, fighterId, variants);
    if (!resolved) return false;
    bank.srcs = [...resolved.srcs];
    bank.durationsMs = [...resolved.durationsMs];
    bank.probed = true;
    bank.source = "manifest";
    voiceFxDebug.manifestBanks += 1;
    return true;
  };
  if (audioManifestState.settled) {
    if (!settleFromManifest(audioManifestState.data)) probeFighterVoiceBank(bank, variants, seeded);
    return bank;
  }
  loadAudioManifest().then((manifest) => {
    if (!settleFromManifest(manifest)) probeFighterVoiceBank(bank, variants, seeded);
  });
  return bank;
}

// Pool caps per cue, unchanged from the eager createSfxPool sizes: a hit cue
// may stack five overlapping plays, anything else three. The difference is
// that a pool now STARTS at one element per confirmed take and only grows
// when a play finds every element busy — measured at 5.0 a devil vs
// commissioner fight created ~366 fighter voice elements at makeFighter
// against Chrome's live-player cap (~75 desktop / ~40 Android), so early
// takes could be torn down and need a reload on first play.
function fighterVoicePoolCap(cue) {
  return cue.startsWith("hit-") || cue === "hit" ? 5 : 3;
}

function fighterVoiceElement(src, preload) {
  const sample = new Audio(src);
  sample.preload = preload;
  voiceFxDebug.voiceElements += 1;
  return sample;
}

function fighterVoicePool(cue, bankKey, variantIndex, src, preload = "auto") {
  const poolKey = `${bankKey}:${variantIndex}`;
  let pool = fighterSfxPools.get(poolKey);
  if (!pool) {
    pool = [fighterVoiceElement(src, preload)];
    pool.cue = cue;
    fighterSfxPools.set(poolKey, pool);
  }
  return pool;
}

// The element a play should use: the first idle one, else a fresh copy while
// the pool is under its cap (the take is genuinely overlapping itself), else
// the oldest — which the caller restarts, exactly as the fixed pools did once
// they wrapped.
function fighterVoiceSample(pool) {
  const idle = pool.find((sample) => sample.paused || sample.ended);
  if (idle) return idle;
  if (pool.length < fighterVoicePoolCap(pool.cue)) {
    const sample = fighterVoiceElement(pool[0].src, "auto");
    pool.push(sample);
    return sample;
  }
  return pool[0];
}

/**
 * Resolve the next fighter voice take for a cue. The fighterSfxCursors
 * round-robin is the no-repeat rotation across confirmed variants; a bank
 * with a single real take gets deterministic playbackRate micro-variation
 * (visualRandom — checksum-exempt, never state.rng) so consecutive plays are
 * never identical; reactive cues with no takes yet borrow their pitch-offset
 * placeholder take from FIGHTER_REACTIVE_PLACEHOLDERS.
 */
function fighterVoiceTake(kind, fighterId) {
  if (!fighterId) return null;
  let cue = kind;
  let rate = 1;
  let bank = fighterVoiceBank(fighterId, cue);
  if (!bank) return null;
  if (!bank.srcs.length) {
    const placeholder = FIGHTER_REACTIVE_PLACEHOLDERS[cue];
    if (!placeholder) return null;
    cue = placeholder.cue;
    rate = placeholder.rate;
    bank = fighterVoiceBank(fighterId, cue);
    if (!bank?.srcs.length) return null;
  }
  const cursorKey = `${fighterId}:${cue}`;
  const cursor = fighterSfxCursors.get(cursorKey) || 0;
  fighterSfxCursors.set(cursorKey, cursor + 1);
  const variantIndex = cursor % bank.srcs.length;
  const pool = fighterVoicePool(cue, bank.key, variantIndex, bank.srcs[variantIndex]);
  if (!pool?.length) return null;
  if (bank.srcs.length === 1) rate *= 0.94 + visualRandom() * 0.12;
  return { sample: fighterVoiceSample(pool), rate, durationMs: bank.durationsMs?.[variantIndex] || 0 };
}

// Voice warm-up runs from makeFighter, i.e. at the same instant the unified
// sheets (8-14 MB) start downloading against the 2.1 s intro. One element per
// confirmed take is created with preload="metadata" so the browser opens the
// file but does not pull the whole 1-3 MB palette during the intro; the FIGHT!
// banner (or this timer, for paths without one — training, demo) then flips
// the same elements to preload="auto" so every take is resident before the
// first exchange. Banks still waiting on the manifest fetch get their pools
// at top-up time instead.
const FIGHTER_VOICE_TOPUP_MS = 2400;
let fighterVoiceTopupTimer = 0;

function warmFighterAudio(fighters = state.fighters) {
  for (const fighter of fighters) {
    const fighterId = fighterSoundId(fighter);
    for (const cue of FIGHTER_AUDIO_CUES) {
      const bank = fighterVoiceBank(fighterId, cue);
      bank?.srcs.forEach((src, index) => fighterVoicePool(cue, bank.key, index, src, "metadata"));
    }
  }
  // The two announcer calls the intro itself makes (the round card and
  // FIGHT!) used to open their banks at the moment they fired, so the first
  // line of every fight was a cold fetch; with the manifest settled these
  // fill synchronously here, a couple of seconds ahead of the call.
  announcerBank(state.round >= 3 ? "finalround" : state.round === 2 ? "round2" : "round1");
  announcerBank("fight");
  window.clearTimeout(fighterVoiceTopupTimer);
  fighterVoiceTopupTimer = window.setTimeout(() => topUpFighterAudio(fighters), FIGHTER_VOICE_TOPUP_MS);
}

function topUpFighterAudio(fighters = state.fighters) {
  window.clearTimeout(fighterVoiceTopupTimer);
  for (const fighter of fighters) {
    const fighterId = fighterSoundId(fighter);
    if (!fighterId) continue;
    for (const cue of FIGHTER_AUDIO_CUES) {
      const bank = fighterVoiceBanks.get(`${fighterId}:${cue}`);
      bank?.srcs.forEach((src, index) => {
        for (const sample of fighterVoicePool(cue, bank.key, index, src)) {
          if (sample.preload !== "auto") sample.preload = "auto";
        }
      });
    }
  }
}

function unlockAudio() {
  state.audioUnlocked = true;
  if ($("#soundToggle").checked) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass && !state.audio) state.audio = new AudioContextClass();
    if (state.audio?.state === "suspended") state.audio.resume();
    // Release 1.6 LOUD: the shared master gain -> limiter bus rides the same
    // first-gesture lazy-init path, so nothing audio-graph runs at boot.
    if (state.audio) ensureAudioGraph();
  }
  syncMusic();
}

/**
 * Which cue a swing announces. Every derived kick profile is tagged
 * `limb: "kick"` by the sim itself, so light and heavy normals thrown with a
 * leg claim the reviewed kick cues instead of the punch-flavoured ones. The
 * tag rides on the move instance that actually spawned, so the audio can never
 * disagree with the attack on screen. Supers and throws keep their own cue
 * whichever limb threw them.
 */
function attackSwingCue(move, actionGroup) {
  if (move.superMove) return "super";
  if (actionGroup === "throw") return "throw";
  if (move.limb === "kick") {
    if (move.kind === "light") return "light-kick-swing";
    if (move.kind === "heavy") return "roundhouse-swing";
  }
  return move.kind;
}

/** The impact counterpart of attackSwingCue. A blocked hit stays a guard cue. */
function attackImpactCue(attack, blocked) {
  if (blocked) return "block";
  if (attack.limb === "kick") {
    if (attack.kind === "light") return "light-kick-impact";
    if (attack.kind === "heavy") return "roundhouse-impact";
  }
  return attack.kind === "light" ? "hit-light" : "hit-heavy";
}

function sound(kind, fighter = null) {
  if (rollbackResimulating) return;
  const fighterId = fighterSoundId(fighter);
  const fallbackKind = fallbackSoundKinds[kind] || kind;
  const signatureSrc = fighterAudioCue(fighterId, kind);
  lastSoundEvent = Object.freeze({
    kind,
    fighterId,
    signature: Boolean(signatureSrc),
    src: signatureSrc || audioAssets[fallbackKind] || null,
  });
  showSoundCaption(kind, fighter);
  if (!$("#soundToggle").checked) return;
  if (demoSession.attract && !state.audioUnlocked) return;
  unlockAudio();
  // Wave 9: signature cues route through the variant banks (no-repeat
  // rotation + micro-variation + reactive placeholders). playbackRate and
  // preservesPitch are set explicitly on every play because pool elements
  // are reused and a detuned take must never leak into the next play.
  const take = fighterVoiceTake(kind, fighterId);
  // Item 21: the dash scuff and the stage-weapon clatter are synthesised
  // (SHARED_SYNTH_VOICES) rather than borrowed samples. The scuff is the
  // foot, so it plays under a fighter's own dash grunt as well; with no
  // take it IS the cue and the shared pool is never consulted.
  const synthesised = sharedSynthVoice(kind, fighter);
  if (take) {
    voiceFxDebug.voiceVariantPlays += 1;
    const sample = take.sample;
    sample.pause();
    sample.currentTime = 0;
    sample.preservesPitch = take.rate === 1;
    sample.playbackRate = take.rate;
    sample.volume = (sfxVolumes[kind] ?? 0.62) * state.sfxVolume;
    const playback = sample.play();
    if (playback?.catch) playback.catch(() => proceduralSound(fallbackKind));
    return;
  }
  if (synthesised) return;
  const pool = sfxPools[fallbackKind];
  if (!pool?.length) {
    proceduralSound(fallbackKind);
    return;
  }
  const cursor = (sfxCursors[fallbackKind] || 0) % pool.length;
  sfxCursors[fallbackKind] = cursor + 1;
  const sample = pool[cursor];
  // Item 21: body-hit.mp3 lands on nearly every impact and the two swing
  // takes on most swings, bit-identical play after play. The reviewed files
  // are frozen, so the variety is applied here: a per-play pitch shift
  // (±6-8%, preservesPitch off so the rate actually changes the sound) and a
  // ±1.5 dB level nudge, drawn so no two consecutive plays of one take can
  // share a pitch (engine/shared-sfx.mjs distinctDraw). visualRandom is the
  // checksum-exempt stream the single-take fighter banks already use. Set on
  // every play: pool elements are reused and a detuned rate must never leak
  // into a kind outside the table.
  const variation = nextSharedVariation(fallbackKind);
  sample.pause();
  sample.currentTime = 0;
  sample.preservesPitch = variation.rate === 1;
  sample.playbackRate = variation.rate;
  sample.volume = Math.min(1, (sfxVolumes[kind] ?? 0.62) * state.sfxVolume * variation.gain);
  const playback = sample.play();
  if (playback?.catch) playback.catch(() => proceduralSound(fallbackKind));
}

// Last variation record per shared kind (the "previous" distinctDraw needs)
// plus the most recent play for QA: snapshot().audio.variation lets the smoke
// prove two consecutive body-hits differ in rate without listening.
const sharedVariationLast = {};
let lastSharedVariation = null;

function nextSharedVariation(kind) {
  const variation = pickSharedVariation(kind, sharedVariationLast[kind], visualRandom);
  if (variation.rate !== 1) {
    sharedVariationLast[kind] = variation;
    audioFxDebug.sharedVariations += 1;
    lastSharedVariation = Object.freeze({ kind, ...variation });
  }
  return variation;
}

// Cues that synthesise instead of borrowing a shared take. Each returns true
// when it handled the cue (whether or not the context was awake enough to
// make a sound) so sound() skips the pool and the procedural fallback.
const SHARED_SYNTH_VOICES = Object.freeze({
  dash: (fighter) => dashScuff(fighter),
  "stage-weapon": () => weaponClatter(),
  // v5.1 TEMPO TELLS: the press the re-arm gap ate.
  "rearm-drop": () => rearmClick(),
});

function sharedSynthVoice(kind, fighter) {
  const voice = SHARED_SYNTH_VOICES[kind];
  if (!voice) return false;
  voice(fighter);
  return true;
}

function showSoundCaption(kind, fighter = null, overrideText = "") {
  if (!state.soundCaptions) return;
  const caption = $("#soundCaption");
  const fighterId = fighterSoundId(fighter);
  const fighterName = fighter?.def?.name || roster.find(({ id }) => id === fighterId)?.name;
  // Wave 9: spoken announcer lines echo their exact text (they are not fixed
  // cue labels) and hold slightly longer so the line can be read.
  const label = overrideText || FIGHTER_AUDIO_LABELS[kind] || soundCaptionLabels[kind];
  if (!caption || !label) return;
  window.clearTimeout(soundCaptionTimer);
  caption.textContent = `◀ ${fighterName ? `${fighterName} · ` : ""}${label} ▶`;
  caption.hidden = false;
  soundCaptionTimer = window.setTimeout(() => { caption.hidden = true; }, overrideText ? 1150 : 720);
}

/**
 * Each personal object gets its own synthesized impact rather than a shared
 * sample: a tone sweep for the body of the sound plus a shaped noise burst for
 * its texture. Synthesis keeps the objects distinct without shipping eight more
 * audio files, works offline, and costs nothing to add a ninth.
 *
 * [startHz, endHz, seconds, waveform, gain, noiseAmount, noiseSeconds, filterHz]
 */
const OBJECT_SOUNDS = Object.freeze({
  pizza: [190, 62, 0.24, "sine", 0.085, 0.5, 0.2, 900],
  mouse: [640, 210, 0.13, "square", 0.06, 0.22, 0.1, 3200],
  loogie: [430, 120, 0.17, "sine", 0.07, 0.62, 0.16, 1500],
  wires: [150, 58, 0.3, "sawtooth", 0.075, 0.4, 0.26, 700],
  xacto: [1500, 640, 0.11, "triangle", 0.062, 0.3, 0.09, 6200],
  golfball: [900, 380, 0.09, "sine", 0.055, 0.16, 0.06, 4200],
  bedbugs: [260, 320, 0.34, "triangle", 0.05, 0.7, 0.32, 2400],
  vinyl: [520, 90, 0.26, "sawtooth", 0.08, 0.34, 0.2, 1800],
  // Steel cane: a hard metallic ring with a short clatter tail.
  cane: [980, 240, 0.16, "triangle", 0.07, 0.28, 0.12, 5200],
  // 5.3 SPECTACLE: the five stage-weapon styles had no entry at all, so
  // picking one up off the floor made no sound whatsoever — objectSound()
  // returned on the missing key. Each is the sound of the object being
  // SCOOPED (a scrape and a knock), not the clatter it makes when it lands
  // (that is weaponClatterParams in engine/shared-sfx.mjs).
  needle: [3400, 2100, 0.07, "triangle", 0.04, 0.14, 0.05, 7000],
  bottle: [420, 180, 0.13, "sine", 0.06, 0.3, 0.1, 2200],
  pigeon: [190, 90, 0.15, "sine", 0.05, 0.5, 0.14, 1100],
  tongs: [1250, 520, 0.12, "triangle", 0.06, 0.26, 0.09, 4600],
  cup: [520, 240, 0.11, "triangle", 0.05, 0.3, 0.1, 1800],
  // The brick is the heaviest scoop in the game: a gritty drag off the
  // rubble and a dead knock, nothing rings.
  brick: [140, 62, 0.17, "sine", 0.075, 0.62, 0.16, 800],
});

function noiseBurst(now, amount, seconds, filterHz) {
  if (!amount || !state.audio) return;
  const frames = Math.max(1, Math.floor(state.audio.sampleRate * seconds));
  const buffer = state.audio.createBuffer(1, frames, state.audio.sampleRate);
  const data = buffer.getChannelData(0);
  for (let index = 0; index < frames; index += 1) {
    // Deterministic pseudo-noise: audio must never touch gameplay RNG.
    const value = Math.sin(index * 12.9898) * 43758.5453;
    data[index] = ((value - Math.floor(value)) * 2 - 1) * (1 - index / frames);
  }
  const source = state.audio.createBufferSource();
  source.buffer = buffer;
  const filter = state.audio.createBiquadFilter();
  filter.type = "lowpass";
  filter.frequency.setValueAtTime(filterHz, now);
  const gain = state.audio.createGain();
  gain.gain.setValueAtTime(Math.max(0.0001, amount * 0.09 * state.sfxVolume), now);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + seconds);
  source.connect(filter).connect(gain).connect(masterBusInput());
  source.start(now);
  source.stop(now + seconds);
}

/**
 * Release 1.7: Perfect Guard 'tink' — a bright metallic ping layered over the
 * ordinary block cue so a just-defend reads instantly by ear. Synthesized on
 * the objectSound pattern (no new samples), render-side only with the
 * announce() resim guard; no gameplay reads or writes.
 */
function perfectGuardTink() {
  if (rollbackResimulating) return;
  showSoundCaption("perfect-guard");
  if (!$("#soundToggle").checked) return;
  unlockAudio();
  if (!state.audio) return;
  const now = state.audio.currentTime;
  const oscillator = state.audio.createOscillator();
  const gain = state.audio.createGain();
  oscillator.type = "triangle";
  oscillator.frequency.setValueAtTime(2600, now);
  oscillator.frequency.exponentialRampToValueAtTime(1450, now + 0.09);
  gain.gain.setValueAtTime(Math.max(0.0001, 0.07 * state.sfxVolume), now);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.11);
  oscillator.connect(gain).connect(masterBusInput());
  oscillator.start(now);
  oscillator.stop(now + 0.11);
}

function objectSound(styleId) {
  if (!$("#soundToggle").checked) return;
  unlockAudio();
  if (!state.audio) return;
  const settings = OBJECT_SOUNDS[styleId];
  if (!settings) return;
  const now = state.audio.currentTime;
  const [startHz, endHz, seconds, waveform, gainValue, noiseAmount, noiseSeconds, filterHz] = settings;
  const oscillator = state.audio.createOscillator();
  const gain = state.audio.createGain();
  oscillator.type = waveform;
  oscillator.frequency.setValueAtTime(startHz, now);
  oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, endHz), now + seconds);
  gain.gain.setValueAtTime(Math.max(0.0001, gainValue * state.sfxVolume), now);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + seconds);
  oscillator.connect(gain).connect(masterBusInput());
  oscillator.start(now);
  oscillator.stop(now + seconds);
  noiseBurst(now, noiseAmount, noiseSeconds, filterHz);
}

function proceduralSound(kind) {
  if (!state.audio) return;
  const now = state.audio.currentTime;
  const oscillator = state.audio.createOscillator();
  const gain = state.audio.createGain();
  const settings = {
    select: [280, 430, 0.055, "square", 0.055],
    jump: [180, 340, 0.1, "sine", 0.045],
    light: [120, 70, 0.08, "square", 0.045],
    heavy: [95, 42, 0.16, "sawtooth", 0.065],
    special: [220, 55, 0.3, "sawtooth", 0.075],
    hit: [80, 35, 0.12, "square", 0.08],
    block: [520, 210, 0.08, "square", 0.04],
    finish: [160, 52, 0.8, "sawtooth", 0.09],
    final: [70, 24, 1.2, "sawtooth", 0.12],
    ko: [130, 45, 0.55, "square", 0.08],
  }[kind] || [160, 80, 0.1, "sine", 0.04];
  oscillator.type = settings[3];
  oscillator.frequency.setValueAtTime(settings[0], now);
  oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, settings[1]), now + settings[2]);
  gain.gain.setValueAtTime(Math.max(0.0001, settings[4] * state.sfxVolume), now);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + settings[2]);
  oscillator.connect(gain).connect(masterBusInput());
  oscillator.start(now);
  oscillator.stop(now + settings[2]);
}

// ---------------------------------------------------------------------------
// Release 1.6 "LOUD" — the synthesized soundstage. Everything below is
// render/presentation audio on the documented superDimLevel pattern:
// module-level, never snapshotted, never read by the simulation, so rollback
// checksums are untouched. Sim-path triggers (crowd swells, impact layers)
// follow the announce() pattern (rollbackResimulating guard + simulationTick
// dedupe); all parameter jitter comes from presentationHash01 tick hashes so
// no RNG stream — gameplay or visual — is ever consumed. The whole graph
// lazy-initialises on the existing unlockAudio() first-user-gesture path:
// nothing here touches WebAudio at boot, so autoplay policy stays silent.
// Every synth voice routes through one shared master gain -> compressor
// limiter, so super + crowd + music + impact stacking cannot clip.
// ---------------------------------------------------------------------------

// Monotonic one-shot totals on the hudFxDebug pattern, exposed via
// snapshot().violence. nodesCreated counts every WebAudio node ever built so
// the leak probe can assert creation stays proportional to events.
const audioFxDebug = {
  impactLayers: 0, crowdSwells: 0, ambienceEvents: 0, nodesCreated: 0,
  // w51: synthesised dizzy rings and clock ticks/buzzers actually voiced
  // (after the sound-toggle / attract gates, unlike the hudFxDebug edges).
  dizzyRings: 0, clockTicks: 0,
  // Item 21: jittered shared-sample plays and the two synthesised cues.
  sharedVariations: 0, dashScuffs: 0, weaponClatters: 0,
  // v5.1 STAGE KO BEATS: the cruise ship's KO horns actually voiced.
  koHorns: 0,
  // v5.1 KO MOMENT: voiced crowd takes actually started (post every gate).
  crowdVoicePlays: 0,
  // v5.1 TEMPO TELLS: re-arm clicks actually voiced.
  rearmClicks: 0,
  // 5.3 CLOSE RANGE: clinch-break snaps actually voiced.
  clinchTechBreaks: 0,
  // v5.3 SPECTACLE: round/match music stingers actually started (post every
  // gate) and low-health danger-stem entries (mix crossing 0.5 upward).
  stingerPlays: 0, dangerStemEnters: 0,
};
// Live node bookkeeping for the QA node-graph hook: persistent = currently
// connected long-lived nodes (master bus, beds, music routing), one-shots =
// currently sounding envelope voices (decremented by their "ended" events).
let audioPersistentNodes = 0;
let audioLiveOneShots = 0;
let audioGraph = null;
let sharedNoiseBuffer = null;

function audioContextRunning() {
  return Boolean(state.audio && state.audio.state === "running");
}

// Shared master bus: gain headroom trim into a limiter-tuned compressor.
function ensureAudioGraph() {
  if (!state.audio) return null;
  if (!audioGraph) {
    const master = state.audio.createGain();
    master.gain.value = 0.92;
    const limiter = state.audio.createDynamicsCompressor();
    limiter.threshold.value = -12;
    limiter.knee.value = 6;
    limiter.ratio.value = 12;
    limiter.attack.value = 0.003;
    limiter.release.value = 0.24;
    master.connect(limiter).connect(state.audio.destination);
    audioGraph = { master, limiter };
    audioPersistentNodes += 2;
    audioFxDebug.nodesCreated += 2;
  }
  return audioGraph;
}

function masterBusInput() {
  return ensureAudioGraph()?.master || state.audio?.destination || null;
}

// One shared deterministic pseudo-noise loop (the noiseBurst hash formula):
// every noise layer and burst reads this buffer through its own filter, so a
// full soundstage costs one buffer allocation.
function ambientNoiseBuffer() {
  if (!state.audio) return null;
  if (!sharedNoiseBuffer || sharedNoiseBuffer.sampleRate !== state.audio.sampleRate) {
    const frames = Math.max(1, Math.floor(state.audio.sampleRate * 1.7));
    const buffer = state.audio.createBuffer(1, frames, state.audio.sampleRate);
    const data = buffer.getChannelData(0);
    for (let index = 0; index < frames; index += 1) {
      const value = Math.sin(index * 12.9898 + 78.233) * 43758.5453;
      data[index] = ((value - Math.floor(value)) * 2 - 1) * 0.86;
    }
    sharedNoiseBuffer = buffer;
  }
  return sharedNoiseBuffer;
}

function trackOneShot(source, extraNodes = 0) {
  audioLiveOneShots += 1;
  audioFxDebug.nodesCreated += 1 + extraNodes;
  source.addEventListener("ended", () => {
    audioLiveOneShots = Math.max(0, audioLiveOneShots - 1);
  }, { once: true });
}

// Filtered-noise envelope voice. Only ever builds nodes on a running context
// so a suspended (headless/stub) context can never accumulate zombie sources.
function synthNoiseShot({
  delay = 0, seconds, filterType = "lowpass", freq, freqEnd = 0, q = 0.8,
  peak, attack = 0.004, rate = 1,
} = {}) {
  if (!audioContextRunning() || !(peak > 0) || !(seconds > 0)) return;
  const bus = masterBusInput();
  const buffer = ambientNoiseBuffer();
  if (!bus || !buffer) return;
  const now = state.audio.currentTime + delay;
  const source = state.audio.createBufferSource();
  source.buffer = buffer;
  source.loop = true;
  source.playbackRate.value = rate;
  const filter = state.audio.createBiquadFilter();
  filter.type = filterType;
  filter.Q.value = q;
  filter.frequency.setValueAtTime(Math.max(40, freq), now);
  if (freqEnd > 0) filter.frequency.exponentialRampToValueAtTime(Math.max(40, freqEnd), now + seconds);
  const gain = state.audio.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(Math.max(0.0002, peak), now + Math.min(attack, seconds * 0.5));
  gain.gain.exponentialRampToValueAtTime(0.0001, now + seconds);
  source.connect(filter).connect(gain).connect(bus);
  source.start(now);
  source.stop(now + seconds + 0.03);
  trackOneShot(source, 2);
}

// Oscillator envelope voice with optional filter and vibrato LFO.
function synthToneShot({
  delay = 0, seconds, wave = "sine", from, to = 0, peak, attack = 0.003,
  filterType = "", freq = 0, q = 1, vibratoRate = 0, vibratoDepth = 0,
} = {}) {
  if (!audioContextRunning() || !(peak > 0) || !(seconds > 0)) return;
  const bus = masterBusInput();
  if (!bus) return;
  const now = state.audio.currentTime + delay;
  const oscillator = state.audio.createOscillator();
  oscillator.type = wave;
  oscillator.frequency.setValueAtTime(Math.max(20, from), now);
  if (to > 0) oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, to), now + seconds);
  const gain = state.audio.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(Math.max(0.0002, peak), now + Math.min(attack, seconds * 0.5));
  gain.gain.exponentialRampToValueAtTime(0.0001, now + seconds);
  let head = oscillator;
  let extraNodes = 1;
  if (filterType) {
    const filter = state.audio.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(Math.max(40, freq), now);
    filter.Q.value = q;
    oscillator.connect(filter);
    head = filter;
    extraNodes += 1;
  }
  if (vibratoRate > 0) {
    const lfo = state.audio.createOscillator();
    lfo.frequency.value = vibratoRate;
    const lfoGain = state.audio.createGain();
    lfoGain.gain.value = vibratoDepth;
    lfo.connect(lfoGain).connect(oscillator.frequency);
    lfo.start(now);
    lfo.stop(now + seconds + 0.03);
    extraNodes += 2;
  }
  head.connect(gain).connect(bus);
  oscillator.start(now);
  oscillator.stop(now + seconds + 0.03);
  trackOneShot(oscillator, extraNodes);
}

// --- Feature: layered impact audio by VIOLENCE_TIERS class -----------------

const IMPACT_LAYER_TIERS = Object.freeze({
  light: Object.freeze({ thump: 0.034, thumpHz: 150, seconds: 0.09, noise: 0 }),
  heavy: Object.freeze({ thump: 0.07, thumpHz: 118, seconds: 0.15, noise: 0.032 }),
  special: Object.freeze({ thump: 0.085, thumpHz: 102, seconds: 0.19, noise: 0.04 }),
  throw: Object.freeze({ thump: 0.078, thumpHz: 95, seconds: 0.19, noise: 0.036 }),
  weapon: Object.freeze({ thump: 0.072, thumpHz: 110, seconds: 0.17, noise: 0.034, ring: true }),
  super: Object.freeze({ thump: 0.11, thumpHz: 86, seconds: 0.25, noise: 0.05 }),
});

// Shared guard for every sim-path synth trigger: the announce() pattern plus
// the exact toggle/attract gating sound() applies to sampled SFX.
function impactAudioAllowed() {
  if (rollbackResimulating) return false;
  if (!$("#soundToggle").checked || state.sfxVolume <= 0) return false;
  if (demoSession.attract && !state.audioUnlocked) return false;
  return true;
}

function impactLayerAudio(tierName, { counter = false } = {}) {
  if (!impactAudioAllowed()) return;
  const profile = IMPACT_LAYER_TIERS[tierName] || IMPACT_LAYER_TIERS.light;
  audioFxDebug.impactLayers += 1;
  // Tick-hash jitter (never an RNG stream) so repeated hits never sound
  // machine-identical; the layer serial keeps same-tick multi-hits distinct.
  const jitter = (salt) => presentationHash01(state.simulationTick, audioFxDebug.impactLayers, salt) - 0.5;
  const level = state.sfxVolume;
  // Low sine sub-thump under every clean hit, bigger for the heavy tiers.
  synthToneShot({
    wave: "sine",
    from: profile.thumpHz * (1 + jitter(3) * 0.18),
    to: 36,
    seconds: profile.seconds * (1 + jitter(5) * 0.14),
    peak: profile.thump * level,
    attack: 0.004,
  });
  if (profile.noise > 0) {
    synthNoiseShot({
      seconds: profile.seconds * 0.8,
      filterType: "lowpass",
      freq: 900 * (1 + jitter(7) * 0.3),
      freqEnd: 160,
      peak: profile.noise * level,
    });
  }
  if (counter) {
    // Sharper crunch transient so counter hits snap out of the mix.
    synthNoiseShot({
      seconds: 0.055,
      filterType: "highpass",
      freq: 1500 * (1 + jitter(11) * 0.2),
      q: 0.9,
      peak: 0.05 * level,
      attack: 0.002,
    });
  }
  if (profile.ring) {
    // Inharmonic partial pair (1 : 1.5024) reads as struck metal.
    const ringHz = 1160 * (1 + jitter(13) * 0.12);
    synthToneShot({
      wave: "triangle", from: ringHz, seconds: 0.42, peak: 0.026 * level,
      attack: 0.002, filterType: "bandpass", freq: ringHz, q: 6,
    });
    synthToneShot({
      wave: "triangle", from: ringHz * 1.5024, seconds: 0.3, peak: 0.017 * level,
      attack: 0.002, filterType: "bandpass", freq: ringHz * 1.5024, q: 6,
    });
  }
}

// --- w51 announcer/clock truth: dizzy ring + clock tick synths -------------

/**
 * Dizzy ring: three triangle chirps climbing a minor-ish arpeggio on a
 * wobble LFO (engine/announcer.mjs dizzyRingPlan), replacing the knockout.mp3
 * groan enterDizzy used to play on a stun the fighter recovers from. Sim-path
 * trigger on the impactAudioAllowed guard; the variant comes from the tick
 * hash so consecutive dizzies never ring identically and no RNG stream moves.
 */
function dizzyRingAudio(fighter) {
  if (!impactAudioAllowed()) return;
  unlockAudio();
  audioFxDebug.dizzyRings += 1;
  const variant = presentationHash01(state.simulationTick, fighter?.side ?? 0, 51);
  const level = state.sfxVolume;
  for (const chirp of dizzyRingPlan(variant)) {
    synthToneShot({
      wave: "triangle", from: chirp.hz, seconds: chirp.seconds, peak: chirp.peak * level,
      attack: 0.006, filterType: "bandpass", freq: chirp.hz, q: 3,
      vibratoRate: chirp.vibratoRate, vibratoDepth: chirp.vibratoDepth, delay: chirp.delay,
    });
  }
}

/**
 * Clock tick for a displayed reading in the final ten seconds (plan in
 * engine/announcer.mjs: 880 Hz ladder, brighter and shorter under :05, a
 * square two-partial buzzer at :00). Fired from updateHud's timer edge — the
 * one place the digit changes — so it can never drift from the red pulse.
 * Same gates as every other sim-path synth; never a reviewed take.
 */
function clockTickAudio(timer) {
  const plan = clockTickPlan(timer);
  if (!plan) return;
  if (plan.kind === "buzzer") showSoundCaption("time-buzzer");
  // impactLayerAudio pattern: no unlockAudio() here — a fight has already
  // unlocked the context on its first sample play, and synthToneShot is a
  // silent no-op on a context that is not running.
  if (!impactAudioAllowed()) return;
  audioFxDebug.clockTicks += 1;
  const level = state.sfxVolume;
  if (plan.kind === "buzzer") {
    synthToneShot({ wave: plan.wave, from: plan.hz, seconds: plan.seconds, peak: plan.peak * level, attack: 0.01, filterType: "lowpass", freq: 1400, q: 0.8 });
    synthToneShot({ wave: plan.wave, from: plan.hz * 1.498, seconds: plan.seconds * 0.9, peak: plan.peak * 0.55 * level, attack: 0.01, filterType: "lowpass", freq: 1400, q: 0.8 });
    return;
  }
  synthToneShot({ wave: plan.wave, from: plan.hz, seconds: plan.seconds, peak: plan.peak * level, attack: 0.002, filterType: "bandpass", freq: plan.hz, q: 4 });
}

// Once-per-round "TEN SECONDS" call at the :10 reading. Keyed like the voice
// round tracker (matchSerial:round) so a rollback that replays the edge, or a
// paused game re-rendering the HUD, cannot book it twice; the announcer busy
// window and shuffle bag handle spacing and the no-repeat rule.
let clockCalloutRoundKey = "";

function clockCallout() {
  if (rollbackResimulating || state.phase !== "fight") return;
  if (Math.ceil(state.timer) !== CLOCK_CALLOUT_SECONDS) return;
  const key = `${state.matchSerial}:${state.round}`;
  if (key === clockCalloutRoundKey) return;
  clockCalloutRoundKey = key;
  voiceFxDebug.clockCallouts += 1;
  announcerSay("tenseconds");
}

// Pre-impact whoosh layered under the swing sample at attack start.
function impactSwingWhoosh(attack) {
  if (!attack || !impactAudioAllowed()) return;
  const kind = attack.superMove ? "super" : attack.kind;
  const size = kind === "super" ? 1 : kind === "special" ? 0.8 : kind === "heavy" ? 0.62 : 0;
  if (!size) return;
  const jitter = presentationHash01(state.simulationTick, 29) - 0.5;
  synthNoiseShot({
    seconds: 0.16 + size * 0.08,
    filterType: "bandpass",
    freq: 340 * (1 + jitter * 0.3),
    freqEnd: 1500 + size * 900,
    q: 1.4,
    peak: (0.016 + size * 0.02) * state.sfxVolume,
    attack: 0.03,
  });
}

// --- Item 21: synthesised dash scuff and stage-weapon clatter --------------

// Previous distinctDraw per synth voice so consecutive dashes (or drops) can
// never share a hiss. Draws come from the tick hash salted by the voice's
// own serial (the impactLayerAudio pattern) — never an RNG stream.
const synthVoiceLastDraw = {};

function synthVoiceDraw(name, serial) {
  let salt = 0;
  const rand = () => presentationHash01(state.simulationTick, serial, 41 + salt++);
  const draw = distinctDraw(synthVoiceLastDraw[name], rand);
  synthVoiceLastDraw[name] = draw;
  return draw;
}

/**
 * Dash scuff: a sneaker skidding on concrete instead of the borrowed
 * jump.mp3. Band-passed hiss sweeping down as the foot slows, over a short
 * sine plant for the push-off; a back dash is the heel dragging (lower,
 * longer). Sim-path trigger, so it rides impactAudioAllowed() and the tick
 * hash like the impact layers.
 */
function dashScuff(fighter) {
  if (!impactAudioAllowed()) return;
  audioFxDebug.dashScuffs += 1;
  const forward = !fighter || fighter.dashDirection === 0 || fighter.dashDirection === fighter.facing;
  const params = dashScuffParams({
    forward,
    draw: synthVoiceDraw("dash", audioFxDebug.dashScuffs),
    level: state.sfxVolume,
  });
  synthNoiseShot(params.hiss);
  synthToneShot(params.plant);
}

/**
 * Stage-weapon clatter: the object that just landed, in its own material
 * (engine/shared-sfx.mjs STAGE_WEAPON_CLATTER keyed by the weapon style) —
 * glass ring and roll for the bottle, metal tinks for the needle, wing flaps
 * for the pigeon — instead of the ui-select menu click.
 */
function weaponClatter() {
  if (!impactAudioAllowed()) return;
  audioFxDebug.weaponClatters += 1;
  const style = stageWeaponProfile()?.style || "cup";
  const params = weaponClatterParams(style, {
    draw: synthVoiceDraw("stage-weapon", audioFxDebug.weaponClatters),
    level: state.sfxVolume,
  });
  for (const tone of params.tones) synthToneShot(tone);
  for (const noise of params.noises) synthNoiseShot(noise);
}

/**
 * v5.1 TEMPO TELLS: re-arm click — the dry tick a press makes when the
 * 4-frame re-arm gap eats it (engine/shared-sfx.mjs rearmClickParams). Sim-
 * path trigger like the scuff; the distinctDraw keeps two eaten presses in
 * one gap from sharing a pitch.
 */
function rearmClick() {
  if (!impactAudioAllowed()) return;
  audioFxDebug.rearmClicks += 1;
  const params = rearmClickParams({
    draw: synthVoiceDraw("rearm-drop", audioFxDebug.rearmClicks),
    level: state.sfxVolume,
  });
  synthNoiseShot(params.tick);
  synthToneShot(params.pip);
}

/**
 * 5.3 CLOSE RANGE: clinch-break snap — the layer that separates the REACTION
 * tech (a hold broken open) from the pre-contact clash. Sim-path trigger on
 * the rearmClick pattern: impactAudioAllowed() gates resimulation and the
 * mute toggle, and the distinctDraw makes two clinch techs in a round sound
 * different by construction.
 */
function clinchTechBreak() {
  if (!impactAudioAllowed()) return;
  audioFxDebug.clinchTechBreaks += 1;
  const params = clinchTechBreakParams({
    draw: synthVoiceDraw("clinch-tech", audioFxDebug.clinchTechBreaks),
    level: state.sfxVolume,
  });
  synthNoiseShot(params.rip);
  for (const partial of params.partials) synthToneShot(partial);
}

// --- Feature: crowd audio bus driven by state.crowdReaction ----------------

// One chatter-bed voicing per crowd variant (engine/crowd.mjs). rate warps the
// shared noise loop so no two variants share a texture.
const CROWD_AUDIO_PROFILES = Object.freeze({
  street: Object.freeze({ base: 0.013, react: 0.042, filterType: "lowpass", filterBase: 430, filterReact: 950, rate: 0.72, swell: "gasp" }),
  somerset: Object.freeze({ base: 0.008, react: 0.024, filterType: "lowpass", filterBase: 360, filterReact: 720, rate: 0.66, swell: "gasp" }),
  tailgate: Object.freeze({ base: 0.021, react: 0.062, filterType: "lowpass", filterBase: 620, filterReact: 1500, rate: 0.86, swell: "roar" }),
  boardwalk: Object.freeze({ base: 0.011, react: 0.034, filterType: "lowpass", filterBase: 520, filterReact: 1050, rate: 0.78, swell: "gasp" }),
  buffet: Object.freeze({ base: 0.012, react: 0.032, filterType: "bandpass", filterBase: 1150, filterReact: 850, rate: 1.06, swell: "clatter" }),
  poolside: Object.freeze({ base: 0.017, react: 0.055, filterType: "lowpass", filterBase: 780, filterReact: 1450, rate: 0.94, swell: "whoop" }),
  vacantLot: Object.freeze({ base: 0.005, react: 0.015, filterType: "lowpass", filterBase: 300, filterReact: 480, rate: 0.6, swell: "echo" }),
});

// Eased applied bus level (0-1), exposed as snapshot().violence.crowdBusLevel.
let crowdAudioLevel = 0;
let crowdBed = null;
// One-shot swell latch fed by stirCrowd (sim path, guarded + tick-deduped).
let crowdSwellPending = 0;
let crowdSwellTick = -1;
// v5.1: the pending swell's kind ("ko" for the round-winning hit, "" else).
let crowdSwellPendingKind = "";
// Post-fatal-blow bed swell and its render-side edge observer.
let crowdKillSwell = 0;
let crowdObservedKillHits = 0;

function latchCrowdSwell(amount, kind = "") {
  if (rollbackResimulating || crowdSwellTick === state.simulationTick) return;
  crowdSwellTick = state.simulationTick;
  crowdSwellPending = Math.max(crowdSwellPending, Math.min(1.6, amount));
  if (kind) crowdSwellPendingKind = kind;
}

function buildCrowdBed(variant) {
  const profile = CROWD_AUDIO_PROFILES[variant] || CROWD_AUDIO_PROFILES.street;
  const bus = masterBusInput();
  const buffer = ambientNoiseBuffer();
  if (!bus || !buffer) return null;
  const source = state.audio.createBufferSource();
  source.buffer = buffer;
  source.loop = true;
  source.playbackRate.value = profile.rate;
  const filter = state.audio.createBiquadFilter();
  filter.type = profile.filterType;
  filter.frequency.value = profile.filterBase;
  filter.Q.value = 0.9;
  const gain = state.audio.createGain();
  gain.gain.value = 0.0001;
  source.connect(filter).connect(gain).connect(bus);
  source.start();
  audioPersistentNodes += 3;
  audioFxDebug.nodesCreated += 3;
  return { variant, profile, source, filter, gain };
}

function teardownCrowdBed() {
  if (!crowdBed) return;
  try { crowdBed.source.stop(); } catch { /* already stopped */ }
  crowdBed.source.disconnect();
  crowdBed.filter.disconnect();
  crowdBed.gain.disconnect();
  audioPersistentNodes = Math.max(0, audioPersistentNodes - 3);
  crowdBed = null;
}

function playCrowdSwell(variant, amount, kind = "") {
  const profile = CROWD_AUDIO_PROFILES[variant] || CROWD_AUDIO_PROFILES.street;
  const strength = clamp(amount / 1.4, 0.25, 1.15);
  const level = state.sfxVolume;
  const jitter = presentationHash01(state.simulationTick, audioFxDebug.crowdSwells) - 0.5;
  if (kind === "ko") {
    // v5.1 KO MOMENT: the KO gets its own recipe under the voiced roar — a
    // slower, longer, lower swell (0.25 s attack, ~2 s) with a second late
    // wave at 0.9 s — so the round-winning hit never reuses the mid-round
    // gasp/whoop the crowd just made for a throw.
    synthNoiseShot({ seconds: 1.6 + strength * 0.6, filterType: "lowpass", freq: 520 + strength * 520, freqEnd: 360, peak: 0.055 * strength * level, attack: 0.25 });
    synthNoiseShot({ seconds: 1.2, filterType: "bandpass", freq: 760 * (1 + jitter * 0.15), q: 1.1, peak: 0.028 * strength * level, attack: 0.2, delay: 0.9 });
    return;
  }
  switch (profile.swell) {
    case "roar":
      synthNoiseShot({ seconds: 0.9 + strength * 0.5, filterType: "lowpass", freq: 700 + strength * 700, freqEnd: 420, peak: 0.05 * strength * level, attack: 0.16 });
      break;
    case "whoop":
      synthNoiseShot({ seconds: 0.6 + strength * 0.3, filterType: "bandpass", freq: 900, q: 1.2, peak: 0.038 * strength * level, attack: 0.1 });
      synthToneShot({ wave: "triangle", from: 520 * (1 + jitter * 0.2), to: 980, seconds: 0.34, peak: 0.014 * strength * level, attack: 0.05, filterType: "bandpass", freq: 800, q: 2 });
      break;
    case "clatter":
      synthNoiseShot({ seconds: 0.5, filterType: "bandpass", freq: 1400, q: 1.4, peak: 0.03 * strength * level, attack: 0.06 });
      synthToneShot({ wave: "triangle", from: 2300 * (1 + jitter * 0.3), seconds: 0.16, peak: 0.012 * strength * level, attack: 0.002, filterType: "bandpass", freq: 2300, q: 7, delay: 0.09 });
      break;
    case "echo":
      // Janney: one sparse gasp and its late slap-back off the rowhomes.
      synthNoiseShot({ seconds: 0.42, filterType: "bandpass", freq: 420, q: 1.6, peak: 0.02 * strength * level, attack: 0.05 });
      synthNoiseShot({ seconds: 0.36, filterType: "bandpass", freq: 380, q: 1.6, peak: 0.009 * strength * level, attack: 0.05, delay: 0.24 });
      break;
    default:
      synthNoiseShot({ seconds: 0.55 + strength * 0.3, filterType: "lowpass", freq: 520 + strength * 520, freqEnd: 300, peak: 0.04 * strength * level, attack: 0.12 });
  }
}

// --- v5.1 KO MOMENT: the voiced crowd ---------------------------------------
// Twelve generated takes (assets/audio/crowd/, engine/crowd-voice.mjs) played
// OVER the synth swell, never instead of it. Module-level render state on the
// announcer pattern: HTMLAudio takes per cue, a shuffle bag per cue (every
// take once per bag, no repeat across the border), a per-cue minimum gap and
// a shared busy window so a gasp never lands on a roar still sounding. The
// level is the cue's base volume scaled by the stir amount (crowdVoiceLevel)
// and the SFX slider. Nothing here reads back into the simulation.
const crowdVoiceBanks = new Map();
const crowdVoiceBags = new Map();
const crowdVoiceLastAt = new Map();
let crowdVoiceBusyUntil = 0;
// The last dozen plays as "cue-take", newest last (snapshot().violence).
const crowdVoiceRecent = [];
let lastCrowdVoice = null;

function crowdVoiceBank(cue) {
  let bank = crowdVoiceBanks.get(cue);
  if (bank) return bank;
  const spec = CROWD_VOICE_CUES[cue];
  bank = [];
  for (let take = 1; take <= (spec?.takes || 0); take += 1) {
    const sample = new Audio(crowdVoicePath(cue, take));
    sample.preload = "auto";
    bank.push(sample);
  }
  crowdVoiceBanks.set(cue, bank);
  return bank;
}

function ensureCrowdVoiceMedia() {
  for (const cue of Object.keys(CROWD_VOICE_CUES)) crowdVoiceBank(cue);
}

/**
 * Play one voiced crowd take. `amount` is the stir amount the reaction
 * answers (sets the level); `source` is bookkeeping for the recent log.
 * Returns the take index played, or -1 when a gate held it back.
 */
function playCrowdVoice(cue, amount, { source = "" } = {}) {
  if (rollbackResimulating || !cue) return -1;
  const spec = CROWD_VOICE_CUES[cue];
  if (!spec) return -1;
  if (!$("#soundToggle")?.checked || !(state.sfxVolume > 0)) return -1;
  if (demoSession.attract && !state.audioUnlocked) return -1;
  const now = performance.now();
  if (now - (crowdVoiceLastAt.get(cue) ?? -Infinity) < spec.minGapMs) return -1;
  if (!spec.layers && now < crowdVoiceBusyUntil) return -1;
  const bank = crowdVoiceBank(cue);
  if (!bank.length) return -1;
  let bag = crowdVoiceBags.get(cue);
  if (!bag || bag.size !== bank.length) {
    bag = createCrowdVoiceBag(bank.length);
    crowdVoiceBags.set(cue, bag);
  }
  const take = crowdVoiceBagDraw(bag, visualRandom);
  const sample = bank[take];
  unlockAudio();
  showSoundCaption("crowd-voice", null, spec.caption);
  sample.pause();
  sample.currentTime = 0;
  sample.volume = clamp(spec.volume * crowdVoiceLevel(amount) * state.sfxVolume, 0, 1);
  const playback = sample.play();
  if (playback?.catch) playback.catch(() => {});
  crowdVoiceLastAt.set(cue, now);
  crowdVoiceBusyUntil = Math.max(crowdVoiceBusyUntil, now + spec.busyMs);
  audioFxDebug.crowdVoicePlays += 1;
  lastCrowdVoice = Object.freeze({ cue, take: take + 1, amount, source, level: Number(sample.volume.toFixed(3)) });
  crowdVoiceRecent.push(`${cue}-${take + 1}`);
  while (crowdVoiceRecent.length > 12) crowdVoiceRecent.shift();
  return take;
}

function updateCrowdAudio(dt) {
  const fightLive = state.screen === "fight" && state.fighters.length === 2;
  const soundOn = Boolean($("#soundToggle")?.checked) && state.sfxVolume > 0;
  // Fatality cinematics: the bed drops away pre-kill so the gore soundscape
  // owns the frame, then swells on the killing blow. The kill is observed
  // render-side via finisher.slowMotionHits (set for gore on or off).
  const finisherHits = state.finisher?.slowMotionHits || 0;
  if (fightLive && finisherHits > crowdObservedKillHits) {
    crowdKillSwell = 1;
    crowdSwellPending = Math.max(crowdSwellPending, 1.5);
  }
  crowdObservedKillHits = state.finisher ? finisherHits : 0;
  crowdKillSwell = Math.max(0, crowdKillSwell - dt / 2.6);
  const preKillDuck = state.finisher && finisherHits === 0 ? 0.12 : 1;
  // v5.1 KO MOMENT: the bed rides the held reaction too, so it stays up for
  // the whole roundover instead of breathing out 2.5 ticks after the KO.
  updateCrowdKoHoldLatch();
  const target = fightLive
    ? clamp(clamp(crowdDrawReaction() / 1.4, 0, 1) * preKillDuck + crowdKillSwell * 0.8, 0, 1)
    : 0;
  // Fast attack, slow decay — the crowd catches its breath rather than
  // snapping quiet.
  const tau = target > crowdAudioLevel ? 0.14 : 0.85;
  crowdAudioLevel += (target - crowdAudioLevel) * (1 - Math.exp(-dt / tau));
  if (crowdAudioLevel < 0.0005) crowdAudioLevel = 0;
  // One-shot swell/gasp bursts latched by stirCrowd spikes and the kill.
  if (crowdSwellPending > 0) {
    const amount = crowdSwellPending;
    const kind = crowdSwellPendingKind;
    crowdSwellPending = 0;
    crowdSwellPendingKind = "";
    if (fightLive && soundOn) {
      audioFxDebug.crowdSwells += 1;
      playCrowdSwell(state.crowd?.variant || "street", amount, kind);
      // The voiced take over the synth layer: roar for the KO and the fatal
      // blow, ooh/gasp by amount below that (engine/crowd-voice.mjs tiers).
      playCrowdVoice(kind === "ko" ? "roar" : crowdVoiceCueFor(amount), amount, { source: kind || "stir" });
    }
  }
  // The sustained cheer follows the KO roar 0.6 s into the hold, once.
  if (fightLive && soundOn && !crowdKoHold.cheerFired && crowdKoHoldAge() >= CROWD_KO_HOLD.cheerDelayTicks) {
    crowdKoHold.cheerFired = true;
    playCrowdVoice("cheer", 1.4, { source: "ko-hold" });
  }
  // v5.1 STAGE KO BEATS: the cruise ship answers the KO with its horn, once
  // per hold, never the same blast twice running (engine/ambient.mjs
  // pickKoHorn off a hash of the hold tick, so replay and live agree).
  if (fightLive && soundOn && state.stage === "cruise" && crowdKoHold.startTick >= 0 && koHorn.holdTick !== crowdKoHold.startTick) {
    koHorn.holdTick = crowdKoHold.startTick;
    koHorn.last = pickKoHorn(koHorn.last, presentationHash01(crowdKoHold.startTick, 211));
    playKoHorn(AMBIENT_KO_HORNS[koHorn.last]);
  }
  const wantBed = fightLive && soundOn && audioContextRunning();
  if (wantBed) {
    const variant = state.crowd?.variant || "street";
    if (crowdBed && crowdBed.variant !== variant) teardownCrowdBed();
    if (!crowdBed) crowdBed = buildCrowdBed(variant);
    if (crowdBed) {
      const profile = crowdBed.profile;
      const pauseDuck = state.paused ? 0.35 : 1;
      const now = state.audio.currentTime;
      crowdBed.gain.gain.setTargetAtTime(
        Math.max(0.0001, (profile.base + crowdAudioLevel * profile.react) * state.sfxVolume * pauseDuck),
        now,
        0.09,
      );
      crowdBed.filter.frequency.setTargetAtTime(profile.filterBase + crowdAudioLevel * profile.filterReact, now, 0.12);
    }
  } else if (crowdBed) teardownCrowdBed();
}

// --- Feature: dynamic music intensity via WebAudio routing -----------------

// Eased intensity (0-1), exposed as snapshot().violence.musicIntensity. Kept
// state-side so QA can read it even where the audio stack is stubbed.
let musicIntensityLevel = 0.45;
// null until routed | "failed" if the element tap ever throws | node bundle.
let musicRouting = null;
let musicDuckPulse = 0;
let musicObservedSuperDim = 0;
let musicObservedFinishPhase = false;

function ensureMusicRouting() {
  if (musicRouting || !audioContextRunning()) return musicRouting;
  const bus = masterBusInput();
  if (!bus) return null;
  try {
    // One-time tap: after this the element's output exists only inside the
    // graph. Element volume (musicBaseVolume * duck * settings) still applies
    // upstream, so duckMusic()/syncMusic() keep working exactly as before —
    // this stage only adds the intensity filter + presence gain.
    const source = state.audio.createMediaElementSource(fightMusic);
    const filter = state.audio.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 5200;
    filter.Q.value = 0.55;
    const presence = state.audio.createGain();
    presence.gain.value = 1;
    source.connect(filter).connect(presence).connect(bus);
    musicRouting = { source, filter, presence };
    audioPersistentNodes += 3;
    audioFxDebug.nodesCreated += 3;
  } catch {
    // Element already claimed or the context refused the tap — leave the
    // element's direct output alone rather than killing the music.
    musicRouting = "failed";
  }
  return musicRouting;
}

function updateMusicIntensity(dt) {
  const fightLive = state.screen === "fight" && state.fighters.length === 2;
  let target = 0.45;
  let tau = 0.4;
  if (fightLive) {
    const lowHealth = state.fighters.some((fighter) => fighter.health <= 30);
    const matchPoint = state.rounds[0] >= 1 || state.rounds[1] >= 1;
    if (lowHealth) target = 0.8;
    else if (matchPoint) target = 0.62;
    if (superDimLevel > 0.3 || state.phase === "finish") target = 1;
    if (state.phase === "roundover" && !state.finisher) target = 0.35;
    if (state.finisher) {
      // Fatality cinematic: heavy duck under the gore mix, fast.
      target = 0.12;
      tau = 0.16;
    }
  }
  // Brief duck on the super-flash / FINISH THEM edge, then the full-open ride.
  const finishNow = fightLive && state.phase === "finish";
  if ((superDimLevel > 0.25 && musicObservedSuperDim <= 0.25) || (finishNow && !musicObservedFinishPhase)) {
    musicDuckPulse = 1;
  }
  musicObservedSuperDim = superDimLevel;
  musicObservedFinishPhase = finishNow;
  musicDuckPulse = Math.max(0, musicDuckPulse - dt / 0.33);
  musicIntensityLevel += (target - musicIntensityLevel) * (1 - Math.exp(-dt / tau));
  if (!$("#musicToggle")?.checked) return;
  const routing = ensureMusicRouting();
  if (!routing || routing === "failed") return;
  const now = state.audio.currentTime;
  const open = clamp(musicIntensityLevel, 0, 1);
  // setTargetAtTime on eased levels: two smoothing stages, zero zipper noise.
  routing.filter.frequency.setTargetAtTime(650 + 16800 * open ** 1.7, now, 0.09);
  routing.presence.gain.setTargetAtTime(
    clamp((0.82 + 0.44 * open) * (1 - 0.55 * musicDuckPulse), 0.05, 1.3),
    now,
    0.08,
  );
}

// --- v5.3 SPECTACLE: music stingers + the low-health stem -------------------
// Both ride ABOVE the bed on their own elements. Nothing here reads back into
// the simulation, everything is rollback-guarded at the call sites, and both
// are silent when the music toggle is off — this is music, not SFX, so it
// obeys #musicToggle and state.musicVolume rather than the SFX slider.

function musicStingerBank(cue) {
  let bank = musicStingerBanks.get(cue);
  if (bank) return bank;
  const spec = MUSIC_STINGERS[cue];
  bank = [];
  for (let take = 1; take <= (spec?.takes || 0); take += 1) {
    const sample = new Audio(musicStingerPath(cue, take));
    sample.preload = "auto";
    bank.push(sample);
  }
  musicStingerBanks.set(cue, bank);
  return bank;
}

/**
 * Play one stinger take over the bed and duck the bed under it for the take's
 * measured length. Returns the take index played, or -1 when a gate held it.
 * The bag guarantees no take follows itself, which is the thing Jez listens
 * for — a KO that sounds identical twice in a row is worse than no stinger.
 */
function playMusicStinger(cue, { source = "" } = {}) {
  if (rollbackResimulating || !cue) return -1;
  const spec = MUSIC_STINGERS[cue];
  if (!spec) return -1;
  if (!$("#musicToggle")?.checked || !(state.musicVolume > 0)) return -1;
  if (demoSession.attract && !state.audioUnlocked) return -1;
  const bank = musicStingerBank(cue);
  if (!bank.length) return -1;
  let bag = musicStingerBags.get(cue);
  if (!bag || bag.size !== bank.length) {
    bag = createCrowdVoiceBag(bank.length);
    musicStingerBags.set(cue, bag);
  }
  const take = crowdVoiceBagDraw(bag, visualRandom);
  const sample = bank[take];
  unlockAudio();
  showSoundCaption("music-sting", null, spec.caption);
  sample.pause();
  sample.currentTime = 0;
  sample.volume = clamp(spec.volume * musicBaseVolume() * state.musicVolume, 0, 1);
  const playback = sample.play();
  if (playback?.catch) playback.catch(() => {});
  // The bed steps aside for the take, then comes back on its own timer. A
  // deeper duck already in flight (the fatality's 0.1, the KO hold's 0.28)
  // wins, so a stinger never LIFTS the bed back over a cinematic.
  duckMusic(Math.min(spec.duck, state.musicDuck), spec.duckMs);
  audioFxDebug.stingerPlays += 1;
  lastMusicSting = Object.freeze({
    cue, take: take + 1, source, level: Number(sample.volume.toFixed(3)),
  });
  musicStingerRecent.push(`${cue}-${take + 1}`);
  while (musicStingerRecent.length > 12) musicStingerRecent.shift();
  return take;
}

function stopDangerStem() {
  if (!dangerStemPlaying) return;
  dangerStem.pause();
  dangerStemPlaying = false;
}

/** Element side of the crossfade: level, and start/stop at the mix edges. */
function syncDangerStem() {
  const wanted = dangerStemGain(dangerStemLevel) * state.musicDuck * musicBaseVolume() * state.musicVolume;
  dangerStem.volume = clamp(wanted, 0, 1);
  const live = dangerStemLevel > 0.002
    && Boolean($("#musicToggle")?.checked)
    && state.musicVolume > 0
    && !document.hidden
    && !state.paused;
  if (!live) {
    stopDangerStem();
    return;
  }
  if (dangerStem.paused) {
    const playback = dangerStem.play();
    if (playback?.catch) playback.catch(() => {});
  }
  dangerStemPlaying = true;
}

/**
 * Ease the danger mix toward its target and hand both halves of the
 * crossfade to syncMusic (bed) and syncDangerStem (stem). Render-clock only.
 */
function updateMusicLayer(dt) {
  const previous = dangerStemLevel;
  const target = dangerStemTarget({
    fightLive: state.screen === "fight" && state.fighters.length === 2,
    phase: state.phase,
    finisher: Boolean(state.finisher),
    healths: state.fighters.map((fighter) => fighter.health),
  });
  dangerStemLevel = dangerStemStep(dangerStemLevel, target, dt);
  if (previous <= 0.5 && dangerStemLevel > 0.5) audioFxDebug.dangerStemEnters += 1;
  // Only touch the elements when the mix is actually moving or sounding —
  // syncMusic is otherwise the sole owner of fightMusic.volume.
  if (Math.abs(dangerStemLevel - previous) > 0.0005 || dangerStemPlaying) syncMusic();
}

// --- Feature: per-stage ambience beds --------------------------------------

// One shared ambience engine, per-stage parameter tables. Layers are
// persistent loops (noise/tone + filter + gain + optional gain-LFO); events
// are sparse one-shots on their own render-clock cadence. Everything sits far
// below the music and ducks with it during cinematics.
const AMBIENCE_PROFILES = Object.freeze({
  somerset: Object.freeze({
    layers: Object.freeze([
      // Distant traffic wash.
      Object.freeze({ kind: "noise", rate: 0.6, filterType: "lowpass", filterFreq: 280, q: 0.7, gain: 0.02, lfoRate: 0.07, lfoDepth: 0.3 }),
      // Substation hum under the el structure.
      Object.freeze({ kind: "tone", wave: "sawtooth", freq: 51, filterType: "lowpass", filterFreq: 130, q: 0.7, gain: 0.006, lfoRate: 0.11, lfoDepth: 0.25 }),
      // El-train rumble; gain is driven by the train visual's x position.
      Object.freeze({ kind: "noise", rate: 0.42, filterType: "bandpass", filterFreq: 105, q: 1.2, gain: 0.028, train: true }),
    ]),
    events: Object.freeze([]),
  }),
  vet: Object.freeze({
    layers: Object.freeze([
      Object.freeze({ kind: "noise", rate: 0.66, filterType: "lowpass", filterFreq: 240, q: 0.7, gain: 0.02, lfoRate: 0.05, lfoDepth: 0.5 }),
    ]),
    events: Object.freeze([Object.freeze({ kind: "stadiumSwell", min: 13, max: 30 })]),
  }),
  wildwood: Object.freeze({
    layers: Object.freeze([
      // Surf, deep slow LFO.
      Object.freeze({ kind: "noise", rate: 0.7, filterType: "lowpass", filterFreq: 430, q: 0.6, gain: 0.024, lfoRate: 0.09, lfoDepth: 0.7 }),
      // Faint carousel tone drifting on the wind.
      Object.freeze({ kind: "tone", wave: "triangle", freq: 392, filterType: "bandpass", filterFreq: 420, q: 2.4, gain: 0.0035, lfoRate: 0.4, lfoDepth: 0.5, vibratoRate: 5.2, vibratoDepth: 4 }),
    ]),
    events: Object.freeze([Object.freeze({ kind: "boardwalkCreak", min: 7, max: 18 })]),
  }),
  buffet: Object.freeze({
    layers: Object.freeze([
      Object.freeze({ kind: "tone", wave: "sine", freq: 92, gain: 0.008, lfoRate: 0.9, lfoDepth: 0.12 }),
      Object.freeze({ kind: "noise", rate: 0.55, filterType: "lowpass", filterFreq: 190, q: 0.7, gain: 0.012, lfoRate: 0.06, lfoDepth: 0.2 }),
    ]),
    events: Object.freeze([Object.freeze({ kind: "kitchenClatter", min: 2.6, max: 7.5 })]),
  }),
  cruise: Object.freeze({
    layers: Object.freeze([
      // Engine drone from decks below.
      Object.freeze({ kind: "tone", wave: "sawtooth", freq: 46, filterType: "lowpass", filterFreq: 120, q: 0.8, gain: 0.01, lfoRate: 0.16, lfoDepth: 0.18 }),
      // Pool water lap.
      Object.freeze({ kind: "noise", rate: 0.8, filterType: "lowpass", filterFreq: 520, q: 0.6, gain: 0.014, lfoRate: 0.27, lfoDepth: 0.75 }),
    ]),
    events: Object.freeze([Object.freeze({ kind: "gullCry", min: 8, max: 21 })]),
  }),
  janney: Object.freeze({
    layers: Object.freeze([
      Object.freeze({ kind: "noise", rate: 0.62, filterType: "bandpass", filterFreq: 330, q: 1.1, gain: 0.018, lfoRate: 0.08, lfoDepth: 0.65 }),
    ]),
    events: Object.freeze([Object.freeze({ kind: "chainRattle", min: 6, max: 16 })]),
  }),
});

let ambienceRig = null;
// State-side engagement flag, exposed as snapshot().violence.ambienceActive.
let ambienceEngaged = false;
let ambienceNextEventAt = 0;
let ambienceEventSerial = 0;

function buildAmbienceLayer(layerSpec, master) {
  const sources = [];
  let nodeCount = 0;
  let head;
  if (layerSpec.kind === "noise") {
    const source = state.audio.createBufferSource();
    source.buffer = ambientNoiseBuffer();
    source.loop = true;
    source.playbackRate.value = layerSpec.rate || 1;
    sources.push(source);
    nodeCount += 1;
    head = source;
  } else {
    const oscillator = state.audio.createOscillator();
    oscillator.type = layerSpec.wave || "sine";
    oscillator.frequency.value = layerSpec.freq || 220;
    sources.push(oscillator);
    nodeCount += 1;
    if (layerSpec.vibratoRate) {
      const vibrato = state.audio.createOscillator();
      vibrato.frequency.value = layerSpec.vibratoRate;
      const vibratoGain = state.audio.createGain();
      vibratoGain.gain.value = layerSpec.vibratoDepth || 1;
      vibrato.connect(vibratoGain).connect(oscillator.frequency);
      sources.push(vibrato);
      nodeCount += 2;
    }
    head = oscillator;
  }
  if (layerSpec.filterType) {
    const filter = state.audio.createBiquadFilter();
    filter.type = layerSpec.filterType;
    filter.frequency.value = layerSpec.filterFreq || 400;
    filter.Q.value = layerSpec.q ?? 0.8;
    head.connect(filter);
    head = filter;
    nodeCount += 1;
  }
  const gain = state.audio.createGain();
  gain.gain.value = layerSpec.train ? 0.0001 : layerSpec.gain;
  nodeCount += 1;
  if (layerSpec.lfoRate) {
    const lfo = state.audio.createOscillator();
    lfo.frequency.value = layerSpec.lfoRate;
    const lfoGain = state.audio.createGain();
    lfoGain.gain.value = layerSpec.gain * (layerSpec.lfoDepth || 0.3);
    lfo.connect(lfoGain).connect(gain.gain);
    sources.push(lfo);
    nodeCount += 2;
  }
  head.connect(gain).connect(master);
  for (const source of sources) source.start();
  return { spec: layerSpec, gain, sources, nodeCount };
}

function buildAmbienceRig(stageId) {
  const profile = AMBIENCE_PROFILES[stageId];
  const bus = masterBusInput();
  if (!profile || !bus || !ambientNoiseBuffer()) return null;
  const master = state.audio.createGain();
  master.gain.value = 0.0001;
  master.connect(bus);
  let nodeCount = 1;
  const layers = [];
  for (const layerSpec of profile.layers) {
    const layer = buildAmbienceLayer(layerSpec, master);
    nodeCount += layer.nodeCount;
    layers.push(layer);
  }
  audioPersistentNodes += nodeCount;
  audioFxDebug.nodesCreated += nodeCount;
  return { stage: stageId, master, layers, nodeCount };
}

function teardownAmbienceRig() {
  if (!ambienceRig) return;
  for (const layer of ambienceRig.layers) {
    for (const source of layer.sources) {
      try { source.stop(); } catch { /* never started */ }
    }
    layer.gain.disconnect();
  }
  ambienceRig.master.disconnect();
  audioPersistentNodes = Math.max(0, audioPersistentNodes - ambienceRig.nodeCount);
  ambienceRig = null;
}

// The ship's horn: two sawtooth reeds a fifth apart through a 600 Hz lowpass
// (the chord of a real whistle), a breath of noise on the attack, one or two
// blasts per the horn spec. Presentation audio, render-side, off the KO hold.
const koHorn = { holdTick: -1, last: -1 };

function playKoHorn(horn) {
  if (!horn || !audioContextRunning()) return;
  const level = state.sfxVolume;
  audioFxDebug.koHorns += 1;
  for (let blast = 0; blast < horn.blasts; blast += 1) {
    const delay = blast * (horn.seconds + horn.gap);
    synthToneShot({ delay, wave: "sawtooth", from: horn.from, seconds: horn.seconds, peak: horn.peak * level, attack: 0.12, filterType: "lowpass", freq: 600, q: 1.1, vibratoRate: 5.5, vibratoDepth: 1.6 });
    synthToneShot({ delay, wave: "sawtooth", from: horn.fifth, seconds: horn.seconds, peak: horn.peak * 0.6 * level, attack: 0.14, filterType: "lowpass", freq: 900, q: 1.1, vibratoRate: 4.8, vibratoDepth: 2.2 });
    synthNoiseShot({ delay, seconds: 0.28, filterType: "bandpass", freq: 420, q: 1.4, peak: 0.018 * level, attack: 0.04 });
  }
}

function playAmbienceEvent(kind) {
  const level = state.sfxVolume;
  const hash = (salt) => presentationHash01(ambienceEventSerial, salt);
  switch (kind) {
    case "stadiumSwell":
      synthNoiseShot({ seconds: 2.6 + hash(3) * 1.6, filterType: "bandpass", freq: 480 + hash(5) * 220, q: 0.9, peak: 0.014 * level, attack: 1.1 });
      break;
    case "boardwalkCreak":
      synthToneShot({ wave: "sawtooth", from: 150 * (0.85 + hash(3) * 0.4), to: 68, seconds: 0.4, peak: 0.007 * level, attack: 0.06, filterType: "lowpass", freq: 620, q: 1.2 });
      break;
    case "kitchenClatter": {
      const ticks = 2 + Math.floor(hash(3) * 3);
      for (let index = 0; index < ticks; index += 1) {
        synthNoiseShot({ delay: index * (0.05 + hash(7 + index) * 0.07), seconds: 0.035, filterType: "highpass", freq: 2300, peak: 0.011 * level, attack: 0.002 });
      }
      synthToneShot({ wave: "triangle", from: 2600 * (0.9 + hash(11) * 0.3), seconds: 0.22, peak: 0.006 * level, attack: 0.002, filterType: "bandpass", freq: 2600, q: 8, delay: 0.04 });
      break;
    }
    case "gullCry": {
      const cries = 1 + (hash(3) < 0.4 ? 1 : 0);
      for (let index = 0; index < cries; index += 1) {
        synthToneShot({ wave: "triangle", from: 1500 * (0.9 + hash(5 + index) * 0.25), to: 940, seconds: 0.4, peak: 0.007 * level, attack: 0.05, filterType: "bandpass", freq: 1300, q: 3, vibratoRate: 9, vibratoDepth: 70, delay: index * 0.5 });
      }
      break;
    }
    case "chainRattle": {
      const ticks = 3 + Math.floor(hash(3) * 3);
      for (let index = 0; index < ticks; index += 1) {
        synthToneShot({ wave: "square", from: 1750 * (0.85 + hash(9 + index) * 0.4), seconds: 0.045, peak: 0.005 * level, attack: 0.002, filterType: "highpass", freq: 1250, delay: index * (0.04 + hash(17 + index) * 0.05) });
      }
      break;
    }
    default:
      break;
  }
}

function updateAmbienceAudio(time, dt) {
  // Stage select previews the highlighted stage at half level; fights run at
  // full level; every other screen is silent (and tears the rig down).
  const wantScreens = state.screen === "fight" || state.screen === "stage";
  const soundOn = Boolean($("#soundToggle")?.checked) && state.sfxVolume > 0;
  ambienceEngaged = wantScreens && soundOn;
  if (!ambienceEngaged) {
    ambienceNextEventAt = 0;
    if (ambienceRig) teardownAmbienceRig();
    return;
  }
  const profile = AMBIENCE_PROFILES[state.stage];
  // Event cadence runs off the render clock (not the context clock) so the
  // rhythm — and the QA counter — never depend on audio backend state.
  if (profile?.events.length) {
    if (!ambienceNextEventAt) ambienceNextEventAt = time + 2500 + presentationHash01(ambienceEventSerial, 61) * 4000;
    if (time >= ambienceNextEventAt) {
      ambienceEventSerial += 1;
      const roll = presentationHash01(ambienceEventSerial, 97);
      const event = profile.events[Math.floor(roll * profile.events.length) % profile.events.length];
      audioFxDebug.ambienceEvents += 1;
      if (state.screen === "fight") playAmbienceEvent(event.kind);
      ambienceNextEventAt = time + (event.min + presentationHash01(ambienceEventSerial, 131) * (event.max - event.min)) * 1000;
    }
  } else ambienceNextEventAt = 0;
  if (!audioContextRunning()) return;
  if (ambienceRig && ambienceRig.stage !== state.stage) teardownAmbienceRig();
  if (!ambienceRig) ambienceRig = buildAmbienceRig(state.stage);
  if (!ambienceRig) return;
  const now = state.audio.currentTime;
  const cinematicDuck = state.finisher ? 0.25 : 1;
  const preview = state.screen === "stage" ? 0.5 : 1;
  const pauseDuck = state.paused ? 0.35 : 1;
  // Follows musicDuck so cinematic ducks pull the bed down with the music.
  const target = clamp(state.sfxVolume, 0, 1) * cinematicDuck * preview * pauseDuck * (0.35 + 0.65 * state.musicDuck);
  ambienceRig.master.gain.setTargetAtTime(Math.max(0.0001, target), now, 0.25);
  // Somerset: El-train rumble loosely follows the moving train-light layer.
  const trainLayer = ambienceRig.layers.find((layer) => layer.spec.train);
  if (trainLayer) {
    const trainX = ((time * 0.08) % (W + 650)) - 500;
    const visible = trainX > -430 && trainX < W;
    trainLayer.gain.gain.setTargetAtTime(visible ? trainLayer.spec.gain : 0.0001, now, 0.6);
  }
}

// Hidden tabs stop the render loop; drop the beds instantly so they cannot
// drone at their last eased level until the tab returns.
function muteRenderAudioBeds() {
  if (!state.audio) return;
  const now = state.audio.currentTime;
  if (crowdBed) crowdBed.gain.gain.setTargetAtTime(0.0001, now, 0.06);
  if (ambienceRig) ambienceRig.master.gain.setTargetAtTime(0.0001, now, 0.06);
}

// --- Wave 9: spoken announcer bank system ----------------------------------
// Banks live at assets/audio/announcer/<cue>-<n>.mp3. None of those files
// exist yet (ElevenLabs auth is down): every cue still fires — the caption
// always shows its line — and each bank is HEAD-probed exactly once per
// session, so real takes drop in the moment they land on disk. All module
// state below is render-side (announce() pattern), never snapshotted, and
// its only randomness is visualRandom (checksum-exempt) — never state.rng.

const ANNOUNCER_MAX_TAKES = 5;

// cue -> index of the authored line its 2.8 retake re-reads (applied at the
// end of ANNOUNCER_LINES below).
const ANNOUNCER_RETAKES = Object.freeze({
  ko: 0,
  perfect: 0,
  finishthem: 0,
  wallbounce: 0,
  "cyraxx-wins": 0,
  flawless: 0,
});

// One line per planned take, mirrored exactly by MISSING-AUDIO.md — the
// caption index and the mp3 take index stay aligned as files appear.
const ANNOUNCER_LINES = (() => {
  const banks = {
    round1: ["ROUND ONE", "ROUND ONE — SETTLE IT", "FIRST ROUND — FIGHT'S ON"],
    round2: ["ROUND TWO", "SECOND ROUND", "ROUND TWO — NO MERCY"],
    finalround: ["FINAL ROUND", "LAST ROUND — MAKE IT COUNT", "THE FINAL ROUND"],
    fight: ["FIGHT!", "GET IT ON!", "THROW DOWN!", "GO!"],
    finishthem: ["FINISH THEM!", "END THIS!", "PUT THEM DOWN!"],
    ko: ["K.O.!", "KNOCKOUT!", "IT'S OVER!", "LIGHTS OUT!"],
    perfect: ["PERFECT!", "UNTOUCHABLE!", "NOT A SCRATCH!"],
    flawless: ["FLAWLESS VICTORY!", "AN ABSOLUTE SHUTOUT!"],
    comeback: ["WHAT A COMEBACK!", "BACK FROM THE DEAD!", "NEVER COUNT THEM OUT!"],
    timeover: ["TIME OVER — DECISION!", "THE CLOCK CALLS IT!", "TIME! JUDGES' DECISION!"],
    // w51 clock truth: spoken once per round when the clock reads :10.
    // TODO(tenseconds-takes): no recorded takes exist yet — the cue is absent
    // from assets/audio/announcer/MANIFEST.json so it is caption-only (zero
    // requests) until the owner approves generating tenseconds-1..3.mp3 with
    // the announcer voice (work order in MISSING-AUDIO.md, Priority 6). The
    // synthesised clock tick carries the moment audibly meanwhile.
    tenseconds: ["TEN SECONDS!", "CLOCK'S RUNNING!", "TIME'S ALMOST UP!"],
    "fatality-performed": ["FATALITY.", "A GRAPHIC FINISH.", "THAT WAS A FINAL BLOW."],
    // Release 1.7 DEPTH: the guard-crush letter-slam's spoken call.
    guardcrush: ["GUARD CRUSH!", "DEFENSE SHATTERED!", "THE GUARD BREAKS!"],
    // Release 1.7 wave 11: the corner wall-bounce conversion.
    wallbounce: ["OFF THE WALL!", "CORNER CARNAGE!", "THE WALL HITS BACK!"],
    "boss-intro": ["THE FINAL AUTHORITY STEPS IN.", "FINAL BOUT — THE BLACK BOOK CLOSES TONIGHT.", "THE COMMISSIONER IS WAITING."],
    connected: ["CHALLENGER CONNECTED!", "YOUR OPPONENT HAS ENTERED!", "THE WIRE IS LIVE!"],
    setpoint: ["SET POINT!", "ONE ROUND FROM GLORY!", "THE MATCH IS ON THE LINE!"],
    rematch: ["REMATCH ACCEPTED!", "RUN IT BACK!", "ONE MORE TIME!"],
    recovered: ["CONNECTION RESTORED!", "BACK IN SYNC!", "THE LINK HOLDS!"],
  };
  for (const { id, name } of roster) {
    banks[`${id}-name`] = [name, name, name];
    banks[`${id}-wins`] = [`${name} WINS!`, `THE WINNER — ${name}!`, `${name} TAKES IT!`];
  }
  // 2.8 filled six banks with an extra take each (ko-5, perfect-4,
  // finishthem-4, wallbounce-4, cyraxx-wins-4, flawless-3), every one a
  // re-read of that bank's FIRST line (whisper-transcribed 2026-09-05: "K.O.",
  // "Perfect!", "Finish them!", "Off the wall", "Cyraxx wins!", "Flawless
  // victory"). Until 5.1 the caption list stopped short of them, so `pick %
  // lines.length` captioned the extra take with the wrong words — the retake
  // table appends the line each one actually speaks so caption == take.
  for (const [cue, lineIndex] of Object.entries(ANNOUNCER_RETAKES)) {
    banks[cue] = [...banks[cue], banks[cue][lineIndex]];
  }
  return Object.freeze(banks);
})();

// Shuffle bags per cue: every take plays once before any repeats, and the
// reshuffle never lets the same take land back-to-back across bag borders.
// w51: the draw itself lives in engine/announcer.mjs (drawFromBag) so the
// no-repeat rule is unit tested; this keeps the checksum-exempt RNG hookup.
const announcerBags = new Map();

function announcerBagDraw(cue, size) {
  return drawFromBag(announcerBags, cue, size, visualRandom);
}

// cue -> { takes: [Audio...], durationsMs, probed }. 5.1: takes AND their
// measured lengths come from assets/audio/MANIFEST.json (the shared
// build-time manifest — see loadAudioManifest), so the picker is CLAMPED to
// takes that exist and the speech clock knows how long each one runs. Two
// fallbacks keep the pre-5.1 behaviour when that file is missing: the 2.7
// announcer-only assets/audio/announcer/MANIFEST.json (take counts, no
// lengths), then the sequential HEAD probe that discovered each bank's end by
// 404ing one request past it (flawless-3, ko-5, wallbounce-4, ...) on every
// cue a session touched; both still stop at the first gap. Lengths unknown to
// the manifest are picked up from each element's loadedmetadata.
const announcerBankCache = new Map();
let announcerManifestPromise = null;

function announcerTakeCounts() {
  if (!announcerManifestPromise) {
    announcerManifestPromise = fetch("assets/audio/announcer/MANIFEST.json")
      .then((response) => (response.ok ? response.json() : null))
      .then((manifest) => (manifest?.takes && typeof manifest.takes === "object" ? manifest.takes : null))
      .catch(() => null);
  }
  return announcerManifestPromise;
}

function fillAnnouncerBank(bank, srcs, durationsMs = []) {
  bank.takes = srcs.map((src, index) => {
    const sample = new Audio(src);
    sample.preload = "auto";
    if (!(durationsMs[index] > 0)) {
      sample.addEventListener("loadedmetadata", () => {
        if (!(bank.durationsMs[index] > 0) && Number.isFinite(sample.duration) && sample.duration > 0) {
          bank.durationsMs[index] = Math.round(sample.duration * 1000);
        }
      }, { once: true });
    }
    return sample;
  });
  bank.durationsMs = srcs.map((_, index) => durationsMs[index] || 0);
  bank.probed = true;
  if (srcs.length) voiceFxDebug.announcerBanksLoaded += 1;
}

function announcerBank(cue) {
  let bank = announcerBankCache.get(cue);
  if (bank) return bank;
  bank = { cue, takes: [], durationsMs: [], probed: false };
  announcerBankCache.set(cue, bank);
  const settleFromManifest = (manifest) => {
    const resolved = announcerBankFromManifest(manifest, cue, ANNOUNCER_MAX_TAKES);
    if (!resolved) return false;
    fillAnnouncerBank(bank, resolved.srcs, resolved.durationsMs);
    voiceFxDebug.manifestBanks += 1;
    return true;
  };
  // The manifest usually settled at boot, so a bank fills synchronously and
  // the very first call on a cue already knows its takes and their lengths.
  if (audioManifestState.settled && settleFromManifest(audioManifestState.data)) return bank;
  (async () => {
    if (!audioManifestState.settled && settleFromManifest(await loadAudioManifest())) return;
    const counts = await announcerTakeCounts();
    const found = [];
    if (counts) {
      // A cue absent from the manifest has zero recorded takes: no requests.
      const count = Math.min(ANNOUNCER_MAX_TAKES, Math.max(0, Math.floor(Number(counts[cue]) || 0)));
      for (let take = 1; take <= count; take += 1) {
        found.push(`assets/audio/announcer/${cue}-${take}.mp3`);
      }
    } else {
      for (let take = 1; take <= ANNOUNCER_MAX_TAKES; take += 1) {
        const src = `assets/audio/announcer/${cue}-${take}.mp3`;
        if (!(await probeAudioFile(src))) break;
        found.push(src);
      }
    }
    fillAnnouncerBank(bank, found);
  })();
  return bank;
}

// Serialised speech clock: each accepted call reserves a busy window so
// layered calls (KO -> fighter-wins -> story) never talk over each other.
// Before 5.1 the window was announcerEstimateMs (word count, capped at
// 1.7 s) while real takes run to 4676 ms (benny-wins-2): a Benny comeback KO
// drawing ko-2 (2429 ms) started the wins call at 950 ms and "comeback" at
// 2500 ms with benny-wins-2 still going — three takes stacked and the duck
// released mid-line. The window now comes from the take's measured length
// (announcerTakeMs), and the same number drives the music duck.
let announcerBusyUntil = 0;

function announcerTakeMs(bank, takeIndex, line) {
  if (takeIndex >= 0) {
    if (bank.durationsMs[takeIndex] > 0) return bank.durationsMs[takeIndex];
    const take = bank.takes[takeIndex];
    if (take && Number.isFinite(take.duration) && take.duration > 0) return Math.round(take.duration * 1000);
  }
  return announcerEstimateMs(line);
}

/**
 * Queue a spoken announcer line. Same guard discipline as announce(): early
 * return during rollback resimulation, everything downstream render-side.
 * The caption always shows the exact line even with zero mp3 assets; music
 * ducks under real takes only.
 */
function announcerSay(cue, { delay = 0 } = {}) {
  if (rollbackResimulating) return false;
  const lines = ANNOUNCER_LINES[cue];
  if (!lines?.length) return false;
  voiceFxDebug.announcerCalls += 1;
  const bank = announcerBank(cue);
  const now = performance.now();
  const pick = announcerBagDraw(cue, Math.max(lines.length, bank.takes.length));
  const line = lines[pick % lines.length];
  const takeIndex = bank.takes.length ? pick % bank.takes.length : -1;
  const speechMs = announcerTakeMs(bank, takeIndex, line);
  const slot = announcerWindow({ now, delay, busyUntil: announcerBusyUntil, speechMs, line });
  const { startAt } = slot;
  announcerBusyUntil = slot.busyUntil;
  window.setTimeout(() => {
    showSoundCaption("announcer", null, line);
    if (!$("#soundToggle").checked) return;
    if (demoSession.attract && !state.audioUnlocked) return;
    const take = takeIndex >= 0 ? bank.takes[takeIndex] : null;
    if (!take) return;
    unlockAudio();
    duckMusic(0.45, Math.max(750, speechMs));
    take.pause();
    take.currentTime = 0;
    take.volume = 0.9 * state.sfxVolume;
    const playback = take.play();
    if (playback?.catch) playback.catch(() => {});
  }, Math.max(0, startAt - now));
  return true;
}

// Banner -> spoken cue map. Runs inside announce() after its rollback guard,
// so every existing announce call site (round intros, FIGHT, FINISH THEM,
// KO, FINAL BLOW) gains the spoken call without new sim-path hooks.
function announcerSpeakBanner(text, plan = null) {
  // w51: an explicit cue plan (finishRound's roundEndAnnouncerPlan) wins
  // over the text map — it knows decision-vs-KO and round-vs-match.
  if (Array.isArray(plan)) {
    if (plan[0]?.cue === "timeover") voiceFxDebug.decisionCalls += 1;
    for (const { cue, delay = 0 } of plan) announcerSay(cue, { delay });
    return;
  }
  // v5.3 (sweep #52): the banner -> cue ladder is engine/announcer.mjs
  // (bannerAnnouncerPlan), so "ROUND 3 speaks finalround" and "a text-only
  // WINS books the NAME bank, never -wins" are asserted facts rather than
  // lines of an if-chain nothing tests. The roster lookup is passed in; this
  // file keeps the speech itself and the one non-speech side effect.
  const banner = bannerAnnouncerPlan(text, {
    fighterIdForName: (name) => roster.find((entry) => entry.name === name)?.id || "",
  });
  for (const { cue, delay = 0 } of banner.plan) announcerSay(cue, { delay });
  // The sheets had the intro to themselves; from FIGHT! the fighters' voice
  // takes may pull their remaining bytes (see warmFighterAudio).
  if (banner.warmFighterVoices) topUpFighterAudio();
}

// --- Wave 9: reactive fighter cues + match-story callouts ------------------

// Sim-path reactive voice trigger: announce() pattern (resim guard) plus a
// per-cue simulationTick dedupe, mirroring the camera latches.
const reactiveCueTicks = new Map();

// Release 1.7 wave 11 — taunt voice payoff. The LINE INDEX was already drawn
// from state.rng inside performTaunt (sim state, checksummed); this side is
// pure presentation on the announce() guard discipline. The caption always
// shows the exact authored line; audio plays the matching bank variant when
// its take exists and falls back to the pitch-shifted placeholder until then.
function fighterTauntCue(fighter, line = 0) {
  if (rollbackResimulating) return;
  voiceFxDebug.reactiveCues += 1;
  const fighterId = fighterSoundId(fighter);
  const lineText = FIGHTER_TAUNT_LINES[fighterId]?.[line] || "";
  showSoundCaption("taunt", fighter, lineText);
  if (!$("#soundToggle").checked) return;
  if (demoSession.attract && !state.audioUnlocked) return;
  unlockAudio();
  const bank = fighterVoiceBank(fighterId, "taunt");
  const src = bank?.srcs?.[line];
  const pool = src ? fighterVoicePool("taunt", bank.key, line, src) : null;
  const sample = pool?.[0];
  if (sample) {
    voiceFxDebug.voiceVariantPlays += 1;
    sample.pause();
    sample.currentTime = 0;
    sample.preservesPitch = true;
    sample.playbackRate = 1;
    sample.volume = (sfxVolumes.taunt ?? 0.62) * state.sfxVolume;
    sample.play()?.catch?.(() => {});
    return;
  }
  // No take on disk yet: the nearest recorded cue, detuned per line so the
  // three rotating lines still read differently.
  const take = fighterVoiceTake("taunt", fighterId);
  if (!take) return;
  voiceFxDebug.voiceVariantPlays += 1;
  const fallback = take.sample;
  fallback.pause();
  fallback.currentTime = 0;
  fallback.preservesPitch = false;
  fallback.playbackRate = take.rate * (1 + line * 0.05);
  fallback.volume = (sfxVolumes.taunt ?? 0.62) * state.sfxVolume;
  fallback.play()?.catch?.(() => {});
}

function fighterReactiveCue(fighter, cue) {
  if (rollbackResimulating || reactiveCueTicks.get(cue) === state.simulationTick) return;
  reactiveCueTicks.set(cue, state.simulationTick);
  voiceFxDebug.reactiveCues += 1;
  sound(cue, fighter);
}

// Render-observed per-round health story: minimum health per side (feeds the
// COMEBACK callout) and the once-per-round desperation bark under 20%.
let voiceRoundKey = "";
let voiceRoundMinHealth = [100, 100];
const desperationFired = [false, false];

function updateVoiceCallouts() {
  if (state.screen !== "fight" || state.fighters.length !== 2) return;
  const key = `${state.matchSerial}:${state.round}`;
  if (key !== voiceRoundKey) {
    voiceRoundKey = key;
    voiceRoundMinHealth = [100, 100];
    desperationFired[0] = false;
    desperationFired[1] = false;
  }
  state.fighters.forEach((fighter, side) => {
    voiceRoundMinHealth[side] = Math.min(voiceRoundMinHealth[side], fighter.health);
    if (!desperationFired[side] && state.phase === "fight" && fighter.health > 0 && fighter.health <= 20) {
      desperationFired[side] = true;
      voiceFxDebug.reactiveCues += 1;
      sound("desperation", fighter);
    }
  });
}

// Round-story detection, called from finishRound behind a rollback guard.
// Pure reads of existing round state plus the render-observed minimum-health
// track above; deduped per round result so a resimulated finish can never
// re-queue. Callouts layer after the primary KO/FINAL BLOW call via the
// announcerSay busy window plus a base delay.
let storyRoundKey = "";

function queueStoryCallouts(winner, type) {
  const key = `${state.matchSerial}:${state.round}:${winner}:${state.rounds[winner]}`;
  if (key === storyRoundKey) return;
  storyRoundKey = key;
  const loser = state.fighters[1 - winner];
  // w51: the time-over line is no longer a layered story callout — a decision
  // OPENS on the timeover bank (finishRound's plan), so queuing it again here
  // spoke "TIME OVER — DECISION!" twice. PERFECT / COMEBACK still layer over
  // a decision when they are true.
  if (type >= 0) {
    voiceFxDebug.storyCallouts += 1;
    announcerSay("fatality-performed", { delay: 2400 });
  } else if (state.fighters[winner].health >= 100) {
    voiceFxDebug.storyCallouts += 1;
    announcerSay("perfect", { delay: 1200 });
    announcerSay("flawless", { delay: 2300 });
  } else if (voiceRoundMinHealth[winner] <= 15) {
    voiceFxDebug.storyCallouts += 1;
    announcerSay("comeback", { delay: 1400 });
  }
  // Online set point: a player is now one round from taking the match.
  if (state.mode === "online" && state.rounds[winner] === 1 && state.rounds[1 - winner] < 2) {
    voiceFxDebug.onlineMoments += 1;
    announcerSay("setpoint", { delay: 2100 });
  }
}

// --- Wave 9: online-moments hooks (UI/network side, never checksummed) -----

let rematchAnnounced = false;

function announcerOnlineMoment(cue) {
  voiceFxDebug.onlineMoments += 1;
  announcerSay(cue);
}

function checkRematchAccepted() {
  if (onlineSession.rematchVotes.size < 2) {
    rematchAnnounced = false;
    return;
  }
  if (rematchAnnounced) return;
  rematchAnnounced = true;
  announcerOnlineMoment("rematch");
}

// Per-rendered-frame audio observer, called from draw() beside the cinematic
// camera update. Levels ease state-side even where WebAudio is stubbed, so
// the QA counters stay meaningful headless; nodes are only touched when the
// context is genuinely running.
function updateAudioPresentation(time, dtMs) {
  const dt = clamp(dtMs / 1000, 0.001, 0.1);
  updateCrowdAudio(dt);
  updateMusicIntensity(dt);
  // v5.3 SPECTACLE: the low-health stem's crossfade rides the same clock.
  updateMusicLayer(dt);
  updateAmbienceAudio(time, dt);
  updateVoiceCallouts();
  // Wave 16: pre-fight dialogue card reveal rides the same per-frame observer.
  updateIntroDialogue();
}

function back(target) {
  if (target === "title") showScreen("title");
  else if (target === "select") showScreen("select");
}

function isPhoneViewport() {
  return navigator.maxTouchPoints > 0
    && window.matchMedia("(pointer: coarse)").matches
    && Math.min(window.innerWidth, window.innerHeight) <= 680;
}

function syncOrientationGate() {
  const phone = isPhoneViewport();
  const portrait = window.innerHeight > window.innerWidth;
  const blocked = phone && portrait;
  document.body.classList.toggle("orientation-blocked", blocked);
  document.body.classList.toggle("mobile-landscape", phone && !portrait);
  if (blocked) renderRotateGate();
  setOnlineLocalSuspended(blocked || document.hidden);
}

function lockLandscape() {
  if (!screen.orientation?.lock) return;
  screen.orientation.lock("landscape").catch(() => {});
}

// ---------------------------------------------------------------------------
// Portrait gate capability handling. The gate must never show a button that
// silently does nothing: iOS offers no element fullscreen at all, and in-app
// browsers (Discord's WKWebView is the reported case) additionally pin the
// webview to portrait so physically rotating the phone changes nothing either.
// Capability checks decide the gate's mode; the user agent only refines the
// wording for known in-app containers. A page cannot programmatically launch
// Safari, so the fallback gives instructions plus a copy-the-link control
// rather than pretending to.
// ---------------------------------------------------------------------------

// Render-only latch: the DOMException (or Error) name of a fullscreen request
// that failed at runtime, so the gate can say why the button disappeared.
let immersiveModeFailure = null;
// The last gate mode written to the DOM, so aria-live only announces changes.
let rotateGateRenderedMode = "";

function fullscreenRequestSupported() {
  const app = $("#app");
  if (typeof app.requestFullscreen === "function") return document.fullscreenEnabled !== false;
  return typeof app.webkitRequestFullscreen === "function";
}

// Best-effort naming of a known in-app browser. Purely cosmetic on top of the
// capability checks: it decides the copy, never whether the button works.
function inAppBrowserName() {
  const ua = navigator.userAgent || "";
  if (/discord/i.test(ua)) return "Discord";
  if (/\bFBAN|\bFBAV|Instagram|Snapchat|TikTok|musical_ly|\bLine\//i.test(ua)) return "this app";
  // A WKWebView identifies as iPhone/iPad without Safari's own token. Real
  // iOS Safari (and Chrome/Firefox on iOS) all end with "Safari/…".
  const iosDevice = /iPhone|iPad|iPod/.test(ua)
    || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  if (iosDevice && !/Safari\//.test(ua)) return "this app";
  return null;
}

function isIosDevice() {
  return /iPhone|iPad|iPod/.test(navigator.userAgent || "")
    || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}

function rotateGateMode() {
  if (document.fullscreenElement || document.webkitFullscreenElement) return "rotate-fullscreen";
  if (immersiveModeFailure) return inAppBrowserName() ? "in-app" : "request-failed";
  if (fullscreenRequestSupported()) return "immersive";
  return inAppBrowserName() ? "in-app" : "rotate-only";
}

function renderRotateGate() {
  const mode = rotateGateMode();
  if (mode === rotateGateRenderedMode) return;
  rotateGateRenderedMode = mode;
  const hint = $("#rotateGateHint");
  const fullscreenButton = $("#fullscreenButton");
  const copyButton = $("#copyGameLinkButton");
  fullscreenButton.hidden = mode !== "immersive";
  copyButton.hidden = mode !== "in-app";
  const browser = isIosDevice() ? "Safari" : "your regular browser";
  if (mode === "immersive") {
    hint.textContent = "Final Blow requires landscape on mobile.";
  } else if (mode === "rotate-fullscreen") {
    hint.textContent = "You're in fullscreen — now turn your phone sideways to play.";
  } else if (mode === "in-app") {
    const container = inAppBrowserName() || "this app";
    const why = immersiveModeFailure ? `Fullscreen was blocked (${immersiveModeFailure})` : "Fullscreen isn't available";
    hint.textContent = `${why} inside ${container}'s browser, and it usually stays locked to portrait. `
      + `Use the menu (⋯ or share) and choose “Open in ${browser}”, or copy the game link below and paste it into ${browser} — then turn your phone sideways.`;
  } else if (mode === "request-failed") {
    hint.textContent = `Fullscreen was blocked here (${immersiveModeFailure}) — turn your phone sideways to play.`;
  } else {
    hint.textContent = "Fullscreen isn't available in this browser — turn your phone sideways to play.";
  }
}

function failImmersiveMode(error) {
  immersiveModeFailure = error?.name || error?.message || "blocked";
  renderRotateGate();
}

// Wave 15: the manifest-shortcut boot router starts a mode without a user
// gesture; a fullscreen request would reject and latch a bogus gate failure,
// so the router suppresses exactly one immersive attempt.
let suppressImmersivePrompt = false;

function enterImmersiveMode() {
  if (suppressImmersivePrompt) {
    suppressImmersivePrompt = false;
    return;
  }
  if (!isPhoneViewport()) return;
  const app = $("#app");
  if (!fullscreenRequestSupported()) {
    failImmersiveMode(new Error("not supported"));
    return;
  }
  let request;
  try {
    request = app.requestFullscreen
      ? app.requestFullscreen({ navigationUI: "hide" })
      : app.webkitRequestFullscreen();
  } catch (error) {
    failImmersiveMode(error);
    return;
  }
  if (request?.then) request.then(lockLandscape).catch(failImmersiveMode);
  else lockLandscape();
}

let deferredInstallPrompt = null;

function updateOfflineBadge() {
  const badge = $("#offlineBadge");
  badge.classList.toggle("ready", state.offlineReady && navigator.onLine);
  badge.classList.toggle("offline", !navigator.onLine);
  badge.textContent = !navigator.onLine ? "OFFLINE PLAY"
    : state.offlineReady ? "OFFLINE READY" : "CACHE CHECK";
}

async function registerOfflineGame() {
  if (!("serviceWorker" in navigator)) {
    $("#offlineBadge").textContent = "ONLINE ONLY";
    return;
  }
  try {
    await navigator.serviceWorker.register("./sw.js?v=final-blow-5.3");
    await navigator.serviceWorker.ready;
    state.offlineReady = true;
    updateOfflineBadge();
  } catch (error) {
    console.warn("Final Blow offline cache unavailable", error);
    $("#offlineBadge").textContent = "ONLINE ONLY";
  }
}

// ---------------------------------------------------------------------------
// v3.3 FRESH — a returning ONLINE player must land on the current build
// without knowing what a hard reload is. The worker already skipWaiting()s and
// claim()s, so when a new version installs, controllerchange fires on every
// open window — and before 3.3 nothing listened: the page kept running the
// stale shell it booted from, silently, forever (a deep link the owner was
// sent "did nothing" because a months-old game.js was answering it). Now: if the
// player is safely on the title screen, reload straight onto the fresh cache;
// if a fight (or anything else — a live online session, the demo he is
// watching) is in progress, never yank the shell out from under it — show a
// dismissible NEW VERSION toast instead and let the player choose. Offline
// play is untouched: controllerchange only ever fires after a complete new
// shell finished installing, so the reload lands on a fully cached build even
// with no network.
// ---------------------------------------------------------------------------
const UPDATE_RELOAD_STAMP_KEY = "finalBlowUpdateReloadAt";
let updateToastDismissed = false;

function updateReloadSafe() {
  // Deliberately narrow: only the resting title screen with no online session
  // and no demo running. Everything else gets the toast.
  return state.screen === "title" && !onlineSession.role && !demoSession.active;
}

function showUpdateToast() {
  if (updateToastDismissed) return;
  $("#updateToast").hidden = false;
}

function performUpdateReload() {
  // Reload-loop guard: if this page already update-reloaded moments ago,
  // something is re-claiming in a cycle — stop reloading and fall back to the
  // visible affordance so the player is never trapped in a refresh loop.
  let lastMs = 0;
  try { lastMs = Number(sessionStorage.getItem(UPDATE_RELOAD_STAMP_KEY)) || 0; } catch { /* storage may be denied */ }
  if (Date.now() - lastMs < 15_000) {
    showUpdateToast();
    return;
  }
  try { sessionStorage.setItem(UPDATE_RELOAD_STAMP_KEY, String(Date.now())); } catch { /* storage may be denied */ }
  location.reload();
}

/**
 * Which shell is this page actually running? Read off the entry script's own
 * cache-busting stamp (game.js?v=final-blow-X) rather than a constant, so it
 * can never drift from the build that truly booted this document.
 */
function pageShellVersion() {
  const src = document.querySelector('script[src^="game.js?v="]')?.getAttribute("src") || "";
  return src.match(/final-blow-([\w.]+)$/)?.[1] || null;
}

/** Ask the (new) controlling worker which shell it caches; null on silence. */
function controllerShellVersion() {
  return new Promise((resolve) => {
    const controller = navigator.serviceWorker?.controller;
    if (!controller) {
      resolve(null);
      return;
    }
    const channel = new MessageChannel();
    const timer = setTimeout(() => resolve(null), 800);
    channel.port1.onmessage = (event) => {
      clearTimeout(timer);
      resolve(String(event.data?.version || "").match(/final-blow-shell-([\w.]+)$/)?.[1] || null);
    };
    try {
      controller.postMessage({ type: "fb-shell-version?" }, [channel.port2]);
    } catch {
      clearTimeout(timer);
      resolve(null);
    }
  });
}

if ("serviceWorker" in navigator) {
  // On a virgin first visit the initial clients.claim() flips controller from
  // null to the brand-new worker — that page IS the current build, so the
  // first controllerchange there must not reload. Any later flip means a NEW
  // worker took over, which only happens when a newer build finished caching.
  let swWasControlled = Boolean(navigator.serviceWorker.controller);
  navigator.serviceWorker.addEventListener("controllerchange", async () => {
    if (!swWasControlled) {
      swWasControlled = true;
      return;
    }
    // Registration echo, not an update: after an update-reload the fresh page
    // registers its own ?v= URL, which browsers treat as a new script and
    // install AGAIN even though the bytes are current — that takeover claims
    // this page too. If the new controller caches exactly the shell this page
    // booted from, there is nothing fresher to fetch: swallow it, or every
    // release would end on a spurious NEW VERSION toast one beat after
    // landing on the new build.
    const takeover = await controllerShellVersion();
    if (takeover !== null && takeover === pageShellVersion()) return;
    if (updateReloadSafe()) performUpdateReload();
    else showUpdateToast();
  });
}

$("#updateReloadButton").addEventListener("click", () => location.reload());
$("#updateDismissButton").addEventListener("click", (event) => {
  event.stopPropagation();
  updateToastDismissed = true;
  $("#updateToast").hidden = true;
});

window.addEventListener("beforeinstallprompt", (event) => {
  event.preventDefault();
  deferredInstallPrompt = event;
  $("#installButton").hidden = false;
});
window.addEventListener("appinstalled", () => {
  deferredInstallPrompt = null;
  $("#installButton").hidden = true;
});

// ---------------------------------------------------------------------------
// R1.9 wave 15: iOS "Add to Home Screen" coach mark. Safari on iOS never
// fires beforeinstallprompt, so the only install path is the share sheet —
// point at it once, dismissible forever, and only in real iOS Safari when
// the game is not already running standalone.
// ---------------------------------------------------------------------------
function maybeShowIosCoachMark() {
  const coach = $("#iosCoachMark");
  if (!coach) return false;
  if (!isIosDevice() || inAppBrowserName()) return false;
  if (!/Safari\//.test(navigator.userAgent || "")) return false;
  if (navigator.standalone === true) return false;
  if (window.matchMedia?.("(display-mode: standalone)").matches
    || window.matchMedia?.("(display-mode: fullscreen)").matches) return false;
  if (localStorage.getItem("final-blow-ios-coach") === "1") return false;
  coach.hidden = false;
  return true;
}

$("#iosCoachDismiss")?.addEventListener("click", () => {
  localStorage.setItem("final-blow-ios-coach", "1");
  $("#iosCoachMark").hidden = true;
});
window.addEventListener("online", updateOfflineBadge);
window.addEventListener("offline", updateOfflineBadge);

function setPaused(paused, reason = "") {
  if (state.screen !== "fight") return false;
  if (state.mode === "online" || state.mode === "demo") {
    state.paused = false;
    $("#pausePanel").hidden = true;
    return false;
  }
  state.paused = Boolean(paused);
  state.pauseReason = state.paused ? String(reason || state.pauseReason || "") : "";
  $("#pausePanel").hidden = !state.paused;
  if (!state.paused) closeMoveListOverlay();
  $("#pauseReason").hidden = !state.pauseReason;
  $("#pauseReason").textContent = state.pauseReason;
  $("#touchControls").classList.toggle("paused", state.paused);
  if (state.paused) {
    fightMusic.pause();
    // v5.3: the danger stem is a second element, so it needs the same stop.
    stopDangerStem();
    showSoundCaption("pause");
  } else {
    showSoundCaption("resume");
    syncMusic();
    canvas.focus();
  }
  // Wave 15: the wake lock releases while paused and returns on resume.
  syncWakeLock();
  return state.paused;
}

function handleControllerDisconnect(index = null, forcedSide = null) {
  if (state.screen !== "fight" || state.mode === "demo") return false;
  const side = Number.isInteger(forcedSide)
    ? forcedSide
    : assignedPadBySide.findIndex((padIndex) => padIndex === index);
  if (side < 0) return false;
  const reason = `PLAYER ${side + 1} CONTROLLER DISCONNECTED`;
  state.pauseReason = reason;
  if (state.mode === "online") {
    setOnlineLocalSuspended(true);
    return true;
  }
  setPaused(true, reason);
  return true;
}

function restartPausedRound() {
  if (state.screen !== "fight" || replayPlayback.active) return;
  setPaused(false);
  startMatch(false);
}

function titleKeyboard(event) {
  if (state.screen === "title" && (event.code === "Enter" || event.code === "Space")) startSelect("arcade");
  // R2.1 STREETS: replay theater transport keys — playback has its own pause
  // (never the pause panel, whose RESTART would corrupt the stream).
  if (replayPlayback.active && state.screen === "fight") {
    if (event.code === "Escape") {
      event.preventDefault();
      exitReplayPlayback("REPLAY CLOSED");
    } else if (event.code === "Space" || event.code === "KeyP") {
      event.preventDefault();
      toggleReplayPause();
    } else if (event.code === "ArrowRight" && replayPlayback.paused) {
      event.preventDefault();
      replayPlayback.pendingStep += 1;
    } else if (event.code === "KeyF") {
      event.preventDefault();
      cycleReplaySpeed();
    }
    return;
  }
  if (state.screen === "replays" && event.code === "Escape") {
    event.preventDefault();
    showScreen("title");
    return;
  }
  if (state.screen === "fight" && (event.code === "Escape" || event.code === "KeyP")) {
    event.preventDefault();
    // 5.1: the pause-menu move list closes first; a second press resumes.
    if (moveListOverlay.open) {
      closeMoveListOverlay();
      return;
    }
    if (controlCard.visible && !state.paused) hideControlCard();
    setPaused(!state.paused);
    return;
  }
  if (event.code === "Escape") {
    if ($("#controlsDialog").open) return;
    if (state.screen !== "title") showScreen("title");
  }
  if (state.screen === "select" && state.teamChoicePending) {
    // 5.1: the Block War opponent prompt owns the keyboard — arrows move
    // between its two buttons, Enter / any attack key confirms the focused one.
    if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.code)) {
      event.preventDefault();
      focusTeamOpponentChoice(["ArrowLeft", "ArrowUp"].includes(event.code) ? -1 : 1);
      return;
    }
    const attackKey = keyMaps.some((map) => [map.lp, map.hp, map.lk, map.hk].includes(event.code));
    if (event.code === "Enter" || event.code === "Space" || attackKey) {
      event.preventDefault();
      const focused = $$("[data-team-opponent]").includes(document.activeElement) ? document.activeElement : null;
      chooseTeamOpponent(focused?.dataset.teamOpponent || "cpu");
    }
    return;
  }
  if (state.screen === "select" && ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.code)) {
    event.preventDefault();
    const side = state.locks[0] ? 1 : 0;
    if (state.mode === "arcade" && state.locks[0]) return;
    const delta = event.code === "ArrowLeft" ? -1 : event.code === "ArrowRight" ? 1 : event.code === "ArrowUp" ? -4 : 4;
    state.picks[side] = (state.picks[side] + delta + roster.length) % roster.length;
    state.selectingPlayer = side;
    updateRosterUI();
  }
  if (state.screen === "select" && event.code === "Enter") chooseFighter(state.picks[state.selectingPlayer]);
  // Wave 16: SF2-style color select — confirming with a LIGHT button locks
  // color 1, confirming with a HEAVY button locks color 2 (either seat's
  // bindings work on the shared cursor, exactly like the ending-skip keys).
  if (state.screen === "select" && !(state.locks[0] && state.locks[1])) {
    for (const map of keyMaps) {
      if (event.code === map.lp || event.code === map.lk) {
        event.preventDefault();
        chooseFighter(state.picks[state.selectingPlayer], 0);
        return;
      }
      if (event.code === map.hp || event.code === map.hk) {
        event.preventDefault();
        chooseFighter(state.picks[state.selectingPlayer], 1);
        return;
      }
    }
  }
}

window.addEventListener("keydown", (event) => {
  // v3.2: the transport claims its keys FIRST. Everything below this
  // treats any keypress during a demo as "the viewer wants out", so without
  // this the slow-motion and frame-step keys would each quit the demo on
  // their first press. Demo/training scoped exactly like the scaler itself.
  if (handleDemoSpeedKey(event)) {
    event.preventDefault();
    return;
  }
  if (demoSession.active) {
    event.preventDefault();
    noteUserActivity();
    return;
  }
  if (pendingKeyBinding) {
    event.preventDefault();
    if (event.code === "Escape") {
      pendingKeyBinding = null;
    } else {
      keyMaps = remapKeyBinding(keyMaps, pendingKeyBinding.player, pendingKeyBinding.action, event.code);
      saveBindings();
      pendingKeyBinding = null;
    }
    renderBindings();
    return;
  }
  if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Space"].includes(event.code)) event.preventDefault();
  if (event.code === "F3") {
    event.preventDefault();
    state.debug = !state.debug;
  }
  if (!keys.has(event.code)) pressed.add(event.code);
  keys.add(event.code);
  // Release 1.8 GRIND: tally count-up and initials entry own the keyboard
  // while their screens are up. v2.1: the arcade ending sequence too.
  if (handleTallyKey(event) || handleInitialsKey(event) || handleEndingKey(event)) return;
  titleKeyboard(event);
});
window.addEventListener("keyup", (event) => keys.delete(event.code));
window.addEventListener("blur", () => { keys.clear(); pressed.clear(); });
document.addEventListener("pointerdown", () => noteUserActivity(), true);

window.addEventListener("gamepadconnected", (event) => {
  $("#padStatus").classList.add("connected");
  $("#padStatus").lastChild.textContent = ` ${event.gamepad.id.split("(")[0].trim().slice(0, 28)} READY`;
  if (state.paused && state.pauseReason.includes("CONTROLLER DISCONNECTED")) {
    state.pauseReason = "CONTROLLER RECONNECTED · RESUME WHEN READY";
    $("#pauseReason").textContent = state.pauseReason;
  }
  if (state.mode === "online" && onlineSession.localSuspended && state.pauseReason.includes("CONTROLLER")) {
    state.pauseReason = "";
    setOnlineLocalSuspended(false);
  }
  sound("select");
});
window.addEventListener("gamepaddisconnected", (event) => {
  handleControllerDisconnect(event.gamepad?.index ?? null);
  if (![...(navigator.getGamepads?.() || [])].filter(Boolean).length) {
    $("#padStatus").classList.remove("connected");
    $("#padStatus").lastChild.textContent = " KEYBOARD READY";
  }
});

// ---------------------------------------------------------------------------
// R1.9 wave 15: full gamepad menu navigation.
// menuPadLoop grows from a single confirm button into a complete navigator:
// d-pad/left stick moves a visible focus (or the roster/stage cursor on the
// screens that already have one), A confirms, B backs out, and a second pad
// drives P2's pick in the local two-player modes. Everything routes through
// handleMenuPadEvent so the QA layer can drive the exact same paths
// headlessly. Keyboard and touch handling are untouched — pad navigation
// clicks the same DOM buttons they do.
// ---------------------------------------------------------------------------
const MENU_PAD_REPEAT = Object.freeze({ initialMs: 340, repeatMs: 150 });
const menuPadSlots = [
  { direction: "", nextRepeatAt: 0, buttons: new Map() },
  { direction: "", nextRepeatAt: 0, buttons: new Map() },
];
const padNavDebug = { moves: 0, confirms: 0, backs: 0 };
let padFocusElement = null;
let menuPadAnyWasPressed = false;

function padMenuDirection(pad) {
  const axisX = pad.axes?.[0] || 0;
  const axisY = pad.axes?.[1] || 0;
  if (buttonValue(pad, 12) || axisY < -0.55) return "up";
  if (buttonValue(pad, 13) || axisY > 0.55) return "down";
  if (buttonValue(pad, 14) || axisX < -0.55) return "left";
  if (buttonValue(pad, 15) || axisX > 0.55) return "right";
  return "";
}

function menuPadDirectionEvents(pad, slot, now) {
  const direction = pad ? padMenuDirection(pad) : "";
  const events = [];
  if (direction !== slot.direction) {
    slot.direction = direction;
    if (direction) {
      events.push(direction);
      slot.nextRepeatAt = now + MENU_PAD_REPEAT.initialMs;
    }
  } else if (direction && now >= slot.nextRepeatAt) {
    events.push(direction);
    slot.nextRepeatAt = now + MENU_PAD_REPEAT.repeatMs;
  }
  return events;
}

function menuPadButtonEdge(pad, slot, index) {
  const pressed = Boolean(pad && buttonValue(pad, index));
  const was = slot.buttons.get(index) || false;
  slot.buttons.set(index, pressed);
  return pressed && !was;
}

function menuFocusRoot() {
  const dialog = $("#controlsDialog");
  if (dialog.open) return dialog;
  if (state.screen === "fight" && state.paused && moveListOverlay.open) return $("#moveListOverlay");
  if (state.screen === "fight") return state.paused ? $("#pausePanel") : null;
  return $(`#${state.screen}Screen`);
}

function menuFocusables(root) {
  if (!root) return [];
  return [...root.querySelectorAll("button, select, input:not([type=hidden])")].filter((element) => {
    if (element.disabled || element.hidden || element.closest("[hidden]")) return false;
    const rect = element.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  });
}

function setPadFocus(element) {
  if (padFocusElement === element) return;
  padFocusElement?.classList.remove("pad-focus");
  padFocusElement = element || null;
  if (padFocusElement) {
    padFocusElement.classList.add("pad-focus");
    padFocusElement.focus?.({ preventScroll: true });
    padFocusElement.scrollIntoView?.({ block: "nearest", inline: "nearest" });
    padNavDebug.moves += 1;
  }
}

function movePadFocus(delta) {
  const focusables = menuFocusables(menuFocusRoot());
  if (!focusables.length) return false;
  const index = focusables.indexOf(padFocusElement);
  if (index < 0) {
    setPadFocus(focusables.find((element) => element.classList.contains("menu-focus")) || focusables[0]);
    return true;
  }
  setPadFocus(focusables[(index + delta + focusables.length) % focusables.length]);
  return true;
}

// Left/right on a focused select or slider adjusts it instead of moving focus.
function adjustPadFocusValue(direction) {
  const element = padFocusElement;
  if (!element || !menuFocusRoot()?.contains(element)) return false;
  if (element.tagName === "SELECT") {
    const next = element.selectedIndex + (direction === "right" ? 1 : -1);
    if (next >= 0 && next < element.options.length) {
      element.selectedIndex = next;
      element.dispatchEvent(new Event("change", { bubbles: true }));
    }
    return true;
  }
  if (element.tagName === "INPUT" && element.type === "range") {
    const step = Number(element.step) || 1;
    const value = Number(element.value) + (direction === "right" ? step : -step);
    element.value = String(Math.min(Number(element.max) || 100, Math.max(Number(element.min) || 0, value)));
    element.dispatchEvent(new Event("input", { bubbles: true }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
    return true;
  }
  return false;
}

function handleSelectPadEvent(kind, padIndex) {
  if (kind === "back") {
    padNavDebug.backs += 1;
    back("title");
    return;
  }
  const twoPlayer = ["versus", "team"].includes(state.mode);
  if (padIndex === 1 && !twoPlayer) return;
  if (state.teamChoicePending) {
    // 5.1: pad on the Block War opponent prompt — left/right between the two
    // buttons, A/Y confirms the focused one. Pad 0 only (P2's pad has no say).
    if (padIndex !== 0) return;
    if (kind === "left" || kind === "right" || kind === "up" || kind === "down") {
      focusTeamOpponentChoice(kind === "left" || kind === "up" ? -1 : 1);
      padNavDebug.moves += 1;
    } else if (kind === "confirm" || kind === "altConfirm") {
      padNavDebug.confirms += 1;
      const focused = $$("[data-team-opponent]").includes(document.activeElement) ? document.activeElement : null;
      chooseTeamOpponent(focused?.dataset.teamOpponent || "cpu");
    }
    return;
  }
  // Pad 0 drives whichever side is currently picking (the keyboard-cursor
  // rule); a second pad always owns P2's pick in the two-player modes.
  const side = padIndex === 1 ? 1 : (state.locks[0] ? 1 : 0);
  if (kind === "confirm" || kind === "altConfirm") {
    padNavDebug.confirms += 1;
    if (state.locks[0] && state.locks[1]) {
      showStageSelect();
      return;
    }
    if (padIndex === 1 && !state.locks[0]) return; // P2's pad waits for P1's lock
    if (state.mode !== "team" && state.locks[side]) return;
    // Wave 16: A confirms color 1, Y confirms color 2.
    chooseFighter(state.picks[side], kind === "altConfirm" ? 1 : 0);
    return;
  }
  if (state.mode === "arcade" && state.locks[0]) return;
  if (state.mode !== "team" && state.locks[side]) return;
  const delta = kind === "left" ? -1 : kind === "right" ? 1 : kind === "up" ? -4 : 4;
  state.picks[side] = (state.picks[side] + delta + roster.length) % roster.length;
  // P2's pad may browse early, but the shared keyboard cursor only follows
  // the side whose turn it actually is.
  if (padIndex === 0 || state.locks[0]) state.selectingPlayer = side;
  updateRosterUI();
  padNavDebug.moves += 1;
}

function handleStagePadEvent(kind) {
  if (kind === "back") {
    padNavDebug.backs += 1;
    showScreen("select");
    return;
  }
  if (kind === "confirm") {
    padNavDebug.confirms += 1;
    startMatch(true);
    return;
  }
  const ids = $$("#stageGrid .stage-card").map((card) => card.dataset.stage);
  if (!ids.length) return;
  const index = Math.max(0, ids.indexOf(state.stage));
  const delta = kind === "left" ? -1 : kind === "right" ? 1 : kind === "up" ? -3 : 3;
  chooseStage(ids[(index + delta + ids.length) % ids.length]);
  padNavDebug.moves += 1;
}

function handleInitialsPadEvent(kind) {
  if (!initialsUi.active) return;
  if (kind === "up") cycleInitialLetter(1);
  else if (kind === "down") cycleInitialLetter(-1);
  else if (kind === "left") initialsUi.cursor = Math.max(0, initialsUi.cursor - 1);
  else if (kind === "right") initialsUi.cursor = Math.min(2, initialsUi.cursor + 1);
  else if (kind === "confirm") {
    padNavDebug.confirms += 1;
    commitInitials();
    return;
  } else if (kind === "back") return;
  renderInitials();
}

const PAD_BACK_TARGETS = Object.freeze({
  online: "title",
  blackbook: "title",
  records: "title",
  ending: "title",
  result: "title",
  replays: "title",
});

function handleGenericPadBack() {
  padNavDebug.backs += 1;
  if (state.screen === "ending" && endingSequence.active) {
    advanceEndingSequence();
    return;
  }
  // An online rematch screen must never be torn down by a stray B press.
  if (state.screen === "result" && state.mode === "online") return;
  const target = PAD_BACK_TARGETS[state.screen];
  if (target) showScreen(target);
}

function handleGenericPadConfirm() {
  padNavDebug.confirms += 1;
  // v2.1: pad confirm skips the current ending beat first; only the resting
  // card starts a fresh arcade run.
  if (state.screen === "ending" && endingSequence.active) {
    advanceEndingSequence();
    return;
  }
  const root = menuFocusRoot();
  if (padFocusElement && root?.contains(padFocusElement)) {
    padFocusElement.click();
    return;
  }
  // No focus engaged: the pre-wave-15 defaults.
  if (state.screen === "title") startSelect("arcade");
  else if (state.screen === "ladder") startMatch(true);
  else if (state.screen === "ending") startSelect("arcade");
  else if (state.screen === "tally") tallyContinue();
  else if (state.screen === "result") {
    if (state.mode === "online") requestOnlineRematch();
    else if (dailySession.active && dailySession.finished) showScreen("title");
    else if (state.mode === "survival" && state.survivalRun?.over) startSurvivalRun(state.survivalRun.playerId);
    else if (state.mode === "team" && state.teamBattle?.over) {
      beginTeamBattle(state.teamBattle.cpu);
      startMatch(true);
    } else startMatch(true);
  }
}

function handleMenuPadEvent(kind, padIndex = 0) {
  const dialog = $("#controlsDialog");
  if (dialog.open) {
    if (kind === "back") {
      padNavDebug.backs += 1;
      dialog.close();
      return;
    }
    if (kind === "confirm") {
      padNavDebug.confirms += 1;
      if (padFocusElement && dialog.contains(padFocusElement)) padFocusElement.click();
      return;
    }
    if ((kind === "left" || kind === "right") && adjustPadFocusValue(kind)) return;
    movePadFocus(kind === "up" || kind === "left" ? -1 : 1);
    return;
  }
  if (state.screen === "fight") {
    if (!state.paused) return; // combat owns the pad through readInput
    if (kind === "back") {
      padNavDebug.backs += 1;
      setPaused(false);
      return;
    }
    if (kind === "confirm") {
      padNavDebug.confirms += 1;
      if (padFocusElement && $("#pausePanel").contains(padFocusElement)) padFocusElement.click();
      else setPaused(false);
      return;
    }
    movePadFocus(kind === "up" || kind === "left" ? -1 : 1);
    return;
  }
  if (state.screen === "select") return handleSelectPadEvent(kind, padIndex);
  if (state.screen === "stage") return handleStagePadEvent(kind);
  if (state.screen === "initials") return handleInitialsPadEvent(kind);
  if (kind === "back") return handleGenericPadBack();
  if (kind === "confirm") return handleGenericPadConfirm();
  // The two ledger screens scroll their list with up/down.
  if ((state.screen === "blackbook" || state.screen === "records") && (kind === "up" || kind === "down")) {
    const scroller = state.screen === "blackbook" ? $("#blackBookList") : $("#recordsGrid");
    if (scroller && scroller.scrollHeight > scroller.clientHeight + 4) {
      scroller.scrollBy({ top: kind === "down" ? 150 : -150, behavior: "smooth" });
      return;
    }
  }
  movePadFocus(kind === "up" || kind === "left" ? -1 : 1);
}

// Mouse/touch use dismisses the pad focus ring until the pad speaks again.
document.addEventListener("pointerdown", () => {
  if (padFocusElement) {
    padFocusElement.classList.remove("pad-focus");
    padFocusElement = null;
  }
}, true);

function menuPadLoop() {
  const now = performance.now();
  const pads = [getPad(0), getPad(1)];
  const anyInput = pads.some((pad) => Boolean(pad && (pad.buttons.some((button) => button.pressed || button.value > 0.55)
    || pad.axes.some((axis) => Math.abs(axis) > 0.55))));
  if (demoSession.active && anyInput && !menuPadAnyWasPressed) {
    menuPadAnyWasPressed = true;
    exitDemo();
    // Wave 15 CABINET MODE: interrupting the attract loop drops straight
    // into character select — insert coin, pick your fighter.
    if (state.cabinetMode) startSelect("arcade");
    requestAnimationFrame(menuPadLoop);
    return;
  }
  if (!demoSession.active && anyInput && !menuPadAnyWasPressed) noteUserActivity();
  menuPadAnyWasPressed = anyInput;
  for (const padIndex of [0, 1]) {
    const pad = pads[padIndex];
    const slot = menuPadSlots[padIndex];
    const pause = menuPadButtonEdge(pad, slot, 9);
    if (pause && state.screen === "fight") setPaused(!state.paused);
    const confirm = menuPadButtonEdge(pad, slot, 0);
    const backEdge = menuPadButtonEdge(pad, slot, 1);
    const directions = menuPadDirectionEvents(pad, slot, now);
    if (state.screen === "fight" && !state.paused) continue; // edges consumed, combat untouched
    // Wave 15 CABINET MODE: any face-button press on the title starts a run.
    if (state.cabinetMode && state.screen === "title" && (confirm || backEdge)) {
      startSelect("arcade");
      continue;
    }
    if (confirm) handleMenuPadEvent("confirm", padIndex);
    // Wave 16: Y/triangle on the select screen is the alt-color confirm.
    const altConfirm = menuPadButtonEdge(pad, slot, 3);
    if (altConfirm && state.screen === "select") handleMenuPadEvent("altConfirm", padIndex);
    if (backEdge) handleMenuPadEvent("back", padIndex);
    for (const direction of directions) handleMenuPadEvent(direction, padIndex);
  }
  requestAnimationFrame(menuPadLoop);
}

